		/// <summary>
		/// 按数据库类型创建连接（不打开）
		/// </summary>
		private IDbConnection? CreateConnection()
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Expected O, but got Unknown
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Expected O, but got Unknown
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005b: Expected O, but got Unknown
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Expected O, but got Unknown
			return ((CoreUnify<DBOperate, DBData.Basics>)(object)this).basics.DBType switch
			{
				DBData.DBType.SqlServer => (IDbConnection?)new SqlConnection(((CoreUnify<DBOperate, DBData.Basics>)(object)this).basics.ConnectStr), 
				DBData.DBType.MySql => (IDbConnection?)new MySqlConnection(((CoreUnify<DBOperate, DBData.Basics>)(object)this).basics.ConnectStr), 
				DBData.DBType.Oracle => (IDbConnection?)new OracleConnection(((CoreUnify<DBOperate, DBData.Basics>)(object)this).basics.ConnectStr), 
				DBData.DBType.SQLite => (IDbConnection?)new SqliteConnection(((CoreUnify<DBOperate, DBData.Basics>)(object)this).basics.ConnectStr), 
				_ => null, 
			};
		}

		/// <summary>
		/// 执行数据库操作，自动管理连接生命周期（短连接，连接池复用）
		/// </summary>
		private async Task<T> WithConnectionAsync<T>(Func<IDbConnection, Task<T>> action, CancellationToken token = default(CancellationToken))
		{
			using IDbConnection conn = CreateConnection() ?? throw new InvalidOperationException("不支持的数据库类型");
			token.ThrowIfCancellationRequested();
			conn.Open();
			return await action(conn);
		}

		/// <summary>
		/// 解析数据
		/// </summary>
		/// <param name="Data"></param>
		/// <returns></returns>
		private void Analysis(ConcurrentDictionary<string, AddressValue> retData, AddressDetails addressDetails, JArray? Data = null)
		{
			object obj = ((Data != null) ? ExtendMethod.ToNJson<JArray>(Data, false) : null);
			if (VAM.IsVirtualAddress(addressDetails))
			{
				obj = VAM.Read(addressDetails);
			}
			AddressValue addressValue = AddressHandler.ExecuteDispose(addressDetails, obj, string.IsNullOrEmpty(obj?.ToString()) ? LanguageHandler.GetLanguageValue("失败", (LanguageModel)null) : LanguageHandler.GetLanguageValue("成功", (LanguageModel)null));
			retData.AddOrUpdate(addressDetails.AddressName, addressValue, (string k, AddressValue v) => addressValue);
		}

