		/// <summary>
		/// 查询数据返回datatable（Dapper 无法直接映射 DataTable，用 DataReader 手写填充）
		/// </summary>
		/// <typeparam name="T">实体类型</typeparam>
		/// <param name="sql">传入sql执行语句</param>
		/// <param name="t">实体类型</param>
		/// <returns></returns>
		public DataTable? QueryDataTable<T>(string sql, T t) where T : class
		{
			return QueryDataTableAsync(sql, t).GetAwaiter().GetResult();
		}

		/// <summary>
		/// 查询数据返回datatable（Dapper 无法直接映射 DataTable，用 DataReader 手写填充）
		/// </summary>
		/// <typeparam name="T">实体类型</typeparam>
		/// <param name="sql">传入sql执行语句</param>
		/// <param name="t">实体类型</param>
		/// <returns></returns>
		public async Task<DataTable?> QueryDataTableAsync<T>(string sql, T t) where T : class
		{
			using IDbConnection conn = CreateConnection() ?? throw new InvalidOperationException("不支持的数据库类型");
			conn.Open();
			DataTable dataTable = new DataTable();
			using IDataReader reader = await SqlMapper.ExecuteReaderAsync(conn, sql, (object)t, (IDbTransaction)null, (int?)null, (CommandType?)null);
			dataTable.Load(reader);
			return dataTable;
		}

