		/// <summary>
		/// 多语句操作（返回第一结果集）
		/// </summary>
		/// <typeparam name="T">实体类型.</typeparam>
		/// <param name="sql">传入sql执行语句.</param>
		/// <returns>第一结果集</returns>
		public async Task<List<T>> QueryMultipleAsync<T>(string sql, T t) where T : class
		{
			using IDbConnection conn = CreateConnection() ?? throw new InvalidOperationException("不支持的数据库类型");
			conn.Open();
			GridReader multiReader = await SqlMapper.QueryMultipleAsync(conn, sql, (object)t, (IDbTransaction)null, (int?)null, (CommandType?)null);
			try
			{
				return (await multiReader.ReadAsync<T>(true)).ToList();
			}
			finally
			{
				((IDisposable)multiReader)?.Dispose();
			}
		}

