namespace Snet.DB.sugar
{
	public class AdoAccessory
	{
		protected IDbBind _DbBind;

		protected IDbFirst _DbFirst;

		protected ICodeFirst _CodeFirst;

		protected IDbMaintenance _DbMaintenance;

		protected IDbConnection _DbConnection;

		protected virtual SugarParameter[] GetParameters(object parameters, PropertyInfo[] propertyInfo, string sqlParameterKeyWord)
		{
			List<SugarParameter> list = new List<SugarParameter>();
			if (parameters != null)
			{
				Type type = parameters.GetType();
				if (type.IsIn(UtilConstants.DicArraySO, UtilConstants.DicArraySS))
				{
					DictionaryToParameters(parameters, sqlParameterKeyWord, list, type);
				}
				else if (parameters is List<SugarParameter>)
				{
					list = parameters as List<SugarParameter>;
				}
				else if (parameters is SugarParameter[])
				{
					list = (parameters as SugarParameter[]).ToList();
				}
				else
				{
					Check.Exception(!type.IsAnonymousType(), "The parameter format is wrong. \nUse new{{xx=xx, xx2=xx2}}  or \nDictionary<string, object> or \nSugarParameter [] ");
					ProperyToParameter(parameters, propertyInfo, sqlParameterKeyWord, list, type);
				}
			}
			return list.ToArray();
		}

		protected void ProperyToParameter(object parameters, PropertyInfo[] propertyInfo, string sqlParameterKeyWord, List<SugarParameter> listParams, Type entityType)
		{
			PropertyInfo[] array = null;
			array = ((propertyInfo == null) ? entityType.GetProperties() : propertyInfo);
			PropertyInfo[] array2 = array;
			foreach (PropertyInfo propertyInfo2 in array2)
			{
				object obj = propertyInfo2.GetValue(parameters, null);
				if (propertyInfo2.PropertyType.IsEnum())
				{
					obj = Convert.ToInt64(obj);
				}
				if (obj == null || obj.Equals(DateTime.MinValue))
				{
					obj = DBNull.Value;
				}
				if (propertyInfo2.Name.ToLower().Contains("hierarchyid"))
				{
					SugarParameter sugarParameter = new SugarParameter(sqlParameterKeyWord + propertyInfo2.Name, SqlDbType.Udt);
					sugarParameter.UdtTypeName = "HIERARCHYID";
					sugarParameter.Value = obj;
					listParams.Add(sugarParameter);
				}
				else
				{
					SugarParameter item = new SugarParameter(sqlParameterKeyWord + propertyInfo2.Name, obj);
					listParams.Add(item);
				}
			}
		}

		protected void DictionaryToParameters(object parameters, string sqlParameterKeyWord, List<SugarParameter> listParams, Type entityType)
		{
			if (entityType == UtilConstants.DicArraySO)
			{
				IEnumerable<SugarParameter> collection = ((Dictionary<string, object>)parameters).Select((KeyValuePair<string, object> it) => new SugarParameter(sqlParameterKeyWord + it.Key, it.Value));
				listParams.AddRange(collection);
			}
			else
			{
				IEnumerable<SugarParameter> collection2 = ((Dictionary<string, string>)parameters).Select((KeyValuePair<string, string> it) => new SugarParameter(sqlParameterKeyWord + it.Key, it.Value));
				listParams.AddRange(collection2);
			}
		}
	}
	/// <summary>
	///  ** description：ActiveX Data Objects
	///  ** author：sunkaixuan
	///  ** date：2017/1/2
	///  ** email:610262374@qq.com
	///  </summary>
	public abstract class AdoProvider : AdoAccessory, IAdo
	{
		internal DateTime BeforeTime = DateTime.MinValue;

		internal DateTime AfterTime = DateTime.MinValue;

		internal DateTime GetDataBeforeTime = DateTime.MinValue;

		internal DateTime GetDataAfterTime = DateTime.MinValue;

		internal DateTime CheckConnectionBeforeTime = DateTime.MinValue;

		internal DateTime CheckConnectionAfterTime = DateTime.MinValue;

		public virtual bool IsNoSql { get; set; }

		internal bool IsOpenAsync { get; set; }

		protected List<IDataParameter> OutputParameters { get; set; }

		public virtual string SqlParameterKeyWord => "@";

		public IDbTransaction Transaction { get; set; }

		public virtual SqlSugarProvider Context { get; set; }

		internal CommandType OldCommandType { get; set; }

		internal bool OldClearParameters { get; set; }

		public IDataParameterCollection DataReaderParameters { get; set; }

		public TimeSpan SqlExecutionTime => AfterTime - BeforeTime;

		public TimeSpan ConnectionExecutionTime => CheckConnectionAfterTime - CheckConnectionBeforeTime;

		public TimeSpan GetDataExecutionTime => GetDataAfterTime - GetDataBeforeTime;

		/// <summary>
		/// Add, delete and modify: the number of affected items;
		/// </summary>
		public int SqlExecuteCount { get; protected set; }

		public SugarActionType SqlExecuteType => Context.SugarActionType;

		public StackTraceInfo SqlStackTrace => UtilMethods.GetStackTrace();

		public bool IsDisableMasterSlaveSeparation { get; set; }

		public virtual IDbBind DbBind
		{
			get
			{
				if (_DbBind == null)
				{
					(_DbBind = InstanceFactory.GetDbBind(Context.CurrentConnectionConfig)).Context = Context;
				}
				return _DbBind;
			}
		}

		public virtual int CommandTimeOut { get; set; }

		public virtual CommandType CommandType { get; set; }

		public virtual bool IsEnableLogEvent { get; set; }

		public virtual bool IsClearParameters { get; set; }

		public virtual Action<string, SugarParameter[]> LogEventStarting => Context.CurrentConnectionConfig.AopEvents?.OnLogExecuting;

		public virtual Action<string, SugarParameter[]> LogEventCompleted => Context.CurrentConnectionConfig.AopEvents?.OnLogExecuted;

		public virtual Action<IDbConnection> CheckConnectionExecuting => Context.CurrentConnectionConfig.AopEvents?.CheckConnectionExecuting;

		public virtual Action<IDbConnection, TimeSpan> CheckConnectionExecuted => Context.CurrentConnectionConfig.AopEvents?.CheckConnectionExecuted;

		public virtual Action<string, SugarParameter[]> OnGetDataReadering => Context.CurrentConnectionConfig.AopEvents?.OnGetDataReadering;

		public virtual Action<string, SugarParameter[], TimeSpan> OnGetDataReadered => Context.CurrentConnectionConfig.AopEvents?.OnGetDataReadered;

		public virtual Func<string, SugarParameter[], KeyValuePair<string, SugarParameter[]>> ProcessingEventStartingSQL => Context.CurrentConnectionConfig.AopEvents?.OnExecutingChangeSql;

		protected virtual Func<string, string> FormatSql { get; set; }

		public virtual Action<SqlSugarException> ErrorEvent => Context.CurrentConnectionConfig.AopEvents?.OnError;

		public virtual Action<DiffLogModel> DiffLogEvent => Context.CurrentConnectionConfig.AopEvents?.OnDiffLogEvent;

		public virtual List<IDbConnection> SlaveConnections { get; set; }

		public virtual IDbConnection MasterConnection { get; set; }

		public virtual string MasterConnectionString { get; set; }

		public virtual CancellationToken? CancellationToken { get; set; }

		public abstract IDbConnection Connection { get; set; }

		protected bool IsMasterSlaveSeparation
		{
			get
			{
				if (Context.CurrentConnectionConfig.SlaveConnectionConfigs.HasValue())
				{
					return !IsDisableMasterSlaveSeparation;
				}
				return false;
			}
		}

		public AdoProvider()
		{
			IsEnableLogEvent = false;
			CommandType = CommandType.Text;
			IsClearParameters = true;
			CommandTimeOut = 300;
		}

		public virtual bool IsValidConnection()
		{
			try
			{
				if (IsAnyTran())
				{
					return true;
				}
				using (OpenAlways())
				{
					return true;
				}
			}
			catch (Exception)
			{
				return false;
			}
		}

		public virtual bool IsValidConnectionNoClose()
		{
			try
			{
				Open();
				return true;
			}
			catch (Exception)
			{
				return false;
			}
		}

		public virtual void Open()
		{
			CheckConnection();
		}

		public virtual async Task OpenAsync()
		{
			await CheckConnectionAsync();
		}

		public SugarConnection OpenAlways()
		{
			SugarConnection result = new SugarConnection
			{
				IsAutoClose = Context.CurrentConnectionConfig.IsAutoCloseConnection,
				conn = Connection,
				Context = Context
			};
			Context.CurrentConnectionConfig.IsAutoCloseConnection = false;
			Open();
			return result;
		}

		public virtual void Close()
		{
			if (Transaction != null)
			{
				Transaction = null;
			}
			if (Connection != null && Connection.State == ConnectionState.Open)
			{
				Connection.Close();
			}
			if (!IsMasterSlaveSeparation || !SlaveConnections.HasValue())
			{
				return;
			}
			foreach (IDbConnection slaveConnection in SlaveConnections)
			{
				if (slaveConnection != null && slaveConnection.State == ConnectionState.Open)
				{
					slaveConnection.Close();
				}
			}
		}

		public virtual void Dispose()
		{
			if (Transaction != null)
			{
				Transaction.Rollback();
				Transaction = null;
			}
			if (Connection != null)
			{
				Connection.Dispose();
			}
			Connection = null;
			if (!IsMasterSlaveSeparation || SlaveConnections == null)
			{
				return;
			}
			foreach (IDbConnection slaveConnection in SlaveConnections)
			{
				if (slaveConnection != null && slaveConnection.State == ConnectionState.Open)
				{
					slaveConnection.Dispose();
				}
			}
		}

		public virtual void CheckConnection()
		{
			CheckConnectionBefore(Connection);
			if (Connection.State != ConnectionState.Open)
			{
				try
				{
					Connection.Open();
				}
				catch (Exception ex)
				{
					ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.DbType == DbType.SqlServer)
					{
						string message = ex.Message;
						if (message != null && message.Contains("provider: SSL"))
						{
							Check.ExceptionEasy(isException: true, ex.Message, "SSL出错，因为升级了驱动,字符串增加Encrypt=True;TrustServerCertificate=True;即可。详细错误：" + ex.Message);
						}
					}
					Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message + $"DbType=\"{Context.CurrentConnectionConfig.DbType}\";ConfigId=\"{Context.CurrentConnectionConfig.ConfigId}\"");
				}
			}
			CheckConnectionAfter(Connection);
		}

		public virtual async Task CheckConnectionAsync()
		{
			CheckConnectionBefore(Connection);
			if (Connection.State != ConnectionState.Open)
			{
				try
				{
					await (Connection as DbConnection).OpenAsync();
				}
				catch (Exception ex)
				{
					Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message + $"DbType=\"{Context.CurrentConnectionConfig.DbType}\";ConfigId=\"{Context.CurrentConnectionConfig.ConfigId}\"");
				}
			}
			CheckConnectionAfter(Connection);
		}

		public virtual void CheckConnectionBefore(IDbConnection Connection)
		{
			CheckConnectionBeforeTime = DateTime.Now;
			if (IsEnableLogEvent)
			{
				CheckConnectionExecuting?.Invoke(Connection);
			}
		}

		public virtual void CheckConnectionAfter(IDbConnection Connection)
		{
			CheckConnectionAfterTime = DateTime.Now;
			if (IsEnableLogEvent)
			{
				CheckConnectionExecuted?.Invoke(Connection, ConnectionExecutionTime);
			}
		}

		public virtual bool IsAnyTran()
		{
			return Transaction != null;
		}

		public virtual bool IsNoTran()
		{
			return Transaction == null;
		}

		public virtual void BeginTran()
		{
			CheckConnection();
			if (Transaction == null)
			{
				Transaction = Connection.BeginTransaction();
			}
		}

		public virtual async Task BeginTranAsync()
		{
			await CheckConnectionAsync();
			if (Transaction == null)
			{
				Transaction = await (Connection as DbConnection).BeginTransactionAsync();
			}
		}

		public virtual void BeginTran(IsolationLevel iso)
		{
			CheckConnection();
			if (Transaction == null)
			{
				Transaction = Connection.BeginTransaction(iso);
			}
		}

		public virtual async Task BeginTranAsync(IsolationLevel iso)
		{
			await CheckConnectionAsync();
			if (Transaction == null)
			{
				Transaction = await (Connection as DbConnection).BeginTransactionAsync(iso);
			}
		}

		public virtual void RollbackTran()
		{
			if (Transaction != null)
			{
				Transaction.Rollback();
				Transaction = null;
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
				{
					Close();
				}
			}
		}

		public virtual async Task RollbackTranAsync()
		{
			if (Transaction != null)
			{
				await (Transaction as DbTransaction).RollbackAsync();
				Transaction = null;
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
				{
					await CloseAsync();
				}
			}
		}

		public virtual void CommitTran()
		{
			if (Transaction != null)
			{
				Transaction.Commit();
				Transaction = null;
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
				{
					Close();
				}
			}
		}

		public virtual async Task CommitTranAsync()
		{
			if (Transaction != null)
			{
				await (Transaction as DbTransaction).CommitAsync();
				Transaction = null;
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
				{
					await CloseAsync();
				}
			}
		}

