		public DbResult<bool> UseTran(Action action, Action<Exception> errorCallBack = null)
		{
			DbResult<bool> dbResult = new DbResult<bool>();
			try
			{
				BeginTran();
				action?.Invoke();
				CommitTran();
				bool data = (dbResult.IsSuccess = true);
				dbResult.Data = data;
			}
			catch (Exception ex)
			{
				Exception ex2 = (dbResult.ErrorException = ex);
				dbResult.ErrorMessage = ex2.Message;
				dbResult.IsSuccess = false;
				RollbackTran();
				errorCallBack?.Invoke(ex2);
			}
			return dbResult;
		}

		public async Task<DbResult<bool>> UseTranAsync(Func<Task> action, Action<Exception> errorCallBack = null)
		{
			DbResult<bool> result = new DbResult<bool>();
			try
			{
				await BeginTranAsync();
				if (action != null)
				{
					await action();
				}
				await CommitTranAsync();
				bool data = (result.IsSuccess = true);
				result.Data = data;
			}
			catch (Exception ex)
			{
				Exception ex2 = (result.ErrorException = ex);
				result.ErrorMessage = ex2.Message;
				result.IsSuccess = false;
				await RollbackTranAsync();
				errorCallBack?.Invoke(ex2);
			}
			return result;
		}

		public DbResult<T> UseTran<T>(Func<T> action, Action<Exception> errorCallBack = null)
		{
			DbResult<T> dbResult = new DbResult<T>();
			try
			{
				BeginTran();
				if (action != null)
				{
					dbResult.Data = action();
				}
				CommitTran();
				dbResult.IsSuccess = true;
			}
			catch (Exception ex)
			{
