			catch (Exception ex)
			{
				Exception ex2 = (result.ErrorException = ex);
				result.ErrorMessage = ex2.Message;
				result.IsSuccess = false;
				RollbackTran();
				errorCallBack?.Invoke(ex2);
			}
			return result;
		}

