		public virtual int ExecuteCommandWithGo(string sql, params SugarParameter[] parameters)
		{
			if (string.IsNullOrEmpty(sql))
			{
				return 0;
			}
			if (!sql.ToLower().Contains("go"))
			{
				return ExecuteCommand(sql);
			}
			ArrayList arrayList = new ArrayList();
			Regex regex = new Regex("^(\\s*)go(\\s*)$", RegexOptions.IgnoreCase | RegexOptions.Multiline | RegexOptions.ExplicitCapture | RegexOptions.Compiled);
			arrayList.AddRange(regex.Split(sql));
			int num = 0;
			foreach (string item in arrayList)
			{
				if (item.HasValue())
				{
					num += ExecuteCommand(item, parameters);
				}
			}
			return num;
		}

		public virtual int ExecuteCommand(string sql, params SugarParameter[] parameters)
		{
			try
			{
				InitParameters(ref sql, parameters);
				if (IsFormat(parameters))
				{
					sql = FormatSql(sql);
				}
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.SqlMiddle?.IsSqlMiddle == true)
				{
					return Context.CurrentConnectionConfig.SqlMiddle.ExecuteCommand(sql, parameters);
				}
				SetConnectionStart(sql);
				if (ProcessingEventStartingSQL != null)
				{
					ExecuteProcessingSQL(ref sql, ref parameters);
				}
				ExecuteBefore(sql, parameters);
				using IDbCommand dbCommand = GetCommand(sql, parameters);
				int num = dbCommand.ExecuteNonQuery();
				if (IsClearParameters)
				{
					dbCommand.Parameters.Clear();
				}
				SqlExecuteCount = num;
				ExecuteAfter(sql, parameters);
				return num;
			}
			catch (Exception ex)
			{
				SugarCatch(ex, sql, parameters);
				CommandType = CommandType.Text;
				if (ErrorEvent != null)
				{
					ExecuteErrorEvent(sql, parameters, ex);
				}
				throw ex;
			}
			finally
			{
				if (IsAutoClose())
				{
					Close();
				}
				SetConnectionEnd(sql);
			}
		}

