				ExecuteBefore(sql, parameters);
				IDbCommand command = GetCommand(sql, parameters);
				IDataReader result = command.ExecuteReader(IsAutoClose() ? CommandBehavior.CloseConnection : CommandBehavior.Default);
				if (num)
				{
					DataReaderParameters = command.Parameters;
