		public virtual void ExecuteBefore(string sql, SugarParameter[] parameters)
		{
			BeforeTime = DateTime.Now;
			if (!IsEnableLogEvent)
			{
				return;
			}
			Action<string, SugarParameter[]> logEventStarting = LogEventStarting;
			if (logEventStarting != null)
			{
				if (parameters == null || parameters.Length == 0)
				{
					logEventStarting(sql, new SugarParameter[0]);
				}
				else
				{
					logEventStarting(sql, parameters);
				}
			}
		}

		public virtual void ExecuteAfter(string sql, SugarParameter[] parameters)
		{
			AfterTime = DateTime.Now;
			if (parameters.HasValue())
			{
				foreach (SugarParameter outputParameter in parameters.Where((SugarParameter it) => it.Direction.IsIn(ParameterDirection.Output, ParameterDirection.InputOutput, ParameterDirection.ReturnValue)))
				{
					IDataParameter dataParameter = OutputParameters.FirstOrDefault((IDataParameter it) => it.ParameterName == outputParameter.ParameterName);
					if (dataParameter == null)
					{
						dataParameter = OutputParameters.FirstOrDefault((IDataParameter it) => it.ParameterName == outputParameter.ParameterName.TrimStart(outputParameter.ParameterName.First()));
					}
					if (dataParameter == null)
					{
						dataParameter = OutputParameters.FirstOrDefault((IDataParameter it) => it.ParameterName == ":" + outputParameter.ParameterName.TrimStart(outputParameter.ParameterName.First()));
					}
					outputParameter.Value = dataParameter.Value;
					OutputParameters.Remove(dataParameter);
				}
			}
			if (IsEnableLogEvent)
			{
				Action<string, SugarParameter[]> logEventCompleted = LogEventCompleted;
				if (logEventCompleted != null)
				{
					if (parameters == null || parameters.Length == 0)
					{
						logEventCompleted(sql, new SugarParameter[0]);
					}
					else
					{
						logEventCompleted(sql, parameters);
					}
				}
			}
			if (OldCommandType != 0)
			{
				CommandType = OldCommandType;
				IsClearParameters = OldClearParameters;
				OldCommandType = (CommandType)0;
				OldClearParameters = false;
			}
		}

