		protected bool IsAutoClose()
		{
			if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
			{
				return Transaction == null;
			}
			return false;
		}

		protected void SetConnectionStart(string sql)
		{
			if (Transaction == null && IsMasterSlaveSeparation && IsRead(sql))
			{
				if (MasterConnection == null)
				{
					MasterConnection = Connection;
					MasterConnectionString = MasterConnection.ConnectionString;
				}
				List<SlaveConnectionConfig> saves = Context.CurrentConnectionConfig.SlaveConnectionConfigs.Where((SlaveConnectionConfig it) => it.HitRate > 0).ToList();
				int randomIndex = UtilRandom.GetRandomIndex(saves.ToDictionary((SlaveConnectionConfig it) => saves.ToList().IndexOf(it), (SlaveConnectionConfig it) => it.HitRate));
				SlaveConnectionConfig slaveConnectionConfig = saves[randomIndex];
				Connection = null;
				Context.CurrentConnectionConfig.ConnectionString = slaveConnectionConfig.ConnectionString;
				Connection = Connection;
				if (SlaveConnections.IsNullOrEmpty() || !SlaveConnections.Any((IDbConnection it) => EqualsConnectionString(it.ConnectionString, Connection.ConnectionString)))
				{
					if (SlaveConnections == null)
					{
						SlaveConnections = new List<IDbConnection>();
					}
					SlaveConnections.Add(Connection);
				}
			}
			else if (Transaction == null && IsMasterSlaveSeparation && MasterConnection == null)
			{
				MasterConnection = Connection;
				MasterConnectionString = MasterConnection.ConnectionString;
			}
		}

		private bool EqualsConnectionString(string connectionString1, string connectionString2)
		{
			string[] first = connectionString1.Split(';');
			string[] second = connectionString2.Split(';');
			return first.Except(second).Count() == 0;
		}

		private bool IsFormat(SugarParameter[] parameters)
		{
			if (FormatSql != null && parameters != null)
			{
				return parameters.Length != 0;
			}
			return false;
		}

		protected void SetConnectionEnd(string sql)
		{
			if (IsMasterSlaveSeparation && IsRead(sql) && Transaction == null)
			{
				Connection = MasterConnection;
				Context.CurrentConnectionConfig.ConnectionString = MasterConnectionString;
			}
			Context.SugarActionType = SugarActionType.UnKnown;
		}

		private bool IsRead(string sql)
		{
			string input = sql.ToLower();
			if (Regex.IsMatch(input, "[ ]*select[ ]"))
			{
				return !Regex.IsMatch(input, "[ ]*insert[ ]|[ ]*update[ ]|[ ]*delete[ ]");
			}
			return false;
		}

		protected void ExecuteErrorEvent(string sql, SugarParameter[] parameters, Exception ex)
		{
			AfterTime = DateTime.Now;
			ErrorEvent(new SqlSugarException(Context, ex, sql, parameters));
		}

		protected void InitParameters(ref string sql, SugarParameter[] parameters)
		{
			SqlExecuteCount = 0;
			BeforeTime = DateTime.MinValue;
			AfterTime = DateTime.MinValue;
			if (!parameters.HasValue())
			{
				return;
			}
			foreach (SugarParameter sugarParameter in parameters)
			{
				if (sugarParameter.Value != null)
				{
					Type type = sugarParameter.Value.GetType();
					if ((type != UtilConstants.ByteArrayType && type.IsArray && !sugarParameter.IsArray) || type.FullName.IsCollectionsList() || type.IsIterator())
					{
						List<string> list = new List<string>();
						foreach (object item in sugarParameter.Value as IEnumerable)
						{
							list.Add(item.ObjToString());
						}
						if (list.IsNullOrEmpty())
						{
							list.Add("-1");
						}
						if (sugarParameter.ParameterName.Substring(0, 1) == ":")
						{
							sql = sql.Replace("@" + sugarParameter.ParameterName.Substring(1), list.ToArray().ToJoinSqlInVals());
						}
						if (sugarParameter.ParameterName.Substring(0, 1) != SqlParameterKeyWord && sql.ObjToString().Contains(SqlParameterKeyWord + sugarParameter.ParameterName))
						{
							sql = sql.Replace(SqlParameterKeyWord + sugarParameter.ParameterName, list.ToArray().ToJoinSqlInVals());
						}
						else if (sugarParameter.Value != null && UtilMethods.IsNumberArray(sugarParameter.Value.GetType()))
						{
							if (list.Any((string it) => it == ""))
							{
								list.RemoveAll((string r) => r == "");
								list.Add("null");
							}
							sql = sql.Replace(sugarParameter.ParameterName, string.Join(",", list));
						}
						else
						{
							sql = sql.Replace(sugarParameter.ParameterName, list.ToArray().ToJoinSqlInVals());
						}
						sugarParameter.Value = DBNull.Value;
					}
				}
				if (sugarParameter.ParameterName != null && sugarParameter.ParameterName.Contains(" "))
				{
					string parameterName = sugarParameter.ParameterName;
					sugarParameter.ParameterName = sugarParameter.ParameterName.Replace(" ", "");
					sql = sql.Replace(parameterName, sugarParameter.ParameterName);
				}
			}
		}

		protected List<TResult> GetData<TResult>(Type entityType, IDataReader dataReader)
		{
			if (entityType == UtilConstants.DynamicType)
			{
				return Context.Utilities.DataReaderToExpandoObjectListNoUsing(dataReader) as List<TResult>;
			}
			if (entityType == UtilConstants.ObjType)
			{
				return (from it in Context.Utilities.DataReaderToExpandoObjectListNoUsing(dataReader)
					select (TResult)(object)it).ToList();
			}
			if (entityType.IsAnonymousType() || StaticConfig.EnableAot)
			{
				if (StaticConfig.EnableAot && entityType == UtilConstants.StringType)
				{
					return Context.Ado.DbBind.DataReaderToListNoUsing<TResult>(entityType, dataReader);
				}
				return Context.Utilities.DataReaderToListNoUsing<TResult>(dataReader);
			}
			return Context.Ado.DbBind.DataReaderToListNoUsing<TResult>(entityType, dataReader);
		}

		protected async Task<List<TResult>> GetDataAsync<TResult>(Type entityType, IDataReader dataReader)
		{
			return (entityType == UtilConstants.DynamicType) ? ((await Context.Utilities.DataReaderToExpandoObjectListAsyncNoUsing(dataReader)) as List<TResult>) : ((entityType == UtilConstants.ObjType) ? (await Context.Utilities.DataReaderToExpandoObjectListAsyncNoUsing(dataReader)).Select((ExpandoObject it) => (TResult)(object)it).ToList() : ((!entityType.IsAnonymousType() && !StaticConfig.EnableAot) ? (await Context.Ado.DbBind.DataReaderToListNoUsingAsync<TResult>(entityType, dataReader)) : ((!StaticConfig.EnableAot || !(entityType == UtilConstants.StringType)) ? (await Context.Utilities.DataReaderToListAsyncNoUsing<TResult>(dataReader)) : (await Context.Ado.DbBind.DataReaderToListNoUsingAsync<TResult>(entityType, dataReader)))));
		}
	}
