	public class CodeFirstProvider : ICodeFirst
	{
		internal static object LockObject = new object();

		protected Dictionary<Type, string> MappingTables = new Dictionary<Type, string>();

		public virtual SqlSugarProvider Context { get; set; }

		protected bool IsBackupTable { get; set; }

		protected int MaxBackupDataRows { get; set; }

		protected virtual int DefultLength { get; set; }

		public CodeFirstProvider()
		{
			if (DefultLength == 0)
			{
				DefultLength = 255;
			}
		}

		public SplitCodeFirstProvider SplitTables()
		{
			return new SplitCodeFirstProvider
			{
				Context = Context,
				DefaultLength = DefultLength
			};
		}

		public virtual ICodeFirst BackupTable(int maxBackupDataRows = int.MaxValue)
		{
			IsBackupTable = true;
			MaxBackupDataRows = maxBackupDataRows;
			return this;
		}

		public virtual ICodeFirst SetStringDefaultLength(int length)
		{
			DefultLength = length;
			return this;
		}

		public void InitTablesWithAttr(params Type[] entityTypes)
		{
			foreach (Type type in entityTypes)
			{
				if (type.GetCustomAttribute<TenantAttribute>() == null || Context?.Root == null)
				{
					Context.CodeFirst.InitTables(type);
				}
				else
				{
					Context.Root.GetConnectionWithAttr(type).CodeFirst.InitTables(type);
				}
			}
		}

		public virtual void InitTables(Type entityType)
		{
			List<SlaveConnectionConfig> slaveConnectionConfigs = Context.CurrentConnectionConfig.SlaveConnectionConfigs;
			Context.CurrentConnectionConfig.SlaveConnectionConfigs = null;
			if (entityType.GetCustomAttribute<SplitTableAttribute>() != null && Context.MappingTables.FirstOrDefault((MappingTable it) => it.EntityName == entityType.Name) == null)
			{
				UtilMethods.StartCustomSplitTable(Context, entityType);
				Context.CodeFirst.SplitTables().InitTables(entityType);
				Context.MappingTables.RemoveAll((MappingTable it) => it.EntityName == entityType.Name);
				UtilMethods.EndCustomSplitTable(Context, entityType);
				return;
			}
			lock (LockObject)
			{
				MappingTableList oldTableList = CopyMappingTalbe();
				EntityInfo entityInfo = Context.GetEntityNoCacheInitMappingInfo(entityType);
				if (!Context.DbMaintenance.IsAnySystemTablePermissions())
				{
					Check.Exception(true, "Dbfirst and  Codefirst requires system table permissions");
				}
				Check.Exception(Context.IsSystemTablesConfig, "Please set SqlSugarClent Parameter ConnectionConfig.InitKeyType=InitKeyType.Attribute ");
				if (Context.Ado.Transaction == null)
				{
					DbResult<bool> dbResult = Context.Ado.UseTran(delegate
					{
						Execute(entityType, entityInfo);
					});
					Check.Exception(!dbResult.IsSuccess, dbResult.ErrorMessage);
				}
				else
				{
					Execute(entityType, entityInfo);
				}
				RestMappingTables(oldTableList);
			}
			Context.CurrentConnectionConfig.SlaveConnectionConfigs = slaveConnectionConfigs;
		}

		public void InitTables<T>()
		{
			InitTables(typeof(T));
		}

		public void InitTables<T, T2>()
		{
			InitTables(typeof(T), typeof(T2));
		}

		public void InitTables<T, T2, T3>()
		{
			InitTables(typeof(T), typeof(T2), typeof(T3));
		}

		public void InitTables<T, T2, T3, T4>()
		{
			InitTables(typeof(T), typeof(T2), typeof(T3), typeof(T4));
		}

		public void InitTables<T, T2, T3, T4, T5>()
		{
			InitTables(typeof(T), typeof(T2), typeof(T3), typeof(T4), typeof(T5));
		}

		public virtual void InitTables(params Type[] entityTypes)
		{
			if (!entityTypes.HasValue())
			{
				return;
			}
			foreach (Type type in entityTypes)
			{
				try
				{
					InitTables(type);
				}
				catch (Exception ex)
				{
					throw new Exception(type.Name + " 创建失败,请认真检查 1、属性需要get set 2、特殊类型需要加Ignore 具体错误内容： " + ex.Message);
				}
			}
		}

		public ICodeFirst As(Type type, string newTableName)
		{
			if (!MappingTables.ContainsKey(type))
			{
				MappingTables.Add(type, newTableName);
			}
			else
			{
				MappingTables[type] = newTableName;
			}
			return this;
		}

		public ICodeFirst As<T>(string newTableName)
		{
			return As(typeof(T), newTableName);
		}

		public virtual void InitTables(string entitiesNamespace)
		{
			Type[] types = Assembly.Load(entitiesNamespace).GetTypes();
			InitTables(types);
		}

		public virtual void InitTables(params string[] entitiesNamespaces)
		{
			if (entitiesNamespaces.HasValue())
			{
				foreach (string entitiesNamespace in entitiesNamespaces)
				{
					InitTables(entitiesNamespace);
				}
			}
		}

		public TableDifferenceProvider GetDifferenceTables<T>()
		{
			Type typeFromHandle = typeof(T);
			return GetDifferenceTables(typeFromHandle);
		}

		public TableDifferenceProvider GetDifferenceTables(params Type[] types)
		{
			TableDifferenceProvider result = new TableDifferenceProvider();
			foreach (Type type in types)
			{
				try
				{
					GetDifferenceTables(result, type);
				}
				catch (Exception ex)
				{
					Check.ExceptionEasy("实体" + type.Name + " 出错,具体错误:" + ex.Message, " " + type.Name + " error." + ex.Message);
				}
			}
			return result;
		}

		private void GetDifferenceTables(TableDifferenceProvider result, Type type)
		{
			bool flag = false;
			string text = "TempDiff" + DateTime.Now.ToString("yyMMssHHmmssfff");
			string oldTableName = Context.EntityMaintenance.GetEntityInfo(type).DbTableName;
			SqlSugarProvider sqlSugarProvider = new SqlSugarProvider(UtilMethods.CopyConfig(Context.CurrentConnectionConfig));
			sqlSugarProvider.CurrentConnectionConfig.SlaveConnectionConfigs = null;
			sqlSugarProvider.CurrentConnectionConfig.ConfigureExternalServices = UtilMethods.IsNullReturnNew(sqlSugarProvider.CurrentConnectionConfig.ConfigureExternalServices);
			ConfigureExternalServices configureExternalServices = sqlSugarProvider.CurrentConnectionConfig.ConfigureExternalServices;
			configureExternalServices.EntityNameService = (Action<Type, EntityInfo>)Delegate.Combine(configureExternalServices.EntityNameService, (Action<Type, EntityInfo>)delegate(Type x, EntityInfo p)
			{
				p.IsDisabledUpdateAll = true;
			});
			sqlSugarProvider.MappingTables = new MappingTableList();
			sqlSugarProvider.MappingTables.Add(type.Name, text);
			try
			{
				ICodeFirst codeFirst = sqlSugarProvider.CodeFirst;
				codeFirst.SetStringDefaultLength(DefultLength);
				codeFirst.InitTables(type);
				flag = true;
				List<DbTableInfo> tableInfoList = sqlSugarProvider.DbMaintenance.GetTableInfoList(isCache: false);
				DbTableInfo dbTableInfo = tableInfoList.FirstOrDefault((DbTableInfo it) => it.Name.EqualCase(oldTableName));
				DbTableInfo newTableInfo = tableInfoList.FirstOrDefault((DbTableInfo it) => it.Name.EqualCase(oldTableName));
				List<DbColumnInfo> columnInfosByTableName = sqlSugarProvider.DbMaintenance.GetColumnInfosByTableName(oldTableName, isCache: false);
				List<DbColumnInfo> columnInfosByTableName2 = sqlSugarProvider.DbMaintenance.GetColumnInfosByTableName(text, isCache: false);
				if (dbTableInfo == null)
				{
					dbTableInfo = new DbTableInfo
					{
						Name = "还未创建:" + oldTableName
					};
					newTableInfo = new DbTableInfo
					{
						Name = "还未创建:" + oldTableName
					};
				}
				result.tableInfos.Add(new DiffTableInfo
				{
					OldTableInfo = dbTableInfo,
					NewTableInfo = newTableInfo,
					OldColumnInfos = columnInfosByTableName,
					NewColumnInfos = columnInfosByTableName2
				});
			}
			catch (Exception ex)
			{
				throw ex;
			}
			finally
			{
				if (flag)
				{
					sqlSugarProvider.DbMaintenance.DropTable(text);
				}
			}
		}

		protected virtual void Execute(Type entityType, EntityInfo entityInfo)
		{
			if (entityInfo.Discrimator.HasValue())
			{
				Check.ExceptionEasy(!Regex.IsMatch(entityInfo.Discrimator, "^(?:\\w+:\\w+)(?:,\\w+:\\w+)*$"), "The format should be type:cat for this type, and if there are multiple, it can be FieldName:cat,FieldName2:dog ", "格式错误应该是type:cat这种格式，如果是多个可以FieldName:cat,FieldName2:dog，不要有空格");
				string[] array = entityInfo.Discrimator.Split(',');
				foreach (string obj in array)
				{
					string text = obj.Split(':').First();
					obj.Split(':').Last();
					entityInfo.Columns.Add(new EntityColumnInfo
					{
						PropertyInfo = typeof(DiscriminatorObject).GetProperty("FieldName"),
						IsOnlyIgnoreUpdate = true,
						DbColumnName = text,
						UnderType = typeof(string),
						PropertyName = text,
						Length = 50
					});
				}
			}
			if (MappingTables.ContainsKey(entityType))
			{
				entityInfo.DbTableName = MappingTables[entityType];
				Context.MappingTables.Add(entityInfo.EntityName, entityInfo.DbTableName);
			}
			if (DefultLength > 0)
			{
				foreach (EntityColumnInfo column in entityInfo.Columns)
				{
					if (column.PropertyInfo.PropertyType == UtilConstants.StringType && column.DataType.IsNullOrEmpty() && column.Length == 0)
					{
						column.Length = DefultLength;
					}
					if (column.DataType != null && column.DataType.Contains(",") && !Regex.IsMatch(column.DataType, "\\d\\,\\d"))
					{
						List<string> source = (from it in column.DataType.Split(',')
							select it.ToLower()).ToList();
						List<string> mapingTypes = Context.Ado.DbBind.MappingTypes.Select<KeyValuePair<string, CSharpDataType>, string>((KeyValuePair<string, CSharpDataType> it) => it.Key.ToLower()).ToList();
						string text2 = source.FirstOrDefault((string it) => mapingTypes.Contains(it));
						if (text2 != null)
						{
							column.DataType = text2;
						}
						if (column.DataType == "varcharmax")
						{
							column.DataType = "nvarchar(max)";
						}
					}
				}
			}
			string tableName = GetTableName(entityInfo);
			Context.MappingTables.Add(entityInfo.EntityName, tableName);
			entityInfo.DbTableName = tableName;
			entityInfo.Columns.ForEach(delegate(EntityColumnInfo it)
			{
				it.DbTableName = tableName;
				if (it.UnderType?.Name == "DateOnly" && it.DataType == null)
				{
					it.DataType = "Date";
				}
				if (it.UnderType?.Name == "TimeOnly" && it.DataType == null)
				{
					it.DataType = "Time";
				}
			});
			bool flag = Context.DbMaintenance.IsAnyTable(tableName, isCache: false);
			if (!flag || !entityInfo.IsDisabledUpdateAll)
			{
				if (flag)
				{
					ExistLogic(entityInfo);
				}
				else
				{
					NoExistLogic(entityInfo);
				}
				Context.DbMaintenance.AddRemark(entityInfo);
				Context.DbMaintenance.AddIndex(entityInfo);
				CreateIndex(entityInfo);
				Context.DbMaintenance.AddDefaultValue(entityInfo);
			}
		}

		private void CreateIndex(EntityInfo entityInfo)
		{
			if (!entityInfo.Indexs.HasValue())
			{
				return;
			}
			foreach (SugarIndexAttribute index in entityInfo.Indexs)
			{
				if (entityInfo.Type.GetCustomAttribute<SplitTableAttribute>() != null)
				{
					string indexName = index.IndexName;
					if (indexName != null && indexName.Contains("{split_table}"))
					{
						index.IndexName = index.IndexName.Replace("{split_table}", entityInfo.DbTableName);
					}
					else
					{
						index.IndexName += entityInfo.DbTableName;
					}
				}
				if (Context.CurrentConnectionConfig.IndexSuffix.HasValue())
				{
					index.IndexName = Context.CurrentConnectionConfig.IndexSuffix + index.IndexName;
				}
				string text = "";
				if (index.IndexName != null)
				{
					string text2 = "{db}";
					if (index.IndexName.Contains(text2))
					{
						index.IndexName = index.IndexName.Replace(text2, Context.Ado.Connection.Database);
					}
					string text3 = "{table}";
					if (index.IndexName.Contains(text3))
					{
						index.IndexName = index.IndexName.Replace(text3, entityInfo.DbTableName);
					}
					if (index.IndexName.ToLower().Contains("{include:"))
					{
						text = Regex.Match(index.IndexName, "\\{include\\:.+$").Value;
						index.IndexName = index.IndexName.Replace(text, "");
					}
					if (index.IndexName.Contains(".") && index.IndexName.Contains("["))
					{
						index.IndexName = index.IndexName.Replace(".", "_");
						index.IndexName = index.IndexName.Replace("[", "").Replace("]", "");
					}
				}
				if (Context.DbMaintenance.IsAnyIndex(index.IndexName))
				{
					continue;
				}
				ISqlBuilder querybulder = InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig);
				querybulder.Context = Context;
				string[] columnNames = (from it in index.IndexFields.Select<KeyValuePair<string, OrderByType>, KeyValuePair<string, OrderByType>>(delegate(KeyValuePair<string, OrderByType> it)
					{
						EntityColumnInfo? entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo z) => z.PropertyName == it.Key);
						if (entityColumnInfo == null && entityInfo.Discrimator == null)
						{
							Check.ExceptionEasy(entityInfo.EntityName + " no   SugarIndex[ " + it.Key + " ]  found", "类" + entityInfo.EntityName + " 索引特性没找到列 ：" + it.Key);
						}
						return new KeyValuePair<string, OrderByType>(entityColumnInfo.DbColumnName, it.Value);
					})
					select querybulder.GetTranslationColumnName(it.Key) + " " + it.Value).ToArray();
				Context.DbMaintenance.CreateIndex(entityInfo.DbTableName, columnNames, index.IndexName + text, index.IsUnique);
			}
		}

		public virtual void NoExistLogic(EntityInfo entityInfo)
		{
			string tableName = GetTableName(entityInfo);
			List<DbColumnInfo> list = new List<DbColumnInfo>();
			if (entityInfo.Columns.HasValue())
			{
				foreach (EntityColumnInfo item2 in from it in entityInfo.Columns
					orderby (!it.IsPrimarykey) ? 1 : 0
					where !it.IsIgnore
					select it)
				{
					DbColumnInfo item = EntityColumnToDbColumn(entityInfo, tableName, item2);
					list.Add(item);
				}
				if (entityInfo.IsCreateTableFiledSort)
				{
					list = list.OrderBy((DbColumnInfo c) => c.CreateTableFieldSort).ToList();
					list = list.OrderBy((DbColumnInfo it) => (!it.IsPrimarykey) ? 1 : 0).ToList();
				}
			}
			Context.DbMaintenance.CreateTable(tableName, list);
		}

		public virtual void ExistLogic(EntityInfo entityInfo)
		{
			if (!entityInfo.Columns.HasValue() || entityInfo.IsDisabledUpdateAll)
			{
				return;
			}
			string tableName = GetTableName(entityInfo);
			List<DbColumnInfo> dbColumns = Context.DbMaintenance.GetColumnInfosByTableName(tableName, isCache: false);
			ConvertColumns(dbColumns);
			List<EntityColumnInfo> entityColumns = entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
			List<DbColumnInfo> list = (from dc in dbColumns
				where !entityColumns.Any((EntityColumnInfo ec) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
				where !entityColumns.Any((EntityColumnInfo ec) => dc.DbColumnName.Equals(ec.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
				select dc).ToList();
			List<EntityColumnInfo> list2 = (from ec in entityColumns
				where ec.OldDbColumnName.IsNullOrEmpty() || !dbColumns.Any((DbColumnInfo dc) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
				where !dbColumns.Any((DbColumnInfo dc) => ec.DbColumnName.Equals(dc.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
				select ec).ToList();
			List<EntityColumnInfo> list3 = (from ec in entityColumns
				where !ec.IsDisabledAlterColumn
				where !dbColumns.Any((DbColumnInfo dc) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
				where dbColumns.Any((DbColumnInfo dc) => dc.DbColumnName.EqualCase(ec.DbColumnName) && ((ec.Length != dc.Length && !UtilMethods.GetUnderType(ec.PropertyInfo).IsEnum() && UtilMethods.GetUnderType(ec.PropertyInfo).IsIn(UtilConstants.StringType)) || ec.IsNullable != dc.IsNullable || IsNoSamePrecision(ec, dc) || IsNoSamgeType(ec, dc)))
				select ec).ToList();
			list3.RemoveAll(delegate(EntityColumnInfo entityColumnInfo3)
			{
				string[] source = "varcharmax,longtext,text,clob".Replace("varcharmax", "nvarchar(max)").Split(',');
				DbColumnInfo dbColumnInfo2 = dbColumns.FirstOrDefault((DbColumnInfo dc) => dc.DbColumnName.EqualCase(entityColumnInfo3.DbColumnName));
				bool flag4 = dbColumnInfo2 != null && dbColumnInfo2.Length == -1 && dbColumnInfo2 != null && dbColumnInfo2.DataType?.EqualCase("nvarchar") == true;
				return (dbColumnInfo2 != null && Enumerable.Contains(source, entityColumnInfo3.DataType)) & flag4;
			});
			List<EntityColumnInfo> list4 = (from entityColumn in entityColumns
				where !string.IsNullOrEmpty(entityColumn.OldDbColumnName)
				where dbColumns.Any((DbColumnInfo dbColumn) => entityColumn.OldDbColumnName.Equals(dbColumn.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
				select entityColumn).ToList();
			bool flag = dbColumns.Where((DbColumnInfo it) => it.IsPrimarykey).Count() > 1 || entityColumns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count() > 1;
			bool flag2 = false;
			foreach (EntityColumnInfo item3 in list2)
			{
				Context.DbMaintenance.AddColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item3));
				flag2 = true;
			}
			if (!entityInfo.IsDisabledDelete)
			{
				foreach (DbColumnInfo item4 in list)
				{
					Context.DbMaintenance.DropColumn(tableName, item4.DbColumnName);
					flag2 = true;
				}
			}
			foreach (EntityColumnInfo item in list3)
			{
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					EntityColumnInfo entityColumnInfo = entityColumns.FirstOrDefault((EntityColumnInfo y) => y.DbColumnName == item.DbColumnName);
					if (entityColumnInfo != null && !string.IsNullOrEmpty(entityColumnInfo.DataType))
					{
						continue;
					}
				}
				Context.DbMaintenance.UpdateColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item));
				flag2 = true;
			}
			foreach (EntityColumnInfo item5 in list4)
			{
				Context.DbMaintenance.RenameColumn(tableName, item5.OldDbColumnName, item5.DbColumnName);
				flag2 = true;
			}
			bool flag3 = false;
			foreach (EntityColumnInfo item2 in entityColumns)
			{
				DbColumnInfo dbColumnInfo = dbColumns.FirstOrDefault((DbColumnInfo dc) => dc.DbColumnName.Equals(item2.DbColumnName, StringComparison.CurrentCultureIgnoreCase));
				if (dbColumnInfo == null)
				{
					continue;
				}
				KeyAction(item2, dbColumnInfo, out var pkDiff, out var idEntityDiff);
				if (((dbColumnInfo != null) & pkDiff) && !idEntityDiff && !flag)
				{
					if (item2.IsPrimarykey)
					{
						flag3 = true;
						Context.DbMaintenance.AddPrimaryKey(tableName, item2.DbColumnName);
					}
					else
					{
						Context.DbMaintenance.DropConstraint(tableName, $"PK_{tableName}_{item2.DbColumnName}");
					}
				}
				else if ((pkDiff | idEntityDiff) && !flag)
				{
					ChangeKey(entityInfo, tableName, item2);
				}
			}
			if (!flag3 && entityColumns.Count((EntityColumnInfo it) => it.IsPrimarykey) == 1 && dbColumns.Count((DbColumnInfo it) => it.IsPrimarykey) == 0)
			{
				EntityColumnInfo entityColumnInfo2 = entityColumns.First((EntityColumnInfo it) => it.IsPrimarykey);
				Context.DbMaintenance.AddPrimaryKey(tableName, entityColumnInfo2.DbColumnName);
			}
			if (flag)
			{
				List<string> list5 = (from it in dbColumns
					where it.IsPrimarykey
					select it.DbColumnName.ToLower() into it
					orderby it
					select it).ToList();
				List<string> list6 = (from it in entityColumns
					where it.IsPrimarykey
					select it.DbColumnName.ToLower() into it
					orderby it
					select it).ToList();
				if (list5.Count == 0 && list6.Count > 1)
				{
					try
					{
						Context.DbMaintenance.AddPrimaryKeys(tableName, list6.ToArray());
					}
					catch (Exception ex)
					{
						Check.Exception(true, ErrorMessage.GetThrowMessage("The current database does not support changing multiple primary keys. " + ex.Message, "当前数据库不支持修改多主键," + ex.Message));
						throw ex;
					}
				}
				else if (!list5.SequenceEqual(list6))
				{
					Check.Exception(true, ErrorMessage.GetThrowMessage("Modification of multiple primary key tables is not supported. Delete tables while creating", "不支持修改多主键表，请删除表在创建"));
				}
			}
			if (flag2 && IsBackupTable)
			{
				Context.DbMaintenance.BackupTable(tableName, tableName + DateTime.Now.ToString("yyyyMMddHHmmss"), MaxBackupDataRows);
			}
			ExistLogicEnd(entityColumns);
		}

		private bool IsNoSamePrecision(EntityColumnInfo ec, DbColumnInfo dc)
		{
			ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
			if (moreSettings != null && moreSettings.EnableCodeFirstUpdatePrecision)
			{
				if (ec.DecimalDigits != dc.DecimalDigits)
				{
					return ec.UnderType.IsIn(UtilConstants.DobType, UtilConstants.DecType);
				}
				return false;
			}
			return false;
		}

		protected virtual void KeyAction(EntityColumnInfo item, DbColumnInfo dbColumn, out bool pkDiff, out bool idEntityDiff)
		{
			pkDiff = item.IsPrimarykey != dbColumn.IsPrimarykey;
			idEntityDiff = item.IsIdentity != dbColumn.IsIdentity;
		}

		protected virtual void ChangeKey(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
		{
			string constraintName = $"PK_{tableName}_{item.DbColumnName}";
			if (Context.DbMaintenance.IsAnyConstraint(constraintName))
			{
				Context.DbMaintenance.DropConstraint(tableName, constraintName);
			}
			Context.DbMaintenance.DropColumn(tableName, item.DbColumnName);
			Context.DbMaintenance.AddColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item));
			if (item.IsPrimarykey)
			{
				Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
			}
		}

		protected virtual void ExistLogicEnd(List<EntityColumnInfo> dbColumns)
		{
		}

		protected virtual void ConvertColumns(List<DbColumnInfo> dbColumns)
		{
		}

		private void RestMappingTables(MappingTableList oldTableList)
		{
			Context.MappingTables.Clear();
			foreach (MappingTable oldTable in oldTableList)
			{
				Context.MappingTables.Add(oldTable.EntityName, oldTable.DbTableName);
			}
		}

		private MappingTableList CopyMappingTalbe()
		{
			MappingTableList mappingTableList = new MappingTableList();
			if (Context.MappingTables == null)
			{
				Context.MappingTables = new MappingTableList();
			}
			foreach (MappingTable mappingTable in Context.MappingTables)
			{
				mappingTableList.Add(mappingTable.EntityName, mappingTable.DbTableName);
			}
			return mappingTableList;
		}

		public virtual string GetCreateTableString(EntityInfo entityInfo)
		{
			StringBuilder stringBuilder = new StringBuilder();
			GetTableName(entityInfo);
			return stringBuilder.ToString();
		}

		public virtual string GetCreateColumnsString(EntityInfo entityInfo)
		{
			StringBuilder stringBuilder = new StringBuilder();
			GetTableName(entityInfo);
			return stringBuilder.ToString();
		}

		protected virtual string GetTableName(EntityInfo entityInfo)
		{
			return Context.EntityMaintenance.GetTableName(entityInfo.EntityName);
		}

		protected virtual DbColumnInfo EntityColumnToDbColumn(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
		{
			Type underType = UtilMethods.GetUnderType(item.PropertyInfo);
			DbColumnInfo result = new DbColumnInfo
			{
				TableId = entityInfo.Columns.IndexOf(item),
				DbColumnName = (item.DbColumnName.HasValue() ? item.DbColumnName : item.PropertyName),
				IsPrimarykey = item.IsPrimarykey,
				IsIdentity = item.IsIdentity,
				TableName = tableName,
				IsNullable = item.IsNullable,
				DefaultValue = item.DefaultValue,
				ColumnDescription = item.ColumnDescription,
				Length = item.Length,
				DecimalDigits = item.DecimalDigits,
				CreateTableFieldSort = item.CreateTableFieldSort
			};
			GetDbType(item, underType, result);
			return result;
		}

		protected virtual void GetDbType(EntityColumnInfo item, Type propertyType, DbColumnInfo result)
		{
			if (!string.IsNullOrEmpty(item.DataType))
			{
				result.DataType = item.DataType;
				return;
			}
			if (propertyType.IsEnum())
			{
				result.DataType = Context.Ado.DbBind.GetDbTypeName((item.Length > 9) ? UtilConstants.LongType.Name : UtilConstants.IntType.Name);
				return;
			}
			string type = GetType(propertyType.Name);
			result.DataType = Context.Ado.DbBind.GetDbTypeName(type);
		}

		protected virtual bool IsNoSamgeType(EntityColumnInfo ec, DbColumnInfo dc)
		{
			if (!string.IsNullOrEmpty(ec.DataType))
			{
				if (ec.IsIdentity && dc.IsIdentity)
				{
					return false;
				}
				return ec.DataType != dc.DataType;
			}
			Type underType = UtilMethods.GetUnderType(ec.PropertyInfo);
			string empty = string.Empty;
			if (underType.IsEnum())
			{
				empty = Context.Ado.DbBind.GetDbTypeName((ec.Length > 9) ? UtilConstants.LongType.Name : UtilConstants.IntType.Name);
			}
			else
			{
				string type = GetType(underType.Name);
				empty = Context.Ado.DbBind.GetDbTypeName(type);
			}
			string dataType = dc.DataType;
			if (empty == "boolean" && dataType == "bool")
			{
				return false;
			}
			if (empty?.ToLower() == "varchar" && dataType?.ToLower() == "string")
			{
				return false;
			}
			if (empty?.ToLower() == "varchar" && dataType?.ToLower() == "nvarchar")
			{
				return false;
			}
			if (empty?.ToLower() == "number" && dataType?.ToLower() == "decimal")
			{
				return false;
			}
			ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
			if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.EnableOracleIdentity == true && empty?.ToLower() == "int" && dataType?.ToLower() == "decimal")
			{
				return false;
			}
			if (empty?.ToLower() == "int" && dataType?.ToLower() == "decimal" && dc.Length == 22 && dc.Scale == 0 && Context.CurrentConnectionConfig.DbType == DbType.Oracle)
			{
				return false;
			}
			if (empty?.ToLower() == "int" && dataType?.ToLower() == "int32")
			{
				return false;
			}
			if (empty?.ToLower() == "date" && dataType?.ToLower() == "datetime")
			{
				return false;
			}
			if (empty?.ToLower() == "bigint" && dataType?.ToLower() == "int64")
			{
				return false;
			}
			if (empty?.ToLower() == "blob" && dataType?.ToLower() == "byte[]")
			{
				return false;
			}
			if (empty == null || dataType == null)
			{
				return empty != dataType;
			}
			if (Context.CurrentConnectionConfig.DbType == DbType.SqlServer && dataType.EqualCase("timestamp") && empty.EqualCase("varbinary"))
			{
				return false;
			}
			if (empty.IsIn("int", "long") && dataType.EqualCase("decimal") && dc.Length == 38 && dc.DecimalDigits == 127)
			{
				return false;
			}
			if (dataType.EqualCase("numeric") && empty.EqualCase("decimal"))
			{
				return false;
			}
			if (ec.UnderType == UtilConstants.BoolType)
			{
				string oracleDataType = dc.OracleDataType;
				if (oracleDataType != null && oracleDataType.EqualCase("number"))
				{
					return false;
				}
			}
			if (ec.UnderType == UtilConstants.LongType && dc.Length == 19 && dc.DecimalDigits == 0)
			{
				string oracleDataType2 = dc.OracleDataType;
				if (oracleDataType2 != null && oracleDataType2.EqualCase("number"))
				{
					return false;
				}
			}
			if (dataType.EqualCase("timestamp") && empty.EqualCase("timestamptz"))
			{
				return false;
			}
			return empty.ToLower() != dataType.ToLower();
		}

		protected string GetType(string name)
		{
			if (name.IsContainsIn("UInt32", "UInt16", "UInt64"))
			{
				name = name.TrimStart('U');
			}
			if (name == "char")
			{
				name = "string";
			}
			return name;
		}
	}
	public class SplitCodeFirstProvider
	{
		public SqlSugarProvider Context;

		public int DefaultLength { get; set; }

		public void InitTables<T>()
		{
			Type typeFromHandle = typeof(T);
			InitTables(typeFromHandle);
		}

		public void InitTables(Type type)
		{
			if (type.GetCustomAttribute<SplitTableAttribute>() != null)
			{
				UtilMethods.StartCustomSplitTable(Context, type);
				_InitTables(type);
				UtilMethods.EndCustomSplitTable(Context, type);
			}
			else
			{
				Context.CodeFirst.SetStringDefaultLength(DefaultLength).InitTables(type);
			}
		}

		private void _InitTables(Type type)
		{
			SplitTableContext splitTableContext = new SplitTableContext(Context)
			{
				EntityInfo = Context.EntityMaintenance.GetEntityInfo(type)
			};
			splitTableContext.CheckPrimaryKey();
			List<SplitTableInfo> tables = splitTableContext.GetTables();
			if (tables.Count > 0)
			{
				foreach (SplitTableInfo item in tables)
				{
					Context.MappingTables.Add(splitTableContext.EntityInfo.EntityName, item.TableName);
					Context.CodeFirst.SetStringDefaultLength(DefaultLength).InitTables(type);
				}
			}
			else
			{
				Context.MappingTables.Add(splitTableContext.EntityInfo.EntityName, splitTableContext.GetDefaultTableName());
				Context.CodeFirst.SetStringDefaultLength(DefaultLength).InitTables(type);
			}
			Context.MappingTables.Add(splitTableContext.EntityInfo.EntityName, splitTableContext.EntityInfo.DbTableName);
		}

		public void InitTables(Type[] types)
		{
			foreach (Type type in types)
			{
				InitTables(type);
			}
		}
	}
	public class TableDifferenceProvider
	{
		internal List<DiffTableInfo> tableInfos = new List<DiffTableInfo>();

		public string ToDiffString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine();
			List<TableDifferenceInfo> list = ToDiffList();
			if (list.IsNullOrEmpty())
			{
				stringBuilder.AppendLine("No change");
			}
			else
			{
				foreach (TableDifferenceInfo item in list)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(14, 1, stringBuilder2);
					handler.AppendLiteral("----Table:");
					handler.AppendFormatted(item.TableName);
					handler.AppendLiteral("----");
					stringBuilder3.AppendLine(ref handler);
					if (item.AddColums.HasValue())
					{
						stringBuilder.AppendLine("Add column: ");
						foreach (DiffColumsInfo addColum in item.AddColums)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder4 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(1, 1, stringBuilder2);
							handler.AppendFormatted(addColum.Message);
							handler.AppendLiteral(" ");
							stringBuilder4.AppendLine(ref handler);
						}
					}
					if (item.UpdateColums.HasValue())
					{
						stringBuilder.AppendLine("Update column: ");
						foreach (DiffColumsInfo updateColum in item.UpdateColums)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder5 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(1, 1, stringBuilder2);
							handler.AppendFormatted(updateColum.Message);
							handler.AppendLiteral(" ");
							stringBuilder5.AppendLine(ref handler);
						}
					}
					if (!item.DeleteColums.HasValue())
					{
						continue;
					}
					stringBuilder.AppendLine("Delete column: ");
					foreach (DiffColumsInfo deleteColum in item.DeleteColums)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder6 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(1, 1, stringBuilder2);
						handler.AppendFormatted(deleteColum.Message);
						handler.AppendLiteral(" ");
						stringBuilder6.AppendLine(ref handler);
					}
				}
			}
			stringBuilder.AppendLine();
			stringBuilder.AppendLine();
			return stringBuilder.ToString();
		}

		public List<TableDifferenceInfo> ToDiffList()
		{
			List<TableDifferenceInfo> list = new List<TableDifferenceInfo>();
			foreach (DiffTableInfo tableInfo in tableInfos)
			{
				TableDifferenceInfo tableDifferenceInfo = new TableDifferenceInfo();
				if (tableInfo.OldTableInfo == null)
				{
					tableInfo.OldTableInfo = new DbTableInfo();
				}
				tableDifferenceInfo.TableName = tableInfo.OldTableInfo.Name;
				tableDifferenceInfo.AddColums = GetAddColumn(tableInfo);
				tableDifferenceInfo.UpdateColums = GetUpdateColumn(tableInfo);
				tableDifferenceInfo.DeleteColums = GetDeleteColumn(tableInfo);
				if (tableDifferenceInfo.IsDiff)
				{
					list.Add(tableDifferenceInfo);
				}
			}
			return list;
		}

		private static List<DiffColumsInfo> GetDeleteColumn(DiffTableInfo tableInfo)
		{
			new List<DiffColumsInfo>();
			return (from it in tableInfo.OldColumnInfos.Where((DbColumnInfo z) => !tableInfo.NewColumnInfos.Any((DbColumnInfo y) => y.DbColumnName.EqualCase(z.DbColumnName))).ToList()
				select new DiffColumsInfo
				{
					Message = GetColumnString(it)
				}).ToList();
		}

		private List<DiffColumsInfo> GetUpdateColumn(DiffTableInfo tableInfo)
		{
			new List<DiffColumsInfo>();
			return (from it in tableInfo.NewColumnInfos
				where tableInfo.OldColumnInfos.Any((DbColumnInfo y) => y.DbColumnName.EqualCase(it.DbColumnName) && (it.Length != y.Length || it.ColumnDescription != y.ColumnDescription || it.DataType != y.DataType || it.DecimalDigits != y.DecimalDigits || it.IsPrimarykey != y.IsPrimarykey || it.IsIdentity != y.IsIdentity || it.IsNullable != y.IsNullable))
				select new DiffColumsInfo
				{
					Message = GetUpdateColumnString(it, tableInfo.OldColumnInfos.FirstOrDefault((DbColumnInfo y) => y.DbColumnName.EqualCase(it.DbColumnName)))
				}).ToList();
		}

		private static List<DiffColumsInfo> GetAddColumn(DiffTableInfo tableInfo)
		{
			new List<DiffColumsInfo>();
			return (from it in tableInfo.NewColumnInfos.Where((DbColumnInfo z) => !tableInfo.OldColumnInfos.Any((DbColumnInfo y) => y.DbColumnName.EqualCase(z.DbColumnName))).ToList()
				select new DiffColumsInfo
				{
					Message = GetColumnString(it)
				}).ToList();
		}

		private static string GetColumnString(DbColumnInfo it)
		{
			return $"{it.DbColumnName}  {it.DataType}  {it.Length} {it.Scale}   default:{it.DefaultValue} description:{it.ColumnDescription} pk:{it.IsPrimarykey} nullable:{it.IsNullable} identity:{it.IsIdentity} ";
		}

		private static string GetUpdateColumnString(DbColumnInfo it, DbColumnInfo old)
		{
			string text = it.DbColumnName + "  changes: ";
			if (it.DataType != old.DataType)
			{
				text += $"  [DataType:{old.DataType}->{it.DataType}] ";
			}
			if (it.Length != old.Length)
			{
				text += $"  [Length:{old.Length}->{it.Length}] ";
			}
			if (it.Scale != old.Scale)
			{
				text += $"  [Scale:{old.Scale}->{it.Scale}] ";
			}
			if (it.ColumnDescription != old.ColumnDescription)
			{
				text += $"  [Description:{old.ColumnDescription}->{it.ColumnDescription}] ";
			}
			if (it.IsPrimarykey != old.IsPrimarykey)
			{
				text += $"  [Pk:{old.IsPrimarykey}->{it.IsPrimarykey}] ";
			}
			if (it.IsNullable != old.IsNullable)
			{
				text += $"  [Nullable:{old.IsNullable}->{it.IsNullable}] ";
			}
			if (it.IsIdentity != old.IsIdentity)
			{
				text += $"  [Identity:{old.IsIdentity}->{it.IsIdentity}] ";
			}
			return text;
		}
	}
	public class TableDifferenceInfo
	{
		public List<DiffColumsInfo> DeleteColums { get; set; } = new List<DiffColumsInfo>();

		public List<DiffColumsInfo> UpdateColums { get; set; } = new List<DiffColumsInfo>();

		public List<DiffColumsInfo> AddColums { get; set; } = new List<DiffColumsInfo>();

		public List<DiffColumsInfo> UpdateRemark { get; set; } = new List<DiffColumsInfo>();

		public bool IsDiff
		{
			get
			{
				if (DeleteColums.Count <= 0 && UpdateColums.Count <= 0 && AddColums.Count <= 0)
				{
					return UpdateRemark.Count > 0;
				}
				return true;
			}
		}

		public string TableName { get; set; }
	}
