		public List<DbColumnInfo> NewColumnInfos { get; set; }
	}
	public class DbBindAccessory
	{
		public QueryBuilder QueryBuilder { get; set; }

		protected List<T> GetEntityList<T>(SqlSugarProvider context, IDataReader dataReader)
		{
			Type type = typeof(T);
			EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
			bool isOwnsOne = entityInfo.Columns.Any((EntityColumnInfo it) => it.ForOwnsOnePropertyInfo != null);
			string types = null;
			List<string> fieldNames = GetDataReaderNames(dataReader, ref types);
			string cacheKey = GetCacheKey(type, fieldNames) + types;
			Action<object, DataAfterModel> dataAfterFunc = context.CurrentConnectionConfig?.AopEvents?.DataExecuted;
			IDataReaderEntityBuilder<T> orCreate = context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => new IDataReaderEntityBuilder<T>(context, dataReader, fieldNames).CreateBuilder(type));
			List<T> list = new List<T>();
			try
			{
				if (dataReader == null)
				{
					return list;
				}
				while (dataReader.Read())
				{
					T val = orCreate.Build(dataReader);
					QueryBuilder queryBuilder = QueryBuilder;
					if (queryBuilder != null && queryBuilder.QueryableFormats?.Any() == true)
					{
						FormatT(val);
					}
					list.Add(val);
					SetAppendColumns(dataReader);
					SetOwnsOne(val, isOwnsOne, entityInfo, dataReader);
				}
				ExecuteDataAfterFun(context, dataAfterFunc, list);
			}
			catch (Exception ex)
			{
				if (!(ex.Message == "Common Language Runtime detected an invalid program."))
				{
					throw;
				}
				Check.Exception(true, ErrorMessage.EntityMappingError, ex.Message);
			}
			return list;
		}

		protected async Task<List<T>> GetEntityListAsync<T>(SqlSugarProvider context, IDataReader dataReader)
		{
			Type type = typeof(T);
			EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
			bool isOwnsOne = entityInfo.Columns.Any((EntityColumnInfo it) => it.ForOwnsOnePropertyInfo != null);
			string types = null;
			List<string> fieldNames = GetDataReaderNames(dataReader, ref types);
			string cacheKey = GetCacheKey(type, fieldNames) + types;
			Action<object, DataAfterModel> dataAfterFunc = context.CurrentConnectionConfig?.AopEvents?.DataExecuted;
			IDataReaderEntityBuilder<T> entytyList = context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => new IDataReaderEntityBuilder<T>(context, dataReader, fieldNames).CreateBuilder(type));
			List<T> result = new List<T>();
			try
			{
				if (dataReader == null)
				{
					return result;
				}
				while (await GetReadAsync(dataReader, context))
				{
					T val = entytyList.Build(dataReader);
					QueryBuilder queryBuilder = QueryBuilder;
					if (queryBuilder != null && queryBuilder.QueryableFormats?.Any() == true)
					{
						FormatT(val);
					}
					result.Add(val);
					SetAppendColumns(dataReader);
					SetOwnsOne(val, isOwnsOne, entityInfo, dataReader);
				}
				ExecuteDataAfterFun(context, dataAfterFunc, result);
			}
			catch (Exception ex)
			{
				if (!(ex.Message == "Common Language Runtime detected an invalid program."))
				{
					throw;
				}
				Check.Exception(true, ErrorMessage.EntityMappingError, ex.Message);
			}
			return result;
		}

		private Task<bool> GetReadAsync(IDataReader dataReader, SqlSugarProvider context)
		{
			QueryBuilder queryBuilder = QueryBuilder;
			if (queryBuilder != null && queryBuilder.Builder?.SupportReadToken == true && context.Ado.CancellationToken.HasValue)
			{
				return QueryBuilder.Builder.GetReaderByToken(dataReader, context.Ado.CancellationToken.Value);
			}
			return ((DbDataReader)dataReader).ReadAsync();
		}

		private void SetOwnsOne(object addItem, bool isOwnsOne, EntityInfo entityInfo, IDataReader dataReader)
		{
			if (!isOwnsOne)
			{
				return;
			}
			foreach (IGrouping<PropertyInfo, EntityColumnInfo> item in (from it in entityInfo.Columns
				where it.ForOwnsOnePropertyInfo != null
				group it by it.ForOwnsOnePropertyInfo).ToList())
			{
				object obj = item.Key.GetValue(addItem);
				if (obj == null)
				{
					obj = item.Key.PropertyType.Assembly.CreateInstance(item.Key.PropertyType.FullName);
					item.Key.SetValue(addItem, obj);
				}
				foreach (EntityColumnInfo item2 in item.ToList())
				{
					QueryBuilder queryBuilder = QueryBuilder;
					if (queryBuilder != null && queryBuilder.SelectValue?.Equals("1") == true)
					{
						continue;
					}
					int ordinal = dataReader.GetOrdinal(item2.DbColumnName);
					if (item2.SqlParameterDbType is Type && item2.UnderType.IsEnum && dataReader.GetValue(ordinal) is string value)
					{
						item2.PropertyInfo.SetValue(obj, UtilMethods.ChangeType2(value, item2.PropertyInfo.PropertyType));
						continue;
					}
					if (item2.IsJson)
					{
						item2.PropertyInfo.SetValue(obj, JsonConvert.DeserializeObject(dataReader.GetValue(ordinal)?.ToString(), item2.PropertyInfo.PropertyType));
						continue;
					}
					object obj2 = dataReader.GetValue(ordinal);
					if (obj2 == DBNull.Value)
					{
						obj2 = null;
					}
					if (item2.UnderType == UtilConstants.GuidType && obj2 is string)
					{
						if (obj2 != null)
						{
							obj2 = Guid.Parse(obj2?.ToString() ?? "");
						}
					}
					else
					{
						Type underType = item2.UnderType;
						if ((object)underType != null && underType.IsEnum && obj2 != null)
						{
							obj2 = UtilMethods.ChangeType2(obj2, item2.UnderType);
						}
						else if (UtilMethods.IsParameterConverter(item2))
						{
							obj2 = UtilMethods.QueryConverter(ordinal, null, dataReader, entityInfo, item2);
						}
					}
					item2.PropertyInfo.SetValue(obj, obj2);
				}
			}
		}

		private void FormatT<T>(T addItem)
		{
			List<QueryableFormat> formats = QueryBuilder.QueryableFormats;
			List<EntityColumnInfo> source = QueryBuilder.Context.EntityMaintenance.GetEntityInfoWithAttr(typeof(T)).Columns.Where((EntityColumnInfo it) => formats.Any((QueryableFormat y) => y.PropertyName == it.PropertyName)).ToList();
			if (!source.Any())
			{
				return;
			}
			foreach (QueryableFormat item in formats)
			{
				EntityColumnInfo? entityColumnInfo = source.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.PropertyName);
				object value = entityColumnInfo.PropertyInfo.GetValue(addItem);
				value = UtilMethods.GetFormatValue(value, item);
				entityColumnInfo.PropertyInfo.SetValue(addItem, value);
			}
		}

		private static void ExecuteDataAfterFun<T>(SqlSugarProvider context, Action<object, DataAfterModel> dataAfterFunc, List<T> result)
		{
			if (dataAfterFunc == null)
			{
				return;
			}
			((AdoProvider)context.Ado).AfterTime = DateTime.Now;
			EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo<T>();
			foreach (T item in result)
			{
				dataAfterFunc(item, new DataAfterModel
				{
					EntityColumnInfos = entityInfo.Columns,
					Entity = entityInfo,
					EntityValue = item
				});
			}
		}

		private string GetCacheKey(Type type, List<string> keys)
		{
			StringBuilder stringBuilder = new StringBuilder("DataReaderToList.");
			stringBuilder.Append(type.FullName);
			stringBuilder.Append(".");
			foreach (string key in keys)
			{
				stringBuilder.Append(key);
			}
			return stringBuilder.ToString();
		}

		private void SetAppendColumns(IDataReader dataReader)
		{
			if (QueryBuilder != null && QueryBuilder.AppendColumns != null && QueryBuilder.AppendColumns.Any())
			{
				if (QueryBuilder.AppendValues == null)
				{
					QueryBuilder.AppendValues = new List<List<QueryableAppendColumn>>();
				}
				List<QueryableAppendColumn> list = new List<QueryableAppendColumn>();
				foreach (QueryableAppendColumn appendColumn in QueryBuilder.AppendColumns)
				{
					int ordinal = dataReader.GetOrdinal(appendColumn.AsName);
					object value = dataReader.GetValue(ordinal);
					list.Add(new QueryableAppendColumn
					{
						Name = appendColumn.Name,
						AsName = appendColumn.AsName,
						Value = value
					});
				}
				QueryBuilder.AppendValues.Add(list);
			}
			if (QueryBuilder?.AppendNavInfo == null)
			{
				return;
			}
			AppendNavResult appendNavResult = new AppendNavResult();
			foreach (KeyValuePair<string, string> item in QueryBuilder?.AppendNavInfo.AppendProperties)
			{
				int ordinal2 = dataReader.GetOrdinal("SugarNav_" + item.Key);
				object value2 = dataReader.GetValue(ordinal2);
				appendNavResult.result.Add("SugarNav_" + item.Key, value2);
			}
			QueryBuilder?.AppendNavInfo.Result.Add(appendNavResult);
		}

		private List<string> GetDataReaderNames(IDataReader dataReader, ref string types)
		{
			List<string> list = new List<string>();
			StringBuilder stringBuilder = new StringBuilder();
			int fieldCount = dataReader.FieldCount;
			for (int i = 0; i < fieldCount; i++)
			{
				list.Add(dataReader.GetName(i));
				Type fieldType = dataReader.GetFieldType(i);
				if (fieldType != null)
				{
					stringBuilder.Append(fieldType.Name.Substring(0, 2));
				}
			}
			types = stringBuilder.ToString();
			if (QueryBuilder?.Context?.Ado is AdoProvider { IsNoSql: not false })
			{
				types = "NoSql";
			}
			return list;
		}

		protected List<T> GetKeyValueList<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			while (dataReader.Read())
			{
				GetKeyValueList(type, dataReader, result);
			}
			return result;
		}

		protected async Task<List<T>> GetKeyValueListAsync<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			while (await ((DbDataReader)dataReader).ReadAsync())
			{
				GetKeyValueList(type, dataReader, result);
			}
			return result;
		}

		private static void GetKeyValueList<T>(Type type, IDataReader dataReader, List<T> result)
		{
			if (UtilConstants.DicOO == type)
			{
				KeyValuePair<object, object> keyValuePair = new KeyValuePair<object, object>(dataReader.GetValue(0), dataReader.GetValue(1));
				result.Add((T)Convert.ChangeType(keyValuePair, typeof(KeyValuePair<object, object>)));
			}
			else if (UtilConstants.DicIS == type)
			{
				KeyValuePair<int, string> keyValuePair2 = new KeyValuePair<int, string>(dataReader.GetValue(0).ObjToInt(), dataReader.GetValue(1).ObjToString());
				result.Add((T)Convert.ChangeType(keyValuePair2, typeof(KeyValuePair<int, string>)));
			}
			else if (UtilConstants.Dicii == type)
			{
				KeyValuePair<int, int> keyValuePair3 = new KeyValuePair<int, int>(dataReader.GetValue(0).ObjToInt(), dataReader.GetValue(1).ObjToInt());
				result.Add((T)Convert.ChangeType(keyValuePair3, typeof(KeyValuePair<int, int>)));
			}
			else if (UtilConstants.DicSi == type)
			{
				KeyValuePair<string, int> keyValuePair4 = new KeyValuePair<string, int>(dataReader.GetValue(0).ObjToString(), dataReader.GetValue(1).ObjToInt());
				result.Add((T)Convert.ChangeType(keyValuePair4, typeof(KeyValuePair<string, int>)));
			}
			else if (UtilConstants.DicSo == type)
			{
				KeyValuePair<string, object> keyValuePair5 = new KeyValuePair<string, object>(dataReader.GetValue(0).ObjToString(), dataReader.GetValue(1));
				result.Add((T)Convert.ChangeType(keyValuePair5, typeof(KeyValuePair<string, object>)));
			}
			else if (UtilConstants.DicSS == type)
			{
				KeyValuePair<string, string> keyValuePair6 = new KeyValuePair<string, string>(dataReader.GetValue(0).ObjToString(), dataReader.GetValue(1).ObjToString());
				result.Add((T)Convert.ChangeType(keyValuePair6, typeof(KeyValuePair<string, string>)));
			}
			else
			{
				Check.Exception(true, ErrorMessage.NotSupportedDictionary);
			}
		}

		protected async Task<List<T>> GetArrayListAsync<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			int count = dataReader.FieldCount;
			Type childType = type.GetElementType();
			while (await ((DbDataReader)dataReader).ReadAsync())
			{
				GetArrayList(type, dataReader, result, count, childType);
			}
			return result;
		}

		protected List<T> GetArrayList<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			int fieldCount = dataReader.FieldCount;
			Type elementType = type.GetElementType();
			while (dataReader.Read())
			{
				GetArrayList(type, dataReader, result, fieldCount, elementType);
			}
			return result;
		}

		private static void GetArrayList<T>(Type type, IDataReader dataReader, List<T> result, int count, Type childType)
		{
			object[] array = new object[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = Convert.ChangeType(dataReader.GetValue(i), childType);
			}
			if (childType == UtilConstants.StringType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => it.ObjToString()).ToArray(), type));
			}
			else if (childType == UtilConstants.ObjType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => (it != DBNull.Value) ? it : null).ToArray(), type));
			}
			else if (childType == UtilConstants.BoolType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => it.ObjToBool()).ToArray(), type));
			}
			else if (childType == UtilConstants.ByteType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => (it != DBNull.Value) ? ((byte)it) : 0).ToArray(), type));
			}
			else if (childType == UtilConstants.DecType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => it.ObjToDecimal()).ToArray(), type));
			}
			else if (childType == UtilConstants.GuidType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => (it != DBNull.Value) ? ((Guid)it) : Guid.Empty).ToArray(), type));
			}
			else if (childType == UtilConstants.DateType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => (it != DBNull.Value) ? ((DateTime)it) : DateTime.MinValue).ToArray(), type));
			}
			else if (childType == UtilConstants.IntType)
			{
				result.Add((T)Convert.ChangeType(array.Select((object it) => it.ObjToInt()).ToArray(), type));
			}
			else
			{
				Check.Exception(true, ErrorMessage.NotSupportedArray);
			}
		}

		protected List<T> GetValueTypeList<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			while (dataReader.Read())
			{
				GetValueTypeList(type, dataReader, result);
			}
			return result;
		}

		protected async Task<List<T>> GetValueTypeListAsync<T>(Type type, IDataReader dataReader)
		{
			List<T> result = new List<T>();
			while (await ((DbDataReader)dataReader).ReadAsync())
			{
				GetValueTypeList(type, dataReader, result);
			}
			return result;
		}

		private static void GetValueTypeList<T>(Type type, IDataReader dataReader, List<T> result)
		{
			object obj = dataReader.GetValue(0);
			if (type == UtilConstants.GuidType)
			{
				obj = Guid.Parse(obj.ToString());
			}
			if (obj == DBNull.Value)
			{
				result.Add(default(T));
			}
			else if (type.IsEnum)
			{
				result.Add((T)Enum.Parse(type, obj.ObjToString()));
			}
			else if (obj != null && UtilMethods.GetUnderType(type).IsEnum)
			{
				result.Add((T)Enum.Parse(UtilMethods.GetUnderType(type), obj.ObjToString()));
			}
			else
			{
				result.Add((T)UtilMethods.ChangeType2(obj, type));
			}
		}
	}
	public abstract class DbBindProvider : DbBindAccessory, IDbBind
	{
		public virtual SqlSugarProvider Context { get; set; }

		public abstract List<KeyValuePair<string, CSharpDataType>> MappingTypes { get; }

		public virtual List<string> IntThrow => new List<string> { "datetime", "byte" };

		public virtual List<string> ShortThrow => new List<string> { "datetime", "guid" };

		public virtual List<string> DecimalThrow => new List<string> { "datetime", "byte", "guid" };

		public virtual List<string> DoubleThrow => new List<string> { "datetime", "byte", "guid" };

		public virtual List<string> DateThrow => new List<string> { "int32", "decimal", "double", "byte", "guid" };

		public virtual List<string> GuidThrow => new List<string> { "int32", "datetime", "decimal", "double", "byte" };

		public virtual List<string> StringThrow => new List<string> { "int32", "datetime", "decimal", "double", "byte", "int64", "uint32", "uint64" };

		public virtual string GetDbTypeName(string csharpTypeName)
		{
			if (csharpTypeName == UtilConstants.ByteArrayType.Name)
			{
				return "varbinary";
			}
			if (csharpTypeName.ToLower() == "int32")
			{
				csharpTypeName = "int";
			}
			if (csharpTypeName.ToLower() == "int16")
			{
				csharpTypeName = "short";
			}
			if (csharpTypeName.ToLower() == "int64")
			{
				csharpTypeName = "long";
			}
			if (csharpTypeName.ToLower().IsIn("boolean", "bool"))
			{
				csharpTypeName = "bool";
			}
			if (csharpTypeName == "DateTimeOffset")
			{
				csharpTypeName = "DateTime";
			}
			List<KeyValuePair<string, CSharpDataType>> list = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Value.ToString().Equals(csharpTypeName, StringComparison.CurrentCultureIgnoreCase)).ToList();
			if (list != null && list.Count > 0)
			{
				return list.First().Key;
			}
			return "varchar";
		}

		public string GetCsharpTypeName(string dbTypeName)
		{
			IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Key == dbTypeName);
			if (!enumerable.HasValue())
			{
				return "string";
			}
			return enumerable.First().Key;
		}

		public string GetCsharpTypeNameByDbTypeName(string dbTypeName)
		{
			IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Key == dbTypeName);
			if (enumerable == null || enumerable.Count() == 0)
			{
				return "string";
			}
			return enumerable.First().Value.ObjToString();
		}

		public virtual string GetConvertString(string dbTypeName)
		{
			string empty = string.Empty;
			switch (dbTypeName.ToLower())
			{
			case "int":
				return "Convert.ToInt32";
			case "nchar":
			case "ntext":
			case "text":
			case "char":
			case "nvarchar":
			case "varchar":
				return "Convert.ToString";
			case "bigint":
				return "Convert.ToInt64";
			case "bit":
				return "Convert.ToBoolean";
			case "date":
			case "datetime":
			case "datetime2":
			case "timestamp":
			case "smalldatetime":
				return "Convert.ToDateTime";
			case "money":
			case "decimal":
			case "numeric":
			case "single":
			case "smallmoney":
				return "Convert.ToDecimal";
			case "float":
				return "Convert.ToSingle";
			case "double":
				return "Convert.ToDouble";
			case "image":
			case "binary":
			case "varbinary":
				return "byte[]";
			case "real":
				return "Convert.ToSingle";
			case "smallint":
				return "Convert.ToInt16";
			case "tinyint":
				return "Convert.ToByte";
			case "uniqueidentifier":
				return "Guid.Parse";
			default:
				return null;
			}
		}

		public virtual string GetPropertyTypeName(string dbTypeName)
		{
			dbTypeName = dbTypeName.ToLower();
			IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Key.Equals(dbTypeName, StringComparison.CurrentCultureIgnoreCase));
			if (dbTypeName == "int32")
			{
				return "int";
			}
			if (dbTypeName == "int64")
			{
				return "long";
			}
			if (dbTypeName == "int16")
			{
				return "short";
			}
			if (enumerable == null)
			{
				return "other";
			}
			if (dbTypeName.IsContainsIn("xml", "string", "String"))
			{
				return "string";
			}
			if (dbTypeName.IsContainsIn("boolean", "bool"))
			{
				return "bool";
			}
			if (enumerable == null || enumerable.Count() == 0)
			{
				return "object";
			}
			if (enumerable.First().Value == CSharpDataType.byteArray)
			{
				return "byte[]";
			}
			return enumerable.First().Value.ToString();
		}

		public virtual List<T> DataReaderToList<T>(Type type, IDataReader dataReader)
		{
			using (dataReader)
			{
				if (UtilMethods.IsKeyValuePairType(type))
				{
					return GetKeyValueList<T>(type, dataReader);
				}
				if (type.IsValueType() || type == UtilConstants.StringType || type == UtilConstants.ByteArrayType)
				{
					return GetValueTypeList<T>(type, dataReader);
				}
				if (type.IsArray)
				{
					return GetArrayList<T>(type, dataReader);
				}
				if (typeof(T) != type && typeof(T).IsInterface)
				{
					return GetEntityListByType<T>(type, Context, dataReader);
				}
				return GetEntityList<T>(Context, dataReader);
			}
		}

		public virtual async Task<List<T>> DataReaderToListAsync<T>(Type type, IDataReader dataReader)
		{
			using (dataReader)
			{
				if (UtilMethods.IsKeyValuePairType(type))
				{
					return await GetKeyValueListAsync<T>(type, dataReader);
				}
				if (type.IsValueType() || type == UtilConstants.StringType || type == UtilConstants.ByteArrayType)
				{
					return await GetValueTypeListAsync<T>(type, dataReader);
				}
				if (type.IsArray)
				{
					return await GetArrayListAsync<T>(type, dataReader);
				}
				if (typeof(T) != type && typeof(T).IsInterface)
				{
					return await GetEntityListByTypeAsync<T>(type, Context, dataReader);
				}
				return await GetEntityListAsync<T>(Context, dataReader);
			}
		}

		public virtual List<T> DataReaderToListNoUsing<T>(Type type, IDataReader dataReader)
		{
			if (UtilMethods.IsKeyValuePairType(type))
			{
				return GetKeyValueList<T>(type, dataReader);
			}
			if (type.IsValueType() || type == UtilConstants.StringType || type == UtilConstants.ByteArrayType)
			{
				return GetValueTypeList<T>(type, dataReader);
			}
			if (type.IsArray)
			{
				return GetArrayList<T>(type, dataReader);
			}
			return GetEntityList<T>(Context, dataReader);
		}

		public virtual Task<List<T>> DataReaderToListNoUsingAsync<T>(Type type, IDataReader dataReader)
		{
			if (UtilMethods.IsKeyValuePairType(type))
			{
				return GetKeyValueListAsync<T>(type, dataReader);
			}
			if (type.IsValueType() || type == UtilConstants.StringType || type == UtilConstants.ByteArrayType)
			{
				return GetValueTypeListAsync<T>(type, dataReader);
			}
			if (type.IsArray)
			{
				return GetArrayListAsync<T>(type, dataReader);
			}
			return GetEntityListAsync<T>(Context, dataReader);
		}

		public virtual List<T> GetEntityListByType<T>(Type entityType, SqlSugarProvider context, IDataReader dataReader)
		{
			object? obj = typeof(DbBindProvider).GetMethod("GetEntityList", BindingFlags.Instance | BindingFlags.NonPublic).MakeGenericMethod(entityType).Invoke(this, new object[2] { context, dataReader });
			List<T> list = new List<T>();
			foreach (object item in obj as IEnumerable)
			{
				list.Add((T)item);
			}
			return list;
		}

		public virtual async Task<List<T>> GetEntityListByTypeAsync<T>(Type entityType, SqlSugarProvider context, IDataReader dataReader)
		{
			return await GetTask<T>((Task)typeof(DbBindProvider).GetMethod("GetEntityListAsync", BindingFlags.Instance | BindingFlags.NonPublic).MakeGenericMethod(entityType).Invoke(this, new object[2] { context, dataReader }));
		}

		private static async Task<List<T>> GetTask<T>(Task task)
		{
			await task.ConfigureAwait(continueOnCapturedContext: false);
			object? value = task.GetType().GetProperty("Result").GetValue(task);
			List<T> list = new List<T>();
			foreach (object item in value as IEnumerable)
			{
				list.Add((T)item);
			}
			return list;
		}
	}
