	public class IDataReaderEntityBuilder<T>
	{
		private delegate T Load(IDataRecord dataRecord);

		private SqlSugarProvider Context;

		private IDataReaderEntityBuilder<T> DynamicBuilder;

		private IDataRecord DataRecord;

		private static readonly MethodInfo isDBNullMethod = typeof(IDataRecord).GetMethod("IsDBNull", new Type[1] { typeof(int) });

		private static readonly MethodInfo getBoolean = typeof(IDataRecord).GetMethod("GetBoolean", new Type[1] { typeof(int) });

		private static readonly MethodInfo getByte = typeof(IDataRecord).GetMethod("GetByte", new Type[1] { typeof(int) });

		private static readonly MethodInfo getDateTime = typeof(IDataRecord).GetMethod("GetDateTime", new Type[1] { typeof(int) });

		private static readonly MethodInfo getDecimal = typeof(IDataRecord).GetMethod("GetDecimal", new Type[1] { typeof(int) });

		private static readonly MethodInfo getDouble = typeof(IDataRecord).GetMethod("GetDouble", new Type[1] { typeof(int) });

		private static readonly MethodInfo getFloat = typeof(IDataRecord).GetMethod("GetFloat", new Type[1] { typeof(int) });

		private static readonly MethodInfo getGuid = typeof(IDataRecord).GetMethod("GetGuid", new Type[1] { typeof(int) });

		private static readonly MethodInfo getInt16 = typeof(IDataRecord).GetMethod("GetInt16", new Type[1] { typeof(int) });

		private static readonly MethodInfo getInt32 = typeof(IDataRecord).GetMethod("GetInt32", new Type[1] { typeof(int) });

		private static readonly MethodInfo getInt64 = typeof(IDataRecord).GetMethod("GetInt64", new Type[1] { typeof(int) });

		private static readonly MethodInfo getString = typeof(IDataRecord).GetMethod("GetString", new Type[1] { typeof(int) });

		private static readonly MethodInfo getdatetimeoffset = typeof(IDataRecordExtensions).GetMethod("Getdatetimeoffset");

		private static readonly MethodInfo getdatetimeoffsetDate = typeof(IDataRecordExtensions).GetMethod("GetdatetimeoffsetDate");

		private static readonly MethodInfo getStringGuid = typeof(IDataRecordExtensions).GetMethod("GetStringGuid");

		private static readonly MethodInfo getXelement = typeof(IDataRecordExtensions).GetMethod("GetXelement");

		private static readonly MethodInfo getConvertStringGuid = typeof(IDataRecordExtensions).GetMethod("GetConvertStringGuid");

		private static readonly MethodInfo getEnum = typeof(IDataRecordExtensions).GetMethod("GetEnum");

		private static readonly MethodInfo getConvertString = typeof(IDataRecordExtensions).GetMethod("GetConvertString");

		private static readonly MethodInfo getConvertFloat = typeof(IDataRecordExtensions).GetMethod("GetConvertFloat");

		private static readonly MethodInfo getConvertBoolean = typeof(IDataRecordExtensions).GetMethod("GetConvertBoolean");

		private static readonly MethodInfo getConvertByte = typeof(IDataRecordExtensions).GetMethod("GetConvertByte");

		private static readonly MethodInfo getConvertChar = typeof(IDataRecordExtensions).GetMethod("GetConvertChar");

		private static readonly MethodInfo getConvertDateTime = typeof(IDataRecordExtensions).GetMethod("GetConvertDateTime");

		private static readonly MethodInfo getConvertTime = typeof(IDataRecordExtensions).GetMethod("GetConvertTime");

		private static readonly MethodInfo getTime = typeof(IDataRecordExtensions).GetMethod("GetTime");

		private static readonly MethodInfo getConvertDecimal = typeof(IDataRecordExtensions).GetMethod("GetConvertDecimal");

		private static readonly MethodInfo getConvertDouble = typeof(IDataRecordExtensions).GetMethod("GetConvertDouble");

		private static readonly MethodInfo getConvertDoubleToFloat = typeof(IDataRecordExtensions).GetMethod("GetConvertDoubleToFloat");

		private static readonly MethodInfo getConvertGuid = typeof(IDataRecordExtensions).GetMethod("GetConvertGuid");

		private static readonly MethodInfo getConvertInt16 = typeof(IDataRecordExtensions).GetMethod("GetConvertInt16");

		private static readonly MethodInfo getConvertInt32 = typeof(IDataRecordExtensions).GetMethod("GetConvertInt32");

		private static readonly MethodInfo getConvertInt64 = typeof(IDataRecordExtensions).GetMethod("GetConvetInt64");

		private static readonly MethodInfo getConvertEnum_Null = typeof(IDataRecordExtensions).GetMethod("GetConvertEnum_Null");

		private static readonly MethodInfo getConvertdatetimeoffset = typeof(IDataRecordExtensions).GetMethod("GetConvertdatetimeoffset");

		private static readonly MethodInfo getConvertdatetimeoffsetDate = typeof(IDataRecordExtensions).GetMethod("GetConvertdatetimeoffsetDate");

		private static readonly MethodInfo getOtherNull = typeof(IDataRecordExtensions).GetMethod("GetOtherNull");

		private static readonly MethodInfo getOther = typeof(IDataRecordExtensions).GetMethod("GetOther");

		private static readonly MethodInfo getJson = typeof(IDataRecordExtensions).GetMethod("GetJson");

		private static readonly MethodInfo getArray = typeof(IDataRecordExtensions).GetMethod("GetArray");

		private static readonly MethodInfo getEntity = typeof(IDataRecordExtensions).GetMethod("GetEntity", new Type[1] { typeof(SqlSugarProvider) });

		private static readonly MethodInfo getMyIntNull = typeof(IDataRecordExtensions).GetMethod("GetMyIntNull");

		private static readonly MethodInfo getMyInt = typeof(IDataRecordExtensions).GetMethod("GetMyInt");

		private Load handler;

		private List<string> ReaderKeys { get; set; }

		private IDataReaderEntityBuilder()
		{
		}

		public IDataReaderEntityBuilder(SqlSugarProvider context, IDataRecord dataRecord, List<string> fieldNames)
		{
			Context = context;
			DataRecord = dataRecord;
			DynamicBuilder = new IDataReaderEntityBuilder<T>();
			ReaderKeys = fieldNames;
		}

		public T Build(IDataRecord dataRecord)
		{
			return handler(dataRecord);
		}

		public IDataReaderEntityBuilder<T> CreateBuilder(Type type)
		{
			DynamicMethod dynamicMethod = new DynamicMethod("SqlSugarEntity", type, new Type[1] { typeof(IDataRecord) }, type, skipVisibility: true);
			ILGenerator iLGenerator = dynamicMethod.GetILGenerator();
			LocalBuilder localBuilder = iLGenerator.DeclareLocal(type);
			iLGenerator.Emit(OpCodes.Newobj, type.GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null));
			iLGenerator.Emit(OpCodes.Stloc, localBuilder);
			Context.InitMappingInfo(type);
			foreach (EntityColumnInfo columnInfo in Context.EntityMaintenance.GetEntityInfoWithAttr(type).Columns)
			{
				string fileName = columnInfo.DbColumnName ?? columnInfo.PropertyName;
				if ((columnInfo.IsIgnore && !ReaderKeys.Any((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase))) || columnInfo.ForOwnsOnePropertyInfo != null || columnInfo == null || !(columnInfo.PropertyInfo.GetSetMethod(nonPublic: true) != null))
				{
					continue;
				}
				bool flag = columnInfo.PropertyInfo?.PropertyType?.FullName == "NetTopologySuite.Geometries.Geometry";
				if (!flag && columnInfo.PropertyInfo?.PropertyType?.FullName == "Kdbndp.LegacyPostgis.PostgisGeometry")
				{
					flag = true;
				}
				if (!flag && columnInfo.PropertyInfo.PropertyType.IsClass() && columnInfo.PropertyInfo.PropertyType != UtilConstants.ByteArrayType && columnInfo.PropertyInfo.PropertyType != UtilConstants.ObjType)
				{
					if (ReaderKeys.Any((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)))
					{
						BindClass(iLGenerator, localBuilder, columnInfo, ReaderKeys.First((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)));
					}
					else if (ReaderKeys.Any((string it) => it.Equals(columnInfo.PropertyName, StringComparison.CurrentCultureIgnoreCase)))
					{
						BindClass(iLGenerator, localBuilder, columnInfo, ReaderKeys.First((string it) => it.Equals(columnInfo.PropertyName, StringComparison.CurrentCultureIgnoreCase)));
					}
				}
				else if (!flag && columnInfo.IsJson && columnInfo.PropertyInfo.PropertyType != UtilConstants.StringType)
				{
					if (ReaderKeys.Any((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)))
					{
						BindClass(iLGenerator, localBuilder, columnInfo, ReaderKeys.First((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)));
					}
				}
				else if (ReaderKeys.Any((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)))
				{
					BindField(iLGenerator, localBuilder, columnInfo, ReaderKeys.First((string it) => it.Equals(fileName, StringComparison.CurrentCultureIgnoreCase)));
				}
				else if (ReaderKeys.Any((string it) => it.Equals(columnInfo.PropertyName, StringComparison.CurrentCultureIgnoreCase)))
				{
					BindField(iLGenerator, localBuilder, columnInfo, ReaderKeys.First((string it) => it.Equals(columnInfo.PropertyName, StringComparison.CurrentCultureIgnoreCase)));
				}
			}
			iLGenerator.Emit(OpCodes.Ldloc, localBuilder);
			iLGenerator.Emit(OpCodes.Ret);
			DynamicBuilder.handler = (Load)dynamicMethod.CreateDelegate(typeof(Load));
			return DynamicBuilder;
		}

		private void BindCustomFunc(ILGenerator generator, LocalBuilder result, EntityColumnInfo columnInfo, string fieldName)
		{
			int ordinal = DataRecord.GetOrdinal(fieldName);
			Label label = generator.DefineLabel();
			generator.Emit(OpCodes.Ldarg_0);
			generator.Emit(OpCodes.Ldc_I4, ordinal);
			generator.Emit(OpCodes.Callvirt, isDBNullMethod);
			generator.Emit(OpCodes.Brtrue, label);
			generator.Emit(OpCodes.Ldloc, result);
			MethodInfo method = (columnInfo.SqlParameterDbType as Type).GetMethod("QueryConverter");
			method = method.MakeGenericMethod(columnInfo.PropertyInfo.PropertyType);
			Type type = columnInfo.SqlParameterDbType as Type;
			generator.Emit(OpCodes.Newobj, type.GetConstructor(Type.EmptyTypes));
			generator.Emit(OpCodes.Ldarg_0);
			generator.Emit(OpCodes.Ldc_I4, ordinal);
			if (method.IsVirtual)
			{
				generator.Emit(OpCodes.Callvirt, method);
			}
			else
			{
				generator.Emit(OpCodes.Call, method);
			}
			generator.Emit(OpCodes.Callvirt, columnInfo.PropertyInfo.GetSetMethod(nonPublic: true));
			generator.MarkLabel(label);
		}

		private void BindClass(ILGenerator generator, LocalBuilder result, EntityColumnInfo columnInfo, string fieldName)
		{
			if (columnInfo.SqlParameterDbType is Type)
			{
				BindCustomFunc(generator, result, columnInfo, fieldName);
				return;
			}
			if (columnInfo.IsJson)
			{
				MethodInfo meth = getJson.MakeGenericMethod(columnInfo.PropertyInfo.PropertyType);
				int ordinal = DataRecord.GetOrdinal(fieldName);
				Label label = generator.DefineLabel();
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal);
				generator.Emit(OpCodes.Callvirt, isDBNullMethod);
				generator.Emit(OpCodes.Brtrue, label);
				generator.Emit(OpCodes.Ldloc, result);
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal);
				InsertBuilder insertBuilder = InstanceFactory.GetInsertBuilder(Context?.CurrentConnectionConfig);
				if (insertBuilder != null && insertBuilder.DeserializeObjectFunc != null)
				{
					if (IDataRecordExtensions.DeserializeObjectFunc == null)
					{
						IDataRecordExtensions.DeserializeObjectFunc = insertBuilder.DeserializeObjectFunc;
					}
					meth = typeof(IDataRecordExtensions).GetMethod("GetDeserializeObject").MakeGenericMethod(columnInfo.PropertyInfo.PropertyType);
				}
				generator.Emit(OpCodes.Call, meth);
				generator.Emit(OpCodes.Callvirt, columnInfo.PropertyInfo.GetSetMethod(nonPublic: true));
				generator.MarkLabel(label);
			}
			if (columnInfo.IsArray)
			{
				MethodInfo meth2 = getArray.MakeGenericMethod(columnInfo.PropertyInfo.PropertyType);
				int ordinal2 = DataRecord.GetOrdinal(fieldName);
				Label label2 = generator.DefineLabel();
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal2);
				generator.Emit(OpCodes.Callvirt, isDBNullMethod);
				generator.Emit(OpCodes.Brtrue, label2);
				generator.Emit(OpCodes.Ldloc, result);
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal2);
				generator.Emit(OpCodes.Call, meth2);
				generator.Emit(OpCodes.Callvirt, columnInfo.PropertyInfo.GetSetMethod(nonPublic: true));
				generator.MarkLabel(label2);
			}
			else if (columnInfo.UnderType == typeof(XElement))
			{
				int ordinal3 = DataRecord.GetOrdinal(fieldName);
				Label label3 = generator.DefineLabel();
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal3);
				generator.Emit(OpCodes.Callvirt, isDBNullMethod);
				generator.Emit(OpCodes.Brtrue, label3);
				generator.Emit(OpCodes.Ldloc, result);
				generator.Emit(OpCodes.Ldarg_0);
				generator.Emit(OpCodes.Ldc_I4, ordinal3);
				BindMethod(generator, columnInfo, ordinal3);
				generator.Emit(OpCodes.Callvirt, columnInfo.PropertyInfo.GetSetMethod(nonPublic: true));
				generator.MarkLabel(label3);
			}
		}

		private void BindField(ILGenerator generator, LocalBuilder result, EntityColumnInfo columnInfo, string fieldName)
		{
			if (columnInfo.SqlParameterDbType is Type)
			{
				BindCustomFunc(generator, result, columnInfo, fieldName);
				return;
			}
			int ordinal = DataRecord.GetOrdinal(fieldName);
			Label label = generator.DefineLabel();
			Label label2 = generator.BeginExceptionBlock();
			generator.Emit(OpCodes.Ldarg_0);
			generator.Emit(OpCodes.Ldc_I4, ordinal);
			generator.Emit(OpCodes.Callvirt, isDBNullMethod);
			generator.Emit(OpCodes.Brtrue, label);
			generator.Emit(OpCodes.Ldloc, result);
			generator.Emit(OpCodes.Ldarg_0);
			generator.Emit(OpCodes.Ldc_I4, ordinal);
			BindMethod(generator, columnInfo, ordinal);
			generator.Emit(OpCodes.Callvirt, columnInfo.PropertyInfo.GetSetMethod(nonPublic: true));
			generator.MarkLabel(label);
			generator.Emit(OpCodes.Leave, label2);
			generator.BeginCatchBlock(typeof(Exception));
			generator.Emit(OpCodes.Ldstr, ErrorMessage.GetThrowMessage(columnInfo.EntityName + " " + columnInfo.PropertyName + " bind error", columnInfo.PropertyName + "绑定到" + columnInfo.EntityName + "失败,可以试着换一个类型，或者使用ORM自定义类型实现"));
			generator.Emit(OpCodes.Newobj, typeof(Exception).GetConstructor(new Type[1] { typeof(string) }));
			generator.Emit(OpCodes.Throw);
			generator.EndExceptionBlock();
		}

		private void BindMethod(ILGenerator generator, EntityColumnInfo columnInfo, int ordinal)
		{
			IDbBind dbBind = Context.Ado.DbBind;
			bool isNullable = false;
			MethodInfo methodInfo = null;
			Type underType = UtilMethods.GetUnderType(columnInfo.PropertyInfo, ref isNullable);
			string text = UtilMethods.GetParenthesesValue(DataRecord.GetDataTypeName(ordinal));
			if (text.IsNullOrEmpty())
			{
				text = underType.Name;
			}
			string propertyName = columnInfo.PropertyName;
			string propertyTypeName = dbBind.GetPropertyTypeName(text);
			propertyTypeName = ((propertyTypeName == "byte[]") ? "byteArray" : propertyTypeName);
			CSharpDataType cSharpDataType = (CSharpDataType)Enum.Parse(typeof(CSharpDataType), propertyTypeName);
			if (Context.Ado is AdoProvider { IsNoSql: not false })
			{
				methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
				if (methodInfo.IsVirtual)
				{
					generator.Emit(OpCodes.Callvirt, methodInfo);
				}
				else
				{
					generator.Emit(OpCodes.Call, methodInfo);
				}
				return;
			}
			if (Context.CurrentConnectionConfig.DbType == DbType.Sqlite)
			{
				if (underType.IsEnum())
				{
					methodInfo = (isNullable ? getConvertEnum_Null.MakeGenericMethod(underType) : getEnum.MakeGenericMethod(underType));
				}
				else if (underType == UtilConstants.IntType)
				{
					methodInfo = (isNullable ? getConvertInt32 : getInt32);
				}
				else
				{
					_ = underType == UtilConstants.DateTimeOffsetType;
					methodInfo = ((underType == UtilConstants.ByteType) ? (isNullable ? getConvertByte : getByte) : ((underType == UtilConstants.StringType && text?.ToLower() == "timestamp") ? (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType)) : (text.EqualCase("STRING") ? (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType)) : ((underType == UtilConstants.StringType && propertyTypeName == "int") ? (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType)) : ((!(underType == UtilConstants.StringType)) ? (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType)) : getString)))));
				}
				if (methodInfo.IsVirtual)
				{
					generator.Emit(OpCodes.Callvirt, methodInfo);
				}
				else
				{
					generator.Emit(OpCodes.Call, methodInfo);
				}
				return;
			}
			string text2 = underType.Name.ToLower();
			if (underType.IsEnum())
			{
				cSharpDataType = CSharpDataType.@enum;
			}
			switch (cSharpDataType)
			{
			case CSharpDataType.@int:
				CheckType(dbBind.IntThrow, text2, propertyTypeName, propertyName);
				if (text2.IsContainsIn("int", "int32"))
				{
					methodInfo = (isNullable ? getConvertInt32 : getInt32);
				}
				if (text2.IsContainsIn("int64"))
				{
					methodInfo = null;
				}
				if (text2.IsContainsIn("byte"))
				{
					methodInfo = (isNullable ? getConvertByte : getByte);
				}
				if (text2.IsContainsIn("int16"))
				{
					methodInfo = (isNullable ? getConvertInt16 : getInt16);
				}
				if (text2 == "uint32" && Context.CurrentConnectionConfig.DbType.IsIn(default(DbType)))
				{
					methodInfo = null;
				}
				if (text2 == "int16")
				{
					methodInfo = null;
				}
				break;
			case CSharpDataType.@bool:
				if (text2 == "bool" || text2 == "boolean")
				{
					methodInfo = (isNullable ? getConvertBoolean : getBoolean);
				}
				break;
			case CSharpDataType.@string:
				if (Context.CurrentConnectionConfig.DbType != DbType.Oracle)
				{
					CheckType(dbBind.StringThrow, text2, propertyTypeName, propertyName);
				}
				methodInfo = getString;
				if (text2 == "guid")
				{
					methodInfo = (isNullable ? getConvertStringGuid : getStringGuid);
				}
				else if (text2 == "xelement")
				{
					methodInfo = getXelement;
				}
				else if (text == "CHAR" && DataRecord.GetDataTypeName(ordinal) == "CHAR(36)")
				{
					methodInfo = null;
				}
				else if (underType.Name == "Char")
				{
					methodInfo = null;
				}
				break;
			case CSharpDataType.DateTime:
				CheckType(dbBind.DateThrow, text2, propertyTypeName, propertyName);
				if (text2 == "datetime")
				{
					methodInfo = (isNullable ? getConvertDateTime : getDateTime);
				}
				if (text2 == "datetime" && text.ToLower() == "time")
				{
					methodInfo = (isNullable ? getConvertTime : getTime);
				}
				if (text2 == "datetimeoffset")
				{
					methodInfo = (isNullable ? getConvertdatetimeoffset : getdatetimeoffset);
				}
				break;
			case CSharpDataType.@decimal:
				CheckType(dbBind.DecimalThrow, text2, propertyTypeName, propertyName);
				if (text2 == "decimal")
				{
					methodInfo = (isNullable ? getConvertDecimal : getDecimal);
				}
				break;
			case CSharpDataType.@double:
			case CSharpDataType.@float:
				CheckType(dbBind.DoubleThrow, text2, propertyTypeName, propertyName);
				methodInfo = ((!text2.IsIn("double", "single") || !(text != "real")) ? (isNullable ? getConvertFloat : getFloat) : (isNullable ? getConvertDouble : getDouble));
				if ((text.Equals("float", StringComparison.CurrentCultureIgnoreCase) & isNullable) && text2.Equals("single", StringComparison.CurrentCultureIgnoreCase))
				{
					methodInfo = getConvertDoubleToFloat;
				}
				if (underType == UtilConstants.DecType)
				{
					methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
				}
				if (underType == UtilConstants.IntType)
				{
					methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
				}
				if (text2 == "string")
				{
					methodInfo = null;
				}
				break;
			case CSharpDataType.Guid:
				CheckType(dbBind.GuidThrow, text2, propertyTypeName, propertyName);
				if (text2 == "guid")
				{
					methodInfo = (isNullable ? getConvertGuid : getGuid);
				}
				break;
			case CSharpDataType.@byte:
				if (text2 == "byte")
				{
					methodInfo = (isNullable ? getConvertByte : getByte);
				}
				break;
			case CSharpDataType.@enum:
				methodInfo = (isNullable ? getConvertEnum_Null.MakeGenericMethod(underType) : getEnum.MakeGenericMethod(underType));
				break;
			case CSharpDataType.@short:
				CheckType(dbBind.ShortThrow, text2, propertyTypeName, propertyName);
				if (text2 == "int16" || text2 == "short")
				{
					methodInfo = (isNullable ? getConvertInt16 : getInt16);
				}
				break;
			case CSharpDataType.@long:
				if (text2 == "int64" || text2 == "long")
				{
					methodInfo = (isNullable ? getConvertInt64 : getInt64);
				}
				break;
			case CSharpDataType.DateTimeOffset:
				methodInfo = (isNullable ? getConvertdatetimeoffset : getdatetimeoffset);
				if (text2 == "datetime")
				{
					methodInfo = (isNullable ? getConvertdatetimeoffsetDate : getdatetimeoffsetDate);
				}
				break;
			default:
				methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
				break;
			case CSharpDataType.Single:
				break;
			}
			if (methodInfo == null && underType == UtilConstants.StringType)
			{
				methodInfo = getConvertString;
			}
			if (underType == UtilConstants.ObjType)
			{
				methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
			}
			if (methodInfo == null)
			{
				methodInfo = (isNullable ? getOtherNull.MakeGenericMethod(underType) : getOther.MakeGenericMethod(underType));
			}
			if (methodInfo.IsVirtual)
			{
				generator.Emit(OpCodes.Callvirt, methodInfo);
			}
			else
			{
				generator.Emit(OpCodes.Call, methodInfo);
			}
		}

		private void CheckType(List<string> invalidTypes, string bindProperyTypeName, string validPropertyType, string propertyName)
		{
			if (invalidTypes.Contains(bindProperyTypeName))
			{
				throw new SqlSugarException($"{propertyName} can't  convert {validPropertyType} to {bindProperyTypeName}");
			}
		}
	}
	public static class IDataRecordExtensions
	{
		public static Func<object, Type, object> DeserializeObjectFunc { get; internal set; }

		public static T GetDeserializeObject<T>(this IDataReader dr, int i)
		{
			object value = dr.GetValue(i);
			if (value == null)
			{
				return default(T);
			}
			object arg = value;
			return (T)DeserializeObjectFunc(arg, typeof(T));
		}

		public static XElement GetXelement(this IDataRecord dr, int i)
		{
			return XElement.Parse(dr.GetString(i).ToString());
		}

		public static Guid GetStringGuid(this IDataRecord dr, int i)
		{
			return Guid.Parse(dr.GetValue(i).ToString());
		}

		public static Guid? GetConvertStringGuid(this IDataRecord dr, int i)
		{
			if (dr.IsDBNull(i))
			{
				return Guid.Empty;
			}
			return Guid.Parse(dr.GetValue(i).ToString());
		}

		public static bool? GetConvertBoolean(this IDataRecord dr, int i)
		{
			return dr.GetBoolean(i);
		}

		public static byte? GetConvertByte(this IDataRecord dr, int i)
		{
			if (dr.IsDBNull(i))
			{
				return null;
			}
			return dr.GetByte(i);
		}

		public static char? GetConvertChar(this IDataRecord dr, int i)
		{
			if (dr.IsDBNull(i))
			{
				return null;
			}
			return dr.GetChar(i);
		}

		public static DateTime? GetConvertDateTime(this IDataRecord dr, int i)
		{
			DateTime dateTime = dr.GetDateTime(i);
			if (dateTime == DateTime.MinValue)
			{
				return null;
			}
			return dateTime;
		}

		public static DateTime? GetConvertTime(this IDataRecord dr, int i)
		{
