		public static T? GetConvertEnum_Null<T>(this IDataReader dr, int i) where T : struct
		{
			if (dr.IsDBNull(i))
			{
				return null;
			}
			object obj = dr.GetValue(i);
			if (obj != null)
			{
				Type type = obj.GetType();
				if (type.IsIn(UtilConstants.FloatType, UtilConstants.DecType, UtilConstants.DobType))
				{
					obj = ((!(Convert.ToDecimal(obj) < 0m)) ? ((object)Convert.ToUInt32(obj)) : ((object)Convert.ToInt32(obj)));
				}
				else if (type == UtilConstants.StringType)
				{
					return (T)Enum.Parse(typeof(T), obj.ObjToString());
				}
			}
			return (T)Enum.ToObject(typeof(T), obj);
		}

