		public RazorFirst UseRazorAnalysis(string razorClassTemplate, string classNamespace = "Models")
		{
			if (razorClassTemplate == null)
			{
				razorClassTemplate = "";
			}
			razorClassTemplate = razorClassTemplate.Replace("@Model.Namespace", classNamespace);
			RazorFirst razorFirst = new RazorFirst();
			if (Context.CurrentConnectionConfig.ConfigureExternalServices?.RazorService != null)
			{
				List<RazorTableInfo> list = new List<RazorTableInfo>();
				List<DbTableInfo> tableInfoList = TableInfoList;
				if (tableInfoList.HasValue())
				{
					foreach (DbTableInfo item in tableInfoList)
					{
						List<DbColumnInfo> columnInfosByTableName = Context.DbMaintenance.GetColumnInfosByTableName(item.Name, isCache: false);
						RazorTableInfo razorTableInfo = new RazorTableInfo
						{
							Columns = (from it in columnInfosByTableName
								where WhereColumnsfunc == null || WhereColumnsfunc(it.DbColumnName)
								select new RazorColumnInfo
								{
									ColumnDescription = it.ColumnDescription,
									DataType = it.DataType,
									DbColumnName = it.DbColumnName,
									DefaultValue = it.DefaultValue,
									IsIdentity = it.IsIdentity,
									IsNullable = it.IsNullable,
									IsPrimarykey = it.IsPrimarykey,
									Length = it.Length
								}).ToList(),
							Description = item.Description,
							DbTableName = item.Name
						};
						foreach (RazorColumnInfo col in razorTableInfo.Columns)
						{
							col.DataType = GetPropertyTypeName(columnInfosByTableName.First((DbColumnInfo it) => it.DbColumnName == col.DbColumnName));
						}
						list.Add(razorTableInfo);
					}
				}
				razorFirst.ClassStringList = Context.CurrentConnectionConfig.ConfigureExternalServices.RazorService.GetClassStringList(razorClassTemplate, list);
			}
			else
			{
				Check.Exception(true, ErrorMessage.GetThrowMessage("Need to achieve ConnectionConfig.ConfigureExternal Services.RazorService", "需要实现 ConnectionConfig.ConfigureExternal Services.RazorService接口"));
			}
			Context.Utilities.RemoveCacheAll();
			razorFirst.FormatFileNameFunc = FormatFileNameFunc;
			return razorFirst;
		}

