		public Dictionary<string, string> ToClassStringList(string nameSpace = "Models")
		{
			Namespace = nameSpace;
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			if (TableInfoList.HasValue())
			{
				foreach (DbTableInfo tableInfo in TableInfoList)
				{
					try
					{
						string text = null;
						string className = tableInfo.Name;
						string text2 = className;
						text = GetClassString(tableInfo, ref className);
						dictionary.Remove(className);
						if (ReplaceClassStringFunc != null)
						{
							text = ReplaceClassStringFunc(text);
						}
						if (FormatClassNameFunc != null && FormatFileNameFunc != null)
						{
							className = text2;
						}
						dictionary.Add(className, text);
					}
					catch (Exception ex)
					{
						Check.Exception(true, "Table '{0}' error,You can filter it with Db.DbFirst.Where(name=>name!=\"{0}\" ) \r\n Error message:{1}", tableInfo.Name, ex.Message);
					}
				}
			}
			return dictionary;
		}

		internal string GetClassString(DbTableInfo tableInfo, ref string className)
		{
			List<DbColumnInfo> list = Context.DbMaintenance.GetColumnInfosByTableName(tableInfo.Name, isCache: false);
			if (Context.IgnoreColumns.HasValue())
			{
				string entityName = Context.EntityMaintenance.GetEntityName(tableInfo.Name);
				list = list.Where((DbColumnInfo c) => !Context.IgnoreColumns.Any((IgnoreColumn ig) => ig.EntityName.Equals(entityName, StringComparison.CurrentCultureIgnoreCase) && c.DbColumnName == ig.PropertyName)).ToList();
			}
			string text = ClassTemplate;
			string text2 = (IsDefaultValue ? ConstructorTemplate : null);
			if (Context.MappingTables.HasValue())
			{
				MappingTable mappingTable = Context.MappingTables.FirstOrDefault((MappingTable it) => it.DbTableName.Equals(tableInfo.Name, StringComparison.CurrentCultureIgnoreCase));
				if (mappingTable.HasValue())
				{
					className = mappingTable.EntityName;
				}
				if (mappingTable != null)
				{
					text = text.Replace("{ClassName}", mappingTable.EntityName);
				}
			}
			if (FormatClassNameFunc != null)
			{
				className = FormatClassNameFunc(className);
			}
			text = text.Replace("{ClassName}", className);
			text = text.Replace("{Namespace}", Namespace);
			text = text.Replace("{using}", IsAttribute ? (UsingTemplate + "using Snet.DB.sugar;\r\n") : UsingTemplate);
			text = text.Replace("{ClassDescription}", ClassDescriptionTemplate.Replace("{ClassDescription}", tableInfo.Description?.Replace(Environment.NewLine, "\t") + "\r\n"));
			text = text.Replace("{SugarTable}", IsAttribute ? $"\r\n    [SugarTable(\"{tableInfo.Name}\")]" : null);
			if (list.HasValue())
			{
				foreach (DbColumnInfo item in list.Where((DbColumnInfo it) => WhereColumnsfunc == null || WhereColumnsfunc(it.DbColumnName)))
				{
					bool flag = list.Last() == item;
					int num = list.IndexOf(item);
					string propertyTemplate = PropertyTemplate;
					string propertyDescriptionTemplate = PropertyDescriptionTemplate;
					string text3 = GetPropertyName(item);
					string text4 = text3;
					if (FormatPropertyNameFunc != null)
					{
						text3 = (item.DbColumnName = FormatPropertyNameFunc(text3));
					}
					string propertyTypeName = GetPropertyTypeName(item);
					propertyTemplate = ((PropertyTextTemplateFunc == null) ? GetPropertyText(item, propertyTemplate) : PropertyTextTemplateFunc(item, PropertyTemplate, propertyTypeName));
					propertyDescriptionTemplate = GetPropertyDescriptionText(item, propertyDescriptionTemplate);
					if (IsAttribute)
					{
						string dataType = item.DataType;
						if (dataType != null && dataType.StartsWith("_") && propertyTemplate.Contains("[]"))
						{
							propertyDescriptionTemplate += "\r\n           [SugarColumn(IsArray=true)]";
							goto IL_038a;
						}
					}
					if (item != null && item.DataType?.StartsWith("json") == true)
					{
						propertyDescriptionTemplate += "\r\n           [SugarColumn(IsJson=true)]";
					}
					else if (FormatPropertyNameFunc != null)
					{
						if (propertyTemplate.Contains("SugarColumn"))
						{
							propertyTemplate = propertyTemplate.Replace(")]", ",ColumnName=\"" + text4 + "\")]");
						}
						else
						{
							propertyDescriptionTemplate = propertyDescriptionTemplate + "\r\n           [SugarColumn(ColumnName=\"" + text4 + "\")]";
						}
					}
					goto IL_038a;
					IL_038a:
					propertyTemplate = propertyDescriptionTemplate + propertyTemplate;
					text = text.Replace("{PropertyName}", propertyTemplate + (flag ? "" : "\r\n{PropertyName}"));
					if (text2.HasValue() && item.DefaultValue != null && !item.IsIdentity)
					{
						bool flag2 = list.Skip(num + 1).Any((DbColumnInfo it) => it.DefaultValue.HasValue());
						if (item.DefaultValue.EqualCase("CURRENT_TIMESTAMP"))
						{
							item.DefaultValue = "DateTime.Now";
						}
						else if (item.DefaultValue == "b'1'")
						{
							item.DefaultValue = "1";
						}
						text2 = text2.Replace("{PropertyName}", text3);
						text2 = text2.Replace("{DefaultValue}", GetPropertyTypeConvert(item)) + ((!flag2) ? "" : ConstructorTemplate);
					}
				}
			}
			if (!list.Any((DbColumnInfo it) => it.DefaultValue != null && !it.IsIdentity))
			{
				text2 = null;
			}
			text = text.Replace("{Constructor}", text2);
			return text.Replace("{PropertyName}", null);
		}

		internal string GetClassString(List<DbColumnInfo> columns, ref string className)
		{
			string classTemplate = ClassTemplate;
			string text = (IsDefaultValue ? ConstructorTemplate : null);
			classTemplate = classTemplate.Replace("{ClassName}", className);
			classTemplate = classTemplate.Replace("{Namespace}", Namespace);
			classTemplate = classTemplate.Replace("{using}", IsAttribute ? (UsingTemplate + "using Snet.DB.sugar;\r\n") : UsingTemplate);
			classTemplate = classTemplate.Replace("{ClassDescription}", ClassDescriptionTemplate.Replace("{ClassDescription}", "\r\n"));
			classTemplate = classTemplate.Replace("{SugarTable}", IsAttribute ? $"\r\n    [SugarTable(\"{className}\")]" : null);
			if (columns.HasValue())
			{
				foreach (DbColumnInfo column in columns)
				{
					bool flag = columns.Last() == column;
					int num = columns.IndexOf(column);
					string propertyTemplate = PropertyTemplate;
					string propertyDescriptionTemplate = PropertyDescriptionTemplate;
					string propertyName = GetPropertyName(column);
					_ = column.PropertyName;
					propertyTemplate = GetPropertyText(column, propertyTemplate);
					propertyDescriptionTemplate = GetPropertyDescriptionText(column, propertyDescriptionTemplate);
					propertyTemplate = propertyDescriptionTemplate + propertyTemplate;
					classTemplate = classTemplate.Replace("{PropertyName}", propertyTemplate + (flag ? "" : "\r\n{PropertyName}"));
					if (text.HasValue() && column.DefaultValue != null)
					{
						bool flag2 = columns.Skip(num + 1).Any((DbColumnInfo it) => it.DefaultValue.HasValue());
						text = text.Replace("{PropertyName}", propertyName);
						text = text.Replace("{DefaultValue}", GetPropertyTypeConvert(column)) + ((!flag2) ? "" : ConstructorTemplate);
					}
				}
			}
			if (!columns.Any((DbColumnInfo it) => it.DefaultValue != null))
			{
				text = null;
			}
			classTemplate = classTemplate.Replace("{Constructor}", text);
			return classTemplate.Replace("{PropertyName}", null);
		}

		public void CreateClassFile(string directoryPath, string nameSpace = "Models")
		{
			string text = Path.DirectorySeparatorChar.ToString();
			Check.ArgumentNullException(directoryPath, "directoryPath can't null");
			Dictionary<string, string> dictionary = ToClassStringList(nameSpace);
			if (!dictionary.IsValuable())
			{
				return;
			}
			foreach (KeyValuePair<string, string> item in dictionary)
			{
				string text2 = item.Key;
				if (FormatFileNameFunc != null)
				{
					text2 = FormatFileNameFunc(text2);
				}
				FileHelper.CreateFile(directoryPath.TrimEnd('\\').TrimEnd('/') + string.Format(text + "{0}.cs", text2), item.Value, Encoding.UTF8);
			}
		}

		private string GetProertypeDefaultValue(DbColumnInfo item)
		{
			string text = item.DefaultValue;
			if (text == null)
			{
				return null;
			}
			if (Regex.IsMatch(text, "^\\(\\'(.+)\\'\\)$"))
			{
				text = Regex.Match(text, "^\\(\\'(.+)\\'\\)$").Groups[1].Value;
			}
			if (Regex.IsMatch(text, "^\\(\\((.+)\\)\\)$"))
			{
				text = Regex.Match(text, "^\\(\\((.+)\\)\\)$").Groups[1].Value;
			}
			if (Regex.IsMatch(text, "^\\((.+)\\)$"))
			{
				text = Regex.Match(text, "^\\((.+)\\)$").Groups[1].Value;
			}
			if (text.Equals(SqlBuilder.SqlDateNow, StringComparison.CurrentCultureIgnoreCase))
			{
				text = "DateTime.Now";
			}
			if (text.Equals("getdate()", StringComparison.CurrentCultureIgnoreCase))
			{
				text = "DateTime.Now";
			}
			if (text.Equals("getutcdate()", StringComparison.CurrentCultureIgnoreCase))
			{
				text = "DateTime.Now";
			}
			if (text.Equals("NOW()", StringComparison.CurrentCultureIgnoreCase))
			{
				text = "DateTime.Now";
			}
			text = text.Replace("\r", "\t").Replace("\n", "\t");
			return text.IsIn("''", "\"\"") ? string.Empty : text;
		}

		private string GetPropertyText(DbColumnInfo item, string PropertyText)
		{
			string format = "\r\n           [SugarColumn({0})]";
			string propertyName = GetPropertyName(item);
			bool flag = propertyName != item.DbColumnName;
			if (((item.IsPrimarykey || item.IsIdentity) | flag) && IsAttribute)
			{
				List<string> list = new List<string>();
				if (item.IsPrimarykey)
				{
					list.Add("IsPrimaryKey=true");
				}
				if (item.IsIdentity)
				{
					list.Add("IsIdentity=true");
				}
				if (flag)
				{
					list.Add("ColumnName=\"" + item.DbColumnName + "\"");
				}
				format = string.Format(format, string.Join(",", list));
			}
			else
			{
				format = null;
			}
			string propertyTypeName = GetPropertyTypeName(item);
			PropertyText = PropertyText.Replace("{SugarColumn}", format);
			PropertyText = PropertyText.Replace("{PropertyType}", propertyTypeName);
			PropertyText = PropertyText.Replace("{PropertyName}", propertyName);
			if (propertyTypeName == "string" && IsStringNullable && !item.IsNullable && PropertyText.EndsWith("{get;set;}\r\n"))
			{
				PropertyText = PropertyText.Replace("{get;set;}\r\n", "{get;set;} = null!;\r\n");
			}
			return PropertyText;
		}

		private string GetEnityName(DbColumnInfo item)
		{
			MappingTable mappingTable = Context.MappingTables.FirstOrDefault((MappingTable it) => it.DbTableName.Equals(item.TableName, StringComparison.CurrentCultureIgnoreCase));
			if (mappingTable != null)
			{
				return mappingTable.EntityName;
			}
			return item.TableName;
		}

		private string GetPropertyName(DbColumnInfo item)
		{
			if (Context.MappingColumns.HasValue())
			{
				MappingColumn mappingColumn = Context.MappingColumns.SingleOrDefault((MappingColumn it) => it.DbColumnName == item.DbColumnName && it.EntityName == GetEnityName(item));
				if (mappingColumn != null)
				{
					return mappingColumn.PropertyName;
				}
				return item.DbColumnName;
			}
			return item.DbColumnName;
		}

		protected virtual string GetPropertyTypeName(DbColumnInfo item)
		{
			string text = ((item.PropertyType != null) ? item.PropertyType.Name : Context.Ado.DbBind.GetPropertyTypeName(item.DataType));
			if (text != "string" && text != "byte[]" && text != "object" && item.IsNullable)
			{
				text += "?";
			}
			if (text == "Int32")
			{
				text = (item.IsNullable ? "int?" : "int");
			}
			if (text == "String")
			{
				text = "string";
			}
			if (text == "string" && item.IsNullable && IsStringNullable)
			{
				text += "?";
			}
			if (item.OracleDataType.EqualCase("raw") && item.Length == 16)
			{
				return "Guid";
			}
			if (item.OracleDataType.EqualCase("number") && item.Length == 1 && item.Scale == 0)
			{
				return "bool";
			}
			if (text.EqualCase("char") || text.EqualCase("char?"))
			{
				return "string";
			}
			if (item.DataType == "tinyint unsigned")
			{
				return "short";
			}
			if (item.DataType == "smallint unsigned")
			{
				return "ushort";
			}
			if (item.DataType == "bigint unsigned")
			{
				return "ulong";
			}
			if (item.DataType == "int unsigned")
			{
				return "uint";
			}
			if (item.DataType == "MediumInt")
			{
				return "int";
			}
			if (item.DataType == "MediumInt unsigned")
			{
				return "uint";
			}
			return text;
		}

		private string GetPropertyTypeConvert(DbColumnInfo item)
		{
			string proertypeDefaultValue = GetProertypeDefaultValue(item);
			if (proertypeDefaultValue == "DateTime.Now" || proertypeDefaultValue == null)
			{
				return proertypeDefaultValue;
			}
			if (proertypeDefaultValue.ObjToString() == "newid()")
			{
				return "Guid.NewGuid()";
			}
			string dataType = item.DataType;
			if (dataType != null && dataType.ToString()?.EndsWith("unsigned") == true)
			{
				return proertypeDefaultValue;
			}
			if (item.DataType == "bit")
			{
				return (proertypeDefaultValue == "1" || proertypeDefaultValue.Equals("true", StringComparison.CurrentCultureIgnoreCase)).ToString().ToLower();
			}
			if (proertypeDefaultValue.EqualCase("NULL"))
			{
				return "null";
			}
			string result = Context.Ado.DbBind.GetConvertString(item.DataType) + "(\"" + proertypeDefaultValue + "\")";
			if (SqlBuilder.SqlParameterKeyWord == ":" && !string.IsNullOrEmpty(item.OracleDataType))
			{
				result = Context.Ado.DbBind.GetConvertString(item.OracleDataType) + "(\"" + proertypeDefaultValue + "\")";
			}
			return result;
		}

		private string GetPropertyDescriptionText(DbColumnInfo item, string propertyDescriptionText)
		{
			propertyDescriptionText = propertyDescriptionText.Replace("{PropertyDescription}", GetColumnDescription(item.ColumnDescription));
			propertyDescriptionText = propertyDescriptionText.Replace("{DefaultValue}", GetProertypeDefaultValue(item));
			propertyDescriptionText = propertyDescriptionText.Replace("{IsNullable}", item.IsNullable.ObjToString());
			return propertyDescriptionText;
		}

		private string GetColumnDescription(string columnDescription)
		{
			if (columnDescription == null)
			{
				return columnDescription;
			}
			columnDescription = columnDescription.Replace("\r", "\t");
			columnDescription = columnDescription.Replace("\n", "\t");
			columnDescription = columnDescription.Replace(Environment.NewLine, "\t");
			columnDescription = Regex.Replace(columnDescription, "\t{2,}", "\t");
			return columnDescription;
		}
	}
