	public class RazorFirst
	{
		public static string DefaultRazorClassTemplate = "using System;\r\nusing System.Linq;\r\nusing System.Text;\r\nusing Snet.DB.sugar;\r\nnamespace @Model.Namespace \r\n{\r\n    ///<summary>\r\n    ///\r\n    ///</summary>\r\n    public partial class @Model.ClassName\r\n    {\r\n           public @(Model.ClassName)(){\r\n\r\n\r\n           }\r\n @foreach (var item in @Model.Columns)\r\n   {\r\n      if(item.IsPrimarykey&&item.IsIdentity){\r\n         @:/// <summary>\r\n         @:/// Desc:@item.ColumnDescription\r\n         @:/// Default:@item.DefaultValue\r\n         @:/// Nullable:@item.IsNullable\r\n         @:/// </summary>     \r\n         @:[Snet.DB.sugar.SugarColumn(IsPrimaryKey = true, IsIdentity = true)]      \r\n         @:public @item.DataType @item.DbColumnName {get;set;}\r\n         }\r\n        else if(item.IsPrimarykey)\r\n        {\r\n         @:/// <summary>\r\n         @:/// Desc:@item.ColumnDescription\r\n         @:/// Default:@item.DefaultValue\r\n         @:/// Nullable:@item.IsNullable\r\n         @:/// </summary>    \r\n         @:[Snet.DB.sugar.SugarColumn(IsPrimaryKey = true)]       \r\n         @:public @item.DataType @item.DbColumnName {get;set;}\r\n         } \r\n        else if(item.IsIdentity)\r\n        {\r\n         @:/// <summary>\r\n         @:/// Desc:@item.ColumnDescription\r\n         @:/// Default:@item.DefaultValue\r\n         @:/// Nullable:@item.IsNullable\r\n         @:/// </summary>       \r\n         @:[Snet.DB.sugar.SugarColumn(IsIdentity = true)]    \r\n         @:public @item.DataType @item.DbColumnName {get;set;}\r\n         }\r\n         else\r\n         {\r\n         @:/// <summary>\r\n         @:/// Desc:@item.ColumnDescription\r\n         @:/// Default:@item.DefaultValue\r\n         @:/// Nullable:@item.IsNullable\r\n         @:/// </summary>           \r\n         @:public @item.DataType @item.DbColumnName {get;set;}\r\n         }\r\n       }\r\n\r\n    }\r\n}";

		internal List<KeyValuePair<string, string>> ClassStringList { get; set; }

		internal Func<string, string> FormatFileNameFunc { get; set; }

		public void CreateClassFile(string directoryPath)
		{
			string text = Path.DirectorySeparatorChar.ToString();
			if (!ClassStringList.HasValue())
			{
				return;
			}
			foreach (KeyValuePair<string, string> classString in ClassStringList)
			{
				string text2 = classString.Key;
				if (FormatFileNameFunc != null)
				{
					text2 = FormatFileNameFunc(text2);
				}
				FileHelper.CreateFile(directoryPath.TrimEnd('\\').TrimEnd('/') + string.Format(text + "{0}.cs", text2), classString.Value, Encoding.UTF8);
			}
		}

		public List<KeyValuePair<string, string>> GetClassStringList()
		{
			return ClassStringList;
		}
	}
