		public virtual List<DbTableInfo> GetViewInfoList(bool isCache = true)
		{
			string cacheKey = "DbMaintenanceProvider.GetViewInfoList" + Context.CurrentConnectionConfig.ConfigId;
			cacheKey = GetCacheKey(cacheKey);
			List<DbTableInfo> list = new List<DbTableInfo>();
			list = ((!isCache) ? Context.Ado.SqlQuery<DbTableInfo>(GetViewInfoListSql) : GetListOrCache<DbTableInfo>(cacheKey, GetViewInfoListSql));
