		public List<DbTableInfo> GetTableInfoList(Func<DbType, string, string> getChangeSqlFunc)
		{
			SqlSugarClient sqlSugarClient = Context.CopyNew();
			sqlSugarClient.CurrentConnectionConfig.IsAutoCloseConnection = true;
			sqlSugarClient.Aop.OnExecutingChangeSql = delegate(string sql, SugarParameter[] pars)
			{
				sql = getChangeSqlFunc(Context.CurrentConnectionConfig.DbType, sql);
				return new KeyValuePair<string, SugarParameter[]>(sql, pars);
			};
			return sqlSugarClient.DbMaintenance.GetTableInfoList(isCache: false);
		}

