		public virtual List<DbColumnInfo> GetColumnInfosByTableName(string tableName, bool isCache = true)
		{
			if (string.IsNullOrEmpty(tableName))
			{
				return new List<DbColumnInfo>();
			}
			string cacheKey = "DbMaintenanceProvider.GetColumnInfosByTableName." + SqlBuilder.GetNoTranslationColumnName(tableName).ToLower() + Context.CurrentConnectionConfig.ConfigId;
			cacheKey = GetCacheKey(cacheKey);
			string sql = string.Format(GetColumnInfosByTableNameSql, tableName);
			if (isCache)
			{
				return (from it in GetListOrCache<DbColumnInfo>(cacheKey, sql)
					group it by it.DbColumnName into it
					select it.First()).ToList();
			}
			return (from it in Context.Ado.SqlQuery<DbColumnInfo>(sql)
				group it by it.DbColumnName into it
				select it.First()).ToList();
		}

