		public virtual bool IsAnyTable<T>()
		{
			if (typeof(T).GetCustomAttribute<SplitTableAttribute>() != null)
			{
				List<SplitTableInfo> tables = Context.SplitHelper(typeof(T)).GetTables();
				bool result = false;
				foreach (SplitTableInfo item in tables)
				{
					if (Context.DbMaintenance.IsAnyTable(item.TableName, isCache: false))
					{
						result = true;
						break;
					}
				}
				return result;
			}
			Context.InitMappingInfo<T>();
			return IsAnyTable(Context.EntityMaintenance.GetEntityInfo<T>().DbTableName, isCache: false);
		}

		public virtual bool IsAnyTable(string tableName, bool isCache = true)
		{
			Check.Exception(string.IsNullOrEmpty(tableName), "IsAnyTable tableName is not null");
			tableName = SqlBuilder.GetNoTranslationColumnName(tableName);
			return GetTableInfoList(isCache)?.Any((DbTableInfo it) => it.Name.Equals(tableName, StringComparison.CurrentCultureIgnoreCase)) ?? false;
		}

		public virtual bool IsAnyColumn(string tableName, string columnName, bool isCache = true)
		{
			columnName = SqlBuilder.GetNoTranslationColumnName(columnName);
			tableName = SqlBuilder.GetNoTranslationColumnName(tableName);
			Check.Exception(!IsAnyTable(tableName, isCache), $"Table {tableName} does not exist");
			List<DbColumnInfo> columnInfosByTableName = GetColumnInfosByTableName(tableName, isCache);
			if (columnInfosByTableName.IsNullOrEmpty())
			{
				return false;
			}
			return columnInfosByTableName.Any((DbColumnInfo it) => it.DbColumnName.Equals(columnName, StringComparison.CurrentCultureIgnoreCase));
		}

		public virtual bool IsPrimaryKey(string tableName, string columnName)
		{
			columnName = SqlBuilder.GetNoTranslationColumnName(columnName);
			Check.Exception(!IsAnyTable(tableName), $"Table {tableName} does not exist");
			List<DbColumnInfo> columnInfosByTableName = GetColumnInfosByTableName(tableName);
			if (columnInfosByTableName.IsNullOrEmpty())
			{
				return false;
			}
			return columnInfosByTableName.Any((DbColumnInfo it) => it.IsPrimarykey && it.DbColumnName.Equals(columnName, StringComparison.CurrentCultureIgnoreCase));
		}

		public virtual bool IsPrimaryKey(string tableName, string columnName, bool isCache = true)
		{
			columnName = SqlBuilder.GetNoTranslationColumnName(columnName);
			Check.Exception(!IsAnyTable(tableName, isCache), $"Table {tableName} does not exist");
			List<DbColumnInfo> columnInfosByTableName = GetColumnInfosByTableName(tableName, isCache);
			if (columnInfosByTableName.IsNullOrEmpty())
			{
				return false;
			}
			return columnInfosByTableName.Any((DbColumnInfo it) => it.IsPrimarykey && it.DbColumnName.Equals(columnName, StringComparison.CurrentCultureIgnoreCase));
		}

		public virtual bool IsIdentity(string tableName, string columnName)
		{
			columnName = SqlBuilder.GetNoTranslationColumnName(columnName);
			Check.Exception(!IsAnyTable(tableName), $"Table {tableName} does not exist");
			List<DbColumnInfo> columnInfosByTableName = GetColumnInfosByTableName(tableName);
			if (columnInfosByTableName.IsNullOrEmpty())
			{
				return false;
			}
			return columnInfosByTableName.Any((DbColumnInfo it) => it.IsIdentity = it.DbColumnName.Equals(columnName, StringComparison.CurrentCultureIgnoreCase));
		}

