		public virtual bool AddPrimaryKey(string tableName, string columnName)
		{
			tableName = SqlBuilder.GetTranslationTableName(tableName);
			columnName = SqlBuilder.GetTranslationTableName(columnName);
			string text = "PK_{0}_{1}";
			if (tableName.IsContainsIn(" ", "-"))
			{
				text = SqlBuilder.GetTranslationColumnName(text);
			}
			string sql = string.Format(AddPrimaryKeySql, tableName, string.Format(text, SqlBuilder.GetNoTranslationColumnName(tableName).Replace("-", "_"), SqlBuilder.GetNoTranslationColumnName(columnName)), columnName);
			if ((tableName + columnName).Length > 25)
			{
				SqlSugarProvider context = Context;
				if (context != null && context.CurrentConnectionConfig?.MoreSettings?.MaxParameterNameLength > 0)
				{
					sql = string.Format(AddPrimaryKeySql, tableName, string.Format(text, SqlBuilder.GetNoTranslationColumnName(tableName).GetNonNegativeHashCodeString(), "Id"), columnName);
				}
			}
