		public virtual bool CreateIndex(string tableName, string[] columnNames, bool isUnique = false)
		{
			string text = string.Format(CreateIndexSql, SqlBuilder.GetTranslationTableName(tableName), string.Join(",", columnNames.Select((string it) => SqlBuilder.GetTranslationColumnName(it))), string.Join("_", columnNames) + Context.CurrentConnectionConfig.IndexSuffix, isUnique ? "UNIQUE" : "");
			text = text.Replace("_" + SqlBuilder.SqlTranslationLeft, "_");
			text = text.Replace(SqlBuilder.SqlTranslationRight + "_", "_");
			text = text.Replace(SqlBuilder.SqlTranslationLeft + SqlBuilder.SqlTranslationLeft, SqlBuilder.SqlTranslationLeft);
