		public virtual bool CreateIndex(string tableName, string[] columnNames, string IndexName, bool isUnique = false)
		{
			string text = "";
			if (IndexName.ToLower().Contains("{include:"))
			{
				text = Regex.Match(IndexName, "\\{include\\:.+$").Value;
				IndexName = IndexName.Replace(text, "");
				if (text == null)
				{
					throw new Exception("include format error");
				}
				text = text.Replace("{include:", "").Replace("}", "");
				text = "include(" + text + ")";
			}
			string sql = string.Format("CREATE {3} INDEX {2} ON {0}({1})" + text, SqlBuilder.GetTranslationColumnName(tableName), string.Join(",", columnNames), IndexName, isUnique ? "UNIQUE" : "");
			Context.Ado.ExecuteCommand(sql);
			return true;
		}

