		public virtual bool AddRemark(EntityInfo entity)
		{
			SqlSugarProvider context = Context;
			List<EntityColumnInfo> list = entity.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
			List<DbColumnInfo> source = new List<DbColumnInfo>();
			if (entity.Columns.Any((EntityColumnInfo it) => it.ColumnDescription.HasValue()))
			{
				source = context.DbMaintenance.GetColumnInfosByTableName(entity.DbTableName, isCache: false);
			}
			foreach (EntityColumnInfo item in list)
			{
				if (item.ColumnDescription == null)
				{
					continue;
				}
				if (context.DbMaintenance.IsAnyColumnRemark(item.DbColumnName, item.DbTableName))
				{
					if (!source.Any((DbColumnInfo it) => it.DbColumnName == item.DbColumnName && it.ColumnDescription == item.ColumnDescription))
					{
						context.DbMaintenance.DeleteColumnRemark(item.DbColumnName, item.DbTableName);
						context.DbMaintenance.AddColumnRemark(item.DbColumnName, item.DbTableName, item.ColumnDescription);
					}
				}
				else
				{
					context.DbMaintenance.AddColumnRemark(item.DbColumnName, item.DbTableName, item.ColumnDescription);
				}
			}
			if (entity.TableDescription != null)
			{
				if (context.DbMaintenance.IsAnyTableRemark(entity.DbTableName))
				{
					context.DbMaintenance.DeleteTableRemark(entity.DbTableName);
					context.DbMaintenance.AddTableRemark(entity.DbTableName, entity.TableDescription);
				}
				else
				{
					context.DbMaintenance.AddTableRemark(entity.DbTableName, entity.TableDescription);
				}
			}
			return true;
		}

		public virtual void AddIndex(EntityInfo entityInfo)
		{
			_ = Context;
			List<EntityColumnInfo> source = entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
			List<EntityColumnInfo> list = source.Where((EntityColumnInfo it) => it.IndexGroupNameList.HasValue()).ToList();
			if (list.HasValue())
			{
				foreach (string item in (from it in list.SelectMany((EntityColumnInfo it) => it.IndexGroupNameList)
					group it by it into it
					select it.Key).ToList())
				{
					string[] array = (from it in list
						where it.IndexGroupNameList.Any((string i) => i.Equals(item, StringComparison.CurrentCultureIgnoreCase))
						select it.DbColumnName).ToArray();
					string indexName = string.Format("Index_{0}_{1}" + Context.CurrentConnectionConfig.IndexSuffix, entityInfo.DbTableName, string.Join("_", array));
					if (!IsAnyIndex(indexName))
					{
						CreateIndex(entityInfo.DbTableName, array);
					}
				}
			}
			List<EntityColumnInfo> list2 = source.Where((EntityColumnInfo it) => it.UIndexGroupNameList.HasValue()).ToList();
			if (!list2.HasValue())
			{
				return;
			}
			foreach (string item2 in (from it in list2.SelectMany((EntityColumnInfo it) => it.UIndexGroupNameList)
				group it by it into it
				select it.Key).ToList())
			{
				string[] array2 = (from it in list2
					where it.UIndexGroupNameList.Any((string i) => i.Equals(item2, StringComparison.CurrentCultureIgnoreCase))
					select it.DbColumnName).ToArray();
				string indexName2 = string.Format("Index_{0}_{1}_Unique" + Context.CurrentConnectionConfig.IndexSuffix, entityInfo.DbTableName, string.Join("_", array2));
				if (!IsAnyIndex(indexName2))
				{
					CreateUniqueIndex(entityInfo.DbTableName, array2);
				}
			}
		}

