		public IDeleteable<T> WhereIF(bool isWhere, Expression<Func<T, bool>> expression)
		{
			if (!DeleteBuilder.WhereInfos.Any())
			{
				Check.ExceptionEasy(!StaticConfig.EnableAllWhereIF, "Need to program startup configuration StaticConfig. EnableAllWhereIF = true; Tip: This operation is very risky if there are no conditions it is easy to update the entire table", " 需要程序启动时配置StaticConfig.EnableAllWhereIF=true; 提示：该操作存在很大的风险如果没有条件很容易将整个表全部更新");
			}
			if (isWhere)
			{
				return Where(expression);
			}
			return this;
		}

		public IDeleteable<T> Where(Expression<Func<T, bool>> expression)
		{
			ExpressionResult expressionValue = DeleteBuilder.GetExpressionValue(expression, ResolveExpressType.WhereSingle);
			string text = expressionValue.GetResultString();
			if (expression.ToString().Contains("Subqueryable()"))
			{
				string text2 = EntityInfo.DbTableName;
				if (DeleteBuilder.AsName.HasValue())
				{
					text2 = DeleteBuilder.AsName;
				}
				if (ExpressionTool.GetParameters(expression).First().Type == typeof(T))
				{
					string translationColumnName = SqlBuilder.GetTranslationColumnName(text2);
					text = text.Replace(translationColumnName, "( SELECT * FROM " + translationColumnName + ")  ");
				}
				text = text.Replace(SqlBuilder.GetTranslationColumnName(expression.Parameters.First().Name) + ".", SqlBuilder.GetTranslationTableName(text2) + ".");
			}
			else if (expressionValue.IsNavicate)
			{
				string name = EntityInfo.DbTableName;
				if (DeleteBuilder.AsName.HasValue())
				{
					name = DeleteBuilder.AsName;
				}
				text = text.Replace(expression.Parameters.First().Name + ".", SqlBuilder.GetTranslationTableName(name) + ".");
				text = text.Replace(SqlBuilder.GetTranslationColumnName(expression.Parameters.First().Name) + ".", SqlBuilder.GetTranslationTableName(name) + ".");
			}
			DeleteBuilder.WhereInfos.Add(text);
			return this;
		}

