		public IDeleteable<T> WhereColumns(List<Dictionary<string, object>> list)
		{
			List<IConditionalModel> list2 = new List<IConditionalModel>();
			foreach (Dictionary<string, object> item in list)
			{
				int num = 0;
				List<KeyValuePair<WhereType, ConditionalModel>> list3 = new List<KeyValuePair<WhereType, ConditionalModel>>();
				foreach (string key in item.Keys)
				{
					list3.Add(new KeyValuePair<WhereType, ConditionalModel>((num == 0) ? WhereType.Or : WhereType.And, new ConditionalModel
					{
						FieldName = key,
						ConditionalType = ConditionalType.Equal,
						FieldValue = item[key].ObjToStringNoTrim(),
						CSharpTypeName = ((item[key] == null) ? null : item[key].GetType().Name)
					}));
					num++;
				}
				list2.Add(new ConditionalCollections
				{
					ConditionalList = list3
				});
			}
			return Where(list2);
		}

