		}

		public KeyValuePair<string, List<SugarParameter>> ToSql()
		{
			DeleteBuilder.EntityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			string key = DeleteBuilder.ToSqlString();
			List<SugarParameter> value = ((DeleteBuilder.Parameters == null) ? null : DeleteBuilder.Parameters.ToList());
			RestoreMapping();
			return new KeyValuePair<string, List<SugarParameter>>(key, value);
		}

		private List<string> GetPrimaryKeys()
		{
			if (tempPrimaryKeys.HasValue())
			{
				return tempPrimaryKeys;
			}
			if (Context.IsSystemTablesConfig)
			{
				return Context.DbMaintenance.GetPrimaries(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
			}
			return (from it in EntityInfo.Columns
				where it.IsPrimarykey
				select it.DbColumnName).ToList();
		}

		private void _ExecuteCommand(out string sql, out SugarParameter[] paramters)
		{
			DeleteBuilder.EntityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			sql = DeleteBuilder.ToSqlString();
			paramters = ((DeleteBuilder.Parameters == null) ? null : DeleteBuilder.Parameters.ToArray());
			RestoreMapping();
			AutoRemoveDataCache();
			Before(sql);
		}

		protected virtual List<string> GetIdentityKeys()
		{
			if (Context.IsSystemTablesConfig)
			{
				return Context.DbMaintenance.GetIsIdentities(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
			}
			return (from it in EntityInfo.Columns
				where it.IsIdentity
				select it.DbColumnName).ToList();
		}

		private void RestoreMapping()
		{
			if (IsAs)
			{
				Context.MappingTables = OldMappingTableList;
			}
		}

		private void AutoRemoveDataCache()
		{
			ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
			ConfigureExternalServices configureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
			if (moreSettings != null && moreSettings.IsAutoRemoveDataCache && configureExternalServices != null && configureExternalServices.DataInfoCacheService != null)
			{
				RemoveDataCache();
			}
		}

		protected virtual void After(string sql)
		{
			if (IsEnableDiffLogEvent)
			{
				bool isDisableMasterSlaveSeparation = Context.Ado.IsDisableMasterSlaveSeparation;
				Context.Ado.IsDisableMasterSlaveSeparation = true;
				if (DeleteBuilder.Parameters == null)
				{
					new List<SugarParameter>();
				}
				diffModel.AfterData = null;
				diffModel.Time = Context.Ado.SqlExecutionTime;
				if (Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent != null)
				{
					Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent(diffModel);
				}
				Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
			}
			if (RemoveCacheFunc != null)
			{
				RemoveCacheFunc();
			}
			DataChangesAop(DeleteObjects);
		}

		protected virtual void Before(string sql)
		{
			if (IsEnableDiffLogEvent)
			{
				bool isDisableMasterSlaveSeparation = Context.Ado.IsDisableMasterSlaveSeparation;
				Context.Ado.IsDisableMasterSlaveSeparation = true;
				List<SugarParameter> list = DeleteBuilder.Parameters;
				if (list == null)
				{
					list = new List<SugarParameter>();
				}
				diffModel.BeforeData = GetDiffTable(sql, list);
				diffModel.Sql = sql;
				diffModel.Parameters = list.ToArray();
				Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
			}
		}

		protected virtual List<DiffLogTableInfo> GetDiffTable(string sql, List<SugarParameter> parameters)
		{
			List<DiffLogTableInfo> list = new List<DiffLogTableInfo>();
			string whereString = Regex.Replace(sql, ".* WHERE ", "", RegexOptions.Singleline);
			if (IsExists(sql))
			{
				Match match = Regex.Match(sql, "\\bWHERE\\b\\s*(.*)", RegexOptions.IgnoreCase | RegexOptions.Singleline);
				if (match.Success)
				{
					whereString = match.Groups[1].Value;
				}
			}
			DataTable dataTable = Context.Queryable<T>().AS(DeleteBuilder.AsName).Filter(null, isDisabledGobalFilter: true)
				.Where(whereString)
				.AddParameters(parameters)
				.ToDataTable();
			if (dataTable.Rows != null && dataTable.Rows.Count > 0)
			{
				foreach (DataRow row in dataTable.Rows)
				{
					DiffLogTableInfo diffLogTableInfo = new DiffLogTableInfo();
					diffLogTableInfo.TableDescription = EntityInfo.TableDescription;
					diffLogTableInfo.TableName = EntityInfo.DbTableName;
					diffLogTableInfo.Columns = new List<DiffLogColumnInfo>();
					foreach (DataColumn col in dataTable.Columns)
					{
						EntityColumnInfo entityColumnInfo = EntityInfo.Columns.Where((EntityColumnInfo it) => it.DbColumnName != null).First((EntityColumnInfo it) => it.DbColumnName.Equals(col.ColumnName, StringComparison.CurrentCultureIgnoreCase));
						DiffLogColumnInfo diffLogColumnInfo = new DiffLogColumnInfo();
						diffLogColumnInfo.Value = row[col.ColumnName];
						diffLogColumnInfo.ColumnName = col.ColumnName;
						diffLogColumnInfo.IsPrimaryKey = entityColumnInfo.IsPrimarykey;
						diffLogColumnInfo.ColumnDescription = entityColumnInfo.ColumnDescription;
						diffLogTableInfo.Columns.Add(diffLogColumnInfo);
					}
					list.Add(diffLogTableInfo);
				}
			}
			return list;
		}

		protected virtual void DataAop(object deleteObj)
		{
			Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataExecuting;
			if (deleteObj != null && action != null)
			{
				DataFilterModel arg = new DataFilterModel
				{
					OperationType = DataFilterType.DeleteByObject,
					EntityValue = deleteObj,
					EntityColumnInfo = EntityInfo.Columns.FirstOrDefault()
				};
				action(deleteObj, arg);
			}
		}

		protected virtual void DataChangesAop(List<T> deleteObjs)
		{
			Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataChangesExecuted;
			if (action == null || deleteObjs == null)
			{
				return;
			}
			foreach (T deleteObj in deleteObjs)
			{
				if (deleteObj != null)
				{
					DataFilterModel arg = new DataFilterModel
					{
						OperationType = DataFilterType.DeleteByObject,
						EntityValue = deleteObj,
						EntityColumnInfo = EntityInfo.Columns.FirstOrDefault()
					};
					action(deleteObj, arg);
				}
			}
		}

		private static bool IsExists(string sql)
		{
			return UtilMethods.CountSubstringOccurrences(sql, "WHERE") > 1;
		}
	}
	public class DeleteMethodInfo
	{
