		public int ExecuteCommand()
		{
			if (Context == null)
			{
				return 0;
			}
			object obj = MethodInfo.Invoke(Context, new object[1] { objectValue });
			return (int)obj.GetType().GetMethod("ExecuteCommand").Invoke(obj, new object[0]);
		}

		public async Task<int> ExecuteCommandAsync()
		{
			if (Context == null)
			{
				return 0;
			}
			object obj = MethodInfo.Invoke(Context, new object[1] { objectValue });
			return await (Task<int>)obj.GetType().GetMyMethod("ExecuteCommandAsync", 0).Invoke(obj, new object[0]);
		}

		public CommonMethodInfo AS(string tableName)
		{
			object obj = MethodInfo.Invoke(Context, new object[1] { objectValue });
			object context = obj.GetType().GetMyMethod("AS", 1, typeof(string)).Invoke(obj, new object[1] { tableName });
			return new CommonMethodInfo
			{
				Context = context
			};
		}

		public CommonMethodInfo EnableDiffLogEvent(object businessData = null)
		{
			if (Context == null)
			{
