			}
			object obj = MethodInfo.Invoke(Context, new object[1] { objectValue });
			object context = obj.GetType().GetMyMethod("EnableDiffLogEvent", 1, typeof(object)).Invoke(obj, new object[1] { businessData });
			return new CommonMethodInfo
			{
				Context = context
			};
		}

		public CommonMethodInfo SplitTable()
		{
			object obj = MethodInfo.Invoke(Context, new object[1] { objectValue });
			object context = obj.GetType().GetMyMethod("SplitTable", 0).Invoke(obj, new object[0]);
