		public async Task<int> ExecuteCommandAsync(string LogicFieldName = null, object deleteValue = null, string deleteTimeFieldName = null)
		{
			SqlSugarProvider context = DeleteBuilder.Context;
			int num;
			if (context != null && context.CurrentConnectionConfig?.MoreSettings?.IsAutoDeleteQueryFilter == true)
			{
				SqlSugarProvider context2 = DeleteBuilder.Context;
				num = ((context2 != null && context2.CurrentConnectionConfig?.MoreSettings?.IsAutoUpdateQueryFilter == true) ? 1 : 0);
			}
			else
			{
				num = 0;
			}
			bool isAutoDelFilter = (byte)num != 0;
			if (isAutoDelFilter)
			{
				DeleteBuilder.Context.CurrentConnectionConfig.MoreSettings.IsAutoUpdateQueryFilter = false;
			}
			LogicFieldName = _ExecuteCommand(LogicFieldName, out ISqlSugarClient db, out string where, out List<SugarParameter> pars);
