			Convert(updateable as UpdateableProvider<T>);
			int result = await updateable.Where(where).ExecuteCommandAsync();
			if (isAutoDelFilter)
			{
				DeleteBuilder.Context.CurrentConnectionConfig.MoreSettings.IsAutoUpdateQueryFilter = true;
			}
			return result;
		}

		private void Convert(UpdateableProvider<T> updateable)
		{
			updateable.IsEnableDiffLogEvent = Deleteable.IsEnableDiffLogEvent;
			updateable.diffModel = Deleteable.diffModel;
			updateable.UpdateBuilder.TableWithString = DeleteBuilder.TableWithString;
			updateable.RemoveCacheFunc = Deleteable.RemoveCacheFunc;
		}

		private string _ExecuteCommand(string LogicFieldName, out ISqlSugarClient db, out string where, out List<SugarParameter> pars)
		{
			EntityInfo entityInfo = Deleteable.EntityInfo;
			db = Deleteable.Context;
			List<object> bigDataInValues = DeleteBuilder.BigDataInValues;
			if (bigDataInValues != null && bigDataInValues.Any())
			{
				string text = db.Queryable<T>().Select("1").AS("T")
					.In(DeleteBuilder.BigDataInValues.ToArray())
					.ToSqlString();
				int num = text.IndexOf("  WHERE ");
				string item = text.Substring(num + 7);
				DeleteBuilder.WhereInfos.Add(item);
			}
			Check.ExceptionEasy(DeleteBuilder.GetWhereString == null, "Logical Delete requires a Where condition", "逻辑删除需要加Where条件");
			where = DeleteBuilder.GetWhereString.Substring(5);
			pars = DeleteBuilder.Parameters;
			if (LogicFieldName.IsNullOrEmpty())
			{
				EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase("isdelete") || it.PropertyName.EqualCase("isdeleted") || it.DbColumnName.EqualCase("isdelete") || it.DbColumnName.EqualCase("isdeleted"));
				if (entityColumnInfo != null)
				{
					LogicFieldName = entityColumnInfo.DbColumnName;
				}
			}
			Check.Exception(LogicFieldName == null, ErrorMessage.GetThrowMessage(entityInfo.EntityName + " is not isdelete or isdeleted", entityInfo.EntityName + " 没有IsDelete或者IsDeleted 的属性, 你也可以用 IsLogic().ExecuteCommand(\"列名\")"));
			return LogicFieldName;
		}
	}
	public class SplitTableDeleteByObjectProvider<T> where T : class, new()
	{
		internal class GroupModel
		{
			public string GroupName { get; set; }

			public T Item { get; set; }
		}

		public ISqlSugarClient Context;

		public DeleteableProvider<T> deleteobj;

		public T[] deleteObjects { get; set; }

		public int ExecuteCommand()
		{
			GroupDataList(deleteObjects, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				List<T> deleteObjs = item.Select((GroupModel it) => it.Item).ToList();
				result += Context.Deleteable<T>().Where(deleteObjs).AS(item.Key)
					.ExecuteCommand();
			}
			return result;
		}

		public async Task<int> ExecuteCommandAsync()
		{
			GroupDataList(deleteObjects, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				List<T> deleteObjs = item.Select((GroupModel it) => it.Item).ToList();
				int num = result;
				result = num + await Context.Deleteable<T>().Where(deleteObjs).AS(item.Key)
					.ExecuteCommandAsync();
			}
			return result;
		}

		private void GroupDataList(T[] datas, out List<GroupModel> groupModels, out int result)
		{
			SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
			Check.Exception(customAttribute == null, typeof(T).Name + " need SplitTableAttribute");
			groupModels = new List<GroupModel>();
			ISqlSugarClient context = Context;
			foreach (T val in datas)
			{
				object value = context.SplitHelper<T>().GetValue(customAttribute.SplitType, val);
				string tableName = context.SplitHelper<T>().GetTableName(customAttribute.SplitType, value);
				groupModels.Add(new GroupModel
				{
					GroupName = tableName,
					Item = val
				});
			}
			result = 0;
		}
	}
	public class SplitTableDeleteProvider<T> where T : class, new()
	{
		public ISqlSugarClient Context;

		public DeleteableProvider<T> deleteobj;

		public IEnumerable<SplitTableInfo> Tables { get; set; }

		public int ExecuteCommand()
		{
			if (Context.Ado.Transaction == null)
			{
				try
				{
					Context.Ado.BeginTran();
					int result = _ExecuteCommand();
					Context.Ado.CommitTran();
					return result;
				}
				catch (Exception ex)
				{
					Context.Ado.RollbackTran();
					throw ex;
				}
			}
			return _ExecuteCommand();
		}

		public async Task<int> ExecuteCommandAsync()
		{
			if (Context.Ado.Transaction == null)
			{
				try
				{
					Context.Ado.BeginTran();
					int result = await _ExecuteCommandAsync();
					Context.Ado.CommitTran();
					return result;
				}
				catch (Exception ex)
				{
					Context.Ado.RollbackTran();
					throw ex;
				}
			}
			return await _ExecuteCommandAsync();
		}

		internal int _ExecuteCommand()
		{
			int num = 0;
			KeyValuePair<string, List<SugarParameter>> keyValuePair = deleteobj.ToSql();
			foreach (SplitTableInfo table in Tables)
			{
				KeyValuePair<string, List<SugarParameter>> sqlObj = GetSqlObj(keyValuePair, table.TableName);
				num += Context.Ado.ExecuteCommand(sqlObj.Key, sqlObj.Value);
			}
			return num;
		}

		internal async Task<int> _ExecuteCommandAsync()
		{
			int num = 0;
			KeyValuePair<string, List<SugarParameter>> sqlobj = deleteobj.ToSql();
			foreach (SplitTableInfo table in Tables)
			{
				KeyValuePair<string, List<SugarParameter>> sqlObj = GetSqlObj(sqlobj, table.TableName);
				int num2 = num;
				num = num2 + await Context.Ado.ExecuteCommandAsync(sqlObj.Key, sqlObj.Value);
			}
			return num;
		}

		private KeyValuePair<string, List<SugarParameter>> GetSqlObj(KeyValuePair<string, List<SugarParameter>> keyValuePair, string asName)
		{
			List<SugarParameter> value = new List<SugarParameter>();
			string key = keyValuePair.Key;
			if (keyValuePair.Value != null)
			{
				value = keyValuePair.Value.Select((SugarParameter it) => new SugarParameter(it.ParameterName, it.Value)).ToList();
			}
			return new KeyValuePair<string, List<SugarParameter>>(Regex.Replace(key, deleteobj.EntityInfo.DbTableName, asName, RegexOptions.IgnoreCase), value);
		}
	}
