	public class DynamicProperyBuilder
	{
		private bool IsCache;

		public DynamicBuilder baseBuilder;

		public static DynamicProperyBuilder CopyNew()
		{
			return new DynamicProperyBuilder();
		}

		public DynamicProperyBuilder CreateProperty(string propertyName, Type properyType, SugarColumn column = null, bool isSplitField = false, Navigate navigate = null)
		{
			if (column == null)
			{
				column = new SugarColumn
				{
					ColumnName = propertyName
				};
			}
			PropertyMetadata propertyMetadata = new PropertyMetadata();
			propertyMetadata.Name = propertyName;
			propertyMetadata.Type = properyType;
			propertyMetadata.CustomAttributes = new List<CustomAttributeBuilder> { baseBuilder.GetProperty(column) };
			if (navigate != null)
			{
				propertyMetadata.CustomAttributes.Add(BuildNavigateAttribute(navigate));
			}
			baseBuilder.propertyAttr.Add(propertyMetadata);
			if (isSplitField)
			{
				propertyMetadata.CustomAttributes.Add(baseBuilder.GetSplitFieldAttr(new SplitFieldAttribute()));
			}
			return this;
		}

		public DynamicProperyBuilder WithCache(bool isCache = true)
		{
			IsCache = isCache;
			return this;
		}

		public Type BuilderType()
		{
			if (IsCache)
			{
				string cacheKey = baseBuilder.entityName + string.Join("_", baseBuilder.propertyAttr.Select((PropertyMetadata it) => it.Name + it.Type.Name));
				return new ReflectionInoCacheService().GetOrCreate(cacheKey, () => DynamicBuilderHelper.CreateDynamicClass(baseBuilder.entityName, baseBuilder.propertyAttr, TypeAttributes.Public, baseBuilder.entityAttr, baseBuilder.baseType, baseBuilder.interfaces));
			}
			return DynamicBuilderHelper.CreateDynamicClass(baseBuilder.entityName, baseBuilder.propertyAttr, TypeAttributes.Public, baseBuilder.entityAttr, baseBuilder.baseType, baseBuilder.interfaces);
		}

		public Tuple<Type, Type> BuilderTypes(DynamicProperyBuilder dynamicBuilderB)
		{
			if (IsCache)
			{
				string text = baseBuilder.entityName + string.Join("_", baseBuilder.propertyAttr.Select((PropertyMetadata it) => it.Name + it.Type.Name));
				string text2 = dynamicBuilderB.baseBuilder.entityName + string.Join("_", dynamicBuilderB.baseBuilder.propertyAttr.Select((PropertyMetadata it) => it.Name + it.Type.Name));
				return new ReflectionInoCacheService().GetOrCreate(text + text2, () => GetBuilderTypes(dynamicBuilderB));
			}
			return GetBuilderTypes(dynamicBuilderB);
		}

		private Tuple<Type, Type> GetBuilderTypes(DynamicProperyBuilder dynamicBuilderB)
		{
			TypeBuilder typeBuilder = EmitTool.CreateTypeBuilder(baseBuilder.entityName, TypeAttributes.Public, baseBuilder.baseType, baseBuilder.interfaces);
			TypeBuilder typeBuilder2 = EmitTool.CreateTypeBuilder(dynamicBuilderB.baseBuilder.entityName, TypeAttributes.Public, dynamicBuilderB.baseBuilder.baseType, dynamicBuilderB.baseBuilder.interfaces);
			DynamicBuilderHelper.CreateDynamicClass(typeBuilder, typeBuilder2, baseBuilder.propertyAttr, baseBuilder.entityAttr);
			DynamicBuilderHelper.CreateDynamicClass(typeBuilder2, typeBuilder, dynamicBuilderB.baseBuilder.propertyAttr, dynamicBuilderB.baseBuilder.entityAttr);
			return new Tuple<Type, Type>(typeBuilder2.CreateTypeInfo().AsType(), typeBuilder.CreateTypeInfo().AsType());
		}

		public CustomAttributeBuilder BuildNavigateAttribute(Navigate navigate)
		{
			NavigateType navigatType = navigate.NavigatType;
			string name = navigate.Name;
			string name2 = navigate.Name2;
			string whereSql = navigate.WhereSql;
			Type mappingType = navigate.MappingType;
			string mappingAId = navigate.MappingAId;
			string mappingBId = navigate.MappingBId;
			string[] queryPropertyNames = navigate.QueryPropertyNames;
			ConstructorInfo constructor;
			object[] constructorArgs;
			if (mappingType != null && mappingAId != null && mappingBId != null)
			{
				constructor = typeof(Navigate).GetConstructor(new Type[5]
				{
					typeof(Type),
					typeof(string),
					typeof(string),
					typeof(string),
					typeof(string[])
				});
				constructorArgs = new object[5] { mappingType, mappingAId, mappingBId, whereSql, queryPropertyNames };
			}
			else if (!string.IsNullOrEmpty(whereSql))
			{
				constructor = typeof(Navigate).GetConstructor(new Type[5]
				{
					typeof(NavigateType),
					typeof(string),
					typeof(string),
					typeof(string),
					typeof(string[])
				});
				constructorArgs = new object[5] { navigatType, name, name2, whereSql, queryPropertyNames };
			}
			else if (!string.IsNullOrEmpty(name2))
			{
				constructor = typeof(Navigate).GetConstructor(new Type[4]
				{
					typeof(NavigateType),
					typeof(string),
					typeof(string),
					typeof(string[])
				});
				constructorArgs = new object[4] { navigatType, name, name2, queryPropertyNames };
			}
			else
			{
				constructor = typeof(Navigate).GetConstructor(new Type[3]
				{
					typeof(NavigateType),
					typeof(string),
					typeof(string[])
				});
				constructorArgs = new object[3] { navigatType, name, queryPropertyNames };
			}
			return new CustomAttributeBuilder(constructor, constructorArgs);
		}
	}
	internal class EmitTool
	{
		internal static ModuleBuilder CreateModuleBuilder()
		{
			return CreateAssembly().DefineDynamicModule("DynamicModule");
		}

		internal static AssemblyBuilder CreateAssembly()
		{
			return AssemblyBuilder.DefineDynamicAssembly(new AssemblyName($"DynamicAssembly_{Guid.NewGuid():N}"), AssemblyBuilderAccess.RunAndCollect);
		}

		internal static TypeBuilder CreateTypeBuilder(string className, TypeAttributes attributes, Type baseType, Type[] interfaces)
		{
			return CreateModuleBuilder().DefineType(className, attributes, baseType, interfaces);
		}

		internal static PropertyBuilder CreateProperty(TypeBuilder typeBuilder, string propertyName, Type propertyType, IEnumerable<CustomAttributeBuilder> propertyCustomAttributes = null)
		{
			FieldBuilder field = typeBuilder.DefineField("_" + propertyName, propertyType, FieldAttributes.Private);
			PropertyBuilder propertyBuilder = typeBuilder.DefineProperty(propertyName, PropertyAttributes.None, propertyType, null);
			MethodBuilder methodBuilder = typeBuilder.DefineMethod("get_" + propertyName, MethodAttributes.Public | MethodAttributes.HideBySig | MethodAttributes.SpecialName, propertyType, Type.EmptyTypes);
			ILGenerator iLGenerator = methodBuilder.GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldarg_0);
			iLGenerator.Emit(OpCodes.Ldfld, field);
			iLGenerator.Emit(OpCodes.Ret);
			MethodBuilder methodBuilder2 = typeBuilder.DefineMethod("set_" + propertyName, MethodAttributes.Public | MethodAttributes.HideBySig | MethodAttributes.SpecialName, null, new Type[1] { propertyType });
			ILGenerator iLGenerator2 = methodBuilder2.GetILGenerator();
			iLGenerator2.Emit(OpCodes.Ldarg_0);
			iLGenerator2.Emit(OpCodes.Ldarg_1);
			iLGenerator2.Emit(OpCodes.Stfld, field);
			iLGenerator2.Emit(OpCodes.Ret);
			propertyBuilder.SetGetMethod(methodBuilder);
			propertyBuilder.SetSetMethod(methodBuilder2);
			if (propertyCustomAttributes != null)
			{
				foreach (CustomAttributeBuilder propertyCustomAttribute in propertyCustomAttributes)
				{
					propertyBuilder.SetCustomAttribute(propertyCustomAttribute);
				}
			}
			return propertyBuilder;
		}
	}
