				typeFromHandle.GetProperty("IsOwnsOne"),
				typeFromHandle.GetProperty("InsertServerTime"),
				typeFromHandle.GetProperty("UpdateServerTime"),
				typeFromHandle.GetProperty("QuerySql"),
				typeFromHandle.GetProperty("CreateTableFieldSort")
			}, new object[27]
			{
				sugarTable.IsPrimaryKey, sugarTable.IsIdentity, sugarTable.DefaultValue, sugarTable.Length, sugarTable.DecimalDigits, sugarTable.ColumnDataType, sugarTable.IsNullable, sugarTable.ColumnDescription, sugarTable.OracleSequenceName, sugarTable.IsIgnore,
				sugarTable.IsJson, sugarTable.IsOnlyIgnoreInsert, sugarTable.IsOnlyIgnoreUpdate, sugarTable.OldColumnName, sugarTable.SqlParameterDbType, sugarTable.SqlParameterSize, sugarTable.IsArray, sugarTable.ColumnName, sugarTable.InsertSql, sugarTable.UpdateSql,
				sugarTable.ExtendedAttribute, sugarTable.IsDisabledAlterColumn, sugarTable.IsOwnsOne, sugarTable.InsertServerTime, sugarTable.UpdateServerTime, sugarTable.QuerySql, sugarTable.CreateTableFieldSort
			});
