	public class EntityMaintenance
	{
		public SqlSugarProvider Context { get; set; }

		public EntityInfo GetEntityInfo<T>()
		{
			return GetEntityInfo(typeof(T));
		}

		public EntityInfo GetEntityInfoWithAttr(Type type)
		{
			return GetEntityInfo(type);
		}

		public EntityInfo GetEntityInfo(Type type)
		{
			TenantAttribute tenantAttribute = type?.GetCustomAttribute<TenantAttribute>();
			if (tenantAttribute == null)
			{
				return _GetEntityInfo(type);
			}
			if (tenantAttribute.configId.ObjToString() == ((Context?.CurrentConnectionConfig?.ConfigId)?.ToString() ?? ""))
			{
				return _GetEntityInfo(type);
			}
			if (Context.Root == null)
			{
				return _GetEntityInfo(type);
			}
			if (!Context.Root.IsAnyConnection(tenantAttribute.configId))
			{
				return _GetEntityInfo(type);
			}
			return Context.Root.GetConnection(tenantAttribute.configId).EntityMaintenance._GetEntityInfo(type);
		}

		private EntityInfo _GetEntityInfo(Type type)
		{
			string cacheKey = "GetEntityInfo" + type.GetHashCode() + type.FullName + Context?.CurrentConnectionConfig?.ConfigId;
			return Context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => GetEntityInfoNoCache(type));
		}

		public EntityInfo GetEntityInfoNoCache(Type type)
		{
			EntityInfo entityInfo = new EntityInfo();
			object obj = (from it in type.GetTypeInfo().GetCustomAttributes(typeof(SugarTable), inherit: false)
				where it is SugarTable
				select it).SingleOrDefault();
			if (obj.HasValue())
			{
				SugarTable sugarTable = (SugarTable)obj;
				entityInfo.DbTableName = sugarTable.TableName;
				entityInfo.TableDescription = sugarTable.TableDescription.ToSqlFilter();
				entityInfo.IsDisabledUpdateAll = sugarTable.IsDisabledUpdateAll;
				entityInfo.IsDisabledDelete = sugarTable.IsDisabledDelete;
				entityInfo.IsCreateTableFiledSort = sugarTable.IsCreateTableFiledSort;
				entityInfo.Discrimator = sugarTable.Discrimator;
			}
			IEnumerable<Attribute> customAttributes = type.GetCustomAttributes(typeof(SugarIndexAttribute));
			if (customAttributes != null && customAttributes.Any())
			{
				entityInfo.Indexs = customAttributes.Select((Attribute it) => it as SugarIndexAttribute).ToList();
			}
			if (entityInfo.TableDescription.IsNullOrEmpty())
			{
				entityInfo.TableDescription = GetTableAnnotation(type);
			}
			if (Context.CurrentConnectionConfig.ConfigureExternalServices != null && Context.CurrentConnectionConfig.ConfigureExternalServices.EntityNameService != null)
			{
				if (entityInfo.DbTableName == null)
				{
					entityInfo.DbTableName = type.Name;
				}
				Context.CurrentConnectionConfig.ConfigureExternalServices.EntityNameService(type, entityInfo);
			}
			entityInfo.Type = type;
			entityInfo.EntityName = entityInfo.Type.Name;
			entityInfo.Columns = new List<EntityColumnInfo>();
			SetColumns(entityInfo);
			return entityInfo;
		}

		public string GetTableName<T>()
		{
			return GetTableName(typeof(T));
		}

		public string GetTableName(Type entityType)
		{
			string typeName = entityType.Name;
			if (Context.MappingTables == null || Context.MappingTables.Count == 0 || !Context.MappingTables.Any((MappingTable it) => it.EntityName == typeName))
			{
				EntityInfo entityInfo = GetEntityInfo(entityType);
				if (entityInfo.DbTableName.HasValue())
				{
					return entityInfo.DbTableName;
				}
				return entityInfo.EntityName;
			}
			MappingTable mappingTable = Context.MappingTables.SingleOrDefault((MappingTable it) => it.EntityName == typeName);
			if (mappingTable != null)
			{
				return mappingTable.DbTableName;
			}
			return typeName;
		}

		public string GetTableName(string entityName)
		{
			if (Context.MappingTables == null || Context.MappingTables.Count == 0)
			{
				return entityName;
			}
			MappingTable mappingTable = Context.MappingTables.SingleOrDefault((MappingTable it) => it.EntityName == entityName);
			if (mappingTable != null)
			{
				return mappingTable.DbTableName;
			}
			return entityName;
		}

		public string GetEntityName(string tableName)
		{
			if (Context.MappingTables == null || Context.MappingTables.Count == 0)
			{
				return tableName;
			}
			MappingTable mappingTable = Context.MappingTables.SingleOrDefault((MappingTable it) => it.DbTableName == tableName);
			if (mappingTable != null)
			{
				return mappingTable.EntityName;
			}
			return tableName;
		}

		public string GetEntityName<T>()
		{
			return Context.EntityMaintenance.GetEntityInfo<T>().EntityName;
		}

		public string GetEntityName(Type type)
		{
			return Context.EntityMaintenance.GetEntityInfo(type).EntityName;
		}

		public string GetDbColumnName<T>(string propertyName)
		{
			return GetDbColumnName(propertyName, typeof(T));
		}

		public string GetDbColumnName(string propertyName, Type entityType)
		{
			Check.Exception(!GetEntityInfo(entityType).Columns.Any((EntityColumnInfo it) => it.PropertyName.Equals(propertyName, StringComparison.CurrentCultureIgnoreCase)), "Property " + propertyName + " is Invalid");
			string typeName = entityType.Name;
			if (Context.MappingColumns == null || Context.MappingColumns.Count == 0 || !Context.MappingColumns.Any((MappingColumn it) => it.EntityName == typeName && it.PropertyName == propertyName))
			{
				EntityColumnInfo entityColumnInfo = GetEntityInfo(entityType).Columns.First((EntityColumnInfo it) => it.PropertyName.Equals(propertyName, StringComparison.CurrentCultureIgnoreCase));
				if (entityColumnInfo.DbColumnName.HasValue())
				{
					return entityColumnInfo.DbColumnName;
				}
				return entityColumnInfo.PropertyName;
			}
			MappingColumn mappingColumn = Context.MappingColumns.SingleOrDefault((MappingColumn it) => it.EntityName == typeName && it.PropertyName == propertyName);
			if (mappingColumn != null)
			{
				return mappingColumn.DbColumnName;
			}
			return propertyName;
		}

		public string GetPropertyName<T>(string dbColumnName)
		{
			EntityColumnInfo entityColumnInfo = Context.EntityMaintenance.GetEntityInfo<T>().Columns.FirstOrDefault((EntityColumnInfo it) => it.DbColumnName.EqualCase(dbColumnName));
			if (entityColumnInfo != null)
			{
				return entityColumnInfo.PropertyName;
			}
			string typeName = typeof(T).Name;
			if (Context.MappingColumns == null || Context.MappingColumns.Count == 0)
			{
				return dbColumnName;
			}
			MappingColumn mappingColumn = Context.MappingColumns.SingleOrDefault((MappingColumn it) => it.EntityName == typeName && it.DbColumnName.Equals(dbColumnName, StringComparison.CurrentCultureIgnoreCase));
			if (mappingColumn != null)
			{
				return mappingColumn.PropertyName;
			}
			return dbColumnName;
		}

		public string GetPropertyName(string dbColumnName, Type entityType)
		{
			EntityColumnInfo entityColumnInfo = Context.EntityMaintenance.GetEntityInfo(entityType).Columns.FirstOrDefault((EntityColumnInfo it) => it.DbColumnName.EqualCase(dbColumnName));
			if (entityColumnInfo != null)
			{
				return entityColumnInfo.PropertyName;
			}
			string typeName = entityType.Name;
			if (Context.MappingColumns == null || Context.MappingColumns.Count == 0)
			{
				return dbColumnName;
			}
			MappingColumn mappingColumn = Context.MappingColumns.SingleOrDefault((MappingColumn it) => it.EntityName == typeName && it.DbColumnName.Equals(dbColumnName, StringComparison.CurrentCultureIgnoreCase));
			if (mappingColumn != null)
			{
				return mappingColumn.PropertyName;
			}
			return dbColumnName;
		}

		public PropertyInfo GetProperty<T>(string dbColumnName)
		{
			string propertyName = GetPropertyName<T>(dbColumnName);
			return typeof(T).GetProperties().First((PropertyInfo it) => it.Name == propertyName);
		}

		/// <summary>
		/// Gets the text contents of this XML element node
		/// </summary>
		/// <param name="entityType">entity type</param>
		/// <param name="nodeAttributeName">The value of the name attribute of the XML node</param>
		/// <returns>the text contents of this XML element node</returns>
		public string GetXElementNodeValue(Type entityType, string nodeAttributeName)
		{
			try
			{
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.IsNoReadXmlDescription == true)
				{
					return "";
				}
				if (entityType.Assembly.IsDynamic && entityType.Assembly.FullName.StartsWith("Dynamic"))
				{
					return null;
				}
				if (entityType.Assembly.FullName.StartsWith("System.Linq.Dynamic.Core.DynamicClasses"))
				{
					return null;
				}
				string location = entityType.Assembly.Location;
				if (string.IsNullOrEmpty(location))
				{
					return null;
				}
				FileInfo fileInfo = new FileInfo(location);
				string xmlPath = entityType.Assembly.Location.Replace(fileInfo.Extension, ".xml");
				if (!File.Exists(xmlPath))
				{
					return string.Empty;
				}
				XElement orCreate = new ReflectionInoCacheService().GetOrCreate("EntityXml_" + xmlPath, () => XElement.Load(xmlPath));
				if (orCreate == null)
				{
					return string.Empty;
				}
				XElement xElement = (from ele in orCreate.Element("members").Elements("member")
					where ele.Attribute("name").Value == nodeAttributeName
					select ele).FirstOrDefault();
				if (xElement == null)
				{
					return string.Empty;
				}
				XElement xElement2 = xElement.Element("summary");
				if (xElement2 != null)
				{
					return xElement2.Value.ToSqlFilter().Trim();
				}
				string text = (from it in xElement.Elements()
					where it.Name.ToString().EqualCase("summary")
					select it.Value).FirstOrDefault();
				if (text == null)
				{
					return string.Empty;
				}
				return text.ToSqlFilter().Trim() ?? "";
			}
			catch
			{
				Check.ExceptionEasy("ORM error reading entity class XML, check entity XML or disable reading XML: MoreSettings IsNoReadXmlDescription set to true (same place to set DbType)", "ORM读取实体类的XML出现错误,检查实体XML或者禁用读取XML: MoreSettings里面的IsNoReadXmlDescription设为true （设置DbType的同一个地方）");
				throw;
			}
		}

		/// <summary>
		/// Gets the code annotation for the database table
		/// </summary>
		/// <param name="entityType">entity type</param>
		/// <returns>the code annotation for the database table</returns>
		public string GetTableAnnotation(Type entityType)
		{
			if (!entityType.IsClass())
			{
				return null;
			}
			string xElementNodeValue = GetXElementNodeValue(entityType, "T:" + entityType.FullName);
			if (string.IsNullOrEmpty(xElementNodeValue))
			{
				return null;
			}
			return xElementNodeValue;
		}

		/// <summary>
		/// Gets the code annotation for the field
		/// </summary>
		/// <param name="entityType">entity type</param>
		/// <param name="dbColumnName">column name</param>
		/// <returns>the code annotation for the field</returns>
		public string GetPropertyAnnotation(Type entityType, string dbColumnName)
		{
			if (!entityType.IsClass() || entityType == typeof(object))
			{
				return null;
			}
			string xElementNodeValue = GetXElementNodeValue(entityType, "P:" + entityType.FullName + "." + dbColumnName);
			if (string.IsNullOrEmpty(xElementNodeValue))
			{
				return GetPropertyAnnotation(entityType.BaseType, dbColumnName);
			}
			return xElementNodeValue;
		}

		private void SetColumns(EntityInfo result)
		{
			PropertyInfo[] properties = result.Type.GetProperties();
			foreach (PropertyInfo propertyInfo in properties)
			{
				EntityColumnInfo column = new EntityColumnInfo();
				Attribute customAttribute = propertyInfo.GetCustomAttribute(typeof(Navigate));
				if (customAttribute != null)
				{
					column.IsIgnore = true;
					column.Navigat = customAttribute as Navigate;
				}
				SugarColumn sugarColumn = (from it in propertyInfo.GetCustomAttributes(typeof(SugarColumn), inherit: true)
					where it is SugarColumn
					select (SugarColumn)it).FirstOrDefault();
				column.ExtendedAttribute = sugarColumn?.ExtendedAttribute;
				column.DbTableName = result.DbTableName;
				column.EntityName = result.EntityName;
				column.PropertyName = propertyInfo.Name;
				column.PropertyInfo = propertyInfo;
				column.UnderType = UtilMethods.GetUnderType(column.PropertyInfo.PropertyType);
				if (sugarColumn != null && sugarColumn.IsOwnsOne)
				{
					SetValueObjectColumns(result, propertyInfo, column);
				}
				if (sugarColumn.IsNullOrEmpty())
				{
					column.DbColumnName = propertyInfo.Name;
				}
				else if (!sugarColumn.IsIgnore)
				{
					column.DbColumnName = (sugarColumn.ColumnName.IsNullOrEmpty() ? propertyInfo.Name : sugarColumn.ColumnName);
					column.IsPrimarykey = sugarColumn.IsPrimaryKey;
					column.IsIdentity = sugarColumn.IsIdentity;
					column.ColumnDescription = sugarColumn.ColumnDescription.ToSqlFilter();
					column.IsNullable = sugarColumn.IsNullable;
					column.Length = sugarColumn.Length;
					column.OldDbColumnName = sugarColumn.OldColumnName;
					column.DataType = sugarColumn.ColumnDataType;
					column.DecimalDigits = sugarColumn.DecimalDigits;
					column.OracleSequenceName = sugarColumn.OracleSequenceName;
					column.IsOnlyIgnoreInsert = sugarColumn.IsOnlyIgnoreInsert;
					column.IsEnableUpdateVersionValidation = sugarColumn.IsEnableUpdateVersionValidation;
					column.IsTranscoding = sugarColumn.IsTranscoding;
					column.SerializeDateTimeFormat = sugarColumn.SerializeDateTimeFormat;
					column.IsJson = sugarColumn.IsJson;
					column.NoSerialize = sugarColumn.NoSerialize;
					column.DefaultValue = sugarColumn.DefaultValue;
					column.IndexGroupNameList = sugarColumn.IndexGroupNameList;
					column.UIndexGroupNameList = sugarColumn.UniqueGroupNameList;
					column.IsOnlyIgnoreUpdate = sugarColumn.IsOnlyIgnoreUpdate;
					column.IsArray = sugarColumn.IsArray;
					column.IsTreeKey = sugarColumn.IsTreeKey;
					column.SqlParameterDbType = sugarColumn.SqlParameterDbType;
					column.SqlParameterSize = sugarColumn.SqlParameterSize;
					column.CreateTableFieldSort = sugarColumn.CreateTableFieldSort;
					column.InsertServerTime = sugarColumn.InsertServerTime;
					column.InsertSql = sugarColumn.InsertSql;
					column.UpdateServerTime = sugarColumn.UpdateServerTime;
					column.UpdateSql = sugarColumn.UpdateSql;
					column.IsDisabledAlterColumn = sugarColumn.IsDisabledAlterColumn;
					column.QuerySql = sugarColumn.QuerySql;
					if (sugarColumn.IsJson && string.IsNullOrEmpty(sugarColumn.ColumnDataType))
					{
						if (column.Length > 0)
						{
							column.DataType = "varchar";
						}
						else
						{
							column.DataType = "varchar(4000)";
						}
					}
					else if (typeof(Nvarchar2PropertyConvert).Equals(sugarColumn.SqlParameterDbType) && column.DataType == null)
					{
						column.DataType = "nvarchar2";
						if (column.Length == 0)
						{
							column.Length = 200;
						}
					}
					if (column.IsPrimarykey && column.IsOnlyIgnoreUpdate)
					{
						column.IsOnlyIgnoreUpdate = false;
					}
				}
				else
				{
					column.IsIgnore = true;
					column.NoSerialize = sugarColumn.NoSerialize;
					column.ColumnDescription = sugarColumn.ColumnDescription;
					column.IsJson = sugarColumn.IsJson;
					column.IsArray = sugarColumn.IsArray;
				}
				if (column.ColumnDescription.IsNullOrEmpty())
				{
					column.ColumnDescription = GetPropertyAnnotation(result.Type, column.PropertyName);
				}
				if (Context.MappingColumns.HasValue())
				{
					MappingColumn mappingColumn = Context.MappingColumns.FirstOrDefault((MappingColumn it) => it.EntityName.Equals(result.EntityName, StringComparison.CurrentCultureIgnoreCase) && it.PropertyName == column.PropertyName);
					if (mappingColumn != null)
					{
						column.DbColumnName = mappingColumn.DbColumnName;
					}
				}
				if (Context.IgnoreColumns.HasValue() && Context.IgnoreColumns.FirstOrDefault((IgnoreColumn it) => it.EntityName.Equals(result.EntityName, StringComparison.CurrentCultureIgnoreCase) && it.PropertyName == column.PropertyName) != null)
				{
					column.IsIgnore = true;
				}
				if (Context.CurrentConnectionConfig.ConfigureExternalServices != null && Context.CurrentConnectionConfig.ConfigureExternalServices.EntityService != null && !column.EntityName.ObjToString().StartsWith("<>f__AnonymousType") && column.PropertyInfo?.ReflectedType != typeof(DbTableInfo))
				{
					bool isOwnsOne = column.IsOwnsOne;
					Context.CurrentConnectionConfig.ConfigureExternalServices.EntityService(propertyInfo, column);
					if (column.IsOwnsOne && !isOwnsOne)
					{
						SetValueObjectColumns(result, propertyInfo, column);
						continue;
					}
				}
				if (column.PropertyInfo.DeclaringType != null && column.PropertyInfo.DeclaringType != result.Type && result.Columns.Any((EntityColumnInfo x) => x.PropertyName == column.PropertyName))
				{
					continue;
				}
				if (column.DataType == null && propertyInfo != null && propertyInfo.PropertyType.Name.IsIn("TimeOnly"))
				{
					column.DataType = "time";
				}
				if (column.DataType == null && propertyInfo != null && propertyInfo.PropertyType.Name.IsIn("DateOnly"))
				{
					column.DataType = "date";
				}
				if (column.DataType == null && column.UnderType == typeof(TimeSpan))
				{
					column.DataType = "time";
					column.Length = 0;
					column.DecimalDigits = 0;
				}
				if (column.OracleSequenceName.HasValue())
				{
					ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.EnableOracleIdentity == true)
					{
						column.OracleSequenceName = null;
					}
				}
				result.Columns.Add(column);
			}
		}

		private void SetValueObjectColumns(EntityInfo result, PropertyInfo property, EntityColumnInfo column)
		{
			column.IsIgnore = true;
			column.IsOwnsOne = true;
			Check.ExceptionEasy(!property.PropertyType.IsClass(), column.PropertyName + " IsOwnsOne必须用在类上面", column.PropertyName + "IsOwnsOne must be used on the class");
			Check.ExceptionEasy(property.PropertyType.FullName.IsCollectionsList(), column.PropertyName + " IsOwnsOne必须用在类上面", column.PropertyName + "IsOwnsOne must be used on the class");
			foreach (EntityColumnInfo item in GetEntityInfoNoCache(property.PropertyType).Columns)
			{
				if (result.Columns.Any((EntityColumnInfo it) => it.PropertyName.EqualCase(item.PropertyName) || it.DbColumnName.EqualCase(item.DbColumnName)))
				{
					Check.ExceptionEasy(" " + result.EntityName + " " + item.PropertyName + " 存在重复定义 (IsOwnsOne) ", " " + result.EntityName + " " + item.PropertyName + " Duplicate definition exists (IsOwnsOne)");
				}
				item.ForOwnsOnePropertyInfo = column.PropertyInfo;
				result.Columns.Add(item);
			}
		}
	}
	public class DeleteNavProvider<Root, T> where Root : class, new() where T : class, new()
	{
		internal DeleteNavOptions deleteNavOptions;

		public List<string> _WhereList = new List<string>();

		public List<SugarParameter> _Parameters = new List<SugarParameter>();

		public List<Root> _Roots { get; set; }

		public List<object> _ParentList { get; set; }

		public List<object> _RootList { get; set; }

		public EntityInfo _ParentEntity { get; set; }

		public EntityColumnInfo _ParentPkColumn { get; set; }

		public SqlSugarProvider _Context { get; set; }

		internal DeleteNavRootOptions _RootOptions { get; set; }

		public bool _IsDeletedParant { get; set; }

		private void DeleteManyToMany<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<T> parentList = _ParentList.Cast<T>().ToList();
			EntityColumnInfo parentPkColumn = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			EntityColumnInfo parentNavigateProperty = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo thisPkColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			Check.ExceptionEasy(thisPkColumn == null, thisPkColumn.EntityName + " need primary key", thisPkColumn.EntityName + "需要主键");
			Check.ExceptionEasy(parentPkColumn == null, parentPkColumn.EntityName + " need primary key", parentPkColumn.EntityName + "需要主键");
			Type mappingType = parentNavigateProperty.Navigat.MappingType;
			EntityInfo mappingEntity = _Context.EntityMaintenance.GetEntityInfo(mappingType);
			EntityColumnInfo mappingA = mappingEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == parentNavigateProperty.Navigat.MappingAId);
			EntityColumnInfo mappingB = mappingEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == parentNavigateProperty.Navigat.MappingBId);
			Check.ExceptionEasy(mappingA == null || mappingB == null, "Navigate property " + name + " error ", "导航属性" + name + "配置错误");
			(from it in mappingEntity.Columns
				where it.PropertyName != mappingA.PropertyName
				where it.PropertyName != mappingB.PropertyName
				where it.IsPrimarykey && !it.IsIdentity && it.OracleSequenceName.IsNullOrEmpty()
				select it).FirstOrDefault();
			if (IsDeleteA() && !_IsDeletedParant)
			{
				SetContext(delegate
				{
					_Context.Deleteable(parentList).EnableDiffLogEventIF(_RootOptions?.IsDiffLogEvent ?? false, _RootOptions?.DiffLogBizData).ExecuteCommand();
				});
			}
			List<object> aids = _ParentList.Select((object it) => parentPkColumn.PropertyInfo.GetValue(it)).ToList();
			List<object> bids = (from DataRow it in _Context.Queryable<object>().Filter(mappingEntity.Type).AS(mappingEntity.DbTableName)
					.In(mappingA.DbColumnName, aids)
					.Select(mappingB.DbColumnName)
					.ToDataTable()
					.Rows
				select it[0]).ToList();
			List<TChild> childList = GetChildList<TChild>().In(thisPkColumn.DbColumnName, bids).ToList();
			if (_WhereList.HasValue())
			{
				bids = childList.Select((TChild it) => thisPkColumn.PropertyInfo.GetValue(it)).ToList();
			}
			if (IsDeleteB())
			{
				SetContext(delegate
				{
					_Context.Deleteable(childList).ExecuteCommand();
				});
			}
			_ParentList = childList.Cast<object>().ToList();
			_ParentPkColumn = thisPkColumn;
			_IsDeletedParant = true;
			if (_WhereList.HasValue())
			{
				SetContext(delegate
				{
					_Context.Deleteable<object>().AS(mappingEntity.DbTableName).In(mappingA.DbColumnName, aids)
						.In(mappingB.DbColumnName, bids)
						.ExecuteCommand();
				});
			}
			else
			{
				SetContext(delegate
				{
					_Context.Deleteable<object>().AS(mappingEntity.DbTableName).In(mappingA.DbColumnName, aids)
						.ExecuteCommand();
				});
			}
		}

		private bool IsDeleteA()
		{
			if (deleteNavOptions != null)
			{
				return deleteNavOptions.ManyToManyIsDeleteA;
			}
			return false;
		}

		private bool IsDeleteB()
		{
			if (deleteNavOptions != null)
			{
				return deleteNavOptions.ManyToManyIsDeleteB;
			}
			return false;
		}

		private void DeleteOneToMany<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<T> prentList = _ParentList.Cast<T>().ToList();
			parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo pkColumnByNav = GetPkColumnByNav(entityInfo, nav);
			EntityColumnInfo fKColumnByNav = GetFKColumnByNav(entityInfo, nav);
			EntityColumnInfo parentPkColumn = GetParentPkColumn();
			EntityColumnInfo parentPkNavColumn = GetParentPkNavColumn(nav);
			if (parentPkNavColumn != null)
			{
				parentPkColumn = parentPkNavColumn;
			}
			if (!_IsDeletedParant)
			{
				SetContext(delegate
				{
					_Context.Deleteable(prentList).EnableDiffLogEventIF(_RootOptions?.IsDiffLogEvent ?? false, _RootOptions?.DiffLogBizData).ExecuteCommand();
				});
			}
			List<object> inValues = _ParentList.Select((object it) => parentPkColumn.PropertyInfo.GetValue(it)).ToList();
			List<TChild> childList = GetChildList<TChild>().In(fKColumnByNav.DbColumnName, inValues).ToList();
			_ParentList = childList.Cast<object>().ToList();
			_ParentPkColumn = pkColumnByNav;
			_IsDeletedParant = true;
			SetContext(delegate
			{
				_Context.Deleteable(childList).ExecuteCommand();
			});
		}

		private ISugarQueryable<TChild> GetChildList<TChild>() where TChild : class, new()
		{
			ISugarQueryable<TChild> sugarQueryable = _Context.Queryable<TChild>();
			if (_WhereList.HasValue())
			{
				foreach (string where in _WhereList)
				{
					sugarQueryable.Where(where);
				}
				sugarQueryable.AddParameters(_Parameters);
			}
			return sugarQueryable;
		}

		private void SetContext(Action action)
		{
			string key = "_DeleteNavTask";
			if (_Context.TempItems == null)
			{
				_Context.TempItems = new Dictionary<string, object>();
			}
			if (!_Context.TempItems.ContainsKey(key))
			{
				_Context.TempItems.Add(key, null);
			}
			object obj = _Context.TempItems[key];
			List<Action> list = new List<Action>();
			if (obj != null)
			{
				list = (List<Action>)obj;
			}
			list.Add(action);
			_Context.TempItems[key] = list;
		}

		private EntityColumnInfo GetParentPkColumn()
		{
			EntityColumnInfo result = _ParentPkColumn;
			if (_ParentPkColumn == null)
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey));
				result = entityColumnInfo;
			}
			return result;
		}

		private EntityColumnInfo GetParentPkNavColumn(EntityColumnInfo nav)
		{
			EntityColumnInfo result = null;
			if (nav.Navigat.Name2.HasValue())
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name2));
				result = entityColumnInfo;
			}
			return result;
		}

		private EntityColumnInfo GetPkColumnByNav(EntityInfo entity, EntityColumnInfo nav)
		{
			EntityColumnInfo result = entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			if (nav.Navigat.Name2.HasValue())
			{
				result = entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name2);
			}
			return result;
		}

		private EntityColumnInfo GetFKColumnByNav(EntityInfo entity, EntityColumnInfo nav)
		{
			return entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
		}

		private void DeleteOneToOne<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<T> parentList = _ParentList.Cast<T>().ToList();
			EntityColumnInfo parentColumn = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
			parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo pkColumnByNav = GetPkColumnByNav(entityInfo, nav);
			Check.Exception(pkColumnByNav == null, $" Navigate {parentEntity.EntityName} : {name} is error ", $"导航实体 {parentEntity.EntityName} 属性 {name} 配置错误");
			if (!_IsDeletedParant)
			{
				SetContext(delegate
				{
					_Context.Deleteable(parentList).EnableDiffLogEventIF(_RootOptions?.IsDiffLogEvent ?? false, _RootOptions?.DiffLogBizData).ExecuteCommand();
				});
			}
			Check.ExceptionEasy(parentColumn == null, "The one-to-one navigation configuration is incorrect", "一对一导航配置错误");
			List<object> inValues = _ParentList.Select((object it) => parentColumn.PropertyInfo.GetValue(it)).ToList();
			List<TChild> childList = _Context.Queryable<TChild>().In(pkColumnByNav.DbColumnName, inValues).ToList();
			_ParentList = childList.Cast<object>().ToList();
			_ParentPkColumn = pkColumnByNav;
			_IsDeletedParant = true;
			SetContext(delegate
			{
				_Context.Deleteable(childList).ExecuteCommand();
			});
		}

		public DeleteNavProvider<Root, TChild> ThenInclude<TChild>(Expression<Func<T, TChild>> expression) where TChild : class, new()
		{
			_Context.InitMappingInfo<TChild>();
			InitParentList();
			GetMamber(expression);
			string name = ExpressionTool.GetMemberName(expression);
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				DeleteOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				DeleteOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				DeleteManyToMany<TChild>(name, entityColumnInfo);
			}
			return GetResult<TChild>();
		}

		public DeleteNavProvider<Root, TChild> ThenInclude<TChild>(Expression<Func<T, List<TChild>>> expression) where TChild : class, new()
		{
			_Context.InitMappingInfo<TChild>();
			InitParentList();
			Expression mamber = GetMamber(expression);
			string name = ExpressionTool.GetMemberName(mamber);
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				DeleteOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				DeleteOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				DeleteManyToMany<TChild>(name, entityColumnInfo);
			}
			return GetResult<TChild>();
		}

		private Expression GetMamber(Expression expression)
		{
			int num = 0;
			Expression expression2 = ExpressionTool.GetLambdaExpressionBody(expression);
			while (expression2 is MethodCallExpression)
			{
				MethodCallExpression methodCallExpression = expression2 as MethodCallExpression;
				ActionMethodCallExpression(methodCallExpression);
				expression2 = methodCallExpression.Arguments[0];
				num++;
				Check.Exception(num > 10000, expression?.ToString() + "  is error");
			}
			return expression2;
		}

		private void ActionMethodCallExpression(MethodCallExpression method)
		{
			QueryBuilder queryBuilder = GetQueryBuilder();
			NavigatManager<T> navigatManager = new NavigatManager<T>
			{
				Context = _Context
			};
			if (!(method.Method.Name == "ToList"))
			{
				if (method.Method.Name == "Where")
				{
					navigatManager.CheckHasRootShortName(method.Arguments[0], method.Arguments[1]);
					Expression expression = method.Arguments[1];
					_WhereList.Add(" " + queryBuilder.GetExpressionValue(expression, ResolveExpressType.WhereSingle).GetString());
				}
				else if (method.Method.Name == "WhereIF" && Expression.Lambda(method.Arguments[1]).Compile().DynamicInvoke()
					.ObjToBool())
				{
					Expression expression2 = method.Arguments[2];
					navigatManager.CheckHasRootShortName(method.Arguments[1], method.Arguments[2]);
					_WhereList.Add(" " + queryBuilder.GetExpressionValue(expression2, ResolveExpressType.WhereSingle).GetString());
				}
			}
			if (queryBuilder.Parameters != null)
			{
				_Parameters.AddRange(queryBuilder.Parameters);
			}
		}

		private QueryBuilder GetQueryBuilder()
		{
			return _Context.Queryable<T>().QueryBuilder;
		}

