		private void InitParentList()
		{
			_ParentEntity = _Context.EntityMaintenance.GetEntityInfo<T>();
			if (_RootList == null)
			{
				List<object> rootList = (_ParentList = _Roots.Cast<object>().ToList());
				_RootList = rootList;
