			return _ThenInclude(expression);
		}

		private InsertNavProvider<Root, TChild> _ThenInclude<TChild>(Expression<Func<T, TChild>> expression) where TChild : class, new()
		{
			string name = ExpressionTool.GetMemberName(expression);
			bool isRoot = false;
			if (_ParentEntity == null)
			{
				_ParentEntity = _Context.EntityMaintenance.GetEntityInfo<Root>();
				IsFirst = true;
				isRoot = true;
			}
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				InitParentList();
				InsertOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				_NavigateType = NavigateType.OneToMany;
				InitParentList();
				InsertOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				InitParentList();
				InsertManyToMany<TChild>(name, entityColumnInfo);
			}
			AddContextInfo(name, isRoot);
			return GetResult<TChild>();
		}

		private InsertNavProvider<Root, TChild> _ThenInclude<TChild>(Expression<Func<T, List<TChild>>> expression) where TChild : class, new()
		{
			string name = ExpressionTool.GetMemberName(expression);
			if (name == null)
			{
				name = ExpressionTool.GetMemberNameByMethod(expression, name);
			}
			bool isRoot = false;
			if (_ParentEntity == null)
			{
				_ParentEntity = _Context.EntityMaintenance.GetEntityInfo<Root>();
				IsFirst = true;
				isRoot = true;
			}
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				InitParentList();
				InsertOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				_NavigateType = NavigateType.OneToMany;
				InitParentList();
				InsertOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				InitParentList();
				InsertManyToMany<TChild>(name, entityColumnInfo);
			}
			AddContextInfo(name, isRoot);
			return GetResult<TChild>();
		}

		private void AddContextInfo(string name, bool isRoot)
		{
			if ((IsNav | isRoot) && NavContext != null && NavContext.Items != null)
			{
				NavContext.Items.Add(new NavContextItem
				{
					Level = 0,
					RootName = name
				});
			}
		}

		private bool NotAny(string name)
		{
			if (IsFirst)
			{
				return true;
			}
			if (NavContext == null)
			{
				return true;
			}
			NavContext navContext = NavContext;
			if (navContext == null)
			{
				return false;
			}
			return navContext.Items?.Any((NavContextItem it) => it.RootName == name) == false;
		}

		private static bool IsDefaultValue(object pvValue)
		{
			return pvValue?.Equals(UtilMethods.GetDefaultValue(pvValue.GetType())) ?? true;
		}

		private void InitParentList()
		{
			if (_RootList == null)
			{
				List<object> rootList = (_ParentList = GetRootList(_Roots).Cast<object>().ToList());
				_RootList = rootList;
			}
			else if (_ParentList == null)
			{
				_ParentList = _RootList;
				EntityColumnInfo parentPkColumn = _Context.EntityMaintenance.GetEntityInfo<T>().Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				_ParentPkColumn = parentPkColumn;
			}
			IsFirst = false;
		}

		private InsertNavProvider<Root, TChild> GetResult<TChild>() where TChild : class, new()
		{
			return new InsertNavProvider<Root, TChild>
			{
				_Context = _Context,
				_ParentEntity = _ParentEntity,
				_ParentList = _ParentList,
				_Roots = _Roots,
				_ParentPkColumn = _ParentPkColumn,
				_RootList = _RootList
			};
		}

		private List<Type> GetRootList<Type>(List<Type> datas) where Type : class, new()
		{
			new List<Type>();
			_Context.InitMappingInfo<Type>();
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<Type>();
			EntityColumnInfo pkColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			InsertDatas(datas, pkColumn);
			_ParentEntity = entityInfo;
			return datas;
		}

		private void InsertIdentity<Type>(List<Type> datas) where Type : class, new()
		{
			foreach (Type data in datas)
			{
				if (IsFirst && _RootOptions != null)
				{
					_Context.Insertable(data).IgnoreColumns(_RootOptions.IgnoreColumns).InsertColumns(_RootOptions.InsertColumns)
						.EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData)
						.ExecuteCommandIdentityIntoEntity();
				}
				else
				{
					_Context.Insertable(data).ExecuteCommandIdentityIntoEntity();
				}
			}
		}

		private EntityColumnInfo GetPkColumnByNav(EntityInfo entity, EntityColumnInfo nav)
		{
			EntityColumnInfo result = entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			if (nav.Navigat.Name2.HasValue())
			{
				result = entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name2);
			}
			return result;
		}

		private EntityColumnInfo GetPkColumnByNav2(EntityInfo entity, EntityColumnInfo nav)
		{
			return entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
		}

		private EntityColumnInfo GetFKColumnByNav(EntityInfo entity, EntityColumnInfo nav)
		{
			return entity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
		}

		private void InsertDatas<TChild>(List<TChild> children, EntityColumnInfo pkColumn, EntityColumnInfo NavColumn = null) where TChild : class, new()
		{
			children = children.Distinct().ToList();
			if (pkColumn == null)
			{
				Check.ExceptionEasy(typeof(TChild).Name + " need primary key ", typeof(TChild).Name + "需要主键");
			}
			StorageableResult<TChild> storageableResult = _Context.Storageable(children).WhereColumns(new string[1] { pkColumn.PropertyName }).GetStorageableResult();
			List<TChild> list = (children = storageableResult.InsertList.Select((StorageableMessage<TChild> it) => it.Item).ToList());
			bool flag = _navOptions != null && _navOptions.OneToManyIfExistsNoInsert;
			if (_NavigateType == NavigateType.OneToMany && !IsFirst && !flag)
			{
				List<TChild> list2 = storageableResult.UpdateList.Select((StorageableMessage<TChild> it) => it.Item).ToList();
				ClearPk(list2, pkColumn);
				list.AddRange(list2);
			}
			else if (_NavigateType == NavigateType.OneToMany && flag)
			{
				children = new List<TChild>();
				children.AddRange(storageableResult.InsertList.Select((StorageableMessage<TChild> it) => it.Item).ToList());
				List<TChild> collection = storageableResult.UpdateList.Select((StorageableMessage<TChild> it) => it.Item).ToList();
				children.AddRange(collection);
			}
			Check.ExceptionEasy(pkColumn == null && NavColumn == null, "The entity is invalid", "实体错误无法使用导航");
			InitData(pkColumn, list);
			_ParentList = children.Cast<object>().ToList();
		}

		private void ClearPk<TChild>(List<TChild> updateData, EntityColumnInfo pkColumn) where TChild : class, new()
		{
			foreach (TChild updateDatum in updateData)
			{
				object value = UtilMethods.DefaultForType(pkColumn.PropertyInfo.PropertyType);
				pkColumn.PropertyInfo.SetValue(updateDatum, value);
			}
		}

		private void InitData<TChild>(EntityColumnInfo pkColumn, List<TChild> insertData) where TChild : class, new()
		{
			if (pkColumn.IsIdentity || pkColumn.OracleSequenceName.HasValue())
			{
				InsertIdentity(insertData);
			}
			else if (pkColumn.UnderType == UtilConstants.LongType)
			{
				SetValue(pkColumn, insertData, () => SnowFlakeSingle.Instance.NextId());
			}
			else if (pkColumn.UnderType == UtilConstants.GuidType)
			{
				SetValue(pkColumn, insertData, () => UtilMethods.NewGuid());
			}
			else if (pkColumn.UnderType == UtilConstants.StringType)
			{
				SetValue(pkColumn, insertData, () => UtilMethods.NewGuid().ToString());
			}
			else
			{
				SetError(pkColumn, insertData);
			}
		}

		private void SetValue<TChild>(EntityColumnInfo pkColumn, List<TChild> insertData, Func<object> value) where TChild : class, new()
		{
			foreach (TChild insertDatum in insertData)
			{
				if (IsDefaultValue(pkColumn.PropertyInfo.GetValue(insertDatum)))
				{
					pkColumn.PropertyInfo.SetValue(insertDatum, value());
				}
			}
			if (IsFirst && _RootOptions != null)
			{
				_Context.Insertable(insertData).IgnoreColumns(_RootOptions.IgnoreColumns).InsertColumns(_RootOptions.InsertColumns)
					.EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData)
					.ExecuteCommand();
			}
			else
			{
				_Context.Insertable(insertData).ExecuteCommand();
			}
		}

		private void SetError<TChild>(EntityColumnInfo pkColumn, List<TChild> insertData) where TChild : class, new()
		{
			foreach (TChild insertDatum in insertData)
			{
				if (IsDefaultValue(pkColumn.PropertyInfo.GetValue(insertDatum)))
				{
					string text = pkColumn.EntityName + " " + pkColumn.DbColumnName;
					Check.ExceptionEasy("The field " + text + " is not an autoassignment type and requires an assignment", "字段" + text + "不是可自动赋值类型需要赋值（并且不能是已存在值） , 可赋值类型有 自增、long、Guid、string");
				}
			}
			if (IsFirst && _RootOptions != null)
			{
				_Context.Insertable(insertData).IgnoreColumns(_RootOptions.IgnoreColumns).InsertColumns(_RootOptions.InsertColumns)
					.EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData)
					.ExecuteCommand();
				return;
			}
			if (_Context.EntityMaintenance.GetEntityInfo(typeof(TChild)).Columns.Any((EntityColumnInfo it) => it.IsIdentity))
			{
				foreach (TChild insertDatum2 in insertData)
				{
					_Context.Insertable(insertDatum2).ExecuteCommandIdentityIntoEntity();
				}
				return;
			}
			_Context.Insertable(insertData).ExecuteCommand();
		}

		private void InsertManyToMany<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<object> parentList = _ParentList;
			EntityColumnInfo entityColumnInfo = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			EntityColumnInfo parentNavigateProperty = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo entityColumnInfo2 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			Check.ExceptionEasy(entityColumnInfo2 == null, entityColumnInfo2.EntityName + " need primary key", entityColumnInfo2.EntityName + "需要主键");
			Check.ExceptionEasy(entityColumnInfo == null, entityColumnInfo.EntityName + " need primary key", entityColumnInfo.EntityName + "需要主键");
			Type mappingType = parentNavigateProperty.Navigat.MappingType;
			EntityInfo entityInfo2 = _Context.EntityMaintenance.GetEntityInfo(mappingType);
			EntityColumnInfo mappingA = entityInfo2.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == parentNavigateProperty.Navigat.MappingAId);
			EntityColumnInfo mappingB = entityInfo2.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == parentNavigateProperty.Navigat.MappingBId);
			Check.ExceptionEasy(mappingA == null || mappingB == null, "Navigate property " + name + " error ", "导航属性" + name + "配置错误");
			EntityColumnInfo entityColumnInfo3 = (from it in entityInfo2.Columns
				where it.PropertyName != mappingA.PropertyName
				where it.PropertyName != mappingB.PropertyName
				where it.IsPrimarykey && !it.IsIdentity && it.OracleSequenceName.IsNullOrEmpty()
				select it).FirstOrDefault();
			IEnumerable<EntityColumnInfo> enumerable = from it in entityInfo2.Columns
				where it.PropertyName != mappingA.PropertyName
				where it.PropertyName != mappingB.PropertyName
				where !it.IsIdentity
				where !it.IsOnlyIgnoreInsert
				where !it.IsIgnore
				where !it.IsPrimarykey
				select it;
			List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
			foreach (object item in parentList)
			{
				object value = parentNavigateProperty.PropertyInfo.GetValue(item);
				if (value == null)
				{
					continue;
				}
				List<TChild> list2 = (List<TChild>)value;
				InsertDatas(list2, entityColumnInfo2);
				object value2 = entityColumnInfo.PropertyInfo.GetValue(item);
				foreach (TChild item2 in list2)
				{
					object value3 = entityColumnInfo2.PropertyInfo.GetValue(item2);
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					dictionary.Add(mappingA.DbColumnName, value2);
					dictionary.Add(mappingB.DbColumnName, value3);
					if (enumerable != null)
					{
						foreach (EntityColumnInfo item3 in enumerable)
						{
							if (!dictionary.ContainsKey(item3.DbColumnName))
							{
								if (item3.UnderType == UtilConstants.DateType)
								{
									dictionary.Add(item3.DbColumnName, DateTime.Now);
								}
								else if (item3.UnderType == UtilConstants.StringType)
								{
									dictionary.Add(item3.DbColumnName, " ");
								}
								else
								{
									dictionary.Add(item3.DbColumnName, UtilMethods.GetDefaultValue(item3.UnderType));
								}
							}
						}
					}
					if (entityColumnInfo3 != null)
					{
						SetMappingTableDefaultValue(entityColumnInfo3, dictionary);
					}
					list.Add(dictionary);
				}
			}
			List<object> primaryKeyValues = list.Select((Dictionary<string, object> x) => x[mappingA.DbColumnName]).ToList();
			if (_navOptions == null || !_navOptions.ManyToManyNoDeleteMap)
			{
				_Context.Deleteable<object>().AS(entityInfo2.DbTableName).In(mappingA.DbColumnName, primaryKeyValues)
					.ExecuteCommand();
			}
			if (HasMappingTemplate(entityInfo2))
			{
				InertMappingWithTemplate(entityInfo2, mappingA, mappingB, list);
			}
			else
			{
				_Context.Insertable(list).AS(entityInfo2.DbTableName).ExecuteCommand();
			}
			SetNewParent<TChild>(entityInfo, entityColumnInfo2);
		}

		private void InertMappingWithTemplate(EntityInfo mappingEntity, EntityColumnInfo mappingA, EntityColumnInfo mappingB, List<Dictionary<string, object>> mappgingTables)
		{
			object obj = _navOptions?.ManyToManySaveMappingTemplate;
			List<object> list = new List<object>();
			foreach (Dictionary<string, object> mappgingTable in mappgingTables)
			{
				object obj2 = JsonConvert.DeserializeObject(JsonConvert.SerializeObject(obj), obj.GetType());
				List<EntityColumnInfo> columns = mappingEntity.Columns;
				foreach (KeyValuePair<string, object> item in mappgingTable)
				{
					string fieldName = item.Key;
					object value = item.Value;
					EntityColumnInfo entityColumnInfo = columns.FirstOrDefault((EntityColumnInfo f) => f.DbColumnName.EqualCase(fieldName));
					if (entityColumnInfo != null && (entityColumnInfo.IsPrimarykey || entityColumnInfo.DbColumnName == mappingA.DbColumnName || entityColumnInfo.DbColumnName == mappingB.DbColumnName))
					{
						entityColumnInfo.PropertyInfo.SetValue(obj2, value);
					}
				}
				list.Add(obj2);
			}
			_Context.InsertableByObject(list).ExecuteCommand();
		}

		private bool HasMappingTemplate(EntityInfo mappingEntity)
		{
			return _navOptions?.ManyToManySaveMappingTemplate?.GetType() == mappingEntity.Type;
		}

		private void SetMappingTableDefaultValue(EntityColumnInfo mappingPk, Dictionary<string, object> keyValuePairs)
		{
			if (mappingPk.UnderType == UtilConstants.LongType)
			{
				keyValuePairs.Add(mappingPk.DbColumnName, SnowFlakeSingle.Instance.NextId());
				return;
			}
			if (mappingPk.UnderType == UtilConstants.GuidType)
			{
				keyValuePairs.Add(mappingPk.DbColumnName, Guid.NewGuid());
				return;
			}
			if (mappingPk.UnderType == UtilConstants.StringType)
			{
				keyValuePairs.Add(mappingPk.DbColumnName, Guid.NewGuid().ToString() ?? "");
				return;
			}
			string text = mappingPk.EntityName + " " + mappingPk.DbColumnName;
			Check.ExceptionEasy("The field " + text + " is not an autoassignment type and requires an assignment", " 中间表主键字段" + text + "不是可自动赋值类型， 可赋值类型有 自增、long、Guid、string。你也可以删掉主键 用双主键");
		}

		private void InsertOneToMany<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			List<TChild> list = new List<TChild>();
			EntityInfo parentEntity = _ParentEntity;
			List<object> parentList = _ParentList;
			EntityColumnInfo entityColumnInfo = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo pkColumnByNav = GetPkColumnByNav2(entityInfo, nav);
			EntityColumnInfo fKColumnByNav = GetFKColumnByNav(entityInfo, nav);
			EntityColumnInfo entityColumnInfo2 = GetParentPkColumn();
			EntityColumnInfo parentPkNavColumn = GetParentPkNavColumn(nav);
			if (parentPkNavColumn != null)
			{
				entityColumnInfo2 = parentPkNavColumn;
			}
			if (ParentIsPk(entityColumnInfo))
			{
				entityColumnInfo2 = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			}
			foreach (object item in parentList)
			{
				object value = entityColumnInfo2.PropertyInfo.GetValue(item);
				List<TChild> list2 = entityColumnInfo.PropertyInfo.GetValue(item) as List<TChild>;
				if (list2 != null)
				{
					foreach (TChild item2 in list2)
					{
						fKColumnByNav.PropertyInfo.SetValue(item2, value, null);
					}
					list.AddRange(list2);
				}
				else if (list2 == null && entityColumnInfo.PropertyInfo.GetValue(item) is IList list3 && list3 != null && list3.Count > 0)
				{
					list2 = GetIChildsBylList(list, fKColumnByNav, value, list3);
				}
			}
			bool isTreeChild = GetIsTreeChild(parentEntity, entityInfo);
			Check.ExceptionEasy(pkColumnByNav == null, entityInfo.EntityName + "need primary key", "实体" + entityInfo.EntityName + "需要主键");
			if (NotAny(name) | isTreeChild)
			{
				InsertDatas(list, pkColumnByNav);
			}
			else
			{
				_ParentList = list.Cast<object>().ToList();
			}
			SetNewParent<TChild>(entityInfo, pkColumnByNav);
		}

		private static List<TChild> GetIChildsBylList<TChild>(List<TChild> children, EntityColumnInfo thisFkColumn, object parentValue, IList ilist) where TChild : class, new()
		{
			List<TChild> list = ilist.Cast<TChild>().ToList();
			foreach (TChild item in list)
			{
				thisFkColumn.PropertyInfo.SetValue(item, parentValue, null);
			}
			children.AddRange(list);
			return list;
		}

		private bool GetIsTreeChild(EntityInfo parentEntity, EntityInfo thisEntity)
		{
			NavContext navContext = NavContext;
			if (navContext != null && navContext.Items?.Any() == true)
			{
				return parentEntity.Type == thisEntity.Type;
			}
			return false;
		}

		private static bool ParentIsPk(EntityColumnInfo parentNavigateProperty)
		{
			if (parentNavigateProperty != null && parentNavigateProperty.Navigat != null && parentNavigateProperty.Navigat.NavigatType == NavigateType.OneToMany)
			{
				return parentNavigateProperty.Navigat.Name2 == null;
			}
			return false;
		}

		private EntityColumnInfo GetParentPkColumn()
		{
			EntityColumnInfo result = _ParentPkColumn;
			if (_ParentPkColumn == null)
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey));
				result = entityColumnInfo;
			}
			return result;
		}

		private EntityColumnInfo GetParentPkNavColumn(EntityColumnInfo nav)
		{
			EntityColumnInfo result = null;
			if (nav.Navigat.Name2.HasValue())
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name2));
				result = entityColumnInfo;
			}
			return result;
		}

		private void SetNewParent<TChild>(EntityInfo entityInfo, EntityColumnInfo entityColumnInfo) where TChild : class, new()
		{
			_ParentEntity = entityInfo;
			_ParentPkColumn = entityColumnInfo;
		}

		private void InsertOneToOne<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<object> parentList = _ParentList;
			EntityColumnInfo entityColumnInfo = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
			EntityColumnInfo entityColumnInfo2 = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			EntityColumnInfo pkColumnByNav = GetPkColumnByNav(entityInfo, nav);
			Check.ExceptionEasy(pkColumnByNav == null, $" Navigate {parentEntity.EntityName} : {name} is error ", $"导航实体 {parentEntity.EntityName} 属性 {name} 配置错误");
			Check.ExceptionEasy(nav.Navigat.WhereSql.HasValue(), " " + name + " Navigate(NavType,WhereSql)  no support insert ", "导航一对一 " + name + " 配置了 Sql变量 不支持插入");
			List<TChild> list = new List<TChild>();
			foreach (object item in parentList)
			{
				object obj = entityColumnInfo.PropertyInfo.GetValue(item);
				TChild val = (TChild)nav.PropertyInfo.GetValue(item);
				if (val == null)
				{
					continue;
				}
				if (IsDefaultValue(obj))
				{
					object value = pkColumnByNav.PropertyInfo.GetValue(val);
					if (IsDefaultValue(obj))
					{
						obj = value;
					}
				}
				if (!IsDefaultValue(obj) && !entityColumnInfo.IsPrimarykey)
				{
					_Context.Updateable<DbTableInfo>().AS(parentEntity.DbTableName).SetColumns(entityColumnInfo.DbColumnName, obj)
						.Where(entityColumnInfo2.DbColumnName, "=", entityColumnInfo2.PropertyInfo.GetValue(item))
						.ExecuteCommand();
				}
				if (IsDefaultValue(obj))
				{
					InsertDatas(new List<TChild> { val }, pkColumnByNav);
					obj = pkColumnByNav.PropertyInfo.GetValue(val);
					entityColumnInfo.PropertyInfo.SetValue(item, obj);
					_Context.Updateable<DbTableInfo>().AS(parentEntity.DbTableName).SetColumns(entityColumnInfo.DbColumnName, obj)
						.Where(entityColumnInfo2.DbColumnName, "=", entityColumnInfo2.PropertyInfo.GetValue(item))
						.ExecuteCommand();
				}
				pkColumnByNav.PropertyInfo.SetValue(val, obj);
				list.Add(val);
			}
			InsertDatas(list, pkColumnByNav);
			_ParentList = list.Cast<object>().ToList();
			SetNewParent<TChild>(entityInfo, pkColumnByNav);
		}
	}
	public class InsertNavTaskInit<Root, T> where Root : class, new() where T : class, new()
	{
		internal SqlSugarProvider Context { get; set; }

		internal InsertNavProvider<Root, Root> insertNavProvider { get; set; }

		internal NavContext NavContext { get; set; }

		public InsertNavMethodInfo IncludeByNameString(string navMemberName, InsertNavOptions insertNavOptions = null)
		{
			InsertNavMethodInfo insertNavMethodInfo = new InsertNavMethodInfo();
			insertNavMethodInfo.Context = insertNavProvider._Context;
			EntityInfo entityInfo = insertNavMethodInfo.Context.EntityMaintenance.GetEntityInfo<T>();
			Expression includeExpression = UtilMethods.GetIncludeExpression(navMemberName, entityInfo, out Type properyItemType, out bool isList);
			object methodInfos = GetType().GetMyMethod("Include", 2, isList).MakeGenericMethod(properyItemType).Invoke(this, new object[2] { includeExpression, insertNavOptions });
			insertNavMethodInfo.MethodInfos = methodInfos;
			return insertNavMethodInfo;
		}

		public InsertNavMethodInfo IncludesAllFirstLayer(params string[] ignoreColumns)
		{
			if (ignoreColumns == null)
			{
				ignoreColumns = new string[0];
			}
			Context = insertNavProvider._Context;
			List<EntityColumnInfo> list = (from it in Context.EntityMaintenance.GetEntityInfo<Root>().Columns
				where !Enumerable.Contains(ignoreColumns, it.PropertyName) || !ignoreColumns.Any((string z) => z.EqualCase(it.DbColumnName))
				where it.Navigat != null
				select it).ToList();
			InsertNavMethodInfo insertNavMethodInfo = IncludeByNameString(list[0].PropertyName);
			foreach (EntityColumnInfo item in list.Skip(1))
			{
				insertNavMethodInfo = insertNavMethodInfo.IncludeByNameString(item.PropertyName);
			}
			return insertNavMethodInfo;
		}

		public InsertNavMethodInfo IncludesAllFirstLayer(InsertNavOptions insertNavOptions, params string[] ignoreColumns)
		{
			if (ignoreColumns == null)
			{
				ignoreColumns = new string[0];
			}
			Context = insertNavProvider._Context;
			List<EntityColumnInfo> list = (from it in Context.EntityMaintenance.GetEntityInfo<Root>().Columns
				where !Enumerable.Contains(ignoreColumns, it.PropertyName) || !ignoreColumns.Any((string z) => z.EqualCase(it.DbColumnName))
				where it.Navigat != null
				select it).ToList();
			InsertNavMethodInfo insertNavMethodInfo = IncludeByNameString(list[0].PropertyName);
			foreach (EntityColumnInfo item in list.Skip(1))
			{
				insertNavMethodInfo = insertNavMethodInfo.IncludeByNameString(item.PropertyName, insertNavOptions);
			}
			return insertNavMethodInfo;
		}

