	public class InsertNavTask<Root, T> where Root : class, new() where T : class, new()
	{
		public SqlSugarProvider Context { get; set; }

		public Func<InsertNavProvider<Root, T>> PreFunc { get; set; }

		internal NavContext NavContext { get; set; }

		public InsertNavTask<Root, TChild> ThenInclude<TChild>(Expression<Func<T, TChild>> expression) where TChild : class, new()
		{
			InsertNavTask<Root, TChild> insertNavTask = new InsertNavTask<Root, TChild>();
			Func<InsertNavProvider<Root, TChild>> preFunc = delegate
			{
				InsertNavProvider<Root, TChild> insertNavProvider = PreFunc().ThenInclude(expression);
				insertNavProvider.NavContext = NavContext;
				return insertNavProvider;
			};
			insertNavTask.PreFunc = preFunc;
			insertNavTask.Context = Context;
			insertNavTask.NavContext = NavContext;
			return insertNavTask;
		}

