		{
			return AsNav().ThenInclude(expression, options);
		}

		public Root ExecuteReturnEntity()
		{
			if (Context.Ado.Transaction != null)
			{
				return (Root)(PreFunc()?._RootList?.FirstOrDefault());
			}
			Root result = null;
			Context.Ado.UseTran(delegate
			{
				result = (Root)(PreFunc()?._RootList?.FirstOrDefault());
			}, delegate(Exception ex)
			{
				throw ex;
			});
			return result;
		}

		public async Task<Root> ExecuteReturnEntityAsync()
		{
			Root result = null;
			await Task.Run(async delegate
			{
				result = ExecuteReturnEntity();
				await Task.Delay(0);
			});
			return result;
		}

		public bool ExecuteCommand()
		{
			if (Context.Ado.Transaction != null)
			{
				PreFunc();
			}
			else
			{
				Context.Ado.UseTran(delegate
				{
					PreFunc();
				}, delegate(Exception ex)
				{
					throw ex;
				});
			}
			return true;
		}

		public async Task<bool> ExecuteCommandAsync()
		{
			await Task.Run(async delegate
			{
				ExecuteCommand();
				await Task.Delay(0);
			});
			return true;
		}

		private InsertNavTask<Root, Root> AsNav()
		{
			InsertNavTask<Root, Root> insertNavTask = new InsertNavTask<Root, Root>();
			Func<InsertNavProvider<Root, Root>> preFunc = delegate
			{
				InsertNavProvider<Root, Root> insertNavProvider = PreFunc().AsNav();
				insertNavProvider.NavContext = NavContext;
				insertNavProvider.IsNav = true;
				return insertNavProvider;
			};
			insertNavTask.PreFunc = preFunc;
			insertNavTask.Context = Context;
			insertNavTask.NavContext = NavContext;
			return insertNavTask;
		}
	}
	internal class NavContext
	{
		public List<NavContextItem> Items { get; set; }
	}
	internal class NavContextItem
	{
		public int Level { get; set; }

