		private static List<TChild> GetIChildsBylList<TChild>(List<TChild> children, EntityColumnInfo thisFkColumn, object parentValue, IList ilist) where TChild : class, new()
		{
			List<TChild> list = ilist.Cast<TChild>().ToList();
			foreach (TChild item in list)
			{
				thisFkColumn.PropertyInfo.SetValue(item, parentValue, null);
			}
			children.AddRange(list);
			return list;
		}

		private static bool ParentIsPk(EntityColumnInfo parentNavigateProperty)
		{
			if (parentNavigateProperty != null && parentNavigateProperty.Navigat != null && parentNavigateProperty.Navigat.NavigatType == NavigateType.OneToMany)
			{
				return parentNavigateProperty.Navigat.Name2 == null;
			}
			return false;
		}

		private void DeleteMany(EntityInfo thisEntity, List<object> ids, string fkName)
		{
			if (_Options == null || !_Options.OneToManyDeleteAll)
			{
				return;
			}
			foreach (EntityColumnInfo item in thisEntity.Columns.Where((EntityColumnInfo it) => it.Navigat != null && it.Navigat.NavigatType == NavigateType.OneToMany).ToList())
			{
				string fkFieldName = item.Navigat.Name2 ?? thisEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey).PropertyName;
				string dbColumnName = thisEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == fkFieldName).DbColumnName;
				object[] array = (from DataRow x in _Context.Queryable<object>().AS(thisEntity.DbTableName).In(fkName, ids.Distinct().ToList())
						.Select(dbColumnName)
						.ToDataTable()
						.Rows
					select x[0]).ToArray();
				Type type = item.PropertyInfo.PropertyType.GenericTypeArguments[0];
				EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo(type);
				string id = item.Navigat.Name;
				string dbColumnName2 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == id).DbColumnName;
				DeleteChild(array, entityInfo, dbColumnName2);
				_Context.Deleteable<object>().AS(entityInfo.DbTableName).In(dbColumnName2, array.Distinct().ToList())
					.ExecuteCommand();
			}
		}

		private void DeleteChild(object[] fks, EntityInfo entity, string column)
		{
			List<EntityColumnInfo> list = entity.Columns.Where(delegate(EntityColumnInfo it)
			{
				if (it.Navigat != null)
				{
					Navigate navigat = it.Navigat;
					if (navigat == null)
					{
						return false;
					}
					return navigat.NavigatType == NavigateType.OneToMany;
				}
				return false;
			}).ToList();
			if (list.Any())
			{
				EntityColumnInfo entityColumnInfo = entity.Columns.First((EntityColumnInfo it) => it.IsPrimarykey);
				List<object> ids = (from DataRow it in _Context.Queryable<object>().AS(entity.DbTableName).In(column, fks.Distinct().ToList())
						.Select(entityColumnInfo.DbColumnName)
						.ToDataTable()
						.Rows
					select it[0]).ToList();
				DeleteChildChild(ids, list);
			}
		}

		private void DeleteChildChild(List<object> ids, List<EntityColumnInfo> childs)
		{
			childIndex++;
			if (childIndex > 4)
			{
				Check.ExceptionEasy("Removing too many levels", "安全机制限制删除脏数据层级不能超过7层");
			}
			foreach (EntityColumnInfo child in childs)
			{
				Navigate navigat = child.Navigat;
				Type type = child.PropertyInfo.PropertyType.GenericTypeArguments[0];
				EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo(type);
				EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => navigat.Name.EqualCase(it.PropertyName));
				EntityColumnInfo entityColumnInfo2 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				List<EntityColumnInfo> list = entityInfo.Columns.Where(delegate(EntityColumnInfo it)
				{
					if (it.Navigat != null)
					{
						Navigate navigat2 = it.Navigat;
						if (navigat2 == null)
						{
							return false;
						}
						return navigat2.NavigatType == NavigateType.OneToMany;
					}
					return false;
				}).ToList();
				if (list.Any())
				{
					List<object> ids2 = (from DataRow it in _Context.Queryable<object>().AS(entityInfo.DbTableName).In(entityColumnInfo.DbColumnName, ids)
							.Select(entityColumnInfo2.DbColumnName)
							.ToDataTable()
							.Rows
						select it[0]).ToList();
					DeleteChildChild(ids2, list);
				}
				_Context.Deleteable<object>().AS(entityInfo.DbTableName).In(entityColumnInfo.DbColumnName, ids)
					.ExecuteCommand();
			}
		}

		private EntityColumnInfo GetParentPkColumn()
		{
			EntityColumnInfo result = _ParentPkColumn;
			if (_ParentPkColumn == null)
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey));
				result = entityColumnInfo;
			}
			return result;
		}

		private EntityColumnInfo GetParentPkNavColumn(EntityColumnInfo nav)
		{
			EntityColumnInfo result = null;
			if (nav.Navigat.Name2.HasValue())
			{
				EntityColumnInfo entityColumnInfo = (_ParentPkColumn = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name2));
				result = entityColumnInfo;
			}
			return result;
		}

		private void SetNewParent<TChild>(EntityInfo entityInfo, EntityColumnInfo entityColumnInfo) where TChild : class, new()
		{
			_ParentEntity = entityInfo;
			_ParentPkColumn = entityColumnInfo;
		}

		public List<TChild> GetNoExistsId<TChild>(List<TChild> old, List<TChild> newList, string pkName)
		{
			new List<TChild>();
			List<string> newIds = newList.Select((TChild item) => GetPropertyValueAsString(item, pkName)).ToList();
			return old.Where((TChild item) => !newIds.Contains(GetPropertyValueAsString(item, pkName))).ToList();
		}

		private string GetPropertyValueAsString<TChild>(TChild item, string propertyName)
		{
			PropertyInfo property = item.GetType().GetProperty(propertyName);
			if (property != null)
			{
				return property.GetValue(item, null)?.ToString() ?? "";
			}
			throw new ArgumentException("Property '" + propertyName + "' not found on type " + item.GetType().Name);
		}

		private void UpdateOneToOne<TChild>(string name, EntityColumnInfo nav) where TChild : class, new()
		{
			EntityInfo parentEntity = _ParentEntity;
			List<object> parentList = _ParentList;
			bool flag = parentEntity.Columns.Count((EntityColumnInfo it) => it.IsPrimarykey) > 1;
			EntityColumnInfo entityColumnInfo = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
			EntityColumnInfo entityColumnInfo2 = parentEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			EntityInfo entityInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>();
			IsDeleted = entityInfo.Columns.Any((EntityColumnInfo it) => it.PropertyName.EqualCase("isdeleted") || it.PropertyName.EqualCase("isdelete"));
			EntityColumnInfo pkColumnByNav = GetPkColumnByNav(entityInfo, nav);
			Check.ExceptionEasy(pkColumnByNav == null, $" Navigate {parentEntity.EntityName} : {name} is error ", $"导航实体 {parentEntity.EntityName} 属性 {name} 配置错误");
			Check.ExceptionEasy(nav.Navigat.WhereSql.HasValue(), " " + name + " Navigate(NavType,WhereSql)  no support update ", "导航一对一 " + name + " 配置了 Sql变量 不支持更新");
			List<TChild> list = new List<TChild>();
			foreach (object item in parentList)
			{
				object obj = entityColumnInfo.PropertyInfo.GetValue(item);
				TChild val = (TChild)nav.PropertyInfo.GetValue(item);
				if (val == null)
				{
					continue;
				}
				if (IsDefaultValue(obj))
				{
					object value = pkColumnByNav.PropertyInfo.GetValue(val);
					if (IsDefaultValue(obj))
					{
						if (!entityColumnInfo.IsPrimarykey && !flag && !entityColumnInfo.IsIdentity)
						{
							_Context.Updateable<DbTableInfo>().AS(parentEntity.DbTableName).SetColumns(entityColumnInfo.DbColumnName, value)
								.Where(entityColumnInfo2.DbColumnName, "=", entityColumnInfo2.PropertyInfo.GetValue(item))
								.ExecuteCommand();
						}
						obj = value;
					}
				}
				if (!IsDefaultValue(obj) && !flag && !entityColumnInfo2.IsIdentity)
				{
					_Context.Updateable<DbTableInfo>().AS(parentEntity.DbTableName).SetColumns(entityColumnInfo.DbColumnName, obj)
						.Where(entityColumnInfo2.DbColumnName, "=", entityColumnInfo2.PropertyInfo.GetValue(item))
						.ExecuteCommand();
				}
				if (IsDefaultValue(obj))
				{
					InsertDatas(new List<TChild> { val }, pkColumnByNav);
					obj = pkColumnByNav.PropertyInfo.GetValue(val);
					entityColumnInfo.PropertyInfo.SetValue(item, obj);
					_Context.Updateable<DbTableInfo>().AS(parentEntity.DbTableName).SetColumns(entityColumnInfo.DbColumnName, obj)
						.Where(entityColumnInfo2.DbColumnName, "=", entityColumnInfo2.PropertyInfo.GetValue(item))
						.ExecuteCommand();
				}
				pkColumnByNav.PropertyInfo.SetValue(val, obj);
				list.Add(val);
			}
			InsertDatas(list, pkColumnByNav);
			_ParentList = list.Cast<object>().ToList();
			SetNewParent<TChild>(entityInfo, pkColumnByNav);
		}

