		private UpdateNavProvider<Root, TChild> _ThenInclude<TChild>(Expression<Func<T, TChild>> expression) where TChild : class, new()
		{
			bool flag = _RootList == null;
			IsFirst = flag && _ParentList == null;
			InitParentList();
			string name = ExpressionTool.GetMemberName(expression);
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			if (_RootOptions == null || !_RootOptions.IsDisableUpdateRoot)
			{
				UpdateRoot(flag, entityColumnInfo);
			}
			IsFirst = false;
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				UpdateOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				UpdateOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				UpdateManyToMany<TChild>(name, entityColumnInfo);
			}
			AddContextInfo(name, flag);
			return GetResult<TChild>();
		}

		private UpdateNavProvider<Root, TChild> _ThenInclude<TChild>(Expression<Func<T, List<TChild>>> expression) where TChild : class, new()
		{
			bool flag = _RootList == null;
			IsFirst = flag && _ParentList == null;
			InitParentList();
			string name = ExpressionTool.GetMemberName(expression);
			if (name == null)
			{
				name = ExpressionTool.GetMemberNameByMethod(expression, name);
			}
			EntityColumnInfo entityColumnInfo = _ParentEntity.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == name);
			if (entityColumnInfo.Navigat == null)
			{
				Check.ExceptionEasy(name + " no navigate attribute", _ParentEntity.EntityName + "的属性" + name + "没有导航属性");
			}
			UpdateRoot(flag, entityColumnInfo);
			IsFirst = false;
			if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToOne || entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
			{
				UpdateOneToOne<TChild>(name, entityColumnInfo);
			}
			else if (entityColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
			{
				UpdateOneToMany<TChild>(name, entityColumnInfo);
			}
			else
			{
				UpdateManyToMany<TChild>(name, entityColumnInfo);
			}
			AddContextInfo(name, flag);
			return GetResult<TChild>();
		}

		private void UpdateRoot(bool isRoot, EntityColumnInfo nav)
		{
			if (isRoot && nav.Navigat.NavigatType != NavigateType.ManyToMany)
			{
				UpdateNavRootOptions rootOptions = _RootOptions;
				if (rootOptions == null || !rootOptions.IsDisableUpdateRoot)
				{
					UpdateRoot();
					return;
				}
			}
			if (isRoot)
			{
				UpdateNavRootOptions rootOptions2 = _RootOptions;
				if (rootOptions2 != null && rootOptions2.IsInsertRoot && nav.Navigat.NavigatType == NavigateType.ManyToMany)
				{
					UpdateRoot();
					return;
				}
			}
			if (_Options != null && _Options.ManyToManyIsUpdateA)
			{
				UpdateRoot();
			}
		}

		private void UpdateRoot()
		{
			if (IsAsNav)
			{
				return;
			}
			if (_Options != null && _Options.RootFunc != null)
			{
				IUpdateable<Root> updateable = _Context.Updateable(_Roots);
				Expression<Action<IUpdateable<Root>>> obj = _Options.RootFunc as Expression<Action<IUpdateable<Root>>>;
				Check.ExceptionEasy(obj == null, "UpdateOptions.RootFunc is error", "UpdateOptions.RootFunc");
				obj.Compile()(updateable);
				updateable.ExecuteCommand();
				return;
			}
			if (IsFirst && _RootOptions != null)
			{
				if (_RootOptions.IsInsertRoot)
				{
					List<Root> list = new List<Root>();
					foreach (Root root in _Roots)
					{
						StorageableResult<Root> storageableResult = _Context.Storageable(root).ToStorage();
						if (storageableResult.InsertList.HasValue())
						{
							list.Add(storageableResult.AsInsertable.IgnoreColumns(_RootOptions.IgnoreInsertColumns).EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData).ExecuteReturnEntity());
							continue;
						}
						storageableResult.AsUpdateable.EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData).UpdateColumns(_RootOptions.UpdateColumns).IgnoreColumns(_RootOptions.IgnoreColumns)
							.IgnoreNullColumns(_RootOptions.IsIgnoreAllNullColumns)
							.ExecuteCommandWithOptLockIF(_RootOptions?.IsOptLock, _RootOptions?.IsOptLock);
						list.Add(root);
					}
					List<object> parentList = (_RootList = list.Cast<object>().ToList());
					_ParentList = parentList;
					return;
				}
				if (_Roots.Count() == 1)
				{
					UpdateNavRootOptions rootOptions = _RootOptions;
					if (rootOptions != null && rootOptions.IsOptLock)
					{
						_Context.Updateable(_Roots.First()).EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData).UpdateColumns(_RootOptions.UpdateColumns)
							.IgnoreColumns(_RootOptions.IgnoreColumns)
							.IgnoreNullColumns(_RootOptions.IsIgnoreAllNullColumns)
							.ExecuteCommandWithOptLockIF(_RootOptions?.IsOptLock, _RootOptions?.IsOptLock);
						return;
					}
				}
				_Context.Updateable(_Roots).EnableDiffLogEventIF(_RootOptions.IsDiffLogEvent, _RootOptions.DiffLogBizData).UpdateColumns(_RootOptions.UpdateColumns)
					.IgnoreColumns(_RootOptions.IgnoreColumns)
					.IgnoreNullColumns(_RootOptions.IsIgnoreAllNullColumns)
					.ExecuteCommandWithOptLockIF(_RootOptions?.IsOptLock, _RootOptions?.IsOptLock);
				return;
			}
			if (_RootOptions != null)
			{
				UpdateNavRootOptions rootOptions2 = _RootOptions;
				if (rootOptions2 != null && rootOptions2.IsDiffLogEvent)
				{
					_Context.Updateable(_Roots).EnableDiffLogEvent(_RootOptions.DiffLogBizData).ExecuteCommand();
					return;
				}
			}
			_Context.Updateable(_Roots).ExecuteCommand();
		}

		private void AddContextInfo(string name, bool isRoot)
		{
			if ((IsAsNav | isRoot) && NavContext != null && NavContext.Items != null)
			{
				NavContext.Items.Add(new NavContextItem
				{
					Level = 0,
					RootName = name
				});
			}
		}

		private bool NotAny(string name)
		{
			if (IsFirst)
			{
				return true;
			}
			if (NavContext == null)
			{
				return true;
			}
			NavContext navContext = NavContext;
			if (navContext == null)
			{
				return false;
			}
			return navContext.Items?.Any((NavContextItem it) => it.RootName == name) == false;
		}

		private static bool IsDefaultValue(object pvValue)
		{
			return pvValue?.Equals(UtilMethods.GetDefaultValue(pvValue.GetType())) ?? true;
		}

		private void InitParentList()
		{
			if (_RootList == null)
			{
				List<object> rootList = (_ParentList = _Roots.Cast<object>().ToList());
				_RootList = rootList;
				_ParentEntity = _Context.EntityMaintenance.GetEntityInfo<Root>();
			}
			else if (_ParentList == null)
			{
				_ParentList = _RootList;
				EntityColumnInfo parentPkColumn = _Context.EntityMaintenance.GetEntityInfo<T>().Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				_ParentPkColumn = parentPkColumn;
			}
		}

