		private void InsertDatas<TChild>(List<TChild> children, EntityColumnInfo pkColumn, EntityColumnInfo NavColumn = null) where TChild : class, new()
		{
			children = children.Distinct().ToList();
			Check.ExceptionEasy(pkColumn == null, typeof(TChild).Name + " has no primary key", typeof(TChild).Name + "没有主键");
			string whereName = pkColumn.PropertyName;
			UpdateNavOptions options = _Options;
			if (options != null && options.OneToOneSaveByPrimaryKey && !pkColumn.IsPrimarykey)
			{
				EntityColumnInfo entityColumnInfo = _Context.EntityMaintenance.GetEntityInfo<TChild>().Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (entityColumnInfo != null)
				{
					whereName = entityColumnInfo.PropertyName;
				}
			}
			StorageableResult<TChild> storageableResult = _Context.Storageable(children).WhereColumns(new string[1] { whereName }).ToStorage();
			List<TChild> list = storageableResult.InsertList.Select((StorageableMessage<TChild> it) => it.Item).ToList();
			List<TChild> second = storageableResult.UpdateList.Select((StorageableMessage<TChild> it) => it.Item).ToList();
			Check.ExceptionEasy(pkColumn == null && NavColumn == null, "The entity is invalid", "实体错误无法使用导航");
			if (_Options != null && _Options.CurrentFunc != null)
			{
				IUpdateable<TChild> asUpdateable = storageableResult.AsUpdateable;
				Expression<Action<IUpdateable<TChild>>> obj = _Options.CurrentFunc as Expression<Action<IUpdateable<TChild>>>;
				Check.ExceptionEasy(obj == null, "UpdateOptions.CurrentFunc is error", "UpdateOptions.CurrentFunc参数设置错误");
				obj.Compile()(asUpdateable);
				if (IsDeleted)
				{
					asUpdateable.PageSize(1).EnableQueryFilter().ExecuteCommand();
				}
				else
				{
					asUpdateable.ExecuteCommand();
				}
			}
			else if (!pkColumn.IsPrimarykey)
			{
				IEnumerable<EntityColumnInfo> source = _Context.EntityMaintenance.GetEntityInfo<TChild>().Columns.Where((EntityColumnInfo it) => it.IsPrimarykey);
				List<string> list2 = new List<string>();
				if (_Options?.IgnoreColumns != null)
				{
					list2.AddRange(_Options.IgnoreColumns);
				}
				if (source.Any())
				{
					list2.AddRange(source.Select((EntityColumnInfo it) => it.PropertyName));
				}
				UpdateNavOptions options2 = _Options;
				if (options2 != null && options2.OneToOneSaveByPrimaryKey)
				{
					list2 = list2.Where((string it) => it != whereName).ToList();
				}
				if (IsDeleted)
				{
					storageableResult.AsUpdateable.IgnoreColumns(list2.ToArray()).PageSize(1).EnableQueryFilter()
						.ExecuteCommand();
				}
				else
				{
					storageableResult.AsUpdateable.IgnoreColumns(list2.ToArray()).ExecuteCommand();
				}
			}
			else
			{
				string[] array = _Options?.IgnoreColumns;
				bool isIgnoreNull = _Options?.IgnoreNullColumns ?? false;
				if (IsDeleted)
				{
					storageableResult.AsUpdateable.IgnoreNullColumns(isIgnoreNull).IgnoreColumns(array?.ToArray()).PageSize(1)
						.EnableQueryFilter()
						.ExecuteCommand();
				}
				else
				{
					storageableResult.AsUpdateable.IgnoreNullColumns(isIgnoreNull).IgnoreColumns(array?.ToArray()).ExecuteCommand();
				}
			}
			InitData(pkColumn, list);
			if (_NavigateType == NavigateType.OneToMany)
			{
				_ParentList = children.Cast<object>().ToList();
			}
			else
			{
				_ParentList = list.Union(second).Cast<object>().ToList();
			}
		}

		private void InitData<TChild>(EntityColumnInfo pkColumn, List<TChild> UpdateData) where TChild : class, new()
		{
			if (pkColumn.IsIdentity || pkColumn.OracleSequenceName.HasValue())
			{
				InsertIdentity(UpdateData);
			}
			else if (pkColumn.UnderType == UtilConstants.LongType)
			{
				SetValue(pkColumn, UpdateData, () => SnowFlakeSingle.Instance.NextId());
			}
			else if (pkColumn.UnderType == UtilConstants.GuidType)
			{
				SetValue(pkColumn, UpdateData, () => UtilMethods.NewGuid());
			}
			else if (pkColumn.UnderType == UtilConstants.StringType)
			{
				SetValue(pkColumn, UpdateData, () => UtilMethods.NewGuid().ToString());
			}
			else
			{
				SetError(pkColumn, UpdateData);
			}
		}

		private void SetValue<TChild>(EntityColumnInfo pkColumn, List<TChild> UpdateData, Func<object> value) where TChild : class, new()
		{
			foreach (TChild UpdateDatum in UpdateData)
			{
				if (IsDefaultValue(pkColumn.PropertyInfo.GetValue(UpdateDatum)))
				{
					pkColumn.PropertyInfo.SetValue(UpdateDatum, value());
				}
			}
			_Context.Insertable(UpdateData).ExecuteCommand();
		}

		private void SetError<TChild>(EntityColumnInfo pkColumn, List<TChild> UpdateData) where TChild : class, new()
		{
			foreach (TChild UpdateDatum in UpdateData)
			{
				if (IsDefaultValue(pkColumn.PropertyInfo.GetValue(UpdateDatum)))
				{
					string text = pkColumn.EntityName + " " + pkColumn.DbColumnName;
					Check.ExceptionEasy("The field " + text + " is not an autoassignment type and requires an assignment", "字段" + text + "不是可自动赋值类型，需要赋值 , 可赋值类型有 自增、long、Guid、string");
				}
			}
			_Context.Insertable(UpdateData).ExecuteCommand();
		}
	}
	public class UpdateNavTaskInit<Root, T> where Root : class, new() where T : class, new()
	{
		internal SqlSugarProvider Context { get; set; }

		internal UpdateNavProvider<Root, Root> UpdateNavProvider { get; set; }

		internal NavContext NavContext { get; set; }

		public UpdateNavTask<Root, TChild> Include<TChild>(Expression<Func<Root, TChild>> expression) where TChild : class, new()
		{
			Context = UpdateNavProvider._Context;
			UpdateNavProvider.NavContext = NavContext;
			UpdateNavTask<Root, TChild> updateNavTask = new UpdateNavTask<Root, TChild>();
			Func<UpdateNavProvider<Root, TChild>> preFunc = () => UpdateNavProvider.ThenInclude(expression);
			updateNavTask.PreFunc = preFunc;
			updateNavTask.Context = Context;
			updateNavTask.NavContext = NavContext;
			return updateNavTask;
		}

