		public UpdateNavMethodInfo IncludesAllFirstLayer(params string[] ignoreColumns)
		{
			if (ignoreColumns == null)
			{
				ignoreColumns = new string[0];
			}
			Context = UpdateNavProvider._Context;
			List<EntityColumnInfo> list = (from it in Context.EntityMaintenance.GetEntityInfo<Root>().Columns
				where !Enumerable.Contains(ignoreColumns, it.PropertyName) || !ignoreColumns.Any((string z) => z.EqualCase(it.DbColumnName))
				where it.Navigat != null
				select it).ToList();
			UpdateNavMethodInfo updateNavMethodInfo = IncludeByNameString(list[0].PropertyName);
			foreach (EntityColumnInfo item in list.Skip(1))
			{
				updateNavMethodInfo = updateNavMethodInfo.IncludeByNameString(item.PropertyName);
			}
			return updateNavMethodInfo;
		}

		public UpdateNavMethodInfo IncludesAllFirstLayer(UpdateNavOptions updateNavOptions, params string[] ignoreColumns)
		{
			if (ignoreColumns == null)
			{
				ignoreColumns = new string[0];
			}
			Context = UpdateNavProvider._Context;
			List<EntityColumnInfo> list = (from it in Context.EntityMaintenance.GetEntityInfo<Root>().Columns
				where !Enumerable.Contains(ignoreColumns, it.PropertyName) || !ignoreColumns.Any((string z) => z.EqualCase(it.DbColumnName))
				where it.Navigat != null
				select it).ToList();
			UpdateNavMethodInfo updateNavMethodInfo = IncludeByNameString(list[0].PropertyName, updateNavOptions);
			foreach (EntityColumnInfo item in list.Skip(1))
			{
				updateNavMethodInfo = updateNavMethodInfo.IncludeByNameString(item.PropertyName, updateNavOptions);
			}
			return updateNavMethodInfo;
		}

		public UpdateNavMethodInfo IncludeByNameString(string navMemberName, UpdateNavOptions updateNavOptions = null)
		{
			UpdateNavMethodInfo updateNavMethodInfo = new UpdateNavMethodInfo();
			updateNavMethodInfo.Context = UpdateNavProvider._Context;
			EntityInfo entityInfo = updateNavMethodInfo.Context.EntityMaintenance.GetEntityInfo<T>();
			Expression includeExpression = UtilMethods.GetIncludeExpression(navMemberName, entityInfo, out Type properyItemType, out bool isList);
			object methodInfos = GetType().GetMyMethod("Include", 2, isList).MakeGenericMethod(properyItemType).Invoke(this, new object[2] { includeExpression, updateNavOptions });
			updateNavMethodInfo.MethodInfos = methodInfos;
			return updateNavMethodInfo;
		}
	}
