		public bool ExecuteCommand()
		{
			if (Context.Ado.Transaction != null)
			{
				PreFunc();
			}
			else
			{
				Context.Ado.UseTran(delegate
				{
					PreFunc();
				}, delegate(Exception ex)
				{
					throw ex;
				});
			}
			return true;
		}

		public async Task<bool> ExecuteCommandAsync()
		{
			await Task.Run(async delegate
			{
				ExecuteCommand();
				await Task.Delay(0);
			});
			return true;
		}

		private UpdateNavTask<Root, Root> AsNav()
		{
			UpdateNavTask<Root, Root> updateNavTask = new UpdateNavTask<Root, Root>();
			Func<UpdateNavProvider<Root, Root>> preFunc = delegate
			{
				UpdateNavProvider<Root, Root> updateNavProvider = PreFunc().AsNav();
				updateNavProvider.IsAsNav = true;
				updateNavProvider.NavContext = NavContext;
				return updateNavProvider;
			};
			updateNavTask.PreFunc = preFunc;
			updateNavTask.Context = Context;
			updateNavTask.NavContext = NavContext;
			return updateNavTask;
		}
	}
