	public class FastBuilder
	{
		public EntityInfo FastEntityInfo { get; set; }

		public virtual bool IsActionUpdateColumns { get; set; }

		public virtual DbFastestProperties DbFastestProperties { get; set; }

		public SqlSugarProvider Context { get; set; }

		public virtual string CharacterSet { get; set; }

		public virtual string UpdateSql { get; set; } = "UPDATE TM\r\n                                                    SET  {0}\r\n                                                    FROM {1} TM\r\n                                                    INNER JOIN {2} TE ON {3} ";

		public virtual void CloseDb()
		{
			if (Context.CurrentConnectionConfig.IsAutoCloseConnection && Context.Ado.Transaction == null)
			{
				Context.Ado.Connection.Close();
			}
		}

		public virtual async Task<int> UpdateByTempAsync(string tableName, string tempName, string[] updateColumns, string[] whereColumns)
		{
			ISqlBuilder sqlbuilder = Context.Queryable<object>().SqlBuilder;
			Check.ArgumentNullException(!updateColumns.Any(), "update columns count is 0");
			Check.ArgumentNullException(!whereColumns.Any(), "where columns count is 0");
			string text = string.Join(",", updateColumns.Select((string it) => "TM." + sqlbuilder.GetTranslationColumnName(it) + "=TE." + sqlbuilder.GetTranslationColumnName(it)));
			string text2 = string.Join(" AND ", whereColumns.Select((string it) => "TM." + sqlbuilder.GetTranslationColumnName(it) + "=TE." + sqlbuilder.GetTranslationColumnName(it)));
			string sql = string.Format(UpdateSql, text, tableName, tempName, text2);
			return await Context.Ado.ExecuteCommandAsync(sql);
		}

		public virtual async Task CreateTempAsync<T>(DataTable dt) where T : class, new()
		{
			ISqlBuilder sqlbuilder = Context.Queryable<object>().SqlBuilder;
			await Context.UnionAll<T>((from it in Context.Queryable<T>().Filter(null, isDisabledGobalFilter: true).Select(string.Join(",", from DataColumn it in dt.Columns
					select sqlbuilder.GetTranslationColumnName(it.ColumnName)))
				where false
				select it).AS(dt.TableName), (from it in Context.Queryable<T>().Filter(null, isDisabledGobalFilter: true).Select(string.Join(",", from DataColumn it in dt.Columns
					select sqlbuilder.GetTranslationColumnName(it.ColumnName)))
				where false
				select it).AS(dt.TableName)).Select("top 1 * into #temp").ToListAsync();
			dt.TableName = "#temp";
		}

		public virtual async Task<int> Merge<T>(string tableName, DataTable dt, EntityInfo entityInfo, string[] whereColumns, string[] updateColumns, List<T> datas) where T : class, new()
		{
			int result = 0;
			int pageSize = 2000;
			if (dt.Columns.Count > 100)
			{
				pageSize = 100;
			}
			else if (dt.Columns.Count > 50)
			{
				pageSize = 300;
			}
			else if (dt.Columns.Count > 30)
			{
				pageSize = 500;
			}
			await Context.Utilities.PageEachAsync(datas, pageSize, async delegate(List<T> pageItems)
			{
				StorageableResult<T> x = await Context.Storageable(pageItems).As(tableName).WhereColumns(whereColumns)
					.ToStorageAsync();
				int num = result;
				result = num + await x.BulkCopyAsync();
				num = result;
				result = num + await x.BulkUpdateAsync(updateColumns);
				return result;
			});
			return result;
		}
	}
	public class FastestProvider<T> : IFastest<T> where T : class, new()
	{
		internal SqlSugarProvider context;

		private ISugarQueryable<T> queryable;

		public bool isLog;

		private EntityInfo entityInfo { get; set; }

		private string AsName { get; set; }

		private int Size { get; set; }

		private string CacheKey { get; set; }

		private string CacheKeyLike { get; set; }

		private string CharacterSet { get; set; }

		private bool IsDataAop { get; set; }

		private bool IsOffIdentity { get; set; }

		private bool IsIgnoreInsertError { get; set; }

		private int BatchsSize { get; set; }

		public FastestProvider(SqlSugarProvider sqlSugarProvider)
		{
			context = sqlSugarProvider;
			queryable = context.Queryable<T>();
			entityInfo = context.EntityMaintenance.GetEntityInfo<T>();
		}

		public int BulkCopy(string tableName, DataTable dt)
		{
			return BulkCopyAsync(tableName, dt).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public int BulkCopy(DataTable dt)
		{
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
			return BulkCopyAsync(AsName, dt).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public Task<int> BulkCopyAsync(DataTable dt)
		{
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
			return BulkCopyAsync(AsName, dt);
		}

		public async Task<int> BulkCopyAsync(string tableName, DataTable dt)
		{
			if (Size > 0)
			{
				int resul = 0;
				await context.Utilities.PageEachAsync(dt.Rows.Cast<DataRow>().ToList(), Size, async delegate(List<DataRow> item)
				{
					int num = resul;
					resul = num + await _BulkCopy(tableName, item.CopyToDataTable());
				});
				return resul;
			}
			return await _BulkCopy(tableName, dt);
		}

		public int BulkCopy(List<T> datas)
		{
			return BulkCopyAsync(datas).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public async Task<int> BulkCopyAsync(List<T> datas)
		{
			if (Size > 0)
			{
				IFastBuilder buider = GetBuider();
				if (buider != null && buider.DbFastestProperties?.NoPage == true)
				{
					Size = 1073741823;
				}
				int resul = 0;
				await context.Utilities.PageEachAsync(datas, Size, async delegate(List<T> item)
				{
					int num = resul;
					resul = num + await _BulkCopy(item);
				});
				return resul;
			}
			return await _BulkCopy(datas);
		}

		public int BulkUpdate(List<T> datas)
		{
			return BulkUpdateAsync(datas).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public async Task<int> BulkUpdateAsync(List<T> datas)
		{
			string[] whereColumns = (from it in entityInfo.Columns
				where it.IsPrimarykey
				select it.DbColumnName ?? it.PropertyName).ToArray();
			string[] updateColumns = (from it in entityInfo.Columns
				where !it.IsPrimarykey && !it.IsIdentity && !it.IsOnlyIgnoreUpdate && !it.IsIgnore
				select it.DbColumnName ?? it.PropertyName).ToArray();
			return await BulkUpdateAsync(datas, whereColumns, updateColumns);
		}

		public int BulkUpdate(List<T> datas, string[] whereColumns, string[] updateColumns)
		{
			whereColumns = whereColumns.Select((string x) => entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(x) || it.DbColumnName.EqualCase(x))?.DbColumnName ?? x).ToArray();
			updateColumns = updateColumns.Select((string x) => entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(x) || it.DbColumnName.EqualCase(x))?.DbColumnName ?? x).ToArray();
			return BulkUpdateAsync(datas, whereColumns, updateColumns).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public int BulkUpdate(List<T> datas, string[] whereColumns)
		{
			return BulkUpdateAsync(datas, whereColumns).GetAwaiter().GetResult();
		}

		public async Task<int> BulkUpdateAsync(List<T> datas, string[] whereColumns)
		{
			whereColumns = whereColumns.Select((string x) => entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(x) || it.DbColumnName.EqualCase(x))?.DbColumnName ?? x).ToArray();
			string[] updateColumns = (from it in entityInfo.Columns
				where !whereColumns.Any((string z) => z.EqualCase(it.DbColumnName))
				where !it.IsIdentity
				where !it.IsPrimarykey
				where !it.IsOnlyIgnoreUpdate
				where !it.IsIgnore
				select it.DbColumnName).ToArray();
			return await BulkUpdateAsync(datas, whereColumns, updateColumns).ConfigureAwait(continueOnCapturedContext: true);
		}

		public async Task<int> BulkUpdateAsync(List<T> datas, string[] whereColumns, string[] updateColumns)
		{
			if (Size > 0)
			{
				int resul = 0;
				await context.Utilities.PageEachAsync(datas, Size, async delegate(List<T> item)
				{
					int num = resul;
					resul = num + await _BulkUpdate(item, whereColumns, updateColumns);
				});
				return resul;
			}
			return await _BulkUpdate(datas, whereColumns, updateColumns);
		}

		public int BulkUpdate(string tableName, DataTable dataTable, string[] whereColumns, string[] updateColumns)
		{
			return BulkUpdateAsync(tableName, dataTable, whereColumns, updateColumns).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public int BulkUpdate(DataTable dataTable, string[] whereColumns, string[] updateColumns)
		{
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
			return BulkUpdateAsync(AsName, dataTable, whereColumns, updateColumns).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

		public int BulkUpdate(DataTable dataTable, string[] whereColumns)
		{
			string[] updateColumns = (from DataColumn it in dataTable.Columns
				select it.ColumnName into it
				where !whereColumns.Any((string z) => z.EqualCase(it))
				select it).ToArray();
			whereColumns = (from DataColumn it in dataTable.Columns
				select it.ColumnName into it
				where whereColumns.Any((string z) => z.EqualCase(it))
				select it).ToArray();
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
			return BulkUpdateAsync(AsName, dataTable, whereColumns, updateColumns).ConfigureAwait(continueOnCapturedContext: true).GetAwaiter().GetResult();
		}

