		{
			string[] updateColumns = (from DataColumn it in dataTable.Columns
				select it.ColumnName into it
				where !whereColumns.Any((string z) => z.EqualCase(it))
				select it).ToArray();
			whereColumns = (from DataColumn it in dataTable.Columns
				select it.ColumnName into it
				where whereColumns.Any((string z) => z.EqualCase(it))
				select it).ToArray();
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
