		}

		public Task<int> BulkMergeAsync(List<T> datas)
		{
			string[] updateColumns = (from it in entityInfo.Columns
				where !it.IsPrimarykey && !it.IsIdentity && !it.IsOnlyIgnoreUpdate && !it.IsIgnore
				select it.DbColumnName ?? it.PropertyName).ToArray();
			string[] whereColumns = (from it in entityInfo.Columns
				where it.IsPrimarykey
				select it.DbColumnName ?? it.PropertyName).ToArray();
			return BulkMergeAsync(datas, whereColumns, updateColumns);
		}

		public int BulkMerge(List<T> datas)
		{
			return BulkMergeAsync(datas).GetAwaiter().GetResult();
		}

		public int BulkMerge(DataTable dataTable, string[] whereColumns, bool isIdentity)
		{
			_BulkMerge(dataTable, whereColumns, out object newValue, out object fastestMethod, out MethodInfo bulkCopyMethod, isAsync: false, isIdentity);
			return (int)bulkCopyMethod.Invoke(fastestMethod, new object[1] { newValue });
		}

		public Task<int> BulkMergeAsync(DataTable dataTable, string[] whereColumns, bool isIdentity)
		{
			_BulkMerge(dataTable, whereColumns, out object newValue, out object fastestMethod, out MethodInfo bulkCopyMethod, isAsync: true, isIdentity);
			return (Task<int>)bulkCopyMethod.Invoke(fastestMethod, new object[1] { newValue });
		}

		public int BulkMerge(DataTable dataTable, string[] whereColumns, string[] updateColumns, bool isIdentity)
		{
			return BulkMergeAsync(dataTable, whereColumns, updateColumns, isIdentity).GetAwaiter().GetResult();
		}

		public Task<int> BulkMergeAsync(DataTable dataTable, string[] whereColumns, string[] updateColumns, bool isIdentity)
		{
			_BulkMerge(dataTable, whereColumns, updateColumns, out object newValue, out object fastestMethod, out MethodInfo bulkCopyMethod, isAsync: true, isIdentity);
			return (Task<int>)bulkCopyMethod.Invoke(fastestMethod, new object[3] { newValue, whereColumns, updateColumns });
		}

		public Task<int> BulkMergeAsync(List<T> datas, string[] whereColumns)
		{
			string[] updateColumns = (from it in entityInfo.Columns
				where !it.IsPrimarykey && !it.IsIdentity && !it.IsOnlyIgnoreUpdate && !it.IsIgnore
				select it.DbColumnName ?? it.PropertyName).ToArray();
			return BulkMergeAsync(datas, whereColumns, updateColumns);
		}

