		public async Task<int> BulkMergeAsync(List<T> datas, string[] whereColumns, string[] updateColumns)
		{
			if (Size > 0)
			{
				int resul = 0;
				await context.Utilities.PageEachAsync(datas, Size, async delegate(List<T> item)
				{
					int num = resul;
					resul = num + await _BulkMerge(item, updateColumns, whereColumns);
				});
				return resul;
			}
			return await _BulkMerge(datas, updateColumns, whereColumns);
		}

