		public async Task<int> BulkMergeAsync(List<T> datas, Expression<Func<T, object>> whereColumnsExp, Expression<Func<T, object>> updateColumnsExp)
		{
			List<EntityColumnInfo> columnInfos = context.EntityMaintenance.GetEntityInfo<T>().Columns;
			string[] whereColumns = (from it in ExpressionTool.GetNewExpressionItemListNew(whereColumnsExp.Body)
				select it.Key).ToArray();
			string[] source = (from it in ExpressionTool.GetNewExpressionItemListNew(updateColumnsExp.Body)
				select it.Key).ToArray();
			source = source.Select((string s) => columnInfos.Where((EntityColumnInfo ec) => ec.DbColumnName.EqualCase(s) || ec.PropertyName.EqualCase(s)).FirstOrDefault()?.DbColumnName ?? s).ToArray();
			return await BulkMergeAsync(datas, whereColumns, source);
		}

