		}

		private async Task<int> _BulkMerge(List<T> datas, string[] updateColumns, string[] whereColumns)
		{
			_ = 2;
			try
			{
				Begin(datas, isAdd: false, isMerge: true);
				Check.Exception(updateColumns == null || updateColumns.Count() == 0, "set columns count=0");
				Check.Exception(whereColumns == null || whereColumns.Count() == 0, "where columns count=0 or need primary key");
				bool isAuto = context.CurrentConnectionConfig.IsAutoCloseConnection;
				context.CurrentConnectionConfig.IsAutoCloseConnection = false;
				bool old = context.Ado.IsDisableMasterSlaveSeparation;
				context.Ado.IsDisableMasterSlaveSeparation = true;
				DataTable dt = ToDdateTable(datas);
				IFastBuilder buider = GetBuider();
				buider.Context = context;
				if (buider != null && buider.DbFastestProperties?.IsMerge == true)
				{
					await buider.CreateTempAsync<T>(dt);
					await buider.ExecuteBulkCopyAsync(dt);
				}
				int result = await buider.Merge(GetTableName(), dt, entityInfo, whereColumns, updateColumns, datas);
				if (buider != null && buider.DbFastestProperties?.IsMerge == true && context.CurrentConnectionConfig.DbType != DbType.Sqlite)
				{
					context.DbMaintenance.DropTable(dt.TableName);
				}
				context.CurrentConnectionConfig.IsAutoCloseConnection = isAuto;
				buider.CloseDb();
				End(datas, isAdd: false, isMerge: true);
				context.Ado.IsDisableMasterSlaveSeparation = old;
				return result;
			}
			catch (Exception)
			{
				context.Close();
				throw;
			}
		}

		private void _BulkMerge(DataTable dataTable, string[] whereColumns, out object newValue, out object fastestMethod, out MethodInfo bulkCopyMethod, bool isAsync, bool isIdentity)
		{
			Check.ExceptionEasy(AsName.IsNullOrEmpty(), "need .AS(tablaeName) ", "需要 .AS(tablaeName) 设置表名");
			string entityName = "BulkMerge_" + isIdentity + AsName.GetNonNegativeHashCodeString();
			DynamicProperyBuilder dynamicProperyBuilder = context.DynamicBuilder().CreateClass(entityName, new SugarTable
			{
				TableName = AsName
			});
			foreach (DataColumn item in dataTable.Columns)
			{
				bool flag = whereColumns.Any((string it) => it.EqualCase(item.ColumnName));
				Type type = item.DataType;
				if (!type.IsClass() && type != typeof(string) && type != typeof(byte[]))
				{
					type = typeof(Nullable<>).MakeGenericType(UtilMethods.GetUnderType(item.DataType));
				}
				dynamicProperyBuilder.CreateProperty(item.ColumnName, type, new SugarColumn
				{
					IsPrimaryKey = flag,
					IsIdentity = (isIdentity & flag),
					IsNullable = true
				});
			}
			List<Dictionary<string, object>> dictList = context.Utilities.DataTableToDictionaryList(dataTable);
			Type type2 = dynamicProperyBuilder.WithCache().BuilderType();
			List<object> sourceList = context.DynamicBuilder().CreateObjectByType(type2, dictList);
			newValue = UtilMethods.ConvertToObjectList(type2, sourceList);
			fastestMethod = context.GetType().GetMethod("Fastest").MakeGenericMethod(type2)
				.Invoke(context, null);
			bulkCopyMethod = fastestMethod.GetType().GetMyMethod(isAsync ? "BulkMergeAsync" : "BulkMerge", 1);
		}

