			string entityName = "BulkMerge_" + isIdentity + AsName.GetNonNegativeHashCodeString();
			DynamicProperyBuilder dynamicProperyBuilder = context.DynamicBuilder().CreateClass(entityName, new SugarTable
			{
				TableName = AsName
			});
			foreach (DataColumn item in dataTable.Columns)
			{
				bool flag = whereColumns.Any((string it) => it.EqualCase(item.ColumnName));
				Type type = item.DataType;
				if (!type.IsClass() && type != typeof(string) && type != typeof(byte[]))
				{
					type = typeof(Nullable<>).MakeGenericType(UtilMethods.GetUnderType(item.DataType));
				}
				dynamicProperyBuilder.CreateProperty(item.ColumnName, type, new SugarColumn
				{
					IsPrimaryKey = flag,
					IsIdentity = (isIdentity & flag),
					IsNullable = true
				});
			}
			List<Dictionary<string, object>> dictList = context.Utilities.DataTableToDictionaryList(dataTable);
			Type type2 = dynamicProperyBuilder.WithCache().BuilderType();
			List<object> sourceList = context.DynamicBuilder().CreateObjectByType(type2, dictList);
			newValue = UtilMethods.ConvertToObjectList(type2, sourceList);
			fastestMethod = context.GetType().GetMethod("Fastest").MakeGenericMethod(type2)
