		private async Task<int> _BulkUpdate(List<T> datas, string[] whereColumns, string[] updateColumns)
		{
			bool isAuto = context.CurrentConnectionConfig.IsAutoCloseConnection;
			bool isAutoOk = false;
			bool old = context.Ado.IsDisableMasterSlaveSeparation;
			bool oldOk = false;
			try
			{
				Begin(datas, isAdd: false);
				Check.Exception(whereColumns == null || whereColumns.Count() == 0, "where columns count=0 or need primary key");
				Check.Exception(updateColumns == null || updateColumns.Count() == 0, "set columns count=0");
				context.CurrentConnectionConfig.IsAutoCloseConnection = false;
				context.Ado.IsDisableMasterSlaveSeparation = true;
				DataTable dt = ToDdateTable(datas);
				IFastBuilder buider = GetBuider();
				ActionIgnoreColums(whereColumns, updateColumns, dt, buider.IsActionUpdateColumns);
				buider.Context = context;
				await buider.CreateTempAsync<T>(dt);
				await buider.ExecuteBulkCopyAsync(dt);
				int result = await buider.UpdateByTempAsync(GetTableName(), dt.TableName, updateColumns, whereColumns);
				if (context.CurrentConnectionConfig.DbType != DbType.Sqlite)
				{
					context.DbMaintenance.DropTable(dt.TableName);
				}
				context.CurrentConnectionConfig.IsAutoCloseConnection = isAuto;
				isAutoOk = true;
				buider.CloseDb();
				context.Ado.IsDisableMasterSlaveSeparation = old;
				oldOk = true;
				End(datas, isAdd: false);
				return result;
			}
			catch (Exception)
			{
				context.Close();
				throw;
			}
			finally
			{
				if (!isAutoOk)
				{
					context.CurrentConnectionConfig.IsAutoCloseConnection = isAuto;
				}
				if (!oldOk)
				{
					context.Ado.IsDisableMasterSlaveSeparation = old;
				}
			}
		}

		private void ActionIgnoreColums(string[] whereColumns, string[] updateColumns, DataTable dt, bool IsActionUpdateColumns)
		{
			if (!((entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).Count() > whereColumns.Length + updateColumns.Length) & IsActionUpdateColumns))
			{
				return;
			}
			List<DataColumn> list = (from DataColumn it in dt.Columns
				where !whereColumns.Any((string y) => y.EqualCase(it.ColumnName))
				where !updateColumns.Any((string y) => y.EqualCase(it.ColumnName))
				select it).ToList();
			foreach (DataRow row in dt.Rows)
			{
				foreach (DataColumn item in list)
				{
					if (!row[item.ColumnName].IsNullOrEmpty())
					{
						continue;
					}
					if (item.DataType == UtilConstants.StringType)
					{
						row[item.ColumnName] = string.Empty;
						if (queryable?.SqlBuilder?.SqlParameterKeyWord == ":")
						{
							row[item.ColumnName] = " ";
						}
					}
					else if (item.DataType == UtilConstants.DateType)
					{
						row[item.ColumnName] = UtilMethods.GetMinDate(context.CurrentConnectionConfig);
					}
					else
					{
						row[item.ColumnName] = Activator.CreateInstance(item.DataType);
					}
				}
			}
		}

		private async Task<int> _BulkUpdate(string tableName, DataTable dataTable, string[] whereColumns, string[] updateColumns)
		{
			List<string> datas = new string[dataTable.Rows.Count].ToList();
			Begin(datas, isAdd: false);
			Check.Exception(whereColumns == null || whereColumns.Count() == 0, "where columns count=0 or need primary key");
			Check.Exception(updateColumns == null || updateColumns.Count() == 0, "set columns count=0");
			bool isAuto = context.CurrentConnectionConfig.IsAutoCloseConnection;
			context.CurrentConnectionConfig.IsAutoCloseConnection = false;
			bool old = context.Ado.IsDisableMasterSlaveSeparation;
			context.Ado.IsDisableMasterSlaveSeparation = true;
			dataTable.TableName = queryable.SqlBuilder.GetTranslationTableName(tableName);
			DataTable dt = GetCopyWriteDataTableUpdate(dataTable);
			IFastBuilder buider = GetBuider();
			if (dt.Columns.Count != dataTable.Columns.Count)
			{
				ActionIgnoreColums(whereColumns, updateColumns, dt, buider.IsActionUpdateColumns);
			}
			buider.Context = context;
			if (buider.DbFastestProperties == null)
			{
				buider.DbFastestProperties = new DbFastestProperties();
			}
			buider.DbFastestProperties.WhereColumns = whereColumns;
			await buider.CreateTempAsync<object>(dt);
			await buider.ExecuteBulkCopyAsync(dt);
			int result = await buider.UpdateByTempAsync(GetTableName(), dt.TableName, updateColumns, whereColumns);
			if (context.CurrentConnectionConfig.DbType != DbType.Sqlite)
			{
				context.DbMaintenance.DropTable(dt.TableName);
			}
			context.CurrentConnectionConfig.IsAutoCloseConnection = isAuto;
			buider.CloseDb();
			context.Ado.IsDisableMasterSlaveSeparation = old;
			End(datas, isAdd: false);
			return result;
		}

