		private void End<Type>(List<Type> datas, bool isAdd, bool isMerge = false)
		{
			string value = (isAdd ? "BulkCopy" : "BulkUpdate");
			if (isMerge)
			{
				value = "BulkMerge";
			}
			context.Ado.IsEnableLogEvent = isLog;
			if (context.CurrentConnectionConfig?.AopEvents?.OnLogExecuted != null)
			{
				context.CurrentConnectionConfig?.AopEvents?.OnLogExecuted($"End {value}  name:{GetTableName()} ,count: {datas.Count},current time: {DateTime.Now}", new SugarParameter[0]);
			}
			RemoveCache();
		}

		private void Begin<Type>(List<Type> datas, bool isAdd, bool isMerge = false)
		{
			string value = (isAdd ? "BulkCopy" : "BulkUpdate");
			if (isMerge)
			{
				value = "BulkMerge";
			}
			isLog = context.Ado.IsEnableLogEvent;
			context.Ado.IsEnableLogEvent = false;
			if (context.CurrentConnectionConfig?.AopEvents?.OnLogExecuting != null)
			{
				context.CurrentConnectionConfig?.AopEvents?.OnLogExecuting($"Begin {value} name:{GetTableName()} ,count: {datas.Count},current time: {DateTime.Now} ", new SugarParameter[0]);
			}
			Action<object, DataFilterModel> action = context.CurrentConnectionConfig.AopEvents?.DataExecuting;
			if (!IsDataAop || action == null)
			{
				return;
			}
			EntityInfo entity = context.EntityMaintenance.GetEntityInfo(typeof(Type));
			foreach (Type data in datas)
			{
				DataAop(data, isAdd ? DataFilterType.InsertByObject : DataFilterType.UpdateByObject, entity);
			}
		}

		private void DataAop<Type>(Type item, DataFilterType type, EntityInfo entity)
		{
			Action<object, DataFilterModel> action = context.CurrentConnectionConfig.AopEvents?.DataExecuting;
			if (action == null || item == null)
			{
				return;
			}
			foreach (EntityColumnInfo column in entity.Columns)
			{
				action(column.PropertyInfo.GetValue(item, null), new DataFilterModel
				{
					OperationType = type,
					EntityValue = item,
					EntityColumnInfo = column
				});
			}
		}

		private IFastBuilder GetBuider()
		{
			_ = string.Empty;
			switch (context.CurrentConnectionConfig.DbType)
			{
			case DbType.MySql:
				return new MySqlFastBuilder
				{
					CharacterSet = CharacterSet
				};
			case DbType.SqlServer:
				return new SqlServerFastBuilder
				{
					DbFastestProperties = 
					{
						IsOffIdentity = IsOffIdentity
					}
				};
			case DbType.Sqlite:
			{
				SqliteFastBuilder sqliteFastBuilder = new SqliteFastBuilder(entityInfo);
				if (sqliteFastBuilder.DbFastestProperties != null)
				{
					sqliteFastBuilder.DbFastestProperties.IsIgnoreInsertError = IsIgnoreInsertError;
				}
				return sqliteFastBuilder;
			}
			case DbType.Oracle:
				return new OracleFastBuilder(entityInfo);
			default:
			{
				IFastBuilder fastBuilder = InstanceFactory.CreateInstance<IFastBuilder>("Snet.DB.sugar." + context.CurrentConnectionConfig.DbType.ToString().Replace("Native", "") + "FastBuilder");
				fastBuilder.CharacterSet = CharacterSet;
				fastBuilder.FastEntityInfo = entityInfo;
				return fastBuilder;
			}
			}
		}

		private DataTable ToDdateTable(List<T> datas)
		{
			IFastBuilder buider = GetBuider();
			DataTable orCreate = ReflectionInoCore<DataTable>.GetInstance().GetOrCreate("BulkCopyAsync" + typeof(T).GetHashCode(), () => (AsName == null) ? queryable.Where((T it) => false).Select("*").ToDataTable() : (from it in queryable.AS(AsName)
				where false
				select it).Select("*").ToDataTable());
			DataTable dataTable = new DataTable();
			List<string> list = new List<string>();
			foreach (DataColumn column2 in orCreate.Columns)
			{
				if (column2.DataType == typeof(ulong))
				{
					list.Add(column2.ColumnName);
				}
				if (column2.DataType.Name == "ClickHouseDecimal")
				{
					dataTable.Columns.Add(column2.ColumnName, typeof(decimal));
				}
				else
				{
					dataTable.Columns.Add(column2.ColumnName, column2.DataType);
				}
			}
			bool flag = true;
			if (!flag)
			{
				foreach (EntityColumnInfo item in entityInfo.Columns.Where((EntityColumnInfo it) => it.IsIdentity))
				{
					if (dataTable.Columns.Contains(item.DbColumnName))
					{
						dataTable.Columns.Remove(item.DbColumnName);
					}
				}
			}
			dataTable.TableName = GetTableName();
			List<EntityColumnInfo> list2 = (flag ? entityInfo.Columns : entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIdentity).ToList());
			if (list2.Where((EntityColumnInfo it) => !it.IsIgnore).Count() > orCreate.Columns.Count)
			{
				IEnumerable<string> tempColumns = from DataColumn it in orCreate.Columns
					select it.ColumnName;
				list2 = list2.Where((EntityColumnInfo it) => tempColumns.Any((string s) => s.EqualCase(it.DbColumnName))).ToList();
			}
			MyTuple discrimator = GetDiscrimator();
			if (discrimator.isDiscrimator)
			{
				Dictionary<string, string> discrimatorDict = discrimator.discrimatorDict;
				if (discrimatorDict != null && discrimatorDict.Count > 0)
				{
					foreach (KeyValuePair<string, string> item2 in discrimator.discrimatorDict)
					{
						if (!dataTable.Columns.Contains(item2.Key))
						{
							dataTable.Columns.Add(item2.Key);
						}
					}
				}
			}
			bool flag2 = context.CurrentConnectionConfig.DbType.IsIn(default(DbType));
			bool flag3 = context.CurrentConnectionConfig.DbType.IsIn(DbType.Sqlite);
			foreach (T data in datas)
			{
				DataRow dataRow = dataTable.NewRow();
				foreach (EntityColumnInfo column in list2)
				{
					if (column.IsIgnore)
					{
						continue;
					}
					string text = column.DbColumnName;
					if (text == null)
					{
						text = column.PropertyName;
					}
					object obj = ValueConverter(column, GetValue(data, column));
					if (column.SqlParameterDbType != null && column.SqlParameterDbType is Type && UtilMethods.HasInterface((Type)column.SqlParameterDbType, typeof(ISugarDataConverter)))
					{
						EntityColumnInfo entityColumnInfo = column;
						Type type = entityColumnInfo.SqlParameterDbType as Type;
						MethodInfo methodInfo = type.GetMethod("ParameterConverter").MakeGenericMethod(entityColumnInfo.PropertyInfo.PropertyType);
						object obj2 = Activator.CreateInstance(type);
						obj = (methodInfo.Invoke(obj2, new object[2] { obj, 100 }) as SugarParameter).Value;
					}
					else if (flag2 && column.UnderType == UtilConstants.BoolType)
					{
						if (!obj.ObjToBool() && list.Any((string z) => z.EqualCase(column.DbColumnName)))
						{
							obj = DBNull.Value;
						}
					}
					else if (flag3 && column.UnderType == UtilConstants.StringType && obj is bool)
					{
						obj = "isSqliteCore_" + obj.ObjToString();
					}
					else if (flag3 && column.UnderType == UtilConstants.BoolType && obj is bool)
					{
						obj = (Convert.ToBoolean(obj) ? 1 : 0);
					}
					else if (column.UnderType == UtilConstants.DateTimeOffsetType && obj != null && obj != DBNull.Value)
					{
						if (buider.DbFastestProperties == null || !buider.DbFastestProperties.HasOffsetTime)
						{
							obj = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)obj);
						}
					}
					else if (obj != DBNull.Value && obj != null && column.UnderType?.FullName == "System.TimeOnly")
					{
						obj = UtilMethods.TimeOnlyToTimeSpan(obj);
					}
					else if (obj != DBNull.Value && obj != null && column.UnderType?.FullName == "System.DateOnly")
					{
						obj = UtilMethods.DateOnlyToDateTime(obj);
					}
					dataRow[text] = obj;
				}
				if (discrimator.isDiscrimator)
				{
					Dictionary<string, string> discrimatorDict2 = discrimator.discrimatorDict;
					if (discrimatorDict2 != null && discrimatorDict2.Count > 0)
					{
						foreach (KeyValuePair<string, string> item3 in discrimator.discrimatorDict)
						{
							string key = item3.Key;
							string value = item3.Value;
							if (!string.IsNullOrWhiteSpace(value) && string.IsNullOrWhiteSpace(dataRow[key]?.ToString() ?? ""))
							{
								dataRow[key] = value;
							}
						}
					}
				}
				dataTable.Rows.Add(dataRow);
			}
			return dataTable;
		}

		private static object GetValue(T item, EntityColumnInfo column)
		{
			if (StaticConfig.EnableAot)
			{
				return column.PropertyInfo.GetValue(item);
			}
			return PropertyCallAdapterProvider<T>.GetInstance(column.PropertyName).InvokeGet(item);
		}

		private string GetTableName()
		{
			if (AsName.HasValue())
			{
				return queryable.SqlBuilder.GetTranslationTableName(AsName);
			}
			return queryable.SqlBuilder.GetTranslationTableName(context.EntityMaintenance.GetTableName<T>());
		}

		private object ValueConverter(EntityColumnInfo columnInfo, object value)
		{
			if (value == null)
			{
				return DBNull.Value;
			}
			if (value is DateTime && (DateTime)value == DateTime.MinValue)
			{
				value = Convert.ToDateTime("1900-01-01");
			}
			else if (columnInfo.UnderType.IsEnum())
			{
				value = Convert.ToInt64(value);
			}
			else if (columnInfo.IsJson && value != null)
			{
				value = context.Utilities.SerializeObject(value);
			}
			else if (columnInfo.IsTranscoding && value.HasValue())
			{
				value = UtilMethods.EncodeBase64(value.ToString());
			}
			return value;
		}

		private DataTable GetCopyWriteDataTable(DataTable dt)
		{
			IFastBuilder buider = GetBuider();
			DbFastestProperties dbFastestProperties = buider.DbFastestProperties;
			if (dbFastestProperties != null && dbFastestProperties.IsConvertDateTimeOffsetToDateTime)
			{
				dt = UtilMethods.ConvertDateTimeOffsetToDateTime(dt);
			}
			DbFastestProperties dbFastestProperties2 = buider.DbFastestProperties;
			if (dbFastestProperties2 != null && dbFastestProperties2.IsNoCopyDataTable)
			{
				return dt;
			}
			DataTable dataTable = null;
			dataTable = ((AsName != null) ? (from it in queryable.Clone().AS(AsName)
				where false
				select it).Select("*").ToDataTable() : (from it in queryable.Clone()
				where false
				select it).Select("*").ToDataTable());
			List<string> list = new List<string>();
			foreach (DataColumn column2 in dataTable.Columns)
			{
				if (column2.DataType == typeof(ulong))
				{
					list.Add(column2.ColumnName);
				}
			}
			if (1 == 0 && (buider.DbFastestProperties == null || !buider.DbFastestProperties.IsOffIdentity))
			{
				string text = "";
				if (AsName != null)
				{
					text = context.DbMaintenance.GetColumnInfosByTableName(AsName).Find((DbColumnInfo f) => f.IsIdentity)?.DbColumnName;
				}
				else
				{
					text = entityInfo.Columns.Find((EntityColumnInfo f) => f.IsIdentity)?.DbColumnName;
				}
				if (!string.IsNullOrEmpty(text) && dataTable.Columns.Contains(text))
				{
					dataTable.Columns.Remove(text);
				}
			}
			List<string> temColumnsList = (from DataColumn it in dataTable.Columns
				select it.ColumnName.ToLower()).ToList();
			List<DataColumn> list2 = (from DataColumn it in dt.Columns
				where temColumnsList.Contains(it.ColumnName.ToLower())
				select it).ToList();
			foreach (DataRow row in dt.Rows)
			{
				DataRow dataRow2 = dataTable.NewRow();
				foreach (DataColumn column in list2)
				{
					dataRow2[column.ColumnName] = row[column.ColumnName];
					if (dataRow2[column.ColumnName] == null || dataRow2[column.ColumnName] == DBNull.Value)
					{
						dataRow2[column.ColumnName] = DBNull.Value;
					}
					else if (column.DataType == UtilConstants.BoolType && context.CurrentConnectionConfig.DbType.IsIn(default(DbType)) && !Convert.ToBoolean(dataRow2[column.ColumnName]) && list.Any((string z) => z.EqualCase(column.ColumnName)))
					{
						dataRow2[column.ColumnName] = DBNull.Value;
					}
				}
				dataTable.Rows.Add(dataRow2);
			}
			dataTable.TableName = dt.TableName;
			return dataTable;
		}

		private DataTable GetCopyWriteDataTableUpdate(DataTable dt)
		{
			ISqlBuilder sqlBuilder = context.Queryable<object>().SqlBuilder;
			List<string> values = (from DataColumn it in dt.Columns
				select sqlBuilder.GetTranslationColumnName(it.ColumnName)).ToList();
			DataTable dataTable = null;
			dataTable = ((AsName != null) ? (from it in queryable.Clone().AS(AsName)
				where false
				select it).Select(string.Join(",", values)).ToDataTable() : (from it in queryable.Clone()
				where false
				select it).Select(string.Join(",", values)).ToDataTable());
			List<string> list = new List<string>();
			foreach (DataColumn column2 in dataTable.Columns)
			{
				if (column2.DataType == typeof(ulong))
				{
					list.Add(column2.ColumnName);
				}
			}
			List<string> temColumnsList = (from DataColumn it in dataTable.Columns
				select it.ColumnName.ToLower()).ToList();
			List<DataColumn> list2 = (from DataColumn it in dt.Columns
				where temColumnsList.Contains(it.ColumnName.ToLower())
				select it).ToList();
			foreach (DataRow row in dt.Rows)
			{
				DataRow dataRow2 = dataTable.NewRow();
				foreach (DataColumn column in list2)
				{
					dataRow2[column.ColumnName] = row[column.ColumnName];
					if (dataRow2[column.ColumnName] == null || dataRow2[column.ColumnName] == DBNull.Value)
					{
						dataRow2[column.ColumnName] = DBNull.Value;
					}
					else if (column.DataType == UtilConstants.BoolType && context.CurrentConnectionConfig.DbType.IsIn(default(DbType)) && !Convert.ToBoolean(dataRow2[column.ColumnName]) && list.Any((string z) => z.EqualCase(column.ColumnName)))
					{
						dataRow2[column.ColumnName] = DBNull.Value;
					}
				}
				dataTable.Rows.Add(dataRow2);
			}
			dataTable.TableName = dt.TableName;
			return dataTable;
		}

		private void RemoveCache()
		{
			if (!string.IsNullOrEmpty(CacheKey) || !string.IsNullOrEmpty(CacheKeyLike))
			{
				Check.Exception(context.CurrentConnectionConfig.ConfigureExternalServices?.DataInfoCacheService == null, "ConnectionConfig.ConfigureExternalServices.DataInfoCacheService is null");
				ICacheService cacheService = context.CurrentConnectionConfig.ConfigureExternalServices?.DataInfoCacheService;
				if (!string.IsNullOrEmpty(CacheKey))
				{
					CacheSchemeMain.RemoveCache(cacheService, CacheKey);
				}
				if (!string.IsNullOrEmpty(CacheKeyLike))
				{
					CacheSchemeMain.RemoveCacheByLike(cacheService, CacheKeyLike);
				}
			}
			ConnectionConfig currentConnectionConfig = context.CurrentConnectionConfig;
			if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.IsAutoRemoveDataCache == true)
			{
				ICacheService cacheService2 = context.CurrentConnectionConfig?.ConfigureExternalServices?.DataInfoCacheService;
				if (cacheService2 != null)
				{
					CacheSchemeMain.RemoveCache(cacheService2, context.EntityMaintenance.GetTableName<T>());
				}
			}
		}

		private MyTuple GetDiscrimator()
		{
			bool flag = entityInfo.Discrimator.HasValue();
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			if (flag)
			{
				Check.ExceptionEasy(!Regex.IsMatch(entityInfo.Discrimator, "^(?:\\w+:\\w+)(?:,\\w+:\\w+)*$"), "The format should be type:cat for this type, and if there are multiple, it can be FieldName:cat,FieldName2:dog ", "格式错误应该是type:cat这种格式，如果是多个可以FieldName:cat,FieldName2:dog，不要有空格");
				string[] array = entityInfo.Discrimator.Split(',');
				foreach (string obj in array)
				{
					string key = obj.Split(':').First();
					string value = obj.Split(':').Last();
					if (!dictionary.ContainsKey(key))
					{
						dictionary.Add(key, value);
					}
				}
			}
			return new MyTuple(flag, dictionary);
		}

