	public class SplitFastest<T> where T : class, new()
	{
		internal class GroupModel
		{
			public string GroupName { get; set; }

			public T Item { get; set; }
		}

		public FastestProvider<T> FastestProvider { get; set; }

		public SqlSugarProvider Context => FastestProvider.context;

		public EntityInfo EntityInfo => Context.EntityMaintenance.GetEntityInfo<T>();

		public int BulkCopy(List<T> datas)
		{
			if (StaticConfig.SplitTableCreateTableFunc != null)
			{
				StaticConfig.SplitTableCreateTableFunc(typeof(T), datas?.Cast<object>()?.ToArray());
			}
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				CreateTable(item.Key);
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				result += FastestProvider.AS(item.Key).BulkCopy(datas2);
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
			}
			return result;
		}

		public async Task<int> BulkCopyAsync(List<T> datas)
		{
			if (StaticConfig.SplitTableCreateTableFunc != null)
			{
				StaticConfig.SplitTableCreateTableFunc(typeof(T), datas?.Cast<object>()?.ToArray());
			}
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				CreateTable(item.Key);
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				int num = result;
				result = num + await FastestProvider.AS(item.Key).BulkCopyAsync(datas2);
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
			}
			return result;
		}

		public int BulkUpdate(List<T> datas)
		{
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				CreateTable(item.Key);
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				result += FastestProvider.AS(item.Key).BulkUpdate(datas2);
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
			}
			return result;
		}

		public async Task<int> BulkUpdateAsync(List<T> datas)
		{
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				CreateTable(item.Key);
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				int num = result;
				result = num + await FastestProvider.AS(item.Key).BulkUpdateAsync(datas2);
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
			}
			return result;
		}

		public int BulkUpdate(List<T> datas, string[] wherColumns, string[] updateColumns)
		{
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				result += FastestProvider.AS(item.Key).BulkUpdate(datas2, wherColumns, updateColumns);
			}
			return result;
		}

		public async Task<int> BulkUpdateAsync(List<T> datas, string[] wherColumns, string[] updateColumns)
		{
			GroupDataList(datas, out List<GroupModel> groupModels, out int result);
			foreach (IGrouping<string, GroupModel> item in from it in groupModels
				group it by it.GroupName)
			{
				List<T> datas2 = item.Select((GroupModel it) => it.Item).ToList();
				int num = result;
				result = num + await FastestProvider.AS(item.Key).BulkUpdateAsync(datas2, wherColumns, updateColumns);
			}
			return result;
		}

		private void CreateTable(string tableName)
		{
			bool isEnableLogEvent = Context.Ado.IsEnableLogEvent;
			Context.Ado.IsEnableLogEvent = false;
			if (!Context.DbMaintenance.IsAnyTable(tableName, isCache: false))
			{
				Context.MappingTables.Add(EntityInfo.EntityName, tableName);
				Context.CodeFirst.InitTables<T>();
			}
			Context.Ado.IsEnableLogEvent = isEnableLogEvent;
		}

		private void GroupDataList(List<T> datas, out List<GroupModel> groupModels, out int result)
		{
			SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
			Check.Exception(customAttribute == null, typeof(T).Name + " need SplitTableAttribute");
			groupModels = new List<GroupModel>();
			SqlSugarProvider context = FastestProvider.context;
			bool flag = typeof(T).GetProperties().Any((PropertyInfo it) => it.GetCustomAttribute<SplitFieldAttribute>() != null);
			foreach (T data in datas)
			{
				if (groupModels.Count > 0 && !flag)
				{
					groupModels.Add(new GroupModel
					{
						GroupName = groupModels[0].GroupName,
						Item = data
					});
				}
				else
				{
					object value = context.SplitHelper<T>().GetValue(customAttribute.SplitType, data);
					string tableName = context.SplitHelper<T>().GetTableName(customAttribute.SplitType, value);
					groupModels.Add(new GroupModel
					{
						GroupName = tableName,
						Item = data
					});
				}
			}
			result = 0;
		}
	}
	public class QueryFilterProvider : IFilter
	{
		public enum FilterJoinPosition
		{
			On,
			Where
		}

		internal SqlSugarProvider Context { get; set; }

		private List<SqlFilterItem> _Filters { get; set; }

		private List<SqlFilterItem> _BackUpFilters { get; set; }

		public List<SqlFilterItem> GetFilterList
		{
			get
			{
				if (_Filters == null)
				{
					_Filters = new List<SqlFilterItem>();
				}
				return _Filters;
			}
		}

		public bool Any()
		{
			if (_Filters != null)
			{
				return _Filters.Any();
			}
			return false;
		}

		public IFilter Add(SqlFilterItem filter)
		{
			if (_Filters == null)
			{
				_Filters = new List<SqlFilterItem>();
			}
			_Filters.Add(filter);
			return this;
		}

		public void Remove(string filterName)
		{
			if (_Filters == null)
			{
				_Filters = new List<SqlFilterItem>();
			}
			_Filters.RemoveAll((SqlFilterItem it) => it.FilterName == filterName);
		}

		public void Clear()
		{
			_Filters = new List<SqlFilterItem>();
		}

		public void Clear<T>()
		{
			_Filters = _Filters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>)).ToList();
		}

		public void Clear(params Type[] types)
		{
			_Filters = _Filters.Where((SqlFilterItem it) => !Enumerable.Contains(types, it.type)).ToList();
		}

		public void Clear<T, T2>()
		{
			_Filters = _Filters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>) && !(it is TableFilterItem<T2>)).ToList();
		}

		public void Clear<T, T2, T3>()
		{
			_Filters = _Filters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>) && !(it is TableFilterItem<T2>) && !(it is TableFilterItem<T3>)).ToList();
		}

		public void ClearAndBackup()
		{
			_BackUpFilters = _Filters;
			_Filters = new List<SqlFilterItem>();
		}

		public void ClearAndBackup<T>()
		{
			_BackUpFilters = _Filters;
			_Filters = _BackUpFilters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>)).ToList();
		}

		public void ClearAndBackup<T, T2>()
		{
			_BackUpFilters = _Filters;
			_Filters = _BackUpFilters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>) && !(it is TableFilterItem<T2>)).ToList();
		}

		public void ClearAndBackup<T, T2, T3>()
		{
			_BackUpFilters = _Filters;
			_Filters = _BackUpFilters.Where((SqlFilterItem it) => !(it is TableFilterItem<T>) && !(it is TableFilterItem<T2>) && !(it is TableFilterItem<T3>)).ToList();
		}

		public void ClearAndBackup(params Type[] types)
		{
			_BackUpFilters = _Filters;
			_Filters = _BackUpFilters.Where((SqlFilterItem it) => !Enumerable.Contains(types, it.type)).ToList();
		}

		public void Restore()
		{
			_Filters = _BackUpFilters;
			if (_Filters == null)
			{
				_Filters = new List<SqlFilterItem>();
			}
		}

		public QueryFilterProvider AddTableFilter<T>(Expression<Func<T, bool>> expression, FilterJoinPosition filterJoinType = FilterJoinPosition.On)
		{
			bool isJoinOn = filterJoinType == FilterJoinPosition.On;
			TableFilterItem<T> filter = new TableFilterItem<T>(expression, isJoinOn);
			Add(filter);
			return this;
		}

		public QueryFilterProvider AddTableFilterIF<T>(bool isAppendFilter, Expression<Func<T, bool>> expression, FilterJoinPosition filterJoinType = FilterJoinPosition.On)
		{
			if (isAppendFilter)
			{
				AddTableFilter(expression, filterJoinType);
			}
			return this;
		}

		public QueryFilterProvider AddTableFilter(Type type, string shortName, FormattableString expString, FilterJoinPosition filterJoinType = FilterJoinPosition.On)
		{
			LambdaExpression expression = DynamicCoreHelper.GetWhere(type, shortName, expString);
			return AddTableFilter(type, expression, filterJoinType);
		}

		public QueryFilterProvider AddTableFilter(Type type, Expression expression, FilterJoinPosition filterJoinType = FilterJoinPosition.On)
		{
			bool isJoinOn = filterJoinType == FilterJoinPosition.On;
			Add(new TableFilterItem<object>(type, expression, isJoinOn));
			return this;
		}

		public QueryFilterProvider AddTableFilterIF(bool isAppendFilter, Type type, Expression expression, FilterJoinPosition posType = FilterJoinPosition.On)
		{
			if (isAppendFilter)
			{
				AddTableFilter(type, expression, posType);
			}
			return this;
		}
	}
	public class GridSaveProvider<T> where T : class, new()
	{
		internal SqlSugarProvider Context { get; set; }

		internal List<T> OldList { get; set; }

		internal List<T> SaveList { get; set; }

		internal bool IsIncluesFirstAll { get; set; }

		internal string[] IgnoreColumnsSaveInclues { get; set; }

		public bool ExecuteCommand()
		{
			List<T> deleteList = GetDeleteList();
			Context.Deleteable(deleteList).PageSize(1000).ExecuteCommand();
			if (IsIncludesSave())
			{
				Context.Utilities.PageEach(SaveList, 1000, delegate(List<T> pageList)
				{
					UpdateNavRootOptions rootOptions = new UpdateNavRootOptions
					{
						IsInsertRoot = true
					};
					Context.UpdateNav(pageList, rootOptions).IncludesAllFirstLayer(IgnoreColumnsSaveInclues).ExecuteCommand();
				});
			}
			else
			{
				Context.Storageable(SaveList).PageSize(1000).ExecuteCommand();
			}
			return true;
		}

		public async Task<bool> ExecuteCommandAsync()
		{
			List<T> deleteList = GetDeleteList();
			await Context.Deleteable(deleteList).PageSize(1000).ExecuteCommandAsync();
			if (!IsIncludesSave())
			{
				await Context.Storageable(SaveList).PageSize(1000).ExecuteCommandAsync();
			}
			else
			{
				await Context.Utilities.PageEachAsync(SaveList, 1000, async delegate(List<T> pageList)
				{
					UpdateNavRootOptions rootOptions = new UpdateNavRootOptions
					{
						IsInsertRoot = true
					};
					await Context.UpdateNav(pageList, rootOptions).IncludesAllFirstLayer(IgnoreColumnsSaveInclues).ExecuteCommandAsync();
				});
			}
			return true;
		}

		public List<T> GetDeleteList()
		{
			string[] primaryKeys = (from it in Context.EntityMaintenance.GetEntityInfo<T>().Columns
				where it.IsPrimarykey
				select it.PropertyName).ToArray();
			var saveListDictionary = SaveList.Select((T item) => new
			{
				Key = CreateCompositeKey(primaryKeys, item),
				Value = item
			});
			return OldList.Where(delegate(T oldItem)
			{
				string compositeKey = CreateCompositeKey(primaryKeys, oldItem);
				return !saveListDictionary.Any(it => it.Key == compositeKey);
			}).ToList();
		}

		public GridSaveProvider<T> IncludesAllFirstLayer(params string[] ignoreColumns)
		{
			IsIncluesFirstAll = true;
			IgnoreColumnsSaveInclues = ignoreColumns;
			return this;
		}

		private bool IsIncludesSave()
		{
			if (IsIncluesFirstAll)
			{
				return Context.EntityMaintenance.GetEntityInfo<T>().Columns.Any((EntityColumnInfo it) => it.Navigat != null);
			}
			return false;
		}

		private string CreateCompositeKey(string[] propertyNames, object obj)
		{
			IEnumerable<string> values = propertyNames.Select((string propertyName) => GetPropertyValue(obj, propertyName)?.ToString() ?? "");
			return string.Join("|", values);
		}

		private object GetPropertyValue(object obj, string propertyName)
		{
			PropertyInfo property = obj.GetType().GetProperty(propertyName);
			if (!(property != null))
			{
				return null;
			}
			return property.GetValue(obj);
		}
	}
	public class InsertableProvider<T> : IInsertable<T> where T : class, new()
	{
		public SqlSugarProvider Context { get; set; }

		public IAdo Ado => Context.Ado;

		public ISqlBuilder SqlBuilder { get; set; }

		public InsertBuilder InsertBuilder { get; set; }

		public bool IsMappingTable
		{
			get
			{
				if (Context.MappingTables != null)
				{
					return Context.MappingTables.Any();
				}
				return false;
			}
		}

		public bool IsMappingColumns
		{
			get
			{
				if (Context.MappingColumns != null)
				{
					return Context.MappingColumns.Any();
				}
				return false;
			}
		}

		public bool IsSingle => InsertObjs.Length == 1;

		public EntityInfo EntityInfo { get; set; }

		public List<MappingColumn> MappingColumnList { get; set; }

		private List<string> IgnoreColumnNameList { get; set; }

		internal bool IsOffIdentity { get; set; }

		public T[] InsertObjs { get; set; }

		public MappingTableList OldMappingTableList { get; set; }

		public bool IsAs { get; set; }

		public bool IsEnableDiffLogEvent { get; set; }

		public DiffLogModel diffModel { get; set; }

		internal Action RemoveCacheFunc { get; set; }

		private string _ExecuteReturnBigIdentity()
		{
			InsertBuilder.IsReturnIdentity = true;
			PreToSql();
			AutoRemoveDataCache();
			string text = InsertBuilder.ToSqlString();
			RestoreMapping();
			Before(text);
			return text;
		}

		private string _ExecuteReturnIdentity()
		{
			InsertBuilder.IsReturnIdentity = true;
			PreToSql();
			AutoRemoveDataCache();
			string text = InsertBuilder.ToSqlString();
			RestoreMapping();
			Before(text);
			return text;
		}

		private string _ExecuteCommand()
		{
			if (InsertBuilder.DbColumnInfoList.HasValue())
			{
				List<string> primaryKeys = GetPrimaryKeys();
				foreach (DbColumnInfo item in InsertBuilder.DbColumnInfoList)
				{
					if ((!primaryKeys.Any((string y) => y.Equals(item.DbColumnName, StringComparison.CurrentCultureIgnoreCase)) && !item.IsPrimarykey) || !(item.PropertyType == UtilConstants.GuidType) || !(item.Value is Guid guid) || !(guid == Guid.Empty))
					{
						continue;
					}
					if (StaticConfig.CustomGuidFunc != null)
					{
						item.Value = StaticConfig.CustomGuidFunc();
					}
					else if (StaticConfig.CustomGuidByValueFunc != null && item.Value is Guid arg)
					{
						item.Value = StaticConfig.CustomGuidByValueFunc(arg);
					}
					else
					{
						item.Value = Guid.NewGuid();
					}
					if (InsertObjs.First().GetType().GetProperties()
						.Any((PropertyInfo it) => it.Name == item.PropertyName))
					{
						InsertObjs.First().GetType().GetProperties()
							.First((PropertyInfo it) => it.Name == item.PropertyName)
							.SetValue(InsertObjs.First(), item.Value, null);
					}
				}
			}
			InsertBuilder.IsReturnIdentity = false;
			PreToSql();
			AutoRemoveDataCache();
			string text = InsertBuilder.ToSqlString();
			RestoreMapping();
			Before(text);
			return text;
		}

		protected void AutoRemoveDataCache()
		{
			ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
			ConfigureExternalServices configureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
			if (moreSettings != null && moreSettings.IsAutoRemoveDataCache && configureExternalServices != null && configureExternalServices.DataInfoCacheService != null)
			{
				RemoveDataCache();
			}
		}

		protected virtual void PreToSql()
		{
			if (!IsOffIdentity)
			{
				List<string> identities = GetIdentityKeys();
				if (identities != null && identities.Any())
				{
					InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !identities.Any((string i) => it.DbColumnName.Equals(i, StringComparison.CurrentCultureIgnoreCase))).ToList();
				}
			}
			if (Context.IgnoreColumns != null && Context.IgnoreColumns.Any())
			{
				List<IgnoreColumn> currentIgnoreColumns = Context.IgnoreColumns.Where((IgnoreColumn it) => it.EntityName == EntityInfo.EntityName).ToList();
				InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !currentIgnoreColumns.Any((IgnoreColumn i) => it.PropertyName.Equals(i.PropertyName, StringComparison.CurrentCulture))).ToList();
			}
			if (Context.IgnoreInsertColumns != null && Context.IgnoreInsertColumns.Any())
			{
				List<IgnoreColumn> currentIgnoreColumns2 = Context.IgnoreInsertColumns.Where((IgnoreColumn it) => it.EntityName == EntityInfo.EntityName).ToList();
				InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !currentIgnoreColumns2.Any((IgnoreColumn i) => it.PropertyName.Equals(i.PropertyName, StringComparison.CurrentCulture))).ToList();
			}
			if (!IsSingle)
			{
				return;
			}
			bool flag = EntityInfo.DbTableName.StartsWith("Dictionary`");
			foreach (DbColumnInfo dbColumnInfo in InsertBuilder.DbColumnInfoList)
			{
				if (InsertBuilder.Parameters == null)
				{
					InsertBuilder.Parameters = new List<SugarParameter>();
				}
				SugarParameter sugarParameter = new SugarParameter(SqlBuilder.SqlParameterKeyWord + dbColumnInfo.DbColumnName, dbColumnInfo.Value, dbColumnInfo.PropertyType);
				if ((InsertBuilder.IsNoInsertNull && sugarParameter.Value == null) || dbColumnInfo.SqlParameterDbType is Type)
				{
					continue;
				}
				if (dbColumnInfo.SqlParameterDbType is System.Data.DbType dbType)
				{
					sugarParameter.DbType = dbType;
				}
				if (dbColumnInfo.IsJson)
				{
					sugarParameter.IsJson = true;
					SqlBuilder.ChangeJsonType(sugarParameter);
				}
				if (dbColumnInfo.IsArray)
				{
					sugarParameter.IsArray = true;
					if (dbColumnInfo.Value == null || dbColumnInfo.Value == DBNull.Value)
					{
						ArrayNull(dbColumnInfo, sugarParameter);
					}
				}
				if ((dbColumnInfo.Value == null) & flag)
				{
					Type nullType = SqlBuilder.GetNullType(InsertBuilder.GetTableNameString, dbColumnInfo.DbColumnName);
					if (nullType != null)
					{
						sugarParameter = new SugarParameter(SqlBuilder.SqlParameterKeyWord + dbColumnInfo.DbColumnName, dbColumnInfo.Value, nullType);
					}
				}
				InsertBuilder.Parameters.Add(sugarParameter);
			}
		}

		private static void ArrayNull(DbColumnInfo item, SugarParameter parameter)
		{
			if (item.PropertyType.IsIn(new Type[2]
			{
				typeof(Guid[]),
				typeof(Guid?[])
			}))
			{
				parameter.DbType = System.Data.DbType.Guid;
			}
			else if (item.PropertyType.IsIn(new Type[2]
			{
				typeof(int[]),
				typeof(int?[])
			}))
			{
				parameter.DbType = System.Data.DbType.Int32;
			}
			else if (item.PropertyType.IsIn(new Type[2]
			{
				typeof(long[]),
				typeof(long?[])
			}))
			{
				parameter.DbType = System.Data.DbType.Int64;
			}
			else if (item.PropertyType.IsIn(new Type[2]
			{
				typeof(short[]),
				typeof(short?[])
			}))
			{
				parameter.DbType = System.Data.DbType.Int16;
			}
		}

		internal void Init()
		{
			InsertBuilder.EntityInfo = EntityInfo;
			Check.Exception(InsertObjs == null || InsertObjs.Count() == 0, "InsertObjs is null");
			int num = 0;
			T[] insertObjs = InsertObjs;
			foreach (T val in insertObjs)
			{
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				if (val is Dictionary<string, string>)
				{
					Check.ExceptionEasy("To use Insertable dictionary, use string or object", "Insertable字典请使用string,object类型");
				}
				if (val is Dictionary<string, object>)
				{
					SetInsertItemByDic(num, val, list);
				}
				else
				{
					DataAop(val);
					SetInsertItemByEntity(num, val, list);
				}
				InsertBuilder.DbColumnInfoList.AddRange(list);
				num++;
			}
		}

		private void DataAop(T item)
		{
			Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataExecuting;
			if (action == null || item == null)
			{
				return;
			}
			foreach (EntityColumnInfo column in EntityInfo.Columns)
			{
				if (column.ForOwnsOnePropertyInfo != null)
				{
					object value = column.ForOwnsOnePropertyInfo.GetValue(item, null);
					if (value != null)
					{
						action(column.PropertyInfo.GetValue(value, null), new DataFilterModel
						{
							OperationType = DataFilterType.InsertByObject,
							EntityValue = item,
							EntityColumnInfo = column
						});
					}
				}
				else if (!(column.PropertyInfo.Name == "Item") || !column.IsIgnore)
				{
					action(column.PropertyInfo.GetValue(item, null), new DataFilterModel
					{
						OperationType = DataFilterType.InsertByObject,
						EntityValue = item,
						EntityColumnInfo = column
					});
				}
			}
		}

		private void DataChangeAop(T[] items)
		{
			Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataChangesExecuted;
			if (action == null)
			{
				return;
			}
			foreach (T val in items)
			{
				if (val == null || val is Dictionary<string, object>)
				{
					continue;
				}
				foreach (EntityColumnInfo column in EntityInfo.Columns)
				{
					if (column.ForOwnsOnePropertyInfo != null)
					{
						object value = column.ForOwnsOnePropertyInfo.GetValue(val, null);
						if (value != null)
						{
							action(column.PropertyInfo.GetValue(value, null), new DataFilterModel
							{
								OperationType = DataFilterType.InsertByObject,
								EntityValue = val,
								EntityColumnInfo = column
							});
						}
					}
					else if (!(column.PropertyInfo.Name == "Item") || !column.IsIgnore)
					{
						action(column.PropertyInfo.GetValue(val, null), new DataFilterModel
						{
							OperationType = DataFilterType.InsertByObject,
							EntityValue = val,
							EntityColumnInfo = column
						});
					}
				}
			}
		}

		private void SetInsertItemByDic(int i, T item, List<DbColumnInfo> insertItem)
		{
			foreach (KeyValuePair<string, object> item2 in (item as Dictionary<string, object>).OrderBy((KeyValuePair<string, object> it) => it.Key))
			{
				DbColumnInfo dbColumnInfo = new DbColumnInfo
				{
					Value = item2.Value,
					DbColumnName = item2.Key,
					PropertyName = item2.Key,
					PropertyType = ((item2.Value == null) ? DBNull.Value.GetType() : UtilMethods.GetUnderType(item2.Value.GetType())),
					TableId = i
				};
				if (dbColumnInfo.PropertyType?.FullName == "System.Text.Json.JsonElement")
				{
					dbColumnInfo.Value = item2.Value.ObjToString();
				}
				if (dbColumnInfo.PropertyType.IsEnum())
				{
					ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						dbColumnInfo.Value = dbColumnInfo.Value.ToString();
						dbColumnInfo.PropertyType = UtilConstants.StringType;
					}
					else
					{
						dbColumnInfo.Value = Convert.ToInt64(dbColumnInfo.Value);
					}
				}
				insertItem.Add(dbColumnInfo);
			}
		}

		private void SetInsertItemByEntity(int i, T item, List<DbColumnInfo> insertItem)
		{
			if (item == null)
			{
				return;
			}
			foreach (EntityColumnInfo column in EntityInfo.Columns)
			{
				if (column.IsIgnore || column.IsOnlyIgnoreInsert)
				{
					continue;
				}
				bool isMappingColumns = IsMappingColumns;
				DbColumnInfo dbColumnInfo = new DbColumnInfo
				{
					Value = GetValue(item, column),
					DbColumnName = column.DbColumnName,
					PropertyName = column.PropertyName,
					PropertyType = UtilMethods.GetUnderType(column.PropertyInfo),
					TableId = i,
					InsertSql = column.InsertSql,
					InsertServerTime = column.InsertServerTime,
					DataType = column.DataType,
					SqlParameterDbType = column.SqlParameterDbType,
					IsIdentity = column.IsIdentity
				};
				if (column.DbColumnName == null)
				{
					column.DbColumnName = column.PropertyName;
				}
				if (isMappingColumns && column.ForOwnsOnePropertyInfo == null)
				{
					dbColumnInfo.DbColumnName = GetDbColumnName(column.PropertyName);
				}
				if (column.IsJson)
				{
					dbColumnInfo.IsJson = true;
				}
				if (column.IsArray)
				{
					dbColumnInfo.IsArray = true;
				}
				if (dbColumnInfo.PropertyType.IsEnum() && dbColumnInfo.Value != null)
				{
					ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						dbColumnInfo.Value = dbColumnInfo.Value.ToString();
						dbColumnInfo.PropertyType = UtilConstants.StringType;
					}
					else
					{
						dbColumnInfo.Value = Convert.ToInt64(dbColumnInfo.Value);
					}
				}
				if (column.IsJson && dbColumnInfo.Value != null)
				{
					if (InsertBuilder.SerializeObjectFunc != null && dbColumnInfo.Value != null)
					{
						dbColumnInfo.Value = InsertBuilder.SerializeObjectFunc(dbColumnInfo.Value);
					}
					else if (dbColumnInfo.Value != null)
					{
						dbColumnInfo.Value = Context.Utilities.SerializeObject(dbColumnInfo.Value);
					}
				}
				if (column.IsTranscoding && dbColumnInfo.Value.HasValue())
				{
					dbColumnInfo.Value = UtilMethods.EncodeBase64(dbColumnInfo.Value.ToString());
				}
				insertItem.Add(dbColumnInfo);
			}
			if (EntityInfo.Discrimator.HasValue())
			{
				Check.ExceptionEasy(!Regex.IsMatch(EntityInfo.Discrimator, "^(?:\\w+:\\w+)(?:,\\w+:\\w+)*$"), "The format should be type:cat for this type, and if there are multiple, it can be FieldName:cat,FieldName2:dog ", "格式错误应该是type:cat这种格式，如果是多个可以FieldName:cat,FieldName2:dog，不要有空格");
				string[] array = EntityInfo.Discrimator.Split(',');
				foreach (string obj in array)
				{
					string text = obj.Split(':').First();
					string value = obj.Split(':').Last();
					insertItem.Add(new DbColumnInfo
					{
						TableId = i,
						DbColumnName = text,
						PropertyName = text,
						PropertyType = typeof(string),
						Value = value
					});
				}
			}
		}

		private static object GetValue(T item, EntityColumnInfo column)
		{
			if (column.ForOwnsOnePropertyInfo != null)
			{
				object value = column.ForOwnsOnePropertyInfo.GetValue(item, null);
				return column.PropertyInfo.GetValue(value, null);
			}
			if (StaticConfig.EnableAot)
			{
				return column.PropertyInfo.GetValue(item, null);
			}
			return PropertyCallAdapterProvider<T>.GetInstance(column.PropertyName).InvokeGet(item);
		}

		private string GetDbColumnName(string propertyName)
		{
			if (!IsMappingColumns)
			{
				return propertyName;
			}
			if (Context.MappingColumns.Any((MappingColumn it) => it.EntityName.Equals(EntityInfo.EntityName, StringComparison.CurrentCultureIgnoreCase)))
			{
				MappingColumnList = Context.MappingColumns.Where((MappingColumn it) => it.EntityName.Equals(EntityInfo.EntityName, StringComparison.CurrentCultureIgnoreCase)).ToList();
			}
			if (MappingColumnList == null || !MappingColumnList.Any())
			{
				return propertyName;
			}
			MappingColumn mappingColumn = MappingColumnList.FirstOrDefault((MappingColumn it) => it.PropertyName.Equals(propertyName, StringComparison.CurrentCultureIgnoreCase));
			if (mappingColumn != null)
			{
				return mappingColumn.DbColumnName;
			}
			return propertyName;
		}

		protected virtual List<string> GetPrimaryKeys()
		{
			if (Context.IsSystemTablesConfig)
			{
				return Context.DbMaintenance.GetPrimaries(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
			}
			return (from it in EntityInfo.Columns
				where it.IsPrimarykey
				select it.DbColumnName).ToList();
		}

		protected virtual List<string> GetIdentityKeys()
		{
			if (Context.IsSystemTablesConfig)
			{
				return Context.DbMaintenance.GetIsIdentities(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
			}
			return (from it in EntityInfo.Columns.Where(delegate(EntityColumnInfo it)
				{
					if (StaticConfig.Check_StringIdentity)
					{
						Check.ExceptionEasy(it.IsIdentity && it.UnderType == typeof(string), "Auto-incremented is not a string, how can I use a executable startup configuration: StaticConfig.Check_StringIdentity=false ", "自增不是能string,如何非要用可以程序启动配置：StaticConfig.Check_StringIdentity=false");
					}
					return it.IsIdentity;
				})
				select it.DbColumnName).ToList();
		}

		protected void RestoreMapping()
		{
			if (IsAs)
			{
				Context.MappingTables = OldMappingTableList;
			}
		}

		protected void After(string sql, long? result)
		{
			if (IsEnableDiffLogEvent)
			{
				bool isDisableMasterSlaveSeparation = Ado.IsDisableMasterSlaveSeparation;
				Ado.IsDisableMasterSlaveSeparation = true;
				if (InsertBuilder.Parameters == null)
				{
					new List<SugarParameter>();
				}
				diffModel.AfterData = GetDiffTable(sql, result);
				diffModel.Time = Context.Ado.SqlExecutionTime;
				if (Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent != null)
				{
					Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent(diffModel);
				}
				Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
			}
			if (RemoveCacheFunc != null)
			{
				RemoveCacheFunc();
			}
			DataChangeAop(InsertObjs);
		}

		protected void Before(string sql)
		{
			if (IsEnableDiffLogEvent)
			{
				bool isDisableMasterSlaveSeparation = Ado.IsDisableMasterSlaveSeparation;
				Ado.IsDisableMasterSlaveSeparation = true;
				List<SugarParameter> list = InsertBuilder.Parameters;
				if (list == null)
				{
					list = new List<SugarParameter>();
				}
				diffModel.BeforeData = null;
				diffModel.Sql = sql;
				diffModel.Parameters = list.ToArray();
				Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
			}
		}

		private List<DiffLogTableInfo> GetDiffTable(string sql, long? identity)
		{
			if (GetIdentityKeys().HasValue() && InsertObjs.Count() > 1)
			{
				return GetDiffTableByEntity();
			}
			if (GetIdentityKeys().IsNullOrEmpty())
			{
				return GetDiffTableByEntity();
			}
			return GetDiffTableBySql(identity);
		}

		private List<DiffLogTableInfo> GetDiffTableByEntity()
		{
			new List<SugarParameter>();
			List<DiffLogTableInfo> list = new List<DiffLogTableInfo>();
			DataTable dataTable = Context.Utilities.ListToDataTable(InsertObjs.ToList());
			foreach (DataRow row in dataTable.Rows)
			{
				DiffLogTableInfo diffLogTableInfo = new DiffLogTableInfo();
				diffLogTableInfo.TableDescription = EntityInfo.TableDescription;
				diffLogTableInfo.TableName = EntityInfo.DbTableName;
				diffLogTableInfo.Columns = new List<DiffLogColumnInfo>();
				foreach (DataColumn col in dataTable.Columns)
				{
					EntityColumnInfo entityColumnInfo = EntityInfo.Columns.Where((EntityColumnInfo it) => it.DbColumnName != null).FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(col.ColumnName, StringComparison.CurrentCultureIgnoreCase));
					DiffLogColumnInfo diffLogColumnInfo = new DiffLogColumnInfo();
					diffLogColumnInfo.Value = row[col.ColumnName];
					diffLogColumnInfo.ColumnName = entityColumnInfo?.DbColumnName ?? col.ColumnName;
					diffLogColumnInfo.IsPrimaryKey = entityColumnInfo?.IsPrimarykey ?? false;
					diffLogColumnInfo.ColumnDescription = entityColumnInfo?.ColumnDescription;
					diffLogTableInfo.Columns.Add(diffLogColumnInfo);
				}
				list.Add(diffLogTableInfo);
			}
			return list;
		}

		private List<DiffLogTableInfo> GetDiffTableBySql(long? identity)
		{
			List<SugarParameter> list = new List<SugarParameter>();
			List<DiffLogTableInfo> list2 = new List<DiffLogTableInfo>();
			string empty = string.Empty;
			List<IConditionalModel> list3 = new List<IConditionalModel>();
			if (identity.HasValue && identity > 0 && GetIdentityKeys().HasValue())
			{
				string fieldName = GetIdentityKeys().Last();
				list3.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.Equal,
					FieldName = fieldName,
					FieldValue = identity.ToString()
				});
			}
			else
			{
				foreach (EntityColumnInfo item in EntityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore && GetPrimaryKeys().Any((string pk) => pk.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase))))
				{
					string dbColumnName = item.DbColumnName;
					string fieldValue = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.PropertyName).PropertyInfo.GetValue(InsertObjs.Last(), null).ObjToString();
					list3.Add(new ConditionalModel
					{
						ConditionalType = ConditionalType.Equal,
						FieldName = dbColumnName,
						FieldValue = fieldValue
					});
				}
			}
			Check.Exception(list3.IsNullOrEmpty(), "Insertable.EnableDiffLogEvent need primary key");
			KeyValuePair<string, SugarParameter[]> keyValuePair = SqlBuilder.ConditionalModelToSql(list3);
			empty = keyValuePair.Key;
			list.AddRange(keyValuePair.Value);
			DataTable dataTable = Context.Queryable<T>().Where(empty).AddParameters(list)
				.ToDataTable();
			if (dataTable.Rows != null && dataTable.Rows.Count > 0)
			{
				foreach (DataRow row in dataTable.Rows)
				{
					DiffLogTableInfo diffLogTableInfo = new DiffLogTableInfo();
					diffLogTableInfo.TableDescription = EntityInfo.TableDescription;
					diffLogTableInfo.TableName = EntityInfo.DbTableName;
					diffLogTableInfo.Columns = new List<DiffLogColumnInfo>();
					foreach (DataColumn col in dataTable.Columns)
					{
						EntityColumnInfo entityColumnInfo = EntityInfo.Columns.Where((EntityColumnInfo it) => it.DbColumnName != null).First((EntityColumnInfo it) => it.DbColumnName.Equals(col.ColumnName, StringComparison.CurrentCultureIgnoreCase));
						DiffLogColumnInfo diffLogColumnInfo = new DiffLogColumnInfo();
						diffLogColumnInfo.Value = row[col.ColumnName];
						diffLogColumnInfo.ColumnName = col.ColumnName;
						diffLogColumnInfo.IsPrimaryKey = entityColumnInfo.IsPrimarykey;
						diffLogColumnInfo.ColumnDescription = entityColumnInfo.ColumnDescription;
						diffLogTableInfo.Columns.Add(diffLogColumnInfo);
					}
					list2.Add(diffLogTableInfo);
				}
				return list2;
			}
			DiffLogTableInfo diffLogTableInfo2 = new DiffLogTableInfo();
			diffLogTableInfo2.TableName = EntityInfo.DbTableName;
			diffLogTableInfo2.TableDescription = EntityInfo.TableDescription;
			diffLogTableInfo2.Columns = (from it in EntityInfo.Columns
				where !it.IsIgnore
				select new DiffLogColumnInfo
				{
					ColumnDescription = it.ColumnDescription,
					ColumnName = it.DbColumnName,
					Value = it.PropertyInfo.GetValue(InsertObjs.Last(), null),
					IsPrimaryKey = it.IsPrimarykey
				}).ToList();
			return new List<DiffLogTableInfo> { diffLogTableInfo2 };
		}

		public IInsertable<T> CallEntityMethod(Expression<Action<T>> method)
		{
			if (InsertObjs.HasValue())
			{
				List<string> oldColumns = InsertBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.PropertyName).ToList();
				Expression body = (Expression.Lambda(method).Body as LambdaExpression).Body;
				Check.Exception(!(body is MethodCallExpression), method.ToString() + " is not method");
				MethodCallExpression callExpresion = body as MethodCallExpression;
				UtilMethods.DataInoveByExpresson(InsertObjs, callExpresion);
				InsertBuilder.DbColumnInfoList = new List<DbColumnInfo>();
				Init();
				InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => oldColumns.Contains(it.PropertyName)).ToList();
			}
			return this;
		}

		private List<Type> InsertPkListWithFunc<Type>(EntityColumnInfo pkInfo)
		{
			InsertBuilder.IsReturnPkList = true;
			InsertBuilder.IsNoPage = true;
			string arg = _ExecuteCommand();
			arg = InsertBuilder.ConvertInsertReturnIdFunc(SqlBuilder.GetTranslationColumnName(pkInfo.DbColumnName), arg);
			List<Type> result = Ado.SqlQuery<Type>(arg, (InsertBuilder.Parameters == null) ? null : InsertBuilder.Parameters.ToArray());
			After(arg, null);
			return result;
		}

		private List<Type> InsertPkListNoFunc<Type>(EntityColumnInfo pkInfo)
		{
			if (Ado.Transaction != null)
			{
				return ReturnDefaultIdentity<Type>(pkInfo);
			}
			try
			{
				Context.Ado.BeginTran();
				List<Type> result = ReturnDefaultIdentity<Type>(pkInfo);
				Context.Ado.CommitTran();
				return result;
			}
			catch (Exception ex)
			{
				Context.Ado.RollbackTran();
				throw ex;
			}
		}

		private List<Type> InsertPkListIdentityCount1<Type>(EntityColumnInfo pkInfo)
		{
			if (pkInfo.UnderType == UtilConstants.IntType)
			{
				return new List<Type> { (Type)(object)ExecuteReturnIdentity() };
			}
			return new List<Type> { (Type)(object)ExecuteReturnBigIdentity() };
		}

		private List<Type> InsertPkListLong<Type>()
		{
			List<long> source = ExecuteReturnSnowflakeIdList();
			try
			{
				return source.Cast<Type>().ToList();
			}
			catch
			{
				Check.ExceptionEasy("long to ExecuteReturnPkList<" + typeof(Type).Name + "> error ", " long 转换成ExecuteReturnPkList<" + typeof(Type).Name + ">失败");
				return null;
			}
		}

		private List<Type> InsertPkListGuid<Type>(EntityColumnInfo pkInfo)
		{
			Check.ExceptionEasy(pkInfo.UnderType.Name != typeof(Type).Name, pkInfo.UnderType.Name + " to ExecuteReturnPkList<" + typeof(Type).Name + "> error ", $" {pkInfo.UnderType.Name} 转换成ExecuteReturnPkList<{typeof(Type).Name}>失败");
			ExecuteCommand();
			List<Type> list = new List<Type>();
			if (InsertBuilder.DbColumnInfoList.HasValue())
			{
				foreach (DbColumnInfo dbColumnInfo in InsertBuilder.DbColumnInfoList)
				{
					if (dbColumnInfo.DbColumnName.EqualCase(pkInfo.DbColumnName))
					{
						list.Add((Type)dbColumnInfo.Value);
					}
				}
			}
			return list;
		}

		private List<Type> ReturnDefaultIdentity<Type>(EntityColumnInfo pkInfo)
		{
			List<Type> list = new List<Type>();
			T[] insertObjs = InsertObjs;
			foreach (T insertObj in insertObjs)
			{
				IInsertable<T> insertable = Context.Insertable(insertObj).AS(InsertBuilder.AsName).InsertColumns(InsertBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.DbColumnName).Distinct().ToArray());
				if (pkInfo.UnderType == UtilConstants.IntType)
				{
					list.Add((Type)(object)insertable.ExecuteReturnIdentity());
				}
				else
				{
					list.Add((Type)(object)insertable.ExecuteReturnBigIdentity());
				}
			}
			return list;
		}

		public void AddQueue()
		{
			if (InsertObjs != null && InsertObjs.Length != 0 && InsertObjs[0] != null)
			{
				KeyValuePair<string, List<SugarParameter>> keyValuePair = ToSql();
				Context.Queues.Add(keyValuePair.Key, keyValuePair.Value);
			}
		}

		public virtual int ExecuteCommand()
		{
			if (InsertObjs.Count() == 1 && InsertObjs.First() == null)
			{
				return 0;
			}
			string sql = _ExecuteCommand();
			int num = Ado.ExecuteCommand(sql, (InsertBuilder.Parameters == null) ? null : InsertBuilder.Parameters.ToArray());
			After(sql, null);
			if (num == -1)
			{
				return InsertObjs.Count();
			}
			return num;
		}

		public virtual string ToSqlString()
		{
			KeyValuePair<string, List<SugarParameter>> sqlObj = ToSql();
			if (sqlObj.Key == null)
			{
				return null;
			}
			return UtilMethods.GetSqlString(Context.CurrentConnectionConfig, sqlObj);
		}

		public virtual KeyValuePair<string, List<SugarParameter>> ToSql()
		{
			InsertBuilder.IsReturnIdentity = true;
			if (SqlBuilder.SqlParameterKeyWord == ":" && !EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity))
			{
				InsertBuilder.IsReturnIdentity = false;
			}
			PreToSql();
			AutoRemoveDataCache();
			string key = InsertBuilder.ToSqlString();
			RestoreMapping();
			return new KeyValuePair<string, List<SugarParameter>>(key, InsertBuilder.Parameters);
		}

