		public virtual List<Type> ExecuteReturnPkList<Type>()
		{
			EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
			Check.ExceptionEasy(entityColumnInfo == null, "ExecuteReturnPkList need primary key", "ExecuteReturnPkList需要主键");
			Check.ExceptionEasy(EntityInfo.Columns.Count((EntityColumnInfo it) => it.IsPrimarykey) > 1, "ExecuteReturnPkList ，Only support technology single primary key", "ExecuteReturnPkList只支技单主键");
			bool flag = entityColumnInfo.IsIdentity || (entityColumnInfo.OracleSequenceName.HasValue() && Context.CurrentConnectionConfig.DbType == DbType.Oracle);
			if (flag && InsertObjs.Length == 1)
			{
				return InsertPkListIdentityCount1<Type>(entityColumnInfo);
			}
			if (flag && InsertBuilder.ConvertInsertReturnIdFunc == null)
			{
				return InsertPkListNoFunc<Type>(entityColumnInfo);
			}
			if (flag && InsertBuilder.ConvertInsertReturnIdFunc != null)
			{
				return InsertPkListWithFunc<Type>(entityColumnInfo);
			}
			if (entityColumnInfo.UnderType == UtilConstants.LongType)
			{
				return InsertPkListLong<Type>();
			}
			return InsertPkListGuid<Type>(entityColumnInfo);
		}

