			EntityColumnInfo snowProperty = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey && it.PropertyInfo.PropertyType == UtilConstants.LongType);
			Check.Exception(snowProperty == null, "The entity sets the primary key and is long");
