		public virtual bool ExecuteCommandIdentityIntoEntity()
		{
			T obj = InsertObjs.First();
			List<string> list = GetIdentityKeys();
			SqlSugarProvider context = Context;
			if (context != null && context.CurrentConnectionConfig?.MoreSettings?.EnableOracleIdentity == true)
			{
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsIdentity);
				if (entityColumnInfo != null)
				{
					list = new List<string> { entityColumnInfo.DbColumnName };
				}
			}
			if (list.Count == 0)
			{
				EntityColumnInfo entityColumnInfo2 = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey && it.UnderType == UtilConstants.LongType);
				if (entityColumnInfo2 != null)
				{
					if (Convert.ToInt64(entityColumnInfo2.PropertyInfo.GetValue(obj)) == 0L)
					{
						long num = ExecuteReturnSnowflakeId();
						entityColumnInfo2.PropertyInfo.SetValue(obj, num);
					}
					else
					{
						ExecuteCommand();
					}
					return true;
				}
				return ExecuteCommand() > 0;
			}
			long num2 = ExecuteReturnBigIdentity();
			Check.Exception(list.Count > 1, "ExecuteCommandIdentityIntoEntity does not support multiple identity keys");
			string dbColumnName = list.First();
			object obj2 = 0;
			obj2 = ((num2 > int.MaxValue) ? ((object)num2) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(uint)) ? ((object)Convert.ToUInt32(num2)) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(ulong)) ? ((object)Convert.ToUInt64(num2)) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(ushort)) ? ((object)Convert.ToUInt16(num2)) : ((!EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(short))) ? ((object)Convert.ToInt32(num2)) : ((object)Convert.ToInt16(num2)))))));
			Context.EntityMaintenance.GetProperty<T>(dbColumnName).SetValue(obj, obj2, null);
			return num2 > 0;
		}

