		public virtual async Task<bool> ExecuteCommandIdentityIntoEntityAsync()
		{
			T result = InsertObjs.First();
			List<string> identityKeys = GetIdentityKeys();
			if (identityKeys.Count == 0)
			{
				EntityColumnInfo snowColumn = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey && it.UnderType == UtilConstants.LongType);
				if (snowColumn != null)
				{
					if (Convert.ToInt64(snowColumn.PropertyInfo.GetValue(result)) != 0L)
					{
						await ExecuteCommandAsync();
					}
					else
					{
						long num = await ExecuteReturnSnowflakeIdAsync();
						snowColumn.PropertyInfo.SetValue(result, num);
					}
					return true;
				}
				return await ExecuteCommandAsync() > 0;
			}
			long num2 = await ExecuteReturnBigIdentityAsync();
			Check.Exception(identityKeys.Count > 1, "ExecuteCommandIdentityIntoEntity does not support multiple identity keys");
			string dbColumnName = identityKeys.First();
			object value = ((num2 > int.MaxValue) ? ((object)num2) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(uint)) ? ((object)Convert.ToUInt32(num2)) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(ulong)) ? ((object)Convert.ToUInt64(num2)) : (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(ushort)) ? ((object)Convert.ToUInt16(num2)) : ((!EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity && it.PropertyInfo.PropertyType == typeof(short))) ? ((object)Convert.ToInt32(num2)) : ((object)Convert.ToInt16(num2)))))));
			Context.EntityMaintenance.GetProperty<T>(dbColumnName).SetValue(result, value, null);
			return num2 > 0;
		}

