		public InsertablePage<T> PageSize(int pageSize)
		{
			InsertablePage<T> insertablePage = new InsertablePage<T>();
			insertablePage.PageSize = pageSize;
			insertablePage.Context = Context;
			insertablePage.DataList = InsertObjs;
			insertablePage.TableName = InsertBuilder.AsName;
			insertablePage.IsEnableDiffLogEvent = IsEnableDiffLogEvent;
			insertablePage.DiffModel = diffModel;
			insertablePage.IsMySqlIgnore = InsertBuilder.MySqlIgnore;
			insertablePage.IsOffIdentity = InsertBuilder.IsOffIdentity;
			if (InsertBuilder.DbColumnInfoList.Any())
			{
				insertablePage.InsertColumns = (from it in (from it in InsertBuilder.DbColumnInfoList
						group it by it.TableId).First()
					select it.DbColumnName).ToList();
			}
			return insertablePage;
		}

