		public IInsertable<T> IgnoreColumns(Expression<Func<T, object>> columns)
		{
			if (columns == null)
			{
				return this;
			}
			List<string> ignoreColumns = (from it in InsertBuilder.GetExpressionValue(columns, ResolveExpressType.ArraySingle).GetResultArray()
				select SqlBuilder.GetNoTranslationColumnName(it)).ToList();
			InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !ignoreColumns.Any((string ig) => ig.Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase))).ToList();
			InsertBuilder.DbColumnInfoList = InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !ignoreColumns.Any((string ig) => ig.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase))).ToList();
			return this;
		}

