		public ISubInsertable<T> AddSubList(Expression<Func<T, object>> items)
		{
			Check.Exception(GetPrimaryKeys().Count == 0, typeof(T).Name + " need Primary key");
			Check.Exception(GetPrimaryKeys().Count > 1, typeof(T).Name + "Multiple primary keys are not supported");
			if (InsertObjs == null || InsertObjs.Count() == 0)
			{
				return new SubInsertable<T>();
			}
			SubInsertable<T> subInsertable = new SubInsertable<T>();
			subInsertable.InsertObjects = InsertObjs;
			subInsertable.Context = Context;
			subInsertable.SubList = new List<SubInsertTreeExpression>();
			subInsertable.SubList.Add(new SubInsertTreeExpression
			{
				Expression = items
			});
			subInsertable.InsertBuilder = InsertBuilder;
			subInsertable.Pk = GetPrimaryKeys().First();
			subInsertable.Entity = EntityInfo;
			return subInsertable;
		}

		public ISubInsertable<T> AddSubList(Expression<Func<T, SubInsertTree>> tree)
		{
			Check.Exception(GetPrimaryKeys().Count == 0, typeof(T).Name + " need Primary key");
			Check.Exception(GetPrimaryKeys().Count > 1, typeof(T).Name + "Multiple primary keys are not supported");
			if (InsertObjs == null || InsertObjs.Count() == 0)
			{
				return new SubInsertable<T>();
			}
			SubInsertable<T> subInsertable = new SubInsertable<T>();
			subInsertable.InsertObjects = InsertObjs;
			subInsertable.Context = Context;
			subInsertable.SubList = new List<SubInsertTreeExpression>();
			subInsertable.InsertBuilder = InsertBuilder;
			subInsertable.Pk = GetPrimaryKeys().First();
			subInsertable.Entity = EntityInfo;
			subInsertable.AddSubList(tree);
			return subInsertable;
		}

		public SplitInsertable<T> SplitTable(SplitType splitType)
		{
			UtilMethods.StartCustomSplitTable(Context, typeof(T));
			SplitTableContext splitTableContext = new SplitTableContext(Context)
			{
				EntityInfo = EntityInfo
			};
			splitTableContext.CheckPrimaryKey();
			SplitInsertable<T> splitInsertable = new SplitInsertable<T>();
			splitInsertable.Context = Context;
			splitInsertable.EntityInfo = EntityInfo;
			splitInsertable.Helper = splitTableContext;
			splitInsertable.SplitType = splitType;
			splitInsertable.TableNames = new List<KeyValuePair<string, object>>();
			splitInsertable.MySqlIgnore = InsertBuilder.MySqlIgnore;
			T[] insertObjs = InsertObjs;
			foreach (T val in insertObjs)
			{
				object value = splitTableContext.GetValue(splitType, val);
				string tableName = splitTableContext.GetTableName(splitType, value);
				splitInsertable.TableNames.Add(new KeyValuePair<string, object>(tableName, val));
			}
			splitInsertable.Inserable = this;
			return splitInsertable;
		}

		public SplitInsertable<T> SplitTable()
		{
			if (StaticConfig.SplitTableCreateTableFunc != null)
			{
				Action<Type, object[]> splitTableCreateTableFunc = StaticConfig.SplitTableCreateTableFunc;
				Type? typeFromHandle = typeof(T);
				object[] insertObjs = InsertObjs;
				splitTableCreateTableFunc(typeFromHandle, insertObjs);
			}
			UtilMethods.StartCustomSplitTable(Context, typeof(T));
			SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
			if (customAttribute != null)
			{
				return SplitTable(customAttribute.SplitType);
			}
			Check.Exception(true, " " + typeof(T).Name + " need SplitTableAttribute");
			return null;
		}
	}
	public class InsertablePage<T> where T : class, new()
	{
		public int PageSize { get; set; }

		public SqlSugarProvider Context { get; set; }

		public T[] DataList { get; set; }

		public string TableName { get; internal set; }

		public List<string> InsertColumns { get; internal set; }

		public bool IsEnableDiffLogEvent { get; internal set; }

		public DiffLogModel DiffModel { get; internal set; }

		public bool IsOffIdentity { get; internal set; }

		public bool IsInsertColumnsNull { get; internal set; }

		public bool IsMySqlIgnore { get; internal set; }

		public int ExecuteCommand()
		{
			if (DataList.Count() == 1 && DataList.First() == null)
			{
				return 0;
			}
			if (PageSize == 0)
			{
				PageSize = 1000;
			}
			int result = 0;
			bool flag = Context.Ado.IsNoTran();
			try
			{
				if (flag)
				{
					Context.Ado.BeginTran();
				}
				Context.Utilities.PageEach(DataList, PageSize, delegate(List<T> pageItem)
				{
					result += Context.Insertable(pageItem).AS(TableName).MySqlIgnore(IsMySqlIgnore)
						.IgnoreColumnsNull(IsInsertColumnsNull)
						.OffIdentity(IsOffIdentity)
						.EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel)
						.InsertColumns(InsertColumns.ToArray())
						.ExecuteCommand();
				});
				if (flag)
				{
					Context.Ado.CommitTran();
				}
			}
			catch (Exception)
			{
				if (flag)
				{
					Context.Ado.RollbackTran();
				}
				throw;
			}
			return result;
		}

		public async Task<int> ExecuteCommandAsync()
		{
			if (DataList.Count() == 1 && DataList.First() == null)
			{
				return 0;
			}
			if (PageSize == 0)
			{
				PageSize = 1000;
			}
			int result = 0;
			bool isNoTran = Context.Ado.IsNoTran();
			try
			{
				if (isNoTran)
				{
					await Context.Ado.BeginTranAsync();
				}
				await Context.Utilities.PageEachAsync(DataList, PageSize, async delegate(List<T> pageItem)
				{
					int num = result;
					result = num + await Context.Insertable(pageItem).AS(TableName).IgnoreColumnsNull(IsInsertColumnsNull)
						.OffIdentity(IsOffIdentity)
						.EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel)
						.InsertColumns(InsertColumns.ToArray())
						.ExecuteCommandAsync();
				});
				if (isNoTran)
				{
					await Context.Ado.CommitTranAsync();
				}
			}
			catch (Exception)
			{
				if (isNoTran)
				{
					await Context.Ado.RollbackTranAsync();
				}
				throw;
			}
			return result;
		}

