	public class ParameterInsertable<T> : IParameterInsertable<T> where T : class, new()
	{
		internal IInsertable<T> Inserable { get; set; }

		internal SqlSugarProvider Context { get; set; }

		public int ExecuteCommand()
		{
			return DefaultExecuteCommand();
		}

		public async Task<int> ExecuteCommandAsync()
		{
			return await DefaultExecuteCommandAsync();
		}

		public int DefaultExecuteCommand()
		{
			int result = 0;
			InsertableProvider<T> insertableProvider = Inserable as InsertableProvider<T>;
			List<string> columns = (from it in insertableProvider.InsertBuilder.DbColumnInfoList
				group it by it.DbColumnName into it
				select it.Key).Distinct().ToList();
			string tableWithString = insertableProvider.InsertBuilder.TableWithString;
			Action removeCacheFunc = insertableProvider.RemoveCacheFunc;
			T[] insertObjs = insertableProvider.InsertObjs;
			int pageSize = 60;
			List<string> list = columns;
			if (list != null && list.Count > 100)
			{
				pageSize = 10;
			}
			else
			{
				List<string> list2 = columns;
				if (list2 != null && list2.Count > 60)
				{
					pageSize = 20;
				}
				else
				{
					List<string> list3 = columns;
					if (list3 != null && list3.Count > 40)
					{
						pageSize = 30;
					}
				}
			}
			Context.Utilities.PageEach(insertObjs, pageSize, delegate(List<T> pagelist)
			{
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					Context.AddQueue("begin");
				}
				foreach (T item in pagelist)
				{
					IInsertable<T> insertable = Context.Insertable(item);
					insertable.InsertBuilder.DbColumnInfoList = insertable.InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => columns.Contains(it.DbColumnName)).ToList();
					insertable.InsertBuilder.TableWithString = tableWithString;
					insertable.InsertBuilder.AsName = Inserable.InsertBuilder.AsName;
					(insertable as InsertableProvider<T>).RemoveCacheFunc = removeCacheFunc;
					insertable.AddQueue();
				}
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					Context.AddQueue("end \r\n");
				}
				result += Context.SaveQueues(isTran: false);
			});
			if (result == -1)
			{
				result = insertObjs.Length;
			}
			return result;
		}

		public async Task<int> DefaultExecuteCommandAsync()
		{
			int result = 0;
			InsertableProvider<T> insertableProvider = Inserable as InsertableProvider<T>;
			List<string> columns = (from it in insertableProvider.InsertBuilder.DbColumnInfoList
				group it by it.DbColumnName into it
				select it.Key).Distinct().ToList();
			string tableWithString = insertableProvider.InsertBuilder.TableWithString;
			Action removeCacheFunc = insertableProvider.RemoveCacheFunc;
			T[] objects = insertableProvider.InsertObjs;
			await Context.Utilities.PageEachAsync(objects, 60, async delegate(List<T> pagelist)
			{
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					Context.AddQueue("begin");
				}
				foreach (T item in pagelist)
				{
					IInsertable<T> insertable = Context.Insertable(item);
					insertable.InsertBuilder.DbColumnInfoList = insertable.InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => columns.Contains(it.DbColumnName)).ToList();
					insertable.InsertBuilder.TableWithString = tableWithString;
					insertable.InsertBuilder.AsName = Inserable.InsertBuilder.AsName;
					(insertable as InsertableProvider<T>).RemoveCacheFunc = removeCacheFunc;
					insertable.AddQueue();
				}
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					Context.AddQueue("end");
				}
				int num = result;
				result = num + await Context.SaveQueuesAsync(isTran: false);
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					result = objects.Length;
				}
				return result;
			});
			return result;
		}

		public int ValuesExecuteCommand()
		{
			int result = 0;
			InsertableProvider<T> insertableProvider = Inserable as InsertableProvider<T>;
			List<string> columns = (from it in insertableProvider.InsertBuilder.DbColumnInfoList
				group it by it.DbColumnName into it
				select it.Key).Distinct().ToList();
			string tableWithString = insertableProvider.InsertBuilder.AsName;
			Action removeCacheFunc = insertableProvider.RemoveCacheFunc;
			T[] insertObjs = insertableProvider.InsertObjs;
			if (insertObjs == null || insertObjs.Count() == 0 || (insertObjs.Count() == 1 && insertObjs.First() == null))
			{
				return result;
			}
			string[] identityList = (from it in insertableProvider.EntityInfo.Columns
				where it.IsIdentity
				select it.PropertyName).ToArray();
			if (insertableProvider.IsOffIdentity)
			{
				identityList = new string[0];
			}
			int pageSize = 100;
			int count = insertableProvider.EntityInfo.Columns.Count();
			pageSize = GetPageSize(pageSize, count);
			Context.Utilities.PageEach(insertObjs, pageSize, delegate(List<T> pagelist)
			{
				List<SugarParameter> list = new List<SugarParameter>();
				GetInsertValues(identityList, columns, tableWithString, removeCacheFunc, pagelist, out StringBuilder batchInsetrSql, list);
				result += Context.Ado.ExecuteCommand(batchInsetrSql.ToString(), list);
			});
			return result;
		}

		public async Task<int> ValuesExecuteCommandAsync()
		{
			int result = 0;
			InsertableProvider<T> insertableProvider = Inserable as InsertableProvider<T>;
			List<string> columns = (from it in insertableProvider.InsertBuilder.DbColumnInfoList
				group it by it.DbColumnName into it
				select it.Key).Distinct().ToList();
			string tableWithString = insertableProvider.InsertBuilder.AsName;
			Action removeCacheFunc = insertableProvider.RemoveCacheFunc;
			T[] insertObjs = insertableProvider.InsertObjs;
			string[] identityList = (from it in insertableProvider.EntityInfo.Columns
				where it.IsIdentity
				select it.PropertyName).ToArray();
			if (insertableProvider.IsOffIdentity)
			{
				identityList = new string[0];
			}
			await Context.Utilities.PageEachAsync(insertObjs, 100, async delegate(List<T> pagelist)
			{
				List<SugarParameter> list = new List<SugarParameter>();
				GetInsertValues(identityList, columns, tableWithString, removeCacheFunc, pagelist, out StringBuilder batchInsetrSql, list);
				int num = result;
				result = num + await Context.Ado.ExecuteCommandAsync(batchInsetrSql.ToString(), list);
			});
			return result;
		}

		private static int GetPageSize(int pageSize, int count)
		{
			if (pageSize * count > 2100)
			{
				pageSize = 50;
			}
			if (pageSize * count > 2100)
			{
				pageSize = 20;
			}
			if (pageSize * count > 2100)
			{
				pageSize = 10;
			}
			return pageSize;
		}

		private void GetInsertValues(string[] identitys, List<string> columns, string tableWithString, Action removeCacheFunc, List<T> items, out StringBuilder batchInsetrSql, List<SugarParameter> allParamter)
		{
			IInsertable<T> itemable = Context.Insertable(items);
			itemable.InsertBuilder.DbColumnInfoList = itemable.InsertBuilder.DbColumnInfoList.Where((DbColumnInfo it) => columns.Contains(it.DbColumnName)).ToList();
			itemable.InsertBuilder.TableWithString = tableWithString;
			(itemable as InsertableProvider<T>).RemoveCacheFunc = removeCacheFunc;
			batchInsetrSql = new StringBuilder();
			batchInsetrSql.Append("INSERT INTO " + itemable.InsertBuilder.GetTableNameString + " ");
			batchInsetrSql.Append("(");
			List<IGrouping<int, DbColumnInfo>> list = (from it in itemable.InsertBuilder.DbColumnInfoList
				where !Enumerable.Contains(identitys, it.PropertyName)
				group it by it.TableId).ToList();
			string value = string.Join(",", from it in list.First()
				select itemable.InsertBuilder.Builder.GetTranslationColumnName(it.DbColumnName));
			batchInsetrSql.Append(value);
			batchInsetrSql.Append(") VALUES");
			string text = "";
			foreach (IGrouping<int, DbColumnInfo> item in list)
			{
				batchInsetrSql.Append("(");
				text = string.Join(",", item.Select((DbColumnInfo it) => FormatValue(it.PropertyType, it.DbColumnName, it.Value, allParamter, itemable.InsertBuilder.Builder.SqlParameterKeyWord)));
				batchInsetrSql.Append(text);
				if (list.Last() == item)
				{
					batchInsetrSql.Append(") ");
				}
				else
				{
					batchInsetrSql.Append("),  ");
				}
			}
		}

		private string FormatValue(Type type, string name, object value, List<SugarParameter> allParamter, string keyword)
		{
			string text = keyword + name + allParamter.Count;
			SugarParameter item = new SugarParameter(text, value, type);
			allParamter.Add(item);
			return text;
		}
	}
