		private void CreateTable()
		{
			bool isEnableLogEvent = Context.Ado.IsEnableLogEvent;
			Context.Ado.IsEnableLogEvent = false;
			foreach (KeyValuePair<string, object> item in (from it in TableNames
				group it by it.Key into it
				select (it)).ToDictionary((IGrouping<string, KeyValuePair<string, object>> it) => it.Key, (IGrouping<string, KeyValuePair<string, object>> it) => it.First().Value))
			{
				SqlSugarClient sqlSugarClient = Context.CopyNew();
				sqlSugarClient.CurrentConnectionConfig.IsAutoCloseConnection = true;
				if (sqlSugarClient.DbMaintenance.IsAnyTable(item.Key, isCache: false))
				{
					continue;
				}
				lock (SplitLockObj)
				{
					SqlSugarClient sqlSugarClient2 = Context.CopyNew();
					sqlSugarClient2.CurrentConnectionConfig.IsAutoCloseConnection = true;
					if (!sqlSugarClient2.DbMaintenance.IsAnyTable(item.Key, isCache: false) && item.Value != null)
					{
						Context.MappingTables.Add(EntityInfo.EntityName, item.Key);
						Context.CodeFirst.InitTables<T>();
					}
				}
			}
			Context.Ado.IsEnableLogEvent = isEnableLogEvent;
			Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
