	public class SubInsertable<T> : ISubInsertable<T> where T : class, new()
	{
		internal EntityInfo Entity { get; set; }

		internal List<SubInsertTreeExpression> SubList { get; set; }

		internal SqlSugarProvider Context { get; set; }

		internal T[] InsertObjects { get; set; }

		internal InsertBuilder InsertBuilder { get; set; }

		internal string Pk { get; set; }

		public ISubInsertable<T> AddSubList(Expression<Func<T, object>> items)
		{
			if (SubList == null)
			{
				SubList = new List<SubInsertTreeExpression>();
			}
			SubList.Add(new SubInsertTreeExpression
			{
				Expression = items
			});
			return this;
		}

		public ISubInsertable<T> AddSubList(Expression<Func<T, SubInsertTree>> tree)
		{
			try
			{
				MemberInitExpression memberInitExpression = tree.Body as MemberInitExpression;
				if (memberInitExpression.Bindings != null)
				{
					MemberAssignment memberAssignment = (MemberAssignment)memberInitExpression.Bindings[0];
					SubList.Add(new SubInsertTreeExpression
					{
						Expression = memberAssignment.Expression,
						Childs = GetSubInsertTree(((MemberAssignment)memberInitExpression.Bindings[1]).Expression)
					});
				}
			}
			catch
			{
				Check.Exception(true, tree.ToString() + " format error ");
			}
			return this;
		}

		private List<SubInsertTreeExpression> GetSubInsertTree(Expression expression)
		{
			List<SubInsertTreeExpression> list = new List<SubInsertTreeExpression>();
			if (expression is ListInitExpression)
			{
				foreach (ElementInit initializer in (expression as ListInitExpression).Initializers)
				{
					SubInsertTreeExpression subInsertTreeExpression = new SubInsertTreeExpression();
					MemberInitExpression memberInitExpression = initializer.Arguments[0] as MemberInitExpression;
					if (memberInitExpression.Bindings != null)
					{
						MemberAssignment memberAssignment = (MemberAssignment)memberInitExpression.Bindings[0];
						subInsertTreeExpression.Expression = memberAssignment.Expression;
						if (memberInitExpression.Bindings.Count > 1)
						{
							subInsertTreeExpression.Childs = GetSubInsertTree(((MemberAssignment)memberInitExpression.Bindings[1]).Expression);
						}
					}
					list.Add(subInsertTreeExpression);
				}
			}
			return list;
		}

		[Obsolete("use ExecuteCommand")]
		public object ExecuteReturnPrimaryKey()
		{
			return ExecuteCommand();
		}

		public async Task<object> ExecuteCommandAsync()
		{
			object resut = 0;
			await Task.Run(delegate
			{
				resut = ExecuteCommand();
			});
			return resut;
		}

		public object ExecuteCommand()
		{
			bool flag = Context.Ado.Transaction == null;
			try
			{
				if (flag)
				{
					Context.Ado.BeginTran();
				}
				object result = Execute();
				if (flag)
				{
					Context.Ado.CommitTran();
				}
				return result;
			}
			catch (Exception ex)
			{
				if (flag)
				{
					Context.Ado.RollbackTran();
				}
				throw ex;
			}
		}

		private object Execute()
		{
			if (InsertObjects != null && InsertObjects.Count() > 0)
			{
				bool flag = IsIdEntity(Entity);
				if (!flag)
				{
					Context.Insertable(InsertObjects).ExecuteCommand();
				}
				T[] insertObjects = InsertObjects;
				foreach (T val in insertObjects)
				{
					int num = 0;
					if (flag)
					{
						num = Context.Insertable(val).ExecuteReturnIdentity();
						Entity.Columns.First((EntityColumnInfo it) => it.IsIdentity || it.OracleSequenceName.HasValue()).PropertyInfo.SetValue(val, num);
					}
					object primaryKey = GetPrimaryKey(Entity, val, num);
					AddChildList(SubList, val, primaryKey);
				}
				return InsertObjects.Count();
			}
			return 0;
		}

		[Obsolete("use ExecuteCommandAsync")]
		public Task<object> ExecuteReturnPrimaryKeyAsync()
		{
			return Task.FromResult(ExecuteReturnPrimaryKey());
		}

		private bool IsIdEntity(EntityInfo entity)
		{
			return entity.Columns.Where((EntityColumnInfo it) => it.IsIdentity || it.OracleSequenceName.HasValue()).Count() > 0;
		}

		private void AddChildList(List<SubInsertTreeExpression> items, object insertObject, object pkValue)
		{
			if (items == null)
			{
				return;
			}
			foreach (SubInsertTreeExpression item in items)
			{
				string memberName = GetMemberName(item, out MemberExpression subMemberException);
				string text = GetChildName(item, subMemberException);
				PropertyInfo property = insertObject.GetType().GetProperty(text);
				if (property == null)
				{
					text = memberName;
					property = insertObject.GetType().GetProperty(text);
				}
				object obj = property.GetValue(insertObject);
				if (obj == null)
				{
					continue;
				}
				if (!(obj is IEnumerable<object>))
				{
					obj = new List<object> { obj };
				}
				if (!string.IsNullOrEmpty(memberName) && memberName != text)
				{
					foreach (object item2 in obj as IEnumerable<object>)
					{
						item2.GetType().GetProperty(memberName).SetValue(item2, pkValue);
					}
				}
				if (!(obj as IEnumerable<object>).Any())
				{
					continue;
				}
				Type type = (obj as IEnumerable<object>).First().GetType();
				Context.InitMappingInfo(type);
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(type);
				bool flag = IsIdEntity(entityInfo);
				string dbTableName = entityInfo.DbTableName;
				List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
				List<object> list2 = (obj as IEnumerable<object>).ToList();
				foreach (object item3 in list2)
				{
					list.Add(GetInsertDictionary(item3, entityInfo));
				}
				if (!flag)
				{
					Context.Insertable(list).AS(dbTableName).ExecuteCommand();
				}
				int num = 0;
				foreach (Dictionary<string, object> item4 in list)
				{
					int num2 = 0;
					if (flag)
					{
						num2 = Context.Insertable(item4).AS(dbTableName).ExecuteReturnIdentity();
						if (Context.CurrentConnectionConfig.DbType == DbType.Oracle && num2 == 0)
						{
							string text2 = entityInfo.Columns.First((EntityColumnInfo it) => it.OracleSequenceName.HasValue())?.OracleSequenceName;
							num2 = Context.Ado.GetInt("select " + text2 + ".currval from dual");
						}
					}
					object insertObject2 = list2[num];
					object primaryKey = GetPrimaryKey(entityInfo, insertObject2, num2);
					AddChildList(item.Childs, insertObject2, primaryKey);
					num++;
				}
			}
		}

		private Dictionary<string, object> GetInsertDictionary(object insetObject, EntityInfo subEntity)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (EntityColumnInfo column in subEntity.Columns)
			{
				if (!column.IsIdentity && !column.IsIgnore)
				{
					if (!string.IsNullOrEmpty(column.OracleSequenceName) && Context.CurrentConnectionConfig.DbType == DbType.Oracle)
					{
						string value = "{SugarSeq:=}" + column.OracleSequenceName + ".nextval{SugarSeq:=}";
						dictionary.Add(column.DbColumnName, value);
					}
					else
					{
						object value2 = column.PropertyInfo.GetValue(insetObject);
						dictionary.Add(column.DbColumnName, value2);
					}
				}
			}
			return dictionary;
		}

		private static string GetChildName(SubInsertTreeExpression item, MemberExpression subMemberException)
		{
			MemberExpression memberExpression = null;
			memberExpression = ((!(subMemberException.Expression is MethodCallExpression)) ? (subMemberException.Expression as MemberExpression) : ((subMemberException.Expression as MethodCallExpression).Arguments.First() as MemberExpression));
			if (memberExpression == null && item.Expression is LambdaExpression)
			{
				memberExpression = (item.Expression as LambdaExpression).Body as MemberExpression;
			}
			if (memberExpression == null && item.Expression is MemberExpression)
			{
				memberExpression = item.Expression as MemberExpression;
			}
			return memberExpression.Member.Name;
		}

		private static string GetMemberName(SubInsertTreeExpression item, out MemberExpression subMemberException)
		{
			Expression expression = ((!(item.Expression is LambdaExpression)) ? item.Expression : (item.Expression as LambdaExpression).Body);
			if (expression is UnaryExpression)
			{
				expression = (expression as UnaryExpression).Operand;
			}
			subMemberException = expression as MemberExpression;
			return subMemberException.Member.Name;
		}

		private object GetPrimaryKey(EntityInfo entityInfo, object InsertObject, int id)
		{
			if (id.ObjToInt() == 0)
			{
				EntityColumnInfo? entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				Check.Exception(entityColumnInfo == null, entityInfo.EntityName + " no primarykey");
				return entityColumnInfo.PropertyInfo.GetValue(InsertObject);
			}
			return id;
		}
	}
