		private static MethodInfo GetIncludesByNameStringMethod(List<Type> types, string navMemberName, MethodInfo method, List<Expression> parametres, EntityInfo entityInfo)
		{
			EntityColumnInfo navColumnInfo = GetNavColumnInfo(navMemberName, entityInfo);
			parametres.AddRange(GetIncludesByNameStringParameters(entityInfo.Type, navColumnInfo));
			if (navColumnInfo.PropertyInfo.PropertyType.FullName.IsCollectionsList())
			{
				types.Add(navColumnInfo.PropertyInfo.PropertyType.GetGenericArguments()[0]);
			}
			else
			{
				types.Add(navColumnInfo.PropertyInfo.PropertyType);
			}
			return method;
		}

		private static EntityColumnInfo GetNavColumnInfo(string navMemberName, EntityInfo entityInfo)
		{
			return entityInfo.Columns.Where((EntityColumnInfo it) => it.Navigat != null && it.PropertyName.EqualCase(navMemberName)).FirstOrDefault();
		}

		private static List<Expression> GetIncludesByNameStringParameters(Type type, EntityColumnInfo item)
		{
			List<Expression> list = new List<Expression>();
			Check.ExceptionEasy(item == null, "\r\nThe \"IncludesByNameString\" method encountered an error. The navigation object does not exist. Please check the parameters and navigation configuration.", "IncludesByNameString方法出错，导航对象不存在，请检查参数和导航配置");
			Type propertyType = item.PropertyInfo.PropertyType;
			if (propertyType.FullName.IsCollectionsList())
			{
				_ = propertyType.GetGenericArguments()[0];
			}
			Expression item2 = ExpressionBuilderHelper.CreateExpressionSelectField(type, item.PropertyName, propertyType);
			list.Add(item2);
			return list;
		}

		public ISugarQueryable<T> IncludesByNameString(string navMemberName)
		{
			foreach (EntityColumnInfo item in EntityInfo.Columns.Where((EntityColumnInfo it) => it.Navigat != null && it.PropertyName.EqualCase(navMemberName)).ToList())
			{
				Type propertyType = item.PropertyInfo.PropertyType;
				Type type = propertyType;
				if (propertyType.FullName.IsCollectionsList())
				{
					type = propertyType.GetGenericArguments()[0];
				}
				Expression expression = ExpressionBuilderHelper.CreateExpressionSelectField(typeof(T), item.PropertyName, propertyType);
				(from it in GetType().GetMethods()
					where it.Name == "IncludesByExpression"
					select it).First().MakeGenericMethod(type).Invoke(this, new object[1] { expression });
			}
			return this;
		}

		public ISugarQueryable<T> IncludesAllFirstLayer(params string[] ignoreProperyNameList)
		{
			foreach (EntityColumnInfo item in EntityInfo.Columns.Where((EntityColumnInfo it) => it.Navigat != null).ToList())
			{
				if (ignoreProperyNameList == null || !ignoreProperyNameList.Any((string z) => z.EqualCase(item.PropertyName)))
				{
					Type propertyType = item.PropertyInfo.PropertyType;
					Type type = propertyType;
					if (propertyType.FullName.IsCollectionsList())
					{
						type = propertyType.GetGenericArguments()[0];
					}
					string shortName = "it";
					if (QueryBuilder.TableShortName.HasValue())
					{
						shortName = QueryBuilder.TableShortName;
					}
					Expression expression = ExpressionBuilderHelper.CreateExpressionSelectField(typeof(T), item.PropertyName, propertyType, shortName);
					(from it in GetType().GetMethods()
						where it.Name == "IncludesByExpression"
						select it).First().MakeGenericMethod(type).Invoke(this, new object[1] { expression });
				}
			}
			return this;
		}

		public ISugarQueryable<T> IncludesAllSecondLayer<TReturn1>(Expression<Func<T, TReturn1>> expression, params string[] ignoreProperyNameList)
		{
			Type type = typeof(TReturn1);
			if (type.FullName.IsCollectionsList())
			{
				type = type.GetGenericArguments()[0];
			}
			foreach (EntityColumnInfo item in Context.EntityMaintenance.GetEntityInfo(type).Columns.Where((EntityColumnInfo it) => it.Navigat != null).ToList())
			{
				if (ignoreProperyNameList == null || !ignoreProperyNameList.Any((string z) => z.EqualCase(item.PropertyName)))
				{
					Type propertyType = item.PropertyInfo.PropertyType;
					Type type2 = propertyType;
					if (propertyType.FullName.IsCollectionsList())
					{
						type2 = propertyType.GetGenericArguments()[0];
					}
					Expression expression2 = ExpressionBuilderHelper.CreateExpressionSelectField(type, item.PropertyName, propertyType);
					(from it in GetType().GetMethods()
						where it.Name == "IncludesByExpression2"
						select it).First().MakeGenericMethod(type, type2).Invoke(this, new object[2] { expression, expression2 });
				}
			}
			return this;
		}

