		public NavISugarQueryable<T> AsNavQueryable()
		{
			return GetNavSugarQueryable();
		}

		private NavISugarQueryable<T> GetNavSugarQueryable()
		{
			NavQueryableProvider<T> obj = new NavQueryableProvider<T>
			{
				Context = Context
			};
			ISugarQueryable<T> sugarQueryable = Clone();
			obj.SqlBuilder = sugarQueryable.SqlBuilder;
			obj.QueryBuilder = sugarQueryable.QueryBuilder;
			return obj;
		}

		private ISugarQueryable<T> GetManyQueryable<TReturn1>(Expression<Func<T, TReturn1>> include1)
		{
			ISugarQueryable<T> result = null;
			if (IsMembers(include1))
			{
				List<string> list = ExpressionTool.ExtractMemberNames(include1);
				if (list.Count > 1)
				{
					if (list.Count == 2)
					{
						result = IncludesByNameString(list[0], list[1]);
					}
					else if (list.Count == 3)
					{
						result = IncludesByNameString(list[0], list[1], list[2]);
					}
					else if (list.Count == 4)
					{
						result = IncludesByNameString(list[0], list[1], list[2], list[3]);
					}
					else if (list.Count == 5)
					{
						result = IncludesByNameString(list[0], list[1], list[2], list[3], list[4]);
					}
					else if (list.Count == 6)
					{
						throw new Exception("Multiple levels of expression exceeded the upper limit");
					}
				}
			}
			return result;
		}

		private static bool IsMembers<TReturn1>(Expression<Func<T, TReturn1>> include1)
		{
			bool result = false;
			Expression expression = (include1.Body as MemberExpression)?.Expression;
			if (expression is MemberExpression && (expression as MemberExpression)?.Expression != null)
			{
				result = true;
			}
			return result;
		}

		public virtual T Single()
		{
			if (QueryBuilder.OrderByValue.IsNullOrEmpty())
			{
				QueryBuilder.OrderByValue = QueryBuilder.DefaultOrderByTemplate;
			}
			int? skip = QueryBuilder.Skip;
			int? take = QueryBuilder.Take;
			string orderByValue = QueryBuilder.OrderByValue;
			QueryBuilder.Skip = null;
			QueryBuilder.Take = null;
			QueryBuilder.OrderByValue = null;
			List<T> list = ToList();
			QueryBuilder.Skip = skip;
			QueryBuilder.Take = take;
			QueryBuilder.OrderByValue = orderByValue;
			if (list == null || list.Count == 0)
			{
				return default(T);
			}
			if (list.Count >= 2)
			{
				Check.Exception(true, ErrorMessage.GetThrowMessage(".Single()  result must not exceed one . You can use.First()", "使用single查询结果集不能大于1，适合主键查询，如果大于1你可以使用Queryable.First"));
				return default(T);
			}
			return list.SingleOrDefault();
		}

		public virtual T Single(Expression<Func<T, bool>> expression)
		{
			_Where(expression);
			T result = Single();
			QueryBuilder.WhereInfos.Remove(QueryBuilder.WhereInfos.Last());
			return result;
		}

		public virtual T First()
		{
			if (QueryBuilder.OrderByValue.IsNullOrEmpty())
			{
				QueryBuilder.OrderByValue = QueryBuilder.DefaultOrderByTemplate;
			}
			if (QueryBuilder.Skip.HasValue)
			{
				QueryBuilder.Take = 1;
				return ToList().FirstOrDefault();
			}
			QueryBuilder.Skip = 0;
			QueryBuilder.Take = 1;
			List<T> list = ToList();
			if (list.HasValue())
			{
				return list.FirstOrDefault();
			}
			return default(T);
		}

		public virtual T First(Expression<Func<T, bool>> expression)
		{
			_Where(expression);
			T result = First();
			QueryBuilder.WhereInfos.Remove(QueryBuilder.WhereInfos.Last());
			return result;
		}

