		public virtual List<TResult> ToList<TResult>(Expression<Func<T, TResult>> expression)
		{
			if (QueryBuilder.Includes != null && QueryBuilder.Includes.Count > 0)
			{
				return NavSelectHelper.GetList(expression, this);
			}
			return Select(expression).ToList();
		}

		public virtual int Count()
		{
			if (!QueryBuilder.Skip.HasValue && !QueryBuilder.Take.HasValue && QueryBuilder.OrderByValue == null && QueryBuilder.PartitionByValue == null && QueryBuilder.SelectValue == null && QueryBuilder.Includes == null && !QueryBuilder.IsDistinct)
			{
				if (StaticConfig.EnableAot)
				{
					KeyValuePair<string, List<SugarParameter>> keyValuePair = Clone().Select<int>(" COUNT(1) ").ToSql();
					return Context.Ado.GetInt(keyValuePair.Key, keyValuePair.Value);
				}
				return Clone().Select<int>(" COUNT(1) ").ToList().FirstOrDefault();
			}
			Dictionary<string, string> asTables = QueryBuilder.AsTables;
			if (asTables != null && asTables.Any() && QueryBuilder.AsTables.FirstOrDefault().Value.StartsWith(" (SELECT * FROM  ("))
			{
				ISugarQueryable<T> sugarQueryable = Clone();
				sugarQueryable.QueryBuilder.OrderByValue = null;
				return sugarQueryable.Select<int>(" COUNT(1) ").ToList().FirstOrDefault();
			}
			_CountBegin(out MappingTableList expMapping, out int result);
			result = ((!IsCache) ? GetCount() : CacheSchemeMain.GetOrCreate(Context.CurrentConnectionConfig.ConfigureExternalServices.DataInfoCacheService, QueryBuilder, () => GetCount(), CacheTime, Context, CacheKey));
			_CountEnd(expMapping);
			return result;
		}

		public virtual int Count(Expression<Func<T, bool>> expression)
		{
			_Where(expression);
			int result = Count();
			QueryBuilder.WhereInfos.Remove(QueryBuilder.WhereInfos.Last());
			return result;
		}

