		public List<T> ToParentList(Expression<Func<T, object>> parentIdExpression, object primaryKeyValue)
		{
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			if (entityInfo.Columns.Any((EntityColumnInfo it) => it.IsTreeKey))
			{
				return _ToParentListByTreeKey(parentIdExpression, primaryKeyValue);
			}
			List<T> list = new List<T>();
			Check.Exception(entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count() == 0, "No Primary key");
			string parentIdName = UtilConvert.ToMemberExpression(parentIdExpression.Body).Member.Name;
			EntityColumnInfo entityColumnInfo = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == parentIdName);
			_ = entityColumnInfo.DbColumnName;
			string tableName = QueryBuilder.GetTableNameString;
			if (!QueryBuilder.IsSingle())
			{
				if (QueryBuilder.JoinQueryInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
				if (QueryBuilder.EasyJoinInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
			}
			T val = Context.Queryable<T>().AS(tableName).WithCacheIF(IsCache, CacheTime)
				.Filter(null, QueryBuilder.IsDisabledGobalFilter)
				.ClearFilter(QueryBuilder.RemoveFilters)
				.InSingle(primaryKeyValue);
			if (val != null)
			{
				list.Add(val);
				object value = entityColumnInfo.PropertyInfo.GetValue(val, null);
				int num = 0;
				while (value != null && Context.Queryable<T>().AS(tableName).WithCacheIF(IsCache, CacheTime)
					.Filter(null, QueryBuilder.IsDisabledGobalFilter)
					.ClearFilter(QueryBuilder.RemoveFilters)
					.In<object>(value)
					.Any())
				{
					Check.Exception(num > 200, ErrorMessage.GetThrowMessage("Dead cycle", "出现死循环或超出循环上限（200），检查最顶层的ParentId是否是null或者0"));
					T val2 = Context.Queryable<T>().AS(tableName).WithCacheIF(IsCache, CacheTime)
						.Filter(null, QueryBuilder.IsDisabledGobalFilter)
						.InSingle(value);
					list.Add(val2);
					value = entityColumnInfo.PropertyInfo.GetValue(val2, null);
					num++;
				}
			}
			return list;
		}

		public List<T> ToParentList(Expression<Func<T, object>> parentIdExpression, object primaryKeyValue, Expression<Func<T, bool>> parentWhereExpression)
		{
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			if (entityInfo.Columns.Any((EntityColumnInfo it) => it.IsTreeKey))
			{
				return _ToParentListByTreeKey(parentIdExpression, primaryKeyValue, parentWhereExpression);
			}
			List<T> list = new List<T>();
			Check.Exception(entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count() == 0, "No Primary key");
			string parentIdName = UtilConvert.ToMemberExpression(parentIdExpression.Body).Member.Name;
			EntityColumnInfo entityColumnInfo = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == parentIdName);
			_ = entityColumnInfo.DbColumnName;
			string tableName = QueryBuilder.GetTableNameString;
			if (!QueryBuilder.IsSingle())
			{
				if (QueryBuilder.JoinQueryInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
				if (QueryBuilder.EasyJoinInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
			}
			T val = Context.Queryable<T>().AS(tableName).WhereIF(parentWhereExpression != null, parentWhereExpression)
				.Filter(null, QueryBuilder.IsDisabledGobalFilter)
				.InSingle(primaryKeyValue);
			if (val != null)
			{
				list.Add(val);
				object value = entityColumnInfo.PropertyInfo.GetValue(val, null);
				int num = 0;
				while (value != null && Context.Queryable<T>().AS(tableName).WhereIF(parentWhereExpression != null, parentWhereExpression)
					.Filter(null, QueryBuilder.IsDisabledGobalFilter)
					.In<object>(value)
					.Any())
				{
					Check.Exception(num > 200, ErrorMessage.GetThrowMessage("Dead cycle", "出现死循环或超出循环上限（200），检查最顶层的ParentId是否是null或者0"));
					T val2 = Context.Queryable<T>().AS(tableName).WhereIF(parentWhereExpression != null, parentWhereExpression)
						.Filter(null, QueryBuilder.IsDisabledGobalFilter)
						.InSingle(value);
					list.Add(val2);
					value = entityColumnInfo.PropertyInfo.GetValue(val2, null);
					num++;
				}
			}
			return list;
		}

		public List<T> ToTree(string childPropertyName, string parentIdPropertyName, object rootValue, string primaryKeyPropertyName)
