		{
			return ToDictionary(key, value).ToDictionary<KeyValuePair<string, object>, string, ValueType>((KeyValuePair<string, object> it) => it.Key, (KeyValuePair<string, object> it) => (ValueType)UtilMethods.ChangeType2(it.Value, typeof(ValueType)));
		}

		public Dictionary<string, object> ToDictionary(Expression<Func<T, object>> key, Expression<Func<T, object>> value)
		{
			if (!QueryBuilder.IsSingle() && (QueryBuilder.AsTables == null || QueryBuilder.AsTables.Count == 0))
			{
				return MergeTable().ToDictionary(key, value);
			}
			QueryBuilder.ResultType = typeof(SugarCacheDictionary);
			string text = QueryBuilder.GetExpressionValue(key, ResolveExpressType.FieldSingle).GetResultString();
			string text2 = QueryBuilder.GetExpressionValue(value, ResolveExpressType.FieldSingle).GetResultString();
			if (!QueryBuilder.IsSingle())
			{
				text = QueryBuilder.TableShortName + "." + text;
				text2 = QueryBuilder.TableShortName + "." + text2;
			}
			if (Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => it.IsJson && it.PropertyName == ExpressionTool.GetMemberName(value)).Any())
			{
				return Select<T>(text + "," + text2).ToList().ToDictionary(ExpressionTool.GetMemberName(key), ExpressionTool.GetMemberName(value));
			}
			if (text2 == null)
			{
				Func<T, object> keySelector = key.Compile();
				Func<T, object> elementSelector = value.Compile();
				return ToList().ToDictionary(keySelector, elementSelector).ToDictionary((KeyValuePair<object, object> it) => it.Key?.ToString(), (KeyValuePair<object, object> it) => it.Value);
			}
			return Select<KeyValuePair<string, object>>(text + "," + text2).ToList().ToDictionary((KeyValuePair<string, object> it) => it.Key.ObjToString(), (KeyValuePair<string, object> it) => it.Value);
		}

