		public List<T> SetContext<ParameterT>(Expression<Func<T, bool>> whereExpression, ParameterT parameter)
		{
			List<ParameterT> list = (Context.TempItems["Queryable_To_Context"] as MapperContext<ParameterT>).list;
			List<ISugarQueryable<object>> list2 = new List<ISugarQueryable<object>>();
			int index = list.IndexOf(parameter);
			string text = Clone().QueryBuilder.GetSelectValue + $",{index} as ";
			ISugarQueryable<object> item = Clone().Where(whereExpression).Select(text ?? "").Select((Expression<Func<T, object>>)((T it) => new
			{
				it = it,
				sql_sugar_index = index
			}));
			list2.Add(item);
			(from it in Context.Union(list2)
				select new
				{
					it = default(T),
					sql_sugar_index = 0
				}).Select("*").ToList();
			new List<T>();
			throw new Exception("开发中");
		}

		public List<T> SetContext<ParameterT>(Expression<Func<T, object>> thisFiled, Expression<Func<object>> mappingFiled, ParameterT parameter)
		{
			if (parameter == null)
			{
				return new List<T>();
			}
			List<T> result = new List<T>();
			Context.EntityMaintenance.GetEntityInfo<ParameterT>();
			MapperContext<ParameterT> mapperContext = Context.TempItems["Queryable_To_Context"] as MapperContext<ParameterT>;
			List<ParameterT> list = mapperContext.list;
			string pkName = "";
			if (mappingFiled.Body is UnaryExpression)
			{
				pkName = ((mappingFiled.Body as UnaryExpression).Operand as MemberExpression).Member.Name;
			}
			else
			{
				pkName = (mappingFiled.Body as MemberExpression).Member.Name;
			}
			string key = thisFiled.ToString() + mappingFiled.ToString() + typeof(ParameterT).FullName + typeof(T).FullName;
			object[] pageItems = (from it in list
				where it != null
				select it.GetType().GetProperty(pkName).GetValue(it)).Distinct().ToArray();
			if (mapperContext.TempChildLists == null)
			{
				mapperContext.TempChildLists = new Dictionary<string, object>();
			}
			if (list != null && mapperContext.TempChildLists.ContainsKey(key))
			{
				result = (List<T>)mapperContext.TempChildLists[key];
			}
			else
			{
				if (mapperContext.TempChildLists == null)
				{
					mapperContext.TempChildLists = new Dictionary<string, object>();
				}
				Context.Utilities.PageEach(pageItems, 200, delegate(List<object> pageIds)
				{
					result.AddRange(Clone().In(thisFiled, pageIds).ToList());
				});
				mapperContext.TempChildLists[key] = result;
			}
			string name = "";
			if (thisFiled.Body is UnaryExpression)
			{
				name = ((thisFiled.Body as UnaryExpression).Operand as MemberExpression).Member.Name;
			}
			else
			{
				name = (thisFiled.Body as MemberExpression).Member.Name;
			}
			object pkValue = parameter.GetType().GetProperty(pkName).GetValue(parameter);
			result = result.Where((T it) => it.GetType().GetProperty(name).GetValue(it)
				.ObjToString() == pkValue.ObjToString()).ToList();
			return result;
		}

		public List<T> SetContext<ParameterT>(Expression<Func<T, object>> thisFiled1, Expression<Func<object>> mappingFiled1, Expression<Func<T, object>> thisFiled2, Expression<Func<object>> mappingFiled2, ParameterT parameter)
		{
			if (parameter == null)
			{
				return new List<T>();
			}
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<ParameterT>();
			EntityInfo entityInfo2 = Context.EntityMaintenance.GetEntityInfo<T>();
			List<T> list = new List<T>();
			MapperContext<ParameterT> mapperContext = Context.TempItems["Queryable_To_Context"] as MapperContext<ParameterT>;
			List<ParameterT> list2 = mapperContext.list;
			string key = thisFiled1.ToString() + mappingFiled1.ToString() + thisFiled2.ToString() + mappingFiled2.ToString() + typeof(ParameterT).FullName + typeof(T).FullName;
			MappingFieldsHelper<ParameterT> mappingFieldsHelper = new MappingFieldsHelper<ParameterT>();
			List<MappingFieldsExpression> mappingFieldsExpressions = new List<MappingFieldsExpression>
			{
				new MappingFieldsExpression
				{
					LeftColumnExpression = thisFiled1,
					LeftEntityColumn = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(thisFiled1)),
					RightColumnExpression = mappingFiled1,
					RightEntityColumn = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(mappingFiled1))
				},
				new MappingFieldsExpression
				{
					LeftColumnExpression = thisFiled2,
					LeftEntityColumn = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(thisFiled2)),
					RightColumnExpression = mappingFiled2,
					RightEntityColumn = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(mappingFiled2))
				}
			};
			List<IConditionalModel> mppingSql = mappingFieldsHelper.GetMppingSql(list2.Cast<object>().ToList(), mappingFieldsExpressions);
			if (mapperContext.TempChildLists == null)
			{
				mapperContext.TempChildLists = new Dictionary<string, object>();
			}
			if (list2 != null && mapperContext.TempChildLists.ContainsKey(key))
			{
				list = (List<T>)mapperContext.TempChildLists[key];
			}
			else
			{
				list = Clone().Where(mppingSql, isWrap: true).ToList();
				mapperContext.TempChildLists[key] = list;
			}
			List<object> list3 = ((IEnumerable<T>)list).Select((Func<T, object>)((T it) => it)).ToList();
			object item = parameter;
			return (from it in mappingFieldsHelper.GetSetList(item, list3, mappingFieldsExpressions)
				select (T)it).ToList();
		}

		public void ForEachDataReader(Action<T> action)
		{
			KeyValuePair<string, List<SugarParameter>> keyValuePair = Clone().ToSql();
			IDataReader dr = Context.Ado.GetDataReader(keyValuePair.Key, keyValuePair.Value);
			Context.EntityMaintenance.GetEntityInfo<T>();
			List<Tuple<string, Type>> columns = UtilMethods.GetColumnInfo(dr);
			string cacheKey = "ForEachDataReader" + typeof(T).GetHashCode() + string.Join(",", columns.Select((Tuple<string, Type> it) => it.Item1 + it.Item2.Name + "_"));
			IDataReaderEntityBuilder<T> orCreate = Context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => new IDataReaderEntityBuilder<T>(Context, dr, columns.Select((Tuple<string, Type> it) => it.Item1).ToList()).CreateBuilder(typeof(T)));
			using (dr)
			{
				while (dr.Read())
				{
					T obj = orCreate.Build(dr);
					action(obj);
				}
			}
			if (Context.CurrentConnectionConfig.IsAutoCloseConnection)
			{
				Context.Ado.Close();
			}
		}

