		public virtual void ForEach(Action<T> action, int singleMaxReads = 300, CancellationTokenSource cancellationTokenSource = null)
		{
			Check.Exception(QueryBuilder.Skip > 0 || QueryBuilder.Take > 0, ErrorMessage.GetThrowMessage("no support Skip take, use PageForEach", "不支持Skip Take,请使用 Queryale.PageForEach"));
			int totalNumber = 0;
			int totalPage = 1;
			for (int i = 1; i <= totalPage; i++)
			{
				if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
				{
					break;
				}
				ISugarQueryable<T> sugarQueryable = Clone();
				foreach (T item in (totalPage == 1) ? sugarQueryable.ToPageList(i, singleMaxReads, ref totalNumber, ref totalPage) : sugarQueryable.ToPageList(i, singleMaxReads))
				{
					if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
					{
						return;
					}
					action(item);
				}
			}
		}

		public virtual void ForEachByPage(Action<T> action, int pageIndex, int pageSize, ref int totalNumber, int singleMaxReads = 300, CancellationTokenSource cancellationTokenSource = null)
		{
			int num = Clone().Count();
			if (num > 0)
			{
				if (pageSize > singleMaxReads && num - (pageIndex - 1) * pageSize > singleMaxReads)
				{
					int num2 = (pageIndex - 1) * pageSize;
					int num3 = num - num2;
					int num4 = 0;
					if (num3 > pageSize)
					{
						num3 = pageSize;
					}
					while (num3 > 0)
					{
						if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
						{
							return;
						}
						if (num4 + singleMaxReads > pageSize)
						{
							singleMaxReads = num3;
						}
						foreach (T item in Clone().Skip(num2).Take(singleMaxReads).ToList())
						{
							if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
							{
								return;
							}
							action(item);
						}
						num3 -= singleMaxReads;
						num2 += singleMaxReads;
						num4 += singleMaxReads;
					}
				}
				else
				{
					if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
					{
						return;
					}
					foreach (T item2 in Clone().ToPageList(pageIndex, pageSize))
					{
						if (cancellationTokenSource != null && cancellationTokenSource.IsCancellationRequested)
						{
							return;
						}
						action(item2);
					}
				}
			}
			totalNumber = num;
		}

