		public virtual List<TResult> ToPageList<TResult>(int pageIndex, int pageSize, ref int totalNumber, Expression<Func<T, TResult>> expression)
		{
			if (QueryBuilder.Includes != null && QueryBuilder.Includes.Count > 0)
			{
				if (pageIndex == 0)
				{
					pageIndex = 1;
				}
				List<TResult> result = Clone().Skip((pageIndex - 1) * pageSize).Take(pageSize).ToList(expression);
				ISugarQueryable<T> sugarQueryable = Clone();
				sugarQueryable.QueryBuilder.Includes = null;
				totalNumber = sugarQueryable.Count();
				return result;
			}
			return Select(expression).ToPageList(pageIndex, pageSize, ref totalNumber).ToList();
		}

