		public virtual async Task<int> CountAsync()
		{
			if (!QueryBuilder.Skip.HasValue && !QueryBuilder.Take.HasValue && QueryBuilder.OrderByValue == null && QueryBuilder.PartitionByValue == null && QueryBuilder.SelectValue == null && QueryBuilder.Includes == null && !QueryBuilder.IsDistinct)
			{
				return (await Clone().Select<int>(" COUNT(1) ").ToListAsync()).FirstOrDefault();
			}
			if ((QueryBuilder.AsTables?.Any() ?? false) && QueryBuilder.AsTables.FirstOrDefault().Value.StartsWith(" (SELECT * FROM  ("))
			{
				ISugarQueryable<T> sugarQueryable = Clone();
				sugarQueryable.QueryBuilder.OrderByValue = null;
				sugarQueryable.QueryBuilder.Includes = null;
				return (await sugarQueryable.Select<int>(" COUNT(1) ").ToListAsync()).FirstOrDefault();
			}
			_CountBegin(out MappingTableList expMapping, out int result);
			result = ((!IsCache) ? (await GetCountAsync()) : CacheSchemeMain.GetOrCreate(Context.CurrentConnectionConfig.ConfigureExternalServices.DataInfoCacheService, QueryBuilder, () => GetCount(), CacheTime, Context, CacheKey));
			_CountEnd(expMapping);
			return result;
		}

