		public virtual async Task ForEachAsync(Action<T> action, int singleMaxReads = 300, CancellationTokenSource cancellationTokenSource = null)
		{
			Check.Exception(QueryBuilder.Skip > 0 || QueryBuilder.Take > 0, ErrorMessage.GetThrowMessage("no support Skip take, use PageForEach", "不支持Skip Take,请使用 Queryale.PageForEach"));
			RefAsync<int> totalNumber = 0;
			RefAsync<int> totalPage = 1;
			for (int i = 1; i <= (int)totalPage; i++)
			{
				if (cancellationTokenSource?.IsCancellationRequested ?? false)
				{
					break;
				}
				ISugarQueryable<T> sugarQueryable = Clone();
				List<T> list = (((int)totalPage != 1) ? (await sugarQueryable.ToPageListAsync(i, singleMaxReads)) : (await sugarQueryable.ToPageListAsync(i, singleMaxReads, totalNumber, totalPage)));
				foreach (T item in list)
				{
					if (cancellationTokenSource?.IsCancellationRequested ?? false)
					{
						return;
					}
					action(item);
				}
			}
		}

		public virtual async Task ForEachByPageAsync(Action<T> action, int pageIndex, int pageSize, RefAsync<int> totalNumber, int singleMaxReads = 300, CancellationTokenSource cancellationTokenSource = null)
		{
			int count = Clone().Count();
			if (count > 0)
			{
				if (pageSize > singleMaxReads && count - (pageIndex - 1) * pageSize > singleMaxReads)
				{
					int Skip = (pageIndex - 1) * pageSize;
					int NowCount = count - Skip;
					int number = 0;
					if (NowCount > pageSize)
					{
						NowCount = pageSize;
					}
					while (NowCount > 0)
					{
						if (cancellationTokenSource?.IsCancellationRequested ?? false)
						{
							return;
						}
						if (number + singleMaxReads > pageSize)
						{
							singleMaxReads = NowCount;
						}
						foreach (T item in await Clone().Skip(Skip).Take(singleMaxReads).ToListAsync())
						{
							if (cancellationTokenSource?.IsCancellationRequested ?? false)
							{
								return;
							}
							action(item);
						}
						NowCount -= singleMaxReads;
						Skip += singleMaxReads;
						number += singleMaxReads;
					}
				}
				else
				{
					if (cancellationTokenSource?.IsCancellationRequested ?? false)
					{
						return;
					}
					foreach (T item2 in Clone().ToPageList(pageIndex, pageSize))
					{
						if (cancellationTokenSource?.IsCancellationRequested ?? false)
						{
							return;
						}
						action(item2);
					}
				}
			}
			totalNumber.Value = count;
		}

		public async Task<List<T>> SetContextAsync<ParameterT>(Expression<Func<T, object>> thisFiled1, Expression<Func<object>> mappingFiled1, Expression<Func<T, object>> thisFiled2, Expression<Func<object>> mappingFiled2, ParameterT parameter)
		{
			if (parameter == null)
			{
				return new List<T>();
			}
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<ParameterT>();
			EntityInfo entityInfo2 = Context.EntityMaintenance.GetEntityInfo<T>();
			new List<T>();
			MapperContext<ParameterT> queryableContext = Context.TempItems["Queryable_To_Context"] as MapperContext<ParameterT>;
			List<ParameterT> list = queryableContext.list;
			string key = thisFiled1.ToString() + mappingFiled1.ToString() + thisFiled2.ToString() + mappingFiled2.ToString() + typeof(ParameterT).FullName + typeof(T).FullName;
			MappingFieldsHelper<ParameterT> fieldsHelper = new MappingFieldsHelper<ParameterT>();
			List<MappingFieldsExpression> mappings = new List<MappingFieldsExpression>
			{
				new MappingFieldsExpression
				{
					LeftColumnExpression = thisFiled1,
					LeftEntityColumn = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(thisFiled1)),
					RightColumnExpression = mappingFiled1,
					RightEntityColumn = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(mappingFiled1))
				},
				new MappingFieldsExpression
				{
					LeftColumnExpression = thisFiled2,
					LeftEntityColumn = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(thisFiled2)),
					RightColumnExpression = mappingFiled2,
					RightEntityColumn = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == ExpressionTool.GetMemberName(mappingFiled2))
				}
			};
			List<IConditionalModel> mppingSql = fieldsHelper.GetMppingSql(list.Cast<object>().ToList(), mappings);
			if (queryableContext.TempChildLists == null)
			{
				queryableContext.TempChildLists = new Dictionary<string, object>();
			}
			List<T> list2;
			if (list != null && queryableContext.TempChildLists.ContainsKey(key))
			{
				list2 = (List<T>)queryableContext.TempChildLists[key];
			}
			else
			{
				list2 = await Clone().Where(mppingSql, isWrap: true).ToListAsync();
				queryableContext.TempChildLists[key] = list2;
			}
			List<object> list3 = ((IEnumerable<T>)list2).Select((Func<T, object>)((T it) => it)).ToList();
			object item = parameter;
			return (from it in fieldsHelper.GetSetList(item, list3, mappings)
				select (T)it).ToList();
		}

		public async Task<List<T>> SetContextAsync<ParameterT>(Expression<Func<T, object>> thisFiled, Expression<Func<object>> mappingFiled, ParameterT parameter)
		{
			List<T> result = new List<T>();
			Context.EntityMaintenance.GetEntityInfo<ParameterT>();
			MapperContext<ParameterT> queryableContext = Context.TempItems["Queryable_To_Context"] as MapperContext<ParameterT>;
			List<ParameterT> list = queryableContext.list;
			string pkName = "";
			if (mappingFiled.Body is UnaryExpression)
			{
				pkName = ((mappingFiled.Body as UnaryExpression).Operand as MemberExpression).Member.Name;
			}
			else
			{
				pkName = (mappingFiled.Body as MemberExpression).Member.Name;
			}
			string key = thisFiled.ToString() + mappingFiled.ToString() + typeof(ParameterT).FullName + typeof(T).FullName;
			object[] pageItems = list.Select((ParameterT it) => it.GetType().GetProperty(pkName).GetValue(it)).ToArray();
			if (queryableContext.TempChildLists == null)
			{
				queryableContext.TempChildLists = new Dictionary<string, object>();
			}
			if (list != null && queryableContext.TempChildLists.ContainsKey(key))
			{
				result = (List<T>)queryableContext.TempChildLists[key];
			}
			else
			{
				if (queryableContext.TempChildLists == null)
				{
					queryableContext.TempChildLists = new Dictionary<string, object>();
				}
				await Context.Utilities.PageEachAsync(pageItems, 200, async delegate(List<object> pageIds)
				{
					List<T> list2 = result;
					list2.AddRange(await Clone().In(thisFiled, pageIds).ToListAsync());
				});
				queryableContext.TempChildLists[key] = result;
			}
			string name = "";
			if (thisFiled.Body is UnaryExpression)
			{
				name = ((thisFiled.Body as UnaryExpression).Operand as MemberExpression).Member.Name;
			}
			else
			{
				name = (thisFiled.Body as MemberExpression).Member.Name;
			}
			object pkValue = parameter.GetType().GetProperty(pkName).GetValue(parameter);
			result = result.Where((T it) => it.GetType().GetProperty(name).GetValue(it)
				.ObjToString() == pkValue.ObjToString()).ToList();
			return result;
		}

