		public async Task<Dictionary<string, object>> ToDictionaryAsync(Expression<Func<T, object>> key, Expression<Func<T, object>> value)
		{
			if (!QueryBuilder.IsSingle() && (QueryBuilder.AsTables == null || QueryBuilder.AsTables.Count == 0))
			{
				return await MergeTable().ToDictionaryAsync(key, value);
			}
			QueryBuilder.ResultType = typeof(SugarCacheDictionary);
			string keyName = QueryBuilder.GetExpressionValue(key, ResolveExpressType.FieldSingle).GetResultString();
			string valueName = QueryBuilder.GetExpressionValue(value, ResolveExpressType.FieldSingle).GetResultString();
			List<KeyValuePair<string, object>> source = await Select<KeyValuePair<string, object>>(keyName + "," + valueName).ToListAsync();
			if (Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => it.IsJson && it.PropertyName == ExpressionTool.GetMemberName(value)).Any())
			{
				return Select<T>(keyName + "," + valueName).ToList().ToDictionary(ExpressionTool.GetMemberName(key), ExpressionTool.GetMemberName(value));
			}
			return source.ToDictionary((KeyValuePair<string, object> it) => it.Key.ObjToString(), (KeyValuePair<string, object> it) => it.Value);
		}

