		public async Task<List<T>> ToParentListAsync(Expression<Func<T, object>> parentIdExpression, object primaryKeyValue)
		{
			List<T> result = new List<T>();
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			if (entityInfo.Columns.Any((EntityColumnInfo it) => it.IsTreeKey))
			{
				return await _ToParentListByTreeKeyAsync(parentIdExpression, primaryKeyValue);
			}
			Check.Exception(entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count() == 0, "No Primary key");
			string parentIdName = UtilConvert.ToMemberExpression(parentIdExpression.Body).Member.Name;
			EntityColumnInfo ParentInfo = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == parentIdName);
			_ = ParentInfo.DbColumnName;
			string tableName = QueryBuilder.GetTableNameString;
			if (!QueryBuilder.IsSingle())
			{
				if (QueryBuilder.JoinQueryInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
				if (QueryBuilder.EasyJoinInfos.Count > 0)
				{
					tableName = QueryBuilder.JoinQueryInfos.First().TableName;
				}
			}
			T val = await Context.Queryable<T>().AS(tableName).WithCacheIF(IsCache, CacheTime)
				.Filter(null, QueryBuilder.IsDisabledGobalFilter)
				.InSingleAsync(primaryKeyValue);
			if (val != null)
			{
				result.Add(val);
				object parentId = ParentInfo.PropertyInfo.GetValue(val, null);
				int i = 0;
				while (true)
				{
					bool flag = parentId != null;
					if (flag)
					{
						flag = await Context.Queryable<T>().AS(tableName).Filter(null, QueryBuilder.IsDisabledGobalFilter)
							.In<object>(parentId)
							.AnyAsync();
					}
					if (!flag)
					{
						break;
					}
					Check.Exception(i > 100, ErrorMessage.GetThrowMessage("Dead cycle", "出现死循环或超出循环上限（100），检查最顶层的ParentId是否是null或者0"));
					T val2 = await Context.Queryable<T>().AS(tableName).WithCacheIF(IsCache, CacheTime)
						.Filter(null, QueryBuilder.IsDisabledGobalFilter)
						.InSingleAsync(parentId);
					result.Add(val2);
					parentId = ParentInfo.PropertyInfo.GetValue(val2, null);
					int num = i + 1;
					i = num;
				}
			}
			return result;
		}

