		private List<T> _ToParentListByTreeKey(Expression<Func<T, object>> parentIdExpression, object primaryKeyValue)
		{
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsTreeKey);
			List<T> list = new List<T>();
			string parentIdName = UtilConvert.ToMemberExpression(parentIdExpression.Body).Member.Name;
			EntityColumnInfo entityColumnInfo2 = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == parentIdName);
			_ = entityColumnInfo2.DbColumnName;
			string tableName = QueryBuilder.GetTableNameString;
			if (!QueryBuilder.IsSingle())
