		private List<T> GetChildList(Expression<Func<T, object>> parentIdExpression, string pkName, List<T> list, object rootValue, bool isContainOneself)
		{
			Expression expression = parentIdExpression.Body;
			if (expression is UnaryExpression)
			{
				expression = (expression as UnaryExpression).Operand;
			}
			string name = (expression as MemberExpression).Member.Name;
			return BuildChildList(list, pkName, name, rootValue, isContainOneself);
		}

		private static List<T> BuildChildList(List<T> list, string idName, string pIdName, object rootValue, bool isContainOneself)
		{
			Type typeFromHandle = typeof(T);
			PropertyInfo idProp = typeFromHandle.GetProperty(idName);
			PropertyInfo pIdProp = typeFromHandle.GetProperty(pIdName);
			Dictionary<T, string> kvpList = list.ToDictionary((T x) => x, (T v) => idProp.GetValue(v).ObjToString());
			Dictionary<string, List<T>> groupKv = (from x in list
				group x by pIdProp.GetValue(x).ObjToString()).ToDictionary((IGrouping<string, T> k) => k.Key, (IGrouping<string, T> v) => v.ToList());
			Func<string, List<T>> fc = null;
			fc = delegate(string rootVal)
			{
				List<T> list3 = new List<T>();
				if (groupKv.TryGetValue(rootVal, out var value))
				{
					list3.AddRange(value);
					foreach (T item in value)
					{
						list3.AddRange(fc(kvpList[item]));
					}
				}
				return list3;
			};
			List<T> list2 = fc(rootValue.ObjToString());
			if (isContainOneself)
			{
				T key = kvpList.FirstOrDefault((KeyValuePair<T, string> x) => x.Value == rootValue.ObjToString()).Key;
				if (key != null)
				{
					list2.Insert(0, key);
				}
			}
			return list2;
		}

		private List<object> GetPrentIds(List<T> list, object id, EntityColumnInfo pkName, EntityColumnInfo parentName)
		{
			object currentId = id;
			List<object> list2 = new List<object>();
			list2.Add(id);
			while (list.Any((T it) => pkName.PropertyInfo.GetValue(it).ObjToString() == currentId.ObjToString()))
			{
				T val = list.First((T it) => pkName.PropertyInfo.GetValue(it).ObjToString() == currentId.ObjToString());
				currentId = parentName.PropertyInfo.GetValue(val);
				list2.Add(currentId);
			}
			return list2;
		}

		private List<T> TreeAndFilterIds(Expression<Func<T, IEnumerable<object>>> childListExpression, Expression<Func<T, object>> parentIdExpression, object rootValue, object[] childIds, ref List<T> list)
		{
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			string pk = GetTreeKey(entityInfo);
			EntityColumnInfo pkColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo z) => z.PropertyName == pk);
			List<object> newIds = new List<object>();
			string parentIdName = GetParentName(parentIdExpression);
			EntityColumnInfo parentName = entityInfo.Columns.FirstOrDefault((EntityColumnInfo z) => z.PropertyName == parentIdName);
			foreach (object id in childIds)
			{
				newIds.AddRange(GetPrentIds(list, id, pkColumn, parentName));
			}
			list = list.Where((T z) => newIds.Any((object it) => it.ObjToString() == pkColumn.PropertyInfo.GetValue(z).ObjToString())).ToList();
			return GetTreeRoot(childListExpression, parentIdExpression, pk, list, rootValue);
		}

		private List<T> TreeAndFilterIds(Expression<Func<T, IEnumerable<object>>> childListExpression, Expression<Func<T, object>> parentIdExpression, Expression<Func<T, object>> primaryKeyExpresion, object rootValue, object[] childIds, ref List<T> list)
		{
			EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
			string pk = ExpressionTool.GetMemberName(primaryKeyExpresion);
			EntityColumnInfo pkColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo z) => z.PropertyName == pk);
			List<object> newIds = new List<object>();
			string parentIdName = GetParentName(parentIdExpression);
			EntityColumnInfo parentName = entityInfo.Columns.FirstOrDefault((EntityColumnInfo z) => z.PropertyName == parentIdName);
			foreach (object id in childIds)
			{
				newIds.AddRange(GetPrentIds(list, id, pkColumn, parentName));
			}
			list = list.Where((T z) => newIds.Any((object it) => it.ObjToString() == pkColumn.PropertyInfo.GetValue(z).ObjToString())).ToList();
			return GetTreeRoot(childListExpression, parentIdExpression, pk, list, rootValue);
		}

		internal List<T> GetTreeRoot(Expression<Func<T, IEnumerable<object>>> childListExpression, Expression<Func<T, object>> parentIdExpression, string pk, List<T> list, object rootValue)
		{
			string name = (childListExpression.Body as MemberExpression).Member.Name;
			string parentName = GetParentName(parentIdExpression);
			return UtilMethods.BuildTree(Context, list, pk, parentName, name, rootValue)?.ToList() ?? null;
		}

		private static string GetParentName(Expression<Func<T, object>> parentIdExpression)
		{
			Expression expression = parentIdExpression.Body;
			if (expression is UnaryExpression)
			{
				expression = (expression as UnaryExpression).Operand;
			}
			return (expression as MemberExpression).Member.Name;
		}

		public List<T> GetTreeChildList(List<T> alllist, object pkValue, string pkName, string childName, string parentIdName)
		{
			List<T> list = alllist.Where((T it) => it.GetType().GetProperty(parentIdName).GetValue(it)
				.ObjToString() == pkValue.ObjToString()).ToList();
			if (list != null && list.Count > 0)
			{
				foreach (T item in list)
				{
					object value = item.GetType().GetProperty(pkName).GetValue(item);
					item.GetType().GetProperty(childName).SetValue(item, GetTreeChildList(alllist, value, pkName, childName, parentIdName));
				}
			}
			return list;
		}

		private static string GetTreeKey(EntityInfo entity)
		{
			Check.Exception(entity.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey || it.IsTreeKey).Count() == 0, "need IsPrimary=true Or IsTreeKey=true");
			string text = entity.Columns.Where((EntityColumnInfo it) => it.IsTreeKey).FirstOrDefault()?.PropertyName;
			if (text == null)
			{
				text = entity.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault()?.PropertyName;
			}
			return text;
		}

		protected int GetCount()
		{
			string empty = string.Empty;
			ToSqlBefore();
			empty = QueryBuilder.ToSqlString();
			empty = QueryBuilder.ToCountSql(empty);
			bool isDisableMasterSlaveSeparation = Context.Ado.IsDisableMasterSlaveSeparation;
			if (QueryBuilder.IsDisableMasterSlaveSeparation)
			{
				Context.Ado.IsDisableMasterSlaveSeparation = true;
			}
			int result = Context.Ado.GetInt(empty, QueryBuilder.Parameters.ToArray());
			Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
			return result;
		}

		protected async Task<int> GetCountAsync()
		{
			_ = string.Empty;
			ToSqlBefore();
			string sql = QueryBuilder.ToSqlString();
			sql = QueryBuilder.ToCountSql(sql);
			return Convert.ToInt32(await Context.Ado.GetScalarAsync(sql, QueryBuilder.Parameters.ToArray()));
		}

		private void _CountEnd(MappingTableList expMapping)
		{
			RestoreMapping();
			QueryBuilder.IsCount = false;
			if (expMapping.Count > 0)
			{
				if (QueryableMappingTableList == null)
				{
					QueryableMappingTableList = new MappingTableList();
				}
				QueryableMappingTableList.Add(expMapping.First());
			}
		}

		private void _CountBegin(out MappingTableList expMapping, out int result)
		{
			expMapping = new MappingTableList();
			if (QueryBuilder.EntityName == "ExpandoObject" && Context.MappingTables.Any((MappingTable it) => it.EntityName == "ExpandoObject"))
			{
				expMapping.Add("ExpandoObject", Context.MappingTables.First((MappingTable it) => it.EntityName == "ExpandoObject").DbTableName);
			}
			InitMapping();
			QueryBuilder.IsCount = true;
			result = 0;
		}

		protected TResult _Min<TResult>(Expression expression)
		{
			if (QueryBuilder.IsSqlQuery)
			{
				QueryBuilder.IsSqlQuery = false;
			}
			QueryBuilder.CheckExpression(expression, "Main");
			bool flag = QueryBuilder.IsSingle();
			ExpressionResult expressionValue = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple);
			TResult result = Min<TResult>(expressionValue.GetResultString());
			QueryBuilder.SelectValue = null;
			return result;
		}

