		private void RestChangeMasterQuery(bool isChangeQueryableMasterSlave)
		{
			if (isChangeQueryableMasterSlave)
			{
				Context.Ado.IsDisableMasterSlaveSeparation = false;
			}
		}

		private bool GetIsMasterQuery()
		{
			int num;
			if (QueryBuilder.IsDisableMasterSlaveSeparation && !Context.Ado.IsDisableMasterSlaveSeparation)
			{
				num = ((Context.Ado.Transaction == null) ? 1 : 0);
				if (num != 0)
				{
					Context.Ado.IsDisableMasterSlaveSeparation = true;
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		private void RestChangeSlaveQuery(bool isChangeQueryableSlaveSlave)
		{
			if (isChangeQueryableSlaveSlave)
			{
				Context.Ado.IsDisableMasterSlaveSeparation = true;
			}
