		private bool GetIsSlaveQuery()
		{
			int num;
			if (QueryBuilder.IsEnableMasterSlaveSeparation && Context.Ado.IsDisableMasterSlaveSeparation)
			{
				num = ((Context.Ado.Transaction == null) ? 1 : 0);
				if (num != 0)
				{
					Context.Ado.IsDisableMasterSlaveSeparation = false;
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		internal bool IsAppendNavColumns()
		{
			if (QueryBuilder.Includes.HasValue())
			{
				return QueryBuilder.AppendNavInfo == null;
			}
			return false;
		}

		internal void SetAppendNavColumns(Expression expression)
		{
			_ = expression.Type;
			Dictionary<string, Expression> newExpressionItemList = ExpressionTool.GetNewExpressionItemList(expression);
			IEnumerable<NavigatManager<T>> enumerable = QueryBuilder.Includes.Cast<NavigatManager<T>>();
			if (enumerable.FirstOrDefault() != null)
			{
				QueryBuilder.AppendNavInfo = new AppendNavInfo();
				AppendNavInfo appendNavInfo = QueryBuilder.AppendNavInfo;
				List<EntityColumnInfo> columns = EntityInfo.Columns;
				IEnumerable<EntityColumnInfo> pkColumns = columns.Where((EntityColumnInfo it) => it.IsPrimarykey);
				AddAppendProperties(enumerable, appendNavInfo, columns, pkColumns);
				AddMappingNavProperties(newExpressionItemList, appendNavInfo, columns);
			}
		}

		private void AddMappingNavProperties(Dictionary<string, Expression> dic, AppendNavInfo navInfo, List<EntityColumnInfo> entityColumns)
		{
			foreach (KeyValuePair<string, Expression> item in dic)
			{
				Expression value = item.Value;
				List<Expression> expressions = new ExpressionTreeVisitor().GetExpressions(value);
				bool flag = expressions.Any() && ExpressionTool.GetMethodName(expressions.Last()).IsIn("Any", "Count");
				if (!expressions.Any() || flag)
				{
					continue;
				}
				string name = ExpressionTool.GetMemberName(expressions.First());
				if (name != null && entityColumns.Any((EntityColumnInfo it) => it.Navigat != null && it.PropertyName == name))
				{
					MappingNavColumnInfo value2 = new MappingNavColumnInfo
					{
						ExpressionList = expressions,
						Name = name
					};
					navInfo.MappingNavProperties.Add(item.Key, value2);
				}
				else if (ExpressionTool.IsNavMember(Context, value))
				{
					MappingNavColumnInfo mappingNavColumnInfo = new MappingNavColumnInfo
					{
						ExpressionList = expressions,
						Name = name
					};
					if (value is MemberExpression { Expression: MemberExpression expression })
					{
						mappingNavColumnInfo.ParentName = expression.Member.Name;
					}
					navInfo.MappingNavProperties.Add(item.Key, mappingNavColumnInfo);
				}
			}
		}

		private static void AddAppendProperties(IEnumerable<NavigatManager<T>> navManages, AppendNavInfo navInfo, List<EntityColumnInfo> entityColumns, IEnumerable<EntityColumnInfo> pkColumns)
		{
			foreach (EntityColumnInfo pkColumn in pkColumns)
			{
				navInfo.AppendProperties.Add(pkColumn.PropertyName, pkColumn.DbColumnName);
			}
			foreach (NavigatManager<T> navManage in navManages)
			{
				Expression expression = navManage.Expressions.First();
				string navName = ExpressionTool.GetMemberName(expression);
				if (expression is LambdaExpression && ExpressionTool.GetMethodName((expression as LambdaExpression).Body) == "ToList")
				{
					navName = ExpressionTool.GetFirstTypeNameFromExpression(expression);
				}
				EntityColumnInfo entityColumnInfo = (from it in entityColumns
					where !it.IsPrimarykey
					where it.Navigat != null
					select it).FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navName);
				if (entityColumnInfo != null && entityColumnInfo.Navigat.NavigatType != NavigateType.ManyToMany)
				{
					string name1 = entityColumnInfo.Navigat.Name;
					string name2 = entityColumnInfo.Navigat.Name2;
					EntityColumnInfo entityColumnInfo2 = entityColumns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name1);
					EntityColumnInfo entityColumnInfo3 = entityColumns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name2);
					if (entityColumnInfo2 != null && (entityColumnInfo.Navigat.NavigatType != NavigateType.OneToMany || entityColumnInfo2.DbColumnName != null) && !navInfo.AppendProperties.ContainsKey(entityColumnInfo2.PropertyName))
					{
						navInfo.AppendProperties.Add(entityColumnInfo2.PropertyName, entityColumnInfo2.DbColumnName);
					}
					if (entityColumnInfo3 != null && !navInfo.AppendProperties.ContainsKey(entityColumnInfo3.PropertyName))
					{
						navInfo.AppendProperties.Add(entityColumnInfo3.PropertyName, entityColumnInfo3.DbColumnName);
					}
					if (entityColumnInfo.Navigat.NavigatType != NavigateType.Dynamic || !name1.HasValue())
					{
						continue;
					}
					foreach (JToken jitem in JArray.Parse(name1))
					{
						EntityColumnInfo entityColumnInfo4 = entityColumns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(((object)jitem[(object)"m"]).ToString()) || it.DbColumnName.EqualCase(((object)jitem[(object)"m"]).ToString()));
						if (entityColumnInfo4 != null && !navInfo.AppendProperties.ContainsKey(entityColumnInfo4.PropertyName))
						{
							navInfo.AppendProperties.Add(entityColumnInfo4.PropertyName, entityColumnInfo4.DbColumnName);
						}
					}
				}
				else if (entityColumnInfo != null && entityColumnInfo.Navigat.NavigatType == NavigateType.ManyToMany)
				{
					string name3 = entityColumnInfo.Navigat.AClassId;
					EntityColumnInfo entityColumnInfo5 = entityColumns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name3);
					if (entityColumnInfo5 != null && !navInfo.AppendProperties.ContainsKey(entityColumnInfo5.PropertyName))
					{
						navInfo.AppendProperties.Add(entityColumnInfo5.PropertyName, entityColumnInfo5.DbColumnName);
					}
				}
			}
		}

		private async Task _InitNavigatAsync<TResult>(List<TResult> result)
		{
			if (QueryBuilder.Includes != null)
			{
				await Task.Run(delegate
				{
					_InitNavigat(result);
				});
			}
		}

		private void _InitNavigat<TResult>(List<TResult> result)
		{
			if (QueryBuilder.Includes == null)
			{
				return;
			}
			List<object> includes = QueryBuilder.Includes;
			AppendNavInfo appendNavInfo = QueryBuilder.AppendNavInfo;
			if (appendNavInfo != null && appendNavInfo.AppendProperties?.Any() == true)
			{
				if (result.HasValue())
				{
					SelectNavQuery(result, includes);
				}
				return;
			}
			foreach (object item in includes)
			{
				if (item is NavigatManager<TResult> navigatManager)
				{
					navigatManager.RootList = result;
					navigatManager.Execute();
				}
			}
		}

		private void SelectNavQuery<TResult>(List<TResult> result, List<object> managers)
		{
			if (!result.Any())
			{
				return;
			}
			IList list = null;
			foreach (object manager in managers)
			{
				PropertyInfo property = manager.GetType().GetProperty("RootList");
				Type type = manager.GetType().GenericTypeArguments[0];
				List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfo(type).Columns;
				List<EntityColumnInfo> columns2 = columns.Where((EntityColumnInfo a) => QueryBuilder.AppendNavInfo.Result.First().result.ContainsKey("SugarNav_" + a.PropertyName)).ToList();
				Type listType = typeof(List<>).MakeGenericType(type);
				if (list == null)
				{
					list = SelectNavQuery_SetList(result, manager, property, type, columns2, listType);
				}
				else
				{
					property.SetValue(manager, list);
				}
				manager.GetType().GetMethod("Execute").Invoke(manager, null);
				SelectNavQuery_MappingList(manager, result, list, columns.Where((EntityColumnInfo a) => a.Navigat != null).ToList());
			}
		}

		private void SelectNavQuery_MappingList<TResult>(object it, List<TResult> result, IList outList, List<EntityColumnInfo> columnInfos)
		{
			for (int i = 0; i < result.Count; i++)
			{
				TResult val = result[i];
				object obj = outList[i];
				foreach (KeyValuePair<string, MappingNavColumnInfo> item in QueryBuilder.AppendNavInfo.MappingNavProperties)
				{
					string rightName = item.Value.Name;
					EntityColumnInfo entityColumnInfo = columnInfos.FirstOrDefault((EntityColumnInfo a) => a.PropertyName == rightName);
					bool num = item.Value.ParentName.HasValue();
					if (num)
					{
						entityColumnInfo = columnInfos.FirstOrDefault((EntityColumnInfo a) => a.PropertyName == item.Value.ParentName);
					}
					object obj2 = entityColumnInfo.PropertyInfo.GetValue(obj);
					string key = item.Key;
					if (num)
					{
						if (obj2 == null)
						{
							obj2 = UtilMethods.GetDefaultValue(entityColumnInfo.PropertyInfo.PropertyType);
						}
						obj2 = obj2.GetType().GetProperty(item.Value.Name).GetValue(obj2);
					}
					if (item.Value.ExpressionList.Count > 1 && obj2 != null)
					{
						try
						{
							MethodCallExpression obj3 = (MethodCallExpression)item.Value.ExpressionList.Last();
							ParameterExpression parameterExpression = ExpressionTool.GetParameters(obj3).First();
							object propertyValue = Expression.Lambda(obj3, parameterExpression).Compile().DynamicInvoke(obj);
							UtilMethods.SetAnonymousObjectPropertyValue(val, key, propertyValue);
						}
						catch (Exception ex)
						{
							string text = item.Value.ExpressionList.Last().ToString();
							Check.ExceptionEasy(text + " no support，" + ex.Message, text + "语法不支持，请查Snet.DB.sugar文档询导航DTO用法，" + ex.Message);
						}
					}
					else if (obj2 != null)
					{
						UtilMethods.SetAnonymousObjectPropertyValue(val, key, obj2);
					}
				}
			}
		}

		private IList SelectNavQuery_SetList<TResult>(List<TResult> result, object it, PropertyInfo p, Type tType, List<EntityColumnInfo> columns, Type listType)
		{
			object obj = Activator.CreateInstance(listType);
			p.SetValue(it, obj);
			int num = 0;
			foreach (TResult item in result)
			{
				_ = item;
				object obj2 = Activator.CreateInstance(tType);
				foreach (KeyValuePair<string, object> item2 in QueryBuilder.AppendNavInfo.Result[num].result)
				{
					string propertyName = item2.Key.Replace("SugarNav_", "");
					PropertyInfo propertyInfo = columns.First((EntityColumnInfo i) => i.PropertyName == propertyName).PropertyInfo;
					if (item2.Value is decimal && UtilMethods.GetUnderType(propertyInfo.PropertyType).IsIn(new Type[2]
					{
						typeof(int),
						typeof(long)
					}))
					{
						object value = UtilMethods.ChangeType2(item2.Value, propertyInfo.PropertyType);
						propertyInfo.SetValue(obj2, value);
					}
					else if (item2.Value == DBNull.Value && UtilMethods.GetUnderType(propertyInfo.PropertyType).IsIn(new Type[2]
					{
						typeof(int),
						typeof(long)
					}))
					{
						object value2 = UtilMethods.ChangeType2(0, propertyInfo.PropertyType);
						propertyInfo.SetValue(obj2, value2);
					}
					else if (item2.Value == DBNull.Value)
					{
						propertyInfo.SetValue(obj2, null);
					}
					else if (UtilMethods.GetUnderType(propertyInfo.PropertyType) == typeof(Guid) && item2.Value is string)
					{
						propertyInfo.SetValue(obj2, new Guid(item2.Value.ToString()));
					}
					else if (UtilMethods.GetUnderType(propertyInfo.PropertyType) == typeof(int) && item2.Value is long)
					{
						propertyInfo.SetValue(obj2, Convert.ToInt32(item2.Value));
					}
					else if (propertyInfo.PropertyType.FullName == "System.Ulid")
					{
						propertyInfo.SetValue(obj2, UtilMethods.To(item2.Value, propertyInfo.PropertyType));
					}
					else if (item2.Value is string text && text != null && text != null && text.StartsWith("[") && text != null && text.EndsWith("]") && UtilMethods.IsArrayOrList(propertyInfo.PropertyType))
					{
						propertyInfo.SetValue(obj2, UtilMethods.ConvertToArray(item2.Value?.ToString(), propertyInfo.PropertyType));
					}
					else
					{
						propertyInfo.SetValue(obj2, item2.Value);
					}
				}
				(obj as IList).Add(obj2);
				num++;
			}
			return obj as IList;
		}

		private bool IsSelectNavQuery()
		{
			if (QueryBuilder.SelectValue.HasValue())
			{
				return !QueryBuilder.NoCheckInclude;
			}
			return false;
		}

		protected void _Mapper<TResult>(List<TResult> result)
		{
			if (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsTranscoding))
			{
				foreach (TResult item in result)
				{
					foreach (EntityColumnInfo item2 in EntityInfo.Columns.Where((EntityColumnInfo it) => it.IsTranscoding))
					{
						object value = item2.PropertyInfo.GetValue(item, null);
						if (value != null)
						{
							item2.PropertyInfo.SetValue(item, UtilMethods.DecodeBase64(value.ToString()), null);
						}
					}
				}
			}
			if (Mappers.HasValue())
			{
				foreach (Action<List<T>> mapper in Mappers)
				{
					if (typeof(TResult) == typeof(T))
					{
						mapper(result.Select((TResult it) => (T)Convert.ChangeType(it, typeof(T))).ToList());
					}
					else
					{
						Check.Exception(true, "{0} and {1} are not a type, Try .select().mapper().ToList", typeof(TResult).FullName, typeof(T).FullName);
					}
				}
			}
			if (MapperAction != null)
			{
				foreach (TResult item3 in result)
				{
					if (typeof(TResult) == typeof(T))
					{
						foreach (Action<T> item4 in MapperAction)
						{
							item4((T)(object)item3);
						}
					}
					else
					{
						Check.Exception(true, "{0} and {1} are not a type, Try .select().mapper().ToList", typeof(TResult).FullName, typeof(T).FullName);
					}
				}
			}
			if (MapperActionWithCache == null)
			{
				return;
			}
			if (typeof(TResult) == typeof(T))
			{
				List<T> obj = (List<T>)Convert.ChangeType(result, typeof(List<T>));
				MapperCache<T> mapperCache = new MapperCache<T>(obj, Context);
				{
					foreach (T item5 in obj)
					{
						mapperCache.GetIndex = 0;
						MapperActionWithCache(item5, mapperCache);
					}
					return;
				}
			}
			Check.Exception(true, "{0} and {1} are not a type, Try .select().mapper().ToList", typeof(TResult).FullName, typeof(T).FullName);
		}

		private ISugarQueryable<T> _Mapper<TObject>(Expression mapperObject, Expression mapperField)
		{
			mapperObject = ((!((mapperObject as LambdaExpression).Body is UnaryExpression)) ? (mapperObject as LambdaExpression).Body : ((mapperObject as LambdaExpression).Body as UnaryExpression).Operand);
			mapperField = ((!((mapperField as LambdaExpression).Body is UnaryExpression)) ? (mapperField as LambdaExpression).Body : ((mapperField as LambdaExpression).Body as UnaryExpression).Operand);
			Check.Exception(!(mapperObject is MemberExpression) || !(mapperField is MemberExpression), ".Mapper() parameter error");
			MemberExpression memberExpression = mapperObject as MemberExpression;
			MemberExpression memberExpression2 = mapperField as MemberExpression;
			Check.Exception(memberExpression2.Type.IsClass(), ".Mapper() parameter error");
			Type type = memberExpression.Type;
			Type type2 = memberExpression2.Expression.Type;
			Check.Exception(type != typeof(TObject) && type != typeof(List<TObject>), ".Mapper() parameter error");
			if (type == typeof(List<TObject>))
			{
				type = typeof(TObject);
			}
			string filedName = memberExpression2.Member.Name;
			string objName = memberExpression.Member.Name;
			EntityInfo filedEntity = Context.EntityMaintenance.GetEntityInfo(type);
			Context.EntityMaintenance.GetEntityInfo(type2);
			bool num = type2 == typeof(T);
			if (Mappers == null)
			{
				Mappers = new List<Action<List<T>>>();
			}
			if (num)
			{
				Action<List<T>> item = delegate(List<T> entitys)
				{
					if (entitys.IsNullOrEmpty() || !entitys.Any())
					{
						return;
					}
					entitys.First();
					EntityColumnInfo whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(filedName, StringComparison.CurrentCultureIgnoreCase));
					if (whereCol == null)
					{
						whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
					}
					if (whereCol == null)
					{
						whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => GetPrimaryKeys().Any((string pk) => pk.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase)));
					}
					if (whereCol == null)
					{
						whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals("id", StringComparison.CurrentCultureIgnoreCase));
					}
					if (whereCol == null)
					{
						whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(it.EntityName + "id", StringComparison.CurrentCultureIgnoreCase));
					}
					if (whereCol == null)
					{
						Check.Exception(true, ".Mapper() parameter error");
					}
					List<string> list = entitys.Select((T it) => it.GetType().GetProperty(filedName).GetValue(it, null)
						.ObjToString()).ToList();
					if (list != null && list.Any() && UtilMethods.GetUnderType(entitys.First().GetType().GetProperty(filedName)
						.PropertyType) == UtilConstants.GuidType)
						{
							list = list.Select((string x) => (!(x == "")) ? x : "null").Distinct().ToList();
						}
						List<IConditionalModel> conditionalModels = new List<IConditionalModel>
						{
							new ConditionalModel
							{
								FieldName = SqlBuilder.GetTranslationColumnName(whereCol.DbColumnName),
								ConditionalType = ConditionalType.In,
								FieldValue = string.Join(",", list.Distinct()),
								CSharpTypeName = whereCol.PropertyInfo.PropertyType.Name
							}
						};
						List<TObject> source = Context.Queryable<TObject>().Where(conditionalModels).ToList();
						foreach (T entity in entitys)
						{
							object whereValue = entity.GetType().GetProperty(filedName).GetValue(entity, null);
							List<TObject> source2 = source.Where((TObject x) => x.GetType().GetProperty(whereCol.PropertyName).GetValue(x, null)
								.ObjToString() == whereValue.ObjToString()).ToList();
							PropertyInfo property = entity.GetType().GetProperty(objName);
							if (property.PropertyType.FullName.IsCollectionsList())
							{
								property.SetValue(entity, source2.ToList(), null);
							}
							else
							{
								property.SetValue(entity, source2.FirstOrDefault(), null);
							}
						}
					};
					Mappers.Add(item);
				}
				else
				{
					Action<List<T>> item2 = delegate(List<T> entitys)
					{
						if (entitys.IsNullOrEmpty() || !entitys.Any())
						{
							return;
						}
						entitys.First();
						EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
						EntityColumnInfo whereCol = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(filedName, StringComparison.CurrentCultureIgnoreCase));
						if (whereCol == null)
						{
							whereCol = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
						}
						if (whereCol == null)
						{
							whereCol = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => GetPrimaryKeys().Any((string pk) => pk.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase)));
						}
						if (whereCol == null)
						{
							whereCol = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals("id", StringComparison.CurrentCultureIgnoreCase));
						}
						if (whereCol == null)
						{
							whereCol = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(it.EntityName + "id", StringComparison.CurrentCultureIgnoreCase));
						}
						if (whereCol == null)
						{
							Check.Exception(true, ".Mapper() parameter error");
						}
						List<string> values = entitys.Select((T it) => it.GetType().GetProperty(whereCol.PropertyName).GetValue(it, null)
							.ObjToString()).ToList();
						string dbColumnName = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == filedName).DbColumnName;
						List<IConditionalModel> conditionalModels = new List<IConditionalModel>
						{
							new ConditionalModel
							{
								FieldName = dbColumnName,
								ConditionalType = ConditionalType.In,
								FieldValue = string.Join(",", values)
							}
						};
						List<TObject> source = Context.Queryable<TObject>().Where(conditionalModels).ToList();
						foreach (T entity2 in entitys)
						{
							object whereValue = entity2.GetType().GetProperty(whereCol.PropertyName).GetValue(entity2, null);
							List<TObject> source2 = source.Where((TObject x) => x.GetType().GetProperty(filedName).GetValue(x, null)
								.ObjToString() == whereValue.ObjToString()).ToList();
							PropertyInfo property = entity2.GetType().GetProperty(objName);
							if (property.PropertyType.FullName.IsCollectionsList())
							{
								property.SetValue(entity2, source2.ToList(), null);
							}
							else
							{
								property.SetValue(entity2, source2.FirstOrDefault(), null);
							}
						}
					};
					Mappers.Add(item2);
				}
				return this;
			}

			private ISugarQueryable<T> _Mapper<TObject>(Expression mapperObject, Expression mainField, Expression childField)
			{
				mapperObject = ((!((mapperObject as LambdaExpression).Body is UnaryExpression)) ? (mapperObject as LambdaExpression).Body : ((mapperObject as LambdaExpression).Body as UnaryExpression).Operand);
				mainField = ((!((mainField as LambdaExpression).Body is UnaryExpression)) ? (mainField as LambdaExpression).Body : ((mainField as LambdaExpression).Body as UnaryExpression).Operand);
				childField = ((!((childField as LambdaExpression).Body is UnaryExpression)) ? (childField as LambdaExpression).Body : ((childField as LambdaExpression).Body as UnaryExpression).Operand);
				Check.Exception(!(mapperObject is MemberExpression) || !(mainField is MemberExpression), ".Mapper() parameter error");
				MemberExpression memberExpression = mapperObject as MemberExpression;
				MemberExpression memberExpression2 = mainField as MemberExpression;
				MemberExpression memberExpression3 = childField as MemberExpression;
				Check.Exception(memberExpression2.Type.IsClass(), ".Mapper() parameter error");
				Check.Exception(memberExpression3.Type.IsClass(), ".Mapper() parameter error");
				Type type = memberExpression.Type;
				Type type2 = memberExpression2.Expression.Type;
				Check.Exception(type != typeof(TObject) && type != typeof(List<TObject>), ".Mapper() parameter error");
				if (type == typeof(List<TObject>))
				{
					type = typeof(TObject);
				}
				string mainFiledName = memberExpression2.Member.Name;
				string childFiledName = memberExpression3.Member.Name;
				string objName = memberExpression.Member.Name;
				EntityInfo filedEntity = Context.EntityMaintenance.GetEntityInfo(type);
				Context.EntityMaintenance.GetEntityInfo(type2);
				bool num = type2 == typeof(T);
				if (Mappers == null)
				{
					Mappers = new List<Action<List<T>>>();
				}
				if (num)
				{
					Action<List<T>> item = delegate(List<T> entitys)
					{
						if (entitys.IsNullOrEmpty() || !entitys.Any())
						{
							return;
						}
						entitys.First();
						EntityColumnInfo whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals(childFiledName, StringComparison.CurrentCultureIgnoreCase));
						if (whereCol == null)
						{
							whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
						}
						if (whereCol == null)
						{
							whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => GetPrimaryKeys().Any((string pk) => pk.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase)));
						}
						if (whereCol == null)
						{
							whereCol = filedEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.Equals("id", StringComparison.CurrentCultureIgnoreCase));
						}
