			private void SetContextModel<TResult>(List<TResult> result, Type entityType)
			{
				if (!result.HasValue() || !UtilMethods.GetRootBaseType(entityType).HasValue() || !(UtilMethods.GetRootBaseType(entityType) == UtilConstants.ModelType))
				{
					return;
				}
				foreach (TResult item in result)
				{
					PropertyInfo? property = item.GetType().GetProperty("Context");
					SqlSugarProvider sqlSugarProvider = Context.Utilities.CopyContext();
					sqlSugarProvider.Ado.IsDisableMasterSlaveSeparation = true;
					if (sqlSugarProvider.CurrentConnectionConfig.AopEvents == null)
					{
						sqlSugarProvider.CurrentConnectionConfig.AopEvents = new AopEvents();
					}
					property.SetValue(item, sqlSugarProvider, null);
				}
			}

