			private void orderPropertyNameByJoin(string orderPropertyName, OrderByType? orderByType)
			{
				string shortName = orderPropertyName.Split('.').FirstOrDefault();
				orderPropertyName = orderPropertyName.Split('.').Last();
				Type type = QueryBuilder.JoinQueryInfos.FirstOrDefault((JoinQueryInfo it) => it.ShortName.EqualCase(shortName))?.EntityType;
				if (type == null)
				{
					type = EntityInfo.Type;
				}
				if (Context.EntityMaintenance.GetEntityInfoWithAttr(type).Columns.Any(delegate(EntityColumnInfo it)
				{
					string dbColumnName = it.DbColumnName;
					return (dbColumnName != null && dbColumnName.EqualCase(orderPropertyName)) || (it.PropertyName?.EqualCase(orderPropertyName) ?? false);
				}))
				{
					string propertyName = Context.EntityMaintenance.GetEntityInfoWithAttr(type).Columns.FirstOrDefault(delegate(EntityColumnInfo it)
					{
						string dbColumnName = it.DbColumnName;
						return (dbColumnName != null && dbColumnName.EqualCase(orderPropertyName)) || (it.PropertyName?.EqualCase(orderPropertyName) ?? false);
					})?.DbColumnName;
					string[] obj = new string[5]
					{
						SqlBuilder.GetTranslationColumnName(shortName),
						".",
						SqlBuilder.GetTranslationColumnName(propertyName),
						" ",
						null
					};
					OrderByType? orderByType2 = orderByType;
					obj[4] = orderByType2.ToString();
					OrderBy(string.Concat(obj));
				}
				else
				{
					Check.ExceptionEasy("OrderByPropertyName error." + orderPropertyName + " does not exist in the entity class", "OrderByPropertyName出错实体类中不存在" + orderPropertyName);
				}
			}

			private void OutIntoTableSql(string TableName, out KeyValuePair<string, List<SugarParameter>> sqlInfo, out string sql, Type tableInfo)
			{
				List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfo(tableInfo).Columns;
				sqlInfo = ToSql();
				string translationTableName = SqlBuilder.GetTranslationTableName(TableName);
				string text = "";
				sql = "";
				if (QueryBuilder.SelectValue is Expression)
				{
					text = "(";
					foreach (KeyValuePair<string, Expression> item in ExpressionTool.GetNewExpressionItemList((Expression)QueryBuilder.SelectValue))
					{
						string text2 = item.Key;
						EntityColumnInfo entityColumnInfo = columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Key);
						if (entityColumnInfo != null)
						{
							text2 = SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName);
						}
						text = text + text2 + ",";
					}
					text = text.TrimEnd(',') + ")";
					sql = $" INSERT  INTO {translationTableName} {text} " + sqlInfo.Key;
					return;
				}
				text = "(";
				string[] array = QueryBuilder.GetSelectValue.Split(',');
				foreach (string input in array)
				{
					string column = Regex.Split(input, " AS ").Last().Trim();
					EntityColumnInfo entityColumnInfo2 = columns.FirstOrDefault((EntityColumnInfo it) => SqlBuilder.GetTranslationColumnName(it.PropertyName) == column);
					if (entityColumnInfo2 != null)
					{
						column = SqlBuilder.GetTranslationColumnName(entityColumnInfo2.DbColumnName);
					}
					text = text + column + ",";
				}
				text = text.TrimEnd(',') + ")";
				sql = $" INSERT  INTO {translationTableName} {text} " + sqlInfo.Key;
			}

			internal string GetTableName(EntityInfo entity, string tableName)
			{
				string text = tableName;
				TenantAttribute tenantAttribute = entity?.Type?.GetCustomAttribute<TenantAttribute>();
				string text2 = Context.CurrentConnectionConfig.ConfigId.ObjToString();
				if (tenantAttribute != null && text2 != tenantAttribute.configId.ObjToString())
				{
					string database = Context.Root.GetConnection(tenantAttribute.configId).Ado.Connection.Database;
					string text3 = Guid.NewGuid().ObjToString();
					database = database.Replace(".", text3);
					tableName = Context.Root.GetConnection(tenantAttribute.configId).EntityMaintenance.GetEntityInfo(entity.Type).DbTableName;
					text = tableName;
					tableName = QueryBuilder.LambdaExpressions.DbMehtods.GetTableWithDataBase(QueryBuilder.Builder.GetTranslationColumnName(database), QueryBuilder.Builder.GetTranslationColumnName(tableName));
					tableName = tableName.Replace(text3, ".");
				}
				if (tenantAttribute != null && text2 != tenantAttribute.configId.ObjToString())
				{
					string dbLinkName = Context.Root.GetConnection(tenantAttribute.configId).CurrentConnectionConfig.DbLinkName;
					if (dbLinkName != null)
					{
						tableName = ((dbLinkName.First() == '@') ? (QueryBuilder.Builder.GetTranslationColumnName(text) + dbLinkName) : ((dbLinkName.Last() != '_') ? (dbLinkName + "." + QueryBuilder.Builder.GetTranslationColumnName(text)) : (dbLinkName + text)));
					}
				}
				if (tableName == null)
				{
					tableName = entity.DbTableName;
				}
				return tableName;
			}

			protected string AppendSelect(List<EntityColumnInfo> entityColumnInfos, string sql, ReadOnlyCollection<ParameterExpression> parameters, List<EntityColumnInfo> columnsResult, int parameterIndex1)
			{
				return AppendSelectWithSubQuery(entityColumnInfos, sql, parameters, columnsResult, parameterIndex1);
			}

			private string AppendSelectWithSubQuery(List<EntityColumnInfo> entityColumnInfos, string sql, ReadOnlyCollection<ParameterExpression> parameters, List<EntityColumnInfo> columnsResult, int parameterIndex1, string parameterName)
			{
				List<string> source = ExpressionTool.GetMemberInit(QueryBuilder.SelectValue)?.Bindings?.Cast<MemberBinding>()?.Select((MemberBinding it) => it.Member.Name)?.ToList() ?? new List<string>();
				if (QueryBuilder.AutoAppendedColumns == null)
				{
					QueryBuilder.AutoAppendedColumns = new List<string>();
				}
				foreach (EntityColumnInfo item in entityColumnInfos)
				{
					if (!item.IsIgnore && !QueryBuilder.AutoAppendedColumns.Contains(item.PropertyName) && columnsResult.Any((EntityColumnInfo it) => it.PropertyName.EqualCase(item.PropertyName)) && !source.Any((string it) => it.EqualCase(item.PropertyName)) && !sql.Contains($"{SqlBuilder.GetTranslationColumnName(parameterName)}.{SqlBuilder.GetTranslationColumnName(item.DbColumnName)} AS {SqlBuilder.GetTranslationColumnName(item.PropertyName)}") && !sql.Contains($"{SqlBuilder.GetTranslationColumnName(parameterName)}.{SqlBuilder.GetTranslationColumnName(item.DbColumnName)} AS  {SqlBuilder.GetTranslationColumnName(item.PropertyName)}"))
					{
						sql = $" {sql},{SqlBuilder.GetTranslationColumnName(parameterName)}.{SqlBuilder.GetTranslationColumnName(item.DbColumnName)} AS {SqlBuilder.GetTranslationColumnName(item.PropertyName)} ";
						QueryBuilder.AutoAppendedColumns.Add(item.PropertyName);
					}
				}
				return sql;
			}

			private string AppendSelectWithSubQuery(List<EntityColumnInfo> entityColumnInfos, string sql, ReadOnlyCollection<ParameterExpression> parameters, List<EntityColumnInfo> columnsResult, int parameterIndex1)
			{
				List<string> source = (from MemberBinding it in ExpressionTool.GetMemberInit(QueryBuilder.SelectValue).Bindings
					select it.Member.Name).ToList();
				_ = parameters[parameterIndex1];
				if (QueryBuilder.AutoAppendedColumns == null)
				{
					QueryBuilder.AutoAppendedColumns = new List<string>();
				}
				foreach (EntityColumnInfo item in entityColumnInfos)
				{
					if (!item.IsIgnore && !QueryBuilder.AutoAppendedColumns.Contains(item.PropertyName) && columnsResult.Any((EntityColumnInfo it) => it.PropertyName.EqualCase(item.PropertyName)) && !source.Any((string it) => it.EqualCase(item.PropertyName)) && !sql.Contains(SqlBuilder.GetTranslationColumnName(item.DbColumnName) + " AS " + SqlBuilder.GetTranslationColumnName(item.PropertyName)) && !sql.Contains(SqlBuilder.GetTranslationColumnName(item.DbColumnName) + " AS  " + SqlBuilder.GetTranslationColumnName(item.PropertyName)))
					{
						if (parameterIndex1 == 0 && QueryBuilder.JoinQueryInfos.Any())
						{
							sql = $" {sql},{SqlBuilder.GetTranslationColumnName(QueryBuilder.TableShortName)}.{SqlBuilder.GetTranslationColumnName(item.DbColumnName)} AS {SqlBuilder.GetTranslationColumnName(item.PropertyName)} ";
							QueryBuilder.AutoAppendedColumns.Add(item.PropertyName);
						}
						else
						{
							sql = $" {sql},{SqlBuilder.GetTranslationColumnName(item.DbColumnName)} AS {SqlBuilder.GetTranslationColumnName(item.PropertyName)} ";
							QueryBuilder.AutoAppendedColumns.Add(item.PropertyName);
						}
					}
				}
				return sql;
			}

			protected string AppendSelect<EntityType>(string sql, ReadOnlyCollection<ParameterExpression> parameters, List<EntityColumnInfo> columnsResult, int parameterIndex1)
			{
				List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfoWithAttr(typeof(EntityType)).Columns;
				return AppendSelectWithSubQuery(columns, sql, parameters, columnsResult, parameterIndex1, parameters[parameterIndex1].Name);
			}

			public virtual JoinQueryInfo GetJoinInfo(Expression joinExpression, JoinType joinType)
			{
				QueryBuilder.CheckExpressionNew(joinExpression, "Join");
				QueryBuilder.JoinExpression = joinExpression;
				Expression body = Expression.Lambda(joinExpression).Body;
				ParameterExpression parameterExpression = (body as LambdaExpression).Parameters.Last();
				ExpressionResult expressionValue = QueryBuilder.GetExpressionValue(joinExpression, ResolveExpressType.WhereMultiple);
				Context.InitMappingInfo(parameterExpression.Type);
				JoinQueryInfo joinQueryInfo = new JoinQueryInfo
				{
					JoinIndex = QueryBuilder.JoinQueryInfos.Count,
					JoinType = joinType,
					JoinWhere = expressionValue.GetResultString(),
					ShortName = parameterExpression.Name,
					EntityType = parameterExpression.Type,
					TableName = null
				};
				if (QueryBuilder.IsCrossQueryWithAttr)
				{
					joinQueryInfo.TableName = GetTableName(Context.EntityMaintenance.GetEntityInfoWithAttr(parameterExpression.Type), joinQueryInfo.TableName);
				}
				else
				{
					joinQueryInfo.TableName = Context.EntityMaintenance.GetTableName(parameterExpression.Type);
				}
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.PgSqlIsAutoToLower == false)
				{
					joinQueryInfo.ShortName = SqlBuilder.GetTranslationColumnName(joinQueryInfo.ShortName);
				}
				if (EntityInfo.Type == joinQueryInfo.EntityType)
				{
					QueryBuilder queryBuilder = QueryBuilder;
					if (queryBuilder != null && queryBuilder.AsTables?.Count() == 1)
					{
						string value = QueryBuilder.AsTables.First().Value;
						if (value.EndsWith(" MergeTable ") && value?.Trim() == QueryBuilder.GetTableNameString?.Trim())
						{
							QueryBuilder.MasterDbTableName = " (SELECT * FROM " + value + ")";
							QueryBuilder.AsTables?.Clear();
						}
					}
				}
				if (joinQueryInfo.JoinIndex == 0)
				{
					ParameterExpression parameterExpression2 = (body as LambdaExpression).Parameters.First();
					QueryBuilder.TableShortName = parameterExpression2.Name;
					if (QueryBuilder.AsTables != null && QueryBuilder.AsTables.Count == 1)
					{
						KeyValuePair<string, string> keyValuePair = QueryBuilder.AsTables.First();
						if (QueryBuilder.TableWithString != "Non")
						{
							ConnectionConfig currentConnectionConfig2 = Context.CurrentConnectionConfig;
							if (currentConnectionConfig2 != null && currentConnectionConfig2.MoreSettings?.IsWithNoLockQuery == true && !QueryBuilder.AsTables.First().Value.ObjToString().Contains("WITH(NOLOCK) "))
							{
								if (QueryBuilder.AsTables.First().Value.EndsWith(") unionTable "))
								{
									QueryBuilder.AsTables[keyValuePair.Key] = " (SELECT * FROM " + QueryBuilder.AsTables.First().Value + ")";
								}
								else if (QueryBuilder.AsTables.First().Value.EndsWith(") MergeTable "))
								{
									QueryBuilder.AsTables[keyValuePair.Key] = " (SELECT * FROM " + QueryBuilder.AsTables.First().Value + ")";
								}
								else
								{
									QueryBuilder.AsTables[keyValuePair.Key] = " (SELECT * FROM " + QueryBuilder.AsTables.First().Value + " WITH(NOLOCK)  )";
								}
								goto IL_054f;
							}
						}
						if (QueryBuilder.IsSqlQuery && QueryBuilder.AsTables.First().Value.ObjToString().StartsWith("("))
						{
							string value2 = QueryBuilder.AsTables.First().Value;
							QueryBuilder.AsTables[keyValuePair.Key] = " (SELECT * FROM " + value2 + ")" + QueryBuilder.TableShortName;
						}
						else
						{
							string text = QueryBuilder.AsTables.First().Value;
							if (text != null && Regex.IsMatch(text.Replace(".", "").Replace("-", ""), "^\\w+$"))
							{
								text = SqlBuilder.GetTranslationTableName(text);
							}
							QueryBuilder.AsTables[keyValuePair.Key] = " (SELECT * FROM " + text + ")";
						}
						goto IL_054f;
					}
				}
				goto IL_057a;
				IL_054f:
				QueryBuilder.SelectValue = SqlBuilder.GetTranslationColumnName(QueryBuilder.TableShortName) + ".*";
				goto IL_057a;
				IL_057a:
				Check.Exception(joinQueryInfo.JoinIndex > 10, ErrorMessage.GetThrowMessage("只支持12个表", "Only 12 tables are supported"));
				return joinQueryInfo;
			}

			protected ISugarQueryable<TResult> _Select<TResult>(Expression expression)
			{
				QueryBuilder.CheckExpression(expression, "Select");
				Context.InitMappingInfo(typeof(TResult));
				ISugarQueryable<TResult> queryable = InstanceFactory.GetQueryable<TResult>(Context.CurrentConnectionConfig);
				queryable.Context = Context;
				queryable.SqlBuilder = SqlBuilder;
				queryable.SqlBuilder.QueryBuilder.Parameters = QueryBuilder.Parameters;
				queryable.SqlBuilder.QueryBuilder.SelectValue = expression;
				queryable.SqlBuilder.QueryBuilder.IsSelectSingleFiledJson = UtilMethods.IsJsonMember(expression, Context);
				queryable.SqlBuilder.QueryBuilder.IsSelectSingleFiledArray = UtilMethods.IsArrayMember(expression, Context);
				if (IsCache)
				{
					queryable.WithCache(CacheTime);
				}
				if (QueryBuilder.IsSqlQuery)
				{
					QueryBuilder.IsSqlQuerySelect = true;
				}
				return queryable;
			}

			protected void _Where(Expression expression)
			{
				QueryBuilder.CheckExpression(expression, "Where");
				bool flag = QueryBuilder.IsSingle();
				ExpressionResult expressionValue = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple);
				QueryBuilder.WhereInfos.Add(SqlBuilder.AppendWhereOrAnd(QueryBuilder.WhereInfos.IsNullOrEmpty(), expressionValue.GetResultString()));
			}

			protected ISugarQueryable<T> _OrderBy(Expression expression, OrderByType type = OrderByType.Asc)
			{
				QueryBuilder.CheckExpression(expression, "OrderBy");
				bool flag = QueryBuilder.IsSingle();
				if (!(ExpressionTool.RemoveConvert(ExpressionTool.GetLambdaExpressionBody(expression)) is MemberExpression) && expression.ToString().IsContainsIn("Desc(", "Asc("))
				{
					string text = "";
					if (!((expression as LambdaExpression).Body is NewExpression newExpression))
					{
						text = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString();
						return OrderBy(text);
					}
					foreach (Expression argument in newExpression.Arguments)
					{
						text = ((!(argument is MemberExpression)) ? (text + QueryBuilder.GetExpressionValue(argument, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple).GetResultString() + ",") : (text + QueryBuilder.GetExpressionValue(argument, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString() + ","));
					}
					text = text.TrimEnd(',');
					OrderBy(text);
					return this;
				}
				if ((expression as LambdaExpression).Body is NewExpression)
				{
					NewExpression obj = (expression as LambdaExpression).Body as NewExpression;
					string text2 = "";
					foreach (Expression argument2 in obj.Arguments)
					{
						text2 = ((argument2 is MemberExpression && type == OrderByType.Asc) ? (text2 + QueryBuilder.GetExpressionValue(argument2, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString() + ",") : ((argument2 is MemberExpression && type == OrderByType.Desc) ? (text2 + QueryBuilder.GetExpressionValue(argument2, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString() + " Desc,") : ((type != OrderByType.Desc) ? (text2 + QueryBuilder.GetExpressionValue(argument2, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple).GetResultString() + ",") : (text2 + QueryBuilder.GetExpressionValue(argument2, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple).GetResultString() + " Desc ,"))));
					}
					text2 = text2.TrimEnd(',');
					OrderBy(text2);
					return this;
				}
				ExpressionResult expressionValue = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple);
				OrderBy(expressionValue.GetResultString() + " " + type.ToString().ToUpper());
				return this;
			}

			private void _ToOffsetPage(int pageIndex, int pageSize)
			{
				QueryBuilder.Offset = $" OFFSET {(pageIndex - 1) * pageSize} ROWS FETCH NEXT {pageSize} ROWS ONLY";
			}

			private int _PageList(int pageIndex, int pageSize)
			{
				if (pageIndex == 0)
				{
					pageIndex = 1;
				}
				if (QueryBuilder.PartitionByValue.HasValue())
				{
					QueryBuilder.ExternalPageIndex = pageIndex;
					QueryBuilder.ExternalPageSize = pageSize;
				}
				else
				{
					QueryBuilder.Skip = (pageIndex - 1) * pageSize;
					QueryBuilder.Take = pageSize;
				}
				return pageIndex;
			}

			protected ISugarQueryable<T> _GroupBy(Expression expression)
			{
				List<string> oldParameterNames = QueryBuilder.Parameters?.Select((SugarParameter it) => it.ParameterName)?.ToList();
				QueryBuilder.CheckExpression(expression, "GroupBy");
				expression = (expression as LambdaExpression).Body;
				bool flag = QueryBuilder.IsSingle();
				string text = null;
				if (expression is NewExpression)
				{
					foreach (Expression argument in (expression as NewExpression).Arguments)
					{
						text = ((!(argument is MemberExpression)) ? (text + QueryBuilder.GetExpressionValue(argument, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple).GetResultString() + ",") : (text + QueryBuilder.GetExpressionValue(argument, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString() + ","));
					}
					text = text.TrimEnd(',');
				}
				else
				{
					expression = ExpressionTool.RemoveConvert(expression);
					text = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString();
				}
				if (oldParameterNames != null && Context.CurrentConnectionConfig.DbType == DbType.SqlServer)
				{
					List<SugarParameter> list = QueryBuilder.Parameters.Where((SugarParameter it) => !oldParameterNames.Contains(it.ParameterName)).ToList();
					QueryBuilder.GroupParameters = list;
					string sqlString = UtilMethods.GetSqlString(DbType.SqlServer, text, list.ToArray());
					QueryBuilder.GroupBySql = sqlString;
					QueryBuilder.GroupBySqlOld = text;
					if (expression is NewExpression newExpression && newExpression.Arguments.Count > 1)
					{
						foreach (Expression argument2 in newExpression.Arguments)
						{
							QueryBuilder queryBuilder = Context.Queryable<object>().QueryBuilder;
							ResolveExpressType resolveExpressType = (flag ? ResolveExpressType.FieldSingle : ResolveExpressType.WhereMultiple);
							if (argument2 is MemberExpression && resolveExpressType == ResolveExpressType.WhereMultiple)
							{
								resolveExpressType = ResolveExpressType.FieldMultiple;
							}
							string resultString = queryBuilder.GetExpressionValue(argument2, resolveExpressType).GetResultString();
							if (queryBuilder.Parameters.Any())
							{
								string sqlString2 = UtilMethods.GetSqlString(DbType.SqlServer, resultString, queryBuilder.Parameters.ToArray());
								QueryBuilder.GroupBySql = sqlString2;
								QueryBuilder.GroupBySqlOld = sqlString2;
								GroupBy(sqlString2);
							}
							else
							{
								GroupBy(resultString);
							}
						}
						return this;
					}
					GroupBy(text);
				}
				else
				{
					GroupBy(text);
				}
				return this;
			}

			protected ISugarQueryable<T> _As(string tableName, string entityName)
			{
				if (QueryBuilder.AsTables != null && QueryBuilder.AsTables.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> it) => it.Key == entityName))
				{
					if (QueryBuilder.JoinQueryInfos.Count((JoinQueryInfo it) => it.TableName.EqualCase(tableName)) > 1)
					{
						Check.ExceptionEasy($"if same entity name ,.LeftJoin(db.Queryable<{entityName}>,(x,y..)=>....).As(\"{tableName}\")", $"存在相同实体，请使用.LeftJoin(db.Queryable<{entityName}>).As(\"{tableName}\",(x,y..)=>...)");
					}
					Check.Exception(true, ErrorMessage.GetThrowMessage($"use As<{tableName}>(\"{tableName}\")", $"请把 As(\"{tableName}\"), 改成 As<{tableName}实体>(\"{tableName}\")"));
				}
				else
				{
					QueryBuilder.AsTables.Add(entityName, tableName);
				}
				return this;
			}

			protected void _Filter(string FilterName, bool isDisabledGobalFilter)
			{
				QueryBuilder.IsDisabledGobalFilter = isDisabledGobalFilter;
				if (!Context.QueryFilter.GetFilterList.HasValue() || !FilterName.HasValue())
				{
					return;
				}
				foreach (SqlFilterItem item in Context.QueryFilter.GetFilterList.Where((SqlFilterItem it) => it.FilterName == FilterName && it.IsJoinQuery == !QueryBuilder.IsSingle()))
				{
					SqlFilterResult sqlFilterResult = item.FilterValue(Context);
					Where(sqlFilterResult.Sql + " ", sqlFilterResult.Parameters);
				}
			}

			public ISugarQueryable<T> _PartitionBy(Expression expression)
			{
				QueryBuilder.CheckExpression(expression, "PartitionBy");
				expression = (expression as LambdaExpression).Body;
				bool flag = QueryBuilder.IsSingle();
				ExpressionResult expressionResult = null;
				string text = null;
				if (expression is NewExpression)
				{
					expressionResult = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.ArraySingle : ResolveExpressType.ArrayMultiple);
					text = string.Join(",", expressionResult.GetResultArray());
				}
				else
				{
					expressionResult = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple);
					text = expressionResult.GetResultString();
				}
				PartitionBy(text);
				return this;
			}

			protected ISugarQueryable<T> _Having(Expression expression)
			{
				QueryBuilder.CheckExpression(expression, "Having");
				bool flag = QueryBuilder.IsSingle();
				ExpressionResult expressionValue = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple);
				Having(expressionValue.GetResultString());
				return this;
			}

			protected List<TResult> _ToList<TResult>()
			{
				List<TResult> list = null;
				KeyValuePair<string, List<SugarParameter>> sqlObj = _ToSql();
				list = ((!IsCache) ? GetData<TResult>(sqlObj) : CacheSchemeMain.GetOrCreate(Context.CurrentConnectionConfig.ConfigureExternalServices.DataInfoCacheService, QueryBuilder, () => GetData<TResult>(sqlObj), CacheTime, Context, CacheKey));
				RestoreMapping();
				_InitNavigat(list);
				_SubQuery(list);
				_Mapper(list);
				return list;
			}

			protected async Task<List<TResult>> _ToListAsync<TResult>()
			{
				KeyValuePair<string, List<SugarParameter>> sqlObj = _ToSql();
				List<TResult> result;
				if (IsCache)
				{
					ICacheService dataInfoCacheService = Context.CurrentConnectionConfig.ConfigureExternalServices.DataInfoCacheService;
					result = CacheSchemeMain.GetOrCreate(dataInfoCacheService, QueryBuilder, () => GetData<TResult>(sqlObj), CacheTime, Context, CacheKey);
				}
				else
				{
					result = await GetDataAsync<TResult>(sqlObj);
				}
				RestoreMapping();
				await _InitNavigatAsync(result);
				await _SubQueryAsync(result);
				_Mapper(result);
				return result;
			}

			private void ToSqlBefore()
			{
				ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
				if (moreSettings != null && moreSettings.IsWithNoLockQuery && string.IsNullOrEmpty(QueryBuilder.TableWithString) && (!moreSettings.DisableWithNoLockWithTran || !Context.Ado.IsAnyTran()))
				{
					With("WITH(NOLOCK) ");
				}
			}

			protected List<TResult> GetData<TResult>(KeyValuePair<string, List<SugarParameter>> sqlObj)
			{
				bool isComplexModel = QueryBuilder.IsComplexModel(sqlObj.Key);
				Type typeFromHandle = typeof(TResult);
				bool isSlaveQuery = GetIsSlaveQuery();
				bool isMasterQuery = GetIsMasterQuery();
				string key = sqlObj.Key;
				SugarParameter[] parameters = sqlObj.Value.ToArray();
				IDataReader dataReader = Db.GetDataReader(key, parameters);
				Db.GetDataBefore(key, parameters);
				List<TResult> result = ((!typeFromHandle.IsInterface) ? GetData<TResult>(isComplexModel, typeFromHandle, dataReader) : GetData<TResult>(isComplexModel, QueryBuilder.AsType, dataReader));
				Db.GetDataAfter(key, parameters);
				RestChangeMasterQuery(isMasterQuery);
				RestChangeSlaveQuery(isSlaveQuery);
				return result;
			}

			protected async Task<List<TResult>> GetDataAsync<TResult>(KeyValuePair<string, List<SugarParameter>> sqlObj)
			{
				bool isComplexModel = QueryBuilder.IsComplexModel(sqlObj.Key);
				Type entityType = typeof(TResult);
				bool isChangeQueryableSlave = GetIsSlaveQuery();
				bool isChangeQueryableMasterSlave = GetIsMasterQuery();
				string sqlString = sqlObj.Key;
				SugarParameter[] parameters = sqlObj.Value.ToArray();
				IDataReader dataReader = await Db.GetDataReaderAsync(sqlString, parameters);
				Db.GetDataBefore(sqlString, parameters);
				List<TResult> result = ((!entityType.IsInterface) ? (await GetDataAsync<TResult>(isComplexModel, entityType, dataReader)) : (await GetDataAsync<TResult>(isComplexModel, QueryBuilder.AsType, dataReader)));
				Db.GetDataAfter(sqlString, parameters);
				RestChangeMasterQuery(isChangeQueryableMasterSlave);
				RestChangeSlaveQuery(isChangeQueryableSlave);
				return result;
			}

			private List<TResult> GetData<TResult>(bool isComplexModel, Type entityType, IDataReader dataReader)
			{
				Bind.QueryBuilder = QueryBuilder;
				Context.Utilities.QueryBuilder = QueryBuilder;
				List<TResult> result;
				if (entityType == UtilConstants.DynamicType)
				{
					result = Context.Utilities.DataReaderToExpandoObjectList(dataReader) as List<TResult>;
				}
				else
				{
					string name = entityType.Name;
					if (name != null && name.StartsWith("ValueTuple`"))
					{
						result = Db.Context.Utilities.DataReaderToValueTupleType<TResult>(dataReader);
					}
					else if (entityType == UtilConstants.ObjType)
					{
						result = (from it in Context.Utilities.DataReaderToExpandoObjectList(dataReader)
							select (TResult)(object)it).ToList();
					}
					else if (QueryBuilder.IsSelectSingleFiledJson)
					{
						result = Context.Utilities.DataReaderToSelectJsonList<TResult>(dataReader);
					}
					else if (QueryBuilder.IsSelectSingleFiledArray)
					{
						result = Context.Utilities.DataReaderToSelectArrayList<TResult>(dataReader);
					}
					else if (((QueryBuilder.IsParameterizedConstructor || entityType.IsAnonymousType()) | isComplexModel) || StaticConfig.EnableAot)
					{
						if (!entityType.IsClass() && StaticConfig.EnableAot)
						{
							result = Bind.DataReaderToList<TResult>(entityType, dataReader);
						}
						else
						{
							result = Context.Utilities.DataReaderToList<TResult>(dataReader);
							if (StaticConfig.EnableAot)
							{
								ResetNavigationPropertiesForAot(result);
							}
						}
					}
					else
					{
						result = Bind.DataReaderToList<TResult>(entityType, dataReader);
					}
				}
				SetContextModel(result, entityType);
				return result;
			}

			private async Task<List<TResult>> GetDataAsync<TResult>(bool isComplexModel, Type entityType, IDataReader dataReader)
			{
				Bind.QueryBuilder = QueryBuilder;
				Context.Utilities.QueryBuilder = QueryBuilder;
				List<TResult> result;
				if (entityType == UtilConstants.DynamicType)
				{
					result = (await Context.Utilities.DataReaderToExpandoObjectListAsync(dataReader)) as List<TResult>;
				}
				else if (entityType.Name?.StartsWith("ValueTuple`") ?? false)
				{
					result = await Db.Context.Utilities.DataReaderToValueTupleTypeAsync<TResult>(dataReader);
				}
				else if (entityType == UtilConstants.ObjType)
				{
					result = (await Context.Utilities.DataReaderToExpandoObjectListAsync(dataReader)).Select((ExpandoObject it) => (TResult)(object)it).ToList();
				}
				else if (QueryBuilder.IsSelectSingleFiledJson)
				{
					result = await Context.Utilities.DataReaderToSelectJsonListAsync<TResult>(dataReader);
				}
				else if (QueryBuilder.IsSelectSingleFiledArray)
				{
					result = await Context.Utilities.DataReaderToSelectArrayListAsync<TResult>(dataReader);
				}
				else if ((entityType.IsAnonymousType() | isComplexModel) || StaticConfig.EnableAot)
				{
					if (!entityType.IsClass() && StaticConfig.EnableAot)
					{
						result = await Bind.DataReaderToListAsync<TResult>(entityType, dataReader);
					}
					else
					{
						result = await Context.Utilities.DataReaderToListAsync<TResult>(dataReader);
						if (StaticConfig.EnableAot)
						{
							ResetNavigationPropertiesForAot(result);
						}
					}
				}
				else
				{
					result = await Bind.DataReaderToListAsync<TResult>(entityType, dataReader);
				}
				SetContextModel(result, entityType);
				return result;
			}

			private void ResetNavigationPropertiesForAot<TResult>(List<TResult> result)
			{
				if (!StaticConfig.EnableAot)
				{
					return;
				}
				IEnumerable<EntityColumnInfo> enumerable = Context.EntityMaintenance.GetEntityInfo<TResult>().Columns.Where((EntityColumnInfo it) => it.Navigat != null);
				if (!enumerable.Any())
				{
					return;
				}
				foreach (TResult item in result)
				{
					foreach (EntityColumnInfo item2 in enumerable)
					{
						item2.PropertyInfo.SetValue(item, null);
					}
				}
			}

			protected void _InQueryable(Expression expression, KeyValuePair<string, List<SugarParameter>> sqlObj)
			{
				QueryBuilder.CheckExpression(expression, "In");
				string appendSql = sqlObj.Key;
				if (sqlObj.Value.HasValue())
				{
					SqlBuilder.RepairReplicationParameters(ref appendSql, sqlObj.Value.ToArray(), 100);
					QueryBuilder.Parameters.AddRange(sqlObj.Value);
				}
				bool flag = QueryBuilder.IsSingle();
				string resultString = QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString();
				string sqlString = string.Format(QueryBuilder.InTemplate, resultString, appendSql);
				QueryBuilder.WhereInfos.Add(SqlBuilder.AppendWhereOrAnd(QueryBuilder.WhereInfos.IsNullOrEmpty(), sqlString));
				_InQueryableIndex += 100;
			}

