			public virtual ISugarQueryable<T> MergeTableWithSubToListJoin()
			{
				ISugarQueryable<T> sugarQueryable = Clone();
				sugarQueryable.QueryBuilder.AppendValues = null;
				sugarQueryable.QueryBuilder.SubToListParameters = null;
				sugarQueryable.QueryBuilder.AppendColumns = null;
				Check.Exception(MapperAction != null || MapperActionWithCache != null, ErrorMessage.GetThrowMessage("'Mapper’ needs to be written after ‘MergeTable’ ", "Mapper 只能在 MergeTable 之后使用"));
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.ToSql();
				int whereIndex = QueryBuilder.WhereIndex + 1;
				ISugarQueryable<T> sugarQueryable2 = Context.Queryable<T>().AS(SqlBuilder.GetPackTable(keyValuePair.Key, "MergeTable")).AddParameters(keyValuePair.Value)
					.Select("*")
					.With("Non");
				sugarQueryable2.QueryBuilder.WhereIndex = whereIndex;
				sugarQueryable2.QueryBuilder.LambdaExpressions.ParameterIndex = QueryBuilder.LambdaExpressions.ParameterIndex++;
				sugarQueryable2.QueryBuilder.LambdaExpressions.Index = QueryBuilder.LambdaExpressions.Index++;
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					sugarQueryable2.Select("MergeTable.*");
				}
				sugarQueryable2.QueryBuilder.AppendValues = QueryBuilder.AppendValues;
				sugarQueryable2.QueryBuilder.SubToListParameters = QueryBuilder.SubToListParameters;
				sugarQueryable2.QueryBuilder.AppendColumns = QueryBuilder.AppendColumns;
				return sugarQueryable2;
			}

