			private void _SubQuery<TResult>(List<TResult> result)
			{
				if (result == null || result.Count == 0 || QueryBuilder.SubToListParameters == null || !QueryBuilder.SubToListParameters.Any())
				{
					return;
				}
				List<List<QueryableAppendColumn>> appendValues = QueryBuilder.AppendValues;
				foreach (KeyValuePair<string, object> subToListParameter in QueryBuilder.SubToListParameters)
				{
					if (appendValues != null)
					{
						AppendSubWhereToList(result, appendValues, subToListParameter);
					}
					else
					{
						AppendSubToList(result, appendValues, subToListParameter);
					}
				}
			}

			private void AppendSubToList<TResult>(List<TResult> result, List<List<QueryableAppendColumn>> appendValues, KeyValuePair<string, object> subPara)
			{
				List<SugarParameter> parameters = QueryBuilder.Parameters;
				PropertyInfo property = typeof(TResult).GetProperty(subPara.Key);
				Type type = property.PropertyType.GetGenericArguments().FirstOrDefault();
				bool flag = false;
				if (type == null)
				{
					type = property.PropertyType;
					flag = true;
				}
				string sql = subPara.Value.ObjToString().Replace("@sugarIndex", "0");
				sql = SqlBuilder.RemoveParentheses(sql);
				object[] param = new object[2] { sql, parameters };
				object obj = ExpressionBuilderHelper.CallFunc(type, param, Clone(), "SubQueryList");
				for (int i = 0; i < result.Count; i++)
				{
					TResult val = result[i];
					Activator.CreateInstance(property.PropertyType, nonPublic: true);
					if (typeof(TResult).IsAnonymousType())
					{
						if (flag)
						{
							JObject val2 = JObject.FromObject((object)val);
							val2.Property(property.Name).Value = (JToken)(object)JObject.FromObject((obj as IList).Cast<object>().FirstOrDefault());
							result[i] = ((JToken)val2).ToObject<TResult>();
						}
						else
						{
							JObject val3 = JObject.FromObject((object)val);
							val3.Property(property.Name).Value = (JToken)(object)JArray.FromObject(obj);
							result[i] = ((JToken)val3).ToObject<TResult>();
						}
					}
					else if (flag)
					{
						if ((obj as IList).Count > 0)
						{
							property.SetValue(val, (obj as IList)[0]);
						}
					}
					else
					{
						property.SetValue(val, obj);
					}
				}
			}

			private void AppendSubWhereToList<TResult>(List<TResult> result, List<List<QueryableAppendColumn>> appendValues, KeyValuePair<string, object> subPara)
			{
				List<SugarParameter> parameters = QueryBuilder.Parameters;
				int num = 0;
				List<string> list = new List<string>();
				foreach (TResult item in result)
				{
					_ = item;
					string text = subPara.Value.ObjToString();
					foreach (QueryableAppendColumn item2 in appendValues[num])
					{
						ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
						SugarParameter[] parametres = new SugarParameter[1]
						{
							new SugarParameter("@p", item2.Value)
						};
						bool disableNvarchar = true;
						ConnectionConfig currentConnectionConfig2 = Context.CurrentConnectionConfig;
						if (currentConnectionConfig2 != null && currentConnectionConfig2.DbType == DbType.SqlServer)
						{
							ConnectionConfig currentConnectionConfig3 = Context.CurrentConnectionConfig;
							if (currentConnectionConfig3 == null || currentConnectionConfig3.MoreSettings?.DisableNvarchar != true)
