			public ISugarQueryable<T> Mapper<AType, BType, MappingType>(Expression<Func<MappingType, ManyToMany>> expression)
			{
				ReadOnlyCollection<Expression> arguments = (expression.Body as MethodCallExpression).Arguments;
				Type typeFromHandle = typeof(AType);
				Type bType = typeof(BType);
				Type bListType = typeof(List<BType>);
				Context.InitMappingInfo(typeFromHandle);
				Context.InitMappingInfo(bType);
				Context.InitMappingInfo(typeof(MappingType));
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(typeof(MappingType));
				string m_aPropertyName = (arguments[0] as MemberExpression).Member.Name;
				string m_bPropertyName = (arguments[1] as MemberExpression).Member.Name;
				string m_aDbField = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == m_aPropertyName).DbColumnName;
				_ = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == m_bPropertyName).DbColumnName;
				EntityInfo aEntity = Context.EntityMaintenance.GetEntityInfo(typeFromHandle);
				string aPropertyName = aEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey)?.PropertyName;
				Check.Exception(aPropertyName == null, aEntity.EntityName + " no primary key");
				EntityInfo entityInfo2 = Context.EntityMaintenance.GetEntityInfo(bType);
				string bProperty = entityInfo2.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey)?.PropertyName;
				Check.Exception(bProperty == null, entityInfo2.EntityName + " no primary key");
				string bDbFiled = entityInfo2.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey).DbColumnName;
				Mapper(delegate(T it, MapperCache<T> cache)
				{
					Dictionary<object, List<BType>> dictionary = cache.Get(delegate(List<T> oldList)
					{
						List<IConditionalModel> conditionalModels = new List<IConditionalModel>
						{
							new ConditionalModel
							{
								ConditionalType = ConditionalType.In,
								FieldName = m_aDbField,
								FieldValue = string.Join(",", oldList.Select((T z) => UtilMethods.GetPropertyValue(z, aPropertyName)).Distinct())
							}
						};
						List<MappingType> source = Context.Queryable<MappingType>().Where(conditionalModels).ToList();
						source.Select((MappingType z) => UtilMethods.GetPropertyValue(z, m_bPropertyName)).Distinct().ToList();
						conditionalModels = new List<IConditionalModel>
						{
							new ConditionalModel
							{
								ConditionalType = ConditionalType.In,
								FieldName = bDbFiled,
								FieldValue = string.Join(",", source.Select((MappingType z) => UtilMethods.GetPropertyValue(z, m_bPropertyName)).Distinct())
							}
						};
						List<BType> source2 = new List<BType>();
						if (source.Any())
						{
							source2 = Context.Queryable<BType>().Where(conditionalModels).ToList();
						}
						Dictionary<object, List<BType>> dictionary2 = new Dictionary<object, List<BType>>();
						foreach (IGrouping<object, MappingType> item in from z in source
							group z by UtilMethods.GetPropertyValue(z, m_aPropertyName))
						{
							List<object> currentBids = item.Select((MappingType z) => UtilMethods.GetPropertyValue(z, m_bPropertyName)).ToList();
							dictionary2.Add(item.Key, source2.Where((BType z) => currentBids.Contains(UtilMethods.GetPropertyValue(z, bProperty))).ToList());
						}
						return dictionary2;
					}, expression.ToString());
					foreach (EntityColumnInfo column in aEntity.Columns)
					{
						object propertyValue = UtilMethods.GetPropertyValue(it, aPropertyName);
						if (dictionary.ContainsKey(propertyValue))
						{
							if (column.PropertyInfo.PropertyType == bType)
							{
								BType val = UtilMethods.ChangeType(dictionary[propertyValue].FirstOrDefault());
								column.PropertyInfo.SetValue(it, val);
							}
							else if (column.PropertyInfo.PropertyType == bListType)
							{
								List<BType> value = UtilMethods.ChangeType(dictionary[propertyValue]);
								column.PropertyInfo.SetValue(it, value);
							}
						}
					}
				});
				return this;
			}

			public virtual ISugarQueryable<T> Mapper(Action<T, MapperCache<T>> mapperAction)
			{
				MapperActionWithCache = (Action<T, MapperCache<T>>)Delegate.Combine(MapperActionWithCache, mapperAction);
				return this;
			}

