			public ISugarQueryable<T> Where(string fieldName, string conditionalType, object fieldValue)
			{
				string name = fieldName.Replace(".", "_") + QueryBuilder.WhereIndex;
				string whereString = SqlBuilder.GetWhere(fieldName, conditionalType, QueryBuilder.WhereIndex);
				Where(whereString);
				QueryBuilder.WhereIndex++;
				QueryBuilder.Parameters.Add(new SugarParameter(name, fieldValue));
				return this;
			}

