			public ISugarQueryable<T> AddJoinInfo(Type JoinType, Dictionary<string, Type> keyIsShortName_ValueIsType_Dictionary, FormattableString onExpString, JoinType type = Snet.DB.sugar.JoinType.Left)
			{
				LambdaExpression lambdaExpression = DynamicCoreHelper.GetWhere(keyIsShortName_ValueIsType_Dictionary, onExpString);
				string name = lambdaExpression.Parameters.Last((ParameterExpression it) => it.Type == JoinType).Name;
				Context.InitMappingInfo(JoinType);
				string resultString = QueryBuilder.GetExpressionValue(lambdaExpression, ResolveExpressType.WhereMultiple).GetResultString();
				return AddJoinInfo(JoinType, name, resultString, type);
			}

			public ISugarQueryable<T> AddJoinInfo(Type JoinType, string shortName, string joinWhere, JoinType type = Snet.DB.sugar.JoinType.Left)
			{
				Context.InitMappingInfo(JoinType);
				string dbTableName = Context.EntityMaintenance.GetEntityInfo(JoinType).DbTableName;
				QueryBuilder.JoinIndex = 1;
				QueryBuilder.JoinQueryInfos.Add(new JoinQueryInfo
				{
					JoinIndex = QueryBuilder.JoinIndex,
					TableName = dbTableName,
					ShortName = shortName,
					JoinType = type,
					JoinWhere = joinWhere,
					EntityType = JoinType
				});
				return this;
			}

