			public ISugarQueryable<T> TranLock(DbLockType? LockType = DbLockType.Wait)
			{
				if (!LockType.HasValue)
				{
					return this;
				}
				Check.ExceptionEasy(Context.Ado.Transaction == null, "need BeginTran", "需要事务才能使用TranLock");
				Check.ExceptionEasy(!QueryBuilder.IsSingle(), "TranLock, can only be used for single table query", "TranLock只能用在单表查询");
				if (Context.CurrentConnectionConfig.DbType == DbType.SqlServer)
				{
					if (LockType == DbLockType.Wait)
					{
						With("WITH(UpdLock,RowLock)");
					}
					else
					{
						With("WITH(UpdLock,RowLock,NoWait)");
					}
				}
				else
				{
					QueryBuilder.TranLock = ((LockType == DbLockType.Error) ? " for update nowait" : " for update");
				}
				return this;
			}

			public ISugarQueryable<T> WhereColumns(Dictionary<string, object> dictionary)
			{
				return WhereColumns(new List<Dictionary<string, object>> { dictionary });
			}

			public ISugarQueryable<T> WhereColumns(Dictionary<string, object> columns, bool ignoreDefaultValue)
			{
				if (!ignoreDefaultValue || columns == null)
				{
					return WhereColumns(columns);
				}
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				foreach (KeyValuePair<string, object> column in columns)
				{
					if (!UtilMethods.IsDefaultValue(column.Value))
					{
						dictionary.Add(column.Key, column.Value);
					}
				}
				return WhereColumns(dictionary);
			}

			public ISugarQueryable<T> WhereColumns(List<Dictionary<string, object>> list)
			{
				List<IConditionalModel> list2 = new List<IConditionalModel>();
				foreach (Dictionary<string, object> item in list)
				{
					int num = 0;
					List<KeyValuePair<WhereType, ConditionalModel>> list3 = new List<KeyValuePair<WhereType, ConditionalModel>>();
					foreach (string key in item.Keys)
					{
						string fieldValue = ((item[key] == null) ? "null" : item[key].ObjToString());
						string cSharpTypeName = ((item[key] == null) ? null : item[key].GetType().Name);
						if (item[key] is Enum)
						{
							SqlSugarProvider context = Context;
							if (context == null || context.CurrentConnectionConfig?.MoreSettings?.TableEnumIsString != true)
							{
								fieldValue = Convert.ToInt64(item[key]).ToString() ?? "";
								cSharpTypeName = "Int64";
							}
						}
						list3.Add(new KeyValuePair<WhereType, ConditionalModel>((num == 0) ? WhereType.Or : WhereType.And, new ConditionalModel
						{
							FieldName = key,
							ConditionalType = ConditionalType.Equal,
							FieldValue = fieldValue,
							CSharpTypeName = cSharpTypeName
						}));
						num++;
					}
					list2.Add(new ConditionalCollections
					{
						ConditionalList = list3
					});
				}
				return Where(list2);
			}

			/// <summary>
			///  if a property that is primary key is a condition
			/// </summary>
			/// <param name="whereClassTypes"></param>
			/// <returns></returns>
			public ISugarQueryable<T> _WhereClassByPrimaryKey(List<T> whereClassTypes)
			{
				if (whereClassTypes.HasValue())
				{
					List<EntityColumnInfo> list = Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => !it.IsIgnore && it.IsPrimarykey).ToList();
					Check.Exception(list == null || list.Count == 0, "{0} no primary key, Can not use WhereClassByPrimaryKey ", typeof(T).Name);
					Check.Exception(!QueryBuilder.IsSingle(), "No support join query");
					List<IConditionalModel> list2 = new List<IConditionalModel>();
					foreach (T whereClassType in whereClassTypes)
					{
						ConditionalCollections conditionalCollections = new ConditionalCollections();
						using (List<EntityColumnInfo>.Enumerator enumerator2 = list.GetEnumerator())
						{
							KeyValuePair<WhereType, ConditionalModel> item;
							for (; enumerator2.MoveNext(); conditionalCollections.ConditionalList.Add(item))
							{
								EntityColumnInfo current2 = enumerator2.Current;
								WhereType key = WhereType.And;
								object value = current2.PropertyInfo.GetValue(whereClassType, null);
								if (conditionalCollections.ConditionalList == null)
								{
									conditionalCollections.ConditionalList = new List<KeyValuePair<WhereType, ConditionalModel>>();
									if (!QueryBuilder.WhereInfos.IsNullOrEmpty() || !list2.IsNullOrEmpty())
									{
										key = WhereType.Or;
									}
								}
								item = new KeyValuePair<WhereType, ConditionalModel>(key, new ConditionalModel
								{
									ConditionalType = ConditionalType.Equal,
									FieldName = QueryBuilder.Builder.GetTranslationColumnName(current2.DbColumnName),
									FieldValue = value.ObjToStringNew(),
									CSharpTypeName = current2.UnderType.Name
								});
								if (value is Enum)
								{
									ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
									if (currentConnectionConfig == null || currentConnectionConfig.MoreSettings?.TableEnumIsString != true)
									{
										if (current2.SqlParameterDbType is Type type && type?.Name == "EnumToStringConvert")
										{
											item.Value.CSharpTypeName = "string";
											continue;
										}
										item.Value.FieldValue = Convert.ToInt64(value).ObjToString();
										item.Value.CSharpTypeName = "int";
										continue;
									}
								}
								if (value != null && current2.UnderType == UtilConstants.DateType)
								{
									item.Value.FieldValue = Convert.ToDateTime(value).ToString("yyyy-MM-dd HH:mm:ss.fff");
								}
							}
						}
						if (conditionalCollections.HasValue())
						{
							list2.Add(conditionalCollections);
						}
					}
					Where(list2, isWrap: true);
				}
				else
				{
					Where(" 1=2 ");
				}
				return this;
			}

			/// <summary>
			///  if a property that is whereColumns key is a condition
			/// </summary>
			/// <param name="whereClassTypes"></param>
			/// <returns></returns>
			public ISugarQueryable<T> _WhereClassByWhereColumns(List<T> whereClassTypes, string[] whereColumns)
			{
				if (whereClassTypes.HasValue())
				{
					List<EntityColumnInfo> list = Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => whereColumns.Any((string x) => x == it.PropertyName) || whereColumns.Any((string x) => x.EqualCase(it.DbColumnName))).ToList();
					Check.Exception(list == null || list.Count == 0, "{0} no primary key, Can not use whereColumns ", typeof(T).Name);
					Check.Exception(!QueryBuilder.IsSingle(), "No support join query");
					List<IConditionalModel> list2 = new List<IConditionalModel>();
					foreach (T whereClassType in whereClassTypes)
					{
						ConditionalCollections conditionalCollections = new ConditionalCollections();
						foreach (EntityColumnInfo item2 in list)
						{
							WhereType key = WhereType.And;
							object value = item2.PropertyInfo.GetValue(whereClassType, null);
							if (conditionalCollections.ConditionalList == null)
							{
								conditionalCollections.ConditionalList = new List<KeyValuePair<WhereType, ConditionalModel>>();
								if (!QueryBuilder.WhereInfos.IsNullOrEmpty() || !list2.IsNullOrEmpty())
								{
									key = WhereType.Or;
								}
							}
							ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
							bool flag = currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.DisableQueryWhereColumnRemoveTrim == true;
							KeyValuePair<WhereType, ConditionalModel> item = new KeyValuePair<WhereType, ConditionalModel>(key, new ConditionalModel
							{
								ConditionalType = ConditionalType.Equal,
								FieldName = QueryBuilder.Builder.GetTranslationColumnName(item2.DbColumnName),
								FieldValue = (flag ? value.ObjToStringNoTrim() : value.ObjToStringNew()),
								CSharpTypeName = item2.PropertyInfo.PropertyType.Name
							});
							if (value == null)
							{
								item.Value.FieldValue = null;
								item.Value.ConditionalType = ConditionalType.EqualNull;
							}
							if (value is Enum)
							{
								ConnectionConfig currentConnectionConfig2 = Context.CurrentConnectionConfig;
								if (currentConnectionConfig2 == null || currentConnectionConfig2.MoreSettings?.TableEnumIsString != true)
								{
									item.Value.FieldValue = Convert.ToInt64(value).ObjToString();
									item.Value.CSharpTypeName = "int";
								}
							}
							conditionalCollections.ConditionalList.Add(item);
						}
						if (conditionalCollections.HasValue())
						{
							list2.Add(conditionalCollections);
						}
					}
					Where(list2, isWrap: true);
				}
				else
				{
					Where(" 1=2 ");
				}
				return this;
			}

			/// <summary>
			///  if a property that is not empty is a condition
			/// </summary>
			/// <param name="whereClassTypes"></param>
			/// <returns></returns>
			public ISugarQueryable<T> WhereClass<ClassType>(List<ClassType> whereClassTypes, bool ignoreDefaultValue = false) where ClassType : class, new()
			{
				if (whereClassTypes.HasValue())
				{
					List<EntityColumnInfo> list = Context.EntityMaintenance.GetEntityInfo<ClassType>().Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
					List<IConditionalModel> list2 = new List<IConditionalModel>();
					foreach (ClassType whereClassType in whereClassTypes)
					{
						ConditionalCollections conditionalCollections = new ConditionalCollections();
						foreach (EntityColumnInfo item2 in list)
						{
							object value = item2.PropertyInfo.GetValue(whereClassType, null);
							WhereType key = WhereType.And;
							bool num = !ignoreDefaultValue && value != null;
							bool flag = ignoreDefaultValue && value != null && value.ObjToString() != UtilMethods.DefaultForType(item2.PropertyInfo.PropertyType).ObjToString();
							if (!(num | flag))
							{
								continue;
							}
							if (conditionalCollections.ConditionalList == null)
							{
								conditionalCollections.ConditionalList = new List<KeyValuePair<WhereType, ConditionalModel>>();
								if (!QueryBuilder.WhereInfos.IsNullOrEmpty() || !list2.IsNullOrEmpty())
								{
									key = WhereType.Or;
								}
							}
							KeyValuePair<WhereType, ConditionalModel> item = new KeyValuePair<WhereType, ConditionalModel>(key, new ConditionalModel
							{
								ConditionalType = ConditionalType.Equal,
								FieldName = item2.DbColumnName,
								FieldValue = value.ObjToString(),
								CSharpTypeName = item2.UnderType.Name
							});
							if (value != null && value.GetType().IsEnum())
							{
								ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
								if (currentConnectionConfig == null || currentConnectionConfig.MoreSettings?.TableEnumIsString != true)
								{
									item.Value.FieldValue = Convert.ToInt64(value).ObjToString();
								}
							}
							else if (value != null && item2.PropertyInfo.PropertyType == UtilConstants.DateType)
							{
								item.Value.FieldValue = value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.ffffff");
							}
							conditionalCollections.ConditionalList.Add(item);
						}
