			public virtual ISugarQueryable<T> In<TParamter>(params TParamter[] pkValues)
			{
				if (pkValues == null || pkValues.Length == 0)
				{
					Where(SqlBuilder.SqlFalse);
					return this;
				}
				if ((pkValues.Length == 1 && pkValues.First().GetType().FullName.IsCollectionsList()) || (pkValues.First() is IEnumerable && pkValues.First().GetType() != UtilConstants.StringType))
				{
					List<object> list = new List<object>();
					foreach (object item in pkValues.First() as IEnumerable)
					{
						list.Add(item);
					}
					return In(list);
				}
				List<string> list2 = (from it in GetPrimaryKeys()
					select SqlBuilder.GetTranslationTableName(it)).ToList();
				Check.Exception(list2 == null || list2.Count != 1, "Queryable.In(params object[] pkValues): Only one primary key");
				string text = list2.FirstOrDefault();
				text = ((QueryBuilder.TableShortName == null) ? null : (QueryBuilder.TableShortName + ".")) + text;
				return In(text, pkValues);
			}

			public virtual ISugarQueryable<T> In<FieldType>(string filed, params FieldType[] inValues)
			{
				if (inValues.Length == 1)
				{
					if (inValues.GetType().IsArray)
					{
						int whereIndex = QueryBuilder.WhereIndex;
						string text = SqlBuilder.SqlParameterKeyWord + "InPara" + whereIndex;
						AddParameters(new SugarParameter(text, inValues[0]));
						Where(string.Format(QueryBuilder.EqualTemplate, SqlBuilder.GetTranslationColumnName(filed), text));
						QueryBuilder.WhereIndex++;
					}
					else
					{
						List<object> list = new List<object>();
						foreach (object item in (IEnumerable)(object)inValues[0])
						{
							if (item != null)
							{
								list.Add(item.ToString().ToSqlValue());
							}
						}
						Where(string.Format(QueryBuilder.InTemplate, SqlBuilder.GetTranslationColumnName(filed), string.Join(",", list)));
					}
				}
				else
				{
					List<object> list2 = new List<object>();
					for (int i = 0; i < inValues.Length; i++)
					{
						FieldType val = inValues[i];
						if (val != null)
						{
							if (UtilMethods.IsNumber(val.GetType().Name))
							{
								list2.Add(val.ToString());
							}
							else
							{
								list2.Add(val.ToString().ToSqlValue());
							}
						}
					}
					Where(string.Format(QueryBuilder.InTemplate, SqlBuilder.GetTranslationColumnName(filed), string.Join(",", list2)));
				}
				return this;
			}

