					{
						return In(resultString, UtilMethods.ConvertToListOfObjects(inValues[0]));
					}
				}
				goto IL_014e;
				IL_014e:
				if (inValues != null && inValues.Length == 1)
				{
					ref readonly FieldType reference2 = ref inValues[0];
					val = default(FieldType);
					if (val == null)
					{
