					if (reference2.GetType()?.IsArray == true && entityColumnInfo != null && (entityColumnInfo == null || entityColumnInfo.UnderType?.IsArray != true))
					{
						return In(resultString, UtilMethods.ConvertToListOfObjects(inValues[0]));
					}
				}
				goto IL_020d;
				IL_020d:
