			public ISugarQueryable<T> SampleBy(int timeNumber, SampleByUnit timeType)
			{
				SampleByUnit sampleByUnit = timeType;
				switch (timeType)
				{
				case SampleByUnit.Month:
				{
					string sampleBy4 = "SAMPLE BY " + timeNumber + sampleByUnit.ToString().Substring(0, 1);
					QueryBuilder.SampleBy = sampleBy4;
					break;
				}
				case SampleByUnit.Millisecond:
				{
					string sampleBy3 = "SAMPLE BY " + timeNumber + " T ";
					QueryBuilder.SampleBy = sampleBy3;
					break;
				}
				case SampleByUnit.Microsecond:
				{
					string sampleBy2 = "SAMPLE BY " + timeNumber + " U ";
					QueryBuilder.SampleBy = sampleBy2;
					break;
				}
				default:
				{
					string sampleBy = "SAMPLE BY " + timeNumber + sampleByUnit.ToString().Substring(0, 1).ToLower();
					QueryBuilder.SampleBy = sampleBy;
					break;
				}
				}
				return this;
			}

