			public ISugarQueryable<T> OrderByPropertyName(string orderPropertyName, OrderByType? orderByType = null)
			{
				if (orderPropertyName.HasValue())
				{
					if (orderPropertyName.Contains(","))
					{
						string[] array = orderPropertyName.Split(',');
						foreach (string orderPropertyName2 in array)
						{
							OrderByPropertyName(orderPropertyName2, orderByType);
						}
						return this;
					}
					if (!QueryBuilder.IsSingle() && orderPropertyName.Contains("."))
					{
						orderPropertyNameByJoin(orderPropertyName, orderByType);
						return this;
					}
					if (Context.EntityMaintenance.GetEntityInfoWithAttr(typeof(T)).Columns.Any(delegate(EntityColumnInfo it)
					{
						string dbColumnName = it.DbColumnName;
						return (dbColumnName != null && dbColumnName.EqualCase(orderPropertyName)) || (it.PropertyName?.EqualCase(orderPropertyName) ?? false);
					}))
					{
						string propertyName = Context.EntityMaintenance.GetEntityInfoWithAttr(typeof(T)).Columns.FirstOrDefault(delegate(EntityColumnInfo it)
						{
							string dbColumnName = it.DbColumnName;
							return (dbColumnName != null && dbColumnName.EqualCase(orderPropertyName)) || (it.PropertyName?.EqualCase(orderPropertyName) ?? false);
						})?.DbColumnName;
						string translationColumnName = SqlBuilder.GetTranslationColumnName(propertyName);
						OrderByType? orderByType2 = orderByType;
						return OrderBy(translationColumnName + " " + orderByType2.ToString());
					}
					Check.ExceptionEasy("OrderByPropertyName error." + orderPropertyName + " does not exist in the entity class", "OrderByPropertyName出错实体类中不存在" + orderPropertyName);
				}
				return this;
			}

