			public DynamicCoreSelectModel Select(string expShortName, List<string> columns, params object[] args)
			{
				DynamicCoreSelectModel dynamicCoreSelectModel = new DynamicCoreSelectModel();
				if (!string.IsNullOrEmpty(QueryBuilder.TableShortName) && expShortName != QueryBuilder.TableShortName)
				{
					if (columns.Any((string it) => it.Contains(expShortName + " ")))
					{
						string pattern = "\\b" + Regex.Escape(expShortName) + "\\s*\\.";
						string replacement = QueryBuilder.TableShortName + ".";
						columns = columns.Select((string it) => Regex.Replace(it, pattern, replacement)).ToList();
						expShortName = QueryBuilder.TableShortName;
					}
					else
					{
						columns = columns.Select((string it) => it.Replace(expShortName + ".", QueryBuilder.TableShortName + ".")).ToList();
						expShortName = QueryBuilder.TableShortName;
					}
				}
				DynamicCoreHelper.BuildPropertySelectorResult buildPropertySelectorResult = DynamicCoreHelper.BuildPropertySelector(expShortName, typeof(T), columns, args);
				if (IsAppendNavColumns())
				{
					SetAppendNavColumns(buildPropertySelectorResult.Exp);
				}
				LambdaExpression exp = buildPropertySelectorResult.Exp;
				MethodInfo methodInfo = GetType().GetMethod("_Select", BindingFlags.Instance | BindingFlags.NonPublic).MakeGenericMethod(buildPropertySelectorResult.ResultNewType);
				dynamicCoreSelectModel.Value = methodInfo.Invoke(this, new object[1] { exp });
				return dynamicCoreSelectModel;
			}

