			public ISugarQueryable<TResult> Select<TResult>(Expression<Func<T, TResult>> expression, bool isAutoFill)
			{
				if (typeof(TResult).IsAnonymousType())
				{
					return Select(expression);
				}
				ISugarQueryable<TResult> sugarQueryable = Select(expression).Clone();
				sugarQueryable.QueryBuilder.IsDistinct = false;
				QueryBuilder queryBuilder = sugarQueryable.QueryBuilder;
				string text = queryBuilder.GetSelectValue;
				if (string.IsNullOrEmpty(text) || text.Trim() == "*")
				{
					QueryBuilder.SelectValue = null;
					return Select<TResult>();
				}
				if (text.StartsWith("*,"))
				{
					List<EntityColumnInfo> source = (from it in Context.EntityMaintenance.GetEntityInfo<T>().Columns
						where typeof(TResult).GetProperties().Any((PropertyInfo s) => s.Name.EqualCase(it.PropertyName))
						where !it.IsIgnore
						select it).ToList();
					if (source.Any())
					{
						text = string.Join(",", source.Select((EntityColumnInfo it) => SqlBuilder.GetTranslationColumnName(it.DbColumnName) + " AS  " + SqlBuilder.GetTranslationColumnName(it.PropertyName) + " ")) + "," + text.TrimStart('*').TrimStart(',');
					}
				}
				if (QueryBuilder.TableShortName.IsNullOrEmpty())
				{
					QueryBuilder.TableShortName = sugarQueryable.QueryBuilder.TableShortName;
				}
				QueryBuilder.Parameters = queryBuilder.Parameters;
				QueryBuilder.SubToListParameters = sugarQueryable.QueryBuilder.SubToListParameters;
				QueryBuilder.LambdaExpressions.ParameterIndex = sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex;
				ReadOnlyCollection<ParameterExpression> parameters = expression.Parameters;
				List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfo<TResult>().Columns;
				text = AppendSelect(EntityInfo.Columns, text, parameters, columns, 0);
				return Select<TResult>(text);
			}

			public virtual ISugarQueryable<TResult> Select<TResult>()
			{
				if (QueryBuilder.JoinExpression != null)
				{
					string selectValue = new SugarMapper(Context).GetSelectValue<TResult>(QueryBuilder);
					return Select<TResult>(selectValue);
				}
				if (QueryBuilder.EntityType == UtilConstants.ObjType || (QueryBuilder.AsTables != null && QueryBuilder.AsTables.Count == 1) || QueryBuilder.EntityName != QueryBuilder.EntityType.Name)
				{
					if (typeof(TResult).IsInterface && QueryBuilder.AsType == null)
					{
						Check.ExceptionEasy("Select< interface > requires a full example of AsType(type) db.Queryable<object>().AsType(type).Select<Interface>().ToList()", "Select<接口>需要AsType(type)完整示例db.Queryable<object>().AsType(type).Select<Interface>().ToList()");
					}
					if (QueryBuilder.SelectValue.HasValue() && QueryBuilder.SelectValue.ObjToString().Contains("AS"))
					{
						return Select<TResult>(QueryBuilder.SelectValue?.ToString() ?? "");
					}
					if (QueryBuilder.IsSingle() && EntityInfo?.Type?.GetCustomAttribute<SplitTableAttribute>() != null && QueryBuilder?.SelectValue?.ToString() == "*")
					{
						List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfo<T>().Columns;
						string selectValue2 = string.Empty;
						List<EntityColumnInfo> source = (from it in columns
							where typeof(TResult).GetProperties().Any((PropertyInfo s) => s.Name.EqualCase(it.PropertyName))
							where !it.IsIgnore
							select it).ToList();
						if (source.Any())
						{
							selectValue2 = string.Join(",", source.Select((EntityColumnInfo it) => SqlBuilder.GetTranslationColumnName(it.DbColumnName) + " AS  " + SqlBuilder.GetTranslationColumnName(it.PropertyName) + " "));
						}
						return Select<TResult>(selectValue2);
					}
					return Select<TResult>(SqlBuilder.SqlSelectAll);
				}
				if (typeof(TResult).IsInterface && typeof(TResult).IsAssignableFrom(EntityInfo.Type) && !QueryBuilder.AsTables.Any())
				{
					AsType(EntityInfo.Type);
				}
				string selectValueByString = QueryBuilder.GetSelectValueByString();
				if (selectValueByString.ObjToString().ToLower().IsContainsIn(".", "(", " as "))
				{
					return Select<TResult>(selectValueByString);
				}
				List<EntityColumnInfo> columns2 = Context.EntityMaintenance.GetEntityInfo<TResult>().Columns;
				IEnumerable<EntityColumnInfo> source2 = EntityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore);
				StringBuilder stringBuilder = new StringBuilder();
				foreach (EntityColumnInfo item in columns2)
				{
					EntityColumnInfo entityColumnInfo = source2.FirstOrDefault((EntityColumnInfo z) => z.PropertyName.EqualCase(item.PropertyName) || z.DbColumnName.EqualCase(item.PropertyName));
					if (entityColumnInfo != null)
					{
						string dbColumnName = entityColumnInfo.DbColumnName;
						string propertyName = item.PropertyName;
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 2, stringBuilder2);
						handler.AppendFormatted(SqlBuilder.GetTranslationColumnName(dbColumnName));
						handler.AppendLiteral(" AS ");
						handler.AppendFormatted(SqlBuilder.GetTranslationColumnName(propertyName));
						handler.AppendLiteral(" ,");
						stringBuilder2.Append(ref handler);
					}
				}
				selectValueByString = stringBuilder.ToString().TrimEnd(',');
				if (selectValueByString == "")
				{
					selectValueByString = "*";
				}
				return Select<TResult>(selectValueByString);
			}

			public virtual ISugarQueryable<TResult> Select<TResult>(string selectValue)
			{
				ISugarQueryable<TResult> queryable = InstanceFactory.GetQueryable<TResult>(Context.CurrentConnectionConfig);
				queryable.Context = Context;
				queryable.SqlBuilder = SqlBuilder;
				queryable.QueryBuilder.ResultType = QueryBuilder.ResultType;
				queryable.IsCache = IsCache;
				queryable.CacheTime = CacheTime;
				QueryBuilder.SelectValue = selectValue;
				if (IsAs)
				{
					((QueryableProvider<TResult>)queryable).IsAs = true;
				}
				return queryable;
			}

