			public virtual ISugarQueryable<T> MergeTable()
			{
				if (IsSubToList())
				{
					return MergeTableWithSubToList();
				}
				Check.Exception(MapperAction != null || MapperActionWithCache != null, ErrorMessage.GetThrowMessage("'Mapper’ needs to be written after ‘MergeTable’ ", "Mapper 只能在 MergeTable 之后使用"));
				KeyValuePair<string, List<SugarParameter>> keyValuePair = _ToSql();
				if (IsSubToList())
				{
					return MergeTableWithSubToListJoin();
				}
				int whereIndex = QueryBuilder.WhereIndex + 1;
				ISugarQueryable<T> sugarQueryable = (EntityInfo.Discrimator.HasValue() ? Context.Queryable<object>().AS(SqlBuilder.GetPackTable(keyValuePair.Key, "MergeTable")).AddParameters(keyValuePair.Value)
					.Select<T>("*")
					.With("Non") : Context.Queryable<T>().AS(SqlBuilder.GetPackTable(keyValuePair.Key, "MergeTable")).AddParameters(keyValuePair.Value)
					.Select("*")
					.With("Non"));
				sugarQueryable.QueryBuilder.WhereIndex = whereIndex;
				sugarQueryable.QueryBuilder.NoCheckInclude = true;
				sugarQueryable.QueryBuilder.Includes = QueryBuilder.Includes;
				sugarQueryable.QueryBuilder.AppendNavInfo = QueryBuilder.AppendNavInfo;
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = QueryBuilder.LambdaExpressions.ParameterIndex++;
				sugarQueryable.QueryBuilder.LambdaExpressions.Index = QueryBuilder.LambdaExpressions.Index++;
				sugarQueryable.QueryBuilder.IsCrossQueryWithAttr = QueryBuilder.IsCrossQueryWithAttr;
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					sugarQueryable.Select("MergeTable.*");
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T> SplitTable()
			{
				UtilMethods.StartCustomSplitTable(Context, typeof(T));
				return SplitTable((List<SplitTableInfo> tag) => tag);
			}

			public ISugarQueryable<T> SplitTable(DateTime beginTime, DateTime endTime)
			{
				UtilMethods.StartCustomSplitTable(Context, typeof(T));
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyInfo.GetCustomAttribute<SplitFieldAttribute>() != null);
				Check.ExceptionEasy(entityColumnInfo == null, "[SplitFieldAttribute] need to be added to the table field", "需要在分表字段加上属性[SplitFieldAttribute]");
				string translationColumnName = SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName);
				string sqlParameterKeyWord = SqlBuilder.SqlParameterKeyWord;
				ISugarQueryable<T> sugarQueryable = Where($" {translationColumnName}>={sqlParameterKeyWord}spBeginTime AND {translationColumnName}<= {sqlParameterKeyWord}spEndTime", new
				{
					spBeginTime = beginTime,
					spEndTime = endTime
				}).SplitTable(delegate(List<SplitTableInfo> tas)
				{
					List<SplitTableInfo> source = tas;
					SplitTableAttribute customAttribute = EntityInfo.Type.GetCustomAttribute<SplitTableAttribute>();
					Check.ExceptionEasy(customAttribute == null, EntityInfo.EntityName + "need SplitTableAttribute", EntityInfo.EntityName + "需要特性 SplitTableAttribute");
					if (SplitType.Month == customAttribute.SplitType)
					{
						return source.Where((SplitTableInfo y) => y.Date >= beginTime.ToString("yyyy-MM").ObjToDate() && y.Date <= endTime.Date.ToString("yyyy-MM").ObjToDate().AddMonths(1)
							.AddDays(-1.0)).ToList();
					}
					if (SplitType.Year == customAttribute.SplitType)
					{
						return source.Where((SplitTableInfo y) => y.Date.Year >= beginTime.Year && y.Date.Year <= endTime.Year).ToList();
					}
					if (SplitType.Week == customAttribute.SplitType)
					{
						DateTime begtinWeek = UtilMethods.GetWeekFirstDayMon(beginTime).Date;
						DateTime endWeek = UtilMethods.GetWeekLastDaySun(endTime).Date;
						return source.Where((SplitTableInfo y) => y.Date >= begtinWeek && y.Date <= endWeek).ToList();
					}
					if (SplitType.Month_6 == customAttribute.SplitType)
					{
						string begtinWeek2 = ((beginTime.Month <= 6) ? beginTime.ToString("yyyy-01-01") : beginTime.ToString("yyyy-06-01"));
						string endWeek2 = ((endTime.Month <= 6) ? endTime.ToString("yyyy-07-01") : endTime.ToString("yyyy-12-01"));
						return source.Where((SplitTableInfo y) => y.Date >= begtinWeek2.ObjToDate() && y.Date <= endWeek2.ObjToDate().AddMonths(1).AddDays(-1.0)).ToList();
					}
					if (SplitType.Season == customAttribute.SplitType)
					{
						DateTime beginSeason = Convert.ToDateTime(beginTime.AddMonths(-((beginTime.Month - 1) % 3)).ToString("yyyy-MM-01")).Date;
						DateTime endSeason = DateTime.Parse(endTime.AddMonths(3 - (endTime.Month - 1) % 3).ToString("yyyy-MM-01")).AddDays(-1.0).Date;
						return source.Where((SplitTableInfo y) => y.Date >= beginSeason && y.Date <= endSeason).ToList();
					}
					return source.Where((SplitTableInfo y) => y.Date >= beginTime.Date && y.Date <= endTime.Date).ToList();
				});
				if (entityColumnInfo.SqlParameterDbType is System.Data.DbType)
				{
					foreach (SugarParameter parameter in sugarQueryable.QueryBuilder.Parameters)
					{
						if (parameter.ParameterName.IsContainsIn("spBeginTime", "spEndTime"))
						{
							parameter.DbType = (System.Data.DbType)entityColumnInfo.SqlParameterDbType;
						}
					}
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T> SplitTable(Func<List<SplitTableInfo>, IEnumerable<SplitTableInfo>> getTableNamesFunc)
			{
				UtilMethods.StartCustomSplitTable(Context, typeof(T));
				SplitTableContext splitTableContext = new SplitTableContext(Context)
				{
					EntityInfo = EntityInfo
				};
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
				IEnumerable<SplitTableInfo> enumerable = getTableNamesFunc(splitTableContext.GetTables());
				List<ISugarQueryable<T>> list = new List<ISugarQueryable<T>>();
				foreach (SplitTableInfo item in enumerable)
				{
					list.Add(Clone().AS(item.TableName));
				}
				if (list.Count == 0)
				{
					ISugarQueryable<T> sugarQueryable = Context.SqlQueryable<object>("-- No table ").Select<T>();
					sugarQueryable.QueryBuilder.SelectValue = null;
					return sugarQueryable;
				}
				ISugarQueryable<T> sugarQueryable2 = Context._UnionAll(list.ToArray());
				sugarQueryable2.QueryBuilder.Includes = QueryBuilder.Includes;
				sugarQueryable2.QueryBuilder.EntityType = typeof(T);
				sugarQueryable2.QueryBuilder.IsDisableMasterSlaveSeparation = QueryBuilder.IsDisableMasterSlaveSeparation;
				sugarQueryable2.QueryBuilder.IsDisabledGobalFilter = QueryBuilder.IsDisabledGobalFilter;
				List<object> includes = sugarQueryable2.QueryBuilder.Includes;
				if (includes != null && includes.Any())
				{
					sugarQueryable2.QueryBuilder.NoCheckInclude = true;
				}
				return sugarQueryable2;
			}

