				{
					ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.DbType == DbType.SqlServer)
					{
						string sqlString = UtilMethods.GetSqlString(DbType.SqlServer, keyValuePair.Key, keyValuePair.Value);
						QueryBuilder.GroupBySql = sqlString;
						QueryBuilder.GroupBySqlOld = keyValuePair.Key;
						QueryBuilder.GroupParameters = keyValuePair.Value.ToList();
						GroupBy(keyValuePair.Key);
						goto IL_00ca;
					}
				}
				GroupBy(keyValuePair.Key);
				QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				goto IL_00ca;
				IL_00ca:
				return this;
			}

			public ISugarQueryable<T> Select(List<SelectModel> models)
			{
				KeyValuePair<string, SugarParameter[]> keyValuePair = SqlBuilder.SelectModelToSql(models);
				List<SugarParameter> groupParameters = QueryBuilder.GroupParameters;
				if (groupParameters != null && groupParameters.Any() && QueryBuilder.GroupBySql.HasValue())
				{
					string sqlString = UtilMethods.GetSqlString(DbType.SqlServer, keyValuePair.Key, UtilMethods.CopySugarParameters(keyValuePair.Value.ToList()).ToArray());
					if (sqlString.Contains(QueryBuilder.GroupBySql))
					{
						Select("{GroupReplaceKey_l33asdysaas1231s}" + sqlString);
						return this;
					}
				}
				Select(keyValuePair.Key);
				QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				return this;
			}

			public ISugarQueryable<TResult> Select<TResult>(List<SelectModel> models)
			{
				KeyValuePair<string, SugarParameter[]> keyValuePair = SqlBuilder.SelectModelToSql(models);
				ISugarQueryable<TResult> sugarQueryable = Select<TResult>(keyValuePair.Key);
				sugarQueryable.QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				return sugarQueryable;
			}

			public ISugarQueryable<T> Select(List<SelectModel> models, AsNameFormatType type)
			{
				if (type == AsNameFormatType.NoConvert)
				{
					foreach (SelectModel model in models)
					{
						if (!string.IsNullOrEmpty(model.AsName))
						{
							model.AsName = UtilConstants.ReplaceKey + SqlBuilder.SqlTranslationLeft + model.AsName + SqlBuilder.SqlTranslationRight;
							model.AsName.ToCheckField();
						}
					}
				}
				return Select(models);
			}

			public ISugarQueryable<T> Having(IFuncModel model)
			{
				QueryBuilder.WhereIndex++;
				KeyValuePair<string, SugarParameter[]> keyValuePair = SqlBuilder.FuncModelToSql(model);
				Having(keyValuePair.Key);
				QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				return this;
			}
