		internal class MappingFieldsHelper<T>
		{
			public SqlSugarProvider Context { get; set; }

			public EntityInfo NavEntity { get; set; }

			public EntityInfo RootEntity { get; set; }

			public MappingFieldsInfo GetMappings(Expression thisFiled, Expression mappingFiled)
			{
				MappingFieldsInfo result = new MappingFieldsInfo();
				if ((mappingFiled as LambdaExpression).Body is UnaryExpression)
				{
					_ = (((mappingFiled as LambdaExpression).Body as UnaryExpression).Operand as MemberExpression).Member.Name;
					return result;
				}
				_ = ((mappingFiled as LambdaExpression).Body as MemberExpression).Member.Name;
				return result;
			}

			public List<IConditionalModel> GetMppingSql(List<object> list, List<MappingFieldsExpression> mappingFieldsExpressions)
			{
				List<IConditionalModel> list2 = new List<IConditionalModel>();
				foreach (object item in list)
				{
					List<KeyValuePair<WhereType, ConditionalModel>> list3 = new List<KeyValuePair<WhereType, ConditionalModel>>();
					int num = 0;
					foreach (MappingFieldsExpression mappingFieldsExpression in mappingFieldsExpressions)
					{
						InitMappingFieldsExpression(mappingFieldsExpression);
						string text = UtilMethods.GetUnderType(mappingFieldsExpression.RightEntityColumn.PropertyInfo.PropertyType).Name;
						if (text.EqualCase("String"))
						{
							object sqlParameterDbType = mappingFieldsExpression.RightEntityColumn.SqlParameterDbType;
							if (sqlParameterDbType is System.Data.DbType)
							{
								_ = (System.Data.DbType)sqlParameterDbType;
								text = "AnsiString";
							}
						}
						list3.Add(new KeyValuePair<WhereType, ConditionalModel>((num == 0) ? WhereType.Or : WhereType.And, new ConditionalModel
						{
							FieldName = mappingFieldsExpression.LeftEntityColumn.DbColumnName,
							ConditionalType = ConditionalType.Equal,
							FieldValue = mappingFieldsExpression.RightEntityColumn.PropertyInfo.GetValue(item).ObjToString(),
							CSharpTypeName = text
						}));
						num++;
					}
					list2.Add(new ConditionalCollections
					{
						ConditionalList = list3
					});
				}
				return list2;
			}

			public void SetChildList(EntityColumnInfo navColumnInfo, object item, List<object> list, List<MappingFieldsExpression> mappingFieldsExpressions)
			{
				if (item == null)
				{
					return;
				}
				List<object> setList = GetSetList(item, list, mappingFieldsExpressions);
				IList list2 = Activator.CreateInstance(navColumnInfo.PropertyInfo.PropertyType, nonPublic: true) as IList;
				foreach (object item2 in setList)
				{
					list2.Add(item2);
				}
				navColumnInfo.PropertyInfo.SetValue(item, list2);
			}

			public void SetChildItem(EntityColumnInfo navColumnInfo, object item, List<object> list, List<MappingFieldsExpression> mappingFieldsExpressions)
			{
				if (item == null)
				{
					return;
				}
				List<object> setList = GetSetList(item, list, mappingFieldsExpressions);
				Activator.CreateInstance(navColumnInfo.PropertyInfo.PropertyType, nonPublic: true);
				foreach (object item2 in setList)
				{
					navColumnInfo.PropertyInfo.SetValue(item, item2);
				}
			}

			public List<object> GetSetList(object item, List<object> list, List<MappingFieldsExpression> mappingFieldsExpressions)
			{
				foreach (MappingFieldsExpression mappingFieldsExpression in mappingFieldsExpressions)
				{
					InitMappingFieldsExpression(mappingFieldsExpression);
				}
				List<object> result = new List<object>();
				switch (mappingFieldsExpressions.Count)
				{
				case 1:
					result = list.Where((object it) => GetWhereByIndex(item, mappingFieldsExpressions, it, 0)).ToList();
					break;
				case 2:
					result = list.Where((object it) => GetWhereByIndex(item, mappingFieldsExpressions, it, 0) && GetWhereByIndex(item, mappingFieldsExpressions, it, 1)).ToList();
					break;
				case 3:
					result = list.Where((object it) => GetWhereByIndex(item, mappingFieldsExpressions, it, 0) && GetWhereByIndex(item, mappingFieldsExpressions, it, 1) && GetWhereByIndex(item, mappingFieldsExpressions, it, 2)).ToList();
					break;
				case 4:
					result = list.Where((object it) => GetWhereByIndex(item, mappingFieldsExpressions, it, 0) && GetWhereByIndex(item, mappingFieldsExpressions, it, 1) && GetWhereByIndex(item, mappingFieldsExpressions, it, 2) && GetWhereByIndex(item, mappingFieldsExpressions, it, 3)).ToList();
					break;
				case 5:
					result = list.Where((object it) => GetWhereByIndex(item, mappingFieldsExpressions, it, 0) && GetWhereByIndex(item, mappingFieldsExpressions, it, 1) && GetWhereByIndex(item, mappingFieldsExpressions, it, 2) && GetWhereByIndex(item, mappingFieldsExpressions, it, 3) && GetWhereByIndex(item, mappingFieldsExpressions, it, 4)).ToList();
					break;
				default:
					Check.ExceptionEasy("MappingField max value  is  5", "MappingField最大数量不能超过5");
					break;
				}
				return result;
			}

			private static bool GetWhereByIndex(object item, List<MappingFieldsExpression> mappingFieldsExpressions, object it, int index)
			{
				string text = mappingFieldsExpressions[index].LeftEntityColumn.PropertyInfo.GetValue(it).ObjToString();
				string text2 = mappingFieldsExpressions[index].RightEntityColumn.PropertyInfo.GetValue(item).ObjToString();
				return text == text2;
			}

			private void InitMappingFieldsExpression(MappingFieldsExpression item)
			{
				string leftName = item.LeftName;
				string rightName = item.RightName;
				if (item.LeftEntityColumn == null)
				{
					item.LeftEntityColumn = NavEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == leftName);
				}
				if (item.RightEntityColumn != null || Context == null)
				{
					return;
				}
				if (item.RightColumnExpression is LambdaExpression)
				{
					Expression expression = (item.RightColumnExpression as LambdaExpression).Body;
					if (expression is UnaryExpression)
					{
						expression = ((UnaryExpression)expression).Operand;
					}
					if (expression is MemberExpression)
					{
						Expression expression2 = (expression as MemberExpression).Expression;
						if (expression2.NodeType == ExpressionType.Parameter)
						{
							item.RightEntityColumn = Context.EntityMaintenance.GetEntityInfo(expression2.Type).Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == rightName);
						}
					}
				}
				if (item.RightEntityColumn == null)
				{
					item.RightEntityColumn = RootEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == rightName);
				}
			}
		}
		public class MappingFieldsInfo
		{
			public DbColumnInfo LeftColumn { get; set; }

			public DbColumnInfo RightColumn { get; set; }
		}
		public class MappingFieldsExpression
		{
			private string _LeftName;

			private string _RightName;

			public Expression LeftColumnExpression { get; set; }

			public Expression RightColumnExpression { get; set; }

			public EntityColumnInfo LeftEntityColumn { get; set; }

			public EntityColumnInfo RightEntityColumn { get; set; }

			public string LeftName
			{
				get
				{
					if (_LeftName == null)
					{
						_LeftName = ExpressionTool.GetMemberName(LeftColumnExpression);
					}
					return _LeftName;
				}
			}

			public string RightName
			{
				get
				{
					if (_RightName == null)
					{
						_RightName = ExpressionTool.GetMemberName(RightColumnExpression);
					}
					return _RightName;
				}
			}
		}
		public class NavigatManager<T>
		{
			private List<Expression> _preExpressionList = new List<Expression>();

			private List<object> _preList = new List<object>();

			private List<Expression> _ListCallFunc;

			public SqlSugarProvider Context { get; set; }

			public bool IsCrossQueryWithAttr { get; set; }

			public Dictionary<string, string> CrossQueryItems { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR1 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR2 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR3 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR4 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR5 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR6 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR7 { get; set; }

			public Func<ISugarQueryable<object>, List<object>> SelectR8 { get; set; }

			public Expression[] Expressions { get; set; }

			public List<T> RootList { get; set; }

			public QueryBuilder QueryBuilder { get; set; }

			public void Execute()
			{
				int num = 1;
				Expression[] expressions = Expressions;
				foreach (Expression item in expressions)
				{
					ExecuteByLay(num, item);
					num++;
				}
			}

			private void ExecuteByLay(int i, Expression item)
			{
				_ListCallFunc = GetWhereExpression(ref item);
				switch (i)
				{
				case 1:
					ExecuteByLay(item, ((IEnumerable<T>)RootList).Select((Func<T, object>)((T it) => it)).ToList(), SelectR1);
					break;
				case 2:
				{
					List<T> rootList = RootList;
					if (RootList == null || rootList.Count == 0)
					{
						return;
					}
					MemberExpression memberExpression = (_preExpressionList.Last() as LambdaExpression).Body as MemberExpression;
					string navObjectName = memberExpression.Member.Name;
					bool num = rootList[0].GetType().GetProperty(navObjectName).PropertyType.Name.StartsWith("List`");
					List<object> list3 = new List<object>();
					list3 = ((!num) ? rootList.Select((T it) => it.GetType().GetProperty(navObjectName).GetValue(it)).ToList() : rootList.SelectMany((T it) => (it.GetType().GetProperty(navObjectName).GetValue(it) as IList)?.Cast<object>() ?? new List<object>()).ToList());
					ExecuteByLay(item, list3, SelectR2);
					_preList = list3;
					break;
				}
				case 3:
				{
					List<object> list4 = _preList.Where((object it) => it != null).ToList();
					if (RootList == null || list4.Count == 0)
					{
						return;
					}
					List<object> list5 = ExecuteByLay(list4);
					ExecuteByLay(item, list5, SelectR3);
					_preList = list5.ToList();
					break;
				}
				case 4:
				{
					List<object> list10 = _preList.Where((object it) => it != null).ToList();
					if (RootList == null || list10.Count == 0)
					{
						return;
					}
					List<object> list11 = ExecuteByLay(list10);
					ExecuteByLay(item, list11, SelectR4);
					_preList = list11.ToList();
					break;
				}
				case 5:
				{
					List<object> list6 = _preList.Where((object it) => it != null).ToList();
					if (RootList == null || list6.Count == 0)
					{
						return;
					}
					List<object> list7 = ExecuteByLay(list6);
					ExecuteByLay(item, list7, SelectR5);
					_preList = list7.ToList();
					break;
				}
				case 6:
				{
					List<object> list8 = _preList.Where((object it) => it != null).ToList();
					if (RootList == null || list8.Count == 0)
					{
						return;
					}
					List<object> list9 = ExecuteByLay(list8);
					ExecuteByLay(item, list9, SelectR6);
					_preList = list9.ToList();
					break;
				}
				case 7:
				{
					List<object> list = _preList.Where((object it) => it != null).ToList();
					if (RootList == null || list.Count == 0)
					{
						return;
					}
					List<object> list2 = ExecuteByLay(list);
					ExecuteByLay(item, list2, SelectR7);
					_preList = list2.ToList();
					break;
				}
				}
				_preExpressionList.Add(item);
				_ListCallFunc = new List<Expression>();
			}

			private List<object> ExecuteByLay(List<object> currentList)
			{
				MemberExpression memberExpression = (_preExpressionList.Last() as LambdaExpression).Body as MemberExpression;
				string navObjectName = memberExpression.Member.Name;
				bool num = currentList[0].GetType().GetProperty(navObjectName).PropertyType.Name.StartsWith("List`");
				List<object> list = new List<object>();
				if (num)
				{
					return currentList.Where((object it) => it.GetType().GetProperty(navObjectName).GetValue(it) != null).SelectMany((object it) => (it.GetType().GetProperty(navObjectName).GetValue(it) as IList).Cast<object>()).ToList();
				}
				return (from it in currentList
					where it.GetType().GetProperty(navObjectName).GetValue(it) != null
					select it.GetType().GetProperty(navObjectName).GetValue(it)).ToList();
			}

			private void ExecuteByLay(Expression expression, List<object> list, Func<ISugarQueryable<object>, List<object>> selector)
			{
				if (list == null || list.Count == 0)
				{
					return;
				}
				list = list.Where((object it) => it != null).ToList();
				MemberExpression memberExpression = (expression as LambdaExpression).Body as MemberExpression;
				Type type = list.Where((object it) => it != null).FirstOrDefault()?.GetType();
				if (type == null)
				{
					return;
				}
				if (type.Name.StartsWith("List`"))
				{
					type = type.GetGenericArguments()[0];
				}
				EntityInfo listItemEntity = Context.EntityMaintenance.GetEntityInfo(type);
				listItemEntity.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				string navObjectName = memberExpression.Member.Name;
				PropertyInfo navObjectNamePropety = type.GetProperty(navObjectName);
				EntityColumnInfo navObjectNameColumnInfo = listItemEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == navObjectName);
				Check.ExceptionEasy(navObjectNameColumnInfo.Navigat == null, navObjectName + " not [Navigat(..)] ", navObjectName + " 没有导航特性 [Navigat(..)] ");
				if (navObjectNameColumnInfo.Navigat.NavigatType == NavigateType.OneToOne)
				{
					Context.Utilities.PageEach(list, 5000, delegate(List<object> pageList)
					{
						OneToOne(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo);
					});
				}
				else if (navObjectNameColumnInfo.Navigat.NavigatType == NavigateType.OneToMany)
				{
					Context.Utilities.PageEach(list, 5000, delegate(List<object> pageList)
					{
						OneToMany(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo);
					});
				}
				else if (navObjectNameColumnInfo.Navigat.NavigatType == NavigateType.OneToManyByArrayList)
				{
					Context.Utilities.PageEach(list, 5000, delegate(List<object> pageList)
					{
						OneToManyByArrayList(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo);
					});
				}
				else if (navObjectNameColumnInfo.Navigat.NavigatType == NavigateType.ManyToOne)
				{
					Context.Utilities.PageEach(list, 5000, delegate(List<object> pageList)
					{
						OneToOne(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo);
					});
				}
				else if (navObjectNameColumnInfo.Navigat.NavigatType == NavigateType.Dynamic)
				{
					Context.Utilities.PageEach(list, 100, delegate(List<object> pageList)
					{
						Dynamic(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo, expression);
					});
				}
				else
				{
					Context.Utilities.PageEach(list, 100, delegate(List<object> pageList)
					{
						ManyToMany(pageList, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo);
					});
				}
			}

			private List<Expression> GetWhereExpression(ref Expression expression)
			{
				List<Expression> list = new List<Expression>();
				if ((expression as LambdaExpression).Body is MethodCallExpression)
				{
					Expression expression2 = (expression as LambdaExpression).Body;
					while (expression2 is MethodCallExpression)
					{
						list.Add(expression2);
						expression2 = (expression2 as MethodCallExpression).Arguments[0];
					}
					expression = Expression.Lambda(expression2);
				}
				return list;
			}

			private void ManyToMany(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo)
			{
				Type type = navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments()[0];
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(type);
				EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (navObjectNameColumnInfo.Navigat.BClassId.HasValue())
				{
					entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.BClassId);
				}
				Check.ExceptionEasy(entityColumnInfo == null, entityInfo.EntityName + " need primary key", entityInfo.EntityName + " 实体需要配置主键");
				SqlSugarProvider context = Context;
				context = GetCrossDatabase(context, type);
				context.InitMappingInfo(type);
				EntityColumnInfo listItemPkColumn = listItemEntity.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				if (navObjectNameColumnInfo.Navigat.AClassId.HasValue())
				{
					listItemPkColumn = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.AClassId);
				}
				Check.ExceptionEasy(listItemPkColumn == null, listItemEntity.EntityName + " need primary key", listItemEntity.EntityName + " 实体需要配置主键");
				List<object> values = (from it in list
					select it.GetType().GetProperty(listItemPkColumn.PropertyName).GetValue(it) into it
					select (it != null) ? it : "null").Distinct().ToList();
				EntityInfo entityInfo2 = Context.EntityMaintenance.GetEntityInfo(navObjectNameColumnInfo.Navigat.MappingType);
				EntityColumnInfo entityColumnInfo2 = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.MappingAId);
				EntityColumnInfo entityColumnInfo3 = entityInfo2.Columns.First((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.MappingBId);
				List<IConditionalModel> list2 = new List<IConditionalModel>();
				list2.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.In,
					FieldName = entityColumnInfo2.DbColumnName,
					FieldValue = string.Join(",", values),
					CSharpTypeName = entityColumnInfo2.PropertyInfo.PropertyType.Name
				});
				SqlSugarProvider abDb = Context;
				abDb = GetCrossDatabase(abDb, entityInfo2.Type);
				ISugarQueryable<object> sugarQueryable = abDb.Queryable<object>();
				ISugarQueryable<object> sugarQueryable2 = sugarQueryable.AS(entityInfo2.DbTableName).WhereIF(navObjectNameColumnInfo?.Navigat?.WhereSql != null, navObjectNameColumnInfo?.Navigat?.WhereSql).ClearFilter(QueryBuilder.RemoveFilters);
				QueryBuilder queryBuilder = QueryBuilder;
				List<SugarAbMapping> source = sugarQueryable2.Filter((queryBuilder != null && queryBuilder.IsDisabledGobalFilter) ? null : entityInfo2.Type).Where(list2).Select<SugarAbMapping>(sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo2.DbColumnName) + " as aid," + sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo3.DbColumnName) + " as bid")
					.ToList();
				List<IConditionalModel> list3 = new List<IConditionalModel>();
				list3.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.In,
					FieldName = entityColumnInfo.DbColumnName,
					FieldValue = string.Join(",", source.Select((SugarAbMapping it) => it.Bid).ToArray()),
					CSharpTypeName = entityColumnInfo3.PropertyInfo.PropertyType.Name
				});
				SqlInfo whereSql = GetWhereSql(GetCrossDatabase(abDb, type));
				if (whereSql.SelectString == null)
				{
					string[] manualPropertyNames = GetQueryPropertyNames(navObjectNameColumnInfo);
					List<string> values2 = (from it in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).WhereIF(manualPropertyNames != null && manualPropertyNames.Length != 0, (EntityColumnInfo it) => Enumerable.Contains(manualPropertyNames, it.PropertyName))
						select GetOneToManySelectByColumnInfo(it, abDb)).ToList();
					whereSql.SelectString = string.Join(",", values2);
				}
				else
				{
					string translationColumnName = InstanceFactory.GetQueryBuilderWithContext(abDb).Builder.GetTranslationColumnName(entityColumnInfo.DbColumnName);
					if (!whereSql.SelectString.ToLower().Contains(translationColumnName?.ToLower()) && !whereSql.SelectString.Contains("*"))
					{
						SqlInfo sqlInfo = whereSql;
						sqlInfo.SelectString = sqlInfo.SelectString + "," + translationColumnName + " AS " + translationColumnName;
					}
				}
				ISugarQueryable<object> sugarQueryable3 = context.Queryable<object>().AS(entityInfo.DbTableName).ClearFilter(QueryBuilder.RemoveFilters);
				QueryBuilder queryBuilder2 = QueryBuilder;
				List<object> list4 = selector(sugarQueryable3.Filter((queryBuilder2 != null && queryBuilder2.IsDisabledGobalFilter) ? null : entityInfo.Type).AddParameters(whereSql.Parameters).Where(list3)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.Select(whereSql.SelectString)
					.OrderByIF(whereSql.OrderByString.HasValue(), whereSql.OrderByString));
				if (list4.HasValue())
				{
					foreach (object item in list)
					{
						if (navObjectNamePropety.GetValue(item) == null)
						{
							object obj = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
							IList list5 = obj as IList;
							foreach (object item2 in list4)
							{
								string pk = listItemPkColumn.PropertyInfo.GetValue(item).ObjToString();
								string bid = entityColumnInfo.PropertyInfo.GetValue(item2).ObjToString();
								if (source.Any((SugarAbMapping x) => x.Aid == pk && x.Bid == bid))
								{
									list5.Add(item2);
								}
							}
							if (whereSql.MappingExpressions.HasValue())
							{
								MappingFieldsHelper<T> mappingFieldsHelper = new MappingFieldsHelper<T>();
								mappingFieldsHelper.Context = Context;
								mappingFieldsHelper.NavEntity = entityInfo;
								mappingFieldsHelper.RootEntity = Context.EntityMaintenance.GetEntityInfo<T>();
								mappingFieldsHelper.SetChildList(navObjectNameColumnInfo, item, list5.Cast<object>().ToList(), whereSql.MappingExpressions);
							}
							else if (whereSql.Skip.HasValue || whereSql.Take.HasValue)
							{
								IList instanceCast = obj as IList;
								IList list6 = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true) as IList;
								SkipTakeIList(whereSql, instanceCast, list6);
								navObjectNamePropety.SetValue(item, list6);
							}
							else
							{
								navObjectNamePropety.SetValue(item, obj);
							}
						}
					}
					return;
				}
				foreach (object item3 in list)
				{
					if (navObjectNamePropety.GetValue(item3) == null)
					{
						IList value = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true) as IList;
						navObjectNamePropety.SetValue(item3, value);
					}
				}
			}

			private static void SkipTakeIList(SqlInfo sql, IList instanceCast, IList newinstance)
			{
				IEnumerable<int> enumerable = Enumerable.Range(0, instanceCast.Count);
				if (sql.Skip.HasValue)
				{
					enumerable = enumerable.Skip(sql.Skip.Value);
				}
				if (sql.Take.HasValue)
				{
					enumerable = enumerable.Take(sql.Take.Value);
				}
				foreach (int item in enumerable)
				{
					newinstance.Add(instanceCast[item]);
				}
			}

			private void OneToOne(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo)
			{
				EntityColumnInfo navColumn = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
				Check.ExceptionEasy(navColumn == null, "OneToOne navigation configuration error", "OneToOne导航配置错误： 实体" + listItemEntity.EntityName + " 不存在" + navObjectNameColumnInfo.Navigat.Name);
				Type propertyType = navObjectNamePropety.PropertyType;
				SqlSugarProvider db = Context;
				db = GetCrossDatabase(db, propertyType);
				EntityInfo entityInfo = db.EntityMaintenance.GetEntityInfo(propertyType);
				db.InitMappingInfo(entityInfo.Type);
				EntityColumnInfo navPkColumn = entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				int num = entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count();
				Check.ExceptionEasy(navPkColumn == null && navObjectNameColumnInfo.Navigat.Name2 == null, entityInfo.EntityName + "need primarykey", entityInfo.EntityName + " 需要主键");
				if (navObjectNameColumnInfo.Navigat.Name2.HasValue())
				{
					navPkColumn = entityInfo.Columns.Where((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name2).FirstOrDefault();
				}
				if (navPkColumn == null && propertyType.FullName.IsCollectionsList())
				{
					Check.ExceptionEasy(navObjectNamePropety.Name + " type error ", "一对一不能是List对象 " + navObjectNamePropety.Name + " ");
				}
				List<object> list2 = null;
				bool flag = IsOwnsOneProperty(listItemEntity, navObjectNameColumnInfo);
				if (flag)
				{
					EntityColumnInfo data = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
					list2 = (from it in list.Select(delegate(object it)
						{
							if (data.ForOwnsOnePropertyInfo == null)
							{
								return it.GetType().GetProperty(navObjectNameColumnInfo.Navigat.Name).GetValue(it);
							}
							object value = data.ForOwnsOnePropertyInfo.GetValue(it);
							return value.GetType().GetProperty(navObjectNameColumnInfo.Navigat.Name).GetValue(value);
						})
						select (it != null) ? it : "null").Distinct().ToList();
				}
				else
				{
					list2 = (from it in list
						select it.GetType().GetProperty(navObjectNameColumnInfo.Navigat.Name).GetValue(it) into it
						select (it != null) ? it : "null").Distinct().ToList();
				}
				List<IConditionalModel> list3 = new List<IConditionalModel>();
				if (IsEnumNumber(navColumn))
				{
					list2 = list2.Select((object it) => Convert.ToInt64(it)).Cast<object>().ToList();
				}
				if (navPkColumn?.UnderType?.Name == UtilConstants.StringType.Name)
				{
					list2 = list2.Select((object it) => it?.ToString()?.Replace(",", "[comma]")).Cast<object>().ToList();
				}
				if (navPkColumn?.UnderType?.Name == UtilConstants.DateType.Name)
				{
					list2 = list2.Select((object it) => (it != null) ? it.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff") : null).Cast<object>().ToList();
				}
				list3.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.In,
					FieldName = navPkColumn.DbColumnName,
					FieldValue = string.Join(",", list2),
					CSharpTypeName = navPkColumn?.UnderType?.Name
				});
				if (OneToOneGlobalInstanceRegistry.IsAny())
				{
					foreach (object item in list)
					{
						if (OneToOneGlobalInstanceRegistry.IsNavigationInitializerCreated(navObjectNamePropety.GetValue(item)) && !StaticConfig.QueryOneToOneEnableDefaultValue)
						{
							navObjectNamePropety.SetValue(item, null);
						}
					}
				}
				bool flag2 = list.Any() && navObjectNamePropety.GetValue(list.First()) == null;
				if (StaticConfig.QueryOneToOneEnableDefaultValue && !flag2 && OneToOneGlobalInstanceRegistry.IsNavWithDefaultValue(navObjectNamePropety))
				{
					flag2 = list.Any() && navObjectNamePropety.GetValue(list.First()) == OneToOneGlobalInstanceRegistry.Instances[navObjectNamePropety.PropertyType];
				}
				if (!flag2)
				{
					return;
				}
				SqlInfo whereSql = GetWhereSql(db, navObjectNameColumnInfo.Navigat.Name);
				if (whereSql.SelectString == null)
				{
					string[] queryPropertyNames = GetQueryPropertyNames(navObjectNameColumnInfo);
					List<string> values = (from it in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).WhereIF(queryPropertyNames != null && queryPropertyNames.Length != 0, (EntityColumnInfo it) => Enumerable.Contains(queryPropertyNames, it.PropertyName))
						select GetOneToOneSelectByColumnInfo(it, db)).ToList();
					whereSql.SelectString = string.Join(",", values);
				}
				ISugarQueryable<object> sugarQueryable = db.Queryable<object>().ClearFilter(QueryBuilder.RemoveFilters);
				object type;
				if (!navPkColumn.IsPrimarykey || num != 1)
				{
					QueryBuilder queryBuilder = QueryBuilder;
					type = ((queryBuilder != null && queryBuilder.IsDisabledGobalFilter) ? null : entityInfo.Type);
				}
				else
				{
					type = null;
				}
				List<object> inner = selector(sugarQueryable.Filter((Type)type).AS(GetDbTableName(entityInfo, whereSql)).WhereIF(navObjectNameColumnInfo.Navigat.WhereSql.HasValue(), navObjectNameColumnInfo.Navigat.WhereSql)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.AddParameters(whereSql.Parameters)
					.Where(list3)
					.Select(whereSql.SelectString));
				if (flag)
				{
					EntityColumnInfo data2 = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
					if (data2.ForOwnsOnePropertyInfo == null)
					{
						foreach (var item2 in (from l in list
							join n in inner on navColumn.PropertyInfo.GetValue(l).ObjToString() equals navPkColumn.PropertyInfo.GetValue(n).ObjToString()
							select new { l, n }).ToList())
						{
							if (navObjectNamePropety.GetValue(item2.l) == null)
							{
								navObjectNamePropety.SetValue(item2.l, item2.n);
							}
						}
						return;
					}
					{
						foreach (var item3 in (from l in list
							let ownsObj = data2.ForOwnsOnePropertyInfo.GetValue(l)
							join n in inner on ownsObj.GetType().GetProperty(navObjectNameColumnInfo.Navigat.Name).GetValue(ownsObj)
								.ObjToString() equals navPkColumn.PropertyInfo.GetValue(n).ObjToString()
							select new { l, n }).ToList())
						{
							if (navObjectNamePropety.GetValue(item3.l) == null)
							{
								navObjectNamePropety.SetValue(item3.l, item3.n);
							}
						}
						return;
					}
				}
				foreach (var item4 in (from l in list
					join n in inner on navColumn.PropertyInfo.GetValue(l).ObjToString() equals navPkColumn.PropertyInfo.GetValue(n).ObjToString()
					select new { l, n }).ToList())
				{
					if (navObjectNamePropety.GetValue(item4.l) == null)
					{
						navObjectNamePropety.SetValue(item4.l, item4.n);
					}
					else if (OneToOneGlobalInstanceRegistry.IsNavWithDefaultValue(navObjectNamePropety) && navObjectNamePropety.GetValue(item4.l) == OneToOneGlobalInstanceRegistry.Instances[navObjectNamePropety.PropertyType])
					{
						navObjectNamePropety.SetValue(item4.l, item4.n);
					}
				}
			}

			private void OneToManyByArrayList(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo)
			{
				Check.ExceptionEasy(!navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments().Any(), navObjectNamePropety?.Name + "Navigation configuration error one to many should be List<T>", navObjectNamePropety?.Name + "导航配置错误一对多应该是List<T>");
				Type type = navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments()[0];
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(type);
				SqlSugarProvider childDb = Context;
				childDb = GetCrossDatabase(childDb, entityInfo.Type);
				childDb.InitMappingInfo(entityInfo.Type);
				EntityColumnInfo navColumn = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
				Check.ExceptionEasy(navColumn == null, entityInfo.EntityName + " not found " + navObjectNameColumnInfo.Navigat.Name + " ", $"实体 {entityInfo.EntityName} 未找到导航配置列 {navObjectNameColumnInfo.Navigat.Name} ");
				Check.ExceptionEasy(!navColumn.IsJson && !navColumn.IsArray, $"Entity {entityInfo.EntityName} navigation configuration errors {navObjectNameColumnInfo.Navigat.Name}, needs to array and IsJson = true or Pgsql IsArray = true ", $"实体 {entityInfo.EntityName} 导航配置错误 {navObjectNameColumnInfo.Navigat.Name} ，需要IsJson=true的数组或者pgsql如果是数组类型用 IsArray=true");
				EntityColumnInfo listItemPkColumn = entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				Check.ExceptionEasy(listItemPkColumn == null && navObjectNameColumnInfo.Navigat.Name2 == null, listItemEntity.EntityName + " not primary key", listItemEntity.EntityName + "没有主键");
				if (navObjectNameColumnInfo.Navigat.Name2.HasValue())
				{
					listItemPkColumn = listItemEntity.Columns.Where((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name2).FirstOrDefault();
					Check.ExceptionEasy(listItemPkColumn == null, navObjectNameColumnInfo.PropertyName + " Navigate is error ", navObjectNameColumnInfo.PropertyName + "导航配置错误,可能顺序反了。");
				}
				List<object> list2 = (from it in list
					select it.GetType().GetProperty(navColumn.PropertyName).GetValue(it) into it
					where it != null
					select it).SelectMany((object it) => (it as IEnumerable).Cast<object>()).Distinct().ToList();
				List<IConditionalModel> list3 = new List<IConditionalModel>();
				if (IsEnumNumber(navColumn))
				{
					list2 = list2.Select((object it) => Convert.ToInt64(it)).Cast<object>().ToList();
				}
				if (navColumn?.UnderType?.Name == UtilConstants.StringType.Name)
				{
					list2 = list2.Select((object it) => it?.ToString()?.Replace(",", "[comma]")).Cast<object>().ToList();
				}
				list3.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.In,
					FieldName = listItemPkColumn.DbColumnName,
					FieldValue = string.Join(",", list2),
					CSharpTypeName = listItemPkColumn?.UnderType?.Name
				});
				SqlInfo whereSql = GetWhereSql(childDb, navObjectNameColumnInfo.Navigat.Name);
				if (!list.Any() || navObjectNamePropety.GetValue(list.First()) != null)
				{
					return;
				}
				if (whereSql.SelectString == null)
				{
					string[] manualPropertyNames = GetQueryPropertyNames(navObjectNameColumnInfo);
					List<string> values = (from it in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).WhereIF(manualPropertyNames != null && manualPropertyNames.Length != 0, (EntityColumnInfo it) => Enumerable.Contains(manualPropertyNames, it.PropertyName))
						select GetOneToManySelectByColumnInfo(it, childDb)).ToList();
					whereSql.SelectString = string.Join(",", values);
				}
				ISugarQueryable<object> sugarQueryable = childDb.Queryable<object>(whereSql.TableShortName).AS(GetDbTableName(entityInfo, whereSql)).ClearFilter(QueryBuilder.RemoveFilters);
				QueryBuilder queryBuilder = QueryBuilder;
				List<object> navList = selector(sugarQueryable.Filter((queryBuilder != null && queryBuilder.IsDisabledGobalFilter) ? null : entityInfo.Type).AddParameters(whereSql.Parameters).Where(list3)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.WhereIF(navObjectNameColumnInfo?.Navigat?.WhereSql != null, navObjectNameColumnInfo?.Navigat?.WhereSql)
					.Select(whereSql.SelectString)
					.OrderByIF(whereSql.OrderByString.HasValue(), whereSql.OrderByString));
				if (navList.HasValue())
				{
					foreach (var item in (from l in list.Distinct()
						from n in navList
						let lValue = listItemPkColumn.PropertyInfo.GetValue(n).ObjToString()
						let nValues = (navColumn.PropertyInfo.GetValue(l) as IEnumerable)?.Cast<object>() ?? new List<object>()
						where nValues != null && nValues.Select((object x) => x.ObjToString()).Contains(lValue)
						select new { l, n } into it
						group it by it.l).ToList())
					{
						IEnumerable<object> source = item.Select(it => it.n);
						if (whereSql.Skip.HasValue)
						{
							source = source.Skip(whereSql.Skip.Value);
						}
						if (whereSql.Take.HasValue)
						{
							source = source.Take(whereSql.Take.Value);
						}
						if (whereSql.MappingExpressions.HasValue())
						{
							MappingFieldsHelper<T> mappingFieldsHelper = new MappingFieldsHelper<T>();
							mappingFieldsHelper.NavEntity = entityInfo;
							mappingFieldsHelper.Context = Context;
							mappingFieldsHelper.RootEntity = Context.EntityMaintenance.GetEntityInfo<T>();
							mappingFieldsHelper.SetChildList(navObjectNameColumnInfo, item.Key, source.ToList(), whereSql.MappingExpressions);
							continue;
						}
						object obj = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
						IList list4 = obj as IList;
						foreach (object item2 in source.ToList())
						{
							list4.Add(item2);
						}
						navObjectNamePropety.SetValue(item.Key, obj);
					}
					{
						foreach (object item3 in list)
						{
							if (navObjectNamePropety.GetValue(item3) == null)
							{
								object value = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
								navObjectNamePropety.SetValue(item3, value);
							}
						}
						return;
					}
				}
				foreach (object item4 in list)
				{
					object value2 = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
					navObjectNamePropety.SetValue(item4, value2);
				}
			}

			private void OneToMany(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo)
			{
				Check.ExceptionEasy(!navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments().Any(), navObjectNamePropety?.Name + "Navigation configuration error one to many should be List<T>", navObjectNamePropety?.Name + "导航配置错误一对多应该是List<T>");
				Type type = navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments()[0];
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(type);
				SqlSugarProvider childDb = Context;
				childDb = GetCrossDatabase(childDb, entityInfo.Type);
				childDb.InitMappingInfo(entityInfo.Type);
				EntityColumnInfo navColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
				Check.ExceptionEasy(navColumn == null, entityInfo.EntityName + " not found " + navObjectNameColumnInfo.Navigat.Name + " ", $"实体 {entityInfo.EntityName} 未找到导航配置列 {navObjectNameColumnInfo.Navigat.Name} ");
				EntityColumnInfo listItemPkColumn = listItemEntity.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				Check.ExceptionEasy(listItemPkColumn == null && navObjectNameColumnInfo.Navigat.Name2 == null, listItemEntity.EntityName + " not primary key", listItemEntity.EntityName + "没有主键");
				if (navObjectNameColumnInfo.Navigat.Name2.HasValue())
				{
					listItemPkColumn = listItemEntity.Columns.Where((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name2).FirstOrDefault();
					Check.ExceptionEasy(listItemPkColumn == null, navObjectNameColumnInfo.PropertyName + " Navigate is error ", navObjectNameColumnInfo.PropertyName + "导航配置错误,可能顺序反了。");
				}
				List<object> list2 = (from it in list
					select it.GetType().GetProperty(listItemPkColumn.PropertyName).GetValue(it) into it
					select (it != null) ? it : "null").Distinct().ToList();
				List<IConditionalModel> list3 = new List<IConditionalModel>();
				if (IsEnumNumber(navColumn))
				{
					list2 = list2.Select((object it) => Convert.ToInt64(it)).Cast<object>().ToList();
				}
				if (navColumn?.UnderType?.Name == UtilConstants.StringType.Name)
				{
					list2 = list2.Select((object it) => it?.ToString()?.Replace(",", "[comma]")).Cast<object>().ToList();
				}
				list3.Add(new ConditionalModel
				{
					ConditionalType = ConditionalType.In,
					FieldName = navColumn.DbColumnName,
					FieldValue = string.Join(",", list2),
					CSharpTypeName = listItemPkColumn?.UnderType?.Name
				});
				SqlInfo whereSql = GetWhereSql(childDb, navObjectNameColumnInfo.Navigat.Name);
				if (!list.Any() || navObjectNamePropety.GetValue(list.First()) != null)
				{
					return;
				}
				if (whereSql.SelectString == null)
				{
					string[] manualPropertyNames = GetQueryPropertyNames(navObjectNameColumnInfo);
					List<string> values = (from it in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).WhereIF(manualPropertyNames != null && manualPropertyNames.Length != 0, (EntityColumnInfo it) => Enumerable.Contains(manualPropertyNames, it.PropertyName))
						select GetOneToManySelectByColumnInfo(it, childDb)).ToList();
					whereSql.SelectString = string.Join(",", values);
				}
				ISugarQueryable<object> sugarQueryable = childDb.Queryable<object>(whereSql.TableShortName).AS(GetDbTableName(entityInfo, whereSql)).ClearFilter(QueryBuilder.RemoveFilters);
				QueryBuilder queryBuilder = QueryBuilder;
				List<object> list4 = selector(sugarQueryable.Filter((queryBuilder != null && queryBuilder.IsDisabledGobalFilter) ? null : entityInfo.Type).AddParameters(whereSql.Parameters).Where(list3)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.WhereIF(navObjectNameColumnInfo?.Navigat?.WhereSql != null, navObjectNameColumnInfo?.Navigat?.WhereSql)
					.Select(whereSql.SelectString)
					.OrderByIF(whereSql.OrderByString.HasValue(), whereSql.OrderByString));
				if (list4.HasValue())
				{
					foreach (var item in (from l in list.Distinct()
						join n in list4 on listItemPkColumn.PropertyInfo.GetValue(l).ObjToString() equals navColumn.PropertyInfo.GetValue(n).ObjToString()
						select new { l, n } into it
						group it by it.l).ToList())
					{
						IEnumerable<object> source = item.Select(it => it.n);
						if (whereSql.Skip.HasValue)
						{
							source = source.Skip(whereSql.Skip.Value);
						}
						if (whereSql.Take.HasValue)
						{
							source = source.Take(whereSql.Take.Value);
						}
						if (whereSql.MappingExpressions.HasValue())
						{
							MappingFieldsHelper<T> mappingFieldsHelper = new MappingFieldsHelper<T>();
							mappingFieldsHelper.NavEntity = entityInfo;
							mappingFieldsHelper.Context = Context;
							mappingFieldsHelper.RootEntity = Context.EntityMaintenance.GetEntityInfo<T>();
							mappingFieldsHelper.SetChildList(navObjectNameColumnInfo, item.Key, source.ToList(), whereSql.MappingExpressions);
							continue;
						}
						object obj = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
						IList list5 = obj as IList;
						foreach (object item2 in source.ToList())
						{
							list5.Add(item2);
						}
						navObjectNamePropety.SetValue(item.Key, obj);
					}
					{
						foreach (object item3 in list)
						{
							if (navObjectNamePropety.GetValue(item3) == null)
							{
								object value = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
								navObjectNamePropety.SetValue(item3, value);
							}
						}
						return;
					}
				}
				foreach (object item4 in list)
				{
					object value2 = Activator.CreateInstance(navObjectNamePropety.PropertyType, nonPublic: true);
					navObjectNamePropety.SetValue(item4, value2);
				}
			}

			private void Dynamic(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo, Expression expression)
			{
				Type[] genericArguments = navObjectNameColumnInfo.PropertyInfo.PropertyType.GetGenericArguments();
				if (genericArguments.Length == 0)
				{
					DynamicOneToOne(list, selector, listItemEntity, navObjectNamePropety, navObjectNameColumnInfo, expression);
					return;
				}
				Type type = genericArguments[0];
				SqlSugarProvider context = Context;
				context = GetCrossDatabase(context, type);
				context.InitMappingInfo(type);
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
				SqlInfo whereSql = GetWhereSql(context, navObjectNameColumnInfo.Navigat.Name);
				if (IsJsonMapping(navObjectNameColumnInfo, whereSql))
				{
					CreateDynamicMappingExpression(whereSql, navObjectNameColumnInfo.Navigat.Name, entityInfo, listItemEntity);
					if (whereSql.WhereString == null)
					{
						whereSql.WhereString = navObjectNameColumnInfo?.Navigat?.Name2;
					}
				}
				Check.ExceptionEasy(whereSql.MappingExpressions.IsNullOrEmpty(), $"{expression} error,dynamic need MappingField ,Demo: Includes(it => it.Books.MappingField(z=>z.studenId,()=>it.StudentId).ToList())", $"{expression} 解析出错,自定义映射需要 MappingField ,例子: Includes(it => it.Books.MappingField(z=>z.studenId,()=>it.StudentId).ToList())");
				if (!list.Any() || navObjectNamePropety.GetValue(list.First()) != null)
				{
					return;
				}
				MappingFieldsHelper<T> mappingFieldsHelper = new MappingFieldsHelper<T>();
				mappingFieldsHelper.Context = context;
				mappingFieldsHelper.NavEntity = entityInfo;
				mappingFieldsHelper.RootEntity = context.EntityMaintenance.GetEntityInfo<T>();
				List<IConditionalModel> mppingSql = mappingFieldsHelper.GetMppingSql(list, whereSql.MappingExpressions);
				List<object> list2 = selector(context.Queryable<object>().AS(GetDbTableName(entityInfo, whereSql)).AddParameters(whereSql.Parameters)
					.Where(mppingSql, isWrap: true)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.Select(whereSql.SelectString)
					.OrderByIF(whereSql.OrderByString.HasValue(), whereSql.OrderByString));
				if (!list2.HasValue())
				{
					return;
				}
				foreach (object item in list)
				{
					mappingFieldsHelper.SetChildList(navObjectNameColumnInfo, item, list2, whereSql.MappingExpressions);
				}
			}

			private void DynamicOneToOne(List<object> list, Func<ISugarQueryable<object>, List<object>> selector, EntityInfo listItemEntity, PropertyInfo navObjectNamePropety, EntityColumnInfo navObjectNameColumnInfo, Expression expression)
			{
				Type propertyType = navObjectNameColumnInfo.PropertyInfo.PropertyType;
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(propertyType);
				SqlSugarProvider context = Context;
				context = GetCrossDatabase(context, propertyType);
				Context.InitMappingInfo(propertyType);
				SqlInfo whereSql = GetWhereSql(context, navObjectNameColumnInfo.Navigat.Name);
				if (IsJsonMapping(navObjectNameColumnInfo, whereSql))
				{
					CreateDynamicMappingExpression(whereSql, navObjectNameColumnInfo.Navigat.Name, entityInfo, listItemEntity);
					if (whereSql.WhereString == null)
					{
						whereSql.WhereString = navObjectNameColumnInfo?.Navigat?.Name2;
					}
				}
				Check.ExceptionEasy(whereSql.MappingExpressions.IsNullOrEmpty(), $"{expression} error，dynamic need MappingField ,Demo: Includes(it => it.Books.MappingField(z=>z.studenId,()=>it.StudentId).ToList())", $"{expression}解析出错， 自定义映射需要 MappingField ,例子: Includes(it => it.Books.MappingField(z=>z.studenId,()=>it.StudentId).ToList())");
				if (!list.Any() || navObjectNamePropety.GetValue(list.First()) != null)
				{
					return;
				}
				MappingFieldsHelper<T> mappingFieldsHelper = new MappingFieldsHelper<T>();
				mappingFieldsHelper.Context = Context;
				mappingFieldsHelper.NavEntity = entityInfo;
				mappingFieldsHelper.RootEntity = Context.EntityMaintenance.GetEntityInfo<T>();
				List<IConditionalModel> mppingSql = mappingFieldsHelper.GetMppingSql(list, whereSql.MappingExpressions);
				List<object> list2 = selector(context.Queryable<object>().AS(GetDbTableName(entityInfo, whereSql)).AddParameters(whereSql.Parameters)
					.Where(mppingSql, isWrap: true)
					.WhereIF(whereSql.WhereString.HasValue(), whereSql.WhereString)
					.Select(whereSql.SelectString)
					.OrderByIF(whereSql.OrderByString.HasValue(), whereSql.OrderByString));
				if (!list2.HasValue())
				{
					return;
				}
				foreach (object item in list)
				{
					mappingFieldsHelper.SetChildItem(navObjectNameColumnInfo, item, list2, whereSql.MappingExpressions);
				}
			}

			private SqlInfo GetWhereSql(ISqlSugarClient db, string properyName = null)
			{
				if (_ListCallFunc == null || _ListCallFunc.Count == 0)
				{
					return new SqlInfo();
				}
				List<string> list = new List<string>();
				List<string> list2 = new List<string>();
				_ListCallFunc.Reverse();
				SqlInfo sqlInfo = new SqlInfo();
				sqlInfo.Parameters = new List<SugarParameter>();
				bool flag = false;
				int parameterIndex = 100;
				foreach (Expression item in _ListCallFunc)
				{
					MethodCallExpression methodCallExpression = item as MethodCallExpression;
					ISugarQueryable<object> sugarQueryable = db.Queryable<object>();
					if (methodCallExpression.Method.Name == "Where")
					{
						if (methodCallExpression.Arguments[1].Type == typeof(List<IConditionalModel>))
						{
							List<IConditionalModel> list3 = ExpressionTool.GetExpressionValue(methodCallExpression.Arguments[1]) as List<IConditionalModel>;
							if (list3.Count > 0)
							{
								KeyValuePair<string, SugarParameter[]> keyValuePair = sugarQueryable.QueryBuilder.Builder.ConditionalModelToSql(list3);
								list.Add(keyValuePair.Key);
								if (keyValuePair.Value != null)
								{
									sqlInfo.Parameters.AddRange(keyValuePair.Value);
								}
							}
						}
						else
						{
							sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = parameterIndex;
							CheckHasRootShortName(methodCallExpression.Arguments[0], methodCallExpression.Arguments[1]);
							Expression expression = methodCallExpression.Arguments[1];
							InitMappingtType(expression);
							list.Add(" " + sugarQueryable.QueryBuilder.GetExpressionValue(expression, ResolveExpressType.WhereSingle).GetString());
							SetTableShortName(sqlInfo, sugarQueryable);
							parameterIndex = sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex;
						}
					}
					else if (methodCallExpression.Method.Name == "WhereIF")
					{
						if (Expression.Lambda(methodCallExpression.Arguments[1]).Compile().DynamicInvoke()
							.ObjToBool())
						{
							sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = parameterIndex;
							Expression expression2 = methodCallExpression.Arguments[2];
							InitMappingtType(expression2);
							CheckHasRootShortName(methodCallExpression.Arguments[1], methodCallExpression.Arguments[2]);
							list.Add(" " + sugarQueryable.QueryBuilder.GetExpressionValue(expression2, ResolveExpressType.WhereSingle).GetString());
							SetTableShortName(sqlInfo, sugarQueryable);
							parameterIndex = sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex;
						}
					}
					else if (methodCallExpression.Method.Name.IsIn("OrderBy", "ThenBy"))
					{
						Expression expression3 = methodCallExpression.Arguments[1];
						list2.Add(" " + sugarQueryable.QueryBuilder.GetExpressionValue(expression3, ResolveExpressType.WhereSingle).GetString());
						SetTableShortName(sqlInfo, sugarQueryable);
					}
					else if (methodCallExpression.Method.Name == "MappingField")
					{
						if (sqlInfo.MappingExpressions == null)
						{
							sqlInfo.MappingExpressions = new List<MappingFieldsExpression>();
						}
						sqlInfo.MappingExpressions.Add(new MappingFieldsExpression
						{
							LeftColumnExpression = methodCallExpression.Arguments[1],
							RightColumnExpression = methodCallExpression.Arguments[2]
						});
					}
					else if (methodCallExpression.Method.Name == "Select")
					{
						Select(properyName, sqlInfo, methodCallExpression, sugarQueryable);
					}
					else if (methodCallExpression.Method.Name.IsIn("OrderByDescending", "ThenByDescending"))
					{
						Expression expression4 = methodCallExpression.Arguments[1];
						list2.Add(" " + sugarQueryable.QueryBuilder.GetExpressionValue(expression4, ResolveExpressType.WhereSingle).GetString() + " DESC");
					}
					else if (methodCallExpression.Method.Name == "Skip")
					{
						Expression expression5 = methodCallExpression.Arguments[1];
						if (expression5 is BinaryExpression)
						{
							sqlInfo.Skip = (int)ExpressionTool.DynamicInvoke(expression5);
						}
						else
						{
							sqlInfo.Skip = (int)ExpressionTool.GetExpressionValue(expression5);
						}
					}
					else if (methodCallExpression.Method.Name == "Take")
					{
						Expression expression6 = methodCallExpression.Arguments[1];
						if (expression6 is BinaryExpression)
						{
							sqlInfo.Take = (int)ExpressionTool.DynamicInvoke(expression6);
						}
						else
						{
							sqlInfo.Take = (int)ExpressionTool.GetExpressionValue(expression6);
						}
					}
					else if (methodCallExpression.Method.Name == "ToList")
					{
						if (methodCallExpression.Arguments.Count > 1)
						{
							Select(properyName, sqlInfo, methodCallExpression, sugarQueryable);
						}
						flag = true;
					}
					else if (methodCallExpression.Method.Name == "SplitTable")
					{
						Expression<Func<List<SplitTableInfo>, IEnumerable<SplitTableInfo>>> expression7 = (Expression<Func<List<SplitTableInfo>, IEnumerable<SplitTableInfo>>>)(item as MethodCallExpression).Arguments[1];
						sqlInfo.SplitTable = expression7.Compile();
					}
					else
					{
						Check.ExceptionEasy($"no support {item}", $"不支持表达式{item} 不支持方法{methodCallExpression.Method.Name}");
					}
					if (sugarQueryable.QueryBuilder.Parameters != null)
					{
						sqlInfo.Parameters.AddRange(sugarQueryable.QueryBuilder.Parameters);
					}
				}
				if (list.Any())
				{
					Check.ExceptionEasy(!flag, $"{_ListCallFunc.First()} need is ToList()", $"{_ListCallFunc.First()} 需要ToList");
					sqlInfo.WhereString = string.Join(" AND ", list);
				}
				if (list2.Any())
				{
					Check.ExceptionEasy(!flag, $"{_ListCallFunc.First()} need is ToList()", $"{_ListCallFunc.First()} 需要ToList");
					sqlInfo.OrderByString = string.Join(" , ", list2);
				}
				if (sqlInfo.SelectString.HasValue())
				{
					Check.ExceptionEasy(!flag, $"{_ListCallFunc.First()} need is ToList()", $"{_ListCallFunc.First()} 需要ToList");
					sqlInfo.OrderByString = string.Join(" , ", list2);
				}
				return sqlInfo;
			}

			private void Select(string properyName, SqlInfo result, MethodCallExpression method, ISugarQueryable<object> queryable)
			{
				Expression expression = method.Arguments[1];
				Expression body = (expression as LambdaExpression).Body;
				Type[] genericArguments = expression.Type.GetGenericArguments();
				List<string> list = (from it in ExpressionTool.GetParameters(expression)
					select it.Name).Distinct().ToList();
				if (list.Count > 1 && result.TableShortName.IsNullOrEmpty())
				{
					result.TableShortName = list[0];
				}
				if (genericArguments == null || genericArguments.Length == 0)
				{
					return;
				}
				Type type = genericArguments[0];
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(type);
				Context.InitMappingInfo(type);
				Check.ExceptionEasy(body.Type != entityInfo.Type, $" new {body.Type.Name}is error ,use Select(it=>new {entityInfo.Type.Name})", $"new {body.Type.Name}是错误的，请使用Select(it=>new {entityInfo.Type.Name})");
				if (entityInfo.Columns.Count((EntityColumnInfo x) => x.Navigat != null) == 0)
				{
					result.SelectString = " " + queryable.QueryBuilder.GetExpressionValue(expression, ResolveExpressType.SelectSingle).GetString();
				}
				else
				{
					EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo x) => x.IsPrimarykey);
					result.SelectString = " " + queryable.QueryBuilder.GetExpressionValue(expression, ResolveExpressType.SelectSingle).GetString();
					if (ExpressionTool.ContainsTwoLevelAccess(expression))
					{
						string text = ExpressionTool.GetParameters(expression).FirstOrDefault()?.Name;
						if (text.HasValue() && result.TableShortName == null)
						{
							result.TableShortName = text;
							result.IsSelectNav = true;
						}
					}
					if (entityColumnInfo != null)
					{
						string dbColumnName = entityColumnInfo.DbColumnName;
						AppColumns(result, queryable, dbColumnName);
					}
					foreach (EntityColumnInfo nav in entityInfo.Columns.Where((EntityColumnInfo x) => x.Navigat != null && x.Navigat.NavigatType == NavigateType.OneToOne))
					{
						EntityColumnInfo entityColumnInfo2 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.Navigat.Name);
						if (entityColumnInfo2 != null)
						{
							AppColumns(result, queryable, entityColumnInfo2.DbColumnName);
						}
					}
					foreach (EntityColumnInfo nav2 in entityInfo.Columns.Where((EntityColumnInfo x) => x.Navigat != null && x.Navigat.NavigatType == NavigateType.OneToMany && x.Navigat.Name2 != null))
					{
						EntityColumnInfo entityColumnInfo3 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav2.Navigat.Name2);
						if (entityColumnInfo3 != null)
						{
							AppColumns(result, queryable, entityColumnInfo3.DbColumnName);
						}
					}
					result.SelectString = result.SelectString.TrimStart(',');
					if (result.SelectString == "")
					{
						result.SelectString = null;
					}
				}
				if (properyName != null)
				{
					EntityColumnInfo entityColumnInfo4 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == properyName);
					EntityColumnInfo entityColumnInfo5 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo x) => x.IsPrimarykey);
					if (entityColumnInfo4 != null)
					{
						string dbColumnName2 = entityColumnInfo4.DbColumnName;
						AppColumns(result, queryable, dbColumnName2);
					}
					if (entityColumnInfo5 != null && entityColumnInfo4 == null && result.SelectString != null && !result.SelectString.Contains(queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo5.DbColumnName)))
					{
						AppColumns(result, queryable, entityColumnInfo5.DbColumnName);
					}
				}
			}

			private static void SetTableShortName(SqlInfo result, ISugarQueryable<object> queryable)
			{
				if (queryable.QueryBuilder.TableShortName.HasValue() && result.TableShortName.IsNullOrEmpty())
				{
					result.TableShortName = queryable.QueryBuilder.TableShortName;
				}
			}

			private SqlSugarProvider GetCrossDatabase(SqlSugarProvider db, Type type)
			{
				if (!IsCrossQueryWithAttr && CrossQueryItems == null)
				{
					return db;
				}
				if (IsCrossQueryWithAttr)
				{
					TenantAttribute customAttribute = type.GetCustomAttribute<TenantAttribute>();
					if (customAttribute != null)
					{
						return db.Root.GetConnection(customAttribute.configId);
					}
					return db;
				}
				if (CrossQueryItems != null && CrossQueryItems.Count > 0 && CrossQueryItems.ContainsKey(type.FullName))
				{
					return db.Root.GetConnection(CrossQueryItems[type.FullName]);
				}
				return db;
			}

			private static void AppColumns(SqlInfo result, ISugarQueryable<object> queryable, string columnName)
			{
				string translationColumnName = queryable.SqlBuilder.GetTranslationColumnName(columnName);
				if (result.IsSelectNav && result.SelectString != null && !result.SelectString.ToLower().Contains(" " + translationColumnName.ToLower() + " AS " + translationColumnName.ToLower()))
				{
					result.SelectString = result.SelectString + "," + translationColumnName + " AS " + translationColumnName;
				}
				if (result.SelectString != null && !result.SelectString.ToLower().Contains(translationColumnName.ToLower()))
				{
					result.SelectString = result.SelectString + "," + translationColumnName + " AS " + translationColumnName;
				}
			}

			public void CheckHasRootShortName(Expression rootExpression, Expression childExpression)
			{
				string shortName = GetShortName(rootExpression);
				if (shortName.HasValue() && childExpression.ToString().Contains(" " + shortName + "."))
				{
					Check.ExceptionEasy($".Where({childExpression}) no support {shortName}.Field, Use .MappingField", $".Where({childExpression})禁止出{shortName}.字段 , 你可以使用.MappingField(z=>z.字段,()=>{shortName}.字段) 与主表字段进行过滤");
				}
				else if (shortName.HasValue() && childExpression.ToString().Contains("(" + shortName + "."))
				{
					Check.ExceptionEasy($".Where({childExpression}) no support {shortName}.Field, Use .MappingField", $".Where({childExpression})禁止出{shortName}.字段 , 你可以使用.MappingField(z=>z.字段,()=>{shortName}.字段) 与主表字段进行过滤");
				}
			}

			private static string GetShortName(Expression expression1)
			{
				string result = null;
				if (expression1 is MemberExpression)
				{
					Expression expression2 = (expression1 as MemberExpression).Expression;
					if (expression2 != null && expression2.Type == typeof(T) && expression2 is ParameterExpression)
					{
						result = (expression2 as ParameterExpression).Name;
					}
				}
				return result;
			}

			private string GetDbTableName(EntityInfo navEntityInfo, SqlInfo sqlInfo)
			{
				if (navEntityInfo.Type.GetCustomAttribute<SplitTableAttribute>() != null && sqlInfo.SplitTable != null)
				{
					return "(" + Context.QueryableByObject(navEntityInfo.Type).SplitTable(sqlInfo.SplitTable).ToSqlString() + ") split_table";
				}
				if (navEntityInfo.Type.GetCustomAttribute<SplitTableAttribute>() != null)
				{
					return "(" + Context.QueryableByObject(navEntityInfo.Type).SplitTable().ToSqlString() + ") split_table";
				}
				return navEntityInfo.DbTableName;
			}

			private void InitMappingtType(Expression exp)
			{
				if (!(exp is LambdaExpression))
				{
					return;
				}
				ReadOnlyCollection<ParameterExpression> parameters = (exp as LambdaExpression).Parameters;
				if (parameters == null)
				{
					return;
				}
				foreach (ParameterExpression item in parameters)
				{
					Context.InitMappingInfo(item.Type);
				}
			}

			private bool IsEnumNumber(EntityColumnInfo navPkColumn)
			{
				if (navPkColumn != null && navPkColumn.UnderType?.IsEnum() == true && (navPkColumn == null || navPkColumn.SqlParameterDbType == null))
				{
					SqlSugarProvider context = Context;
					if (context == null)
					{
						return true;
					}
					return context.CurrentConnectionConfig?.MoreSettings?.TableEnumIsString != true;
				}
				return false;
			}

			private static bool IsOwnsOneProperty(EntityInfo listItemEntity, EntityColumnInfo navObjectNameColumnInfo)
			{
				if (listItemEntity.Columns.Any((EntityColumnInfo it) => it.IsOwnsOne))
				{
					return !listItemEntity.Type.GetProperties().Any((PropertyInfo it) => it.PropertyType.Name == navObjectNameColumnInfo.Navigat.Name);
				}
				return false;
			}

			private static bool IsJsonMapping(EntityColumnInfo navObjectNameColumnInfo, SqlInfo sqlObj)
			{
				if (sqlObj.MappingExpressions == null)
				{
					return navObjectNameColumnInfo.Navigat.Name.HasValue();
				}
				return false;
			}

			private void CreateDynamicMappingExpression(SqlInfo sqlObj, string name, EntityInfo navEntityInfo, EntityInfo listItemEntity)
			{
				JArray obj = JArray.Parse(name);
				sqlObj.MappingExpressions = new List<MappingFieldsExpression>();
				foreach (JToken item in obj)
				{
					string m = ((object)item[(object)"m"])?.ToString() ?? "";
					string c = ((object)item[(object)"c"])?.ToString() ?? "";
					Check.ExceptionEasy(m.IsNullOrEmpty() || c.IsNullOrEmpty(), name + " Navigation json format error, see documentation", name + "导航json格式错误,请看文档");
					EntityColumnInfo entityColumnInfo = navEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(c));
					Check.ExceptionEasy(entityColumnInfo == null, c + " does not exist in " + navEntityInfo.EntityName, c + "不存在于" + navEntityInfo.EntityName);
					EntityColumnInfo rightEntityColumn = listItemEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(m));
					Check.ExceptionEasy(entityColumnInfo == null, m + " does not exist in " + listItemEntity.EntityName, m + "不存在于" + listItemEntity.EntityName);
					sqlObj.MappingExpressions.Add(new MappingFieldsExpression
					{
						LeftEntityColumn = entityColumnInfo,
						RightEntityColumn = rightEntityColumn
					});
				}
			}

			private string GetOneToManySelectByColumnInfo(EntityColumnInfo it, ISqlSugarClient db)
			{
				QueryBuilder queryBuilderWithContext = InstanceFactory.GetQueryBuilderWithContext(db);
				if (it.QuerySql.HasValue())
				{
					return it.QuerySql + " AS " + queryBuilderWithContext.Builder.GetTranslationColumnName(it.PropertyName);
				}
				if (it.ForOwnsOnePropertyInfo != null)
				{
					return queryBuilderWithContext.Builder.GetTranslationColumnName(it.DbColumnName);
				}
				return queryBuilderWithContext.Builder.GetTranslationColumnName(it.DbColumnName) + " AS " + queryBuilderWithContext.Builder.GetTranslationColumnName(it.PropertyName);
			}

			private string GetOneToOneSelectByColumnInfo(EntityColumnInfo it, ISqlSugarClient db)
			{
				QueryBuilder queryBuilderWithContext = InstanceFactory.GetQueryBuilderWithContext(db);
				if (it.QuerySql.HasValue())
				{
					return it.QuerySql + " AS " + queryBuilderWithContext.Builder.GetTranslationColumnName(it.PropertyName);
				}
				if (it.ForOwnsOnePropertyInfo != null)
				{
					return queryBuilderWithContext.Builder.GetTranslationColumnName(it.DbColumnName);
				}
				return queryBuilderWithContext.Builder.GetTranslationColumnName(it.DbColumnName) + " AS " + queryBuilderWithContext.Builder.GetTranslationColumnName(it.PropertyName);
			}

			/// <summary>
			/// 获取查询的属性名称列表
			/// </summary>
			/// <param name="navObjectNamePropety"></param>
			/// <returns></returns>
			private string[] GetQueryPropertyNames(EntityColumnInfo navObjectNameColumnInfo)
			{
				string[] result = null;
				if (navObjectNameColumnInfo != null && navObjectNameColumnInfo.Navigat?.QueryPropertyNames?.Any() == true)
				{
					Navigate navigate = navObjectNameColumnInfo?.Navigat;
					result = navObjectNameColumnInfo.Navigat.QueryPropertyNames;
					List<string> list = result.ToList();
					if (navigate.AClassId != null)
					{
						list.Add(navigate.AClassId);
					}
					if (navigate.BClassId != null)
					{
						list.Add(navigate.BClassId);
					}
					if (navigate.Name != null)
					{
						list.Add(navigate.Name);
					}
					if (navigate.Name2 != null)
					{
						list.Add(navigate.Name2);
					}
					result = list.ToArray();
				}
				return result;
			}
		}
		internal class NavSelectHelper
		{
			internal class NavMappingColumn
			{
				public string Key { get; set; }

				public string Value { get; set; }

				public bool IsError { get; set; }
			}

			internal static List<TResult> GetList<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				List<TResult> list = new List<TResult>();
				bool flag = IsSqlFunc(expression, queryableProvider);
				bool flag2 = IsClass(expression, queryableProvider);
				if (isGroup(expression, queryableProvider))
				{
					ISugarQueryable<T> sugarQueryable = queryableProvider.Clone();
					sugarQueryable.QueryBuilder.Includes = null;
					list = sugarQueryable.Select(expression).ToList();
					ISugarQueryable<T> sugarQueryable2 = queryableProvider.Clone();
					sugarQueryable2.Select(GetGroupSelect(typeof(T), queryableProvider.Context, queryableProvider.QueryBuilder));
					sugarQueryable2.QueryBuilder.NoCheckInclude = true;
					List<NavMappingColumn> mappingColumn = GetMappingColumn(expression);
					MegerList(list, sugarQueryable2.ToList(), sugarQueryable.Context, mappingColumn);
				}
				else if (flag)
				{
					list = SqlFunc(expression, queryableProvider);
				}
				else if (typeof(TResult).IsAnonymousType() && !flag2)
				{
					list = SqlFunc(expression, queryableProvider);
				}
				else if (typeof(TResult).IsAnonymousType() && flag2)
				{
					list = Action(expression, queryableProvider);
				}
				else if (expression.ToString().Contains("FirstOrDefault()"))
				{
					list = Action(expression, queryableProvider);
				}
				else
				{
					try
					{
						list = SqlFunc(expression, queryableProvider);
					}
					catch (Exception ex)
					{
						try
						{
							Console.WriteLine("Select DTO  error  . Warning:" + ex.Message);
							list = Action(expression, queryableProvider);
						}
						catch
						{
							throw;
						}
					}
				}
				return list;
			}

			private static List<TResult> Action<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				queryableProvider.Context.EntityMaintenance.GetEntityInfo<TResult>();
				List<T> list = queryableProvider.Clone().ToList();
				DataTable dataTable = queryableProvider.Context.Utilities.ListToDataTable(list);
				foreach (DataRow row in dataTable.Rows)
				{
					foreach (DataColumn column in dataTable.Columns)
					{
						if (column.DataType.IsClass() && (row[column.ColumnName] == null || row[column.ColumnName] == DBNull.Value))
						{
							row[column.ColumnName] = Activator.CreateInstance(column.DataType, nonPublic: true);
						}
					}
				}
				list = queryableProvider.Context.Utilities.DataTableToList<T>(dataTable);
				return list.Select(expression.Compile()).ToList();
			}

			private static List<TResult> SqlFunc<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				List<NavMappingColumn> mappingColumn = GetMappingColumn(expression);
				if (mappingColumn.Any((NavMappingColumn it) => it.IsError))
				{
					return Action(expression, queryableProvider);
				}
				ISugarQueryable<T> sugarQueryable = queryableProvider.Clone();
				List<EntityColumnInfo> columns = sugarQueryable.Context.EntityMaintenance.GetEntityInfo<TResult>().Columns;
				List<EntityColumnInfo> columns2 = sugarQueryable.Context.EntityMaintenance.GetEntityInfo<T>().Columns;
				string[] ignoreColumns = GetIgnoreColumns(columns, columns2);
				sugarQueryable.QueryBuilder.Includes = null;
				List<TResult> result = sugarQueryable.IgnoreColumns(ignoreColumns).Select(expression).ToList();
				string defaultSelector = GetDefaultSelector(queryableProvider.Context.EntityMaintenance.GetEntityInfo<T>(), queryableProvider.QueryBuilder);
				ISugarQueryable<T> sugarQueryable2 = queryableProvider.Select(defaultSelector).Clone();
				sugarQueryable2.QueryBuilder.NoCheckInclude = true;
				List<T> includeList = sugarQueryable2.ToList();
				MegerList(result, includeList, sugarQueryable.Context, mappingColumn);
				return result;
			}

			private static string[] GetIgnoreColumns(List<EntityColumnInfo> dtoEntity, List<EntityColumnInfo> tableEntity)
			{
				return (from dto in dtoEntity
					join tab in tableEntity on dto.PropertyInfo.PropertyType equals tab.PropertyInfo.PropertyType
					where tab.Navigat != null
					select tab.PropertyName).Distinct().ToArray();
			}

			internal static async Task<List<TResult>> GetListAsync<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				return await Task.Run(() => GetList(expression, queryableProvider));
			}

			private static string GetGroupSelect(Type type, SqlSugarProvider context, QueryBuilder queryBuilder)
			{
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
				List<string> list = new List<string>();
				foreach (EntityColumnInfo listNavColumn in GetListNavColumns(entityInfo))
				{
					if (queryBuilder.TableShortName.HasValue())
					{
						list.Add($" min({queryBuilder.TableShortName}.{listNavColumn.DbColumnName}) as {listNavColumn.DbColumnName}");
					}
					else
					{
						list.Add(" min(" + listNavColumn.DbColumnName + ") as " + listNavColumn.DbColumnName);
					}
				}
				return string.Join(",", list);
			}

			private static string GetDefaultSelector(EntityInfo entityInfo, QueryBuilder queryBuilder)
			{
				List<EntityColumnInfo> listNavColumns = GetListNavColumns(entityInfo);
				List<string> list = new List<string>();
				if (listNavColumns.Count == 0)
				{
					return null;
				}
				foreach (EntityColumnInfo item in listNavColumns)
				{
					if (queryBuilder.TableShortName.HasValue())
					{
						list.Add($" {queryBuilder.TableShortName}.{item.DbColumnName} as {item.DbColumnName}");
					}
					else
					{
						list.Add(" " + item.DbColumnName + " as " + item.DbColumnName);
					}
				}
				return string.Join(",", list);
			}

			private static List<EntityColumnInfo> GetListNavColumns(EntityInfo entityInfo)
			{
				string[] list = (from it in entityInfo.Columns
					where it.Navigat != null
					select it.Navigat.Name).ToArray();
				string[] list2 = (from it in entityInfo.Columns
					where it.Navigat != null && it.Navigat.Name2 != null
					select it.Navigat.Name2).ToArray();
				return entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey || Enumerable.Contains(list, it.PropertyName) || Enumerable.Contains(list2, it.PropertyName)).ToList();
			}

			private static void MegerList<TResult, T>(List<TResult> result, List<T> includeList, SqlSugarProvider context, List<NavMappingColumn> navMappingColumns)
			{
				if (result.Count != includeList.Count)
				{
					return;
				}
				List<EntityColumnInfo> columns = context.EntityMaintenance.GetEntityInfo<T>().Columns;
				List<EntityColumnInfo> columns2 = context.EntityMaintenance.GetEntityInfo<TResult>().Columns;
				int num = 0;
				foreach (T include in includeList)
				{
					foreach (EntityColumnInfo column in columns)
					{
						if (column.Navigat == null)
						{
							continue;
						}
						object value = column.PropertyInfo.GetValue(include);
						EntityColumnInfo entityColumnInfo = columns2.FirstOrDefault((EntityColumnInfo z) => z.PropertyName.Equals(column.PropertyName) && z.PropertyInfo.PropertyType == column.PropertyInfo.PropertyType);
						if (entityColumnInfo == null && navMappingColumns.Any((NavMappingColumn z) => z.Value == column.PropertyName))
						{
							NavMappingColumn mappingColumn = navMappingColumns.First((NavMappingColumn z) => z.Value == column.PropertyName);
							entityColumnInfo = columns2.FirstOrDefault((EntityColumnInfo z) => z.PropertyName.Equals(mappingColumn.Key) && z.PropertyInfo.PropertyType == column.PropertyInfo.PropertyType);
						}
						if (entityColumnInfo != null)
						{
							TResult val = result[num];
							entityColumnInfo.PropertyInfo.SetValue(val, value);
						}
					}
					num++;
				}
			}

			private static bool IsClass<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				Expression lambdaExpressionBody = ExpressionTool.GetLambdaExpressionBody(expression);
				if (lambdaExpressionBody is NewExpression)
				{
					foreach (Expression argument in ((NewExpression)lambdaExpressionBody).Arguments)
					{
						if (argument is MemberExpression && ((MemberExpression)argument).Type.IsClass())
						{
							return true;
						}
					}
				}
				return false;
			}

			private static bool IsSqlFunc<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				Expression lambdaExpressionBody = ExpressionTool.GetLambdaExpressionBody(expression);
				if (lambdaExpressionBody is NewExpression)
				{
					foreach (Expression argument in ((NewExpression)lambdaExpressionBody).Arguments)
					{
						if (argument is MethodCallExpression)
						{
							MethodInfo method = ((MethodCallExpression)argument).Method;
							if (method.DeclaringType != null && method.DeclaringType.Name == "SqlFunc")
							{
								return true;
							}
						}
					}
				}
				if (lambdaExpressionBody is MemberInitExpression)
				{
					foreach (MemberAssignment binding in ((MemberInitExpression)lambdaExpressionBody).Bindings)
					{
						if (binding.Expression is MethodCallExpression)
						{
							MethodInfo method2 = ((MethodCallExpression)binding.Expression).Method;
							if (method2.DeclaringType != null && method2.DeclaringType.Name == "SqlFunc")
							{
								return true;
							}
						}
					}
				}
				return false;
			}

			private static List<NavMappingColumn> GetMappingColumn(Expression expression)
			{
				Expression lambdaExpressionBody = ExpressionTool.GetLambdaExpressionBody(expression);
				string name = (expression as LambdaExpression).Parameters.FirstOrDefault().Name;
				List<NavMappingColumn> list = new List<NavMappingColumn>();
				if (lambdaExpressionBody is NewExpression)
				{
					int num = 0;
					ReadOnlyCollection<Expression> arguments = ((NewExpression)lambdaExpressionBody).Arguments;
					ReadOnlyCollection<MemberInfo> members = ((NewExpression)lambdaExpressionBody).Members;
					foreach (Expression item in arguments)
					{
						_ = members[num].Name;
						if (item is MethodCallExpression)
						{
							AddCallError(list, item, name);
						}
						num++;
					}
				}
				else if (lambdaExpressionBody is MemberInitExpression)
				{
					foreach (MemberAssignment binding in ((MemberInitExpression)lambdaExpressionBody).Bindings)
					{
						string name2 = binding.Member.Name;
						_ = binding.Expression;
						if (binding.Expression is MemberExpression)
						{
							list.Add(new NavMappingColumn
							{
								Key = name2,
								Value = ExpressionTool.GetMemberName(binding.Expression)
							});
						}
						else if (binding.Expression is MethodCallExpression)
						{
							AddCallError(list, binding.Expression, name);
						}
					}
				}
				return list;
			}

			private static void AddCallError(List<NavMappingColumn> result, Expression item, string parameterName)
			{
				MethodCallExpression methodCallExpression = item as MethodCallExpression;
				if (methodCallExpression.Method.Name == "ToList" && methodCallExpression.Arguments.Count > 0 && methodCallExpression.Arguments[0] is MethodCallExpression)
				{
					methodCallExpression = (MethodCallExpression)methodCallExpression.Arguments[0];
				}
				if (methodCallExpression.Method.Name == "Select")
				{
					if (!item.ToString().Contains("Subqueryable"))
					{
						result.Add(new NavMappingColumn
						{
							IsError = true
						});
					}
				}
				else if (methodCallExpression.Method.Name == "Join" && item.ToString().Contains(" " + parameterName + "."))
				{
					result.Add(new NavMappingColumn
					{
						IsError = true
					});
				}
			}

			private static bool isGroup<T, TResult>(Expression<Func<T, TResult>> expression, QueryableProvider<T> queryableProvider)
			{
				return queryableProvider.QueryBuilder.GetGroupByString.HasValue();
			}
		}
