			public virtual ISugarQueryable<TResult> SelectMergeTable<TResult>(Expression<Func<T, T2, TResult>> expression)
			{
				return Select(expression).MergeTable();
			}

			public ISugarQueryable<T, T2, T3> LeftJoinIF<T3>(bool isLeftJoin, Expression<Func<T, T2, T3, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3> sugarQueryable = LeftJoin(joinExpression);
				if (!isLeftJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T, T2, T3> InnerJoinIF<T3>(bool isJoin, Expression<Func<T, T2, T3, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3> sugarQueryable = InnerJoin(joinExpression);
				if (!isJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T, T2, T3> LeftJoin<T3>(ISugarQueryable<T3> joinQueryable, Expression<Func<T, T2, T3, bool>> joinExpression)
			{
				base.Context.InitMappingInfo<T3>();
				ISugarQueryable<T, T2, T3> queryable = InstanceFactory.GetQueryable<T, T2, T3>(base.Context.CurrentConnectionConfig);
				queryable.SqlBuilder = base.SqlBuilder;
				queryable.Context = base.Context;
				JoinQueryInfo joinInfo = GetJoinInfo(joinExpression, JoinType.Left);
				KeyValuePair<string, List<SugarParameter>> keyValuePair = joinQueryable.ToSql();
				string appendSql = keyValuePair.Key;
				base.QueryBuilder.LambdaExpressions.ParameterIndex += 100;
				UtilMethods.RepairReplicationParameters(ref appendSql, keyValuePair.Value.ToArray(), base.QueryBuilder.LambdaExpressions.ParameterIndex, "");
				joinInfo.TableName = "(" + appendSql + ")";
				base.QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				queryable.QueryBuilder.JoinQueryInfos.Add(joinInfo);
				queryable.QueryBuilder.LambdaExpressions.ParameterIndex = base.QueryBuilder.LambdaExpressions.ParameterIndex;
				return queryable;
			}

			public ISugarQueryable<T, T2, T3> LeftJoinIF<T3>(bool isJoin, ISugarQueryable<T3> joinQueryable, Expression<Func<T, T2, T3, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3> sugarQueryable = LeftJoin(joinQueryable, joinExpression);
				if (!isJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

