					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T, T2, T3, T4, T5> RightJoinIF<T5>(bool isJoin, Expression<Func<T, T2, T3, T4, T5, bool>> joinExpression, string tableName)
			{
				ISugarQueryable<T, T2, T3, T4, T5> sugarQueryable = RightJoin(joinExpression);
				sugarQueryable.QueryBuilder.JoinQueryInfos.Last().TableName = tableName;
				if (!isJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

