			{
				base.QueryBuilder.JoinIndex = 1;
				base.QueryBuilder.JoinQueryInfos.Add(new JoinQueryInfo
				{
					JoinIndex = base.QueryBuilder.JoinIndex,
					TableName = tableName,
					ShortName = shortName,
					JoinType = type,
					JoinWhere = joinWhere
				});
				return this;
			}

