			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7> LeftJoinIF<T7>(bool isLeftJoin, Expression<Func<T, T2, T3, T4, T5, T6, T7, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7> sugarQueryable = LeftJoin(joinExpression);
				if (!isLeftJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7> InnerJoinIF<T7>(bool isJoin, Expression<Func<T, T2, T3, T4, T5, T6, T7, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7> sugarQueryable = InnerJoin(joinExpression);
				if (!isJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7> LeftJoin<T7>(ISugarQueryable<T7> joinQueryable, Expression<Func<T, T2, T3, T4, T5, T6, T7, bool>> joinExpression)
			{
				base.Context.InitMappingInfo<T7>();
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7> queryable = InstanceFactory.GetQueryable<T, T2, T3, T4, T5, T6, T7>(base.Context.CurrentConnectionConfig);
				queryable.SqlBuilder = base.SqlBuilder;
				queryable.Context = base.Context;
				JoinQueryInfo joinInfo = GetJoinInfo(joinExpression, JoinType.Left);
				KeyValuePair<string, List<SugarParameter>> keyValuePair = joinQueryable.ToSql();
				string appendSql = keyValuePair.Key;
				base.QueryBuilder.LambdaExpressions.ParameterIndex += 100;
				UtilMethods.RepairReplicationParameters(ref appendSql, keyValuePair.Value.ToArray(), base.QueryBuilder.LambdaExpressions.ParameterIndex, "");
				joinInfo.TableName = "(" + appendSql + ")";
				base.QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				queryable.QueryBuilder.JoinQueryInfos.Add(joinInfo);
				queryable.QueryBuilder.LambdaExpressions.ParameterIndex = base.QueryBuilder.LambdaExpressions.ParameterIndex;
				return queryable;
			}

