			public new ISugarQueryable<T, T2, T3, T4, T5, T6> In<FieldType>(Expression<Func<T, object>> expression, params FieldType[] inValues)
			{
				bool flag = base.QueryBuilder.IsSingle();
				string resultString = base.QueryBuilder.GetExpressionValue(expression, flag ? ResolveExpressType.FieldSingle : ResolveExpressType.FieldMultiple).GetResultString();
				In(resultString, inValues);
				return this;
			}

