			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9> LeftJoinIF<T9>(bool isLeftJoin, Expression<Func<T, T2, T3, T4, T5, T6, T7, T8, T9, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9> sugarQueryable = LeftJoin(joinExpression);
				if (!isLeftJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
