			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9> LeftJoin<T9>(ISugarQueryable<T9> joinQueryable, Expression<Func<T, T2, T3, T4, T5, T6, T7, T8, T9, bool>> joinExpression)
			{
				base.Context.InitMappingInfo<T9>();
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9> queryable = InstanceFactory.GetQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9>(base.Context.CurrentConnectionConfig);
				queryable.SqlBuilder = base.SqlBuilder;
				queryable.Context = base.Context;
				JoinQueryInfo joinInfo = GetJoinInfo(joinExpression, JoinType.Left);
				KeyValuePair<string, List<SugarParameter>> keyValuePair = joinQueryable.ToSql();
				string appendSql = keyValuePair.Key;
				base.QueryBuilder.LambdaExpressions.ParameterIndex += 100;
				UtilMethods.RepairReplicationParameters(ref appendSql, keyValuePair.Value.ToArray(), base.QueryBuilder.LambdaExpressions.ParameterIndex, "");
				joinInfo.TableName = "(" + appendSql + ")";
				base.QueryBuilder.Parameters.AddRange(keyValuePair.Value);
				queryable.QueryBuilder.JoinQueryInfos.Add(joinInfo);
				queryable.QueryBuilder.LambdaExpressions.ParameterIndex = base.QueryBuilder.LambdaExpressions.ParameterIndex;
				return queryable;
			}

