			public ISugarQueryable<TResult> Select<TResult>(Expression<Func<T, T2, T3, T4, T5, T6, T7, T8, TResult>> expression, bool isAutoFill)
			{
				ISugarQueryable<TResult> sugarQueryable = Select(expression).Clone();
				string text = sugarQueryable.QueryBuilder.GetSelectValue;
				if (base.QueryBuilder.IsSingle() || string.IsNullOrEmpty(text) || text.Trim() == "*")
				{
					text = " ";
				}
				UtilMethods.UpdateQueryBuilderByClone(base.QueryBuilder, sugarQueryable);
				base.QueryBuilder.Parameters = sugarQueryable.QueryBuilder.Parameters;
				base.QueryBuilder.SelectNewIgnoreColumns = sugarQueryable.QueryBuilder.SelectNewIgnoreColumns;
				base.QueryBuilder.SubToListParameters = sugarQueryable.QueryBuilder.SubToListParameters;
				base.QueryBuilder.LambdaExpressions.ParameterIndex = sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex;
				ReadOnlyCollection<ParameterExpression> parameters = expression.Parameters;
				List<EntityColumnInfo> columns = base.Context.EntityMaintenance.GetEntityInfo<TResult>().Columns;
				text = AppendSelect<T>(text, parameters, columns, 0);
				text = AppendSelect<T2>(text, parameters, columns, 1);
				text = AppendSelect<T3>(text, parameters, columns, 2);
				text = AppendSelect<T4>(text, parameters, columns, 3);
				text = AppendSelect<T5>(text, parameters, columns, 4);
				text = AppendSelect<T6>(text, parameters, columns, 5);
				text = AppendSelect<T7>(text, parameters, columns, 6);
				text = AppendSelect<T8>(text, parameters, columns, 7);
				if (text.Trim().First() == ',')
				{
					text = text.TrimStart(' ').TrimStart(',');
				}
				return Select<TResult>(text);
			}

