			public new ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9> AddJoinInfo(string tableName, string shortName, string joinWhere, JoinType type = JoinType.Left)
			{
				base.QueryBuilder.JoinIndex = 1;
				base.QueryBuilder.JoinQueryInfos.Add(new JoinQueryInfo
				{
					JoinIndex = base.QueryBuilder.JoinIndex,
					TableName = tableName,
					ShortName = shortName,
					JoinType = type,
					JoinWhere = joinWhere
				});
				return this;
			}

