			public ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11> LeftJoinIF<T11>(bool isLeftJoin, Expression<Func<T, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, bool>> joinExpression)
			{
				ISugarQueryable<T, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11> sugarQueryable = LeftJoin(joinExpression);
				if (!isLeftJoin)
				{
					sugarQueryable.QueryBuilder.JoinQueryInfos.Remove(sugarQueryable.QueryBuilder.JoinQueryInfos.Last());
				}
				return sugarQueryable;
			}

