				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo(EntityType);
				string viewName = string.Format(viewNameFomat, entityInfo.DbTableName);
				if (!Context.DbMaintenance.GetViewInfoList().Any((DbTableInfo it) => it.Name.EqualCase(viewName)))
