					string value = (string)QueryableObj.GetType().GetMyMethod("ToSqlString", 0).Invoke(QueryableObj, new object[0]);
					string sql = $"CREATE  VIEW  {viewName} AS {Environment.NewLine} {value}";
					Context.Ado.ExecuteCommand(sql);
					return true;
				}
				return false;
