		public class ReportableProvider<T> : IReportable<T>
		{
			private List<T> datas = new List<T>();

			private List<DateTime> dates = new List<DateTime>();

			private bool isDates;

			internal QueryBuilder queryBuilder;

			private bool _isOnlySelectEntity;

			public SqlSugarProvider Context { get; set; }

			internal InsertBuilder formatBuilder { get; set; }

			public string GetNextSql
			{
				get
				{
					string fullSqlDateNow = queryBuilder.Builder.FullSqlDateNow;
					if (fullSqlDateNow != null && fullSqlDateNow.ToLower()?.Contains(" dual") == true)
					{
						return " from dual ";
					}
					return null;
				}
			}

			public ReportableProvider(T data)
			{
				datas.Add(data);
				Init();
			}

			public ReportableProvider(List<T> list)
			{
				datas = list;
				Init();
			}

			public ISugarQueryable<T> ToQueryable()
			{
				StringBuilder stringBuilder = new StringBuilder();
				if (datas.Any())
				{
					if (isDates)
					{
						List<DateTime> list = dates;
						Each(stringBuilder, list);
					}
					else
					{
						List<T> list2 = datas;
						Each(stringBuilder, list2);
					}
				}
				else if (typeof(T).IsClass())
				{
					T val = (T)Activator.CreateInstance(typeof(T), nonPublic: true);
					datas.Add(val);
					ClassMethod(val, stringBuilder, isLast: true);
				}
				else
				{
					stringBuilder.Append("SELECT  NULL as ColumnName ");
					stringBuilder.Append(GetNextSql);
				}
				return Context.SqlQueryable<object>(stringBuilder.ToString()).Select<T>();
			}

			public ISugarQueryable<SingleColumnEntity<Y>> ToQueryable<Y>()
			{
				return ToQueryable().Select<SingleColumnEntity<Y>>();
			}

			public ISugarQueryable<SingleColumnEntity<Y>> ToQueryable<Y>(bool isOnlySelectEntity)
			{
				_isOnlySelectEntity = isOnlySelectEntity;
				return ToQueryable<Y>();
			}

			private void Each<Y>(StringBuilder sb, List<Y> list)
			{
				int num = 0;
				foreach (Y item in list)
				{
					num++;
					bool isLast = num == list.Count;
					if (typeof(T).IsClass())
					{
						ClassMethod(item, sb, isLast);
					}
					else
					{
						NoClassMethod(item, sb, isLast);
					}
				}
			}

			private void ClassMethod<Y>(Y data, StringBuilder sb, bool isLast)
			{
				StringBuilder stringBuilder = new StringBuilder();
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
				stringBuilder.Append(string.Join(",", from it in entityInfo.Columns
					where !it.IsIgnore
					select GetSelect(it, data)));
				if (!_isOnlySelectEntity)
				{
					stringBuilder.Append(",null as NoCacheColumn");
				}
				sb.AppendLine(" SELECT " + stringBuilder.ToString());
				sb.Append(GetNextSql);
				if (!isLast)
				{
					sb.AppendLine(" UNION ALL ");
				}
			}

			private object GetSelect<Y>(EntityColumnInfo it, Y data)
			{
				return $" {FormatValue(it.PropertyInfo.GetValue(data, null), it)} AS {queryBuilder.Builder.GetTranslationColumnName(it.PropertyName)} ";
			}

			private void NoClassMethod<Y>(Y data, StringBuilder sb, bool isLast)
			{
				sb.AppendLine(" SELECT " + FormatValue(data));
				sb.Append(" AS " + queryBuilder.Builder.GetTranslationColumnName("ColumnName") + " ");
				sb.Append(GetNextSql);
				if (!isLast)
				{
					sb.AppendLine(" UNION ALL ");
				}
			}

			private void Init()
			{
				if (datas.Count != 1)
				{
					return;
				}
				T val = datas.First();
				isDates = val is ReportableDateType;
				if (!(val is ReportableDateType))
				{
					return;
				}
				object obj = UtilMethods.ChangeType2(val, typeof(ReportableDateType));
				if (obj is ReportableDateType)
				{
					switch ((ReportableDateType)obj)
					{
					case ReportableDateType.MonthsInLast1years:
						dates.AddRange(GetMonths(1));
						break;
					case ReportableDateType.MonthsInLast3years:
						dates.AddRange(GetMonths(3));
						break;
					case ReportableDateType.MonthsInLast10years:
						dates.AddRange(GetMonths(10));
						break;
					case ReportableDateType.years1:
						dates.AddRange(GetYears(1));
						break;
					case ReportableDateType.years3:
						dates.AddRange(GetYears(3));
						break;
					case ReportableDateType.years10:
						dates.AddRange(GetYears(10));
						break;
					}
				}
			}

			private List<DateTime> GetYears(int v)
			{
				List<DateTime> list = new List<DateTime>();
				for (int i = 0; i < v; i++)
				{
					DateTime item = (DateTime.Now.AddYears(i * -1).Year + "-01-01").ObjToDate();
					list.Add(item);
				}
				return list;
			}

			private List<DateTime> GetMonths(int v)
			{
				List<DateTime> list = new List<DateTime>();
				foreach (DateTime year in GetYears(v))
				{
					for (int i = 0; i < 12; i++)
					{
						list.Add(year.AddMonths(i));
					}
				}
				return list;
			}

			private object FormatValue(object value, EntityColumnInfo entityColumnInfo = null)
			{
				if (entityColumnInfo != null && entityColumnInfo.UnderType == UtilConstants.DateType && value == null && Context.CurrentConnectionConfig.DbType == DbType.SqlServer)
				{
					return " CAST( NULL AS DATETIME) ";
				}
				if (entityColumnInfo != null && entityColumnInfo.IsJson && value != null)
				{
					return "'" + Context.Utilities.SerializeObject(value).ToSqlFilter() + "'";
				}
				if (value == null)
				{
					return "null";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType.IsIn(new Type[6]
				{
					typeof(int),
					typeof(uint),
					typeof(long),
					typeof(ulong),
					typeof(short),
					typeof(ushort)
				}))
				{
					return value;
				}
				if (underType.IsIn(new Type[2]
				{
					typeof(decimal),
					typeof(double)
				}))
				{
					_ = (Expression<Func<SingleColumnEntity<object>, object>>)((SingleColumnEntity<object> it) => Convert.ToDecimal(it.ColumnName));
					return queryBuilder.LambdaExpressions.DbMehtods.ToDecimal(new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs>
						{
							new MethodCallExpressionArgs
							{
								IsMember = true,
								MemberName = formatBuilder.FormatValue(value)
							}
						}
					});
				}
				if (underType.IsIn(new Type[1] { typeof(Guid) }))
				{
					_ = (Expression<Func<SingleColumnEntity<object>, object>>)((SingleColumnEntity<object> it) => Convert.ToDecimal(it.ColumnName));
					return queryBuilder.LambdaExpressions.DbMehtods.ToGuid(new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs>
						{
							new MethodCallExpressionArgs
							{
								IsMember = true,
								MemberName = formatBuilder.FormatValue(value)
							}
						}
					});
				}
				if (underType.IsIn(new Type[1] { typeof(DateTime) }) || underType.Name == "DateOnly")
				{
					if (Context.CurrentConnectionConfig.DbType == DbType.Oracle)
					{
						return queryBuilder.LambdaExpressions.DbMehtods.Oracle_ToDate(new MethodCallExpressionModel
						{
							Args = new List<MethodCallExpressionArgs>
							{
								new MethodCallExpressionArgs
								{
									IsMember = true,
									MemberName = value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss").ToSqlValue()
								},
								new MethodCallExpressionArgs
								{
									IsMember = true,
									MemberName = "yyyy-mm-dd hh24:mi:ss".ToSqlValue()
								}
							}
						});
					}
					return queryBuilder.LambdaExpressions.DbMehtods.ToDate(new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs>
						{
							new MethodCallExpressionArgs
							{
								IsMember = true,
								MemberName = formatBuilder.FormatValue(UtilMethods.DateOnlyToDateTime(value))
							}
						}
					});
				}
				return formatBuilder.FormatValue(value);
			}
		}
		public class SaveableProvider<T> : ISaveable<T> where T : class, new()
		{
			public List<T> saveObjects = new List<T>();

			public List<T> existsObjects;

			public SqlSugarProvider Context { get; set; }

			public List<T> insertObjects
			{
				get
				{
					bool isDisableMasterSlaveSeparation = Context.Ado.IsDisableMasterSlaveSeparation;
					Context.Ado.IsDisableMasterSlaveSeparation = true;
					new List<T>();
					List<string> pks = GetPrimaryKeys();
					Check.Exception(pks.IsNullOrEmpty(), "Need primary key");
					Check.Exception(pks.Count() > 1, "Multiple primary keys are not supported");
					EntityColumnInfo pkInfo = (from it in EntityInfo.Columns
						where !it.IsIgnore
						where it.DbColumnName.Equals(pks.First(), StringComparison.CurrentCultureIgnoreCase)
						select it).First();
					IEnumerable<object> enumerable = saveObjects.Select((T it) => it.GetType().GetProperty(pkInfo.PropertyName).GetValue(it, null));
					if (existsObjects == null)
					{
						existsObjects = Context.Queryable<T>().In<IEnumerable<object>>(enumerable).ToList();
					}
					Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
					return saveObjects.Where((T it) => !existsObjects.Any((T e) => e.GetType().GetProperty(pkInfo.PropertyName).GetValue(e, null)
						.ObjToString() == it.GetType().GetProperty(pkInfo.PropertyName).GetValue(it, null)
						.ObjToString())).ToList();
				}
			}

			public List<T> updatObjects
			{
				get
				{
					bool isDisableMasterSlaveSeparation = Context.Ado.IsDisableMasterSlaveSeparation;
					Context.Ado.IsDisableMasterSlaveSeparation = true;
					new List<T>();
					List<string> pks = GetPrimaryKeys();
					Check.Exception(pks.IsNullOrEmpty(), "Need primary key");
					Check.Exception(pks.Count() > 1, "Multiple primary keys are not supported");
					EntityColumnInfo pkInfo = (from it in EntityInfo.Columns
						where !it.IsIgnore
						where it.DbColumnName.Equals(pks.First(), StringComparison.CurrentCultureIgnoreCase)
						select it).First();
					IEnumerable<object> enumerable = saveObjects.Select((T it) => it.GetType().GetProperty(pkInfo.PropertyName).GetValue(it, null));
					if (existsObjects == null)
					{
						existsObjects = Context.Queryable<T>().In<IEnumerable<object>>(enumerable).ToList();
					}
					Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
					return saveObjects.Where((T it) => existsObjects.Any((T e) => e.GetType().GetProperty(pkInfo.PropertyName).GetValue(e, null)
						.ObjToString() == it.GetType().GetProperty(pkInfo.PropertyName).GetValue(it, null)
						.ObjToString())).ToList();
				}
			}

			public IInsertable<T> insertable { get; set; }

