		public class Storageable<T> : IStorageable<T> where T : class, new()
		{
			internal ISqlBuilder Builder;

			private List<SugarParameter> Parameters;

			private List<StorageableInfo<T>> allDatas = new List<StorageableInfo<T>>();

			private List<T> dbDataList = new List<T>();

			private List<KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>> whereFuncs = new List<KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>>();

			private Expression<Func<T, object>> whereExpression;

			private Func<DateTime, string> formatTime;

			private DbLockType? lockType;

			private bool isDisableFilters;

			private Expression<Func<T, bool>> queryableWhereExp;

			private List<EntityColumnInfo> wherecolumnList;

			private SqlSugarProvider Context { get; set; }

			private string asname { get; set; }

			public Storageable(List<T> datas, SqlSugarProvider context)
			{
				Context = context;
				if (datas == null)
				{
					datas = new List<T>();
				}
				allDatas = datas.Select((T it) => new StorageableInfo<T>
				{
					Item = it
				}).ToList();
			}

			public IStorageable<T> TableDataRange(Expression<Func<T, bool>> exp)
			{
				queryableWhereExp = exp;
				return this;
			}

			public IStorageable<T> SplitInsert(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Insert, conditions, message));
				return this;
			}

			public IStorageable<T> SplitDelete(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Delete, conditions, message));
				return this;
			}

			public IStorageable<T> SplitUpdate(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Update, conditions, message));
				return this;
			}

			public IStorageable<T> Saveable(string inserMessage = null, string updateMessage = null)
			{
				return SplitUpdate((StorageableInfo<T> it) => it.Any(), updateMessage).SplitInsert((StorageableInfo<T> it) => true, inserMessage);
			}

			public IStorageable<T> SplitError(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Error, conditions, message));
				return this;
			}

			public IStorageable<T> SplitIgnore(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Ignore, conditions, message));
				return this;
			}

			public IStorageable<T> DisableFilters()
			{
				isDisableFilters = true;
				return this;
			}

			public IStorageable<T> TranLock(DbLockType dbLockType = DbLockType.Wait)
			{
				lockType = dbLockType;
				return this;
			}

			public IStorageable<T> TranLock(DbLockType? LockType)
			{
				if (LockType.HasValue)
				{
					lockType = LockType;
					return this;
				}
				return this;
			}

			public IStorageable<T> SplitOther(Func<StorageableInfo<T>, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>(StorageType.Other, conditions, message));
				return this;
			}

			public StorageablePage<T> PageSize(int PageSize, Action<int> ActionCallBack = null)
			{
				if (PageSize > 10000)
				{
					Check.ExceptionEasy("Advanced save page Settings should not exceed 10,000, and the reasonable number of pages is about 2000", "高级保存分页设置不要超过1万，合理分页数在2000左右");
				}
				return new StorageablePage<T>
				{
					Context = Context,
					PageSize = PageSize,
					Data = allDatas.Select((StorageableInfo<T> it) => it.Item).ToList(),
					ActionCallBack = ActionCallBack,
					TableName = asname,
					whereExpression = whereExpression,
					lockType = lockType
				};
			}

			public StorageableSplitProvider<T> SplitTable()
			{
				return new StorageableSplitProvider<T>
				{
					Context = Context,
					SaveInfo = this,
					List = allDatas.Select((StorageableInfo<T> it) => it.Item).ToList(),
					EntityInfo = Context.EntityMaintenance.GetEntityInfoWithAttr(typeof(T)),
					whereExpression = whereExpression
				};
			}

			public IStorageable<T> DefaultAddElseUpdate()
			{
				EntityColumnInfo column = Context.EntityMaintenance.GetEntityInfo<T>().Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (column == null)
				{
					Check.ExceptionEasy("DefaultAddElseUpdate() need primary key", "DefaultAddElseUpdate()这个方法只能用于主键");
				}
				return SplitUpdate(delegate(StorageableInfo<T> it)
				{
					object value = column.PropertyInfo.GetValue(it.Item);
					object defaultValue = UtilMethods.GetDefaultValue(column.PropertyInfo.PropertyType);
					return value != null && value.ObjToString() != defaultValue.ObjToString();
				}).SplitInsert((StorageableInfo<T> it) => true);
			}

			public int ExecuteCommand()
			{
				StorageableResult<T> storageableResult = ToStorage();
				int num = 0 + storageableResult.AsInsertable.ExecuteCommand();
				int num2 = storageableResult.AsUpdateable.ExecuteCommand();
				if (num2 < 0)
				{
					num2 = 0;
				}
				return num + num2;
			}

			public T ExecuteReturnEntity()
			{
				StorageableResult<T> storageableResult = ToStorage();
				List<StorageableMessage<T>> insertList = storageableResult.InsertList;
				if (insertList != null && insertList.Any())
				{
					T result = storageableResult.AsInsertable.ExecuteReturnEntity();
					storageableResult.AsUpdateable.ExecuteCommand();
					return result;
				}
				storageableResult.AsInsertable.ExecuteCommand();
				storageableResult.AsUpdateable.ExecuteCommand();
				StorageableMessage<T>? storageableMessage = storageableResult.UpdateList.FirstOrDefault();
				if (storageableMessage == null)
				{
					return null;
				}
				return storageableMessage.Item;
			}

			public async Task<T> ExecuteReturnEntityAsync()
			{
				StorageableResult<T> x = ToStorage();
				if (x.InsertList.Any())
				{
					T data = await x.AsInsertable.ExecuteReturnEntityAsync();
					await x.AsUpdateable.ExecuteCommandAsync();
					return data;
				}
				await x.AsInsertable.ExecuteCommandAsync();
				await x.AsUpdateable.ExecuteCommandAsync();
				StorageableMessage<T>? storageableMessage = x.UpdateList.FirstOrDefault();
				return (storageableMessage != null) ? storageableMessage.Item : null;
			}

			public Task<int> ExecuteCommandAsync(CancellationToken cancellationToken)
			{
				Context.Ado.CancellationToken = cancellationToken;
				return ExecuteCommandAsync();
			}

			public async Task<int> ExecuteCommandAsync()
			{
				int result = 0;
				StorageableResult<T> x = await ToStorageAsync();
				int num = result;
				result = num + await x.AsInsertable.ExecuteCommandAsync();
				int num2 = await x.AsUpdateable.ExecuteCommandAsync();
				if (num2 < 0)
				{
					num2 = 0;
				}
				return result + num2;
			}

			public int ExecuteSqlBulkCopy()
			{
				StorageableResult<T> storageableResult = ToStorage();
				return storageableResult.BulkCopy() + storageableResult.BulkUpdate();
			}

			public async Task<int> ExecuteSqlBulkCopyAsync()
			{
				StorageableResult<T> storage = await ToStorageAsync();
				return await storage.BulkCopyAsync() + await storage.BulkUpdateAsync();
			}

			public StorageableResult<T> ToStorage()
			{
				if (whereFuncs == null || whereFuncs.Count == 0)
				{
					return Saveable().ToStorage();
				}
				if (allDatas.Count == 0)
				{
					StorageableResult<T> storageableResult = new StorageableResult<T>();
					storageableResult.AsDeleteable = from it in Context.Deleteable<T>().AS(asname)
						where false
						select it;
					storageableResult.AsInsertable = Context.Insertable(new List<T>()).AS(asname);
					storageableResult.AsUpdateable = Context.Updateable(new List<T>()).AS(asname);
					storageableResult.InsertList = new List<StorageableMessage<T>>();
					storageableResult.UpdateList = new List<StorageableMessage<T>>();
					storageableResult.DeleteList = new List<StorageableMessage<T>>();
					storageableResult.ErrorList = new List<StorageableMessage<T>>();
					storageableResult.IgnoreList = new List<StorageableMessage<T>>();
					storageableResult.OtherList = new List<StorageableMessage<T>>();
					storageableResult.TotalList = new List<StorageableMessage<T>>();
					return storageableResult;
				}
				IEnumerable<EntityColumnInfo> enumerable = Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => it.IsPrimarykey);
				if (whereExpression == null && !enumerable.Any())
				{
					Check.ExceptionEasy(isException: true, "Need primary key or WhereColumn", "使用Storageable实体需要主键或者使用WhereColumn指定条件列");
				}
				if (whereExpression == null && enumerable.Any())
				{
					Context.Utilities.PageEach(allDatas, 300, delegate(List<StorageableInfo<T>> item)
					{
						List<T> collection = Context.Queryable<T>().Filter(null, isDisableFilters).TranLock(lockType)
							.AS(asname)
							.WhereClassByPrimaryKey(item.Select((StorageableInfo<T> it) => it.Item).ToList())
							.ToList();
						dbDataList.AddRange(collection);
					});
				}
				string[] pkProperties = GetPkProperties(enumerable);
				List<StorageableMessage<T>> list = allDatas.Select((StorageableInfo<T> it) => new StorageableMessage<T>
				{
					Item = it.Item,
					Database = dbDataList,
					PkFields = pkProperties
				}).ToList();
				foreach (KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string> item in whereFuncs.OrderByDescending<KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>, int>((KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string> it) => (int)it.key))
				{
					List<StorageableMessage<T>> source = list.Where((StorageableMessage<T> it) => !it.StorageType.HasValue).ToList();
					Func<StorageableMessage<T>, bool> value = item.value1;
					foreach (StorageableMessage<T> item2 in source.Where(value).ToList())
					{
						item2.StorageType = item.key;
						item2.StorageMessage = item.value2;
					}
				}
				List<StorageableMessage<T>> list2 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Delete).ToList();
				List<StorageableMessage<T>> list3 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Update).ToList();
				List<StorageableMessage<T>> list4 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Insert).ToList();
				List<StorageableMessage<T>> errorList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Error).ToList();
				List<StorageableMessage<T>> ignoreList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Ignore || !it.StorageType.HasValue).ToList();
				List<StorageableMessage<T>> otherList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Other).ToList();
				StorageableResult<T> storageableResult2 = new StorageableResult<T>
				{
					_WhereColumnList = wherecolumnList,
					_AsName = asname,
					_Context = Context,
					AsDeleteable = Context.Deleteable<T>().AS(asname),
					AsUpdateable = Context.Updateable(list3.Select((StorageableMessage<T> it) => it.Item).ToList()).AS(asname),
					AsInsertable = Context.Insertable(list4.Select((StorageableMessage<T> it) => it.Item).ToList()).AS(asname),
					OtherList = otherList,
					InsertList = list4,
					DeleteList = list2,
					UpdateList = list3,
					ErrorList = errorList,
					IgnoreList = ignoreList,
					TotalList = list
				};
				if (whereExpression != null)
				{
					storageableResult2.AsUpdateable.WhereColumns(whereExpression);
					storageableResult2.AsDeleteable.WhereColumns(list3.Select((StorageableMessage<T> it) => it.Item).ToList(), whereExpression);
				}
				if (whereExpression != null)
				{
					storageableResult2.AsDeleteable.WhereColumns(list2.Select((StorageableMessage<T> it) => it.Item).ToList(), whereExpression);
				}
				else
				{
					storageableResult2.AsDeleteable.Where(list2.Select((StorageableMessage<T> it) => it.Item).ToList());
				}
				return storageableResult2;
			}

			public StorageableResult<T> GetStorageableResult()
			{
