			public async Task<StorageableResult<T>> ToStorageAsync()
			{
				if (whereFuncs == null || whereFuncs.Count == 0)
				{
					return await Saveable().ToStorageAsync();
				}
				if (allDatas.Count == 0)
				{
					StorageableResult<T> storageableResult = new StorageableResult<T>();
					storageableResult.AsDeleteable = from it in Context.Deleteable<T>().AS(asname)
						where false
						select it;
					storageableResult.AsInsertable = Context.Insertable(new List<T>()).AS(asname);
					storageableResult.AsUpdateable = Context.Updateable(new List<T>()).AS(asname);
					storageableResult.InsertList = new List<StorageableMessage<T>>();
					storageableResult.UpdateList = new List<StorageableMessage<T>>();
					storageableResult.DeleteList = new List<StorageableMessage<T>>();
					storageableResult.ErrorList = new List<StorageableMessage<T>>();
					storageableResult.IgnoreList = new List<StorageableMessage<T>>();
					storageableResult.OtherList = new List<StorageableMessage<T>>();
					storageableResult.TotalList = new List<StorageableMessage<T>>();
					return storageableResult;
				}
				IEnumerable<EntityColumnInfo> pkInfos = Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => it.IsPrimarykey);
				if (whereExpression == null && !pkInfos.Any())
				{
					Check.Exception(true, "Need primary key or WhereColumn");
				}
				if (whereExpression == null && pkInfos.Any())
				{
					await Context.Utilities.PageEachAsync(allDatas, 300, async delegate(List<StorageableInfo<T>> item)
					{
						List<T> collection = await Context.Queryable<T>().Filter(null, isDisableFilters).AS(asname)
							.TranLock(lockType)
							.WhereClassByPrimaryKey(item.Select((StorageableInfo<T> it) => it.Item).ToList())
							.ToListAsync();
						dbDataList.AddRange(collection);
					});
				}
				string[] pkProperties = GetPkProperties(pkInfos);
				List<StorageableMessage<T>> list = allDatas.Select((StorageableInfo<T> it) => new StorageableMessage<T>
				{
					Item = it.Item,
					Database = dbDataList,
					PkFields = pkProperties
				}).ToList();
				foreach (KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string> item in whereFuncs.OrderByDescending<KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string>, int>((KeyValuePair<StorageType, Func<StorageableInfo<T>, bool>, string> it) => (int)it.key))
				{
					List<StorageableMessage<T>> source = list.Where((StorageableMessage<T> it) => !it.StorageType.HasValue).ToList();
					Func<StorageableMessage<T>, bool> value = item.value1;
					foreach (StorageableMessage<T> item2 in source.Where(value).ToList())
					{
						item2.StorageType = item.key;
						item2.StorageMessage = item.value2;
					}
				}
				List<StorageableMessage<T>> list2 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Delete).ToList();
				List<StorageableMessage<T>> list3 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Update).ToList();
				List<StorageableMessage<T>> list4 = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Insert).ToList();
				List<StorageableMessage<T>> errorList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Error).ToList();
				List<StorageableMessage<T>> ignoreList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Ignore || !it.StorageType.HasValue).ToList();
				List<StorageableMessage<T>> otherList = list.Where((StorageableMessage<T> it) => it.StorageType == StorageType.Other).ToList();
				StorageableResult<T> storageableResult2 = new StorageableResult<T>
				{
					_WhereColumnList = wherecolumnList,
					_AsName = asname,
					_Context = Context,
					AsDeleteable = Context.Deleteable<T>().AS(asname),
					AsUpdateable = Context.Updateable(list3.Select((StorageableMessage<T> it) => it.Item).ToList()).AS(asname),
					AsInsertable = Context.Insertable(list4.Select((StorageableMessage<T> it) => it.Item).ToList()).AS(asname),
					OtherList = otherList,
					InsertList = list4,
					DeleteList = list2,
					UpdateList = list3,
					ErrorList = errorList,
					IgnoreList = ignoreList,
					TotalList = list
				};
				if (whereExpression != null)
				{
					storageableResult2.AsUpdateable.WhereColumns(whereExpression);
					storageableResult2.AsDeleteable.WhereColumns(list2.Select((StorageableMessage<T> it) => it.Item).ToList(), whereExpression);
				}
				storageableResult2.AsDeleteable.Where(list2.Select((StorageableMessage<T> it) => it.Item).ToList());
				return storageableResult2;
			}

			private string[] GetPkProperties(IEnumerable<EntityColumnInfo> pkInfos)
			{
				if (whereExpression == null)
				{
					return pkInfos.Select((EntityColumnInfo it) => it.PropertyName).ToArray();
				}
				return wherecolumnList.Select((EntityColumnInfo it) => it.PropertyName).ToArray();
			}

			public IStorageable<T> WhereColumns(Expression<Func<T, object>> columns, Func<DateTime, string> formatTime)
			{
				this.formatTime = formatTime;
				return WhereColumns(columns);
			}

			public IStorageable<T> WhereColumns(Expression<Func<T, object>> columns)
			{
				if (columns == null)
				{
					return this;
				}
				if (asname == null && typeof(T).GetCustomAttribute<SplitTableAttribute>() != null)
				{
					whereExpression = columns;
					return this;
				}
				List<string> list = (from it in GetExpressionValue(columns, ResolveExpressType.ArraySingle).GetResultArray()
					select Builder.GetNoTranslationColumnName(it)).ToList();
				IEnumerable<EntityColumnInfo> source = Context.EntityMaintenance.GetEntityInfo<T>().Columns.Where((EntityColumnInfo it) => !it.IsIgnore);
				List<EntityColumnInfo> whereColumns = source.Where((EntityColumnInfo it) => list.Any((string y) => it.DbColumnName.Equals(y, StringComparison.CurrentCultureIgnoreCase) || it.PropertyName.Equals(y, StringComparison.CurrentCultureIgnoreCase))).ToList();
				wherecolumnList = whereColumns;
				if (whereColumns.Count == 0)
				{
					whereColumns = source.Where((EntityColumnInfo it) => it.IsPrimarykey).ToList();
				}
				if (whereColumns.Count > 0)
				{
					if (queryableWhereExp == null)
					{
						Context.Utilities.PageEach(allDatas, 200, delegate(List<StorageableInfo<T>> itemList)
						{
							List<IConditionalModel> list2 = new List<IConditionalModel>();
							SetConditList(itemList, whereColumns, list2);
							List<T> collection = Context.Queryable<T>().AS(asname).Filter(null, isDisableFilters)
								.TranLock(lockType)
								.Where(list2, isWrap: true)
								.ToList();
							dbDataList.AddRange(collection);
						});
					}
					else
					{
						dbDataList.AddRange(Context.Queryable<T>().AS(asname).Where(queryableWhereExp)
							.ToList());
					}
				}
				whereExpression = columns;
				return this;
			}

			public IStorageable<T> WhereColumns(string[] columns)
			{
				List<string> propertyNames = columns.Select((string it) => Context.EntityMaintenance.GetPropertyName<T>(it)).ToList();
				Expression<Func<T, object>> columns2 = ExpressionBuilderHelper.CreateNewFields<T>(Context.EntityMaintenance.GetEntityInfo<T>(), propertyNames);
				return WhereColumns(columns2);
			}

			public IStorageable<T> WhereColumns(string[] columns, Func<DateTime, string> formatTime)
			{
				this.formatTime = formatTime;
				return WhereColumns(columns);
			}

			private void SetConditList(List<StorageableInfo<T>> itemList, List<EntityColumnInfo> whereColumns, List<IConditionalModel> conditList)
			{
				foreach (StorageableInfo<T> item in itemList)
				{
					ConditionalCollections conditionalCollections = new ConditionalCollections
					{
						ConditionalList = new List<KeyValuePair<WhereType, ConditionalModel>>()
					};
					conditList.Add(conditionalCollections);
					int num = 0;
					foreach (EntityColumnInfo whereColumn in whereColumns)
					{
						object obj = whereColumn.PropertyInfo.GetValue(item.Item, null);
						if (obj is string text && text == "null")
						{
							obj = "[null]";
						}
						if (obj != null && obj.GetType().IsEnum())
						{
							ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
							obj = ((moreSettings == null || moreSettings.TableEnumIsString != true) ? ((object)Convert.ToInt64(obj)) : obj.ToString());
						}
						if (whereColumn.SqlParameterDbType != null && whereColumn.SqlParameterDbType is Type && UtilMethods.HasInterface((Type)whereColumn.SqlParameterDbType, typeof(ISugarDataConverter)))
						{
							EntityColumnInfo entityColumnInfo = whereColumn;
							Type type = entityColumnInfo.SqlParameterDbType as Type;
							MethodInfo methodInfo = type.GetMethod("ParameterConverter").MakeGenericMethod(entityColumnInfo.PropertyInfo.PropertyType);
							object obj2 = Activator.CreateInstance(type);
							obj = (methodInfo.Invoke(obj2, new object[2] { obj, 100 }) as SugarParameter).Value;
						}
						string cSharpTypeName = UtilMethods.GetTypeName(obj);
						if (whereColumn.SqlParameterDbType is System.Data.DbType dbType)
						{
							switch (dbType)
							{
							case System.Data.DbType.AnsiStringFixedLength:
								cSharpTypeName = "char";
								break;
							case System.Data.DbType.StringFixedLength:
								cSharpTypeName = "nchar";
								break;
							}
						}
						conditionalCollections.ConditionalList.Add(new KeyValuePair<WhereType, ConditionalModel>((num == 0) ? WhereType.Or : WhereType.And, new ConditionalModel
						{
							FieldName = whereColumn.DbColumnName,
							ConditionalType = ConditionalType.Equal,
							CSharpTypeName = cSharpTypeName,
							FieldValue = ((obj == null) ? "null" : obj.ObjToString(formatTime)),
							FieldValueConvertFunc = null
						}));
						num++;
					}
				}
			}

			public virtual ExpressionResult GetExpressionValue(Expression expression, ResolveExpressType resolveType)
			{
				ILambdaExpressions resolveExpress = InstanceFactory.GetLambdaExpressions(Context.CurrentConnectionConfig);
				if (Context.CurrentConnectionConfig.MoreSettings != null)
				{
					resolveExpress.TableEnumIsString = Context.CurrentConnectionConfig.MoreSettings.TableEnumIsString;
					resolveExpress.PgSqlIsAutoToLower = Context.CurrentConnectionConfig.MoreSettings.PgSqlIsAutoToLower;
				}
				else
				{
					resolveExpress.PgSqlIsAutoToLower = true;
				}
				resolveExpress.Context = Context;
				resolveExpress.SugarContext = new ExpressionOutParameter
				{
					Context = Context
				};
				resolveExpress.MappingColumns = Context.MappingColumns;
				resolveExpress.MappingTables = Context.MappingTables;
				resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
				resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				resolveExpress.InitMappingInfo = Context.InitMappingInfo;
				resolveExpress.RefreshMapping = delegate
				{
					resolveExpress.MappingColumns = Context.MappingColumns;
					resolveExpress.MappingTables = Context.MappingTables;
					resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
					resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				};
				resolveExpress.Resolve(expression, resolveType);
				if (Parameters == null)
				{
					Parameters = new List<SugarParameter>();
				}
				Parameters.AddRange(resolveExpress.Parameters);
				return resolveExpress.Result;
			}

			public IStorageable<T> As(string tableName)
			{
				asname = tableName;
				return this;
			}
		}
		public class StorageableDataTable
		{
			internal string SugarGroupId = "SugarGroupId";

			internal string SugarUpdateRows = "SugarUpdateRows";

			internal string SugarColumns = "SugarColumns";

			internal string SugarErrorMessage = "SugarErrorMessage";

			internal List<DataRow> dbDataList = new List<DataRow>();

			internal Func<DateTime, string> formatTime;

			private List<KeyValuePair<StorageType, Func<DataRow, bool>, string>> whereFuncs = new List<KeyValuePair<StorageType, Func<DataRow, bool>, string>>();

			internal DataTable DataTable { get; set; }

			internal SqlSugarProvider Context { get; set; }

			internal string[] Columns { get; set; } = new string[0];

			public StorageableDataTable WhereColumns(string name)
			{
				return WhereColumns(new string[1] { name });
			}

			public StorageableDataTable WhereColumns(string name, Func<DateTime, string> formatTime)
			{
				this.formatTime = formatTime;
				return WhereColumns(new string[1] { name });
			}

			public StorageableDataTable WhereColumns(string[] names, Func<DateTime, string> formatTime)
			{
				this.formatTime = formatTime;
				return WhereColumns(names);
			}

			public StorageableDataTable WhereColumns(string[] names)
			{
				Columns = names;
				ISugarQueryable<object> queryable = Context.Queryable<object>();
				Check.Exception(Columns == null || Columns.Length == 0, "need WhereColums");
				string tableName = queryable.SqlBuilder.GetTranslationTableName(DataTable.TableName);
				Context.Utilities.PageEach(DataTable.Rows.Cast<DataRow>(), 200, delegate(List<DataRow> itemList)
				{
					List<IConditionalModel> list = new List<IConditionalModel>();
					SetConditList(itemList, Columns, list);
					string text = null;
					if (queryable.SqlBuilder.SqlParameterKeyWord == ":")
					{
						text = " * /*" + Guid.NewGuid().ToString() + "*/";
					}
					List<DataRow> collection = Context.Queryable<object>().AS(tableName).Where(list)
						.Select(text)
						.ToDataTable()
						.Rows.Cast<DataRow>().ToList();
					dbDataList.AddRange(collection);
				});
				return this;
			}

			public StorageableDataTable WhereColumns(List<string> names)
			{
				return WhereColumns(names.ToArray());
			}

			public StorageableDataTable SplitInsert(Func<DataRow, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<DataRow, bool>, string>(StorageType.Insert, conditions, message));
				return this;
			}

			public StorageableDataTable SplitDelete(Func<DataRow, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<DataRow, bool>, string>(StorageType.Delete, conditions, message));
				return this;
			}

			public StorageableDataTable SplitUpdate(Func<DataRow, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<DataRow, bool>, string>(StorageType.Update, conditions, message));
				return this;
			}

			public StorageableDataTable Saveable(string inserMessage = null, string updateMessage = null)
			{
				SplitUpdate((DataRow it) => it.Any(), updateMessage);
				SplitInsert((DataRow it) => true, inserMessage);
				return this;
			}

			public StorageableDataTable SplitError(Func<DataRow, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<DataRow, bool>, string>(StorageType.Error, conditions, message));
				return this;
			}

			public StorageableDataTable SplitIgnore(Func<DataRow, bool> conditions, string message = null)
			{
				whereFuncs.Add(new KeyValuePair<StorageType, Func<DataRow, bool>, string>(StorageType.Ignore, conditions, message));
				return this;
			}

			public DataTableResult ToStorage()
			{
				if (whereFuncs == null || whereFuncs.Count == 0)
				{
					Saveable();
				}
				foreach (DataRow row in DataTable.Rows)
				{
					foreach (KeyValuePair<StorageType, Func<DataRow, bool>, string> item in whereFuncs.OrderByDescending<KeyValuePair<StorageType, Func<DataRow, bool>, string>, int>((KeyValuePair<StorageType, Func<DataRow, bool>, string> it) => (int)it.key))
					{
						SplitMethod(item.value1, item.key, row, item.value2);
					}
					if (row[SugarGroupId] == null || row[SugarGroupId] == DBNull.Value)
					{
						row[SugarGroupId] = StorageType.Ignore;
					}
				}
				DataTable.Columns.Remove(SugarUpdateRows);
				DataTable.Columns.Remove(SugarColumns);
				List<DataTableGroups> list = (from DataRow it in DataTable.Rows
					where it[SugarGroupId] != null && it[SugarGroupId] != DBNull.Value
					group it by ((StorageType)it[SugarGroupId]/*cast due to constrained. prefix*/).ToString() into it
					select new DataTableGroups
					{
						Type = it.Key,
						DataTable = it.CopyToDataTable()
					}).ToList();
				DataTable.Columns.Remove(SugarGroupId);
				DataTable.Columns.Remove(SugarErrorMessage);
				List<Dictionary<string, object>> list2 = new List<Dictionary<string, object>>();
				List<Dictionary<string, object>> list3 = new List<Dictionary<string, object>>();
				DataTableGroups dataTableGroups = list.FirstOrDefault((DataTableGroups it) => it.Type == StorageType.Delete.ToString());
				if (list.Any((DataTableGroups it) => it.Type == StorageType.Insert.ToString()))
				{
					foreach (DataTableGroups item2 in list)
					{
						if (item2.Type == StorageType.Insert.ToString())
						{
							item2.DataTable.Columns.Remove(SugarGroupId);
							item2.DataTable.Columns.Remove(SugarErrorMessage);
							list2.AddRange(Context.Utilities.DataTableToDictionaryList(item2.DataTable));
						}
					}
				}
				if (list.Any((DataTableGroups it) => it.Type == StorageType.Update.ToString()))
				{
					foreach (DataTableGroups item3 in list)
					{
						if (item3.Type == StorageType.Update.ToString())
						{
							item3.DataTable.Columns.Remove(SugarGroupId);
							item3.DataTable.Columns.Remove(SugarErrorMessage);
							list3.AddRange(Context.Utilities.DataTableToDictionaryList(item3.DataTable));
						}
					}
				}
				List<IConditionalModel> list4 = new List<IConditionalModel>();
				if (dataTableGroups != null)
				{
					SetConditList(dataTableGroups.DataTable.Rows.Cast<DataRow>().ToList(), Columns, list4);
				}
				string translationTableName = Context.Queryable<object>().SqlBuilder.GetTranslationTableName(DataTable.TableName);
				return new DataTableResult
				{
					DataTableGroups = list,
					AsDeleteable = Context.Deleteable<object>().AS(translationTableName).Where(list4),
					AsUpdateable = Context.Updateable(list3).AS(translationTableName).WhereColumns(Columns),
					AsInsertable = Context.Insertable(list2).AS(translationTableName)
				};
			}

			private void SplitMethod(Func<DataRow, bool> conditions, StorageType type, DataRow item, string message)
			{
				item[SugarColumns] = Columns;
				item[SugarUpdateRows] = dbDataList;
				if ((item[SugarGroupId] == null || item[SugarGroupId] == DBNull.Value) && conditions(item))
				{
					item[SugarGroupId] = type;
					item[SugarErrorMessage] = message;
				}
			}

			private void SetConditList(List<DataRow> itemList, string[] whereColumns, List<IConditionalModel> conditList)
			{
				foreach (DataRow item in itemList)
				{
					ConditionalCollections conditionalCollections = new ConditionalCollections
					{
						ConditionalList = new List<KeyValuePair<WhereType, ConditionalModel>>()
					};
					conditList.Add(conditionalCollections);
					int num = 0;
					foreach (string text in whereColumns)
					{
						object obj = item[text];
						if (obj != null && obj.GetType().IsEnum())
						{
							obj = Convert.ToInt64(obj);
						}
						conditionalCollections.ConditionalList.Add(new KeyValuePair<WhereType, ConditionalModel>((num == 0) ? WhereType.Or : WhereType.And, new ConditionalModel
						{
							FieldName = text,
							ConditionalType = ConditionalType.Equal,
							FieldValue = obj.ObjToString(formatTime),
							CSharpTypeName = obj?.GetType()?.Name
						}));
						num++;
					}
				}
			}
		}
		public class DataTableResult
		{
			public List<DataTableGroups> DataTableGroups { get; set; }

			public IUpdateable<Dictionary<string, object>> AsUpdateable { get; set; }

			public IDeleteable<object> AsDeleteable { get; set; }

			public IInsertable<Dictionary<string, object>> AsInsertable { get; set; }
		}
		public class DataTableGroups
		{
			public string Type { get; set; }

			public DataTable DataTable { get; set; }
		}
		public static class StorageableDataTableExtensions
		{
			public static bool Any(this DataRow row)
			{
				List<DataRow> source = row["SugarUpdateRows"] as List<DataRow>;
				string[] columns = row["SugarColumns"] as string[];
				return source.Any(delegate(DataRow it)
				{
					bool flag = true;
					string[] array = columns;
					foreach (string columnName in array)
					{
						if (flag)
						{
							flag = row[columnName].ObjToString() == it[columnName].ObjToString();
							if (!flag && it[columnName] != null && it[columnName].GetType() == UtilConstants.DecType)
							{
								flag = row[columnName].ObjToDecimal() == it[columnName].ObjToDecimal();
							}
							if (!flag)
							{
								break;
							}
						}
					}
					return flag;
				});
			}
		}
		public class StorageableMethodInfo
		{
			internal SqlSugarProvider Context { get; set; }

			internal MethodInfo MethodInfo { get; set; }

			internal object objectValue { get; set; }

			public StorageableAsMethodInfo AsInsertable
			{
				get
				{
					string type = "AsInsertable";
					return GetAs(type);
				}
			}

			public StorageableAsMethodInfo AsUpdateable
			{
				get
				{
					string type = "AsUpdateable";
					return GetAs(type);
				}
			}

			public int ExecuteCommand()
			{
				if (Context == null)
				{
					return 0;
				}
				object callValue = null;
				MethodInfo saveMethod = GetSaveMethod(ref callValue);
				if (saveMethod == null)
				{
					return 0;
				}
				return (int)saveMethod.Invoke(callValue, new object[0]);
			}

			private StorageableAsMethodInfo GetAs(string type)
			{
				object callValue = null;
				MethodInfo saveMethod = GetSaveMethod(ref callValue);
				if (saveMethod == null)
				{
					return new StorageableAsMethodInfo(null);
				}
				saveMethod = callValue.GetType().GetMethod("ToStorage");
				callValue = saveMethod.Invoke(callValue, new object[0]);
				return new StorageableAsMethodInfo(type)
				{
					ObjectValue = callValue,
					Method = saveMethod
				};
			}

			private MethodInfo GetSaveMethod(ref object callValue)
			{
				if (objectValue == null)
				{
					return null;
				}
				callValue = MethodInfo.Invoke(Context, new object[1] { objectValue });
				return callValue.GetType().GetMyMethod("ExecuteCommand", 0);
			}

			public StorageableMethodInfo ToStorage()
			{
				return this;
			}

			public StorageableSplitTableMethodInfo SplitTable()
			{
				object callValue = null;
				MethodInfo saveMethod = GetSaveMethod(ref callValue);
				if (saveMethod == null)
				{
					return new StorageableSplitTableMethodInfo(null);
				}
				saveMethod = callValue.GetType().GetMethod("SplitTable");
				callValue = saveMethod.Invoke(callValue, new object[0]);
				return new StorageableSplitTableMethodInfo(null)
				{
					ObjectValue = callValue,
					Method = saveMethod
				};
			}

			public StorageableSplitTableMethodInfo AS(string tableName)
			{
				object callValue = null;
				MethodInfo saveMethod = GetSaveMethod(ref callValue);
				if (saveMethod == null)
				{
					return new StorageableSplitTableMethodInfo(null);
				}
				saveMethod = callValue.GetType().GetMyMethod("As", 1);
				callValue = saveMethod.Invoke(callValue, new object[1] { tableName });
				return new StorageableSplitTableMethodInfo(null)
				{
					ObjectValue = callValue,
					Method = saveMethod
				};
			}

			public StorageableSplitTableMethodInfo WhereColumns(string[] strings)
			{
				object callValue = null;
				MethodInfo saveMethod = GetSaveMethod(ref callValue);
				if (saveMethod == null)
				{
					return new StorageableSplitTableMethodInfo(null);
				}
				saveMethod = callValue.GetType().GetMyMethod("WhereColumns", 1, typeof(string[]));
				callValue = saveMethod.Invoke(callValue, new object[1] { strings });
				return new StorageableSplitTableMethodInfo(null)
				{
					ObjectValue = callValue,
					Method = saveMethod
				};
			}
		}
		public class StorageableAsMethodInfo
		{
			private string type;

			internal object ObjectValue { get; set; }

			internal MethodInfo Method { get; set; }

			private StorageableAsMethodInfo()
			{
			}

			public StorageableAsMethodInfo(string type)
			{
				this.type = type;
			}

			public int ExecuteCommand()
			{
				if (type == null)
				{
					return 0;
				}
				object value = ObjectValue.GetType().GetProperty(type).GetValue(ObjectValue);
				return (int)value.GetType().GetMethod("ExecuteCommand").Invoke(value, new object[0]);
			}

			public StorageableCommonMethodInfo IgnoreColumns(params string[] ignoreColumns)
			{
				object obj = (ObjectValue?.GetType().GetProperty(type))?.GetValue(ObjectValue);
				object value = obj?.GetType().GetMyMethod("IgnoreColumns", 1, typeof(string[])).Invoke(obj, new object[1] { ignoreColumns });
