						await Context.Ado.BeginTranAsync();
					}
					await Context.Utilities.PageEachAsync(Data, PageSize, async delegate(List<T> pageItem)
					{
						int num = result;
						result = num + await Context.Storageable(pageItem).As(TableName).TranLock(lockType)
							.WhereColumns(whereExpression)
							.ExecuteCommandAsync();
						if (ActionCallBack != null)
						{
							ActionCallBack(result);
						}
					});
					if (isNoTran)
					{
						await Context.Ado.CommitTranAsync();
					}
				}
				catch (Exception)
				{
					if (isNoTran)
					{
						await Context.Ado.RollbackTranAsync();
					}
					throw;
				}
				return result;
			}

