			}

			internal int pageSize = 1000;

			internal Action<int> ActionCallBack;

			internal Storageable<T> SaveInfo { get; set; }

			internal SqlSugarProvider Context { get; set; }

			internal List<T> List { get; set; }

			internal EntityInfo EntityInfo { get; set; }

			internal Expression<Func<T, object>> whereExpression { get; set; }

			public StorageableSplitProvider<T> PageSize(int size, Action<int> ActionCallBack = null)
			{
				pageSize = size;
				return this;
			}

			public int ExecuteCommand()
			{
				if (List.Count > pageSize)
				{
					int result = 0;
					Context.Utilities.PageEach(List, pageSize, delegate(List<T> pageItem)
					{
						result += _ExecuteCommand(pageItem);
					});
					return result;
				}
				List<T> list = List;
				return _ExecuteCommand(list);
			}

			public int ExecuteSqlBulkCopy()
			{
				if (List.Count > pageSize)
				{
					int result = 0;
					Context.Utilities.PageEach(List, pageSize, delegate(List<T> pageItem)
					{
						result += _ExecuteSqlBulkCopy(pageItem);
					});
					return result;
				}
				List<T> list = List;
				return _ExecuteSqlBulkCopy(list);
			}

			public async Task<int> ExecuteCommandAsync()
			{
				if (List.Count > pageSize)
				{
					int result = 0;
					await Context.Utilities.PageEachAsync(List, pageSize, async delegate(List<T> pageItem)
					{
						int num = result;
						result = num + await _ExecuteCommandAsync(pageItem);
						if (ActionCallBack != null)
						{
							ActionCallBack(result);
						}
					});
					return result;
				}
				List<T> list = List;
				return await _ExecuteCommandAsync(list);
			}

			public async Task<int> ExecuteSqlBulkCopyAsync()
			{
				if (List.Count > pageSize)
				{
					int result = 0;
					await Context.Utilities.PageEachAsync(List, pageSize, async delegate(List<T> pageItem)
					{
						int num = result;
						result = num + await _ExecuteSqlBulkCopyAsync(pageItem);
						if (ActionCallBack != null)
						{
							ActionCallBack(result);
						}
					});
					return result;
				}
				List<T> list = List;
				return await _ExecuteSqlBulkCopyAsync(list);
			}

			private async Task<int> _ExecuteCommandAsync(List<T> list)
			{
				int num = 0;
				GroupDataList(list, out List<GroupModel> groupModels, out int _);
				foreach (IGrouping<string, GroupModel> item in from it in groupModels
					group it by it.GroupName)
				{
					List<T> dataList = item.Select((GroupModel it) => it.Item).ToList();
					int num2 = num;
					num = num2 + await Context.Storageable(dataList).As(item.Key).WhereColumns(whereExpression)
						.ExecuteCommandAsync();
					if (ActionCallBack != null)
					{
						ActionCallBack(num);
					}
				}
				return num;
			}

			private int _ExecuteCommand(List<T> list)
			{
				int num = 0;
				GroupDataList(list, out List<GroupModel> groupModels, out int _);
				foreach (IGrouping<string, GroupModel> item in from it in groupModels
					group it by it.GroupName)
				{
					List<T> dataList = item.Select((GroupModel it) => it.Item).ToList();
					num += Context.Storageable(dataList).As(item.Key).WhereColumns(whereExpression)
						.ExecuteCommand();
				}
				return num;
			}

			private async Task<int> _ExecuteSqlBulkCopyAsync(List<T> list)
			{
				int num = 0;
				GroupDataList(list, out List<GroupModel> groupModels, out int _);
				foreach (IGrouping<string, GroupModel> item in from it in groupModels
					group it by it.GroupName)
				{
					List<T> dataList = item.Select((GroupModel it) => it.Item).ToList();
					int num2 = num;
					num = num2 + await Context.Storageable(dataList).As(item.Key).WhereColumns(whereExpression)
						.ExecuteSqlBulkCopyAsync();
					if (ActionCallBack != null)
					{
						ActionCallBack(num);
					}
				}
				return num;
			}

			private int _ExecuteSqlBulkCopy(List<T> list)
			{
				int num = 0;
				GroupDataList(list, out List<GroupModel> groupModels, out int _);
				foreach (IGrouping<string, GroupModel> item in from it in groupModels
					group it by it.GroupName)
				{
					List<T> dataList = item.Select((GroupModel it) => it.Item).ToList();
					num += Context.Storageable(dataList).As(item.Key).WhereColumns(whereExpression)
						.ExecuteSqlBulkCopy();
				}
				return num;
			}

			private void GroupDataList(List<T> datas, out List<GroupModel> groupModels, out int result)
			{
				SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
				Check.Exception(customAttribute == null, typeof(T).Name + " need SplitTableAttribute");
				groupModels = new List<GroupModel>();
				SqlSugarProvider context = Context;
				foreach (T data in datas)
				{
					object value = context.SplitHelper<T>().GetValue(customAttribute.SplitType, data);
					string tableName = context.SplitHelper<T>().GetTableName(customAttribute.SplitType, value);
					groupModels.Add(new GroupModel
					{
						GroupName = tableName,
						Item = data
					});
				}
				List<string> tableNames = groupModels.Select((GroupModel it) => it.GroupName).Distinct().ToList();
				CreateTable(tableNames);
				result = 0;
			}

			private void CreateTable(List<string> tableNames)
			{
				bool isEnableLogEvent = Context.Ado.IsEnableLogEvent;
				Context.Ado.IsEnableLogEvent = false;
				foreach (string tableName in tableNames)
				{
					if (!Context.DbMaintenance.IsAnyTable(tableName, isCache: false) && tableName != null)
					{
						Context.MappingTables.Add(EntityInfo.EntityName, tableName);
						Context.CodeFirst.InitTables<T>();
					}
				}
				Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				Context.MappingTables.Add(EntityInfo.EntityName, EntityInfo.DbTableName);
			}
		}
		public class DeleteBuilder : IDMLBuilder
		{
			private List<string> _WhereInfos;

			public EntityInfo EntityInfo { get; set; }

			public SqlSugarProvider Context { get; set; }

			public ILambdaExpressions LambdaExpressions { get; set; }

			public List<SugarParameter> Parameters { get; set; }

			public StringBuilder sql { get; set; }

			public ISqlBuilder Builder { get; set; }

			public string TableWithString { get; set; }

			public string AsName { get; set; }

			public virtual List<string> WhereInfos
			{
				get
				{
					_WhereInfos = UtilMethods.IsNullReturnNew(_WhereInfos);
					return _WhereInfos;
				}
				set
				{
					_WhereInfos = value;
				}
			}

			public virtual List<object> BigDataInValues { get; set; }

			public virtual string BigDataFiled { get; set; }

			public virtual string SqlTemplate => "DELETE FROM {0}{1}";

			public string WhereInTemplate => "{0} IN ({1})";

			public string WhereInOrTemplate => "OR";

			public string WhereInAndTemplate => "AND";

			public string WhereInEqualTemplate => Builder.SqlTranslationLeft + "{0}" + Builder.SqlTranslationRight + "=N'{1}'";

			public string WhereInAreaTemplate => "({0})";

			public virtual string GetTableNameString
			{
				get
				{
					string text = Builder.GetTranslationTableName(EntityInfo.EntityName);
					if (AsName.HasValue())
					{
						text = Builder.GetTranslationColumnName(AsName);
					}
					text += " ";
					if (TableWithString.HasValue())
					{
						text = text + TableWithString + " ";
					}
					return text;
				}
			}

			public virtual string GetWhereString
			{
				get
				{
					if (_WhereInfos == null || _WhereInfos.Count == 0)
					{
						return null;
					}
					string text = null;
					int num = 0;
					foreach (string whereInfo in _WhereInfos)
					{
						bool flag = num == 0;
						text += (flag ? "WHERE " : "AND ");
						text = text + whereInfo + " ";
						num++;
					}
					return text;
				}
			}

			public virtual void Clear()
			{
			}

			public virtual string ToSqlString()
			{
				if (BigDataInValues.IsNullOrEmpty())
				{
					return string.Format(SqlTemplate, GetTableNameString, GetWhereString);
				}
				string getWhereString = GetWhereString;
				string text = string.Format(SqlTemplate, GetTableNameString, getWhereString);
				text += (getWhereString.IsNullOrEmpty() ? " WHERE " : " AND ");
				StringBuilder stringBuilder = new StringBuilder();
				int num = 1000;
				int i = 1;
				for (int num2 = (BigDataInValues.Count + num - 1) / num; num2 >= i; i++)
				{
					List<object> list = BigDataInValues.Skip((i - 1) * num).Take(num).ToList();
					stringBuilder.Append(text + string.Format(WhereInTemplate, BigDataFiled, list.ToArray().ToJoinSqlInVals()));
					stringBuilder.Append(";");
				}
				return stringBuilder.ToString();
			}

			public virtual ExpressionResult GetExpressionValue(Expression expression, ResolveExpressType resolveType)
			{
				ILambdaExpressions resolveExpress = LambdaExpressions;
				LambdaExpressions.Clear();
				if (Context.CurrentConnectionConfig.MoreSettings != null)
				{
					resolveExpress.TableEnumIsString = Context.CurrentConnectionConfig.MoreSettings.TableEnumIsString;
					resolveExpress.PgSqlIsAutoToLower = Context.CurrentConnectionConfig.MoreSettings.PgSqlIsAutoToLower;
				}
				else
				{
					resolveExpress.PgSqlIsAutoToLower = true;
				}
				resolveExpress.SugarContext = new ExpressionOutParameter
				{
					Context = Context
				};
				resolveExpress.MappingColumns = Context.MappingColumns;
				resolveExpress.MappingTables = Context.MappingTables;
				resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
				resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				resolveExpress.InitMappingInfo = Context.InitMappingInfo;
				resolveExpress.RefreshMapping = delegate
				{
					resolveExpress.MappingColumns = Context.MappingColumns;
					resolveExpress.MappingTables = Context.MappingTables;
					resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
					resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				};
				resolveExpress.Resolve(expression, resolveType);
				if (Parameters == null)
				{
					Parameters = new List<SugarParameter>();
				}
				Parameters.AddRange(resolveExpress.Parameters);
				return resolveExpress.Result;
			}
		}
