			public virtual string SqlTemplate
			{
				get
				{
					if (IsReturnIdentity)
					{
						return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;SELECT SCOPE_IDENTITY();";
					}
					return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;";
				}
			}

			public virtual string SqlTemplateBatch => "INSERT {0} ({1})";

			public virtual string SqlTemplateBatchSelect => "{0} AS {1}";

			public virtual string SqlTemplateBatchUnion => "\t\r\nUNION ALL ";

			public virtual Func<object, string> SerializeObjectFunc { get; set; }

