			public virtual ExpressionResult GetExpressionValue(Expression expression, ResolveExpressType resolveType)
			{
				ILambdaExpressions resolveExpress = LambdaExpressions;
				if (resolveType.IsIn(ResolveExpressType.FieldSingle, ResolveExpressType.FieldMultiple, ResolveExpressType.SelectSingle, ResolveExpressType.SelectMultiple) && expression is LambdaExpression && (expression as LambdaExpression).Body is BinaryExpression)
				{
					resolveType = (resolveType.IsIn(ResolveExpressType.SelectSingle, ResolveExpressType.FieldSingle) ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple);
				}
				LambdaExpressions.Clear();
				if (Context.CurrentConnectionConfig.MoreSettings != null)
				{
					resolveExpress.TableEnumIsString = Context.CurrentConnectionConfig.MoreSettings.TableEnumIsString;
					resolveExpress.PgSqlIsAutoToLower = Context.CurrentConnectionConfig.MoreSettings.PgSqlIsAutoToLower;
				}
				else
				{
					resolveExpress.PgSqlIsAutoToLower = true;
				}
				resolveExpress.SugarContext = new ExpressionOutParameter
				{
					Context = Context,
					QueryBuilder = this
				};
				resolveExpress.RootExpression = expression;
				resolveExpress.JoinQueryInfos = Builder.QueryBuilder.JoinQueryInfos;
				resolveExpress.IsSingle = IsSingle() && resolveType != ResolveExpressType.WhereMultiple;
				resolveExpress.MappingColumns = Context.MappingColumns;
				resolveExpress.MappingTables = Context.MappingTables;
				resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
				resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				resolveExpress.InitMappingInfo = Context.InitMappingInfo;
				resolveExpress.RefreshMapping = delegate
				{
					resolveExpress.MappingColumns = Context.MappingColumns;
					resolveExpress.MappingTables = Context.MappingTables;
					resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
					resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				};
				resolveExpress.Resolve(expression, resolveType);
				Parameters.AddRange(resolveExpress.Parameters.Select((SugarParameter it) => new SugarParameter(it.ParameterName, it.Value, it.DbType)
				{
					Size = it.Size,
					TypeName = it.TypeName,
					IsNvarchar2 = it.IsNvarchar2
				}));
				ExpressionResult result = resolveExpress.Result;
				if (IsSingle() && resolveExpress.SingleTableNameSubqueryShortName.HasValue())
				{
					if (TableShortName != null && TableShortName.StartsWith("\""))
					{
						Check.Exception(!string.IsNullOrEmpty(TableShortName) && resolveExpress.SingleTableNameSubqueryShortName != TableShortName.TrimEnd('"').TrimStart('"'), "{0} and {1} need same name", resolveExpress.SingleTableNameSubqueryShortName, TableShortName);
						TableShortName = resolveExpress.SingleTableNameSubqueryShortName;
					}
					else
					{
						Check.Exception(!string.IsNullOrEmpty(TableShortName) && resolveExpress.SingleTableNameSubqueryShortName != TableShortName, "{0} and {1} need same name", resolveExpress.SingleTableNameSubqueryShortName, TableShortName);
						TableShortName = resolveExpress.SingleTableNameSubqueryShortName;
					}
				}
				return result;
			}

			internal string GetFilters(Type type)
			{
				string text = "";
				if (Context != null)
				{
					SqlSugarProvider context = Context;
					BindingFlags bindingAttr = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
					int num = 0;
					if (context.QueryFilter.GetFilterList != null)
					{
						foreach (SqlFilterItem getFilter in context.QueryFilter.GetFilterList)
						{
							if (RemoveFilters != null && RemoveFilters.Length != 0 && Enumerable.Contains(RemoveFilters, getFilter.type))
							{
								continue;
							}
							PropertyInfo property = getFilter.GetType().GetProperty("exp", bindingAttr);
							if (!(property != null))
							{
								continue;
							}
							Type ChildType = getFilter.type;
							bool flag = ChildType.IsInterface && type.GetInterfaces().Any((Type it) => it == ChildType);
							if ((ChildType == type) | flag)
							{
								context.EntityMaintenance.GetEntityInfo(ChildType);
								Expression expression = property.GetValue(getFilter, null) as Expression;
								string text2 = ((num == 0) ? " " : " AND ");
								num++;
								text = text + text2 + GetExpressionValue(expression, ResolveExpressType.WhereSingle).GetString();
								if (flag)
								{
									text = ReplaceFilterColumnName(text, type);
								}
							}
						}
					}
				}
				return text;
			}

			public virtual string ToSqlString()
			{
				string orderByValue = OrderByValue;
				string text = orderByValue;
				bool flag = IsCount && PartitionByValue.IsNullOrEmpty();
				AppendFilter();
				sql = new StringBuilder();
				if (OrderByValue == null && (Skip.HasValue || Take.HasValue))
				{
					OrderByValue = " ORDER BY GetDate() ";
				}
				if (PartitionByValue.HasValue())
				{
					OrderByValue = PartitionByValue + OrderByValue;
				}
				bool flag2 = Skip.HasValue || Take.HasValue;
				string text2 = $",ROW_NUMBER() OVER({GetOrderByString}) AS RowIndex ";
				string text3 = GetGroupByString + HavingInfos;
				string text4 = ((!flag2 && OrderByValue.HasValue()) ? GetOrderByString : null);
				if (flag)
				{
					text4 = null;
				}
				sql.AppendFormat(SqlTemplate, GetSelectValue, GetTableNameString, GetWhereValueString, text3, text4);
				sql.Replace(UtilConstants.ReplaceKey, (!flag2) ? null : (flag ? null : text2));
				if (flag)
				{
					OrderByValue = orderByValue;
					return sql.ToString();
				}
				string text5 = ToPageSql(sql.ToString(), Take, Skip);
				if (ExternalPageIndex > 0)
				{
					if (text.IsNullOrEmpty())
					{
						text = " ORDER BY GetDate() ";
					}
					text5 = $"SELECT *,ROW_NUMBER() OVER({GetExternalOrderBy(text)}) AS RowIndex2 FROM ({text5}) ExternalTable ";
					text5 = ToPageSql2(text5, ExternalPageIndex, ExternalPageSize, isExternal: true);
				}
				OrderByValue = orderByValue;
				return text5;
			}

			public virtual void AppendFilter()
			{
				if (IsDisabledGobalFilter || !Context.QueryFilter.GetFilterList.HasValue())
				{
					return;
				}
				List<SqlFilterItem> list = Context.QueryFilter.GetFilterList.Where((SqlFilterItem it) => it.FilterName.IsNullOrEmpty()).ToList();
				if (RemoveFilters != null && RemoveFilters.Length != 0)
				{
					list = list.Where((SqlFilterItem it) => !Enumerable.Contains(RemoveFilters, it.type)).ToList();
				}
				foreach (SqlFilterItem item in list)
				{
					if (item.GetType().Name.StartsWith("TableFilterItem"))
					{
						AppendTableFilter(item);
					}
				}
				foreach (SqlFilterItem item2 in from it in list
					where it.GetType().Name == "SqlFilterItem"
					where it.IsJoinQuery == !IsSingle()
					select it)
				{
					SqlFilterResult sqlFilterResult = item2.FilterValue(Context);
					WhereInfos.Add(Builder.AppendWhereOrAnd(WhereInfos.IsNullOrEmpty(), sqlFilterResult.Sql + " "));
					SugarParameter[] parameters = Context.Ado.GetParameters(sqlFilterResult.Parameters);
					if (parameters.HasValue())
					{
						Parameters.AddRange(parameters);
					}
				}
			}

			private void AppendTableFilter(SqlFilterItem item)
			{
				BindingFlags bindingAttr = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
				PropertyInfo? property = item.GetType().GetProperty("exp", bindingAttr);
				Type ChildType = item.type;
