			internal string ReplaceFilterColumnName(string sql, Type filterType, string shortName = null)
			{
				foreach (EntityColumnInfo item in Context.EntityMaintenance.GetEntityInfoWithAttr(filterType).Columns.Where((EntityColumnInfo it) => !it.IsIgnore))
				{
					if (shortName == null)
					{
						sql = sql.Replace(Builder.GetTranslationColumnName(item.PropertyName), Builder.GetTranslationColumnName(item.DbColumnName));
						continue;
					}
					sql = sql.Replace(Builder.GetTranslationColumnName(shortName) + "." + Builder.GetTranslationColumnName(item.PropertyName), Builder.GetTranslationColumnName(shortName) + "." + Builder.GetTranslationColumnName(item.DbColumnName));
					sql = sql.Replace(shortName + "." + Builder.GetTranslationColumnName(item.PropertyName), shortName + "." + Builder.GetTranslationColumnName(item.DbColumnName));
				}
				return sql;
			}

			private string GetSql(Expression exp, bool isSingle)
			{
