			public virtual string ToJoinString(JoinQueryInfo joinInfo)
			{
				string name = joinInfo.TableName;
				if (AsTables.Any())
				{
					if (Context.MappingTables != null && Context.MappingTables.Any((MappingTable it) => it.DbTableName == name))
					{
						name = Context.MappingTables.First((MappingTable it) => it.DbTableName == name).EntityName;
					}
					if (AsTables.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> it) => it.Key == name))
					{
						name = AsTables.First<KeyValuePair<string, string>>((KeyValuePair<string, string> it) => it.Key == name).Value;
					}
				}
				bool flag = name != null && name.StartsWith("(") && name.EndsWith(")");
				string text = joinInfo.ShortName;
				if (text.HasValue())
				{
					text = Builder.GetTranslationColumnName(text);
				}
				string text2 = string.Format(JoinTemplate, joinInfo.JoinType.ToString() + " ", Builder.GetTranslationTableName(name) + " ", text + " " + (((TableWithString == "Non") | flag) ? " " : TableWithString), joinInfo.JoinWhere);
				if (joinInfo.EntityType != null && Context.EntityMaintenance.GetEntityInfoWithAttr(joinInfo.EntityType).Discrimator.HasValue())
				{
					EntityInfo entityInfoWithAttr = Context.EntityMaintenance.GetEntityInfoWithAttr(joinInfo.EntityType);
					text2 = $" {text2} AND {text}.{UtilMethods.GetDiscrimator(entityInfoWithAttr, Builder)}";
				}
				if (joinInfo.JoinType == JoinType.Cross)
				{
					text2 = text2[..text2.IndexOf(" ON ")];
				}
				return text2;
			}

