				if (JoinQueryInfos.Count == 0 && string.IsNullOrEmpty(OrderByValue) && IsSqlQuery && OldSql.HasValue() && !Skip.HasValue && !Take.HasValue && (WhereInfos == null || WhereInfos.Count == 0))
				{
					return OldSql;
				}
				return result;
			}

