			protected string SubToListMethod(string result)
			{
				string result2 = result;
				List<string> list = new List<string>();
				List<string> allShortName = new List<string>();
				if (IsSingleSubToList())
				{
					TableShortName = (SelectValue as LambdaExpression).Parameters[0].Name;
				}
				allShortName.Add(Builder.SqlTranslationLeft + Builder.GetNoTranslationColumnName(TableShortName.ObjToString().ToLower()) + Builder.SqlTranslationRight + ".");
				if (JoinQueryInfos.HasValue())
				{
					foreach (JoinQueryInfo joinQueryInfo in JoinQueryInfos)
					{
						allShortName.Add(Builder.SqlTranslationLeft + Builder.GetNoTranslationColumnName(joinQueryInfo.ShortName.ObjToString().ToLower()) + Builder.SqlTranslationRight + ".");
					}
				}
				else if (EasyJoinInfos != null && EasyJoinInfos.Any())
				{
					Check.ExceptionEasy("No Supprt Subquery.ToList(), Inner Join Or  Left Join", "Subquery.ToList请使用Inner方式联表");
				}
				if (TableShortName != null)
				{
					_ = Builder.GetTranslationColumnName(TableShortName) + "\\.";
					foreach (KeyValuePair<string, object> subToListParameter in SubToListParameters)
					{
						string pattern = $"\\{Builder.SqlTranslationLeft}[\\w]{{1,20}}?\\{Builder.SqlTranslationRight}\\.\\{Builder.SqlTranslationLeft}.{{1,50}}?\\{Builder.SqlTranslationRight}";
						if (Builder.SqlTranslationLeft == string.Empty)
						{
							pattern = "[\\w]{1,20}?\\..{1,50}? ";
						}
						List<string> collection = (from Match it in Regex.Matches(subToListParameter.Value.ObjToString(), pattern, RegexOptions.IgnoreCase)
							where allShortName.Any((string z) => it.Value.ObjToString().ToLower().Contains(z))
							select it.Value).ToList();
						list.AddRange(collection);
					}
					int num = 0;
					list = list.Distinct().ToList();
					if (list.Any())
					{
						List<QueryableAppendColumn> list2 = new List<QueryableAppendColumn>();
						foreach (string item in list)
						{
							result += $",{item} as app_ext_col_{num}";
							list2.Add(new QueryableAppendColumn
							{
								AsName = $"app_ext_col_{num}",
								Name = item,
								Index = num
							});
							num++;
						}
						AppendColumns = list2;
					}
				}
				if (HasAppText(result2))
				{
					return result2;
				}
				return result;
			}

