			public void CheckExpression(Expression expression, string methodName)
			{
				if (IsSingle() || JoinExpression == null)
				{
					return;
				}
				ReadOnlyCollection<ParameterExpression> parameters = (JoinExpression as LambdaExpression).Parameters;
				ReadOnlyCollection<ParameterExpression> parameters2 = (expression as LambdaExpression).Parameters;
				if ((expression as LambdaExpression).Body.ToString() == "True" || parameters2 == null || parameters2.Count <= 0)
				{
					return;
				}
				foreach (ParameterExpression item in parameters2)
				{
					int index = parameters2.IndexOf(item);
					string name = item.Name;
					string name2 = parameters[index].Name;
					Check.Exception(name.ToLower() != name2.ToLower(), ErrorMessage.ExpressionCheck, name2, methodName, name);
				}
			}

			public void CheckExpressionNew(Expression expression, string methodName)
			{
				if (IsSingle() || JoinExpression == null)
				{
					return;
				}
				ReadOnlyCollection<ParameterExpression> parameters = (JoinExpression as LambdaExpression).Parameters;
				ReadOnlyCollection<ParameterExpression> parameters2 = (expression as LambdaExpression).Parameters;
				if ((expression as LambdaExpression).Body.ToString() == "True" || parameters2 == null || parameters2.Count <= 0)
				{
					return;
				}
				if (parameters.Count + 1 != parameters2.Count)
				{
					string value = "(" + string.Join(",", parameters2.Select((ParameterExpression it) => it.Name)) + ")=>";
					string value2 = "(" + string.Join(",", parameters.Select((ParameterExpression it) => it.Name)) + "," + parameters2.Last().Type.Name + " )=>";
					throw new Exception(ErrorMessage.GetThrowMessage($"Join {parameters2.Last().Type.Name} error , Please change {value} to {value2}.", $"Join {parameters2.Last().Type.Name} 错误, 请把 {value} 改成 {value2} "));
				}
				foreach (ParameterExpression item in parameters2.Take(parameters.Count))
				{
					int index = parameters2.IndexOf(item);
					string name = item.Name;
					string name2 = parameters[index].Name;
					Check.Exception(name.ToLower() != name2.ToLower(), ErrorMessage.ExpressionCheck, name2, methodName, name);
				}
			}

