			private string[] SqlSplicingOperator = new string[29]
			{
				">", ">=", "<", "<=", "(", ")", "!=", "<>", "not", "=",
				"||", "&&", "&", "|", "null", "is", "isnot", "like", "nolike", "+",
				"-", "*", "/", "%", "$casewhen", "$then", "$when", "$else", "$end"
			};

			internal int GetParameterNameIndex = 100;

