			public UpdateBuilder UpdateBuilder { get; set; }

			public SqlQueryBuilder SqlQueryBuilder
			{
				get
				{
					_SqlQueryBuilder = UtilMethods.IsNullReturnNew(_SqlQueryBuilder);
					return _SqlQueryBuilder;
				}
				set
				{
					_SqlQueryBuilder = value;
				}
			}

			public virtual bool SupportReadToken { get; set; } = true;

			public virtual string SqlParameterKeyWord => "@";

			public abstract string SqlTranslationLeft { get; }

			public abstract string SqlTranslationRight { get; }

			public virtual string SqlFalse => "1=2 ";

			public virtual string SqlDateNow => "GETDATE()";

			public virtual string FullSqlDateNow => "SELECT GETDATE()";

			public virtual string SqlSelectAll => "*";

			public virtual Task<bool> GetReaderByToken(IDataReader dataReader, CancellationToken cancellationToken)
			{
				return ((DbDataReader)dataReader).ReadAsync(cancellationToken);
