			public virtual string GetTranslationTableName(string name)
			{
				Check.ArgumentNullException(name, string.Format(ErrorMessage.ObjNotExist, "Table Name"));
				if (!name.Contains("<>f__AnonymousType") && name.IsContainsIn("(", ")", SqlTranslationLeft) && name != "Dictionary`2")
				{
					MappingTable mappingTable = Context.MappingTables?.FirstOrDefault((MappingTable it) => it.EntityName.Equals(name, StringComparison.CurrentCultureIgnoreCase));
					if (mappingTable != null)
					{
						return GetTranslationColumnName(mappingTable.DbTableName);
					}
					return name;
				}
				if (Context.MappingTables == null)
				{
					return name;
				}
				MappingTable mappingTable2 = Context.MappingTables.FirstOrDefault((MappingTable it) => it.EntityName.Equals(name, StringComparison.CurrentCultureIgnoreCase));
				name = ((mappingTable2 == null) ? name : mappingTable2.DbTableName);
				if (name.IsContainsIn("(", ")", SqlTranslationLeft))
				{
					return name;
				}
				if (name.Contains("."))
				{
					return string.Join(".", from it in name.Split('.')
						select SqlTranslationLeft + it + SqlTranslationRight);
				}
				return SqlTranslationLeft + name + SqlTranslationRight;
			}

			public virtual string GetTranslationColumnName(string entityName, string propertyName)
			{
				Check.ArgumentNullException(entityName, string.Format(ErrorMessage.ObjNotExist, "Table Name"));
				Check.ArgumentNullException(propertyName, string.Format(ErrorMessage.ObjNotExist, "Column Name"));
				MappingColumn mappingColumn = Context.MappingColumns.FirstOrDefault((MappingColumn it) => it.EntityName.Equals(entityName, StringComparison.CurrentCultureIgnoreCase) && it.PropertyName.Equals(propertyName, StringComparison.CurrentCultureIgnoreCase));
				if (mappingColumn != null)
				{
					return SqlTranslationLeft + mappingColumn.DbColumnName + SqlTranslationRight;
				}
				return SqlTranslationLeft + propertyName + SqlTranslationRight;
			}

			public virtual string GetTranslationColumnName(string propertyName)
			{
				if (propertyName.Contains(SqlTranslationLeft))
				{
					return propertyName;
				}
				if (propertyName.Contains("."))
				{
					return string.Join(".", from it in propertyName.Split('.')
						select SqlTranslationLeft + it + SqlTranslationRight);
				}
				return SqlTranslationLeft + propertyName + SqlTranslationRight;
			}

			public virtual string GetNoTranslationColumnName(string name)
			{
				if (name.Contains("="))
				{
					name = name.Split('=').First();
				}
				if (!name.Contains(SqlTranslationLeft))
				{
					return name;
				}
				if (!name.Contains(".") && name.StartsWith(SqlTranslationLeft) && name.EndsWith(SqlTranslationRight))
				{
					return name.TrimStart(Convert.ToChar(SqlTranslationLeft)).TrimEnd(Convert.ToChar(SqlTranslationRight));
				}
				if (name != null)
				{
					return Regex.Match(name, ".*\\" + SqlTranslationLeft + "(.*?)\\" + SqlTranslationRight).Groups[1].Value;
				}
				return string.Empty;
			}

