			public string GetWhere(string fieldName, string conditionalType, int? parameterIndex = null)
			{
				object[] obj = new object[4]
				{
					GetTranslationColumnName(fieldName),
					conditionalType,
					SqlParameterKeyWord,
					null
				};
				string text = fieldName.Replace(".", "_");
				int? num = parameterIndex;
				obj[3] = text + num;
				return string.Format(" {0} {1} {2}{3} ", obj);
			}

