			public virtual KeyValuePair<string, SugarParameter[]> ConditionalModelToSql(List<IConditionalModel> models, int beginIndex = 0)
			{
				if (models.IsNullOrEmpty())
				{
					return default(KeyValuePair<string, SugarParameter[]>);
				}
				StringBuilder stringBuilder = new StringBuilder();
				List<SugarParameter> list = new List<SugarParameter>();
				ISqlBuilder sqlbuilder = InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig);
				int mainIndex = 0;
				int indexTree = 0;
				foreach (IConditionalModel model in models)
				{
					if (model is ConditionalModel)
					{
						ConditionalModel conditionalModel = model as ConditionalModel;
						if (conditionalModel.CustomConditionalFunc != null)
						{
							int num = mainIndex + beginIndex;
							string text = ((num == 0) ? "" : "AND");
							KeyValuePair<string, SugarParameter[]> conditionalSql = conditionalModel.CustomConditionalFunc.GetConditionalSql(conditionalModel, num);
							list.AddRange(conditionalSql.Value);
							stringBuilder.AppendFormat(" " + text + " " + conditionalSql.Key);
							mainIndex++;
							continue;
						}
						if (conditionalModel.FieldName == UtilMethods.FieldNameSql())
						{
							stringBuilder.Append(conditionalModel.FieldValue);
							continue;
						}
						int num2 = mainIndex + beginIndex;
						string text2 = ((num2 == 0) ? "" : "AND");
						if (beginIndex > 0)
						{
							text2 = null;
						}
						string text3 = " {0} {1} {2} {3}  ";
						string text4 = $"{sqlbuilder.SqlParameterKeyWord}Condit{conditionalModel.FieldName}{num2}";
						SqlSugarProvider context = Context;
						if (context != null && context.CurrentConnectionConfig?.MoreSettings?.MaxParameterNameLength > 0 && text4.Length > Context?.CurrentConnectionConfig?.MoreSettings?.MaxParameterNameLength)
						{
							text4 = string.Format("{0}Condit{1}{2}", sqlbuilder.SqlParameterKeyWord, conditionalModel.FieldName.GetHashCode().ToString().Replace("-", ""), num2);
						}
						if (text4.Contains("."))
						{
							text4 = text4.Replace(".", "_");
						}
						if (text4.Contains("["))
						{
							text4 = text4.Replace("[", "_");
						}
						if (text4.Contains("]"))
						{
							text4 = text4.Replace("]", "_");
						}
						if (!string.IsNullOrEmpty(SqlTranslationLeft) && text4.Contains(SqlTranslationLeft))
						{
							text4 = text4.Replace(SqlTranslationLeft, "_");
						}
						string fieldName = conditionalModel.FieldName;
						conditionalModel.FieldName = GetTranslationColumnName(conditionalModel.FieldName);
						conditionalModel.FieldName = conditionalModel.FieldName.ToCheckField();
						ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
						bool flag = currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.EnableILike == true;
						switch (conditionalModel.ConditionalType)
						{
						case ConditionalType.Equal:
							Equal(stringBuilder, list, conditionalModel, text2, text3, text4);
							break;
						case ConditionalType.Like:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), flag ? "ILIKE" : "LIKE", text4);
							list.Add(new SugarParameter(text4, "%" + conditionalModel.FieldValue + "%"));
							break;
						case ConditionalType.GreaterThan:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), ">", text4);
							list.Add(new SugarParameter(text4, GetFieldValue(conditionalModel)));
							break;
						case ConditionalType.GreaterThanOrEqual:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), ">=", text4);
							list.Add(new SugarParameter(text4, GetFieldValue(conditionalModel)));
							break;
						case ConditionalType.LessThan:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), "<", text4);
							list.Add(new SugarParameter(text4, GetFieldValue(conditionalModel)));
							break;
						case ConditionalType.LessThanOrEqual:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), "<=", text4);
							list.Add(new SugarParameter(text4, GetFieldValue(conditionalModel)));
							break;
						case ConditionalType.In:
							In(stringBuilder, conditionalModel, text2, text3);
							break;
						case ConditionalType.NotIn:
							NotIn(stringBuilder, list, conditionalModel, text2, text3, text4);
							break;
						case ConditionalType.LikeLeft:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), flag ? "ILIKE" : "LIKE", text4);
							list.Add(new SugarParameter(text4, conditionalModel.FieldValue + "%"));
							break;
						case ConditionalType.NoLike:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), flag ? "NOT ILIKE" : " NOT LIKE", text4);
							list.Add(new SugarParameter(text4, "%" + conditionalModel.FieldValue + "%"));
							break;
						case ConditionalType.LikeRight:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), flag ? "ILIKE" : "LIKE", text4);
							list.Add(new SugarParameter(text4, "%" + conditionalModel.FieldValue));
							break;
						case ConditionalType.NoEqual:
							stringBuilder.AppendFormat(text3, text2, conditionalModel.FieldName.ToSqlFilter(), "<>", text4);
							list.Add(new SugarParameter(text4, GetFieldValue(conditionalModel)));
							break;
						case ConditionalType.IsNullOrEmpty:
							stringBuilder.AppendFormat(" {0} (({1}) OR ({2})) ", text2, conditionalModel.FieldName.ToSqlFilter() + " IS NULL ", conditionalModel.FieldName.ToSqlFilter() + " = '' ");
							list.Add(new SugarParameter(text4, conditionalModel.FieldValue));
							break;
						case ConditionalType.IsNot:
							IsNot(stringBuilder, list, conditionalModel, text2, text3, text4);
							break;
						case ConditionalType.EqualNull:
							EqualNull(stringBuilder, list, conditionalModel, text2, text3, text4);
							break;
						case ConditionalType.InLike:
							InLike(stringBuilder, list, conditionalModel, num2, text2, text4);
							break;
						case ConditionalType.Range:
							Range(stringBuilder, list, conditionalModel, num2, text2, text4);
							break;
						case ConditionalType.RangeDate:
							RangeDate(stringBuilder, list, conditionalModel, num2, text2, text4);
							break;
						}
						conditionalModel.FieldName = fieldName;
					}
					else if (model is ConditionalCollections)
					{
						if (model is ConditionalCollections conditionalCollections && conditionalCollections.ConditionalList.HasValue())
						{
							foreach (KeyValuePair<WhereType, ConditionalModel> conditional in conditionalCollections.ConditionalList)
							{
								int num3 = conditionalCollections.ConditionalList.IndexOf(conditional);
								bool flag2 = num3 == 0;
								bool num4 = num3 == conditionalCollections.ConditionalList.Count - 1;
								if (models.IndexOf(conditionalCollections) == 0 && num3 == 0 && beginIndex == 0)
								{
									stringBuilder.AppendFormat(" ( ");
								}
								else if (flag2)
								{
									stringBuilder.AppendFormat(" {0} ( ", conditional.Key.ToString().ToUpper());
								}
								List<IConditionalModel> list2 = new List<IConditionalModel> { conditional.Value };
								KeyValuePair<string, SugarParameter[]> keyValuePair = ConditionalModelToSql(list2, 1000 * (1 + num3) + models.IndexOf(conditionalCollections));
								if (!flag2 && conditional.Value.FieldName != "[value=sql" + UtilConstants.ReplaceKey + "]")
								{
									stringBuilder.AppendFormat(" {0} ", conditional.Key.ToString().ToUpper());
								}
								stringBuilder.Append(keyValuePair.Key);
								if (list2?.FirstOrDefault() is ConditionalModel { CustomConditionalFunc: not null })
								{
									stringBuilder.Replace(" AND (  AND", " AND (  ");
									stringBuilder.Replace(" OR (  AND", " OR (  ");
									stringBuilder.Replace(" (  AND ", " ( ");
									stringBuilder.Replace(" (  OR ", " ( ");
									stringBuilder.Replace("   OR  AND ", "   OR ");
									stringBuilder.Replace("   AND  AND ", "   AND ");
								}
								list.AddRange(keyValuePair.Value);
								if (num4)
								{
									stringBuilder.Append(" ) ");
								}
							}
						}
					}
					else
					{
						ConditionalTree item = model as ConditionalTree;
						BuilderTree(stringBuilder, item, ref indexTree, list, ref mainIndex);
					}
					mainIndex++;
				}
				return new KeyValuePair<string, SugarParameter[]>(stringBuilder.ToString(), list.ToArray());
			}

			private static void Range(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, int index, string type, string parameterName)
			{
				string[] array = (item.FieldValue ?? "").Split(',');
				if (array.Length != 2)
				{
					Check.ExceptionEasy("The " + item.FieldName + " value is not a valid format, but is properly separated by a comma (1,2)", item.FieldName + " 值不是有效格式，正确是 1,2 这种中间逗号隔开");
				}
				object fieldValue = GetFieldValue(new ConditionalModel
				{
					CSharpTypeName = item.CSharpTypeName,
					FieldValue = array.FirstOrDefault()
				});
				object fieldValue2 = GetFieldValue(new ConditionalModel
				{
					CSharpTypeName = item.CSharpTypeName,
					FieldValue = array.LastOrDefault()
				});
				string text = parameterName + "_01";
				string text2 = parameterName + "_02";
				builder.AppendFormat(type + "( {0}>={1} AND {0}<={2} )", item.FieldName.ToSqlFilter(), text, text2);
				parameters.Add(new SugarParameter(text, fieldValue));
				parameters.Add(new SugarParameter(text2, fieldValue2));
			}

			private static void RangeDate(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, int index, string type, string parameterName)
			{
				string[] array = (item.FieldValue ?? "").Split(',');
				if (array.Length != 2)
				{
					Check.ExceptionEasy("The " + item.FieldName + " value is not a valid format, but is properly separated by a comma (1,2)", item.FieldName + " 值不是有效格式，正确是 1,2 这种中间逗号隔开");
				}
				DateTime[] dateRange = GetDateRange(array.FirstOrDefault(), array.LastOrDefault());
				string text = parameterName + "_01";
				string text2 = parameterName + "_02";
				builder.AppendFormat(type + "( {0}>={1} AND {0}<{2} )", item.FieldName.ToSqlFilter(), text, text2);
				parameters.Add(new SugarParameter(text, dateRange.First()));
				parameters.Add(new SugarParameter(text2, dateRange.Last()));
			}

			public static DateTime[] GetDateRange(string date1Str, string date2Str)
			{
				date1Str = date1Str.Trim();
				date2Str = date2Str.Trim();
				int length = date2Str.Trim().Length;
				if (date1Str.Length == 4)
				{
					date1Str = new DateTime(int.Parse(date1Str), 1, 1).ToString("yyyy-MM-dd HH:mm:ss");
				}
				if (date2Str.Length == 4)
				{
					date2Str = new DateTime(int.Parse(date2Str), 1, 1).ToString("yyyy-MM-dd HH:mm:ss");
				}
				if (date1Str.Length == 13)
				{
					date1Str += ":00:00";
				}
				if (date2Str.Length == 13)
				{
					date2Str += ":00:00";
				}
				if (!DateTime.TryParse(date1Str, out var result))
				{
					Check.ExceptionEasy("date1 format is incorrect.(yyyy-MM-dd | yyyy | yyyy-MM | yyyy-MM-dd HH | yyyy-MM-dd HH:mm |yyyy-MM-dd HH:mm:ss)", "date1 格式不正确，支持格式 yyyy-MM-dd | yyyy | yyyy-MM | yyyy-MM-dd HH | yyyy-MM-dd HH:mm|yyyy-MM-dd HH:mm:ss");
				}
				if (!DateTime.TryParse(date2Str, out var result2))
				{
					Check.ExceptionEasy("date2 format is incorrect.", "date2 格式不正确");
				}
				switch (length)
				{
				case 4:
					result2 = result2.AddYears(1);
					break;
				case 7:
					result2 = result2.AddMonths(1);
					break;
				case 10:
					result2 = result2.AddDays(1.0);
					break;
				case 13:
					result2 = result2.AddHours(1.0);
					break;
				case 16:
					result2 = result2.AddMinutes(1.0);
					break;
				case 19:
					result2 = result2.AddSeconds(1.0);
					break;
				default:
					Check.ExceptionEasy("date format is incorrect.(yyyy-MM-dd | yyyy | yyyy-MM | yyyy-MM-dd HH | yyyy-MM-dd HH:mm|yyyy-MM-dd HH:mm:ss)", "date 格式不正确，支持格式 yyyy-MM-dd | yyyy | yyyy-MM | yyyy-MM-dd HH | yyyy-MM-dd HH:mm|yyyy-MM-dd HH:mm:ss");
					break;
				}
				return new DateTime[2] { result, result2 };
			}

			private static void InLike(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, int index, string type, string parameterName)
			{
				List<string> list = (item.FieldValue ?? "").Split(',').ToList();
				List<string> list2 = new List<string>();
				int num = 0;
				foreach (string item2 in list)
				{
					string text = $"{parameterName}{index}{num}";
					list2.Add(item.FieldName.ToSqlFilter() + " LIKE " + text);
					parameters.Add(new SugarParameter(text, "%" + item2 + "%"));
					num++;
				}
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(5, 2, builder);
				handler.AppendLiteral(" ");
				handler.AppendFormatted(type);
				handler.AppendLiteral(" (");
				handler.AppendFormatted(string.Join(" OR ", list2));
				handler.AppendLiteral(") ");
				builder.Append(ref handler);
			}

			private static void EqualNull(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, string type, string temp, string parameterName)
			{
				if (GetFieldValue(item) == null || item.FieldValue == null)
				{
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "  IS ", " NULL ");
				}
				else
				{
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "=", parameterName);
					parameters.Add(new SugarParameter(parameterName, GetFieldValue(item)));
				}
			}

			private static void IsNot(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, string type, string temp, string parameterName)
			{
				if (item.FieldValue == null)
				{
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), " IS NOT ", "NULL");
					return;
				}
				if (builder.Length > 0)
				{
					builder.AppendFormat(" AND (" + temp, null, item.FieldName.ToSqlFilter(), "<>", parameterName);
				}
				else
				{
					builder.Append("(");
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "<>", parameterName);
				}
				parameters.Add(new SugarParameter(parameterName, item.FieldValue));
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(12, 1, builder);
				handler.AppendLiteral("OR ");
				handler.AppendFormatted(item.FieldName.ToSqlFilter());
				handler.AppendLiteral(" is null ");
				builder.Append(ref handler);
				builder.Append(")");
			}

			private static void NotIn(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, string type, string temp, string parameterName)
			{
				if (item.FieldValue == null)
				{
					item.FieldValue = string.Empty;
				}
				string text = "(" + item.FieldValue.Split(',').ToJoinSqlInVals() + ")";
				if (item.CSharpTypeName.HasValue() && UtilMethods.IsNumber(item.CSharpTypeName))
				{
					text = text.Replace("'", "");
				}
				else if (text.Contains("'null'"))
				{
					text = text.Replace("'null'", "null");
				}
				if (text.Contains("[null]"))
				{
					text = text.Replace("[null]", "'null'");
				}
				if (text.Contains("[comma]"))
				{
					text = text.Replace("[comma]", ",");
				}
				builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "NOT IN", text);
				parameters.Add(new SugarParameter(parameterName, item.FieldValue));
			}

			private void In(StringBuilder builder, ConditionalModel item, string type, string temp)
			{
				if (item.FieldValue == null)
				{
					item.FieldValue = string.Empty;
				}
				string empty = string.Empty;
				string[] array = item.FieldValue.Split(',');
				int num = 1000;
				if (array.Length > num && Context.CurrentConnectionConfig.DbType == DbType.Oracle)
				{
					InBig(builder, item, type, temp, array, num);
					return;
				}
				empty = In_GetInValue(item, array);
				if (item.CSharpTypeName.HasValue() && UtilMethods.IsNumber(item.CSharpTypeName))
				{
					empty = empty.Replace("'", "");
				}
				else if (empty.Contains("'null'"))
				{
					empty = empty.Replace("'null'", "null");
				}
				if (empty.Contains("[comma]"))
				{
					empty = empty.Replace("[comma]", ",");
				}
				if (empty.Contains("[null]"))
				{
					empty = empty.Replace("[null]", "'null'");
				}
				if (item.CSharpTypeName.EqualCase("guid") && empty == "('')")
				{
					empty = "('" + Guid.Empty.ToString() + "')";
				}
				else if (empty == "()")
				{
					empty = "(NULL)";
				}
				if (array.Length == 1 && empty != "(null)")
				{
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "=", empty.TrimStart('(').TrimEnd(')'));
				}
				else
				{
					builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "IN", empty);
				}
			}

			private void InBig(StringBuilder builder, ConditionalModel item, string type, string temp, string[] inArray, int pageSize)
			{
				List<string> sqlList = new List<string>();
				Context.Utilities.PageEach(inArray, pageSize, delegate(List<string> items)
				{
					if (item.CSharpTypeName.EqualCase("string") || item.CSharpTypeName == null)
					{
						sqlList.Add("(" + item.FieldName.ToSqlFilter() + " IN (" + items.Distinct().ToArray().ToJoinSqlInVals() + "))");
					}
					else
					{
						sqlList.Add("(" + item.FieldName.ToSqlFilter() + " IN (" + items.Select((string it) => (!(it == "")) ? it : "null").Distinct().ToArray()
							.ToJoinSqlInVals() + "))");
					}
				});
				string text = " " + string.Join(" OR ", sqlList) + " ";
				if (item.CSharpTypeName.HasValue() && UtilMethods.IsNumber(item.CSharpTypeName))
				{
					text = text.Replace("'", "");
				}
				builder.AppendFormat(temp, type, "", " ", text);
			}

			private string In_GetInValue(ConditionalModel item, string[] inArray)
			{
				string text;
				if (item.CSharpTypeName.EqualCase("string") || item.CSharpTypeName == null)
				{
					text = "(" + inArray.Distinct().ToArray().ToJoinSqlInVals() + ")";
				}
				if (!item.CSharpTypeName.EqualCase("bool") && !item.CSharpTypeName.EqualCase("Boolean"))
				{
					text = ((!item.CSharpTypeName.EqualCase("nstring")) ? ("(" + inArray.Select((string it) => (!(it == "")) ? it : "null").Distinct().ToArray()
						.ToJoinSqlInVals() + ")") : ("(" + inArray.Select((string it) => (!(it == "")) ? it : "null").Distinct().ToArray()
						.ToJoinSqlInValsByVarchar() + ")"));
				}
				else
				{
					ILambdaExpressions lambdaExpressions = InstanceFactory.GetLambdaExpressions(Context.CurrentConnectionConfig);
					lambdaExpressions.Context = Context;
					string thisValue = lambdaExpressions.DbMehtods.TrueValue();
					text = "(" + string.Join(",", inArray.Distinct().ToArray()) + ")";
					if (thisValue.EqualCase("true"))
					{
						text = text.Replace("1", "true").Replace("0", "false");
					}
				}
				return text;
			}

			private static void Equal(StringBuilder builder, List<SugarParameter> parameters, ConditionalModel item, string type, string temp, string parameterName)
			{
				if (item.FieldValue != null && item.FieldValue == "null" && item.FieldValue != "[null]")
				{
					builder.AppendFormat(" " + item.FieldName.ToSqlFilter() + " is null ");
					return;
				}
				if (item.FieldValue == "[null]")
				{
					item.FieldValue = "null";
				}
				builder.AppendFormat(temp, type, item.FieldName.ToSqlFilter(), "=", parameterName);
				SugarParameter sugarParameter = new SugarParameter(parameterName, GetFieldValue(item));
				if (item.CSharpTypeName.EqualCase("DateOnly"))
				{
					sugarParameter.DbType = System.Data.DbType.Date;
				}
				if (item.CSharpTypeName.EqualCase("Char"))
				{
					sugarParameter.DbType = System.Data.DbType.StringFixedLength;
				}
				if (item.CSharpTypeName.EqualCase("AnsiString"))
				{
					sugarParameter.DbType = System.Data.DbType.AnsiString;
				}
				parameters.Add(sugarParameter);
			}

			private void BuilderTree(StringBuilder builder, ConditionalTree item, ref int indexTree, List<SugarParameter> parameters, ref int mainIndex)
			{
				ConditionalCollections item2 = ToConditionalCollections(item, ref indexTree, parameters);
				KeyValuePair<string, SugarParameter[]> keyValuePair = ConditionalModelToSql(new List<IConditionalModel> { item2 }, mainIndex);
				string appendSql = keyValuePair.Key;
				RepairReplicationParameters(ref appendSql, keyValuePair.Value, indexTree);
				parameters.AddRange(keyValuePair.Value);
				string value = appendSql;
				builder.Append(value);
				indexTree++;
			}

			private ConditionalCollections ToConditionalCollections(ConditionalTree item, ref int indexTree, List<SugarParameter> parameters)
			{
				List<KeyValuePair<WhereType, ConditionalModel>> list = new List<KeyValuePair<WhereType, ConditionalModel>>();
				int num = 0;
				foreach (KeyValuePair<WhereType, IConditionalModel> conditional in item.ConditionalList)
				{
					ConditionalModel conditionalModel = new ConditionalModel();
					if (conditional.Value is ConditionalModel)
					{
						conditionalModel = (ConditionalModel)conditional.Value;
					}
					else
					{
						ConditionalTree item2 = conditional.Value as ConditionalTree;
						ConditionalCollections item3 = ToConditionalCollections(item2, ref indexTree, parameters);
						KeyValuePair<string, SugarParameter[]> keyValuePair = ConditionalModelToSql(new List<IConditionalModel> { item3 }, num);
						string appendSql = keyValuePair.Key;
						if (appendSql.StartsWith(" NULL "))
						{
							appendSql = Regex.Replace(appendSql, "^ NULL ", conditional.Key.ToString().ToUpper());
						}
						RepairReplicationParameters(ref appendSql, keyValuePair.Value, indexTree);
						conditionalModel = new ConditionalModel
						{
							FieldName = "[value=sql" + UtilConstants.ReplaceKey + "]",
							FieldValue = appendSql
						};
						parameters.AddRange(keyValuePair.Value);
						indexTree++;
					}
					list.Add(new KeyValuePair<WhereType, ConditionalModel>(conditional.Key, conditionalModel));
					num++;
				}
				return new ConditionalCollections
				{
					ConditionalList = list
				};
			}

			public KeyValuePair<string, SugarParameter[]> FuncModelToSql(IFuncModel model)
			{
				ObjectFuncModel obj = model as ObjectFuncModel;
				string funcName = obj.FuncName;
				List<object> parameters = obj.Parameters;
				IDbMethods dbMehtods = Context.Queryable<object>().QueryBuilder.LambdaExpressions.DbMehtods;
				List<string> allMethods = GetAllMethods(dbMehtods);
				string methodName = GetMethodName(funcName, allMethods);
				MethodInfo method = GetMethod(dbMehtods, methodName);
				ParameterInfo[] parameters2 = method.GetParameters();
				string text = "";
				List<SugarParameter> list = new List<SugarParameter>();
				text = GetSql(parameters, dbMehtods, methodName, method, parameters2, list);
				if (funcName.EqualCase("MappingColumn"))
				{
					SqlSugarProvider context = Context;
					if (context == null || context.CurrentConnectionConfig?.MoreSettings?.EnableModelFuncMappingColumn != true)
					{
						Check.ExceptionEasy("Enable MappingColumn need in ConnectionConfig - > MoreSettings - > EnableModelFuncMappingColumn set to true", "MappingColumn考虑到风险情况需要开启才能使用，请在 ConnectionConfig->MoreSettings->EnableModelFuncMappingColumn设置为true");
					}
					text = parameters.First()?.ToString() ?? "";
				}
				return new KeyValuePair<string, SugarParameter[]>(text, list.ToArray());
			}

			private string GetSql(List<object> parameters, IDbMethods dbMethods, string methodName, MethodInfo methodInfo, ParameterInfo[] pars, List<SugarParameter> resPars)
			{
				if (IsNoParameter(pars))
				{
					return GetNoParameterMehtodSql(dbMethods, methodInfo);
				}
				if (IsFormatMethod(methodName))
				{
					return GetFormatMethodSql(parameters, resPars);
				}
				if (IsSqlFuncMethod(pars))
				{
					return GetSqlFuncSql(parameters, dbMethods, methodName, methodInfo, resPars);
				}
				if (IsMergeStringMethod(methodName))
				{
					return GetSqlFuncSql(parameters, dbMethods, methodName, methodInfo, resPars);
				}
				return GetNoSupportMethodSql(methodInfo);
			}

			private static MethodInfo GetMethod(IDbMethods dbMethods, string methodName)
			{
				return (from it in dbMethods.GetType().GetMethods()
					where it.Name == methodName
					where it.Name != "Equals" || (it.GetParameters().Length == 1 && it.GetParameters().First().ParameterType == typeof(MethodCallExpressionModel))
					select it).FirstOrDefault();
			}

			private static string GetMethodName(string name, List<string> methods)
			{
				string? text = methods.FirstOrDefault((string it) => name.EqualCase("SqlFunc_" + it) || name.EqualCase(it));
				Check.Exception(text == null, " " + name + " is error ");
				return text;
			}

			private static List<string> GetAllMethods(IDbMethods dbMethods)
			{
				return new ReflectionInoCacheService().GetOrCreate("Json2SqlGetFuncSql", () => (from it in dbMethods.GetType().GetMethods()
					where it.Name != "GetHashCode"
					select it.Name).ToList());
			}

			private static string GetNoSupportMethodSql(MethodInfo methodInfo)
			{
				throw new Exception(methodInfo.Name);
			}

			private string GetSqlFuncSql(List<object> parameters, IDbMethods dbMethods, string methodName, MethodInfo methodInfo, List<SugarParameter> resPars)
			{
				List<MethodCallExpressionArgs> list = new List<MethodCallExpressionArgs>();
				int num = 0;
				foreach (object parameter in parameters)
				{
					num++;
					string value = null;
					if (methodName.IsIn("ContainsArray", "ContainsArrayUseSqlParameters") && num == 1)
					{
						string[] source = Regex.Split(parameter?.ToString() ?? "", ":");
						int num2 = source.Count();
						source.First();
						string value2 = source.Last();
						if (num2 > 2)
						{
							value2 = string.Join(":", source.Skip(1));
						}
						object[] parvalue = Context.Utilities.DeserializeObject<object[]>(value2);
						value = GetParameterName(resPars, parvalue);
					}
					else
					{
						value = GetSqlPart(parameter, resPars);
					}
					list.Add(new MethodCallExpressionArgs
					{
						MemberName = value,
						MemberValue = (resPars.FirstOrDefault((SugarParameter it) => it.ParameterName == value)?.Value ?? value),
						IsMember = true
					});
				}
				if (IsMergeStringMethod(methodName))
				{
					return methodInfo.Invoke(dbMethods, new object[1] { list.Select((MethodCallExpressionArgs it) => it.MemberName.ObjToString()).ToArray() }).ObjToString();
				}
				if (IsToStringFormat(methodName, list))
				{
					string fieldName = list.First().MemberName.ObjToString();
					string format = list.Last().MemberValue.ObjToString();
					return (from it in Context.Queryable<object>()
						select SqlFunc.MappingColumn<DateTime>(fieldName).ToString(format)).QueryBuilder.GetSelectValue;
				}
				return methodInfo.Invoke(dbMethods, new object[1]
				{
					new MethodCallExpressionModel
					{
						Name = methodName,
						Args = list
					}
				}).ObjToString();
			}

			private static bool IsToStringFormat(string methodName, List<MethodCallExpressionArgs> args)
			{
				if (methodName == "ToString")
				{
					if (args == null)
					{
						return false;
					}
					return args.Count == 2;
				}
				return false;
			}

			private string GetFormatMethodSql(List<object> parameters, List<SugarParameter> resPars)
			{
				List<string> list = new List<string>();
				foreach (object parameter in parameters)
				{
					string sqlPart = GetSqlPart(parameter, resPars);
					list.Add(sqlPart.ObjToString());
				}
				return string.Join(" ", string.Join(" ", list));
			}

			private static string GetNoParameterMehtodSql(IDbMethods dbMethods, MethodInfo methodInfo)
			{
				return methodInfo.Invoke(dbMethods, new object[0]).ObjToString();
			}

			private static bool IsMergeStringMethod(string methodName)
			{
				return methodName == "MergeString";
			}

			private static bool IsSqlFuncMethod(ParameterInfo[] pars)
			{
				return pars.First().ParameterType == typeof(MethodCallExpressionModel);
			}

			private static bool IsFormatMethod(string methodName)
			{
				return methodName.EqualCase("format");
			}

			private static bool IsNoParameter(ParameterInfo[] pars)
			{
				return pars.Length == 0;
			}

			public KeyValuePair<string, SugarParameter[]> GroupByModelToSql(List<GroupByModel> models)
			{
				StringBuilder stringBuilder = new StringBuilder("");
				List<SugarParameter> list = new List<SugarParameter>();
				foreach (GroupByModel model in models)
				{
					if (model != null && model.FieldName is IFuncModel)
					{
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder3 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 1, stringBuilder2);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(GetSqlPart(model.FieldName, list));
						handler.AppendLiteral(" ,");
						stringBuilder3.Append(ref handler);
					}
					else if (model != null)
					{
						GroupByModel groupByModel = model;
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder4 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 1, stringBuilder2);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(GetTranslationColumnName(groupByModel.FieldName.ObjToString().ToSqlFilter()));
						handler.AppendLiteral(" ,");
						stringBuilder4.Append(ref handler);
					}
				}
				return new KeyValuePair<string, SugarParameter[]>(stringBuilder.ToString().TrimEnd(','), list?.ToArray());
			}

			public KeyValuePair<string, SugarParameter[]> OrderByModelToSql(List<OrderByModel> models)
			{
				StringBuilder stringBuilder = new StringBuilder("");
				List<SugarParameter> list = new List<SugarParameter>();
				foreach (OrderByModel model in models)
				{
					if (model != null && model.FieldName is IFuncModel)
					{
						OrderByModel orderByModel = model;
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder3 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(4, 2, stringBuilder2);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(GetSqlPart(model.FieldName, list));
						handler.AppendLiteral(" ");
						handler.AppendFormatted(orderByModel.OrderByType.ToString().ToUpper());
						handler.AppendLiteral(" ,");
						stringBuilder3.Append(ref handler);
					}
					else if (model != null)
					{
						OrderByModel orderByModel2 = model;
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder4 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(4, 2, stringBuilder2);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(GetTranslationColumnName(orderByModel2.FieldName.ObjToString().ToSqlFilter()));
						handler.AppendLiteral(" ");
						handler.AppendFormatted(orderByModel2.OrderByType.ToString().ToUpper());
						handler.AppendLiteral(" ,");
						stringBuilder4.Append(ref handler);
					}
				}
				return new KeyValuePair<string, SugarParameter[]>(stringBuilder.ToString().TrimEnd(','), list?.ToArray());
			}

			public KeyValuePair<string, SugarParameter[]> SelectModelToSql(List<SelectModel> models)
			{
				StringBuilder stringBuilder = new StringBuilder("");
				List<SugarParameter> list = new List<SugarParameter>();
				foreach (SelectModel model in models)
				{
					if (model != null)
					{
						SelectModel selectModel = model;
						selectModel.AsName = GetAsName(selectModel);
						selectModel.FieldName = GetSqlPart(selectModel.FieldName, list).ObjToString();
						AppendFiledName(stringBuilder, selectModel);
					}
				}
				return new KeyValuePair<string, SugarParameter[]>(stringBuilder.ToString().TrimEnd(','), list.ToArray());
			}

			private string GetAsName(SelectModel orderByModel)
			{
				if (orderByModel.AsName.IsNullOrEmpty())
				{
					orderByModel.AsName = orderByModel.FieldName.ObjToString();
				}
				if (orderByModel.AsName.StartsWith(UtilConstants.ReplaceKey))
				{
					return orderByModel.AsName.Replace(UtilConstants.ReplaceKey, string.Empty);
				}
				string asName = orderByModel.AsName;
				if (asName != null && asName.Contains("["))
				{
					orderByModel.AsName = orderByModel.AsName.Trim('[').Trim(']');
					return SqlTranslationLeft + orderByModel.AsName + SqlTranslationRight;
				}
				if (SqlTranslationLeft != null)
				{
					string asName2 = orderByModel.AsName;
					if (asName2 != null && asName2.Contains(SqlTranslationLeft))
					{
						return orderByModel.AsName;
					}
				}
				return SqlTranslationLeft + orderByModel.AsName + SqlTranslationRight;
			}

			private void AppendFiledName(StringBuilder sql, SelectModel orderByModel)
			{
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 2, sql);
				handler.AppendLiteral(" ");
				handler.AppendFormatted<object>(orderByModel.FieldName);
				handler.AppendLiteral(" AS ");
				handler.AppendFormatted(orderByModel.AsName);
				handler.AppendLiteral(" ,");
				sql.Append(ref handler);
			}

			private string GetSqlPart(object value, List<SugarParameter> pars)
			{
				Check.Exception(value == null, " FiledName is error ");
				if (IsSqlSplicingOperator(value))
				{
					return GetSqlSplicingOperator(value);
				}
				if (IsString(value))
				{
					return GetSqlPartByString(value, pars);
				}
				if (IsListObject(value))
				{
					return GetSqlPartByListObject(value, pars);
				}
				if (IsObjectFunc(value))
				{
					return GetSqlPartByObjectFuncModel(value, pars);
				}
				return GetSqlPartError(value);
			}

			private static string GetSqlSplicingOperator(object value)
			{
				string text = value.ObjToString();
				if (text == "||")
				{
					return "OR";
				}
				if (text == "&&")
				{
					return "AND";
				}
				if (text.EqualCase("isnot"))
				{
					return " IS NOT ";
				}
				if (text.EqualCase("$casewhen"))
				{
					return " CASE WHEN ";
				}
				if (text.EqualCase("$then"))
				{
					return " THEN ";
				}
				if (text.EqualCase("$when"))
				{
					return " WHEN ";
				}
				if (text.EqualCase("$else"))
				{
					return " ELSE ";
				}
				if (text.EqualCase("$end"))
				{
					return " END ";
				}
				return text;
			}

			private static string GetSqlPartError(object value)
			{
				Check.Exception(value == null, $" {value} is error ");
				return null;
			}

			private string GetSqlPartByObjectFuncModel(object value, List<SugarParameter> pars)
			{
				ObjectFuncModel model = value as ObjectFuncModel;
				KeyValuePair<string, SugarParameter[]> keyValuePair = FuncModelToSql(model);
				pars.AddRange(keyValuePair.Value);
				return keyValuePair.Key;
			}

			private string GetSqlPartByListObject(object value, List<SugarParameter> pars)
			{
				List<object> list = value as List<object>;
				if (list.Count == 1)
				{
					return GetSqlPart(list.First(), pars).ObjToString();
				}
				Check.Exception(value == null, $" {value} is error ");
				return null;
			}

			private string GetSqlPartByString(object value, List<SugarParameter> pars)
			{
				string valueString = value.ObjToString().Trim();
				if (Json2SqlHelper.IsSqlValue(valueString))
				{
					return GetParameterName(pars, valueString);
				}
				return GetTranslationColumnName(value.ObjToString().ToCheckField());
			}

			private string GetSplicingOperator(string valueString)
			{
				string text = Regex.Match(valueString, "\\@s\\:(.+)").Groups[1].Value;
				if (text == null)
				{
					text = "";
				}
				text = text.Trim();
				if (text.ToLower().IsIn(SqlSplicingOperator))
				{
					return text;
				}
				Check.ExceptionEasy(valueString + " is error ", valueString + " 不是有效的拼接符号,拼接符号有:and、or、>=、<=、>、<、=、(、)");
				return text;
			}

			private string GetParameterName(List<SugarParameter> pars, string valueString)
			{
				object value = Json2SqlHelper.GetValue(valueString);
				new SugarParameter("@p" + pars.Count(), value);
				value = UtilMethods.ConvertDataByTypeName(Json2SqlHelper.GetType(valueString), value.ObjToString());
				return GetParameterName(pars, value);
			}

			private string GetParameterName(List<SugarParameter> pars, object parvalue)
			{
				string text = "@p" + pars.Count() + "_" + GetParameterNameIndex + $"{QueryBuilder?.LambdaExpressions?.ParameterIndex}";
				SugarParameter item = new SugarParameter(text, parvalue);
				pars.Add(item);
				GetParameterNameIndex++;
				if (QueryBuilder != null)
				{
					QueryBuilder.LambdaExpressions.ParameterIndex++;
				}
				return text;
			}

			private static bool IsListObject(object value)
			{
				return value.GetType() == typeof(List<object>);
			}

			private static bool IsString(object value)
			{
				return value.GetType() == typeof(string);
			}

			private static bool IsObjectFunc(object value)
			{
				return value is ObjectFuncModel;
			}

			private bool IsSqlSplicingOperator(object value)
			{
				return Enumerable.Contains(SqlSplicingOperator, value.ObjToString());
			}
		}
		public class SqlQueryBuilder : IDMLBuilder
		{
			private string _Fields;

			private StringBuilder _Sql;

			private List<SugarParameter> _Parameters;

