			public string Fields
			{
				get
				{
					if (_Fields.IsNullOrEmpty())
					{
						_Fields = Regex.Match(sql.ObjToString().Replace("\n", string.Empty).Replace("\r", string.Empty)
							.Trim(), "select(.*?)from", RegexOptions.IgnoreCase).Groups[1].Value;
						if (_Fields.IsNullOrEmpty())
						{
							_Fields = "*";
						}
					}
					return _Fields;
				}
				set
				{
					_Fields = value;
				}
			}

