			{
				return sql.ToString();
			}

			public void Clear()
			{
				sql = null;
			}
		}
		public class UpdateBuilder : IDMLBuilder
		{
			private int GetDbColumnIndex;

			public SqlSugarProvider Context { get; set; }

			public ILambdaExpressions LambdaExpressions { get; set; }

			public ISqlBuilder Builder { get; set; }

			public StringBuilder sql { get; set; }

			public List<SugarParameter> Parameters { get; set; }

			public string TableName { get; set; }

			public string TableWithString { get; set; }

			public List<DbColumnInfo> DbColumnInfoList { get; set; }

			public List<string> WhereValues { get; set; }

			public string AppendWhere { get; set; }

			public List<KeyValuePair<string, string>> SetValues { get; set; }

			public bool IsNoUpdateNull { get; set; }

			public bool IsNoUpdateDefaultValue { get; set; }

			public List<string> PrimaryKeys { get; set; }

			public List<string> OldPrimaryKeys { get; set; }

			public bool IsOffIdentity { get; set; }

			public bool IsWhereColumns { get; set; }

			public bool? IsListUpdate { get; set; }

			public List<string> UpdateColumns { get; set; }

			public List<string> IgnoreColumns { get; set; }

			public List<JoinQueryInfo> JoinInfos { get; set; }

			public string ShortName { get; set; }

			public Dictionary<string, ReSetValueBySqlExpListModel> ReSetValueBySqlExpList { get; set; }

			public virtual string ReSetValueBySqlExpListType { get; set; }

			public EntityInfo EntityInfo { get; set; }

			public virtual string SqlTemplate => "UPDATE {0} SET\r\n           {1} {2}";

			public virtual string SqlTemplateBatch => "UPDATE S SET {0} FROM {1} S {2}   INNER JOIN ";

			public virtual string SqlTemplateJoin => "            (\r\n              {0}\r\n\r\n            ) T ON {1}\r\n                ; ";

			public virtual string SqlTemplateBatchSet => "{0} AS {1}";

			public virtual string SqlTemplateBatchSelect => "{0} AS {1}";

			public virtual string SqlTemplateBatchUnion => "\t\t\r\nUNION ALL ";

			public virtual string GetTableNameString
			{
				get
				{
					string translationTableName = Builder.GetTranslationTableName(TableName);
					translationTableName += " ";
					if (TableWithString.HasValue())
					{
						translationTableName = translationTableName + TableWithString + " ";
					}
					return translationTableName;
				}
			}

			public virtual string GetTableNameStringNoWith => Builder.GetTranslationTableName(TableName);

			public UpdateBuilder()
			{
				sql = new StringBuilder();
				DbColumnInfoList = new List<DbColumnInfo>();
				SetValues = new List<KeyValuePair<string, string>>();
				WhereValues = new List<string>();
				Parameters = new List<SugarParameter>();
			}

			public virtual void Clear()
			{
			}

			public virtual ExpressionResult GetExpressionValue(Expression expression, ResolveExpressType resolveType, bool isMapping = true)
			{
				ILambdaExpressions resolveExpress = LambdaExpressions;
				LambdaExpressions.Clear();
				if (Context.CurrentConnectionConfig.MoreSettings != null)
				{
					resolveExpress.PgSqlIsAutoToLower = Context.CurrentConnectionConfig.MoreSettings.PgSqlIsAutoToLower;
					resolveExpress.TableEnumIsString = Context.CurrentConnectionConfig.MoreSettings.TableEnumIsString;
				}
				else
				{
					resolveExpress.PgSqlIsAutoToLower = true;
				}
				if (isMapping)
				{
					resolveExpress.MappingColumns = Context.MappingColumns;
					resolveExpress.MappingTables = Context.MappingTables;
					resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
					resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				}
				resolveExpress.InitMappingInfo = Context.InitMappingInfo;
				resolveExpress.RefreshMapping = delegate
				{
					resolveExpress.MappingColumns = Context.MappingColumns;
					resolveExpress.MappingTables = Context.MappingTables;
					resolveExpress.IgnoreComumnList = Context.IgnoreColumns;
					resolveExpress.SqlFuncServices = ((Context.CurrentConnectionConfig.ConfigureExternalServices == null) ? null : Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices);
				};
				resolveExpress.SugarContext = new ExpressionOutParameter
				{
					Context = Context
				};
				resolveExpress.Resolve(expression, resolveType);
				Parameters.AddRange(resolveExpress.Parameters);
				return resolveExpress.Result;
			}

			public virtual string ToSqlString()
			{
				if (IsNoUpdateNull)
				{
					DbColumnInfoList = DbColumnInfoList.Where((DbColumnInfo it) => it.Value != null || it.UpdateServerTime || !string.IsNullOrEmpty(it.UpdateSql)).ToList();
				}
				if (IsNoUpdateDefaultValue)
				{
					DbColumnInfoList = DbColumnInfoList.Where(delegate(DbColumnInfo it)
					{
						if (it.Value.ObjToString() == "0" && it.PropertyType.IsEnum)
						{
							return it.Value.ObjToLong() != UtilMethods.DefaultForType(it.PropertyType).ObjToLong();
						}
						return it.UpdateServerTime || !string.IsNullOrEmpty(it.UpdateSql) || it.Value.ObjToString() != UtilMethods.DefaultForType(it.PropertyType).ObjToString();
					}).ToList();
				}
				List<IGrouping<int, DbColumnInfo>> list = (from it in DbColumnInfoList
					group it by it.TableId).ToList();
				if (list.Count() == 1 && !IsListUpdate.HasValue)
				{
					ActionMinDate();
					return ToSingleSqlString(list);
				}
				return TomultipleSqlString(list);
			}

			protected virtual string TomultipleSqlString(List<IGrouping<int, DbColumnInfo>> groupList)
			{
				Check.Exception(PrimaryKeys == null || PrimaryKeys.Count == 0, " Update List<T> need Primary key");
				int num = 200;
				int num2 = 1;
				int num3 = (groupList.Count + num - 1) / num;
				StringBuilder stringBuilder = new StringBuilder();
				while (num3 >= num2)
				{
					StringBuilder stringBuilder2 = new StringBuilder();
					string arg = string.Join(",", (from it in groupList.First()
						where !it.IsPrimarykey && (!it.IsIdentity || (IsOffIdentity && it.IsIdentity))
						select it).Select(delegate(DbColumnInfo it)
					{
						if (SetValues.IsValuable())
						{
							IEnumerable<KeyValuePair<string, string>> enumerable = SetValues.Where<KeyValuePair<string, string>>((KeyValuePair<string, string> sv) => sv.Key == Builder.GetTranslationColumnName(it.DbColumnName));
							if (enumerable != null && enumerable.Any())
							{
								return enumerable.First().Value;
							}
						}
						return string.Format("S.{0}=T.{0}", Builder.GetTranslationColumnName(it.DbColumnName));
					}));
					stringBuilder.AppendFormat(SqlTemplateBatch.ToString(), arg, GetTableNameStringNoWith, TableWithString);
					int num4 = 0;
					foreach (IGrouping<int, DbColumnInfo> item in groupList.Skip((num2 - 1) * num).Take(num).ToList())
					{
						if (num4 != 0)
						{
							stringBuilder2.Append(SqlTemplateBatchUnion);
						}
						stringBuilder2.Append("\r\n SELECT " + string.Join(",", item.Select((DbColumnInfo it) => string.Format(SqlTemplateBatchSelect, FormatValue(it.Value), Builder.GetTranslationColumnName(it.DbColumnName)))));
						num4++;
					}
					num2++;
					stringBuilder2.Append("\r\n");
					string text = null;
					if (WhereValues.HasValue())
					{
						foreach (string whereValue in WhereValues)
						{
							bool flag = text == null;
							text += (flag ? null : " AND ");
							text += Regex.Replace(whereValue, "\\" + Builder.SqlTranslationLeft, "S." + Builder.SqlTranslationLeft);
						}
					}
					if (PrimaryKeys.HasValue())
					{
						foreach (string primaryKey in PrimaryKeys)
						{
							bool flag2 = text == null;
							text += (flag2 ? null : " AND ");
							text += string.Format("S.{0}=T.{0}", Builder.GetTranslationColumnName(primaryKey));
						}
					}
					stringBuilder.AppendFormat(SqlTemplateJoin, stringBuilder2, text);
				}
				return stringBuilder.ToString();
			}

			protected virtual string ToSingleSqlString(List<IGrouping<int, DbColumnInfo>> groupList)
			{
				string text = string.Join(",", (from it in groupList.First()
					where !it.IsPrimarykey && (!it.IsIdentity || (IsOffIdentity && it.IsIdentity))
					select it).Select(delegate(DbColumnInfo it)
				{
					if (SetValues.IsValuable())
					{
						IEnumerable<KeyValuePair<string, string>> enumerable = from sv in SetValues
							where !it.IsPrimarykey && (!it.IsIdentity || (IsOffIdentity && it.IsIdentity))
							where sv.Key == Builder.GetTranslationColumnName(it.DbColumnName) || sv.Key == Builder.GetTranslationColumnName(it.PropertyName)
							select sv;
						if (enumerable != null && enumerable.Any())
						{
							return enumerable.First().Value;
						}
						if (JoinInfos != null && JoinInfos.Any())
						{
							enumerable = from sv in SetValues
								where !it.IsPrimarykey && (!it.IsIdentity || (IsOffIdentity && it.IsIdentity))
								where sv.Key == Builder.GetNoTranslationColumnName(it.DbColumnName) || sv.Key == Builder.GetNoTranslationColumnName(it.PropertyName)
								select sv;
							return Builder.GetTranslationColumnName(ShortName) + "." + Builder.GetTranslationColumnName(enumerable.First().Key) + "=" + enumerable.First().Value;
						}
					}
					return Builder.GetTranslationColumnName(it.DbColumnName) + "=" + GetDbColumn(it, Context.Ado.SqlParameterKeyWord + it.DbColumnName);
				}));
				string whereString = null;
				if (WhereValues.HasValue())
				{
					foreach (string whereValue in WhereValues)
					{
						bool flag = whereString == null;
						whereString += (flag ? " WHERE " : " AND ");
						whereString += whereValue;
					}
				}
				else if (PrimaryKeys.HasValue() && !IsWhereColumns)
				{
					int num = 100000;
					foreach (string item in PrimaryKeys)
					{
						num++;
						bool flag2 = whereString == null;
						whereString += (flag2 ? " WHERE " : " AND ");
						if (GetPkIsSugarDataConverter() && GetColumnInfo(item) != null)
						{
							GetColumnInfo(item);
							object value = DbColumnInfoList.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(item) || it.PropertyName.EqualCase(item))?.Value;
							SugarParameter parameterConverter = UtilMethods.GetParameterConverter(num, Context, value, EntityInfo, EntityInfo?.Columns.First((EntityColumnInfo it) => it.DbColumnName.Equals(item) || it.PropertyName.Equals(item)));
							whereString = whereString + Builder.GetTranslationColumnName(item) + "=" + parameterConverter.ParameterName;
							Parameters.Add(parameterConverter);
							continue;
						}
						whereString = whereString + Builder.GetTranslationColumnName(item) + "=" + Context.Ado.SqlParameterKeyWord + item;
						EntityColumnInfo columnInfo = GetColumnInfo(item);
						if (columnInfo != null && columnInfo.SqlParameterDbType is System.Data.DbType dbType)
						{
							SugarParameter sugarParameter = Parameters?.FirstOrDefault((SugarParameter it) => it.ParameterName == Context.Ado.SqlParameterKeyWord + item);
							if (sugarParameter != null)
							{
								sugarParameter.DbType = dbType;
							}
						}
					}
				}
				if (PrimaryKeys.HasValue() && IsWhereColumns)
				{
					foreach (string primaryKey in PrimaryKeys)
					{
						bool flag3 = whereString == null;
						whereString += (flag3 ? " WHERE " : " AND ");
						whereString = whereString + Builder.GetTranslationColumnName(primaryKey) + "=" + Context.Ado.SqlParameterKeyWord + primaryKey;
					}
				}
				if (JoinInfos != null && JoinInfos.Any())
				{
					return GetJoinUpdate(text, ref whereString);
				}
				return string.Format(SqlTemplate, GetTableNameString, text, whereString);
			}

			private EntityColumnInfo GetColumnInfo(string item)
			{
				return EntityInfo?.Columns?.FirstOrDefault((EntityColumnInfo it) => it.DbColumnName.EqualCase(item) || it.PropertyName.EqualCase(item));
			}

			private bool GetPkIsSugarDataConverter()
			{
				return EntityInfo?.Columns.Any((EntityColumnInfo it) => it.IsPrimarykey && it.SqlParameterDbType is Type && typeof(ISugarDataConverter).IsAssignableFrom(it.SqlParameterDbType as Type)) ?? false;
			}

			protected virtual string GetJoinUpdate(string columnsString, ref string whereString)
			{
				string translationColumnName = Builder.GetTranslationColumnName(TableName);
				TableName = Builder.GetTranslationColumnName(ShortName);
				string text = $" FROM {translationColumnName} {Builder.GetTranslationColumnName(ShortName)} ";
				foreach (JoinQueryInfo joinInfo in JoinInfos)
				{
					text += $"\r\n JOIN {Builder.GetTranslationColumnName(joinInfo.TableName)}  {Builder.GetTranslationColumnName(joinInfo.ShortName)} ON {joinInfo.JoinWhere} ";
				}
				whereString = text + "\r\n" + whereString;
				return string.Format(SqlTemplate, GetTableNameString, columnsString, whereString);
			}

			public virtual void ActionMinDate()
			{
				if (Parameters == null)
				{
					return;
				}
				foreach (SugarParameter parameter in Parameters)
				{
					if ((parameter.DbType == System.Data.DbType.Date || parameter.DbType == System.Data.DbType.DateTime) && parameter.Value != null && parameter.Value != DBNull.Value && parameter.Value is DateTime && Convert.ToDateTime(parameter.Value) == DateTime.MinValue)
					{
						parameter.Value = UtilMethods.GetMinDate(Context.CurrentConnectionConfig);
					}
				}
			}

			public virtual object FormatValue(object value)
			{
				if (value == null)
				{
					return "NULL";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType)
				{
					DateTime dateTime = value.ObjToDate();
					if (dateTime < UtilMethods.GetMinDate(Context.CurrentConnectionConfig))
					{
						dateTime = UtilMethods.GetMinDate(Context.CurrentConnectionConfig);
					}
					return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					return "0x" + BitConverter.ToString((byte[])value).Replace("-", "");
				}
				if (underType.IsEnum())
				{
					ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						return value.ToSqlValue();
					}
					return Convert.ToInt64(value);
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.DateTimeOffsetType)
				{
					return FormatDateTimeOffset(value);
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					return "N'" + value.ToString().ToSqlFilter() + "'";
				}
				if (underType == UtilConstants.IntType || underType == UtilConstants.LongType)
				{
					return value;
				}
				if (UtilMethods.IsNumber(underType.Name))
				{
					if (value is decimal num)
					{
						return num.ToString(CultureInfo.InvariantCulture);
					}
					if (value.ObjToString().Contains(","))
					{
						return $"'{value}'";
					}
					return value;
				}
				return "N'" + value.ToString() + "'";
			}

			public virtual string FormatDateTimeOffset(object value)
			{
				return "'" + UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value).ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}

			public virtual string GetDbColumn(DbColumnInfo columnInfo, object name)
			{
				if (columnInfo.UpdateServerTime)
				{
					return LambdaExpressions.DbMehtods.GetDate();
				}
				if (columnInfo.PropertyType.FullName == "NetTopologySuite.Geometries.Geometry")
				{
					string text = Builder.SqlParameterKeyWord + "Geometry" + GetDbColumnIndex;
					SugarParameter item = new SugarParameter(text, columnInfo.Value)
					{
						DbType = System.Data.DbType.Object
					};
					Parameters.Add(item);
					GetDbColumnIndex++;
					return text;
				}
				if ((columnInfo.Value is decimal || columnInfo.Value is double || columnInfo.Value is float) && UtilMethods.IsErrorDecimalString() == true)
				{
					string text2 = Builder.SqlParameterKeyWord + "Decimal" + GetDbColumnIndex;
					SugarParameter item2 = new SugarParameter(text2, columnInfo.Value);
					Parameters.Add(item2);
					GetDbColumnIndex++;
					return text2;
				}
				if (IsListSetExp(columnInfo) || IsSingleSetExp(columnInfo))
				{
					if (ReSetValueBySqlExpList[columnInfo.PropertyName].Type == ReSetValueBySqlExpListModelType.List)
					{
						return Builder.GetTranslationColumnName(columnInfo.DbColumnName) + ReSetValueBySqlExpList[columnInfo.PropertyName].Sql + name;
					}
					return ReSetValueBySqlExpList[columnInfo.PropertyName].Sql;
				}
				if (columnInfo.UpdateSql.HasValue())
				{
					if (columnInfo.UpdateSql.Contains("{0}"))
					{
						if (columnInfo.Value == null)
						{
							return string.Format(columnInfo.UpdateSql, "null").Replace("'null'", "null");
						}
						string updateSql = columnInfo.UpdateSql;
						object value = columnInfo.Value;
						return string.Format(updateSql, (value != null) ? value.ObjToString().ToSqlFilter() : null);
					}
					return columnInfo.UpdateSql;
				}
				if (columnInfo.SqlParameterDbType is Type && IsNoParameterConvert(columnInfo))
				{
					Type type = columnInfo.SqlParameterDbType as Type;
					MethodInfo methodInfo = type.GetMethod("ParameterConverter").MakeGenericMethod(typeof(string));
					object obj = Activator.CreateInstance(type);
					return (methodInfo.Invoke(obj, new object[2] { columnInfo.Value, GetDbColumnIndex }) as SugarParameter).ParameterName;
				}
				if (columnInfo.SqlParameterDbType is Type type2 && type2 == typeof(EnumToStringConvert))
				{
					SqlSugarProvider context = Context;
					if (context != null && context.CurrentConnectionConfig?.MoreSettings?.TableEnumIsString == true)
					{
						string text3 = Builder.SqlParameterKeyWord + columnInfo.PropertyName + "_str" + GetDbColumnIndex;
						SugarParameter item3 = new SugarParameter(text3, columnInfo.Value);
						Parameters.Add(item3);
						GetDbColumnIndex++;
						return text3;
					}
				}
				if (columnInfo.SqlParameterDbType is Type)
				{
					Type type3 = columnInfo.SqlParameterDbType as Type;
					MethodInfo methodInfo2 = type3.GetMethod("ParameterConverter").MakeGenericMethod(columnInfo.PropertyType);
					object obj2 = Activator.CreateInstance(type3);
					SugarParameter sugarParameter = methodInfo2.Invoke(obj2, new object[2] { columnInfo.Value, GetDbColumnIndex }) as SugarParameter;
					GetDbColumnIndex++;
					Parameters.Add(sugarParameter);
					return sugarParameter.ParameterName;
				}
				if (columnInfo.PropertyType != null && columnInfo.PropertyType.Name == "TimeOnly" && name != null && !name.ObjToString().StartsWith(Builder.SqlParameterKeyWord))
				{
					object obj3 = UtilMethods.TimeOnlyToTimeSpan(columnInfo.Value);
					string text4 = Builder.SqlParameterKeyWord + columnInfo.DbColumnName + "_ts" + GetDbColumnIndex;
					if (obj3 == null)
					{
						Parameters.Add(new SugarParameter(text4, null)
						{
							DbType = System.Data.DbType.Date
						});
					}
					else
					{
						Parameters.Add(new SugarParameter(text4, obj3));
					}
					GetDbColumnIndex++;
					return text4;
				}
				if (columnInfo.PropertyType != null && columnInfo.PropertyType.Name == "DateOnly")
				{
					object obj4 = UtilMethods.DateOnlyToDateTime(columnInfo.Value);
					string text5 = Builder.SqlParameterKeyWord + columnInfo.DbColumnName + "_ts" + GetDbColumnIndex;
					if (obj4 == null)
					{
						Parameters.Add(new SugarParameter(text5, null)
						{
							DbType = System.Data.DbType.Date
						});
					}
					else
					{
						Parameters.Add(new SugarParameter(text5, Convert.ToDateTime(obj4)));
					}
					GetDbColumnIndex++;
					return text5;
				}
				if (UtilMethods.IsErrorParameterName(Context.CurrentConnectionConfig, columnInfo))
				{
					string text6 = Builder.SqlParameterKeyWord + "CrorrPara" + GetDbColumnIndex;
					SugarParameter item4 = new SugarParameter(text6, columnInfo.Value);
					Parameters.Add(item4);
					GetDbColumnIndex++;
					return text6;
				}
				return name?.ToString() ?? "";
			}

			private static bool IsNoParameterConvert(DbColumnInfo columnInfo)
			{
				if (columnInfo.SqlParameterDbType is Type c)
				{
					bool flag = typeof(NoParameterCommonPropertyConvert).IsAssignableFrom(c);
					if (flag)
					{
						return flag;
					}
				}
				return (Type)columnInfo.SqlParameterDbType == UtilConstants.SqlConvertType;
			}

			private bool IsSingleSetExp(DbColumnInfo columnInfo)
			{
				if (ReSetValueBySqlExpList != null && ReSetValueBySqlExpList.ContainsKey(columnInfo.PropertyName) && !IsListUpdate.HasValue)
				{
					return (from it in DbColumnInfoList
						group it by it.TableId).Count() == 1;
				}
				return false;
			}

			private bool IsListSetExp(DbColumnInfo columnInfo)
			{
				if (ReSetValueBySqlExpListType != null && ReSetValueBySqlExpList != null)
				{
					return ReSetValueBySqlExpList.ContainsKey(columnInfo.PropertyName);
				}
				return false;
			}
		}
