			private void InitMappingInfo(EntityInfo entityInfo)
			{
				if (MappingTables == null)
				{
					MappingTables = new MappingTableList();
				}
				if (MappingColumns == null)
				{
					MappingColumns = new MappingColumnList();
				}
				if (IgnoreColumns == null)
				{
					IgnoreColumns = new IgnoreColumnList();
				}
				if (IgnoreInsertColumns == null)
				{
					IgnoreInsertColumns = new IgnoreColumnList();
				}
				if (!MappingTables.Any((MappingTable it) => it.EntityName == entityInfo.EntityName) && entityInfo.DbTableName != entityInfo.EntityName && entityInfo.DbTableName.HasValue())
				{
					MappingTables.Add(entityInfo.EntityName, entityInfo.DbTableName);
				}
				if (!entityInfo.Columns.Any((EntityColumnInfo it) => it.EntityName == entityInfo.EntityName))
				{
					return;
				}
				IEnumerable<MappingColumn> source = MappingColumns.Where((MappingColumn it) => it.EntityName == entityInfo.EntityName);
				foreach (EntityColumnInfo item in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore))
				{
					if (!source.Any((MappingColumn it) => it.PropertyName == item.PropertyName) && item.PropertyName != item.DbColumnName && item.DbColumnName.HasValue())
					{
						MappingColumns.Add(item.PropertyName, item.DbColumnName, item.EntityName);
					}
				}
				IEnumerable<IgnoreColumn> source2 = IgnoreColumns.Where((IgnoreColumn it) => it.EntityName == entityInfo.EntityName);
				foreach (EntityColumnInfo item2 in entityInfo.Columns.Where((EntityColumnInfo it) => it.IsIgnore))
				{
					if (!source2.Any((IgnoreColumn it) => it.PropertyName == item2.PropertyName))
					{
						IgnoreColumns.Add(item2.PropertyName, item2.EntityName);
					}
				}
				IEnumerable<IgnoreColumn> source3 = IgnoreInsertColumns.Where((IgnoreColumn it) => it.EntityName == entityInfo.EntityName);
				foreach (EntityColumnInfo item3 in entityInfo.Columns.Where((EntityColumnInfo it) => it.IsOnlyIgnoreInsert))
				{
					if (!source3.Any((IgnoreColumn it) => it.PropertyName == item3.PropertyName))
					{
						IgnoreInsertColumns.Add(item3.PropertyName, item3.EntityName);
					}
				}
			}

