			private void CheckDbDependency(ConnectionConfig config)
			{
				switch (config.DbType)
				{
				case DbType.MySql:
					DependencyManagement.TryMySqlData();
					break;
				case DbType.Sqlite:
					DependencyManagement.TrySqlite();
					break;
				case DbType.Oracle:
					DependencyManagement.TryOracle();
					break;
				default:
					throw new Exception("ConnectionConfig.DbType is null");
				case DbType.SqlServer:
					break;
				}
			}

			protected List<JoinQueryInfo> GetJoinInfos(ISqlBuilder sqlBuilder, Expression joinExpression, ref List<SugarParameter> parameters, ref string shortName, params Type[] entityTypeArray)
			{
				List<JoinQueryInfo> list = new List<JoinQueryInfo>();
				List<ParameterExpression> list2 = ((LambdaExpression)joinExpression).Parameters.ToList();
				ILambdaExpressions lambdaExpressions = sqlBuilder.QueryBuilder.LambdaExpressions;
				lambdaExpressions.MappingColumns = MappingColumns;
				lambdaExpressions.MappingTables = MappingTables;
				lambdaExpressions.IsSingle = false;
				lambdaExpressions.SugarContext = new ExpressionOutParameter
				{
					Context = Context
				};
				if (Context.CurrentConnectionConfig.MoreSettings != null)
				{
					lambdaExpressions.PgSqlIsAutoToLower = Context.CurrentConnectionConfig.MoreSettings.PgSqlIsAutoToLower;
				}
				else
				{
					lambdaExpressions.PgSqlIsAutoToLower = true;
				}
				if (Context.CurrentConnectionConfig.ConfigureExternalServices != null)
				{
					lambdaExpressions.SqlFuncServices = Context.CurrentConnectionConfig.ConfigureExternalServices.SqlFuncServices;
				}
				lambdaExpressions.Resolve(joinExpression, ResolveExpressType.Join);
				int num = 0;
				string[] array = MergeJoinArray(lambdaExpressions.Result.GetResultArray());
				if (array == null)
				{
					return null;
				}
				parameters = lambdaExpressions.Parameters;
				foreach (Type entityType in entityTypeArray)
				{
					bool num2 = num == 0;
					num++;
					JoinQueryInfo joinQueryInfo = new JoinQueryInfo();
					bool num3 = lambdaExpressions.MappingTables.HasValue();
					MappingTable mappingTable = null;
					if (num3)
					{
						mappingTable = lambdaExpressions.MappingTables.FirstOrDefault((MappingTable it) => it.EntityName.Equals(entityType.Name, StringComparison.CurrentCultureIgnoreCase));
						joinQueryInfo.TableName = ((mappingTable != null) ? mappingTable.DbTableName : entityType.Name);
					}
					else
					{
						joinQueryInfo.TableName = entityType.Name;
					}
					ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
					bool flag = moreSettings != null && !moreSettings.PgSqlIsAutoToLower;
					if (num2)
					{
						ParameterExpression parameterExpression = list2.First();
						list2.Remove(parameterExpression);
						shortName = parameterExpression.Name;
						if (flag)
						{
							shortName = sqlBuilder.GetTranslationColumnName(shortName);
						}
					}
					string value = array[num * 2 - 2];
					joinQueryInfo.ShortName = list2[num - 1].Name;
					joinQueryInfo.JoinType = (JoinType)Enum.Parse(typeof(JoinType), value);
					joinQueryInfo.JoinWhere = array[num * 2 - 1];
					joinQueryInfo.JoinIndex = num;
					joinQueryInfo.EntityType = entityType;
					if (flag)
					{
						joinQueryInfo.ShortName = sqlBuilder.GetTranslationColumnName(joinQueryInfo.ShortName);
					}
					list.Add(joinQueryInfo);
				}
				lambdaExpressions.Clear();
				return list;
			}

			private string[] MergeJoinArray(string[] joinArray)
			{
				List<string> list = new List<string>();
				string text = null;
				int num = 0;
				if (joinArray == null)
				{
					return null;
				}
				foreach (string text2 in joinArray)
				{
					num++;
					bool flag = joinArray.Length == num;
					if (text2.IsIn(JoinType.Full.ToString(), JoinType.Inner.ToString(), JoinType.Left.ToString(), JoinType.Right.ToString(), JoinType.Cross.ToString()))
					{
						if (text != null)
						{
							list.Add(text);
						}
						text = null;
						list.Add(text2);
					}
					else
					{
						text += ((text == null) ? text2 : ("," + text2));
					}
					if (flag)
					{
						list.Add(text);
					}
				}
				return list.ToArray();
			}

			protected Dictionary<string, string> GetEasyJoinInfo(Expression joinExpression, ref string shortName, ISqlBuilder builder, params Type[] entityTypeArray)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				List<ParameterExpression> list = ((LambdaExpression)joinExpression).Parameters.ToList();
				shortName = list.First().Name;
				ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
				bool flag = moreSettings != null && !moreSettings.PgSqlIsAutoToLower;
				int num = 1;
				foreach (Type type in entityTypeArray)
				{
					if (flag)
					{
						dictionary.Add(" " + builder.GetTranslationColumnName(list[num].Name), type.Name);
					}
					else
					{
						dictionary.Add(" " + list[num].Name, type.Name);
					}
					num++;
				}
				return dictionary;
			}

			public SqlSugarProvider(ConnectionConfig config)
			{
				Context = this;
				CurrentConnectionConfig = config;
				ContextID = Guid.NewGuid();
				Check.ArgumentNullException(config, "config is null");
				CheckDbDependency(config);
				if (StaticConfig.CompleteDbFunc != null)
				{
					if (CurrentConnectionConfig.AopEvents == null)
					{
						CurrentConnectionConfig.AopEvents = new AopEvents();
					}
					StaticConfig.CompleteDbFunc(this);
				}
			}

