			/// <summary>
			/// Get datebase time
			/// </summary>
			/// <returns></returns>
			public DateTime GetDate()
			{
				ISqlBuilder sqlbuilder = InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig);
				sqlbuilder.Context = Context;
				object scalar = Ado.GetScalar(sqlbuilder.FullSqlDateNow);
				if (scalar is DateTime)
				{
					return (DateTime)scalar;
				}
				if (scalar is DateTimeOffset dateTime)
				{
					return UtilMethods.ConvertFromDateTimeOffset(dateTime);
				}
				return Convert.ToDateTime(scalar);
			}

