			internal ISugarQueryable<T> _UnionAll<T>(ISugarQueryable<T>[] queryables)
			{
				ISqlBuilder sqlbuilder = InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig);
				Check.Exception(queryables.IsNullOrEmpty(), "UnionAll.queryables is null ");
				int num = 1;
				List<KeyValuePair<string, List<SugarParameter>>> list = new List<KeyValuePair<string, List<SugarParameter>>>();
				for (int i = 0; i < queryables.Length; i++)
				{
					KeyValuePair<string, List<SugarParameter>> keyValuePair = queryables[i].ToSql();
					string appendSql = keyValuePair.Key;
					ConnectionConfig currentConnectionConfig = CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.MaxParameterNameLength > 0)
					{
						UtilMethods.RepairReplicationParameters(Context, ref appendSql, keyValuePair.Value.ToArray(), num, "UnionAll");
					}
					else
					{
						UtilMethods.RepairReplicationParameters(ref appendSql, keyValuePair.Value.ToArray(), num, "UnionAll");
					}
					if (keyValuePair.Value.HasValue())
					{
						list.Add(new KeyValuePair<string, List<SugarParameter>>(sqlbuilder.GetUnionFomatSql(appendSql), keyValuePair.Value));
					}
					else
					{
						list.Add(new KeyValuePair<string, List<SugarParameter>>(sqlbuilder.GetUnionFomatSql(appendSql), new List<SugarParameter>()));
					}
					num++;
				}
				string unionAllSql = sqlbuilder.GetUnionAllSql(list.Select((KeyValuePair<string, List<SugarParameter>> it) => it.Key).ToList());
				SugarParameter[] parameters = list.SelectMany((KeyValuePair<string, List<SugarParameter>> it) => it.Value).ToArray();
				ISugarQueryable<object> sugarQueryable = Context.Queryable<object>().AS(UtilMethods.GetPackTable(unionAllSql, "unionTable")).With("Non");
				sugarQueryable.AddParameters(parameters);
				if (Context.CurrentConnectionConfig.DbType == DbType.Oracle && sqlbuilder.SqlSelectAll == "*")
				{
					return sugarQueryable.Select<T>("unionTable.*");
				}
				ConnectionConfig currentConnectionConfig2 = Context.CurrentConnectionConfig;
				if (currentConnectionConfig2 != null && currentConnectionConfig2.MoreSettings?.IsWithNoLockQuery == true)
				{
					return sugarQueryable.Select<T>(sqlbuilder.SqlSelectAll).With("Non");
				}
				return sugarQueryable.Select<T>(sqlbuilder.SqlSelectAll);
			}

