			public InsertMethodInfo InsertableByObject(object singleEntityObjectOrListObject)
			{
				if (singleEntityObjectOrListObject == null)
				{
					return new InsertMethodInfo();
				}
				if (singleEntityObjectOrListObject.GetType().FullName.IsCollectionsList())
				{
					IList list = (IList)singleEntityObjectOrListObject;
					if (list == null || list.Count == 0)
					{
						return new InsertMethodInfo();
					}
					Type type = list[0].GetType();
					IList list2 = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(type));
					foreach (object item in list)
					{
						list2.Add(item);
					}
					MethodInfo methodInfo = (from it in Context.GetType().GetMethods()
						where it.Name == "Insertable"
						where it.GetGenericArguments().Any()
						where it.GetParameters().Any((ParameterInfo z) => z.ParameterType.Name.StartsWith("List"))
						where it.Name == "Insertable"
						select it).ToList().Single().MakeGenericMethod(list2.GetType().GetGenericArguments().First());
					return new InsertMethodInfo
					{
						Context = Context,
						MethodInfo = methodInfo,
						objectValue = list2
					};
				}
				MethodInfo methodInfo2 = (from it in Context.GetType().GetMethods()
					where it.Name == "Insertable"
					where it.GetGenericArguments().Any()
					where it.GetParameters().Any((ParameterInfo z) => z.ParameterType.Name == "T")
					where it.Name == "Insertable"
					select it).ToList().Single().MakeGenericMethod(singleEntityObjectOrListObject.GetType());
				return new InsertMethodInfo
				{
					Context = Context,
					MethodInfo = methodInfo2,
					objectValue = singleEntityObjectOrListObject
				};
			}

