			public GridSaveProvider<T> GridSave<T>(List<T> saveList) where T : class, new()
			{
				Check.ExceptionEasy(saveList == null, "saveList is null", "saveList 不能是 null");
				Check.ExceptionEasy(Context.TempItems == null || !Context.TempItems.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key == "OldData_" + saveList.GetHashCode()), "saveList no tracking", "saveList 没有使用跟踪");
				List<T> oldList = (List<T>)Context.TempItems.FirstOrDefault<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key == "OldData_" + saveList.GetHashCode()).Value;
				return GridSave(oldList, saveList);
			}

