			public RepositoryType GetRepository<RepositoryType>() where RepositoryType : ISugarRepository, new()
			{
				Type typeFromHandle = typeof(RepositoryType);
				bool num = typeFromHandle.GetConstructors().Any((ConstructorInfo z) => z.GetParameters().Any());
				object obj = null;
				if (num)
				{
					object[] args = new string[1];
					obj = Activator.CreateInstance(typeFromHandle, args);
				}
				else
				{
					obj = Activator.CreateInstance(typeFromHandle);
				}
				RepositoryType result = (RepositoryType)obj;
				if (result.Context == null)
				{
					result.Context = Context;
				}
				return result;
			}

			public virtual void Close()
			{
				if (Context.Ado != null)
				{
					Context.Ado.Close();
				}
			}

			public virtual void Open()
			{
				if (Context.Ado != null)
				{
					Context.Ado.Open();
				}
			}

			public virtual void Dispose()
			{
				if (Context.Ado != null)
				{
					Context.Ado.Dispose();
				}
			}

