			public void AddQueue(string sql, object parsmeters = null)
			{
				if (Queues == null)
				{
					Queues = new QueueList();
				}
				SugarParameter[] parameters = Context.Ado.GetParameters(parsmeters);
				if (parameters != null)
				{
					SugarParameter[] array = parameters;
					foreach (SugarParameter sugarParameter in array)
					{
						if (sugarParameter.ParameterName.StartsWith(":"))
						{
							sugarParameter.ParameterName = "@" + sugarParameter.ParameterName.Trim(':');
						}
					}
				}
				Queues.Add(sql, parameters);
			}

