			private async Task<T> SaveQueuesProviderAsync<T>(bool isTran, Func<string, List<SugarParameter>, Task<T>> func)
			{
				try
				{
					if (Queues == null || Queues.Count == 0)
					{
						return default(T);
					}
					isTran = isTran && Ado.Transaction == null;
					if (isTran)
					{
						Ado.BeginTran();
					}
					StringBuilder stringBuilder = new StringBuilder();
					List<SugarParameter> list = new List<SugarParameter>();
					int num = 1;
					if (Queues.HasValue())
					{
						IEnumerable<IGrouping<string, string>> source = from it in Queues.SelectMany((QueueItem it) => it.Parameters ?? new SugarParameter[0])
							select it.ParameterName into it
							group it by it?.ToLower() into it
							where it.Count() > 1
							select it;
						int num2 = source.Count();
						bool flag = source.Count() > 0;
						foreach (QueueItem queue in Queues)
						{
							if (queue.Sql == null)
							{
								queue.Sql = string.Empty;
							}
							if (queue.Parameters == null)
							{
								queue.Parameters = new SugarParameter[0];
							}
							List<SugarParameter> list2 = queue.Parameters.OrderByDescending((SugarParameter it) => it.ParameterName.Length).ToList();
							List<SugarParameter> list3 = new List<SugarParameter>();
							string text = queue.Sql;
							foreach (SugarParameter itemParameter in list2)
							{
								string text2 = itemParameter.ParameterName + "_q_" + num;
								SugarParameter sugarParameter = new SugarParameter(text2, itemParameter.Value);
								sugarParameter.DbType = itemParameter.DbType;
								if (num2 > 500 || (flag && source.Any((IGrouping<string, string> it) => it.Key.EqualCase(itemParameter.ParameterName))))
								{
									if (text2.StartsWith(":") && text.ToLower().Contains(itemParameter.ParameterName.ToLower().Replace(":", "@")))
									{
										itemParameter.ParameterName = itemParameter.ParameterName.Replace(":", "@");
									}
									text = UtilMethods.ReplaceSqlParameter(text, itemParameter, text2);
									list3.Add(sugarParameter);
								}
								else
								{
									sugarParameter.ParameterName = itemParameter.ParameterName;
									list3.Add(sugarParameter);
								}
							}
							list.AddRange(list3);
							text = text.TrimEnd('\r').TrimEnd('\n').TrimEnd('\r')
								.TrimEnd('\n')
								.TrimEnd(';') + ";";
							if (text == "begin;")
							{
								text = text.TrimEnd(';') + "\n";
							}
							stringBuilder.AppendLine(text);
							num++;
						}
					}
					Queues.Clear();
					InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig).FormatSaveQueueSql(stringBuilder);
					T result = await func(stringBuilder.ToString(), list);
					if (isTran)
					{
						Ado.CommitTran();
					}
					return result;
				}
				catch (Exception ex)
				{
					if (isTran)
					{
						Ado.RollbackTran();
					}
					throw ex;
				}
			}

			private T SaveQueuesProvider<T>(bool isTran, Func<string, List<SugarParameter>, T> func)
			{
				try
				{
					if (Queues == null || Queues.Count == 0)
					{
						return default(T);
					}
					isTran = isTran && Ado.Transaction == null;
					if (isTran)
					{
						Ado.BeginTran();
					}
					StringBuilder stringBuilder = new StringBuilder();
					List<SugarParameter> list = new List<SugarParameter>();
					int num = 1;
					if (Queues.HasValue())
					{
						IEnumerable<IGrouping<string, string>> source = from it in Queues.SelectMany((QueueItem it) => it.Parameters ?? new SugarParameter[0])
							select it.ParameterName into it
							group it by it?.ToLower() into it
							where it.Count() > 1
							select it;
						int num2 = source.Count();
						bool flag = source.Count() > 0;
						foreach (QueueItem queue in Queues)
						{
							if (queue.Sql == null)
							{
								queue.Sql = string.Empty;
							}
							if (queue.Parameters == null)
							{
								queue.Parameters = new SugarParameter[0];
							}
							List<SugarParameter> list2 = queue.Parameters.OrderByDescending((SugarParameter it) => it.ParameterName.Length).ToList();
							List<SugarParameter> list3 = new List<SugarParameter>();
							string text = queue.Sql;
							foreach (SugarParameter itemParameter in list2)
							{
								string text2 = itemParameter.ParameterName + "_q_" + num;
								SugarParameter sugarParameter = new SugarParameter(text2, itemParameter.Value);
								sugarParameter.DbType = itemParameter.DbType;
								if (num2 > 500 || (flag && source.Any((IGrouping<string, string> it) => it.Key.EqualCase(itemParameter.ParameterName))))
								{
									if (text2.StartsWith(":") && text.ToLower().Contains(itemParameter.ParameterName.ToLower().Replace(":", "@")))
									{
										itemParameter.ParameterName = itemParameter.ParameterName.Replace(":", "@");
									}
									text = UtilMethods.ReplaceSqlParameter(text, itemParameter, text2);
								}
								else
								{
									sugarParameter.ParameterName = itemParameter.ParameterName;
								}
								list3.Add(sugarParameter);
							}
							list.AddRange(list3);
							text = text.TrimEnd('\r').TrimEnd('\n').TrimEnd('\r')
								.TrimEnd('\n')
								.TrimEnd(';') + ";";
							if (text != null && text.StartsWith("INSERT INTO ") && text != null && text.EndsWith(" returning ;"))
							{
								text = text.Replace(" returning ;", " ;");
							}
							if (text == "begin;")
							{
								text = text.TrimEnd(';') + "\n";
							}
							stringBuilder.AppendLine(text);
							num++;
						}
					}
					Queues.Clear();
					InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig).FormatSaveQueueSql(stringBuilder);
					T result = func(stringBuilder.ToString(), list);
					if (isTran)
					{
						Ado.CommitTran();
					}
					return result;
				}
				catch (Exception ex)
				{
					if (isTran)
					{
						Ado.RollbackTran();
					}
					throw ex;
				}
			}

