			public void Tracking<T>(T data) where T : class, new()
			{
				if (data != null)
				{
					UtilMethods.IsNullReturnNew(TempItems);
					string key = "Tracking_" + data.GetHashCode();
					if (!TempItems.ContainsKey(key))
					{
						T val = new T();
						FastCopy.Copy(data, val);
						TempItems.Add(key, val);
					}
				}
			}

			public void ClearTracking()
			{
				if (Context.TempItems == null)
				{
					return;
				}
				foreach (string item in (from it in Context.TempItems
					where it.Key.StartsWith("Tracking_") || it.Key.StartsWith("OldData_")
					select it.Key).ToList())
				{
					Context.TempItems.Remove(item);
				}
			}

			public void Tracking<T>(List<T> datas) where T : class, new()
			{
				foreach (T data in datas)
				{
					Tracking(data);
				}
				if (datas != null)
				{
					Check.ExceptionEasy(Context.TempItems.ContainsKey("OldData_" + datas.GetHashCode()), "The object already has a trace", "对象已存在跟踪,如果要在跟踪可以先清除 db.ClearTracking() ");
					Context.TempItems.Add("OldData_" + datas.GetHashCode(), datas.Cast<T>().ToList());
				}
			}

			public SqlSugarClient CopyNew()
			{
				SqlSugarClient sqlSugarClient = new SqlSugarClient(UtilMethods.CopyConfig(Ado.Context.CurrentConnectionConfig));
				sqlSugarClient.QueryFilter = QueryFilter;
				sqlSugarClient.Ado.CommandTimeOut = Ado.CommandTimeOut;
				return sqlSugarClient;
			}

			public void ThenMapper<T>(IEnumerable<T> list, Action<T> action)
			{
				Context.Utilities.PageEach(list, 200, delegate(List<T> pageList)
				{
					_ThenMapper(pageList, action);
				});
			}

			public async Task ThenMapperAsync<T>(IEnumerable<T> list, Func<T, Task> action)
			{
				await Context.Utilities.PageEachAsync(list, 200, async delegate(List<T> pageList)
				{
					await _ThenMapperAsync(pageList, action);
				});
			}
		}
