			protected virtual SqlSugarClient GetContext()
			{
				SqlSugarClient sqlSugarClient = null;
				string text = _configs.GetHashCode().ToString();
				StackFrame[] frames = new StackTrace(fNeedFileInfo: true).GetFrames();
				bool flag = UtilMethods.IsAnyAsyncMethod(frames);
				if (frames.Length >= 0)
				{
					foreach (StackFrame item in frames.Take(35))
					{
						Type type = item.GetMethod()?.ReflectedType;
						if (type != null)
						{
							Type[] array = ((!type.Name.StartsWith("<")) ? type?.GetInterfaces() : type?.ReflectedType?.GetInterfaces());
							if (array != null && array.Any((Type it) => it.Name.IsIn("IJob")))
							{
								text += "IJob";
								break;
							}
						}
					}
				}
				if (flag)
				{
					return GetAsyncContext(text);
				}
				return GetThreadContext(text);
			}

			private SqlSugarClient GetAsyncContext(string key)
			{
				SqlSugarClient data = CallContextAsync<SqlSugarClient>.GetData(key);
				if (data == null)
				{
					List<ConnectionConfig> copyConfigs = GetCopyConfigs();
					CallContextAsync<SqlSugarClient>.SetData(key, new SqlSugarClient(copyConfigs));
					data = CallContextAsync<SqlSugarClient>.GetData(key);
					if (_configAction != null)
					{
						_configAction(data);
					}
				}
				return data;
			}

			private SqlSugarClient GetThreadContext(string key)
			{
				SqlSugarClient data = CallContextThread<SqlSugarClient>.GetData(key);
				if (data == null)
				{
					List<ConnectionConfig> copyConfigs = GetCopyConfigs();
					CallContextThread<SqlSugarClient>.SetData(key, new SqlSugarClient(copyConfigs));
					data = CallContextThread<SqlSugarClient>.GetData(key);
					if (_configAction != null)
					{
						_configAction(data);
					}
				}
				return data;
			}

			private List<ConnectionConfig> GetCopyConfigs()
			{
				return _configs.Select((ConnectionConfig it) => UtilMethods.CopyConfig(it)).ToList();
			}

