			public SqlSugarClient CopyNew()
			{
				SqlSugarClient sqlSugarClient = new SqlSugarClient(UtilMethods.CopyConfig(Ado.Context.CurrentConnectionConfig));
				sqlSugarClient.QueryFilter = QueryFilter;
				if (ScopedContext._AllClients != null)
				{
					foreach (SugarTenant allClient in ScopedContext._AllClients)
					{
						if (!sqlSugarClient.IsAnyConnection(allClient.ConnectionConfig.ConfigId))
						{
							sqlSugarClient.AddConnection(UtilMethods.CopyConfig(allClient.ConnectionConfig));
						}
					}
				}
				return sqlSugarClient;
			}

