			public SqlSugarScopeProvider(SqlSugarProvider conn)
			{
				this.conn = conn;
				initThreadMainId = GetCurrentThreadId();
				string key = GetKey();
				initkey = key;
				GetContext(isInit: true);
			}

			private static string GetCurrentThreadId()
			{
				return Thread.CurrentThread.ManagedThreadId.ToString() ?? "";
			}

			private SqlSugarProvider GetAsyncContext(bool isInit = false)
			{
				if (isInit)
				{
					CallContextAsync<SqlSugarProvider>.SetData(GetKey(), conn);
					isInit = false;
					return conn;
				}
				SqlSugarProvider data = CallContextAsync<SqlSugarProvider>.GetData(GetKey());
				if (data == null)
				{
					SqlSugarProvider sqlSugarProvider = new SqlSugarProvider(conn.CurrentConnectionConfig);
					CallContextAsync<SqlSugarProvider>.SetData(GetKey(), sqlSugarProvider);
					return sqlSugarProvider;
				}
				return data;
			}

			private SqlSugarProvider GetThreadContext(bool isInit = false)
			{
				if (isInit)
				{
					CallContextThread<SqlSugarProvider>.SetData(GetKey(), conn);
					isInit = false;
					return conn;
				}
				SqlSugarProvider data = CallContextThread<SqlSugarProvider>.GetData(GetKey());
				if (data == null)
				{
					SqlSugarProvider sqlSugarProvider = new SqlSugarProvider(conn.CurrentConnectionConfig);
					CallContextThread<SqlSugarProvider>.SetData(GetKey(), sqlSugarProvider);
					return sqlSugarProvider;
				}
				return data;
			}

			protected virtual SqlSugarProvider GetContext(bool isInit = false)
			{
				SqlSugarProvider sqlSugarProvider = null;
				GetKey();
				if (UtilMethods.IsAnyAsyncMethod(new StackTrace(fNeedFileInfo: true).GetFrames()))
				{
					return GetAsyncContext(isInit);
				}
				return GetThreadContext(isInit);
			}

			private string GetKey()
			{
				if (!string.IsNullOrEmpty(initkey) && initThreadMainId == GetCurrentThreadId())
				{
					return initkey;
				}
				string text = "SqlSugarProviderScope_" + conn.CurrentConnectionConfig.ConfigId;
				if (frames == null)
				{
					frames = new StackTrace(fNeedFileInfo: true).GetFrames();
				}
				if (frames.Length >= 0)
				{
					foreach (StackFrame item in frames.Take(35))
					{
						Type type = item.GetMethod()?.ReflectedType;
						if (type != null)
						{
							Type[] array = ((!type.Name.StartsWith("<")) ? type?.GetInterfaces() : type?.ReflectedType?.GetInterfaces());
							if (array != null && array.Any((Type it) => it.Name.IsIn("IJob")))
							{
								text += "IJob";
								break;
							}
						}
					}
				}
				return text;
			}

