		public class ParameterUpdateable<T> where T : class, new()
		{
			internal UpdateableProvider<T> Updateable { get; set; }

			internal SqlSugarProvider Context { get; set; }

			public int ExecuteCommand()
			{
				int result = 0;
				T[] updateObjs = Updateable.UpdateObjs;
				int num = updateObjs.Length;
				int pageSize = GetPageSize(20, num);
				Context.Utilities.PageEach(updateObjs.ToList(), pageSize, delegate(List<T> item)
				{
					Before(item.ToList());
					new List<SugarParameter>();
					KeyValuePair<string, SugarParameter[]> sql = GetSql(item);
					result += Context.Ado.ExecuteCommand(sql.Key, sql.Value);
					After(item.ToList());
				});
				if (result >= 0)
				{
					return result;
				}
				return num;
			}

			public async Task<int> ExecuteCommandAsync()
			{
				int result = 0;
				T[] updateObjs = Updateable.UpdateObjs;
				int count = updateObjs.Length;
				int pageSize = GetPageSize(20, count);
				await Context.Utilities.PageEachAsync(updateObjs.ToList(), pageSize, async delegate(List<T> item)
				{
					Before(item.ToList());
					new List<SugarParameter>();
					KeyValuePair<string, SugarParameter[]> sql = GetSql(item);
					int num = result;
					result = num + await Context.Ado.ExecuteCommandAsync(sql.Key, sql.Value);
					After(item.ToList());
				});
				return (result < 0) ? count : result;
			}

			private void Before(List<T> updateObjects)
			{
				if (Updateable.IsEnableDiffLogEvent && updateObjects.Count > 0)
				{
					bool isDisableMasterSlaveSeparation = Updateable.Ado.IsDisableMasterSlaveSeparation;
					Updateable.Ado.IsDisableMasterSlaveSeparation = true;
					List<SugarParameter> list = Updateable.UpdateBuilder.Parameters;
					if (list == null)
					{
						list = new List<SugarParameter>();
					}
					Updateable.diffModel.BeforeData = GetDiffTable(updateObjects);
					Updateable.diffModel.Sql = Updateable.UpdateBuilder.ToSqlString();
					Updateable.diffModel.Parameters = list.ToArray();
					Updateable.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
				}
			}

			protected void After(List<T> updateObjects)
			{
				if (Updateable.IsEnableDiffLogEvent && updateObjects.Count > 0)
				{
					bool isDisableMasterSlaveSeparation = Updateable.Ado.IsDisableMasterSlaveSeparation;
					Updateable.Ado.IsDisableMasterSlaveSeparation = true;
					Updateable.diffModel.AfterData = GetDiffTable(updateObjects);
					Updateable.diffModel.Time = Context.Ado.SqlExecutionTime;
					if (Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent != null)
					{
						Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent(Updateable.diffModel);
					}
					Updateable.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
				}
				if (Updateable.RemoveCacheFunc != null)
				{
					Updateable.RemoveCacheFunc();
				}
			}

			private List<DiffLogTableInfo> GetDiffTable(List<T> updateObjects)
			{
				string translationColumnName = Updateable.UpdateBuilder.Builder.GetTranslationColumnName(Updateable.UpdateBuilder.TableName);
				List<string> list = Updateable.WhereColumnList ?? Updateable.UpdateBuilder.PrimaryKeys;
				if (list == null)
				{
					list = (from it in Updateable.UpdateBuilder.DbColumnInfoList
						where it.IsPrimarykey
						select it.DbColumnName).Distinct().ToList();
				}
				SqlSugarClient sqlSugarClient = Context.CopyNew();
				sqlSugarClient.Aop.DataExecuting = null;
				List<DbColumnInfo> dbColumnInfoList = sqlSugarClient.Updateable(updateObjects).UpdateBuilder.DbColumnInfoList;
				List<SugarParameter> list2 = new List<SugarParameter>();
				StringBuilder stringBuilder = new StringBuilder();
				string value = string.Join(",", dbColumnInfoList.Select((DbColumnInfo x) => x.DbColumnName).Distinct().ToList());
				foreach (IGrouping<int, DbColumnInfo> item in from it in dbColumnInfoList
					group it by it.TableId)
				{
					StringBuilder stringBuilder2 = new StringBuilder();
					StringBuilder stringBuilder3;
					StringBuilder.AppendInterpolatedStringHandler handler;
					foreach (string whereItem in list)
					{
						DbColumnInfo dbColumnInfo = item.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(whereItem));
						string value2 = FormatValue(dbColumnInfo.PropertyType, dbColumnInfo.DbColumnName, dbColumnInfo.Value, list2);
						stringBuilder3 = stringBuilder2;
						StringBuilder stringBuilder4 = stringBuilder3;
						handler = new StringBuilder.AppendInterpolatedStringHandler(8, 2, stringBuilder3);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(dbColumnInfo.DbColumnName);
						handler.AppendLiteral(" = ");
						handler.AppendFormatted(value2);
						handler.AppendLiteral(" AND");
						stringBuilder4.Append(ref handler);
					}
					stringBuilder3 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder3;
					handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder3);
					handler.AppendLiteral(" ");
					handler.AppendFormatted(Regex.Replace(stringBuilder2.ToString(), "AND$", ""));
					handler.AppendLiteral(" OR");
					stringBuilder5.Append(ref handler);
				}
				string sql = $"SELECT {value} FROM {translationColumnName} WHERE {Regex.Replace(stringBuilder.ToString(), "OR$", "")}";
				DataTable dataTable = sqlSugarClient.Ado.GetDataTable(sql, list2);
				return Updateable.GetTableDiff(dataTable);
			}

			public KeyValuePair<string, SugarParameter[]> GetSql(List<T> updateObjects)
			{
				UpdateableProvider<T> updateable = Updateable;
				ISqlBuilder builder = updateable.UpdateBuilder.Builder;
				(from it in updateable.UpdateBuilder.DbColumnInfoList
					group it by it.DbColumnName into it
					select it.Key).Distinct().ToList();
				string translationColumnName = builder.GetTranslationColumnName(updateable.UpdateBuilder.TableName);
				List<string> list = updateable.WhereColumnList ?? updateable.UpdateBuilder.PrimaryKeys;
				if (list == null)
				{
					list = (from it in updateable.UpdateBuilder.DbColumnInfoList
						where it.IsPrimarykey
						select it.DbColumnName).Distinct().ToList();
				}
				StringBuilder stringBuilder = new StringBuilder();
				string format = " UPDATE " + translationColumnName + " SET {0}  WHERE {1};\r\n";
				List<SugarParameter> list2 = new List<SugarParameter>();
				Check.ExceptionEasy(list == null || !list.Any(), "Updates cannot be without a primary key or condition", "更新不能没有主键或者条件");
				SqlSugarClient sqlSugarClient = Context.CopyNew();
				sqlSugarClient.Aop.DataExecuting = null;
				foreach (IGrouping<int, DbColumnInfo> item in from it in sqlSugarClient.Updateable(updateObjects).UpdateBuilder.DbColumnInfoList
					group it by it.TableId)
				{
					Check.ExceptionEasy(item == null || item.ToList()?.Any() != true, "Set has no columns", "更新Set没有列");
					StringBuilder stringBuilder2 = new StringBuilder();
					foreach (DbColumnInfo setItem in item.ToList())
					{
						if (setItem.IsPrimarykey)
						{
							continue;
						}
						List<string> updateColumns = Updateable.UpdateBuilder.UpdateColumns;
						if (updateColumns == null || !updateColumns.Any() || Updateable.UpdateBuilder.UpdateColumns.Any((string it) => it.EqualCase(setItem.DbColumnName)))
						{
							List<string> ignoreColumns = Updateable.UpdateBuilder.IgnoreColumns;
							if (ignoreColumns == null || !ignoreColumns.Any() || !Updateable.UpdateBuilder.IgnoreColumns.Any((string it) => it.EqualCase(setItem.DbColumnName)))
							{
								string value = FormatValue(setItem.PropertyType, setItem.DbColumnName, setItem.Value, list2);
								StringBuilder stringBuilder3 = stringBuilder2;
								StringBuilder stringBuilder4 = stringBuilder3;
								StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 2, stringBuilder3);
								handler.AppendLiteral(" ");
								handler.AppendFormatted(builder.GetTranslationColumnName(setItem.DbColumnName));
								handler.AppendLiteral(" = ");
								handler.AppendFormatted(value);
								handler.AppendLiteral(" ,");
								stringBuilder4.Append(ref handler);
							}
						}
					}
					StringBuilder stringBuilder5 = new StringBuilder();
					foreach (string whereItem in list)
					{
						DbColumnInfo dbColumnInfo = item.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(whereItem));
						string value2 = FormatValue(dbColumnInfo.PropertyType, dbColumnInfo.DbColumnName, dbColumnInfo.Value, list2);
						StringBuilder stringBuilder3 = stringBuilder5;
						StringBuilder stringBuilder6 = stringBuilder3;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(8, 2, stringBuilder3);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(dbColumnInfo.DbColumnName);
						handler.AppendLiteral(" = ");
						handler.AppendFormatted(value2);
						handler.AppendLiteral(" AND");
						stringBuilder6.Append(ref handler);
					}
					string value3 = string.Format(format, stringBuilder2.ToString().TrimEnd(','), stringBuilder5.ToString().TrimEnd('D').TrimEnd('N')
						.TrimEnd('A'));
					stringBuilder.Append(value3);
				}
				builder.FormatSaveQueueSql(stringBuilder);
				return new KeyValuePair<string, SugarParameter[]>(stringBuilder.ToString(), list2.ToArray());
			}

			private int GetPageSize(int pageSize, int count)
			{
				int? num = (from it in Updateable.UpdateBuilder.DbColumnInfoList
					group it by it.TableId)?.FirstOrDefault()?.Count();
				if (num > 100)
				{
					pageSize = 20;
				}
				else if (num > 60)
				{
					pageSize = 30;
				}
				else if (num > 40)
				{
					pageSize = 50;
				}
				return pageSize;
			}

			private string FormatValue(Type type, string name, object value, List<SugarParameter> allParamter)
			{
				string text = Updateable.UpdateBuilder.Builder.SqlParameterKeyWord + name + allParamter.Count;
				SugarParameter item = new SugarParameter(text, value, type);
				allParamter.Add(item);
				return text;
			}
		}
		public class SplitTableUpdateByObjectProvider<T> where T : class, new()
