			public async Task<int> ExecuteCommandWithOptLockAsync(bool isThrowError = false)
			{
				GroupDataList(UpdateObjects, out List<GroupModel> groupModels, out int result);
				Action<object, DataFilterModel> dataEvent = Context.CurrentConnectionConfig.AopEvents?.DataExecuting;
				Context.Aop.DataExecuting = null;
				foreach (IGrouping<string, GroupModel> item in from it in groupModels
					group it by it.GroupName)
				{
					List<T> list = item.Select((GroupModel it) => it.Item).ToList();
					if (IsVersion())
					{
						Check.ExceptionEasy(list.Count > 1, "The version number can only be used for single record updates", "版本号只能用于单条记录更新");
						int num = result;
						result = num + await Context.Updateable(list.First()).WhereColumns(WhereColumns?.ToArray()).EnableDiffLogEventIF(IsEnableDiffLogEvent, BusinessData)
							.UpdateColumns(updateobj.UpdateBuilder.UpdateColumns?.ToArray())
							.IgnoreColumns(updateobj.UpdateBuilder.IsNoUpdateNull, updateobj.UpdateBuilder.IsOffIdentity, updateobj.UpdateBuilder.IsNoUpdateDefaultValue)
							.IgnoreColumns(GetIgnoreColumns())
							.AS(item.Key)
							.ExecuteCommandWithOptLockAsync(isThrowError);
					}
					else
					{
						int num = result;
						result = num + await Context.Updateable(list).WhereColumns(WhereColumns?.ToArray()).EnableDiffLogEventIF(IsEnableDiffLogEvent, BusinessData)
							.UpdateColumns(updateobj.UpdateBuilder.UpdateColumns?.ToArray())
							.IgnoreColumns(updateobj.UpdateBuilder.IsNoUpdateNull, updateobj.UpdateBuilder.IsOffIdentity, updateobj.UpdateBuilder.IsNoUpdateDefaultValue)
							.IgnoreColumns(GetIgnoreColumns())
							.AS(item.Key)
							.ExecuteCommandWithOptLockAsync(isThrowError);
					}
				}
				Context.Aop.DataExecuting = dataEvent;
				return result;
			}

			private string[] GetIgnoreColumns()
			{
				if (updateobj.UpdateBuilder.DbColumnInfoList.Any())
				{
					List<string> columns = updateobj.UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.DbColumnName).Distinct().ToList();
					return (from it in (from it in Context.EntityMaintenance.GetEntityInfo<T>().Columns
							where !columns.Any((string y) => y.EqualCase(it.DbColumnName))
							select it.DbColumnName).ToArray()
						where !string.IsNullOrEmpty(it)
						select it).ToArray();
				}
				return null;
			}

			private void GroupDataList(T[] datas, out List<GroupModel> groupModels, out int result)
			{
				SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
				Check.Exception(customAttribute == null, typeof(T).Name + " need SplitTableAttribute");
				groupModels = new List<GroupModel>();
				SqlSugarProvider context = Context;
				foreach (T val in datas)
				{
					object value = context.SplitHelper<T>().GetValue(customAttribute.SplitType, val);
					string tableName = context.SplitHelper<T>().GetTableName(customAttribute.SplitType, value);
					groupModels.Add(new GroupModel
					{
						GroupName = tableName,
						Item = val
					});
				}
				result = 0;
			}

			private bool IsVersion()
			{
				return Context.EntityMaintenance.GetEntityInfo<T>().Columns.Any((EntityColumnInfo it) => it.IsEnableUpdateVersionValidation);
			}
		}
		public class SplitTableUpdateProvider<T> where T : class, new()
		{
			public SqlSugarProvider Context;

			public UpdateableProvider<T> updateobj;

			public IEnumerable<SplitTableInfo> Tables { get; set; }

			public int ExecuteCommandWithOptLock(bool isThrowError = false)
			{
				T[] updateObjs = updateobj.UpdateObjs;
				string tableName = Context.SplitHelper(updateObjs.FirstOrDefault()).GetTableName();
				string[] columns = updateobj.UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.DbColumnName).Distinct().ToArray();
				return Context.Updateable(updateObjs).AS(tableName).UpdateColumns(columns)
					.ExecuteCommandWithOptLock(isThrowError);
			}

			public int ExecuteCommand()
			{
				if (Context.Ado.Transaction == null)
				{
					try
					{
						Context.Ado.BeginTran();
						int result = _ExecuteCommand();
						Context.Ado.CommitTran();
						return result;
					}
					catch (Exception ex)
					{
						Context.Ado.RollbackTran();
						throw ex;
					}
				}
				return _ExecuteCommand();
			}

			public async Task<int> ExecuteCommandWithOptLockAsync(bool isThrowError = false)
			{
				T[] updateObjs = updateobj.UpdateObjs;
				string tableName = Context.SplitHelper(updateObjs.FirstOrDefault()).GetTableName();
				string[] columns = updateobj.UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.DbColumnName).Distinct().ToArray();
				return await Context.Updateable(updateObjs).AS(tableName).UpdateColumns(columns)
					.ExecuteCommandWithOptLockAsync(isThrowError);
			}

			public async Task<int> ExecuteCommandAsync()
			{
				if (Context.Ado.Transaction == null)
				{
					try
					{
						Context.Ado.BeginTran();
						int result = await _ExecuteCommandAsync();
						Context.Ado.CommitTran();
						return result;
					}
					catch (Exception ex)
					{
						Context.Ado.RollbackTran();
						throw ex;
					}
				}
				return await _ExecuteCommandAsync();
			}

			private int _ExecuteCommand()
			{
				int num = 0;
				string tableName = updateobj.UpdateBuilder.TableName;
				IEnumerable<SplitTableInfo> tables = Tables;
				if (tables != null && tables.Any())
				{
					updateobj.UpdateBuilder.TableName = Tables.First().TableName;
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = updateobj.ToSql();
				IEnumerable<SplitTableInfo> tables2 = Tables;
				if (tables2 != null && tables2.Any())
				{
					updateobj.UpdateBuilder.TableName = tableName;
				}
				foreach (SplitTableInfo table in Tables)
				{
					KeyValuePair<string, List<SugarParameter>> sqlObj = GetSqlObj(keyValuePair, table.TableName);
					num += Context.Ado.ExecuteCommand(sqlObj.Key, sqlObj.Value);
				}
				return num;
			}

			private async Task<int> _ExecuteCommandAsync()
			{
				int num = 0;
				string tableName = updateobj.UpdateBuilder.TableName;
				if (Tables?.Any() ?? false)
				{
					updateobj.UpdateBuilder.TableName = Tables.First().TableName;
				}
				KeyValuePair<string, List<SugarParameter>> sqlobj = updateobj.ToSql();
				if (Tables?.Any() ?? false)
				{
					updateobj.UpdateBuilder.TableName = tableName;
				}
				foreach (SplitTableInfo table in Tables)
				{
					KeyValuePair<string, List<SugarParameter>> sqlObj = GetSqlObj(sqlobj, table.TableName);
					int num2 = num;
					num = num2 + await Context.Ado.ExecuteCommandAsync(sqlObj.Key, sqlObj.Value);
				}
				return num;
			}

			private KeyValuePair<string, List<SugarParameter>> GetSqlObj(KeyValuePair<string, List<SugarParameter>> keyValuePair, string asName)
			{
				List<SugarParameter> value = new List<SugarParameter>();
				string key = keyValuePair.Key;
				if (keyValuePair.Value != null)
				{
					value = keyValuePair.Value.Select((SugarParameter it) => new SugarParameter(it.ParameterName, it.Value)).ToList();
				}
				return new KeyValuePair<string, List<SugarParameter>>(Regex.Replace(key, updateobj.EntityInfo.DbTableName, asName, RegexOptions.IgnoreCase), value);
			}
		}
		public class UpdateableFilter<T> where T : class, new()
		{
			public T[] DataList { get; set; }

			public SqlSugarProvider Context { get; set; }

			public int PageSize { get; internal set; }

			public string TableName { get; internal set; }

			public bool IsEnableDiffLogEvent { get; internal set; }

			public DiffLogModel DiffModel { get; internal set; }

			public List<string> UpdateColumns { get; internal set; }

			public int ExecuteCommand()
			{
				if (DataList.Count() == 1 && DataList.First() == null)
				{
					return 0;
				}
				PageSize = 1;
				int result = 0;
				bool flag = Context.Ado.IsNoTran();
				try
				{
					if (flag)
					{
						Context.Ado.BeginTran();
					}
					Context.Utilities.PageEach(DataList, PageSize, delegate(List<T> pageItem)
					{
						result += SetFilterSql(Context.Updateable(pageItem.First()).AS(TableName).EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel)
							.UpdateColumns(UpdateColumns.ToArray())).ExecuteCommand();
					});
					if (flag)
					{
						Context.Ado.CommitTran();
					}
				}
				catch (Exception)
				{
					if (flag)
					{
						Context.Ado.RollbackTran();
					}
					throw;
				}
				return result;
			}

			public async Task<int> ExecuteCommandAsync()
			{
				if (DataList.Count() == 1 && DataList.First() == null)
				{
					return 0;
				}
				PageSize = 1;
				int result = 0;
				bool isNoTran = Context.Ado.IsNoTran();
				try
				{
					if (isNoTran)
					{
						await Context.Ado.BeginTranAsync();
					}
					await Context.Utilities.PageEachAsync(DataList, PageSize, async delegate(List<T> pageItem)
					{
						int num = result;
						result = num + await SetFilterSql(Context.Updateable(pageItem.First()).AS(TableName).EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel)
							.UpdateColumns(UpdateColumns.ToArray())).ExecuteCommandAsync();
					});
					if (isNoTran)
					{
						await Context.Ado.CommitTranAsync();
					}
				}
				catch (Exception)
				{
					if (isNoTran)
					{
						await Context.Ado.RollbackTranAsync();
					}
					throw;
				}
				return result;
			}

			private IUpdateable<T> SetFilterSql(IUpdateable<T> updateable)
			{
				ISugarQueryable<T> sugarQueryable = Context.Queryable<T>();
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 10000;
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.ToSql();
				string text = UtilMethods.RemoveBeforeFirstWhere(keyValuePair.Key);
				if (text != keyValuePair.Key)
				{
					updateable.UpdateBuilder.AppendWhere = text;
				}
				if (keyValuePair.Value != null)
				{
					updateable.UpdateBuilder.Parameters.AddRange(keyValuePair.Value);
				}
				return updateable;
			}
		}
		public class UpdateableProvider<T> : IUpdateable<T> where T : class, new()
		{
			public SqlSugarProvider Context { get; internal set; }

			public EntityInfo EntityInfo { get; internal set; }

			public ISqlBuilder SqlBuilder { get; internal set; }

			public UpdateBuilder UpdateBuilder { get; set; }

			public IAdo Ado => Context.Ado;

			public T[] UpdateObjs { get; set; }

			/// <summary>
			/// true : by expression  update
			/// false: by object update
			/// </summary>
			public bool UpdateParameterIsNull { get; set; }

			public bool IsMappingTable
			{
				get
				{
					if (Context.MappingTables != null)
					{
						return Context.MappingTables.Any();
					}
					return false;
				}
			}

