			private bool IsUpdateNullByList()
			{
				if (UpdateObjs.Count() > 1)
				{
					if (!UpdateBuilder.IsNoUpdateNull)
					{
						return UpdateBuilder.IsNoUpdateDefaultValue;
					}
					return true;
				}
				return false;
			}

			private int DatasTrackingExecommand()
			{
				int num = 0;
				bool flag = Context.Ado.IsNoTran();
				try
				{
					if (flag)
					{
						Context.Ado.BeginTran();
					}
					int i = 0;
					T[] updateObjs = UpdateObjs;
					foreach (T val in updateObjs)
					{
						IUpdateable<T> updateable = Clone();
						(updateable as UpdateableProvider<T>).UpdateObjs = new T[1] { val };
						updateable.UpdateBuilder.IsListUpdate = null;
						updateable.UpdateBuilder.DbColumnInfoList = updateable.UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.TableId == i).ToList();
						AppendTracking(val, updateable);
						List<DbColumnInfo> dbColumnInfoList = updateable.UpdateBuilder.DbColumnInfoList;
						if (dbColumnInfoList != null && dbColumnInfoList.Any())
						{
							num += updateable.ExecuteCommand();
						}
						int num2 = i + 1;
						i = num2;
					}
					if (flag)
					{
						Context.Ado.CommitTran();
					}
				}
				catch (Exception)
				{
					if (flag)
					{
						Context.Ado.RollbackTran();
					}
					throw;
				}
				return num;
			}

			private async Task<int> DatasTrackingExecommandAsync()
			{
				bool isNoTran = Context.Ado.IsNoTran();
				int trakRows = 0;
				try
				{
					if (isNoTran)
					{
						await Context.Ado.BeginTranAsync();
					}
					int i = 0;
					T[] updateObjs = UpdateObjs;
					foreach (T val in updateObjs)
					{
						IUpdateable<T> updateable = Clone();
						(updateable as UpdateableProvider<T>).UpdateObjs = new T[1] { val };
						updateable.UpdateBuilder.IsListUpdate = null;
						updateable.UpdateBuilder.DbColumnInfoList = updateable.UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.TableId == i).ToList();
						AppendTracking(val, updateable);
						if (updateable.UpdateBuilder.DbColumnInfoList?.Any() ?? false)
						{
							int num = trakRows;
							trakRows = num + await updateable.ExecuteCommandAsync();
						}
						int num2 = i + 1;
						i = num2;
					}
					if (isNoTran)
					{
						await Context.Ado.CommitTranAsync();
					}
				}
				catch (Exception)
				{
					if (isNoTran)
					{
						await Context.Ado.RollbackTranAsync();
					}
					throw;
				}
				return trakRows;
			}

			private bool UpdateObjectNotWhere()
			{
				SqlSugarProvider context = Context;
				if (context != null && context.CurrentConnectionConfig?.MoreSettings?.DatabaseModel == DbType.SqlServer)
				{
					return false;
				}
				if (Context.CurrentConnectionConfig.DbType != DbType.MySql)
				{
					return Context.CurrentConnectionConfig.DbType != DbType.SqlServer;
				}
				return false;
			}

			private void AppendTracking(T item, IUpdateable<T> newUpdateable)
			{
				if (!IsTrakingData() && !IsTrakingDatas())
				{
					return;
				}
				KeyValuePair<string, object> keyValuePair = Context.TempItems.FirstOrDefault<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.StartsWith("Tracking_" + item.GetHashCode()));
				List<string> diff = FastCopy.GetDiff(item, (T)keyValuePair.Value);
				if (diff.Count > 0)
				{
					List<string> pks = (from it in EntityInfo.Columns
						where it.IsPrimarykey
						select it.PropertyName).ToList();
					diff = diff.Where((string it) => !pks.Contains(it)).ToList();
					if (diff.Count > 0)
					{
						newUpdateable.UpdateColumns(diff.ToArray());
					}
				}
				else
				{
					(newUpdateable as UpdateableProvider<T>).UpdateObjs = new T[1];
					newUpdateable.UpdateBuilder.DbColumnInfoList = new List<DbColumnInfo>();
				}
			}

			private void AppendSets()
			{
				if (SetColumnsIndex > 0)
				{
					List<string> source = UpdateBuilder.SetValues.Select<KeyValuePair<string, string>, string>((KeyValuePair<string, string> it) => SqlBuilder.GetNoTranslationColumnName(it.Key.ToLower())).ToList();
					List<string> addKeys = source.Where((string k) => !UpdateBuilder.DbColumnInfoList.Any((DbColumnInfo it) => it.PropertyName.ToLower() == k || it.DbColumnName.ToLower() == k)).ToList();
					List<EntityColumnInfo> source2 = EntityInfo.Columns.Where((EntityColumnInfo it) => !GetPrimaryKeys().Any((string p) => p.ToLower() == it.PropertyName?.ToLower() || p.ToLower() == it.DbColumnName?.ToLower()) && addKeys.Any((string k) => it.PropertyName?.ToLower() == k || it.DbColumnName?.ToLower() == k)).ToList();
					UpdateBuilder.DbColumnInfoList.AddRange(source2.Select((EntityColumnInfo it) => new DbColumnInfo
					{
						PropertyName = it.PropertyName,
						DbColumnName = it.DbColumnName
					}));
				}
				SetColumnsIndex++;
			}

			private string _ExecuteCommand()
			{
				CheckWhere();
				PreToSql();
				AutoRemoveDataCache();
				Check.ExceptionEasy(UpdateParameterIsNull && UpdateBuilder.DbColumnInfoList.Count() == UpdateObjs.Length && UpdateObjs.Length == UpdateBuilder.DbColumnInfoList.Count((DbColumnInfo it) => it.IsPrimarykey), "The primary key cannot be updated", "主键不能更新，更新主键会对代码逻辑存在未知隐患,如果非要更新：建议你删除在插入或者新建一个没主键的类。");
				Check.Exception(UpdateBuilder.WhereValues.IsNullOrEmpty() && GetPrimaryKeys().IsNullOrEmpty(), "You cannot have no primary key and no conditions");
				string text = UpdateBuilder.ToSqlString();
				ValidateVersion();
				RestoreMapping();
				Before(text);
				return text;
			}

			private void CheckWhere()
			{
				if (UpdateParameterIsNull && UpdateBuilder.WhereValues.IsNullOrEmpty())
				{
					Check.ExceptionEasy("Update requires conditions", "更新需要条件 Where");
				}
			}

			private void _WhereColumn(string columnName)
			{
				List<DbColumnInfo> columnInfos = columns.Where((DbColumnInfo it) => it.DbColumnName.Equals(columnName, StringComparison.OrdinalIgnoreCase) || it.PropertyName.Equals(columnName, StringComparison.OrdinalIgnoreCase)).ToList();
				if (!UpdateBuilder.DbColumnInfoList.Any((DbColumnInfo y) => y.DbColumnName == columnInfos.First().DbColumnName))
				{
					UpdateBuilder.DbColumnInfoList.AddRange(columnInfos);
				}
			}

			private void AutoRemoveDataCache()
			{
				ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
				ConfigureExternalServices configureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
				if (moreSettings != null && moreSettings.IsAutoRemoveDataCache && configureExternalServices != null && configureExternalServices.DataInfoCacheService != null)
				{
					RemoveDataCache();
				}
			}

			internal void Init()
			{
				UpdateBuilder.TableName = EntityInfo.EntityName;
				if (IsMappingTable)
				{
					MappingTable mappingTable = Context.MappingTables.SingleOrDefault((MappingTable it) => it.EntityName == EntityInfo.EntityName);
					if (mappingTable != null)
					{
						UpdateBuilder.TableName = mappingTable.DbTableName;
					}
				}
				int num = 0;
				if (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsPrimarykey))
				{
					UpdateBuilder.OldPrimaryKeys = (from it in EntityInfo.Columns
						where it.IsPrimarykey
						select it.DbColumnName).ToList();
				}
				T[] updateObjs = UpdateObjs;
				foreach (T val in updateObjs)
				{
					List<DbColumnInfo> updateItem = new List<DbColumnInfo>();
					bool num3 = val is Dictionary<string, object>;
					if (val is Dictionary<string, string>)
					{
						Check.ExceptionEasy("To use Updateable dictionary, use string or object", "Updateable字典请使用string,object类型");
					}
					if (num3)
					{
						SetUpdateItemByDic(num, val, updateItem);
					}
					else
					{
						DataAop(val);
						SetUpdateItemByEntity(num, val, updateItem);
						Tracking(val);
					}
					num++;
				}
				columns = UpdateBuilder.DbColumnInfoList;
				List<EntityColumnInfo> list = EntityInfo.Columns.Where((EntityColumnInfo it) => it.IsOnlyIgnoreUpdate).ToList();
				if (list != null && list.Any())
				{
					IgnoreColumns(list.Select((EntityColumnInfo it) => it.PropertyName).ToArray());
				}
			}

			private void Tracking(T item)
			{
				if (!IsTrakingData())
				{
					return;
				}
				KeyValuePair<string, object> keyValuePair = Context.TempItems.FirstOrDefault<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.StartsWith("Tracking_" + item.GetHashCode()));
				if (keyValuePair.Key == null && keyValuePair.Value == null)
				{
					return;
				}
				List<string> diff = FastCopy.GetDiff(item, (T)keyValuePair.Value);
				if (diff.Count > 0)
				{
					List<string> pks = (from it in EntityInfo.Columns
						where it.IsPrimarykey
						select it.PropertyName).ToList();
					diff = diff.Where((string it) => !pks.Contains(it)).ToList();
					if (diff.Count > 0)
					{
						UpdateColumns(diff.ToArray());
					}
				}
				else
				{
					UpdateObjs = new T[1];
					UpdateBuilder.DbColumnInfoList = new List<DbColumnInfo>();
				}
			}

			private bool IsTrakingData()
			{
				if (!UpdateParameterIsNull && Context.TempItems != null && Context.TempItems.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.StartsWith("Tracking_")))
				{
					return UpdateObjs.Length == 1;
				}
				return false;
			}

			private bool IsTrakingDatas()
			{
				if (!UpdateParameterIsNull && Context.TempItems != null && Context.TempItems.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.StartsWith("Tracking_")))
				{
					return UpdateObjs.Length > 1;
				}
				return false;
			}

			private void DataAop(T item)
			{
				Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataExecuting;
				if (action == null || item == null)
				{
					return;
				}
				foreach (EntityColumnInfo column in EntityInfo.Columns)
				{
					if (column.ForOwnsOnePropertyInfo != null)
					{
						object value = column.ForOwnsOnePropertyInfo.GetValue(item, null);
						if (value != null)
						{
							action(column.PropertyInfo.GetValue(value, null), new DataFilterModel
							{
								OperationType = DataFilterType.UpdateByObject,
								EntityValue = item,
								EntityColumnInfo = column
							});
						}
					}
					else if (!(column.PropertyInfo.Name == "Item") || !column.IsIgnore)
					{
						action(column.PropertyInfo.GetValue(item, null), new DataFilterModel
						{
							OperationType = DataFilterType.UpdateByObject,
							EntityValue = item,
							EntityColumnInfo = column
						});
					}
				}
			}

			private void DataChangesAop(T[] items)
			{
				if (typeof(T).FullName.StartsWith("System.Collections.Generic.Dictionary`"))
				{
					return;
				}
				Action<object, DataFilterModel> action = Context.CurrentConnectionConfig.AopEvents?.DataChangesExecuted;
				if (action == null)
				{
					return;
				}
				foreach (T val in items)
				{
					if (val == null)
					{
						continue;
					}
					foreach (EntityColumnInfo column in EntityInfo.Columns)
					{
						if (column.ForOwnsOnePropertyInfo != null)
						{
							object value = column.ForOwnsOnePropertyInfo.GetValue(val, null);
							if (value != null)
							{
								action(column.PropertyInfo.GetValue(value, null), new DataFilterModel
								{
									OperationType = DataFilterType.UpdateByObject,
									EntityValue = val,
									EntityColumnInfo = column
								});
							}
						}
						else if (!(column.PropertyInfo.Name == "Item") || !column.IsIgnore)
						{
							action(column.PropertyInfo.GetValue(val, null), new DataFilterModel
							{
								OperationType = DataFilterType.UpdateByObject,
								EntityValue = val,
								EntityColumnInfo = column
							});
						}
					}
				}
			}

			private void CheckTranscodeing(bool checkIsJson = true)
			{
				if (EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsTranscoding))
				{
					Check.Exception(true, ErrorMessage.GetThrowMessage("UpdateColumns no support IsTranscoding", "SetColumns方式更新不支持IsTranscoding，你可以使用db.Updateable(实体)的方式更新"));
				}
			}

			private void SetUpdateItemByDic(int i, T item, List<DbColumnInfo> updateItem)
			{
				foreach (KeyValuePair<string, object> item2 in (item as Dictionary<string, object>).OrderBy((KeyValuePair<string, object> it) => it.Key))
				{
					DbColumnInfo dbColumnInfo = new DbColumnInfo
					{
						Value = item2.Value,
						DbColumnName = item2.Key,
						PropertyName = item2.Key,
						PropertyType = ((item2.Value == null) ? DBNull.Value.GetType() : UtilMethods.GetUnderType(item2.Value.GetType())),
						TableId = i
					};
					if (dbColumnInfo.PropertyType.IsEnum())
					{
						ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
						if (moreSettings != null && moreSettings.TableEnumIsString == true)
						{
							dbColumnInfo.PropertyType = UtilConstants.StringType;
							dbColumnInfo.Value = dbColumnInfo.Value.ToString();
						}
						else
						{
							dbColumnInfo.Value = Convert.ToInt64(dbColumnInfo.Value);
						}
					}
					updateItem.Add(dbColumnInfo);
				}
				UpdateBuilder.DbColumnInfoList.AddRange(updateItem);
			}

			private void SetUpdateItemByEntity(int i, T item, List<DbColumnInfo> updateItem)
			{
				foreach (EntityColumnInfo column in EntityInfo.Columns)
				{
					if (column.IsIgnore)
					{
						continue;
					}
					Check.ExceptionEasy(item == null, "db.Updateable(data) data is required ", "db.Updateable(data) data不能是null");
					DbColumnInfo dbColumnInfo = new DbColumnInfo
					{
						Value = GetValue(item, column),
						DbColumnName = GetDbColumnName(column.PropertyName),
						PropertyName = column.PropertyName,
						PropertyType = UtilMethods.GetUnderType(column.PropertyInfo),
						SqlParameterDbType = column.SqlParameterDbType,
						TableId = i,
						UpdateSql = column.UpdateSql,
						UpdateServerTime = column.UpdateServerTime,
						IsPrimarykey = column.IsPrimarykey,
						DataType = column.DataType
					};
					if (column.ForOwnsOnePropertyInfo != null)
					{
						dbColumnInfo.DbColumnName = column.DbColumnName;
					}
					if (dbColumnInfo.PropertyType.IsEnum() && dbColumnInfo.Value != null)
					{
						ConnMoreSettings moreSettings = Context.CurrentConnectionConfig.MoreSettings;
						if (moreSettings != null && moreSettings.TableEnumIsString == true)
						{
							dbColumnInfo.PropertyType = UtilConstants.StringType;
							dbColumnInfo.Value = dbColumnInfo.Value.ToString();
						}
						else
						{
							dbColumnInfo.Value = Convert.ToInt64(dbColumnInfo.Value);
						}
					}
					if (column.IsJson)
					{
						dbColumnInfo.IsJson = true;
						InsertBuilder insertBuilder = InstanceFactory.GetInsertBuilder(Context?.CurrentConnectionConfig);
						if (insertBuilder != null && insertBuilder.SerializeObjectFunc != null && dbColumnInfo.Value != null)
						{
							dbColumnInfo.Value = insertBuilder?.SerializeObjectFunc(dbColumnInfo.Value);
						}
						else if (dbColumnInfo.Value != null)
						{
							dbColumnInfo.Value = Context.Utilities.SerializeObject(dbColumnInfo.Value);
						}
					}
					if (column.IsArray)
					{
						dbColumnInfo.IsArray = true;
					}
					if (EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsTranscoding && it.DbColumnName.Equals(column.DbColumnName, StringComparison.CurrentCultureIgnoreCase)) != null && dbColumnInfo.Value.HasValue())
					{
						dbColumnInfo.Value = UtilMethods.EncodeBase64(dbColumnInfo.Value.ToString());
					}
					updateItem.Add(dbColumnInfo);
				}
				UpdateBuilder.DbColumnInfoList.AddRange(updateItem);
			}

			private static object GetValue(T item, EntityColumnInfo column)
			{
				if (column.ForOwnsOnePropertyInfo != null)
				{
					object value = column.ForOwnsOnePropertyInfo.GetValue(item, null);
					if (value == null)
					{
						return null;
					}
					return column.PropertyInfo.GetValue(value, null);
				}
				return column.PropertyInfo.GetValue(item, null);
			}

			private string GetSetSql(string value, Expression<Func<T, T>> columns)
			{
				if (value.Contains("= \"SYSDATE\""))
				{
					value = value.Replace("= \"SYSDATE\"", "= SYSDATE");
				}
				string name = columns.Parameters.First().Name;
				string text = "," + SqlBuilder.GetTranslationColumnName(name) + ".";
				string text2 = "," + SqlBuilder.GetTranslationColumnName(EntityInfo.DbTableName) + ".";
				if (text != text2)
				{
					value = value.Replace(text, ",");
				}
				return value;
			}

			private void PreToSql()
			{
				if (UpdateBuilder.UpdateColumns.HasValue())
				{
					List<string> columns = UpdateBuilder.UpdateColumns;
					UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => (from iit in GetPrimaryKeys()
						select iit.ToLower()).Contains(it.DbColumnName.ToLower()) || columns.Contains<string>(it.PropertyName, StringComparer.OrdinalIgnoreCase) || columns.Contains<string>(it.DbColumnName, StringComparer.OrdinalIgnoreCase)).ToList();
				}
				UpdateBuilder.EntityInfo = EntityInfo;
				UpdateBuilder.PrimaryKeys = GetPrimaryKeys();
				if (IsWhereColumns)
				{
					foreach (string primaryKey2 in UpdateBuilder.PrimaryKeys)
					{
						if (WhereColumnList == null || WhereColumnList.Count() <= 0)
						{
							Check.Exception(!UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.DbColumnName.ToLower()).Contains(primaryKey2.ToLower()), "Use UpdateColumns().WhereColumn() ,UpdateColumns need {0}", primaryKey2);
						}
					}
				}
				if (Context.IgnoreColumns != null && Context.IgnoreColumns.Any())
				{
					List<IgnoreColumn> currentIgnoreColumns = Context.IgnoreColumns.Where((IgnoreColumn it) => it.EntityName == EntityInfo.EntityName).ToList();
					UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => !currentIgnoreColumns.Any((IgnoreColumn i) => it.PropertyName.Equals(i.PropertyName, StringComparison.CurrentCulture))).ToList();
				}
				if (IsSingle)
				{
					bool flag = EntityInfo.DbTableName.StartsWith("Dictionary`");
					foreach (DbColumnInfo item in UpdateBuilder.DbColumnInfoList)
					{
						if (UpdateBuilder.Parameters == null)
						{
							UpdateBuilder.Parameters = new List<SugarParameter>();
						}
						if (UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> it) => SqlBuilder.GetNoTranslationColumnName(it.Key) == item.PropertyName) || item.SqlParameterDbType is Type)
						{
							continue;
						}
						SugarParameter sugarParameter = new SugarParameter(SqlBuilder.SqlParameterKeyWord + item.DbColumnName, item.Value, item.PropertyType);
						if (item.IsJson)
						{
							sugarParameter.IsJson = true;
							SqlBuilder.ChangeJsonType(sugarParameter);
						}
						if (item.SqlParameterDbType is System.Data.DbType dbType)
						{
							sugarParameter.DbType = dbType;
						}
						if (item.IsArray)
						{
							sugarParameter.IsArray = true;
							if (sugarParameter.Value == null || sugarParameter.Value == DBNull.Value)
							{
								ArrayNull(item, sugarParameter);
							}
						}
						if ((item.Value == null) & flag)
						{
							Type nullType = SqlBuilder.GetNullType(UpdateBuilder.GetTableNameString, item.DbColumnName);
							if (nullType != null)
							{
								sugarParameter = new SugarParameter(SqlBuilder.SqlParameterKeyWord + item.DbColumnName, item.Value, nullType);
							}
						}
						UpdateBuilder.Parameters.Add(sugarParameter);
					}
				}
				List<string> identities = GetIdentityKeys();
				if (identities != null && identities.Any())
				{
					UpdateBuilder.DbColumnInfoList.ForEach(delegate(DbColumnInfo it)
					{
						string text = identities.SingleOrDefault((string i) => it.DbColumnName.Equals(i, StringComparison.CurrentCultureIgnoreCase));
						if (text != null && text.Any())
						{
							it.IsIdentity = true;
						}
					});
				}
				List<string> primaryKey = GetPrimaryKeys();
				if (primaryKey != null && primaryKey.Count > 0)
				{
					UpdateBuilder.DbColumnInfoList.ForEach(delegate(DbColumnInfo it)
					{
						string text = primaryKey.SingleOrDefault((string i) => it.DbColumnName.Equals(i, StringComparison.CurrentCultureIgnoreCase));
						if (text != null && text.Any())
						{
							it.IsPrimarykey = true;
						}
					});
				}
				if (!UpdateBuilder.Parameters.HasValue() || !UpdateBuilder.SetValues.IsValuable())
				{
					return;
				}
				UpdateBuilder.Parameters.RemoveAll((SugarParameter it) => UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.SqlParameterKeyWord + SqlBuilder.GetNoTranslationColumnName(v.Key) == it.ParameterName));
			}

			private static void ArrayNull(DbColumnInfo item, SugarParameter parameter)
			{
				if (item.PropertyType.IsIn(new Type[2]
				{
					typeof(Guid[]),
					typeof(Guid?[])
				}))
				{
					parameter.DbType = System.Data.DbType.Guid;
				}
				else if (item.PropertyType.IsIn(new Type[2]
				{
					typeof(int[]),
					typeof(int?[])
				}))
				{
					parameter.DbType = System.Data.DbType.Int32;
				}
				else if (item.PropertyType.IsIn(new Type[2]
				{
					typeof(long[]),
					typeof(long?[])
				}))
				{
					parameter.DbType = System.Data.DbType.Int64;
				}
				else if (item.PropertyType.IsIn(new Type[2]
				{
					typeof(short[]),
					typeof(short?[])
				}))
				{
					parameter.DbType = System.Data.DbType.Int16;
				}
			}

			private void OptRollBack(int updateRows, T updateData, object oldValue, string name)
			{
				if (updateRows == 0)
				{
					EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name)?.PropertyInfo.SetValue(updateData, oldValue);
				}
			}

			private string GetDbColumnName(string propertyName)
			{
				if (!IsMappingColumns)
				{
					return propertyName;
				}
				if (Context.MappingColumns.Any((MappingColumn it) => it.EntityName.Equals(EntityInfo.EntityName, StringComparison.CurrentCultureIgnoreCase)))
				{
					MappingColumnList = Context.MappingColumns.Where((MappingColumn it) => it.EntityName.Equals(EntityInfo.EntityName, StringComparison.CurrentCultureIgnoreCase)).ToList();
				}
				if (MappingColumnList == null || !MappingColumnList.Any())
				{
					return propertyName;
				}
				MappingColumn mappingColumn = MappingColumnList.FirstOrDefault((MappingColumn it) => it.PropertyName.Equals(propertyName, StringComparison.CurrentCultureIgnoreCase));
				if (mappingColumn != null)
				{
					return mappingColumn.DbColumnName;
				}
				return propertyName;
			}

			protected List<string> GetPrimaryKeys()
			{
				if (WhereColumnList.HasValue())
				{
					return WhereColumnList;
				}
				if (Context.IsSystemTablesConfig)
				{
					return Context.DbMaintenance.GetPrimaries(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
				}
				return (from it in EntityInfo.Columns
					where it.IsPrimarykey
					select it.DbColumnName).ToList();
			}

			protected virtual List<string> GetIdentityKeys()
			{
				if (Context.IsSystemTablesConfig)
				{
					return Context.DbMaintenance.GetIsIdentities(Context.EntityMaintenance.GetTableName(EntityInfo.EntityName));
				}
				return (from it in EntityInfo.Columns
					where it.IsIdentity
					select it.DbColumnName).ToList();
			}

			private void RestoreMapping()
			{
				if (IsAs)
				{
					Context.MappingTables = OldMappingTableList;
				}
			}

			private void ValidateVersion()
			{
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsEnableUpdateVersionValidation);
				List<DbColumnInfo> list = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.IsPrimarykey).ToList();
				if (entityColumnInfo == null || !IsVersionValidation)
				{
					return;
				}
				Check.Exception(list.IsNullOrEmpty(), "UpdateVersionValidation the primary key is required.");
				List<IConditionalModel> list2 = new List<IConditionalModel>();
				foreach (DbColumnInfo item in list)
				{
					list2.Add(new ConditionalModel
					{
						CSharpTypeName = item.PropertyType.Name,
						FieldName = item.DbColumnName,
						ConditionalType = ConditionalType.Equal,
						FieldValue = item.Value.ObjToString()
					});
				}
				T val = Context.Queryable<T>().Where(list2).First();
				if (val == null)
				{
					return;
				}
				object value = EntityInfo.Type.GetProperty(entityColumnInfo.PropertyName).GetValue(UpdateObjs.Last(), null);
				object value2 = EntityInfo.Type.GetProperty(entityColumnInfo.PropertyName).GetValue(val, null);
				Check.Exception(value == null, "UpdateVersionValidation entity property {0} is not null", entityColumnInfo.PropertyName);
				Check.Exception(value2 == null, "UpdateVersionValidation database column {0} is not null", entityColumnInfo.DbColumnName);
				if (entityColumnInfo.PropertyInfo.PropertyType.IsIn(UtilConstants.IntType, UtilConstants.LongType))
				{
					if (Convert.ToInt64(value2) != Convert.ToInt64(value))
					{
						throw new VersionExceptions($"UpdateVersionValidation {entityColumnInfo.PropertyName} Not the latest version ");
					}
				}
				else if (entityColumnInfo.PropertyInfo.PropertyType.IsIn(UtilConstants.DateType))
				{
					if (value2.ObjToDate() != value.ObjToDate())
					{
						throw new VersionExceptions($"UpdateVersionValidation {entityColumnInfo.PropertyName} Not the latest version ");
					}
				}
				else if (entityColumnInfo.PropertyInfo.PropertyType.IsIn(UtilConstants.ByteArrayType))
				{
					if (UtilMethods.GetLong((byte[])value2) != UtilMethods.GetLong((byte[])value))
					{
						throw new VersionExceptions($"UpdateVersionValidation {entityColumnInfo.PropertyName} Not the latest version ");
					}
				}
				else
				{
					Check.ThrowNotSupportedException($"UpdateVersionValidation Not Supported Type [ {entityColumnInfo.PropertyInfo.PropertyType} ] , {entityColumnInfo.PropertyName}");
				}
			}

			private void After(string sql)
			{
				if (IsEnableDiffLogEvent && !string.IsNullOrEmpty(sql))
				{
					bool isDisableMasterSlaveSeparation = Ado.IsDisableMasterSlaveSeparation;
					Ado.IsDisableMasterSlaveSeparation = true;
					List<SugarParameter> list = UpdateBuilder.Parameters;
					if (list == null)
					{
						list = new List<SugarParameter>();
					}
					diffModel.AfterData = GetDiffTable(sql, list);
					diffModel.Time = Context.Ado.SqlExecutionTime;
					if (Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent != null)
					{
						Context.CurrentConnectionConfig.AopEvents.OnDiffLogEvent(diffModel);
					}
					Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
				}
				if (RemoveCacheFunc != null)
				{
					RemoveCacheFunc();
				}
				DataChangesAop(UpdateObjs);
			}

			private string _ExecuteCommandWithOptLock(T updateData, ref object oldVerValue)
			{
				Check.ExceptionEasy(UpdateParameterIsNull, "Optimistic lock can only be an entity update method", "乐观锁只能是实体更新方式");
				EntityColumnInfo verColumn = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsEnableUpdateVersionValidation);
				Check.ExceptionEasy(verColumn == null, " " + EntityInfo.EntityName + " need  IsEnableUpdateVersionValidation=true ", "实体" + EntityInfo.EntityName + "没有找到版本标识特性 IsEnableUpdateVersionValidation");
				Check.ExceptionEasy(UpdateObjs.Length > 1, "Optimistic lock can only handle a single update ", "乐观锁只能处理单条更新");
				Check.ExceptionEasy(!verColumn.UnderType.IsIn(UtilConstants.StringType, UtilConstants.LongType, UtilConstants.GuidType, UtilConstants.DateType), "Optimistic locks can only be guid, long, and string types", "乐观锁只能是Guid、Long和字符串类型");
				object fieldValue = (oldVerValue = verColumn.PropertyInfo.GetValue(updateData));
				object randomByType = UtilMethods.GetRandomByType(verColumn.UnderType);
				verColumn.PropertyInfo.SetValue(updateData, randomByType);
				DbColumnInfo dbColumnInfo = UpdateBuilder.DbColumnInfoList.FirstOrDefault((DbColumnInfo it) => it.PropertyName.EqualCase(verColumn.PropertyName));
				if (dbColumnInfo == null)
				{
					dbColumnInfo = new DbColumnInfo
					{
						DbColumnName = verColumn.DbColumnName,
						PropertyName = verColumn.PropertyName,
						Value = randomByType
					};
					UpdateBuilder.DbColumnInfoList.Add(dbColumnInfo);
				}
				dbColumnInfo.Value = randomByType;
				List<string> primaryKeys = GetPrimaryKeys();
				Check.ExceptionEasy(primaryKeys.Count == 0, "need primary key or WhereColumn", "需要主键或者WhereColumn");
				Where(verColumn.DbColumnName, "=", fieldValue);
				foreach (string p in primaryKeys)
				{
					EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.DbColumnName.EqualCase(p) || it.PropertyName.EqualCase(p));
					Where(entityColumnInfo.DbColumnName, "=", entityColumnInfo.PropertyInfo.GetValue(updateData));
				}
				return verColumn.PropertyName;
			}

			private void Before(string sql)
			{
				if (IsEnableDiffLogEvent && !string.IsNullOrEmpty(sql))
				{
					bool isDisableMasterSlaveSeparation = Ado.IsDisableMasterSlaveSeparation;
					Ado.IsDisableMasterSlaveSeparation = true;
					List<SugarParameter> list = UpdateBuilder.Parameters;
					if (list == null)
					{
						list = new List<SugarParameter>();
					}
					diffModel.BeforeData = GetDiffTable(sql, list);
					diffModel.Sql = sql;
					diffModel.Parameters = list.ToArray();
					Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
				}
			}

			private bool IsPrimaryKey(DbColumnInfo it)
			{
				return GetPrimaryKeys().Any((string p) => p.Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || p.Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase));
			}

			internal List<DiffLogTableInfo> GetTableDiff(DataTable dt)
			{
				List<DiffLogTableInfo> list = new List<DiffLogTableInfo>();
				if (dt.Rows != null && dt.Rows.Count > 0)
				{
					foreach (DataRow row in dt.Rows)
					{
						DiffLogTableInfo diffLogTableInfo = new DiffLogTableInfo();
						diffLogTableInfo.TableDescription = EntityInfo.TableDescription;
						diffLogTableInfo.TableName = EntityInfo.DbTableName;
						diffLogTableInfo.Columns = new List<DiffLogColumnInfo>();
						foreach (DataColumn col in dt.Columns)
						{
							try
							{
								EntityColumnInfo entityColumnInfo = EntityInfo.Columns.Where((EntityColumnInfo it) => it.DbColumnName != null).First((EntityColumnInfo it) => it.DbColumnName.Equals(col.ColumnName, StringComparison.CurrentCultureIgnoreCase));
								DiffLogColumnInfo diffLogColumnInfo = new DiffLogColumnInfo();
								diffLogColumnInfo.Value = row[col.ColumnName];
								diffLogColumnInfo.ColumnName = col.ColumnName;
								diffLogColumnInfo.IsPrimaryKey = entityColumnInfo.IsPrimarykey;
								diffLogColumnInfo.ColumnDescription = entityColumnInfo.ColumnDescription;
								diffLogTableInfo.Columns.Add(diffLogColumnInfo);
							}
							catch (Exception ex)
							{
								Check.ExceptionEasy(col.ColumnName + " No corresponding entity attribute found in difference log ." + ex.Message, col.ColumnName + "在差异日志中可能没有找到相应的实体属性,详细:" + ex.Message);
							}
						}
						list.Add(diffLogTableInfo);
					}
				}
				return list;
			}

			private List<DiffLogTableInfo> GetDiffTable(string sql, List<SugarParameter> parameters)
			{
				List<DiffLogTableInfo> list = new List<DiffLogTableInfo>();
				DataTable dataTable = null;
				if (UpdateParameterIsNull)
				{
					string whereString = Regex.Replace(sql, ".* WHERE ", "", RegexOptions.Singleline);
					if (IsExists(sql))
					{
						if (UpdateBuilder.SetValues != null)
						{
							foreach (KeyValuePair<string, string> setValue in UpdateBuilder.SetValues)
							{
								string value = setValue.Value;
								if (value != null && value.Contains("SELECT"))
								{
									sql = sql.Replace(setValue.Value, null);
								}
							}
						}
						whereString = UtilMethods.RemoveBeforeFirstWhere(sql);
					}
					dataTable = Context.Queryable<T>().AS(UpdateBuilder.TableName).Filter(null, isDisabledGobalFilter: true)
						.Where(whereString)
						.AddParameters(parameters)
						.ToDataTable();
				}
				else if (UpdateObjs.ToList().Count == 0)
				{
					dataTable = new DataTable();
				}
				else
				{
					List<string> whereColumnList = WhereColumnList;
					dataTable = ((whereColumnList != null && whereColumnList.Any()) ? Context.Queryable<T>().Filter(null, isDisabledGobalFilter: true).WhereClassByWhereColumns(UpdateObjs.ToList(), WhereColumnList.ToArray())
						.ToDataTable() : ((!UpdateBuilder.TableName.HasValue()) ? Context.Queryable<T>().Filter(null, isDisabledGobalFilter: true).WhereClassByPrimaryKey(UpdateObjs.ToList())
						.ToDataTable() : Context.Queryable<T>().AS(UpdateBuilder.TableName).Filter(null, isDisabledGobalFilter: true)
						.WhereClassByPrimaryKey(UpdateObjs.ToList())
						.ToDataTable()));
				}
				if (dataTable.Rows != null && dataTable.Rows.Count > 0)
				{
					foreach (DataRow row in dataTable.Rows)
					{
						DiffLogTableInfo diffLogTableInfo = new DiffLogTableInfo();
						diffLogTableInfo.TableDescription = EntityInfo.TableDescription;
						diffLogTableInfo.TableName = EntityInfo.DbTableName;
						diffLogTableInfo.Columns = new List<DiffLogColumnInfo>();
						foreach (DataColumn col in dataTable.Columns)
						{
							try
							{
								EntityColumnInfo entityColumnInfo = EntityInfo.Columns.Where((EntityColumnInfo it) => it.DbColumnName != null).First((EntityColumnInfo it) => it.DbColumnName.Equals(col.ColumnName, StringComparison.CurrentCultureIgnoreCase));
								DiffLogColumnInfo diffLogColumnInfo = new DiffLogColumnInfo();
								diffLogColumnInfo.Value = row[col.ColumnName];
								diffLogColumnInfo.ColumnName = col.ColumnName;
								diffLogColumnInfo.IsPrimaryKey = entityColumnInfo.IsPrimarykey;
								diffLogColumnInfo.ColumnDescription = entityColumnInfo.ColumnDescription;
								diffLogTableInfo.Columns.Add(diffLogColumnInfo);
							}
							catch (Exception ex)
							{
								Check.ExceptionEasy(col.ColumnName + " No corresponding entity attribute found in difference log ." + ex.Message, col.ColumnName + "在差异日志中可能没有找到相应的实体属性,详细:" + ex.Message);
							}
						}
						list.Add(diffLogTableInfo);
					}
				}
				return list;
			}

			private static bool IsExists(string sql)
			{
				return UtilMethods.CountSubstringOccurrences(sql, "WHERE") > 1;
			}

