			public virtual int ExecuteCommandWithOptLockIF(bool? IsVersionValidation, bool? IsOptLock = null)
			{
				if (IsOptLock == true)
				{
					return ExecuteCommandWithOptLock(IsVersionValidation == true);
				}
				return ExecuteCommand();
			}

			public virtual int ExecuteCommandWithOptLock(bool IsVersionValidation = false)
			{
				T[] updateObjs = UpdateObjs;
				Check.ExceptionEasy(updateObjs != null && updateObjs.Length > 1, " OptLock can only be used on a single object, and the argument cannot be List", "乐观锁只能用于单个对象,参数不能是List,如果是一对多操作请更新主表统一用主表验证");
				T val = UpdateObjs.FirstOrDefault();
				if (val == null)
				{
					return 0;
				}
				object oldVerValue = null;
				string text = _ExecuteCommandWithOptLock(val, ref oldVerValue);
				int num = ExecuteCommand();
				OptRollBack(num, val, oldVerValue, text);
				if ((num == 0) & IsVersionValidation)
				{
					throw new VersionExceptions($"UpdateVersionValidation {text} Not the latest version ");
				}
				return num;
			}

			public virtual int ExecuteCommand()
			{
				if (IsTrakingDatas() || IsUpdateNullByList())
				{
					return DatasTrackingExecommand();
				}
				string text = _ExecuteCommand();
				if (UpdateBuilder.AppendWhere.HasValue())
				{
					text = text + " AND " + UpdateBuilder.AppendWhere;
				}
				if (string.IsNullOrEmpty(text))
				{
					return 0;
				}
				int result = 0;
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.IsCorrectErrorSqlParameterName == true)
				{
					UpdateBuilder.Parameters = UpdateBuilder.Parameters.Where((SugarParameter it) => UtilMethods.NoErrorParameter(it.ParameterName)).ToList();
				}
				List<SugarParameter> list = null;
				if (IsEnableDiffLogEvent)
				{
					list = UtilMethods.CopySugarParameters(UpdateBuilder.Parameters);
				}
				if (text != Environment.NewLine)
				{
					result = Ado.ExecuteCommand(text, (UpdateBuilder.Parameters == null) ? null : UpdateBuilder.Parameters.ToArray());
				}
				if (list != null && UpdateBuilder.Parameters != null && string.Join(",", list.Select((SugarParameter it) => it.ParameterName)) != string.Join(",", UpdateBuilder.Parameters.Select((SugarParameter it) => it.ParameterName)))
				{
					UpdateBuilder.Parameters = list;
				}
				After(text);
				return result;
			}

			public virtual T ExecuteReturnEntity()
			{
				int num = ExecuteCommand();
				if (num > 0 && !UpdateParameterIsNull)
				{
					return UpdateObjs.FirstOrDefault();
				}
				if (num > 0 && UpdateParameterIsNull)
				{
					List<string> whereValues = UpdateBuilder.WhereValues;
					ISugarQueryable<T> sugarQueryable = Context.Queryable<T>();
					foreach (string item in whereValues)
					{
						sugarQueryable.Where(item);
					}
					sugarQueryable.AddParameters(UtilMethods.CopySugarParameters(UpdateBuilder.Parameters));
					return sugarQueryable.First();
				}
				return null;
			}

			public bool ExecuteCommandHasChange()
			{
				return ExecuteCommand() > 0;
			}

			public virtual async Task<int> ExecuteCommandWithOptLockAsync(bool IsVersionValidation = false)
			{
				T[] updateObjs = UpdateObjs;
				Check.ExceptionEasy(updateObjs != null && updateObjs.Length > 1, " OptLock can only be used on a single object, and the argument cannot be List", "乐观锁只能用于单个对象,参数不能是List,如果是一对多操作请更新主表统一用主表验证");
				T updateData = UpdateObjs.FirstOrDefault();
				if (updateData == null)
				{
					return 0;
				}
				object oldValue = null;
				string name = _ExecuteCommandWithOptLock(updateData, ref oldValue);
				int num = await ExecuteCommandAsync();
				OptRollBack(num, updateData, oldValue, name);
				if ((num == 0) & IsVersionValidation)
				{
					throw new VersionExceptions($"UpdateVersionValidation {name} Not the latest version ");
				}
				return num;
			}

