			public UpdateablePage<T> PageSize(int pageSize)
			{
				ThrowUpdateByExpressionByMesage(" PageSize(num) ");
				UpdateablePage<T> updateablePage = new UpdateablePage<T>();
				updateablePage.PageSize = pageSize;
				updateablePage.Context = Context;
				updateablePage.DataList = UpdateObjs;
				updateablePage.TableName = UpdateBuilder.TableName;
				updateablePage.IsEnableDiffLogEvent = IsEnableDiffLogEvent;
				updateablePage.WhereColumnList = WhereColumnList?.ToArray();
				updateablePage.DiffModel = diffModel;
				updateablePage.ReSetValueBySqlExpList = UpdateBuilder.ReSetValueBySqlExpList;
				if (UpdateBuilder.DbColumnInfoList.Any())
				{
					updateablePage.UpdateColumns = (from it in (from it in UpdateBuilder.DbColumnInfoList
							group it by it.TableId).First()
						select it.DbColumnName).ToList();
				}
				UpdateBuilder updateBuilder = UpdateBuilder;
				if (updateBuilder != null && updateBuilder.UpdateColumns?.Any() == true)
				{
					updateablePage.UpdateColumns = UpdateBuilder.UpdateColumns;
				}
				return updateablePage;
			}

			public IUpdateable<T, T2> InnerJoin<T2>(Expression<Func<T, T2, bool>> joinExpress)
			{
				UpdateableProvider<T, T2> updateableProvider = new UpdateableProvider<T, T2>();
				updateableProvider.updateableObj = this;
				ISugarQueryable<T, T2> sugarQueryable = Context.Queryable<T>().LeftJoin(joinExpress);
				updateableProvider.updateableObj.UpdateBuilder.JoinInfos = sugarQueryable.QueryBuilder.JoinQueryInfos;
				updateableProvider.updateableObj.UpdateBuilder.ShortName = joinExpress.Parameters.FirstOrDefault()?.Name;
				return updateableProvider;
			}

			public IUpdateable<T, T2> InnerJoin<T2>(ISugarQueryable<T> queryable, Expression<Func<T, T2, bool>> joinExpress)
			{
				string tableName = " (" + queryable.Clone().ToSqlString() + ") ";
				return InnerJoin(joinExpress, tableName);
			}

			public IUpdateable<T, T2> InnerJoin<T2>(ISugarQueryable<T2> queryable, Expression<Func<T, T2, bool>> joinExpress)
			{
				string joinTable = " (" + queryable.Clone().ToSqlString() + ") ";
				return InnerJoin(joinTable, joinExpress, UpdateBuilder.TableName);
			}

			public IUpdateable<T, T2> InnerJoin<T2>(string joinTable, Expression<Func<T, T2, bool>> joinExpress, string tableName)
			{
				UpdateableProvider<T, T2> updateableProvider = new UpdateableProvider<T, T2>();
				updateableProvider.updateableObj = this;
				ISugarQueryable<T, T2> sugarQueryable = Context.Queryable<T>().LeftJoin(joinExpress);
				updateableProvider.updateableObj.UpdateBuilder.JoinInfos = sugarQueryable.QueryBuilder.JoinQueryInfos;
				updateableProvider.updateableObj.UpdateBuilder.JoinInfos.Last().TableName = joinTable;
				updateableProvider.updateableObj.UpdateBuilder.ShortName = joinExpress.Parameters.FirstOrDefault()?.Name;
				updateableProvider.updateableObj.UpdateBuilder.TableName = tableName;
				return updateableProvider;
			}

			public IUpdateable<T, T2> InnerJoin<T2>(Expression<Func<T, T2, bool>> joinExpress, string TableName)
			{
				UpdateableProvider<T, T2> updateableProvider = new UpdateableProvider<T, T2>();
				updateableProvider.updateableObj = this;
				ISugarQueryable<T, T2> sugarQueryable = Context.Queryable<T>().LeftJoin(joinExpress);
				updateableProvider.updateableObj.UpdateBuilder.JoinInfos = sugarQueryable.QueryBuilder.JoinQueryInfos;
				updateableProvider.updateableObj.UpdateBuilder.ShortName = joinExpress.Parameters.FirstOrDefault()?.Name;
				updateableProvider.updateableObj.UpdateBuilder.TableName = TableName;
				return updateableProvider;
			}

			public IUpdateable<T> Clone()
			{
				Context.SugarActionType = SugarActionType.Update;
				UpdateableProvider<T> updateableProvider = InstanceFactory.GetUpdateableProvider<T>(Context.CurrentConnectionConfig);
				ISqlBuilder sqlbuilder = InstanceFactory.GetSqlbuilder(Context.CurrentConnectionConfig);
				updateableProvider.Context = Context;
				updateableProvider.EntityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
				updateableProvider.SqlBuilder = sqlbuilder;
				updateableProvider.SqlBuilder.Context = Context;
				updateableProvider.UpdateObjs = UpdateObjs;
				updateableProvider.WhereColumnList = WhereColumnList;
				updateableProvider.IsWhereColumns = IsWhereColumns;
				updateableProvider.IgnoreColumnNameList = IgnoreColumnNameList;
				updateableProvider.IsAs = IsAs;
				updateableProvider.IsOffIdentity = IsOffIdentity;
				updateableProvider.IsEnableDiffLogEvent = IsEnableDiffLogEvent;
				updateableProvider.diffModel = diffModel;
				updateableProvider.UpdateParameterIsNull = UpdateParameterIsNull;
				updateableProvider.RemoveCacheFunc = RemoveCacheFunc;
				updateableProvider.SetColumnsIndex = SetColumnsIndex;
				updateableProvider.OldMappingTableList = OldMappingTableList;
				updateableProvider.MappingColumnList = MappingColumnList;
				updateableProvider.columns = columns.ToList();
				updateableProvider.UpdateBuilder = InstanceFactory.GetUpdateBuilder(Context.CurrentConnectionConfig);
				updateableProvider.UpdateBuilder.Builder = sqlbuilder;
				updateableProvider.UpdateBuilder.LambdaExpressions = InstanceFactory.GetLambdaExpressions(Context.CurrentConnectionConfig);
				updateableProvider.Context = Context;
				updateableProvider.UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.ToList();
				updateableProvider.UpdateBuilder.TableName = UpdateBuilder.TableName;
				updateableProvider.UpdateBuilder.WhereValues = UpdateBuilder?.WhereValues?.ToList();
				updateableProvider.UpdateBuilder.Parameters = UpdateBuilder?.Parameters?.ToList();
				updateableProvider.UpdateBuilder.IsListUpdate = UpdateBuilder.IsListUpdate;
				updateableProvider.UpdateBuilder.IsWhereColumns = UpdateBuilder.IsWhereColumns;
				updateableProvider.UpdateBuilder.WhereValues = UpdateBuilder?.WhereValues?.ToList();
				updateableProvider.UpdateBuilder.IsNoUpdateDefaultValue = UpdateBuilder.IsNoUpdateDefaultValue;
				updateableProvider.UpdateBuilder.IsNoUpdateNull = UpdateBuilder.IsNoUpdateNull;
				updateableProvider.UpdateBuilder.SetValues = UpdateBuilder?.SetValues?.ToList();
				updateableProvider.UpdateBuilder.UpdateColumns = UpdateBuilder?.UpdateColumns?.ToList();
				updateableProvider.UpdateBuilder.Context = Context;
				return updateableProvider;
			}

