			public IUpdateable<T> ReSetValue(Action<T> setValueExpression)
			{
				ThrowUpdateByExpression();
				if (UpdateObjs.HasValue())
				{
					List<string> oldColumns = UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.PropertyName).ToList();
					T[] updateObjs = UpdateObjs;
					foreach (T obj in updateObjs)
					{
						setValueExpression(obj);
					}
					UpdateBuilder.DbColumnInfoList = new List<DbColumnInfo>();
					Init();
					UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => oldColumns.Contains(it.PropertyName)).ToList();
				}
				return this;
			}

			public IUpdateable<T> PublicSetColumns(Expression<Func<T, object>> filedNameExpression, string computationalSymbol)
			{
				if (UpdateParameterIsNull)
				{
					Check.Exception(UpdateParameterIsNull, ErrorMessage.GetThrowMessage("The PublicSetColumns(exp,string) overload can only be used to update entity objects: db.Updateable(object)", "PublicSetColumns(exp,string)重载只能用在实体对象更新：db.Updateable(对象)，请区分表达式更新和实体对象更不同用法 "));
				}
				else
				{
					string name = ExpressionTool.GetMemberName(filedNameExpression);
					if (name == null)
					{
						Check.ExceptionEasy(filedNameExpression?.ToString() + " format error ", filedNameExpression?.ToString() + "参数格式错误");
					}
					if (UpdateBuilder.ReSetValueBySqlExpList == null)
					{
						UpdateBuilder.ReSetValueBySqlExpList = new Dictionary<string, ReSetValueBySqlExpListModel>();
					}
					if (!UpdateBuilder.ReSetValueBySqlExpList.ContainsKey(name))
					{
						UpdateBuilder.ReSetValueBySqlExpList.Add(name, new ReSetValueBySqlExpListModel
						{
							Type = ReSetValueBySqlExpListModelType.List,
							Sql = computationalSymbol,
							DbColumnName = SqlBuilder.GetTranslationColumnName(EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == name).DbColumnName)
						});
					}
				}
				return this;
			}

			public IUpdateable<T> PublicSetColumns(Expression<Func<T, object>> filedNameExpression, Expression<Func<T, object>> ValueExpExpression)
			{
				if (UpdateParameterIsNull)
				{
					return SetColumns(filedNameExpression, ValueExpExpression);
				}
				string name = ExpressionTool.GetMemberName(filedNameExpression);
				if (name == null)
				{
					Check.ExceptionEasy(filedNameExpression?.ToString() + " format error ", filedNameExpression?.ToString() + "参数格式错误");
				}
				string resultString = UpdateBuilder.GetExpressionValue(ValueExpExpression, ResolveExpressType.WhereSingle).GetResultString();
				if (UpdateBuilder.ReSetValueBySqlExpList == null)
				{
					UpdateBuilder.ReSetValueBySqlExpList = new Dictionary<string, ReSetValueBySqlExpListModel>();
				}
				if (!UpdateBuilder.ReSetValueBySqlExpList.ContainsKey(name))
				{
					UpdateBuilder.ReSetValueBySqlExpList.Add(name, new ReSetValueBySqlExpListModel
					{
						Sql = resultString,
						DbColumnName = SqlBuilder.GetTranslationColumnName(EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == name).DbColumnName)
					});
				}
				return this;
			}

			public IUpdateable<T> CallEntityMethod(Expression<Action<T>> method)
			{
				ThrowUpdateByExpression();
				if (UpdateObjs.HasValue())
				{
					List<string> oldColumns = UpdateBuilder.DbColumnInfoList.Select((DbColumnInfo it) => it.PropertyName).ToList();
					Expression body = (Expression.Lambda(method).Body as LambdaExpression).Body;
					Check.Exception(!(body is MethodCallExpression), method.ToString() + " is not method");
					MethodCallExpression callExpresion = body as MethodCallExpression;
					UtilMethods.DataInoveByExpresson(UpdateObjs, callExpresion);
					UpdateBuilder.DbColumnInfoList = new List<DbColumnInfo>();
					Init();
					UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => oldColumns.Contains(it.PropertyName)).ToList();
				}
				return this;
			}

			public IUpdateable<T> WhereColumns(Expression<Func<T, object>> columns)
			{
				ThrowUpdateByExpression();
				IsWhereColumns = true;
				UpdateBuilder.IsWhereColumns = true;
				Check.Exception(UpdateParameterIsNull, "Updateable<T>().Updateable is error,Use Updateable(obj).WhereColumns");
				List<string> list = (from it in UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.ArraySingle).GetResultArray()
					select SqlBuilder.GetNoTranslationColumnName(it)).ToList();
				if (WhereColumnList == null)
				{
					WhereColumnList = new List<string>();
				}
				foreach (string item in list)
				{
					_WhereColumn(item);
					EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(item));
					if (entityColumnInfo != null)
					{
						WhereColumnList.Add(entityColumnInfo.DbColumnName);
					}
					else
					{
						WhereColumnList.Add(item);
					}
				}
				return this;
			}

