			public IUpdateable<T> UpdateColumns(Expression<Func<T, object>> columns)
			{
				ThrowUpdateByExpression();
				List<string> collection = (from it in UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.ArraySingle).GetResultArray()
					select SqlBuilder.GetNoTranslationColumnName(it)).ToList();
				if (SqlBuilder?.SqlTranslationLeft == string.Empty)
				{
					if (columns != null && columns.Body is UnaryExpression { Operand: MemberExpression operand } && operand.Type == UtilConstants.BoolType)
					{
						collection = new List<string> { UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.FieldSingle)?.GetResultString() };
					}
				}
				if (UpdateBuilder.UpdateColumns == null)
				{
					UpdateBuilder.UpdateColumns = new List<string>();
				}
				UpdateBuilder.UpdateColumns.AddRange(collection);
				return this;
			}

			public IUpdateable<T> UpdateColumns(string[] columns, bool appendColumnsByDataFilter)
			{
				List<string> list = new List<string>();
				if (appendColumnsByDataFilter)
				{
					T val = new T();
					UtilMethods.ClearPublicProperties(val, EntityInfo);
					T obj = ((UpdateableProvider<T>)Context.Updateable(val)).UpdateObjs.First();
					foreach (EntityColumnInfo item in EntityInfo.Columns.Where((EntityColumnInfo it) => !it.IsPrimarykey && !it.IsIgnore && !it.IsOnlyIgnoreUpdate))
					{
						object value = item.PropertyInfo.GetValue(obj);
						if (value != null && !value.Equals("") && !value.Equals(UtilMethods.GetDefaultValue(item.UnderType)))
						{
							list.Add(item.PropertyName);
						}
					}
				}
				list.AddRange(columns);
				return UpdateColumns(list.ToArray());
			}

