			public IUpdateable<T> EnableQueryFilter()
			{
				try
				{
					ThrowUpdateByObject();
				}
				catch
				{
					Check.ExceptionEasy("Updateable<T>(obj) no support, use Updateable<T>().SetColumn ", "更新过滤器只能用在表达式方式更新 ,更新分为实体更新和表达式更新 。正确用法 Updateable<T>().SetColum(..).Where(..)");
				}
				ISugarQueryable<T> sugarQueryable = Context.Queryable<T>();
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 1000;
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.ToSql();
				string[] array = Regex.Split(keyValuePair.Key, " Where ", RegexOptions.IgnoreCase);
				if (array.Length > 1)
				{
					Where(array.Last(), keyValuePair.Value);
				}
				return this;
			}

			public virtual IUpdateable<T> SetColumns(string fieldName, object fieldValue)
			{
				ThrowUpdateByObject();
				bool flag = false;
				bool isArray = false;
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName.EqualCase(fieldName));
				if (entityColumnInfo != null)
				{
					fieldName = entityColumnInfo.DbColumnName;
					flag = entityColumnInfo.IsJson;
					isArray = entityColumnInfo.IsArray;
				}
				string text = SqlBuilder.SqlParameterKeyWord + "Const" + UpdateBuilder.LambdaExpressions.ParameterIndex;
				UpdateBuilder.LambdaExpressions.ParameterIndex = UpdateBuilder.LambdaExpressions.ParameterIndex + 1;
				if (UpdateBuilder.Parameters == null)
				{
					UpdateBuilder.Parameters = new List<SugarParameter>();
				}
				if (flag && fieldValue != null && !(fieldValue is string))
				{
					InsertBuilder insertBuilder = InstanceFactory.GetInsertBuilder(Context.CurrentConnectionConfig);
					fieldValue = ((insertBuilder.SerializeObjectFunc == null) ? Context.Utilities.SerializeObject(fieldValue) : insertBuilder.SerializeObjectFunc(fieldValue));
				}
				SugarParameter sugarParameter = new SugarParameter(text, fieldValue);
				sugarParameter.IsJson = flag;
				sugarParameter.IsArray = isArray;
				UpdateBuilder.Parameters.Add(sugarParameter);
				if (entityColumnInfo != null && entityColumnInfo.UpdateServerTime)
				{
					string date = Context.Queryable<object>().QueryBuilder.LambdaExpressions.DbMehtods.GetDate();
					UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(fieldName), SqlBuilder.GetTranslationColumnName(fieldName) + "=" + date));
				}
				else
				{
					UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(fieldName), SqlBuilder.GetTranslationColumnName(fieldName) + "=" + text));
				}
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => (!UpdateParameterIsNull && IsPrimaryKey(it)) || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				if (!UpdateBuilder.DbColumnInfoList.Any((DbColumnInfo it) => it.DbColumnName.EqualCase(fieldName)))
				{
					UpdateBuilder.DbColumnInfoList.Add(new DbColumnInfo
					{
						DbColumnName = fieldName,
						Value = fieldValue,
						PropertyName = fieldName,
						IsJson = flag,
						IsArray = isArray,
						PropertyType = fieldValue?.GetType()
					});
				}
				AppendSets();
				return this;
			}

			public IUpdateable<T> SetColumnsIF(bool isUpdateColumns, Expression<Func<T, object>> filedNameExpression, object fieldValue)
			{
				if (isUpdateColumns)
				{
					return SetColumns(filedNameExpression, fieldValue);
				}
				return this;
			}

			public virtual IUpdateable<T> SetColumns(Expression<Func<T, object>> filedNameExpression, Expression<Func<T, object>> valueExpression)
			{
				if (valueExpression == null)
				{
					return SetColumns(filedNameExpression, (object)null);
				}
				string propertyName = UpdateBuilder.GetExpressionValue(filedNameExpression, ResolveExpressType.FieldSingle).GetString();
				propertyName = UpdateBuilder.Builder.GetTranslationColumnName(propertyName);
				Expression expression = ExpressionTool.RemoveConvert(valueExpression.Body);
				string value = UpdateBuilder.GetExpressionValue(expression, ResolveExpressType.WhereSingle).GetString();
				value = $" {propertyName}={value} ";
				UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(propertyName, value));
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => (!UpdateParameterIsNull && IsPrimaryKey(it)) || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				AppendSets();
				if (typeof(T) == UtilConstants.ObjType)
				{
					UpdateBuilder.DbColumnInfoList.Add(new DbColumnInfo
					{
						DbColumnName = UpdateBuilder.Builder.GetNoTranslationColumnName(propertyName),
						Value = value,
						PropertyName = propertyName,
						SqlParameterDbType = typeof(NoParameterCommonPropertyConvert)
					});
				}
				return this;
			}

			public virtual IUpdateable<T> SetColumns(Expression<Func<T, object>> filedNameExpression, object fieldValue)
			{
				string name = UpdateBuilder.GetExpressionValue(filedNameExpression, ResolveExpressType.FieldSingle).GetString();
				name = UpdateBuilder.Builder.GetNoTranslationColumnName(name);
				return SetColumns(name, fieldValue);
			}

			public virtual IUpdateable<T> SetColumns(Expression<Func<T, T>> columns)
			{
				ThrowUpdateByObject();
				string[] resultArray = UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.Update).GetResultArray();
				object[] checkObj = resultArray;
				Check.ArgumentNullException(checkObj, "UpdateColumns Parameter error, UpdateColumns(it=>new T{ it.id=1}) is valid, UpdateColumns(it=>T) is error");
				KeyValuePair<string, Expression>[] array = ExpressionTool.GetNewExpressionItemList(columns).ToArray();
				if (resultArray.HasValue())
				{
					int num = 0;
					string[] array2 = resultArray;
					foreach (string obj in array2)
					{
						string propertyName = (propertyName = array[num].Key);
						num++;
						string value = obj;
						value = GetSetSql(value, columns);
						UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(propertyName), value));
					}
				}
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.UpdateServerTime || it.UpdateSql.HasValue() || (!UpdateParameterIsNull && IsPrimaryKey(it)) || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				CheckTranscodeing(checkIsJson: false);
				AppendSets();
				return this;
			}

			public virtual IUpdateable<T> SetColumns(Expression<Func<T, T>> columns, bool appendColumnsByDataFilter)
			{
				ThrowUpdateByObject();
				string[] resultArray = UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.Update).GetResultArray();
				object[] checkObj = resultArray;
				Check.ArgumentNullException(checkObj, "UpdateColumns Parameter error, UpdateColumns(it=>new T{ it.id=1}) is valid, UpdateColumns(it=>T) is error");
				if (resultArray.HasValue())
				{
					string[] array = resultArray;
					foreach (string text in array)
					{
						string noTranslationColumnName = SqlBuilder.GetNoTranslationColumnName(text);
						string text2 = text;
						if (text2.Contains("= \"SYSDATE\""))
						{
							text2 = text2.Replace("= \"SYSDATE\"", "= SYSDATE");
						}
						UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(noTranslationColumnName), text2));
					}
				}
				if (appendColumnsByDataFilter)
				{
					T val = new T();
					UtilMethods.ClearPublicProperties(val, EntityInfo);
					T obj = ((UpdateableProvider<T>)Context.Updateable(val)).UpdateObjs.First();
					foreach (EntityColumnInfo item2 in EntityInfo.Columns.Where((EntityColumnInfo it) => !it.IsPrimarykey && !it.IsIgnore && !it.IsOnlyIgnoreUpdate))
					{
						object value = item2.PropertyInfo.GetValue(obj);
						if (value != null && !value.Equals("") && !value.Equals(UtilMethods.GetDefaultValue(item2.UnderType)))
						{
							string text3 = SqlBuilder.SqlParameterKeyWord + item2.PropertyName + 1000;
							SugarParameter item = new SugarParameter(text3, value);
							UpdateBuilder.Parameters.Add(item);
							UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(item2.DbColumnName), SqlBuilder.GetTranslationColumnName(item2.DbColumnName) + "=" + text3));
						}
					}
				}
				if (EntityInfo.Columns.Any((EntityColumnInfo it) => it.UpdateServerTime || it.UpdateSql.HasValue()))
				{
					foreach (EntityColumnInfo item3 in EntityInfo.Columns.Where((EntityColumnInfo it) => it.UpdateServerTime || it.UpdateSql.HasValue()))
					{
						if (item3.UpdateServerTime)
						{
							UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(item3.DbColumnName), SqlBuilder.GetTranslationColumnName(item3.DbColumnName) + "=" + UpdateBuilder.LambdaExpressions.DbMehtods.GetDate()));
						}
						else if (item3.UpdateSql.HasValue())
						{
							UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(item3.DbColumnName), SqlBuilder.GetTranslationColumnName(item3.DbColumnName) + "=" + item3.UpdateSql));
						}
					}
				}
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.UpdateServerTime || it.UpdateSql.HasValue() || (!UpdateParameterIsNull && IsPrimaryKey(it)) || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				CheckTranscodeing(checkIsJson: false);
				AppendSets();
				return this;
			}

			public virtual IUpdateable<T> SetColumns(Expression<Func<T, bool>> columns)
			{
				ThrowUpdateByObject();
				BinaryExpression binaryExpression = columns.Body as BinaryExpression;
				Check.Exception(!binaryExpression.NodeType.IsIn(ExpressionType.Equal), "No support {0}", columns.ToString());
				Check.Exception(!(binaryExpression.Left is MemberExpression) && !(binaryExpression.Left is UnaryExpression), "No support {0}", columns.ToString());
				Check.Exception(ExpressionTool.IsConstExpression(binaryExpression.Left as MemberExpression), "No support {0}", columns.ToString());
				if (UpdateBuilder.LambdaExpressions.ParameterIndex <= 1 && (from it in EntityInfo.Columns
					select it.PropertyName.TrimEnd('2') into it
					group it by it).Any((IGrouping<string, string> it) => it.Count() > 1))
				{
					UpdateBuilder.LambdaExpressions.ParameterIndex = 100;
				}
				string text = UpdateBuilder.GetExpressionValue(columns, ResolveExpressType.WhereSingle).GetResultString().Replace(")", " )")
					.Replace("(", "( ")
					.Trim()
					.TrimStart('(')
					.TrimEnd(')')
					.Replace("= =", "=");
				if (IsCorrectErrorSqlParameterName())
				{
					text = UpdateBuilder.GetExpressionValue(binaryExpression.Right, ResolveExpressType.WhereSingle).GetResultString().Trim();
				}
				if (text.EndsWith(" IS NULL  "))
				{
					text = Regex.Split(text, " IS NULL  ")[0] + " = NULL ";
				}
				else if (!text.Contains("=") && text.Contains("IS  NULL  "))
				{
					text = Regex.Split(text, "IS  NULL  ")[0] + " = NULL ";
				}
				string key = SqlBuilder.GetNoTranslationColumnName(text);
				if (IsCorrectErrorSqlParameterName())
				{
					Expression left = binaryExpression.Left;
					MemberExpression member = left as MemberExpression;
					if (member != null)
					{
						key = EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == member.Member.Name).DbColumnName;
						text = $" {SqlBuilder.GetTranslationColumnName(key)}={text} ";
					}
				}
				if (EntityInfo.Columns.Where((EntityColumnInfo it) => it.IsJson || it.IsTranscoding).Any((EntityColumnInfo it) => it.DbColumnName.EqualCase(key) || it.PropertyName.EqualCase(key)))
				{
					CheckTranscodeing();
				}
				if (columns.ToString().Contains("Subqueryable()."))
				{
					text = text.Replace(SqlBuilder.GetTranslationColumnName((ExpressionTool.RemoveConvert(binaryExpression.Left) as MemberExpression).Expression?.ToString() ?? "") + ".", UpdateBuilder.GetTableNameString.TrimEnd() + ".");
				}
				UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(SqlBuilder.GetTranslationColumnName(key), text));
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => (!UpdateParameterIsNull && IsPrimaryKey(it)) || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				AppendSets();
				return this;
			}

			public IUpdateable<T> SetColumnsIF(bool isUpdateColumns, Expression<Func<T, bool>> columns)
			{
				ThrowUpdateByObject();
				if (isUpdateColumns)
				{
					SetColumns(columns);
				}
				return this;
			}

			public IUpdateable<T> SetColumnsIF(bool isUpdateColumns, Expression<Func<T, T>> columns)
			{
				ThrowUpdateByObject();
				if (isUpdateColumns)
				{
					SetColumns(columns);
				}
				return this;
			}

			public IUpdateable<T> In<PkType>(Expression<Func<T, object>> inField, ISugarQueryable<PkType> childQueryExpression)
			{
				ExpressionResult expressionValue = UpdateBuilder.GetExpressionValue(inField, ResolveExpressType.FieldSingle);
				UpdateBuilder.LambdaExpressions.ParameterIndex = childQueryExpression.QueryBuilder.LambdaExpressions.ParameterIndex + 1;
				string resultString = expressionValue.GetResultString();
				if (!UpdateBuilder.SetValues.Any())
				{
					KeyValuePair<string, List<SugarParameter>> keyValuePair = childQueryExpression.ToSql();
					Where($" {resultString} IN ( SELECT {resultString} FROM ( {keyValuePair.Key} ) SUBDEL) ", keyValuePair.Value);
				}
				else
				{
					Where($" {resultString} IN ( SELECT {resultString} FROM ( {childQueryExpression.ToSqlString()} ) SUBDEL) ");
				}
				return this;
			}

			public IUpdateable<T> WhereIF(bool isWhere, Expression<Func<T, bool>> expression)
			{
				if (!UpdateBuilder.WhereValues.Any())
				{
					Check.ExceptionEasy(!StaticConfig.EnableAllWhereIF, "Need to program startup configuration StaticConfig. EnableAllWhereIF = true; Tip: This operation is very risky if there are no conditions it is easy to update the entire table", " 需要程序启动时配置StaticConfig.EnableAllWhereIF=true; 提示：该操作存在很大的风险如果没有条件很容易将整个表全部更新");
				}
				if (isWhere)
				{
					return Where(expression);
				}
				return this;
			}

			public IUpdateable<T> Where(Expression<Func<T, bool>> expression)
			{
				Check.Exception(UpdateObjectNotWhere() && UpdateObjs.Length > 1, ErrorMessage.GetThrowMessage("update List no support where", "集合更新不支持Where请使用WhereColumns"));
				ExpressionResult expressionValue = UpdateBuilder.GetExpressionValue(expression, ResolveExpressType.WhereSingle);
				string text = expressionValue.GetResultString();
				if (expression.ToString().Contains("Subqueryable()"))
				{
					string text2 = EntityInfo.DbTableName;
					if (UpdateBuilder.TableName.HasValue())
					{
						text2 = UpdateBuilder.TableName;
					}
					if (ExpressionTool.GetParameters(expression).First().Type == typeof(T))
					{
						string translationColumnName = SqlBuilder.GetTranslationColumnName(text2);
						text = text.Replace(translationColumnName, "( SELECT * FROM " + translationColumnName + ")  ");
					}
					text = text.Replace(SqlBuilder.GetTranslationColumnName(expression.Parameters.First().Name) + ".", SqlBuilder.GetTranslationTableName(text2) + ".");
				}
				else if (expressionValue.IsNavicate)
				{
					string name = EntityInfo.DbTableName;
					if (UpdateBuilder.TableName.HasValue())
					{
						name = UpdateBuilder.TableName;
					}
					text = text.Replace(expression.Parameters.First().Name + ".", SqlBuilder.GetTranslationTableName(name) + ".");
					text = text.Replace(SqlBuilder.GetTranslationColumnName(expression.Parameters.First().Name) + ".", SqlBuilder.GetTranslationTableName(name) + ".");
				}
				UpdateBuilder.WhereValues.Add(text);
				return this;
			}

			public IUpdateable<T> Where(string whereSql, object parameters = null)
			{
				Check.Exception(UpdateObjectNotWhere() && UpdateObjs.Length > 1, ErrorMessage.GetThrowMessage("update List no support where", "集合更新不支持Where请使用WhereColumns"));
				if (whereSql.HasValue())
				{
					UpdateBuilder.WhereValues.Add(whereSql);
				}
				if (parameters != null)
				{
					UpdateBuilder.Parameters.AddRange(Context.Ado.GetParameters(parameters));
				}
				return this;
			}

			public IUpdateable<T> Where(string fieldName, string conditionalType, object fieldValue)
			{
				Check.Exception(UpdateObjectNotWhere() && UpdateObjs.Length > 1, ErrorMessage.GetThrowMessage("update List no support where", "集合更新不支持Where请使用WhereColumns"));
				string whereSql = SqlBuilder.GetWhere(fieldName, conditionalType, 0);
				Where(whereSql);
				string name = SqlBuilder.SqlParameterKeyWord + fieldName + "0";
				UpdateBuilder.Parameters.Add(new SugarParameter(name, fieldValue));
				return this;
			}

			public IUpdateable<T> Where(List<IConditionalModel> conditionalModels)
			{
				Check.Exception(UpdateObjectNotWhere() && UpdateObjs.Length > 1, ErrorMessage.GetThrowMessage("update List no support where", "集合更新不支持Where请使用WhereColumns"));
				KeyValuePair<string, SugarParameter[]> keyValuePair = Context.Queryable<T>().SqlBuilder.ConditionalModelToSql(conditionalModels);
				Where(keyValuePair.Key, keyValuePair.Value);
				return this;
			}

			public ParameterUpdateable<T> UseParameter()
			{
				ThrowUpdateByExpressionByMesage(ErrorMessage.GetThrowMessage("UseParameter can only be updated through entity objects", "UseParameter只能通过实体对象更新，不能是表达式方式更新"));
				return new ParameterUpdateable<T>
				{
					Context = Context,
					Updateable = this
				};
			}

			public IUpdateable<T> In(object[] ids)
			{
				ThrowUpdateByObjectByMesage(" In(object[] ids) ");
				List<IConditionalModel> list = new List<IConditionalModel>();
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				Check.ExceptionEasy(entityColumnInfo == null, "In need primary key", "In需要实体有主键");
				list.Add(new ConditionalModel
				{
					FieldName = entityColumnInfo.DbColumnName,
					ConditionalType = ConditionalType.In,
					FieldValue = string.Join(",", ids),
					CSharpTypeName = entityColumnInfo.UnderType?.Name
				});
				return Where(list);
			}
		}
		public class UpdateablePage<T> where T : class, new()
		{
			public T[] DataList { get; set; }

			public SqlSugarProvider Context { get; set; }

			public int PageSize { get; internal set; }

			public string TableName { get; internal set; }

			public bool IsEnableDiffLogEvent { get; internal set; }

			public DiffLogModel DiffModel { get; internal set; }

			public List<string> UpdateColumns { get; internal set; }

			public string[] WhereColumnList { get; internal set; }

			public Dictionary<string, ReSetValueBySqlExpListModel> ReSetValueBySqlExpList { get; internal set; }

			public UpdateableFilter<T> EnableQueryFilter()
			{
				return new UpdateableFilter<T>
				{
					Context = Context,
					DataList = DataList,
					DiffModel = DiffModel,
					IsEnableDiffLogEvent = IsEnableDiffLogEvent,
					PageSize = PageSize,
					TableName = TableName,
					UpdateColumns = UpdateColumns
				};
			}

			public int ExecuteCommand()
			{
				if (DataList.Count() == 1 && DataList.First() == null)
				{
					return 0;
				}
				if (PageSize == 0)
				{
					PageSize = 1000;
				}
				int result = 0;
				bool flag = Context.Ado.IsNoTran();
				try
				{
					if (flag)
					{
						Context.Ado.BeginTran();
					}
					Context.Utilities.PageEach(DataList, PageSize, delegate(List<T> pageItem)
					{
						IUpdateable<T> updateable = Context.Updateable(pageItem).AS(TableName);
						updateable.UpdateBuilder.ReSetValueBySqlExpList = ReSetValueBySqlExpList;
						result += updateable.WhereColumns(WhereColumnList).EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel).UpdateColumns(UpdateColumns.ToArray())
							.ExecuteCommand();
					});
					if (flag)
					{
						Context.Ado.CommitTran();
					}
				}
				catch (Exception)
				{
					if (flag)
					{
						Context.Ado.RollbackTran();
					}
					throw;
				}
				return result;
			}

			public async Task<int> ExecuteCommandAsync()
			{
				if (DataList.Count() == 1 && DataList.First() == null)
				{
					return 0;
				}
				if (PageSize == 0)
				{
					PageSize = 1000;
				}
				int result = 0;
				bool isNoTran = Context.Ado.IsNoTran();
				try
				{
					if (isNoTran)
					{
						await Context.Ado.BeginTranAsync();
					}
					await Context.Utilities.PageEachAsync(DataList, PageSize, async delegate(List<T> pageItem)
					{
						IUpdateable<T> updateable = Context.Updateable(pageItem);
						updateable.UpdateBuilder.ReSetValueBySqlExpList = ReSetValueBySqlExpList;
						int num = result;
						result = num + await updateable.AS(TableName).WhereColumns(WhereColumnList).EnableDiffLogEventIF(IsEnableDiffLogEvent, DiffModel)
							.UpdateColumns(UpdateColumns.ToArray())
							.ExecuteCommandAsync();
					});
					if (isNoTran)
					{
						await Context.Ado.CommitTranAsync();
					}
				}
				catch (Exception)
				{
					if (isNoTran)
					{
						await Context.Ado.RollbackTranAsync();
					}
					throw;
				}
				return result;
			}
		}
		public class UpdateableProvider<T, T2> : IUpdateable<T, T2> where T : class, new()
		{
			public IUpdateable<T> updateableObj { get; set; }

			public int ExecuteCommand()
			{
				return updateableObj.ExecuteCommand();
			}

