			{
				return updateableObj.ExecuteCommandAsync();
			}

			public IUpdateable<T, T2, T3> InnerJoin<T3>(Expression<Func<T, T2, T3, bool>> joinExpress)
			{
				updateableObj.UpdateBuilder.Context.InitMappingInfo<T3>();
				UpdateableProvider<T, T2, T3> updateableProvider = new UpdateableProvider<T, T2, T3>();
				updateableProvider.updateableObj = updateableObj;
				JoinQueryInfo joinInfo = ((QueryableProvider<T>)updateableObj.UpdateBuilder.Context.Queryable<T>()).GetJoinInfo(joinExpress, JoinType.Inner);
				updateableProvider.updateableObj.UpdateBuilder.JoinInfos.Add(joinInfo);
				updateableProvider.updateableObj.UpdateBuilder.ShortName = joinExpress.Parameters.FirstOrDefault()?.Name;
				return updateableProvider;
			}

			public IUpdateable<T, T2> SetColumns(Expression<Func<T, T2, T>> columns)
			{
				Dictionary<string, Expression> memberBindingItemList = ExpressionTool.GetMemberBindingItemList((columns.Body as MemberInitExpression).Bindings);
				UpdateBuilder UpdateBuilder = updateableObj.UpdateBuilder;
				ISqlBuilder SqlBuilder = UpdateBuilder.Builder;
				UpdateBuilder.LambdaExpressions.IsSingle = false;
				foreach (KeyValuePair<string, Expression> item in memberBindingItemList)
				{
					string dbColumnName = updateableObj.UpdateBuilder.Context.EntityMaintenance.GetDbColumnName<T>(item.Key);
					string text = null;
					Expression value = item.Value;
					if (value != null && value.Type?.IsEnum == true && ExpressionTool.NoParameterOrSqlfunc(ExpressionTool.RemoveConvert(item.Value)))
					{
						object obj = ExpressionTool.DynamicInvoke(item.Value);
						long num = Convert.ToInt64(obj);
						SqlSugarProvider context = updateableObj.UpdateBuilder.Context;
						if (context != null && context.CurrentConnectionConfig?.MoreSettings?.TableEnumIsString == true)
						{
							obj = obj?.ToString();
						}
						updateableObj.UpdateBuilder.LambdaExpressions.ParameterIndex++;
						string text2 = item.Key + updateableObj.UpdateBuilder.LambdaExpressions.ParameterIndex;
						SugarParameter sugarParameter = new SugarParameter(updateableObj.UpdateBuilder.Builder.SqlParameterKeyWord + text2, num);
						updateableObj.UpdateBuilder.Parameters.Add(sugarParameter);
						text = sugarParameter.ParameterName;
					}
					else
					{
						text = updateableObj.UpdateBuilder.GetExpressionValue(ExpressionTool.RemoveConvert(item.Value), ResolveExpressType.WhereMultiple).GetString();
					}
					if (ExpressionTool.GetMethodName(ExpressionTool.RemoveConvert(item.Value)) == "End")
					{
						text = UtilMethods.RemoveEqualOne(text);
					}
					updateableObj.UpdateBuilder.SetValues.Add(new KeyValuePair<string, string>(dbColumnName, text));
				}
				UpdateBuilder.DbColumnInfoList = UpdateBuilder.DbColumnInfoList.Where((DbColumnInfo it) => it.UpdateServerTime || it.UpdateSql.HasValue() || UpdateBuilder.SetValues.Any<KeyValuePair<string, string>>((KeyValuePair<string, string> v) => SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.DbColumnName, StringComparison.CurrentCultureIgnoreCase) || SqlBuilder.GetNoTranslationColumnName(v.Key).Equals(it.PropertyName, StringComparison.CurrentCultureIgnoreCase)) || it.IsPrimarykey).ToList();
				return this;
			}

			public IUpdateable<T, T2> Where(Expression<Func<T, T2, bool>> whereExpression)
			{
				string item = updateableObj.UpdateBuilder.GetExpressionValue(whereExpression, ResolveExpressType.WhereMultiple).GetString();
				updateableObj.UpdateBuilder.WhereValues.Add(item);
				return this;
			}
		}
