		public class UpdateExpressionMethodInfo
		{
			internal SqlSugarProvider Context { get; set; }

			internal MethodInfo MethodInfo { get; set; }

			internal object objectValue { get; set; }

			internal Type Type { get; set; }

			public int ExecuteCommand()
			{
				if (Context == null)
				{
					return 0;
				}
				return (int)objectValue.GetType().GetMethod("ExecuteCommand").Invoke(objectValue, new object[0]);
			}

			public async Task<int> ExecuteCommandAsync()
			{
				if (Context == null)
				{
					return 0;
				}
				return await (Task<int>)objectValue.GetType().GetMyMethod("ExecuteCommandAsync", 0).Invoke(objectValue, new object[0]);
			}

			public UpdateExpressionMethodInfo Where(string expShortName, FormattableString whereExpressionString)
			{
				MethodInfo myMethod = objectValue.GetType().GetMyMethod("Where", 1);
				LambdaExpression lambdaExpression = DynamicCoreHelper.GetWhere(Type, expShortName, whereExpressionString);
				object obj = myMethod.Invoke(objectValue, new object[1] { lambdaExpression });
				return new UpdateExpressionMethodInfo
				{
					objectValue = obj,
					Type = Type,
					Context = Context
				};
			}

			public UpdateExpressionMethodInfo SetColumns(string expShortName, FormattableString fieldExpressionString)
			{
				MethodInfo methodInfo = (from it in objectValue.GetType().GetMethods()
					where it.Name == "SetColumns" && it.GetParameters().Count() == 1 && it.GetParameters().First().ToString()
						.Contains(",System.Boolean")
					select it).Single();
				LambdaExpression lambdaExpression = DynamicCoreHelper.GetWhere(Type, expShortName, fieldExpressionString);
				object obj = methodInfo.Invoke(objectValue, new object[1] { lambdaExpression });
				return new UpdateExpressionMethodInfo
				{
					objectValue = obj,
					Type = Type,
					Context = Context
				};
			}
		}
