		internal class CacheSchemeMain
		{
			public static T GetOrCreate<T>(ICacheService cacheService, QueryBuilder queryBuilder, Func<T> getData, int cacheDurationInSeconds, SqlSugarProvider context, string cacheKey)
			{
				CacheKey key = CacheKeyBuider.GetKey(context, queryBuilder);
				key.AppendKey = cacheKey;
				string cacheKey2 = key.ToString();
				return cacheService.GetOrCreate(cacheKey2, getData, cacheDurationInSeconds);
			}

			public static void RemoveCache(ICacheService cacheService, string tableName)
			{
				if (cacheService == null)
				{
					return;
				}
				if (StaticConfig.CacheRemoveByLikeStringFunc != null)
				{
					StaticConfig.CacheRemoveByLikeStringFunc(cacheService, "." + tableName.ToLower() + ".");
					return;
				}
				IEnumerable<string> allKey = cacheService.GetAllKey<string>();
				if (!allKey.HasValue())
				{
					return;
				}
				foreach (string item in allKey)
				{
					if (item.ToLower().Contains("." + tableName.ToLower() + "."))
					{
						cacheService.Remove<string>(item);
					}
				}
			}

			public static void RemoveCacheByLike(ICacheService cacheService, string likeString)
			{
				if (cacheService == null)
				{
					return;
				}
				if (StaticConfig.CacheRemoveByLikeStringFunc != null)
				{
					StaticConfig.CacheRemoveByLikeStringFunc(cacheService, likeString);
					return;
				}
				IEnumerable<string> allKey = cacheService.GetAllKey<string>();
				if (!allKey.HasValue())
				{
					return;
				}
				foreach (string item in allKey)
				{
					if (item != null && item.ToLower().Contains(likeString.ToLower()))
					{
						cacheService.Remove<string>(item);
					}
				}
			}
		}
		public sealed class SnowFlakeSingle
		{
			private static object LockObject;

			private static IdWorker worker;

			public static int WorkId;

			public static int DatacenterId;

			public static IdWorker Instance
			{
				get
				{
					if (worker == null)
					{
						lock (LockObject)
						{
							if (worker == null)
							{
								worker = new IdWorker(WorkId, DatacenterId, 0L);
							}
						}
					}
					return worker;
				}
			}

			public static IdWorker instance => Instance;

			private SnowFlakeSingle()
			{
			}

			static SnowFlakeSingle()
			{
				LockObject = new object();
				WorkId = 1;
				DatacenterId = 1;
			}
		}
		public class ValueToStringConverter : JsonConverter
		{
			public override bool CanRead => false;

			public override bool CanConvert(Type objectType)
			{
				return objectType.IsValueType;
			}

			public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
			{
				throw new NotSupportedException();
			}

			public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
			{
				string text = value?.ToString();
				writer.WriteValue(text);
			}
		}
		public class RefAsync<T>
		{
			public T Value { get; set; }

			public RefAsync()
			{
			}

			public RefAsync(T value)
			{
				Value = value;
			}

			public override string ToString()
			{
				T value = Value;
				if (value != null)
				{
					return value.ToString();
				}
				return "";
			}

			public static implicit operator T(RefAsync<T> r)
			{
				return r.Value;
			}

			public static implicit operator RefAsync<T>(T value)
			{
				return new RefAsync<T>(value);
			}
		}
