		public class ConfigQuery
		{
			public SqlSugarProvider Context { get; set; }

			public void SetTable<T>(Expression<Func<T, object>> keyExpression, Expression<Func<T, object>> valueTextExpression, string uniqueCode = null, Expression<Func<T, object>> whereExpression = null, string asTableName = null)
			{
				lock (SqlFuncExtendsion.TableInfos)
				{
					EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
					ExpressionContext expressionContext = new ExpressionContext();
					QueryBuilder queryBuilder = Context.Queryable<T>().QueryBuilder;
					string key = queryBuilder.GetExpressionValue(keyExpression, ResolveExpressType.FieldSingle).GetString();
					string value = queryBuilder.GetExpressionValue(valueTextExpression, ResolveExpressType.FieldSingle).GetString();
					string text = null;
					if (whereExpression != null)
					{
						text = queryBuilder.GetExpressionValue(whereExpression, ResolveExpressType.WhereSingle).GetResultString();
					}
					expressionContext.MappingTables = Context.MappingTables;
					if (!SqlFuncExtendsion.TableInfos.Any((ConfigTableInfo y) => y.Type == typeof(T) && y.Code == uniqueCode))
					{
						SqlFuncExtendsion.TableInfos.Add(new ConfigTableInfo
						{
							Type = typeof(T),
							TableName = (asTableName ?? entityInfo.DbTableName),
							Key = key,
							Value = value,
							Where = text,
							Parameter = queryBuilder.Parameters,
							Code = uniqueCode
						});
					}
					else
					{
						Check.Exception(true, "SetKeyValue error , entity & uniqueCode already exist");
					}
				}
			}

			public void SetTable<T>(Expression<Func<T, object>> key, Expression<Func<T, object>> value)
			{
				SetTable(key, value, null, null, null);
			}

			public bool Any()
			{
				return SqlFuncExtendsion.TableInfos.Any();
			}
		}
