		public class CaseWhenResolve
		{
			private List<MethodCallExpression> allMethods = new List<MethodCallExpression>();

			private ExpressionContext context;

			public CaseWhenResolve(MethodCallExpression expression, ExpressionContext context, Expression oppsiteExpression)
			{
				this.context = context;
				MethodCallExpression methodCallExpression = expression;
				allMethods.Add(methodCallExpression);
				if (context.IsSingle && oppsiteExpression != null && oppsiteExpression is MemberExpression)
				{
					Expression expression2 = (oppsiteExpression as MemberExpression).Expression;
					if (expression2 is ParameterExpression)
					{
						this.context.SingleTableNameSubqueryShortName = (expression2 as ParameterExpression).Name;
					}
				}
				else if (context.IsSingle && context.Expression is LambdaExpression)
				{
					this.context.SingleTableNameSubqueryShortName = (context.Expression as LambdaExpression).Parameters.First().Name;
				}
				while (methodCallExpression != null)
				{
					MethodCallExpression methodCallExpression2 = methodCallExpression.Object as MethodCallExpression;
					if (methodCallExpression2 != null)
					{
						allMethods.Add(methodCallExpression2);
					}
					methodCallExpression = methodCallExpression2;
				}
			}

			public string GetSql()
			{
				allMethods.Reverse();
				List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
				foreach (MethodCallExpression allMethod in allMethods)
				{
					allMethods.First();
					allMethods.Last();
					bool flag = false;
					if (allMethod.Arguments.Count == 0)
					{
						list.Add(new KeyValuePair<string, string>(allMethod.Method.Name, "null"));
						continue;
					}
					Expression expression = allMethod.Arguments[0];
					if (ExpressionTool.IsNegate(expression))
					{
						flag = true;
						expression = (expression as UnaryExpression).Operand;
					}
					if (allMethod.Method.Name.IsIn("Return", "End") && expression.Type == UtilConstants.BoolType && ExpressionTool.IsEqualOrLtOrGt(expression))
					{
						expression = ExpressionTool.GetConditionalExpression(expression);
					}
					else if (allMethod.Method.Name.IsIn("Return", "End") && expression.Type == UtilConstants.BoolType && ExpressionTool.GetMethodName(expression).IsIn("Contains", "StartsWith", "EndsWith"))
					{
						expression = ExpressionTool.GetConditionalExpression(expression);
					}
					string sql = SubTools.GetMethodValue(context, expression, context.IsSingle ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple);
					if (allMethod.Method.Name == "IF")
					{
						SugarParameter sugarParameter = context.Parameters.FirstOrDefault((SugarParameter it) => it.ParameterName == sql.Trim());
						if (sugarParameter != null && sugarParameter.Value is bool)
						{
							sql = (Convert.ToBoolean(sugarParameter.Value) ? " 1=1 " : " 1=2 ");
							context.Parameters.Remove(sugarParameter);
						}
					}
					if (flag)
					{
						sql = " (" + sql + "*-1) ";
					}
					list.Add(new KeyValuePair<string, string>(allMethod.Method.Name, sql));
				}
				return context.DbMehtods.CaseWhen(list);
			}
		}
