		public class ExpressionResult
		{
			private ExpressionParameter _CurrentParameter;

			private ResolveExpressType _ResolveExpressType;

			private StringBuilder _Result;

			public bool IsLockCurrentParameter { get; set; }

			public bool IsUpper { get; set; }

			public bool IsNavicate { get; set; }

			public ExpressionParameter CurrentParameter
			{
				get
				{
					return _CurrentParameter;
				}
				set
				{
					Check.Exception(value != null && IsLockCurrentParameter, "CurrentParameter is locked.");
					_CurrentParameter = value;
					IsLockCurrentParameter = false;
				}
			}

			private StringBuilder Result
			{
				get
				{
					if (_Result == null)
					{
						_Result = new StringBuilder();
					}
					return _Result;
				}
				set
				{
					_Result = value;
				}
			}

			public bool LastCharIsSpace
			{
				get
				{
					if (_Result == null || _Result.Length == 0)
					{
						return true;
					}
					return _Result.ToString().Last() == ' ';
				}
			}

			private ExpressionResult()
			{
			}

			public ExpressionResult(ResolveExpressType resolveExpressType)
			{
				_ResolveExpressType = resolveExpressType;
			}

			public string GetString()
			{
				if (_Result == null)
				{
					return null;
				}
				if (IsUpper)
				{
					return _Result.ToString().ToUpper().Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",")
						.TrimEnd(',');
				}
				return _Result.ToString().Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",").TrimEnd(',');
			}

			public string[] GetResultArray()
			{
				if (_Result == null)
				{
					return null;
				}
				List<string> list = new List<string>();
				list = ((!IsUpper) ? Result.ToString().TrimEnd(',').Split(',')
					.ToList() : Result.ToString().ToUpper().TrimEnd(',')
					.Split(',')
					.ToList());
				if (Result.ToString().Contains("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}"))
				{
					for (int i = 0; i < list.Count; i++)
					{
						list[i] = list[i].Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",");
					}
				}
				return list.ToArray();
			}

			public string GetResultString()
			{
				if (_Result == null)
				{
					return null;
				}
				if (_ResolveExpressType.IsIn(ResolveExpressType.SelectMultiple, ResolveExpressType.SelectSingle))
				{
					return Result.ToString().Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",").TrimEnd(',');
				}
				if (IsUpper)
				{
					return Result.ToString().Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",").ToUpper();
				}
				return Result.ToString().Replace("{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}", ",");
			}

			public void TrimEnd()
			{
				if (_Result != null)
				{
					Result = Result.Remove(Result.Length - 1, 1);
				}
			}

			public bool Contains(string value)
			{
				if (Result.Equals(value))
				{
					return true;
				}
				return Result.ToString().ToLower().Contains(value?.ToLower());
			}

			internal void Insert(int index, string value)
			{
				if (Result == null)
				{
					Result.Append(value);
				}
				Result.Insert(index, value);
			}

			public void Append(object parameter)
			{
				if (CurrentParameter.HasValue() && CurrentParameter.AppendType.IsIn(ExpressionResultAppendType.AppendTempDate))
				{
					CurrentParameter.CommonTempData = parameter;
					return;
				}
				switch (_ResolveExpressType)
				{
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
				case ResolveExpressType.Update:
					parameter = parameter?.ToString() + ",";
					break;
				}
				if (Result.Length > 0 && Result[Result.Length - 1] == ',' && parameter != null && parameter.ToString()?.StartsWith("  AS ") == true && parameter != null && parameter.ToString()?.EndsWith(" ,") == true)
				{
					Result.Length--;
				}
				Result.Append(parameter);
			}

			public void AppendFormat(string parameter, params object[] orgs)
			{
				if (CurrentParameter.HasValue() && CurrentParameter.AppendType.IsIn(ExpressionResultAppendType.AppendTempDate))
				{
					CurrentParameter.CommonTempData = new KeyValuePair<string, object[]>(parameter, orgs);
					return;
				}
				switch (_ResolveExpressType)
				{
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
					parameter += ",";
					break;
				}
				Result.AppendFormat(parameter, orgs);
			}

			public void Replace(string parameter, string newValue)
			{
				Result.Replace(parameter, newValue);
			}
		}
		public enum ExpressionResultAppendType
		{
			AppendResult,
			AppendTempDate
		}
