			public static bool ContainsTwoLevelAccess(Expression exp)
			{
				bool result = false;
				if (exp is LambdaExpression { Body: MemberInitExpression body } lambdaExpression)
				{
					ParameterExpression parameterExpression = lambdaExpression.Parameters[0];
					foreach (MemberBinding binding in body.Bindings)
					{
						if (binding is MemberAssignment { Expression: MemberExpression { Expression: MemberExpression expression2 } } && expression2.Expression == parameterExpression)
						{
							result = true;
							break;
						}
					}
				}
				return result;
			}

