					string text2 = Guid.NewGuid().ToString() ?? "";
					value = value.Replace("(", text).Replace(")", text2);
					value = context.GetTranslationColumnName(value);
					value = value.Replace(text, "(").Replace(text2, ")");
				}
				return value;
			}

