			internal static SugarParameter GetParameterBySqlParameterDbType(int index, object value, ExpressionContext context, Expression member)
			{
				Expression expression = (member as MemberExpression)?.Expression;
				EntityColumnInfo entityColumnInfo = (context?.SugarContext.Context.EntityMaintenance.GetEntityInfo(expression.Type)).Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == GetMemberName(member));
				Type type = entityColumnInfo.SqlParameterDbType as Type;
				if (type != null)
				{
					MethodInfo methodInfo = type.GetMethod("ParameterConverter").MakeGenericMethod(entityColumnInfo.PropertyInfo.PropertyType);
					object obj = Activator.CreateInstance(type);
					return methodInfo.Invoke(obj, new object[2] { value, index }) as SugarParameter;
				}
				SugarParameter sugarParameter = new SugarParameter("@Common" + index, value)
				{
					DbType = (System.Data.DbType)entityColumnInfo.SqlParameterDbType
				};
				if (entityColumnInfo.SqlParameterSize != null && entityColumnInfo.SqlParameterSize.ObjToInt() > 0)
				{
					sugarParameter.Size = entityColumnInfo.SqlParameterSize.ObjToInt();
				}
				return sugarParameter;
			}

