			public static Dictionary<string, Expression> GetNewExpressionItemList(Expression lamExp)
			{
				Expression lambdaExpressionBody = GetLambdaExpressionBody(lamExp);
				if (lambdaExpressionBody is MemberInitExpression)
				{
					return GetMemberBindingItemList((lambdaExpressionBody as MemberInitExpression).Bindings);
				}
				NewExpression newExpression = lambdaExpressionBody as NewExpression;
				if (newExpression == null)
				{
					Check.ExceptionEasy("Use Select(it=>new class(){})", "导航查询请使用Select(it=>new class(){})");
				}
				Dictionary<string, Expression> dictionary = new Dictionary<string, Expression>();
				for (int i = 0; i < newExpression.Arguments.Count; i++)
				{
					Expression value = newExpression.Arguments[i];
					ParameterInfo parameterInfo = newExpression.Constructor.GetParameters()[i];
					dictionary.Add(parameterInfo.Name, value);
				}
				return dictionary;
			}

