			public static string GetOperator(ExpressionType expressiontype)
			{
				switch (expressiontype)
				{
				case ExpressionType.And:
					return "&";
				case ExpressionType.AndAlso:
					return "AND";
				case ExpressionType.Equal:
					return "=";
				case ExpressionType.GreaterThan:
					return ">";
				case ExpressionType.GreaterThanOrEqual:
					return ">=";
				case ExpressionType.LessThan:
					return "<";
				case ExpressionType.LessThanOrEqual:
					return "<=";
				case ExpressionType.NotEqual:
					return "<>";
				case ExpressionType.Or:
					return "|";
				case ExpressionType.OrElse:
					return "OR";
				case ExpressionType.Add:
				case ExpressionType.AddChecked:
					return "+";
				case ExpressionType.Subtract:
				case ExpressionType.SubtractChecked:
					return "-";
				case ExpressionType.Divide:
					return "/";
				case ExpressionType.Multiply:
				case ExpressionType.MultiplyChecked:
					return "*";
				case ExpressionType.Modulo:
					return "%";
				case ExpressionType.Coalesce:
					throw new Exception("Expression no support ?? ,Use SqlFunc.IsNull");
				default:
					Check.ThrowNotSupportedException(string.Format(ErrorMessage.OperatorError, expressiontype.ToString()));
					return null;
				}
			}

			public static void GetOneToOneInfo<T>(SqlSugarProvider context, Expression<Func<T, object>> LeftObject, out MemberExpression memberExpression, out string navObjectName, out EntityColumnInfo navColumn, out EntityInfo navEntityInfo, out EntityColumnInfo navPkColumn)
			{
				memberExpression = LeftObject.Body as MemberExpression;
				Type typeFromHandle = typeof(T);
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(typeFromHandle);
				entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				navObjectName = memberExpression.Member.Name;
				string navObjectName2 = navObjectName;
				PropertyInfo? property = typeFromHandle.GetProperty(navObjectName);
				EntityColumnInfo navObjectNameColumnInfo = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == navObjectName2);
				Check.ExceptionEasy(navObjectNameColumnInfo.Navigat == null, navObjectName + " not [Navigat(..)] ", navObjectName + " 没有导航特性 [Navigat(..)] ");
				Check.ExceptionEasy(navObjectNameColumnInfo.Navigat.NavigatType != NavigateType.OneToOne, "IncludeLeftJoin can only be one-on-one ", "IncludeLeftJoin 只能是一对一 ");
				navColumn = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name);
				Check.ExceptionEasy(navColumn == null, "OneToOne navigation configuration error", "OneToOne导航配置错误： 实体" + entityInfo.EntityName + " 不存在" + navObjectNameColumnInfo.Navigat.Name);
				Type propertyType = property.PropertyType;
				navEntityInfo = context.EntityMaintenance.GetEntityInfo(propertyType);
				context.InitMappingInfo(navEntityInfo.Type);
				navPkColumn = navEntityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).FirstOrDefault();
				Check.ExceptionEasy(navPkColumn == null && navObjectNameColumnInfo.Navigat.Name2 == null, navEntityInfo.EntityName + "need primarykey", navEntityInfo.EntityName + " 需要主键");
				if (navObjectNameColumnInfo.Navigat.Name2.HasValue())
				{
					navPkColumn = navEntityInfo.Columns.Where((EntityColumnInfo it) => it.PropertyName == navObjectNameColumnInfo.Navigat.Name2).FirstOrDefault();
				}
			}

