			public static object GetMemberValue(MemberInfo member, Expression expression)
			{
				MemberExpression memberExpression = expression as MemberExpression;
				Stack<MemberInfo> stack = new Stack<MemberInfo>();
				MemberExpression memberExpression2 = null;
				while (expression is MemberExpression)
				{
					memberExpression2 = expression as MemberExpression;
					stack.Push(memberExpression2.Member);
					if (memberExpression2.Expression == null)
					{
						bool num = memberExpression2.Member.MemberType == MemberTypes.Property;
						bool flag = memberExpression2.Member.MemberType == MemberTypes.Field;
						if (num)
						{
							try
							{
								GetPropertyValue(memberExpression2);
							}
							catch
							{
							}
						}
						else if (flag)
						{
							GetFiledValue(memberExpression2);
						}
					}
					_ = memberExpression2.Expression;
					expression = memberExpression2.Expression;
				}
				if (!(expression is ConstantExpression constantExpression))
				{
					return DynamicInvoke(memberExpression);
				}
				object obj2 = constantExpression.Value;
				while (stack.Count > 0)
				{
					MemberInfo mi = stack.Pop();
					if (mi.MemberType == MemberTypes.Property)
					{
						if (obj2 == null)
						{
							return null;
						}
						PropertyInfo propertyInfo = (from it in obj2.GetType().GetProperties()
							where it.Name == mi.Name
							select it).FirstOrDefault();
						obj2 = ((!(propertyInfo == null)) ? propertyInfo.GetValue(obj2, null) : DynamicInvoke(expression, (memberExpression == null) ? memberExpression2 : memberExpression));
					}
					else if (mi.MemberType == MemberTypes.Field)
					{
						FieldInfo field = obj2.GetType().GetField(mi.Name);
						obj2 = ((!(field == null)) ? field.GetValue(obj2) : DynamicInvoke(expression, (memberExpression == null) ? memberExpression2 : memberExpression));
					}
				}
				return obj2;
			}

			internal static Expression RemoveConvert(Expression item)
			{
				for (int i = 0; i < 10; i++)
				{
					if (!(item is UnaryExpression))
					{
						break;
					}
					if ((item as UnaryExpression).NodeType != ExpressionType.Convert)
					{
						break;
					}
					item = (item as UnaryExpression).Operand;
				}
				return item;
			}

			internal static Expression RemoveConvertThanOne(Expression item)
			{
				for (int i = 0; i < 10; i++)
				{
					if (!(item is UnaryExpression))
					{
						break;
					}
					if ((item as UnaryExpression).NodeType != ExpressionType.Convert)
					{
						break;
					}
					if (!((item as UnaryExpression).Operand is UnaryExpression))
					{
						break;
					}
					item = (item as UnaryExpression).Operand;
				}
				return item;
			}

			public static string GetMemberName(Expression expression)
			{
				if (expression is LambdaExpression)
				{
					expression = (expression as LambdaExpression).Body;
				}
				if (expression is UnaryExpression)
				{
					expression = ((UnaryExpression)expression).Operand;
				}
				return (expression as MemberExpression)?.Member?.Name;
			}

			internal static object GetExpressionValue(Expression expression)
			{
				try
				{
					if (expression is ConstantExpression)
					{
						return (expression as ConstantExpression).Value;
					}
					if (expression is MethodCallExpression)
					{
						return Expression.Lambda(expression).Compile().DynamicInvoke();
					}
					return GetMemberValue((expression as MemberExpression).Member, expression);
				}
				catch
				{
					return Expression.Lambda(expression).Compile().DynamicInvoke();
				}
			}

			public static object GetFiledValue(MemberExpression memberExpr)
			{
				if (!(memberExpr.Member is FieldInfo))
				{
					return DynamicInvoke(memberExpr);
				}
				object obj = null;
				FieldInfo fieldInfo = (FieldInfo)memberExpr.Member;
				Check.Exception(fieldInfo.IsPrivate, $" Field \"{fieldInfo.Name}\" can't be private ");
				obj = fieldInfo.GetValue(memberExpr.Member);
				if (obj != null && obj.GetType().IsClass() && obj.GetType() != UtilConstants.StringType)
				{
					string name = memberExpr.Member.Name;
					PropertyInfo property = obj.GetType().GetProperty(name);
					if (property != null)
					{
						obj = property.GetValue(obj, null);
					}
					FieldInfo field = obj.GetType().GetField(name);
					if (field != null)
					{
						obj = field.GetValue(obj);
					}
					if (field == null && property == null)
					{
						Check.Exception(fieldInfo.IsPrivate, $" Field \"{fieldInfo.Name}\" can't be private ");
					}
				}
				return obj;
			}

			public static bool IsConstExpression(MemberExpression memberExpr)
			{
				bool result = false;
				while (memberExpr != null && memberExpr.Expression != null)
				{
					if (memberExpr.Expression is ConstantExpression)
					{
						result = true;
						break;
					}
					if (memberExpr.Expression is BinaryExpression && (memberExpr.Expression as BinaryExpression).NodeType == ExpressionType.ArrayIndex)
					{
						result = true;
						break;
					}
					memberExpr = memberExpr.Expression as MemberExpression;
				}
				return result;
			}

			public static object GetPropertyValue(MemberExpression memberExpr)
			{
				if (!(memberExpr.Member is PropertyInfo))
				{
					return DynamicInvoke(memberExpr);
				}
				object obj = null;
				PropertyInfo propertyInfo = (PropertyInfo)memberExpr.Member;
				obj = propertyInfo.GetValue(memberExpr.Member, null);
				if (obj != null && obj.GetType().IsClass() && obj.GetType() != UtilConstants.StringType)
				{
					string name = memberExpr.Member.Name;
					PropertyInfo property = obj.GetType().GetProperty(name);
					if (property != null)
					{
						obj = property.GetValue(obj, null);
					}
					FieldInfo field = obj.GetType().GetField(name);
					if (field != null)
					{
						obj = field.GetValue(obj);
					}
					if (field == null && property == null && !obj.GetType().FullName.IsCollectionsList())
					{
						Check.Exception(true, $" Property \"{propertyInfo.Name}\" can't be private ");
					}
				}
				return obj;
			}

			public static object DynamicInvoke(Expression expression, MemberExpression memberExpression = null)
			{
				try
				{
					object obj = Expression.Lambda(expression).Compile().DynamicInvoke();
					if (obj != null && obj.GetType().IsClass() && obj.GetType() != UtilConstants.StringType && memberExpression != null)
					{
						obj = Expression.Lambda(memberExpression).Compile().DynamicInvoke();
					}
					return obj;
				}
				catch (InvalidOperationException ex)
				{
					return new MapperExpressionResolve(expression, ex).GetSql();
				}
				catch (Exception ex2)
				{
					throw new Exception("No support " + expression.ToString() + " " + ex2.Message);
				}
			}

			public static Type GetPropertyOrFieldType(MemberInfo propertyOrField)
			{
				if (propertyOrField.MemberType == MemberTypes.Property)
				{
					return ((PropertyInfo)propertyOrField).PropertyType;
				}
				if (propertyOrField.MemberType == MemberTypes.Field)
				{
					return ((FieldInfo)propertyOrField).FieldType;
				}
				throw new NotSupportedException();
			}

			public static bool IsEntity(Type type)
			{
				if (type.IsClass())
				{
					return type != UtilConstants.StringType;
				}
				return false;
			}

			public static bool IsValueType(Type type)
			{
				return !IsEntity(type);
			}

			public static bool IsUnConvertExpress(Expression item)
			{
				if (item is UnaryExpression)
				{
					return item.NodeType == ExpressionType.Convert;
				}
				return false;
			}

			internal static List<NewExpressionInfo> GetNewexpressionInfos(Expression item, ExpressionContext context, BaseResolve baseResolve)
			{
				List<NewExpressionInfo> list = new List<NewExpressionInfo>();
				foreach (MemberBinding binding in ((MemberInitExpression)item).Bindings)
				{
					if (binding.BindingType != MemberBindingType.Assignment)
					{
						throw new NotSupportedException();
					}
					MemberAssignment memberAssignment = (MemberAssignment)binding;
					NewExpressionInfo newExpressionInfo = new NewExpressionInfo();
					if (memberAssignment.Expression is MemberExpression)
					{
						newExpressionInfo.LeftNameName = memberAssignment.Member.Name;
						Expression expression = (memberAssignment.Expression as MemberExpression).Expression;
						newExpressionInfo.ShortName = expression?.ToString() ?? "";
						newExpressionInfo.RightName = (memberAssignment.Expression as MemberExpression).Member.Name;
						newExpressionInfo.RightDbName = context.GetDbColumnName(expression.Type.Name, newExpressionInfo.RightName);
						if (IsNavMember(context, expression))
						{
							NewExpressionInfo newExpressionInfo2 = newExpressionInfo;
							string rightDbName = (newExpressionInfo.RightName = baseResolve.GetNewExpressionValue(memberAssignment.Expression));
							newExpressionInfo2.RightDbName = rightDbName;
						}
						list.Add(newExpressionInfo);
					}
					else if (memberAssignment.Expression is ConstantExpression)
					{
						object value = ((ConstantExpression)memberAssignment.Expression).Value;
						newExpressionInfo.Type = "ConstantExpression";
						newExpressionInfo.RightName = memberAssignment.Member.Name;
						newExpressionInfo.ShortName = memberAssignment.Member.Name;
						newExpressionInfo.RightName = memberAssignment.Member.Name;
						newExpressionInfo.LeftNameName = memberAssignment.Member.Name;
						newExpressionInfo.RightDbName = UtilMethods.GetSqlValue(value);
						list.Add(newExpressionInfo);
					}
					else if (memberAssignment.Expression is MemberInitExpression || memberAssignment.Expression is NewExpression)
					{
						foreach (KeyValuePair<string, Expression> newExpressionItem in GetNewExpressionItemList(memberAssignment.Expression))
						{
							newExpressionInfo = new NewExpressionInfo();
							newExpressionInfo.Type = "NewExpression";
							newExpressionInfo.RightName = newExpressionItem.Key;
							newExpressionInfo.ShortName = GetParameters(newExpressionItem.Value).First().Name;
							newExpressionInfo.RightName = newExpressionItem.Key;
							newExpressionInfo.LeftNameName = memberAssignment.Member.Name + "." + newExpressionItem.Key;
							newExpressionInfo.RightDbName = newExpressionItem.Key;
							list.Add(newExpressionInfo);
						}
					}
					else
					{
						string newExpressionValue2 = baseResolve.GetNewExpressionValue(RemoveConvert(memberAssignment.Expression));
						newExpressionInfo.Type = "ConstantExpression";
						newExpressionInfo.RightName = memberAssignment.Member.Name;
						newExpressionInfo.ShortName = memberAssignment.Member.Name;
						newExpressionInfo.RightName = memberAssignment.Member.Name;
						newExpressionInfo.LeftNameName = memberAssignment.Member.Name;
						newExpressionInfo.RightDbName = newExpressionValue2;
						list.Add(newExpressionInfo);
					}
				}
				return list;
			}

			internal static List<NewExpressionInfo> GetNewDynamicexpressionInfos(Expression item, ExpressionContext context, BaseResolve baseResolve)
			{
				List<NewExpressionInfo> list = new List<NewExpressionInfo>();
				int num = 0;
				foreach (Expression argument in ((NewExpression)item).Arguments)
				{
					NewExpressionInfo newExpressionInfo = new NewExpressionInfo();
					ReadOnlyCollection<MemberInfo> members = ((NewExpression)item).Members;
					if (argument is MemberExpression)
					{
						MemberExpression member = (MemberExpression)argument;
						string entityName = member.Expression?.Type?.Name;
						newExpressionInfo.RightName = member.Member.Name;
						newExpressionInfo.ShortName = member.Expression?.ToString() ?? "";
						newExpressionInfo.RightName = member.Member.Name;
						newExpressionInfo.RightDbName = context.GetDbColumnName(entityName, newExpressionInfo.RightName);
						bool flag = member.Expression != null && IsNavMember(context, member.Expression);
						newExpressionInfo.LeftNameName = member.Member.Name;
						if (flag && (context?.SugarContext?.QueryBuilder?.JoinQueryInfos?.Count()).GetValueOrDefault() == 0)
						{
							ExpressionContext copyContextWithMapping = context.GetCopyContextWithMapping();
							copyContextWithMapping.Resolve(member, ResolveExpressType.FieldSingle);
							string resultString = copyContextWithMapping.Result.GetResultString();
							if (context.IsSingle && context.CurrentShortName.IsNullOrEmpty())
							{
								context.SingleTableNameSubqueryShortName = GetParameters(member)?.FirstOrDefault()?.Name;
							}
							newExpressionInfo.RightDbName = resultString;
						}
						else if (flag && context != null && context.SugarContext?.QueryBuilder?.JoinQueryInfos?.Any((JoinQueryInfo it) => it.ShortName?.StartsWith("pnv_" + GetMemberName(member.Expression)) ?? false) == true)
						{
							newExpressionInfo.ShortName = "pnv_" + GetMemberName(member.Expression);
						}
						list.Add(newExpressionInfo);
					}
					else if (argument is ConstantExpression)
					{
						object value = ((ConstantExpression)argument).Value;
						MemberInfo memberInfo = members[num];
						newExpressionInfo.Type = "ConstantExpression";
						newExpressionInfo.RightName = memberInfo.Name;
						newExpressionInfo.ShortName = memberInfo.Name;
						newExpressionInfo.RightName = memberInfo.Name;
						newExpressionInfo.LeftNameName = memberInfo.Name;
						newExpressionInfo.RightDbName = UtilMethods.GetSqlValue(value);
						list.Add(newExpressionInfo);
					}
					else if (argument is MemberInitExpression || argument is NewExpression)
					{
						foreach (KeyValuePair<string, Expression> newExpressionItem in GetNewExpressionItemList(argument))
						{
							newExpressionInfo = new NewExpressionInfo();
							newExpressionInfo.Type = "NewExpression";
							newExpressionInfo.RightName = newExpressionItem.Key;
							newExpressionInfo.ShortName = GetParameters(newExpressionItem.Value).First().Name;
							newExpressionInfo.RightName = newExpressionItem.Key;
							newExpressionInfo.LeftNameName = members[num].Name + "." + newExpressionItem.Key;
							newExpressionInfo.RightDbName = newExpressionItem.Key;
							list.Add(newExpressionInfo);
						}
					}
					else
					{
						string newExpressionValue = baseResolve.GetNewExpressionValue(argument);
						MemberInfo memberInfo2 = members[num];
						newExpressionInfo.Type = "ConstantExpression";
						newExpressionInfo.RightName = memberInfo2.Name;
						newExpressionInfo.ShortName = memberInfo2.Name;
						newExpressionInfo.RightName = memberInfo2.Name;
						newExpressionInfo.LeftNameName = memberInfo2.Name;
						newExpressionInfo.RightDbName = newExpressionValue;
						list.Add(newExpressionInfo);
					}
					num++;
				}
				return list;
			}

			internal static bool IsSubQuery(Expression it)
			{
				if (it is MethodCallExpression)
				{
					MethodCallExpression methodCallExpression = (MethodCallExpression)it;
					if (methodCallExpression.Object != null && methodCallExpression.Object.Type.Name.StartsWith("Subquery"))
					{
						return true;
					}
				}
				return false;
			}

			internal static bool IsIsNullSubQuery(Expression it)
			{
				if (it is MethodCallExpression)
				{
					MethodCallExpression methodCallExpression = (MethodCallExpression)it;
					if (methodCallExpression.Method.Name == "IsNull" && methodCallExpression.Arguments.Count == 2 && IsSubQuery(methodCallExpression.Arguments[0]))
					{
						return true;
					}
				}
				return false;
			}

			internal static bool IsMemberInit(object selectValue)
			{
				bool result = false;
				if (selectValue is Expression)
				{
					if (selectValue is MemberInitExpression)
					{
						result = true;
					}
					else if (selectValue is LambdaExpression && ((LambdaExpression)selectValue).Body is MemberInitExpression)
					{
						result = true;
					}
				}
				return result;
			}

			internal static MemberInitExpression GetMemberInit(object selectValue)
			{
				MemberInitExpression result = null;
				if (selectValue is Expression)
				{
					if (selectValue is MemberInitExpression)
					{
						result = (MemberInitExpression)selectValue;
					}
					else if (selectValue is LambdaExpression)
					{
						LambdaExpression lambdaExpression = (LambdaExpression)selectValue;
						if (lambdaExpression.Body is MemberInitExpression)
						{
							result = (MemberInitExpression)lambdaExpression.Body;
						}
					}
				}
				return result;
			}

			public static bool IsNegate(Expression exp)
			{
				if (exp is UnaryExpression)
				{
					return exp.NodeType == ExpressionType.Negate;
				}
				return false;
			}

			public static bool GetIsLength(Expression item)
			{
				if (item is MemberExpression && (item as MemberExpression).Member.Name == "Length")
				{
					Expression expression = (item as MemberExpression).Expression;
					if (expression == null)
					{
						return false;
					}
					if (expression.Type == UtilConstants.StringType && item.Type == UtilConstants.IntType)
					{
						return true;
					}
					return false;
				}
				return false;
			}
		}
