				list.Add(new MethodCallExpressionArgs
				{
					MemberName = str,
					MemberValue = str
				});
				list.AddRange((array as string[]).Select((string it) => new MethodCallExpressionArgs
				{
					MemberValue = it,
					MemberName = it,
					IsMember = (((it != null && it.StartsWith("[")) || (it != null && it.StartsWith("`")) || (it != null && it.StartsWith("\""))) && ((it != null && it.EndsWith("]")) || (it != null && it.EndsWith("`")) || (it?.EndsWith("\"") ?? false)))
				}));
				return list;
			}

