			public virtual string FullTextContains(MethodCallExpressionModel mode)
			{
				object value = mode.Args[0].MemberName;
				if (mode.Args[0].MemberValue is List<string>)
				{
					value = string.Join("|| ' ' ||", mode.Args[0].MemberValue as List<string>);
				}
				object memberName = mode.Args[1].MemberName;
				return $"to_tsvector('chinese', {value}) @@ to_tsquery('chinese', {memberName})";
			}

			public virtual string PgsqlArrayContains(MethodCallExpressionModel model)
			{
				string text = model.Args[1].MemberValue.ToString();
				string value = "text";
				if (model.Args[1].MemberValue is int)
				{
					value = "int4";
				}
				else if (model.Args[1].MemberValue is long)
				{
					value = "int8";
				}
				else if (model.Args[1].MemberValue is short)
				{
					value = "int2";
				}
				if (!UtilMethods.IsNumber(model.Args[1].MemberValue.GetType().Name))
				{
					text = "'" + text + "'";
				}
				return $"{model.Args[0].MemberName}::{value}[] @> ARRAY[{text}]";
			}

			public virtual string SelectFields(MethodCallExpressionModel model)
			{
				return string.Join(",", model.Args.Select((MethodCallExpressionArgs it) => it.MemberName));
			}

			public virtual string UNIX_TIMESTAMP(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				return $" UNIX_TIMESTAMP({memberName}) ";
			}
		}
