			public virtual string GetTranslationTableName(string entityName, bool isMapping = true)
			{
				Check.ArgumentNullException(entityName, string.Format(ErrorMessage.ObjNotExist, "Table Name"));
				if (IsTranslationText(entityName))
				{
					return entityName;
				}
				isMapping = isMapping && MappingTables.HasValue();
				bool flag = entityName.Contains(".");
				if (isMapping & flag)
				{
					string[] columnInfo = entityName.Split('.');
					MappingTable mappingTable = MappingTables.FirstOrDefault((MappingTable it) => it.EntityName.Equals(columnInfo.Last(), StringComparison.CurrentCultureIgnoreCase));
					if (mappingTable != null)
					{
						columnInfo[columnInfo.Length - 1] = mappingTable.EntityName;
					}
					return string.Join(".", columnInfo.Select((string it) => GetTranslationText(it)));
				}
				if (isMapping)
				{
					MappingTable mappingTable2 = MappingTables.FirstOrDefault((MappingTable it) => it.EntityName.Equals(entityName, StringComparison.CurrentCultureIgnoreCase));
					string text = ((mappingTable2 == null) ? entityName : mappingTable2.DbTableName);
					if (text.Contains(SqlTranslationLeft) && text.Contains(SqlTranslationRight))
					{
						return text;
					}
					if (text.Contains("."))
					{
						return string.Join(".", from it in text.Split('.')
							select SqlTranslationLeft + it + SqlTranslationRight);
					}
					return SqlTranslationLeft + text + SqlTranslationRight;
				}
				if (flag)
				{
					return string.Join(".", from it in entityName.Split('.')
						select GetTranslationText(it));
				}
				return GetTranslationText(entityName);
			}

			public virtual string GetTranslationColumnName(string columnName)
			{
				Check.ArgumentNullException(columnName, string.Format(ErrorMessage.ObjNotExist, "Column Name"));
				if (columnName.Substring(0, 1) == SqlParameterKeyWord || columnName.Substring(0, 1) == "@")
				{
					return columnName;
				}
				ExpressionOutParameter sugarContext = SugarContext;
				if (sugarContext != null && sugarContext.Context?.CurrentConnectionConfig?.MoreSettings?.IsCorrectErrorSqlParameterName == true)
				{
					if (IsTranslationText(columnName.Replace(" ", "")))
					{
						return columnName;
					}
					return GetTranslationText(columnName);
				}
				if (IsTranslationText(columnName))
				{
					return columnName;
				}
				if (columnName.Contains("."))
				{
					return string.Join(".", from it in columnName.Split('.')
						select GetTranslationText(it));
				}
				return GetTranslationText(columnName);
			}

			public virtual string GetDbColumnName(string entityName, string propertyName)
			{
				if (MappingColumns.HasValue())
				{
					MappingColumn mappingColumn = MappingColumns.SingleOrDefault((MappingColumn it) => it.EntityName == entityName && it.PropertyName == propertyName);
					if (mappingColumn != null)
					{
						return mappingColumn.DbColumnName;
					}
					return propertyName;
				}
				return propertyName;
			}

			public virtual bool IsTranslationText(string name)
			{
				return name.IsContainsIn(SqlTranslationLeft, SqlTranslationRight, " ", "(", ")");
			}

			public virtual string GetTranslationText(string name)
			{
				return SqlTranslationLeft + name + SqlTranslationRight;
			}

			public virtual string GetAsString(string asName, string fieldValue)
			{
				if (fieldValue.Contains(".*") || fieldValue == "*")
				{
					return fieldValue;
				}
				return string.Format(" {0} {1} {2} ", GetTranslationColumnName(fieldValue), "AS", GetTranslationColumnName(asName));
			}

			public virtual string GetAsString2(string asName, string fieldValue)
			{
				if (fieldValue.Contains(".*") || fieldValue == "*")
				{
					return fieldValue;
				}
				return string.Format(" {0} {1} {2} ", fieldValue, "AS", GetTranslationColumnName(asName));
			}

			public virtual string GetEqString(string eqName, string fieldValue)
			{
				return string.Format(" {0} {1} {2} ", GetTranslationColumnName(eqName), "=", GetTranslationColumnName(fieldValue));
			}

			public virtual string GetAsString(string asName, string fieldValue, string fieldShortName)
			{
				if (fieldValue.Contains(".*") || fieldValue == "*")
				{
					return fieldValue;
				}
				return string.Format(" {0} {1} {2} ", GetTranslationColumnName(fieldShortName + "." + fieldValue), "AS", GetTranslationColumnName(asName));
			}
		}
		/// <summary>
		/// BaseResolve-Append
		/// </summary>
		/// <summary>
		/// BaseResolve-Append
		/// </summary>
		/// <summary>
		/// BaseResolve-Helper
		/// </summary>
		///  <summary>
		/// BaseResolve New Expression
		///  </summary>
		///  <summary>
		/// BaseResolve New Expression
		///  </summary>
		/// <summary>
		/// BaseResolve-Validate
		/// </summary>
		public class BaseResolve
		{
			protected static Dictionary<string, string> MethodMapping = new Dictionary<string, string>
			{
				{ "ToString", "ToString" },
				{ "ToInt32", "ToInt32" },
				{ "ToInt16", "ToInt32" },
