				{ "EndsWith", "EndsWith" },
				{ "StartsWith", "StartsWith" },
				{ "HasValue", "HasValue" },
				{ "Trim", "Trim" },
				{ "Equals", "Equals" },
				{ "ToLower", "ToLower" },
				{ "ToUpper", "ToUpper" },
				{ "Substring", "Substring" },
				{ "DateAdd", "DateAdd" },
				{ "CompareTo", "CompareTo" }
			};

			protected static Dictionary<string, DateType> MethodTimeMapping = new Dictionary<string, DateType>
			{
				{
					"AddYears",
					DateType.Year
				},
				{
					"AddMonths",
					DateType.Month
				},
				{
					"AddDays",
					DateType.Day
				},
				{
					"AddHours",
					DateType.Hour
				},
				{
					"AddMinutes",
					DateType.Minute
				},
				{
					"AddSeconds",
					DateType.Second
				},
				{
					"AddMilliseconds",
					DateType.Millisecond
				}
			};

			protected Expression Expression { get; set; }

			protected Expression ExactExpression { get; set; }

			public ExpressionContext Context { get; set; }

			public bool? IsLeft { get; set; }

			public int ContentIndex => Context.Index;

			public int Index { get; set; }

			public ExpressionParameter BaseParameter { get; set; }

			private BaseResolve()
			{
			}

			public BaseResolve(ExpressionParameter parameter)
			{
				Expression = parameter.CurrentExpression;
				Context = parameter.Context;
				BaseParameter = parameter;
			}

			public BaseResolve Start()
			{
				SetParameter(out Expression expression, out ExpressionParameter parameter);
				if (expression is LambdaExpression)
				{
					return new LambdaExpressionResolve(parameter);
				}
				if (expression is BinaryExpression && expression.NodeType == ExpressionType.Coalesce)
				{
					return new CoalesceResolveItems(parameter);
				}
				if (expression is BinaryExpression)
				{
					return new BinaryExpressionResolve(parameter);
				}
				if (expression is BlockExpression)
				{
					Check.ThrowNotSupportedException("BlockExpression");
				}
				else
				{
					if (expression is ConditionalExpression)
					{
						return new ConditionalExpressionResolve(parameter);
					}
					if (expression is MethodCallExpression)
					{
						return new MethodCallExpressionResolve(parameter);
					}
					if (expression is MemberExpression && ((MemberExpression)expression).Expression == null)
					{
						return new MemberNoExpressionResolve(parameter);
					}
					if (expression is MemberExpression && ((MemberExpression)expression).Expression.NodeType == ExpressionType.Constant)
					{
						return new MemberConstExpressionResolve(parameter);
					}
					if (expression is MemberExpression && ((MemberExpression)expression).Expression.NodeType == ExpressionType.New)
					{
						return new MemberNewExpressionResolve(parameter);
					}
					if (expression is ConstantExpression)
					{
						return new ConstantExpressionResolve(parameter);
					}
					if (expression is MemberExpression)
					{
						return new MemberExpressionResolve(parameter);
					}
					if (expression is UnaryExpression)
					{
						return new UnaryExpressionResolve(parameter);
					}
					if (expression is MemberInitExpression)
					{
						return new MemberInitExpressionResolve(parameter);
					}
					if (expression is NewExpression)
					{
						return new NewExpressionResolve(parameter);
					}
					if (expression is NewArrayExpression)
					{
						return new NewArrayExpessionResolve(parameter);
					}
					if (expression is ParameterExpression)
					{
						return new TypeParameterExpressionReolve(parameter);
					}
					if (expression != null && expression.NodeType.IsIn(ExpressionType.NewArrayBounds))
					{
						Check.ThrowNotSupportedException("ExpressionType.NewArrayBounds");
					}
				}
				return null;
			}

			protected void AppendMember(ExpressionParameter parameter, bool? isLeft, object appendValue)
			{
				Context.ParameterIndex++;
				if (isLeft == true)
				{
					appendValue = appendValue?.ToString() + "46450BDC-77B7-4025-B2A6-3F048CA85AD0" + parameter.BaseParameter.Index;
				}
				if (Context.Result.Contains("{0}"))
				{
					Context.Result.Replace("{0}", appendValue.ObjToString());
				}
				else
				{
					Context.Result.Append(appendValue);
				}
			}

			protected void AppendValue(ExpressionParameter parameter, bool? isLeft, object value)
			{
				if (parameter.BaseExpression is BinaryExpression || parameter.BaseExpression == null)
				{
					Expression expression = ((isLeft == true) ? parameter.BaseParameter.RightExpression : parameter.BaseParameter.LeftExpression);
					if (value is MapperSql)
					{
						ApppendMapperSql(parameter, isLeft, value);
						return;
					}
					if (parameter.CurrentExpression is MethodCallExpression || parameter.CurrentExpression is ConditionalExpression || parameter.CurrentExpression.NodeType == ExpressionType.Coalesce)
					{
						AppendMethod(parameter, isLeft, value);
						return;
					}
					if (expression is MemberExpression)
					{
						AppendMember(parameter, isLeft, value, expression);
						return;
					}
					if (ExpressionTool.RemoveConvert(expression) is MemberExpression)
					{
						AppendMember(parameter, isLeft, value, ExpressionTool.RemoveConvert(expression));
						return;
					}
					value = ((expression is UnaryExpression && (expression as UnaryExpression).Operand is MemberExpression) ? AppendUnaryExp(parameter, isLeft, value, expression) : ((expression?.Type == UtilConstants.BoolType && value is bool flag && parameter != null && parameter.BaseParameter?.OperatorValue?.IsIn("AND", "OR") == true) ? AppendOtherBool(parameter, isLeft, flag ? " 1=1 " : " 1=2 ") : ((isLeft != true || !(value is bool flag2) || !(parameter?.BaseParameter?.BaseExpression is BinaryExpression { Left: UnaryExpression { NodeType: ExpressionType.Not } left }) || ExpressionTool.GetParameters(left).Count != 0) ? AppendOther(parameter, isLeft, value) : AppendOtherBool(parameter, isLeft, flag2 ? " (1=1) " : " (1=2) "))));
				}
			}

			private object AppendOther(ExpressionParameter parameter, bool? isLeft, object value)
			{
				string text = Context.SqlParameterKeyWord + "Const" + Context.ParameterIndex;
				Context.ParameterIndex++;
				if (value != null && value.GetType().IsEnum())
				{
					value = ((Context.TableEnumIsString != true) ? ((object)Convert.ToInt64(value)) : value.ToString());
				}
				Context.Parameters.Add(new SugarParameter(text, value));
				text = $" {text} ";
				if (isLeft == true)
				{
					text = text + "46450BDC-77B7-4025-B2A6-3F048CA85AD0" + parameter.BaseParameter.Index;
				}
				if (Context.Result.Contains("{0}"))
				{
					Context.Result.Replace("{0}", text);
				}
				else
				{
					Context.Result.Append(text);
				}
				return value;
			}

			private object AppendOtherBool(ExpressionParameter parameter, bool? isLeft, object value)
			{
				Context.ParameterIndex++;
				string text = value?.ToString() ?? "";
				if (isLeft == true)
				{
					text = text + "46450BDC-77B7-4025-B2A6-3F048CA85AD0" + parameter.BaseParameter.Index;
				}
				if (Context.Result.Contains("{0}"))
				{
					Context.Result.Replace("{0}", text);
				}
				else
				{
					Context.Result.Append(text);
				}
				return value;
			}

			private object AppendUnaryExp(ExpressionParameter parameter, bool? isLeft, object value, Expression oppoSiteExpression)
			{
				string text = Context.SqlParameterKeyWord + ((MemberExpression)(oppoSiteExpression as UnaryExpression).Operand).Member.Name + Context.ParameterIndex;
				if (value.ObjToString() != "NULL" && !parameter.ValueIsNull)
				{
					value = ((Context.TableEnumIsString == true) ? value.ToString() : value);
					Context.Parameters.Add(new SugarParameter(text, value));
				}
				else
				{
					text = value.ObjToString();
				}
				Context.ParameterIndex++;
				text = $" {text} ";
				if (isLeft == true)
				{
					text = text + "46450BDC-77B7-4025-B2A6-3F048CA85AD0" + parameter.BaseParameter.Index;
				}
				if (Context.Result.Contains("{0}"))
				{
					Context.Result.Replace("{0}", text);
				}
				else
				{
					Context.Result.Append(text);
				}
				return value;
			}

			private void AppendMember(ExpressionParameter parameter, bool? isLeft, object value, Expression oppoSiteExpression)
			{
				string text = Context.SqlParameterKeyWord + ((MemberExpression)oppoSiteExpression).Member.Name + Context.ParameterIndex;
				if (IsNullValue(parameter, value))
				{
					text = " NULL ";
					parameter.BaseParameter.ValueIsNull = true;
				}
				else if (value.ObjToString() != "NULL" && !parameter.ValueIsNull)
				{
					EntityColumnInfo columnInfo = GetColumnInfo(oppoSiteExpression);
					if (columnInfo != null && columnInfo.SqlParameterDbType != null && columnInfo.SqlParameterDbType is System.Data.DbType)
					{
						SugarParameter sugarParameter = new SugarParameter(text, value, (System.Data.DbType)columnInfo.SqlParameterDbType);
						if (columnInfo.SqlParameterSize != null)
						{
							sugarParameter.Size = columnInfo.SqlParameterSize.ObjToInt();
						}
