			private string GetAsNameResolveAnObject(ExpressionParameter parameter, Expression item, string asName, bool isSameType)
			{
				Start();
				object commonTempData = parameter.CommonTempData;
				foreach (PropertyInfo property in item.Type.GetProperties().Cast<PropertyInfo>().ToList())
				{
					if (Context.IgnoreComumnList != null && Context.IgnoreComumnList.Any((IgnoreColumn it) => it.EntityName.Equals(item.Type.Name, StringComparison.CurrentCultureIgnoreCase) && it.PropertyName.Equals(property.Name, StringComparison.CurrentCultureIgnoreCase)))
					{
						continue;
					}
					if (property.PropertyType.IsClass())
					{
						SugarColumn customAttribute = property.GetCustomAttribute<SugarColumn>();
						if ((customAttribute?.IsJson ?? false) & isSameType)
						{
							asName = GetAsNameAndShortName(item, commonTempData, property);
						}
						else if (customAttribute != null && customAttribute.IsJson)
						{
							asName = GetAsName(item, commonTempData, property);
						}
						else if (customAttribute != null && Context.SugarContext != null && Context.SugarContext.Context != null)
						{
							EntityColumnInfo entityColumnInfo = Context.SugarContext.Context.EntityMaintenance.GetEntityInfo(item.Type).Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == property.Name);
							if (entityColumnInfo != null && entityColumnInfo.IsJson)
							{
								asName = GetAsName(item, commonTempData, property);
							}
						}
					}
					else
					{
						asName = ((!isSameType) ? GetAsName(item, commonTempData, property) : GetAsNameAndShortName(item, commonTempData, property));
					}
				}
				return asName;
			}

