						List<string> list2 = (from it in item.Type.GetProperties()
							where it.PropertyType.IsClass() && !it.PropertyType.Name.StartsWith("System.")
							select it.PropertyType.Name).ToList();
						if (list2.Count > 0)
						{
							List<string> names = new List<string>();
							foreach (MemberBinding binding in ((MemberInitExpression)item).Bindings)
							{
								names.Add(binding.Member.Name);
							}
							list2 = list2.Where((string it) => !names.Contains(it)).ToList();
							QueryBuilder queryBuilder = Context?.SugarContext?.QueryBuilder;
							if (queryBuilder != null)
							{
								foreach (string item3 in list2)
								{
									if (queryBuilder.SelectNewIgnoreColumns == null)
									{
