					if (Context.Expression != null && Context.SingleTableNameSubqueryShortName.IsNullOrEmpty())
					{
						Context.SingleTableNameSubqueryShortName = (Context.Expression as LambdaExpression)?.Parameters?.FirstOrDefault()?.Name;
