				Context.ParameterIndex = copyContextWithMapping.ParameterIndex;
				if (copyContextWithMapping.Parameters.HasValue())
				{
					Context.Parameters.AddRange(copyContextWithMapping.Parameters);
				}
				if (ExpressionTool.IsEqualOrLtOrGt(item))
				{
					string text = copyContextWithMapping.Result.GetString();
					string text2 = AppendParameter(true);
					string text3 = AppendParameter(false);
					text = Context.DbMehtods.IIF(new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs>
						{
							new MethodCallExpressionArgs
							{
