			private void ResolveUnaryExpMem(ExpressionParameter parameter, Expression item, string asName)
			{
				if (!Context.Result.IsLockCurrentParameter)
				{
					MemberExpression memberExpression = ((UnaryExpression)item).Operand as MemberExpression;
					string text = string.Empty;
					if (item.NodeType == ExpressionType.Negate)
					{
						text = " -1*";
					}
					bool flag = ((UnaryExpression)item).Operand.ToString() == "DateTime.Now";
					if (memberExpression.Expression == null && !flag)
					{
						Context.Result.CurrentParameter = parameter;
						Context.Result.IsLockCurrentParameter = true;
						parameter.IsAppendTempDate();
						Expression = item;
						Start();
						parameter.IsAppendResult();
						Context.Result.Append(text + Context.GetAsString(asName, parameter.CommonTempData.ObjToString()));
						Context.Result.CurrentParameter = null;
					}
					else if ((memberExpression.Expression is ConstantExpression) | flag)
					{
						string text2 = Context.SqlParameterKeyWord + "constant" + Context.ParameterIndex;
						Context.ParameterIndex++;
						parameter.Context.Result.Append(text + Context.GetAsString(asName, text2));
						Context.Parameters.Add(new SugarParameter(text2, ExpressionTool.GetMemberValue(memberExpression.Member, memberExpression)));
					}
					else
					{
						Context.Result.CurrentParameter = parameter;
						Context.Result.IsLockCurrentParameter = true;
						parameter.IsAppendTempDate();
						Expression = memberExpression;
						Start();
						parameter.IsAppendResult();
						Context.Result.Append(text + Context.GetAsString(asName, parameter.CommonTempData.ObjToString()));
						Context.Result.CurrentParameter = null;
					}
				}
			}

