			protected void ResolveNewExpressions(ExpressionParameter parameter, Expression item, string asName)
			{
				if (item is ParameterExpression)
				{
					Type itemType = item.Type;
					PropertyInfo ignoreProperty = itemType.GetProperties().FirstOrDefault((PropertyInfo it) => it.PropertyType == itemType);
					if (ignoreProperty != null && ignoreProperty.Name != asName)
					{
						if (Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns == null)
						{
							Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns = new List<KeyValuePair<string, string>>();
						}
						Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns.Add(new KeyValuePair<string, string>(ignoreProperty.Name, itemType.Name));
					}
					if (Context?.SugarContext?.Context != null)
					{
						foreach (EntityColumnInfo item2 in Context?.SugarContext?.Context.EntityMaintenance.GetEntityInfo(item.Type).Columns.Where((EntityColumnInfo it) => it.PropertyInfo != ignoreProperty).Where((EntityColumnInfo it) => it.IsIgnore).Where((EntityColumnInfo it) => it.PropertyInfo.PropertyType.IsClass())
							.ToList())
						{
							if (Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns == null)
							{
								Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns = new List<KeyValuePair<string, string>>();
							}
							Context.SugarContext.QueryBuilder.SelectNewIgnoreColumns.Add(new KeyValuePair<string, string>(item2.PropertyInfo.Name, itemType.Name));
						}
					}
				}
				if (item is ConstantExpression)
				{
					ResolveConst(parameter, item, asName);
				}
				else if (item is MemberExpression && ((MemberExpression)item).Expression == null)
				{
					ResolveMember(parameter, item, asName);
				}
				else if (item is MemberExpression && ((MemberExpression)item).Expression.NodeType == ExpressionType.Constant)
				{
					ResolveMemberConst(parameter, item, asName);
				}
				else if (item is MemberExpression)
				{
					ResolveMemberOther(parameter, item, asName);
				}
				else if (item is UnaryExpression && ((UnaryExpression)item).Operand is MemberExpression)
				{
					ResolveUnaryExpMem(parameter, item, asName);
				}
				else if (item is UnaryExpression && ((UnaryExpression)item).Operand is ConstantExpression)
				{
					ResolveUnaryExpConst(parameter, item, asName);
				}
				else if (ExpressionTool.RemoveConvert(item) is BinaryExpression)
				{
					ResolveBinary(item, asName);
				}
				else if (item.Type.IsClass())
				{
					asName = ResolveClass(parameter, item, asName);
				}
				else if (item.Type == UtilConstants.BoolType && item is MethodCallExpression && IsNotCaseExpression(item))
				{
					ResloveBoolMethod(parameter, item, asName);
				}
				else if (item.NodeType == ExpressionType.Not && (item as UnaryExpression).Operand is MethodCallExpression && ((item as UnaryExpression).Operand as MethodCallExpression).Method.Name.IsIn("IsNullOrEmpty", "IsNullOrWhiteSpace"))
				{
					ResloveNot(parameter, item, asName);
				}
				else if (item is MethodCallExpression && (item as MethodCallExpression).Method.Name.IsIn("Count", "Any") && !item.ToString().StartsWith("Subqueryable"))
				{
					ResloveCountAny(parameter, item, asName);
				}
				else if (item is MethodCallExpression || item is UnaryExpression || item is ConditionalExpression || item.NodeType == ExpressionType.Coalesce)
				{
					ResloveOtherMUC(parameter, item, asName);
				}
				else
				{
					Check.ThrowNotSupportedException(item.GetType().Name);
				}
			}

			private Dictionary<string, string> GetMappingColumns(Expression currentExpression)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				if (currentExpression == null)
				{
					return dictionary;
				}
				List<Type> list = new List<Type>();
				int num = 0;
				if (currentExpression is NewExpression)
				{
					num = (currentExpression as NewExpression).Arguments.Count;
					foreach (Expression argument in (currentExpression as NewExpression).Arguments)
					{
						if (argument.Type.IsClass())
						{
							list.Add(argument.Type);
						}
					}
				}
				else if (currentExpression is MemberInitExpression)
				{
					num = (currentExpression as MemberInitExpression).Bindings.Count;
					foreach (MemberAssignment binding in (currentExpression as MemberInitExpression).Bindings)
					{
						if (binding.Expression.Type.IsClass())
						{
							list.Add(binding.Expression.Type);
						}
					}
				}
				if (list.Count == num && list.Count == list.Distinct().Count())
				{
					return dictionary;
				}
				string[] array = currentExpression.ToString().Split(',');
				for (int i = 0; i < array.Length; i++)
				{
					string[] source = array[i].Split('=').ToArray();
					string value = source.Last().Trim().Split('.')
						.First()
						.TrimEnd(')')
						.TrimEnd('}');
					string text = source.First().Trim();
					if (text.Contains("{"))
					{
						text = text.Split('{').Last().Trim();
					}
					if (text.Contains("("))
					{
						text = text.Split('(').Last().Trim();
					}
					if (!dictionary.ContainsKey(text))
					{
						dictionary.Add(text, value);
					}
				}
				return dictionary;
			}

			private static bool IsSubToList(Expression item)
			{
				if (ExpressionTool.GetMethodName(item).IsIn("ToList", "First"))
				{
					return IsSubquery(item);
