				return false;
			}

			private static bool IsSubquery(Expression item)
			{
				if (!(item is MethodCallExpression methodCallExpression))
				{
					return false;
				}
				if (methodCallExpression.Object == null)
				{
					return false;
				}
				return methodCallExpression.Object.Type.Name.StartsWith("Subquery");
			}

