			private bool IsNullValue(ExpressionParameter parameter, object value)
			{
				if (value == null && !parameter.ValueIsNull && parameter.BaseParameter != null && parameter.BaseParameter.OperatorValue.IsIn("=", "<>"))
				{
					return Context.ResolveType.IsIn(ResolveExpressType.WhereMultiple, ResolveExpressType.WhereSingle);
				}
				return false;
