			private static bool IsNotCaseExpression(Expression item)
			{
				if ((item as MethodCallExpression).Method.Name == "IIF")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "IsNull")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "End" && item.ToString().Contains("IF("))
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "AggregateMax")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "AggregateMin")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "AggregateSum")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "ToBool")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "ToBoolean")
				{
					return false;
				}
				if ((item as MethodCallExpression).Method.Name == "Select" && item.ToString().Contains("Subqueryable()"))
				{
					return false;
				}
				return true;
			}

			private static bool IsBoolValue(Expression item)
			{
				if (item.Type == UtilConstants.BoolType && item is MemberExpression && (item as MemberExpression).Expression != null && (item as MemberExpression).Expression.Type == typeof(bool?))
				{
					return (item as MemberExpression).Member.Name == "Value";
