			protected static bool IsConvert(Expression item)
			{
				if (item is UnaryExpression)
				{
					return item.NodeType == ExpressionType.Convert;
				}
				return false;
			}

			protected static bool IsNotMember(Expression item)
			{
				if (item is UnaryExpression && item.Type == UtilConstants.BoolType && (item as UnaryExpression).NodeType == ExpressionType.Not && (item as UnaryExpression).Operand is MemberExpression && ((item as UnaryExpression).Operand as MemberExpression).Expression != null)
				{
					return ((item as UnaryExpression).Operand as MemberExpression).Expression.NodeType == ExpressionType.Parameter;
				}
				return false;
			}

			protected static bool IsNotParameter(Expression item)
			{
				if (item is UnaryExpression && item.Type == UtilConstants.BoolType && (item as UnaryExpression).NodeType == ExpressionType.Not && (item as UnaryExpression).Operand is MemberExpression && ((item as UnaryExpression).Operand as MemberExpression).Expression != null)
				{
					return ((item as UnaryExpression).Operand as MemberExpression).Expression.NodeType == ExpressionType.MemberAccess;
				}
