		public class BinaryExpressionResolve : BaseResolve
		{
			public BinaryExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				ResolveExpressType resolveType = parameter.Context.ResolveType;
				if (resolveType == ResolveExpressType.FieldSingle || resolveType == ResolveExpressType.FieldMultiple)
				{
					string newExpressionValue = GetNewExpressionValue(base.Expression);
					base.Context.Result.Append(newExpressionValue);
				}
				else
				{
					Other(parameter);
				}
			}

			private void Other(ExpressionParameter parameter)
			{
				BinaryExpression binaryExpression = base.Expression as BinaryExpression;
				if (binaryExpression.NodeType == ExpressionType.ArrayIndex)
				{
					string text = AppendParameter(ExpressionTool.DynamicInvoke(binaryExpression));
					ExpressionParameter baseParameter = base.BaseParameter;
					if (baseParameter != null && baseParameter.IsLeft == true)
					{
						base.Context.Result.Append($" {base.BaseParameter.BaseParameter.OperatorValue} {text} ");
					}
					else
					{
						base.Context.Result.Append(" " + text + " ");
					}
					return;
				}
				string text2 = (parameter.OperatorValue = ExpressionTool.GetOperator(binaryExpression.NodeType));
				string text4 = text2;
				if (IsGroupSubquery(binaryExpression.Right, text4))
				{
					SubGroup(binaryExpression, text4);
				}
				else if (IsJoinString(binaryExpression, text4))
				{
					JoinString(parameter, binaryExpression);
				}
				else if (IsUpdateJson(parameter, binaryExpression, text4))
				{
					parameter.CommonTempData = "IsJson=true";
					DefaultBinary(parameter, binaryExpression, text4);
					parameter.CommonTempData = null;
				}
				else if (IsUpdateArray(parameter, binaryExpression, text4))
				{
					parameter.CommonTempData = "IsArray=true";
					DefaultBinary(parameter, binaryExpression, text4);
					parameter.CommonTempData = null;
				}
				else if (IsBinaryGroup(text4, binaryExpression))
				{
					ExpressionTool.IsComparisonOperator(binaryExpression);
					string newExpressionValue = GetNewExpressionValue(binaryExpression.Left);
					string newExpressionValue2 = GetNewExpressionValue(binaryExpression.Right);
					base.Context.Result.Append($"( {newExpressionValue} {text4} {newExpressionValue2} )");
				}
				else
				{
					DefaultBinary(parameter, binaryExpression, text4);
				}
			}

			private bool IsBinaryGroup(string operatorValue, BinaryExpression expression)
			{
				Expression expression2 = ExpressionTool.RemoveConvert(expression.Left);
				Expression expression3 = ExpressionTool.RemoveConvert(expression.Right);
				if (operatorValue != null && operatorValue.IsIn("AND", "OR") && expression2 is BinaryExpression && expression3 is BinaryExpression)
				{
					Expression expression4 = ExpressionTool.RemoveConvert((expression2 as BinaryExpression).Right);
					Expression expression5 = ExpressionTool.RemoveConvert((expression3 as BinaryExpression).Right);
					bool num = ExpressionTool.GetMethodName(expression4) == "Select" || expression4 is BinaryExpression;
					bool flag = ExpressionTool.GetMethodName(expression5) == "Select" || expression5 is BinaryExpression;
					bool flag2 = ExpressionTool.ContainsMethodName(expression2 as BinaryExpression, "Group");
					bool flag3 = ExpressionTool.ContainsMethodName(expression3 as BinaryExpression, "Group");
					if ((num & flag2) || (flag & flag3))
					{
						return true;
					}
				}
				return false;
			}

			private bool IsUpdateArray(ExpressionParameter parameter, BinaryExpression expression, string operatorValue)
			{
				if (parameter.Context.ResolveType == ResolveExpressType.WhereSingle && operatorValue == "=" && expression.Left is MemberExpression && expression.Left.Type.IsClass() && base.Context.SugarContext != null)
				{
					MemberExpression memberExpression = expression.Left as MemberExpression;
					if (memberExpression.Expression != null && base.Context.SugarContext.Context.EntityMaintenance.GetEntityInfo(memberExpression.Expression.Type).Columns.FirstOrDefault((EntityColumnInfo it) => it.IsArray && it.PropertyName == ExpressionTool.GetMemberName(expression.Left)) != null)
					{
						return true;
					}
				}
				return false;
			}

			private bool IsUpdateJson(ExpressionParameter parameter, BinaryExpression expression, string operatorValue)
			{
				if (parameter.Context.ResolveType == ResolveExpressType.WhereSingle && operatorValue == "=" && expression.Left is MemberExpression && expression.Left.Type.IsClass() && base.Context.SugarContext != null)
				{
					MemberExpression memberExpression = expression.Left as MemberExpression;
					if (memberExpression.Expression != null && base.Context.SugarContext.Context.EntityMaintenance.GetEntityInfo(memberExpression.Expression.Type).Columns.FirstOrDefault((EntityColumnInfo it) => it.IsJson && it.PropertyName == ExpressionTool.GetMemberName(expression.Left)) != null)
					{
						return true;
					}
				}
				return false;
			}

			private void JoinString(ExpressionParameter parameter, BinaryExpression expression)
			{
				string text = GetNewExpressionValue(expression.Left);
				string newExpressionValue = GetNewExpressionValue(expression.Right);
				if (text == null && base.BaseParameter?.BaseExpression == null && expression.Left is ParameterExpression)
				{
					text = base.Context.SqlParameterKeyWord + "MethodConst1";
				}
				string text2 = base.Context.DbMehtods.MergeString(text, newExpressionValue);
				if (base.Context.Result.Contains("{0}"))
				{
					base.Context.Result.Replace("{0}", " " + text2 + " ");
					base.Context.Result.Append(" 46450BDC-77B7-4025-B2A6-3F048CA85AD0" + parameter.BaseParameter.Index + " ");
				}
				else
				{
					base.Context.Result.Append(" " + text2 + " ");
				}
			}

			private void DefaultBinary(ExpressionParameter parameter, BinaryExpression expression, string operatorValue)
			{
				bool isEqual = expression.NodeType == ExpressionType.Equal;
				ExpressionTool.IsComparisonOperator(expression);
				base.ExactExpression = expression;
				Expression leftExpression = ExpressionTool.RemoveConvert(expression.Left);
				Expression rightExpression = ExpressionTool.RemoveConvert(expression.Right);
				if (leftExpression.Type == typeof(char))
				{
					leftExpression = expression.Left;
					rightExpression = expression.Right;
				}
				if (operatorValue.IsIn("AND", "OR") && leftExpression is BinaryExpression binaryExpression && binaryExpression?.Left is BinaryExpression binaryExpression2 && ExpressionTool.GetMethodName(binaryExpression2?.Right) == "Select" && ExpressionTool.ContainsMethodName(binaryExpression2, "GroupBy"))
				{
					string newExpressionValue = GetNewExpressionValue(binaryExpression2.Left);
					string newExpressionValue2 = GetNewExpressionValue(binaryExpression2.Right);
					string newExpressionValue3 = GetNewExpressionValue(binaryExpression.Right);
					string value = ExpressionTool.GetOperator(binaryExpression.NodeType);
					base.Context.Result.Append($" (({newExpressionValue + " IN " + newExpressionValue2}) {operatorValue} {GetNewExpressionValue(rightExpression)}) {value} {newExpressionValue3} ");
					return;
				}
				if (operatorValue == "=" && ExpressionTool.RemoveConvert(leftExpression) is ConstantExpression)
				{
					leftExpression = expression.Right;
					rightExpression = expression.Left;
				}
				if (RightIsHasValue(leftExpression, rightExpression, ExpressionTool.IsLogicOperator(expression)))
