				queryBuilder.Builder = InstanceFactory.GetSqlbuilder(context.CurrentConnectionConfig);
				queryBuilder.Builder.Context = queryBuilder.Context;
				queryBuilder.Builder.QueryBuilder = queryBuilder;
				queryBuilder.Context = context;
				ExpressionResult expressionValue = queryBuilder.GetExpressionValue(expression, ResolveExpressType.WhereMultiple);
				string name = (expression as LambdaExpression).Parameters[0].Name;
				string resultString = expressionValue.GetResultString();
				resultString = resultString.Replace(queryBuilder.Builder.GetTranslationColumnName(name) + ".", "");
				if (queryBuilder.Parameters != null && queryBuilder.Parameters.Count > 0)
				{
					foreach (SugarParameter parameter in queryBuilder.Parameters)
					{
						resultString = resultString.Replace(parameter.ParameterName, parameter.Value.ObjToString().ToSqlValue());
					}
				}
				return resultString;
			}

			private MapperExpressionInfo GetSelectInfo(Expression expression)
			{
				Expression expression2 = expression;
				if (expression2 is UnaryExpression)
				{
					expression2 = (expression2 as UnaryExpression).Operand;
				}
				Type type = (expression2 as MemberExpression).Expression.Type;
				context.InitMappingInfo(type);
				string name = (expression2 as MemberExpression).Member.Name;
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
				string dbColumnName = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == name).DbColumnName;
				return new MapperExpressionInfo
				{
					Type = type,
					FieldName = dbColumnName,
					EntityInfo = entityInfo
				};
