		public class MemberConstExpressionResolve : BaseResolve
		{
			public MemberConstExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				MemberExpression memberExpression = base.Expression as MemberExpression;
				bool? isLeft = parameter.IsLeft;
				object memberValue = ExpressionTool.GetMemberValue(memberExpression.Member, memberExpression);
				ExpressionParameter baseParameter = parameter.BaseParameter;
				bool isSetTempData = baseParameter.CommonTempData.HasValue() && baseParameter.CommonTempData.Equals(CommonTempDataType.Result);
				switch (parameter.Context.ResolveType)
				{
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.Update:
					memberValue = Select(parameter, memberValue);
					break;
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
					Where(parameter, isLeft, memberValue, baseParameter, isSetTempData);
					break;
				case ResolveExpressType.FieldSingle:
				case (ResolveExpressType)6:
				case ResolveExpressType.FieldMultiple:
				case ResolveExpressType.Join:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					break;
				}
			}

			private void Where(ExpressionParameter parameter, bool? isLeft, object value, ExpressionParameter baseParameter, bool isSetTempData)
			{
				if (parameter.OppsiteExpression != null)
				{
					Expression expression = ExpressionTool.RemoveConvert(parameter.OppsiteExpression);
					value = GetMemberValue(value, expression, out SugarParameter outConvertParameter);
					if (value?.GetType()?.FullName == "Microsoft.Extensions.Primitives.StringValues")
					{
						value = value.ToString();
					}
					if (outConvertParameter != null && !isSetTempData && expression is MemberExpression memberExpression)
					{
						outConvertParameter.ParameterName = "@" + memberExpression.Member.Name + base.Context.ParameterIndex;
						base.Context.ParameterIndex++;
						base.Context.Parameters.Add(outConvertParameter);
						AppendMember(parameter, isLeft, outConvertParameter.ParameterName);
						return;
					}
				}
				if (isSetTempData)
				{
					baseParameter.CommonTempData = value;
				}
				else
				{
					AppendValue(parameter, isLeft, value);
				}
			}

			private object Select(ExpressionParameter parameter, object value)
			{
				if (value != null && value.GetType().IsEnum())
				{
					ExpressionContext context = base.Context;
					value = ((context == null || context.SugarContext?.Context?.CurrentConnectionConfig?.MoreSettings?.TableEnumIsString != true) ? ((object)Convert.ToInt64(value)) : Convert.ToString(value));
				}
				parameter.BaseParameter.CommonTempData = value;
				return value;
			}
		}
		public class MemberExpressionResolve : BaseResolve
		{
			public ExpressionParameter Parameter { get; set; }

			public MemberExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				SettingParameters(parameter, out ExpressionParameter baseParameter, out MemberExpression expression, out bool? isLeft, out bool isSetTempData, out bool isValue, out bool isValueBool, out bool isLength, out bool isDateValue, out bool isHasValue, out bool isDateDate, out bool isMemberValue, out bool isSingle, out bool fieldIsBool, out bool isSelectField, out bool isField);
				baseParameter.ChildExpression = expression;
				ProcessNavigationMemberAndUpdateExpression(ref expression, ref isValue);
				if (isLength)
				{
					ResolveLength(parameter, isLeft, expression);
				}
				else if (IsDateDiff(expression))
				{
					ResolveDateDiff(parameter, isLeft, expression);
				}
				else if (expression.Member.Name == "DayOfWeek" && expression.Type == typeof(DayOfWeek))
				{
					ResolveDayOfWeek(parameter, isLeft, expression);
				}
				else if (isHasValue)
				{
					ResolveHasValue(parameter, expression);
				}
				else if (isDateValue)
				{
					ResolveDateValue(parameter, isLeft, expression);
				}
				else if (isValueBool)
				{
					ResolveValueBool(parameter, baseParameter, expression, isLeft, isSingle);
				}
				else if (isValue && expression.Expression != null && expression.Expression is MethodCallExpression)
				{
					ResolveCallValue(parameter, baseParameter, expression, isLeft, isSetTempData, isSingle);
				}
				else if (isValue & IsNavValue(expression))
				{
					expression = expression.Expression as MemberExpression;
					ResolveMemberValue(parameter, baseParameter, expression, isLeft, isSetTempData);
				}
				else if (isValue)
				{
					ResolveValue(parameter, baseParameter, expression, isLeft, isSetTempData, isSingle);
				}
				else if (expression.Expression != null && expression.Expression.Type == UtilConstants.DateType && expression != null && expression.Expression is MethodCallExpression)
				{
					ResolveDateDateByCall(parameter, isLeft, expression);
				}
				else if (isDateDate)
				{
					ResolveDateDate(parameter, isLeft, expression);
				}
				else if (IsConvertMemberName(expression))
				{
					ResolveConvertMemberName(parameter, expression, isLeft);
				}
				else if (isMemberValue)
				{
					ResolveMemberValue(parameter, baseParameter, expression, isLeft, isSetTempData);
				}
				else if (fieldIsBool && !isField && !isSelectField)
				{
					ResolvefieldIsBool(parameter, baseParameter, isLeft, isSetTempData, expression, isSingle);
				}
				else
				{
					ResolveDefault(parameter, baseParameter, expression, isLeft, isSetTempData, isSingle);
				}
			}

			private void ProcessNavigationMemberAndUpdateExpression(ref MemberExpression expression, ref bool isValue)
			{
				if (isValue && expression.Expression is MemberExpression { Expression: MemberExpression expression2 } memberExpression && ExpressionTool.IsNavMember(base.Context, expression2))
				{
					expression = memberExpression;
					isValue = false;
				}
			}

			private static bool IsNavValue(MemberExpression expression)
			{
				if (expression.Type == UtilConstants.DateType && expression.Expression is MemberExpression)
				{
					return (expression.Expression as MemberExpression)?.Expression is MemberExpression;
				}
				return false;
			}

			private void DefaultOneToOneN(ExpressionParameter parameter, ExpressionParameter baseParameter, bool? isLeft, bool isSetTempData, OneToOneNavgateExpressionN navN)
			{
				MapperSql memberSql = navN.GetMemberSql();
				SetNavigateResult();
				base.Context.SingleTableNameSubqueryShortName = navN.shorName;
				if (isSetTempData)
				{
					baseParameter.CommonTempData = memberSql;
				}
				else
				{
					AppendValue(parameter, isLeft, memberSql);
				}
			}

			private void DefaultOneToOne(ExpressionParameter parameter, ExpressionParameter baseParameter, bool? isLeft, bool isSetTempData, OneToOneNavgateExpression nav)
			{
				MapperSql sql = nav.GetSql();
				SetNavigateResult();
				base.Context.SingleTableNameSubqueryShortName = nav.ShorName;
				if (isSetTempData)
				{
					baseParameter.CommonTempData = sql;
				}
				else
				{
					AppendValue(parameter, isLeft, sql);
				}
			}

			private void ResolveDefault(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData, bool isSingle)
			{
				string empty = string.Empty;
				switch (parameter.Context.ResolveType)
				{
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.Update:
					empty = GetSingleName(parameter, expression, isLeft);
					if (isSetTempData)
					{
						baseParameter.CommonTempData = empty;
					}
					else
					{
						base.Context.Result.Append(empty);
					}
					break;
				case ResolveExpressType.SelectMultiple:
					empty = GetMultipleName(parameter, expression, isLeft);
					if (isSetTempData)
					{
						baseParameter.CommonTempData = empty;
					}
					else
					{
						base.Context.Result.Append(empty);
					}
					break;
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
					ResolveWhereLogic(parameter, baseParameter, expression, isLeft, isSetTempData, isSingle);
					break;
				case ResolveExpressType.FieldSingle:
					empty = GetSingleName(parameter, expression, isLeft);
					if (IsFieldIsCommonTemp(isSetTempData, parameter))
					{
						baseParameter.CommonTempData = empty;
					}
					else
					{
						base.Context.Result.Append(empty);
					}
					break;
				case ResolveExpressType.FieldMultiple:
					empty = GetMultipleName(parameter, expression, isLeft);
					if (IsFieldIsCommonTemp(isSetTempData, parameter))
					{
						baseParameter.CommonTempData = empty;
					}
					else
					{
						base.Context.Result.Append(empty);
					}
					break;
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					empty = GetName(parameter, expression, isLeft, parameter.Context.ResolveType == ResolveExpressType.ArraySingle);
					if (IsFieldIsCommonTemp(isSetTempData, parameter))
					{
						baseParameter.CommonTempData = empty;
					}
					else
					{
						base.Context.Result.Append(empty);
					}
					break;
				case (ResolveExpressType)6:
				case ResolveExpressType.Join:
					break;
				}
			}

			private bool IsFieldIsCommonTemp(bool isSetTempData, ExpressionParameter parameter)
			{
				if (parameter.BaseParameter == null)
				{
					return false;
				}
				string childExpression = parameter.BaseParameter.ChildExpression.ObjToString();
				string value = parameter.BaseParameter.CurrentExpression.ObjToString();
				IEnumerable<string> source = UtilConstants.DateTypeStringList.Select((string it) => childExpression + "." + it);
				if (isSetTempData)
				{
					return source.Contains(value);
				}
				return false;
			}

			private void ResolveBoolLogic(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData, bool isSingle)
			{
				string empty = string.Empty;
				if (isSetTempData)
				{
					if (ExpressionTool.IsConstExpression(expression))
					{
						baseParameter.CommonTempData = ExpressionTool.GetMemberValue(expression.Member, expression)?.ToString() + "=1 ";
						return;
					}
					empty = GetName(parameter, expression, null, isSingle);
					baseParameter.CommonTempData = empty + "=1 ";
				}
				else if (ExpressionTool.IsConstExpression(expression))
				{
					AppendValue(parameter, isLeft, ExpressionTool.GetMemberValue(expression.Member, expression)?.ToString() + "=1 ");
				}
				else
				{
					empty = GetName(parameter, expression, isLeft, isSingle);
					AppendMember(parameter, isLeft, empty + "=1 ");
				}
			}

			private void ResolveWhereLogic(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData, bool isSingle)
			{
				string empty = string.Empty;
				if (isSetTempData)
				{
					if (ExpressionTool.IsConstExpression(expression))
					{
						object memberValue = ExpressionTool.GetMemberValue(expression.Member, expression);
						baseParameter.CommonTempData = memberValue;
					}
					else
					{
						empty = GetName(parameter, expression, null, isSingle);
						baseParameter.CommonTempData = empty;
					}
				}
				else if (ExpressionTool.IsConstExpression(expression))
				{
					object memberValue2 = ExpressionTool.GetMemberValue(expression.Member, expression);
					AppendValue(parameter, isLeft, memberValue2);
				}
				else
				{
					empty = GetName(parameter, expression, isLeft, isSingle);
					AppendMember(parameter, isLeft, empty);
				}
			}

			private void ResolveMemberValue(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData)
			{
				OneToOneNavgateExpression nav = new OneToOneNavgateExpression(base.Context?.SugarContext?.Context, this);
				nav.ExpContext = base.Context;
				OneToOneNavgateExpressionN oneToOneNavgateExpressionN = new OneToOneNavgateExpressionN(base.Context?.SugarContext?.Context);
				if (nav.IsNavgate(expression))
				{
					if (base.Context?.SugarContext?.QueryBuilder?.JoinQueryInfos != null)
					{
						string p = expression.Expression.ObjToString();
						QueryBuilder querybuilder = base.Context?.SugarContext?.QueryBuilder;
						JoinQueryInfo joinQueryInfo = querybuilder.JoinQueryInfos.FirstOrDefault((JoinQueryInfo it) => querybuilder.TableShortName + "." + it.ShortName.Replace("pnv_", "") == p);
						if (joinQueryInfo != null)
						{
							EntityColumnInfo entityColumnInfo = nav.ProPertyEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == nav.MemberName);
							MapperSql mapperSql = new MapperSql
							{
								Sql = querybuilder.Builder.GetTranslationColumnName(joinQueryInfo.ShortName) + "." + querybuilder.Builder.GetTranslationColumnName(entityColumnInfo.DbColumnName)
							};
							if (isSetTempData)
							{
								baseParameter.CommonTempData = mapperSql;
							}
							else
							{
								AppendValue(parameter, isLeft, mapperSql);
							}
						}
						else
						{
							DefaultOneToOne(parameter, baseParameter, isLeft, isSetTempData, nav);
						}
					}
					else
					{
						DefaultOneToOne(parameter, baseParameter, isLeft, isSetTempData, nav);
					}
				}
				else if (oneToOneNavgateExpressionN.IsNavgate(expression) && ExpressionTool.GetParameters(expression).Any())
				{
					DefaultOneToOneN(parameter, baseParameter, isLeft, isSetTempData, oneToOneNavgateExpressionN);
				}
				else
				{
					ResolveMemberValue(parameter, baseParameter, isLeft, isSetTempData, expression);
				}
			}

			private void ResolveConvertMemberName(ExpressionParameter parameter, MemberExpression expression, bool? isLeft)
			{
				ParameterExpression parameterExpression = (expression.Expression as UnaryExpression).Operand as ParameterExpression;
				string memberName = ExpressionTool.GetMemberName(expression);
				if (base.Context.IsSingle)
				{
					AppendMember(parameter, isLeft, base.Context.GetTranslationColumnName(memberName));
				}
				else
				{
					AppendMember(parameter, isLeft, base.Context.GetTranslationColumnName(parameterExpression.Name + "." + memberName));
				}
			}

			private void ResolveDayOfWeek(ExpressionParameter parameter, bool? isLeft, MemberExpression expression)
			{
				Expression expression2 = expression.Expression;
				string newExpressionValue = GetNewExpressionValue(expression2);
				string appendValue = base.Context.DbMehtods.DateValue(new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs>
					{
						new MethodCallExpressionArgs
						{
							MemberName = newExpressionValue,
							MemberValue = newExpressionValue
						},
						new MethodCallExpressionArgs
						{
							MemberName = DateType.Weekday,
							MemberValue = DateType.Weekday
						}
					}
				});
				AppendMember(parameter, isLeft, (object)appendValue);
			}

			private void ResolveDateDiff(ExpressionParameter parameter, bool? isLeft, MemberExpression expression)
			{
				BinaryExpression obj = expression.Expression as BinaryExpression;
				Expression right = obj.Right;
				Expression left = obj.Left;
				DateType dateType = DateType.Day;
				string newExpressionValue = GetNewExpressionValue(right);
				string newExpressionValue2 = GetNewExpressionValue(left);
				foreach (KeyValuePair<string, DateType> item in UtilMethods.EnumToDictionary<DateType>())
				{
					if (expression.Member.Name.ToLower().Contains(item.Key.ToLower()))
					{
						dateType = item.Value;
						break;
					}
				}
				string appendValue = base.Context.DbMehtods.DateDiff(new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs>
					{
						new MethodCallExpressionArgs
						{
							MemberName = dateType,
							MemberValue = dateType
						},
						new MethodCallExpressionArgs
						{
							MemberName = newExpressionValue,
							MemberValue = newExpressionValue
						},
						new MethodCallExpressionArgs
						{
							MemberName = newExpressionValue2,
							MemberValue = newExpressionValue2
						}
					}
				});
				AppendMember(parameter, isLeft, (object)appendValue);
			}

			private void ResolveDateDateByCall(ExpressionParameter parameter, bool? isLeft, MemberExpression expression)
			{
				string newExpressionValue = GetNewExpressionValue(expression.Expression);
				if (expression.Member.Name == "Date")
				{
					AppendMember(parameter, isLeft, GetToDateShort(newExpressionValue));
					return;
				}
				foreach (int value in Enum.GetValues(typeof(DateType)))
				{
					string name = Enum.GetName(typeof(DateType), value);
					if (expression.Member.Name == name)
					{
						AppendMember(parameter, isLeft, base.Context.DbMehtods.MergeString(GetDateValue(newExpressionValue, (DateType)value)));
					}
				}
			}

			private void ResolveCallValue(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData, bool isSingle)
			{
				try
				{
					baseParameter.ChildExpression = expression;
					_ = string.Empty;
					if (isSetTempData)
					{
						object commonTempData = ExpressionTool.DynamicInvoke(expression);
						baseParameter.CommonTempData = commonTempData;
					}
					else
					{
						object value = ExpressionTool.DynamicInvoke(expression);
						AppendValue(parameter, isLeft, value);
					}
				}
				catch
				{
					Check.Exception(true, "Not Support {0}", expression.ToString());
				}
			}

			private MemberExpression ResolveValue(ExpressionParameter parameter, ExpressionParameter baseParameter, MemberExpression expression, bool? isLeft, bool isSetTempData, bool isSingle)
			{
				expression = expression.Expression as MemberExpression;
				baseParameter.ChildExpression = expression;
				if (UtilMethods.GetUnderType(expression.Type) == UtilConstants.BoolType && parameter.BaseExpression != null && ExpressionTool.IsLogicOperator(parameter.BaseExpression))
				{
