						ConvertParameterTypeByType(expression2, sugarParameter3);
						base.Context.Parameters.Add(sugarParameter3);
						base.Context.ParameterIndex++;
					}
					else if (expression2 is MemberExpression)
					{
						if (base.Context.Result.IsLockCurrentParameter)
						{
							continue;
						}
						base.Context.Result.CurrentParameter = parameter;
						base.Context.Result.IsLockCurrentParameter = true;
						parameter.IsAppendTempDate();
						base.Expression = expression2;
						Start();
						parameter.IsAppendResult();
						parameter.Context.Result.Append(base.Context.GetEqString(memberName, parameter.CommonTempData.ObjToString().Replace(",", "{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}")));
						if (base.Context.Parameters != null)
						{
							SugarParameter sugarParameter4 = base.Context.Parameters?.FirstOrDefault((SugarParameter it) => it.Value == null && it.ParameterName == parameter.CommonTempData.ObjToString());
							if (sugarParameter4 != null)
							{
								ConvertParameterTypeByType(expression2, sugarParameter4);
							}
						}
						base.Context.Result.CurrentParameter = null;
					}
					else if (expression2 is BinaryExpression && ExpressionTool.NoParameterOrSqlfunc(expression2))
					{
						object paramterValue3 = System.Linq.Expressions.Expression.Lambda(expression2).Compile().DynamicInvoke();
						parameter.Context.Result.Append(base.Context.GetEqString(memberName, AppendParameter(paramterValue3)));
					}
					else if (expression2 is BinaryExpression)
					{
						string text2 = GetNewExpressionValue(expression2);
						if (text2.HasValue())
						{
							text2 = text2.Replace(",", "{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}");
						}
						if (expression2.Type == UtilConstants.BoolType)
						{
							string text3 = AppendParameter(true);
							string text4 = AppendParameter(false);
							text2 = new DefaultDbMethod().IIF(new MethodCallExpressionModel
							{
								Args = new List<MethodCallExpressionArgs>
								{
									new MethodCallExpressionArgs
									{
										MemberValue = text2,
										MemberName = text2
									},
									new MethodCallExpressionArgs
									{
										MemberValue = text3,
										MemberName = text3
									},
									new MethodCallExpressionArgs
									{
										MemberValue = text4,
										MemberName = text4
									}
								}
							});
						}
						base.Context.Result.Append(base.Context.GetEqString(memberName, text2));
					}
					else if (expression2 is MemberInitExpression)
					{
						try
						{
							object paramterValue4 = ExpressionTool.DynamicInvoke(expression2);
							string fieldValue4 = AppendParameter(paramterValue4);
							parameter.Context.Result.Append(base.Context.GetEqString(memberName, fieldValue4));
						}
						catch (Exception ex)
						{
							throw new NotSupportedException("Not Supported " + expression2.ToString() + " " + ex.Message);
						}
					}
					else if (expression2 is NewExpression)
					{
						try
						{
							object paramterValue5 = ExpressionTool.DynamicInvoke(expression2);
							string fieldValue5 = AppendParameter(paramterValue5);
							parameter.Context.Result.Append(base.Context.GetEqString(memberName, fieldValue5));
						}
						catch (Exception ex2)
						{
							throw new NotSupportedException("Not Supported " + expression2.ToString() + " " + ex2.Message);
						}
					}
					else if (expression2 is ConditionalExpression)
					{
						string newExpressionValue = GetNewExpressionValue(expression2);
						base.Context.Result.Append(base.Context.GetEqString(memberName, newExpressionValue));
					}
				}
			}

			private static void ConvertParameterTypeByType(Expression item, SugarParameter addItem)
			{
				Type underType = UtilMethods.GetUnderType(item.Type);
				if (addItem.Value == null && underType == UtilConstants.DateType)
				{
					addItem.DbType = System.Data.DbType.Date;
				}
				if (addItem.Value == null && underType.IsIn(UtilConstants.ULongType, UtilConstants.UIntType, UtilConstants.FloatType, UtilConstants.IntType, UtilConstants.LongType, UtilConstants.DecType, UtilConstants.DobType))
				{
					addItem.DbType = System.Data.DbType.Int32;
				}
				if (addItem.Value == null && underType == UtilConstants.BoolType)
				{
					addItem.DbType = System.Data.DbType.Boolean;
				}
			}

			private static bool IsConst(Expression item)
			{
				if (!(item is UnaryExpression) && item.NodeType != ExpressionType.Constant)
				{
					if (item is MemberExpression)
					{
						return ((MemberExpression)item).Expression.NodeType == ExpressionType.Constant;
					}
					return false;
				}
				return true;
			}

			private static bool IsConstNew(Expression item)
			{
				if (item != null && !ExpressionTool.GetParameters(item).Any())
				{
					return true;
				}
				if (!(item is UnaryExpression) && item.NodeType != ExpressionType.Constant)
				{
					if (item is MemberExpression)
					{
						return ((MemberExpression)item).Expression.NodeType == ExpressionType.Constant;
					}
					return false;
				}
				return true;
			}

			private static bool IsMethod(Expression item)
			{
				if (!(item is MethodCallExpression))
				{
					if (item is UnaryExpression)
					{
						return (item as UnaryExpression).Operand is MethodCallExpression;
					}
					return false;
				}
				return true;
			}

			private void MethodCall(ExpressionParameter parameter, string memberName, Expression item)
			{
				if (IsSubMethod(item as MethodCallExpression))
				{
					UtilMethods.GetOldValue(parameter.CommonTempData, delegate
					{
						parameter.CommonTempData = CommonTempDataType.Result;
						base.Expression = item;
						Start();
						string text2 = base.Context.GetEqString(memberName, parameter.CommonTempData.ObjToString());
						bool flag = text2.Contains(" JOIN ") && text2.Contains(" ON ");
						if (text2.Contains(","))
						{
							text2 = text2.Replace(",", "{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}");
						}
						if (ResolveExpressType.Update == base.Context.ResolveType)
						{
							string translationTableName = base.Context.GetTranslationTableName(parameter.CurrentExpression.Type.Name);
							if (!translationTableName.Contains("."))
							{
								if (flag)
								{
									string name = (base.BaseParameter.BaseParameter.CurrentExpression as LambdaExpression).Parameters[0].Name;
									text2 = text2.Replace(base.Context.GetTranslationColumnName(name), translationTableName);
								}
								else
								{
									string text3 = (base.BaseParameter?.BaseParameter?.CurrentExpression as LambdaExpression)?.Parameters[0].Name;
									text2 = text2.Replace(base.Context.SqlTranslationLeft + text3 + base.Context.SqlTranslationRight + ".", translationTableName + ".");
									text2 = text2.Replace(base.Context.SqlTranslationLeft + text3.ToUpper() + base.Context.SqlTranslationRight + ".", translationTableName + ".");
									text2 = text2.Replace(base.Context.SqlTranslationLeft + text3.ToLower() + base.Context.SqlTranslationRight + ".", translationTableName + ".");
								}
							}
						}
						parameter.Context.Result.Append(text2);
					});
					return;
				}
				base.Expression = item;
				Start();
				string text = parameter.CommonTempData.ObjToString().Replace(",", "{112A689B-17A1-4A06-9D27-A39EAB8BC3D5}");
				parameter.Context.Result.Append(base.Context.GetEqString(memberName, text));
				if (text == "sysdate")
				{
					ExpressionContext context = base.Context;
					if (context != null && context.SugarContext?.Context?.CurrentConnectionConfig?.MoreSettings?.IsAutoToUpper == false)
					{
						parameter.Context.Result.Replace(" = \"sysdate\" ", " = sysdate ");
					}
				}
			}

			private void Select(MemberInitExpression expression, ExpressionParameter parameter, bool isSingle)
			{
				bool flag = false;
				foreach (MemberBinding binding in expression.Bindings)
				{
					if (binding.BindingType != MemberBindingType.Assignment)
					{
						throw new NotSupportedException();
					}
					MemberAssignment memberAssignment = (MemberAssignment)binding;
					string memberName = memberAssignment.Member.Name;
					ExpressionContext context = base.Context;
					if (context != null && context.SugarContext?.QueryBuilder?.AppendNavInfo?.MappingNavProperties?.ContainsKey(memberName) == true)
					{
						continue;
					}
					Expression expression2 = ExpressionTool.RemoveConvert(memberAssignment.Expression);
					if (expression2.Type.IsClass() && expression2 is MemberExpression && (expression2 as MemberExpression).Expression is ParameterExpression)
					{
						Type type = ((expression2 as MemberExpression).Expression as ParameterExpression).Type;
						if (base.Context.SugarContext != null)
						{
							EntityColumnInfo entityColumnInfo = base.Context.SugarContext.Context.EntityMaintenance.GetEntityInfo(type).Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == memberName);
							if (entityColumnInfo != null && entityColumnInfo.Navigat != null)
							{
								break;
							}
						}
					}
					if (IsNullable(expression2) && expression2 is UnaryExpression)
					{
						Type memberInfoType = ExpressionTool.GetMemberInfoType(memberAssignment.Member);
						if (IsNullable(memberInfoType) && UtilMethods.GetUnderType(memberInfoType) == UtilMethods.GetUnderType(expression2.Type))
						{
							expression2 = (expression2 as UnaryExpression).Operand;
						}
					}
					if (expression2 is ParameterExpression)
					{
						flag = true;
					}
					ResolveNewExpressions(parameter, expression2, memberName);
				}
				if (flag)
				{
					QueryBuilder queryBuilder = base.Context?.SugarContext?.QueryBuilder;
					if (queryBuilder != null)
					{
						queryBuilder.IsAnyParameterExpression = true;
					}
				}
			}

			private static bool IsNullable(Type memtype)
			{
				return memtype.Name == "Nullable`1";
			}

			private static bool IsNullable(Expression item)
			{
				return item.Type.Name == "Nullable`1";
			}

			private bool IsExtMethod(string methodName)
			{
				if (base.Context.SqlFuncServices == null)
				{
					return false;
				}
				return base.Context.SqlFuncServices.Select((SqlFuncExternal it) => it.UniqueMethodName).Contains(methodName);
			}

			private bool CheckMethod(MethodCallExpression expression)
			{
				if (IsExtMethod(expression.Method.Name))
				{
					return true;
				}
				if (expression.Method.ReflectedType().FullName != "Snet.DB.sugar.SqlFunc")
				{
					return false;
				}
				return true;
			}
		}
		public class MemberNewExpressionResolve : BaseResolve
		{
			public MemberNewExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				MemberExpression expression = base.Expression as MemberExpression;
				_ = parameter.IsLeft;
				ExpressionTool.DynamicInvoke(expression);
			}
		}
		public class MemberNoExpressionResolve : BaseResolve
		{
			public MemberNoExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				MemberExpression obj = base.Expression as MemberExpression;
				bool? isLeft = parameter.IsLeft;
				bool isField = obj.Member is FieldInfo;
				bool isProperty = obj.Member is PropertyInfo;
				ExpressionParameter baseParameter = parameter.BaseParameter;
				bool isSetTempData = baseParameter.CommonTempData.HasValue() && baseParameter.CommonTempData.Equals(CommonTempDataType.Result);
				object value = GetValue(obj, isField, isProperty);
				switch (base.Context.ResolveType)
				{
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.Update:
					Update(parameter, isLeft, baseParameter, isSetTempData, value);
					break;
				case ResolveExpressType.FieldSingle:
				case (ResolveExpressType)6:
				case ResolveExpressType.FieldMultiple:
				case ResolveExpressType.Join:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					break;
				}
			}

			private void Update(ExpressionParameter parameter, bool? isLeft, ExpressionParameter baseParameter, bool isSetTempData, object value)
			{
				if (isSetTempData)
				{
					baseParameter.CommonTempData = value;
				}
				else
				{
					AppendValue(parameter, isLeft, value);
				}
			}

			private static object GetValue(MemberExpression expression, bool isField, bool isProperty)
			{
				object result = null;
				if (isField)
				{
					result = ExpressionTool.GetFiledValue(expression);
				}
				else if (isProperty)
				{
					result = ExpressionTool.GetPropertyValue(expression);
				}
				return result;
			}
		}
		/// <summary>
		/// MethodCall base DateFomat
		/// </summary>
		///  <summary>
		/// MethodCall Helper
		///  </summary>
		public class MethodCallExpressionResolve : BaseResolve
		{
			private int contextIndex;

			private Type TempParseType;

			public MethodCallExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				contextIndex = base.Context.Index;
				if (!(base.Expression is MethodCallExpression methodCallExpression))
				{
					return;
				}
				bool? isLeft = parameter.IsLeft;
				string text = methodCallExpression.Method.Name;
				bool flag = IsValidNativeMethod(methodCallExpression, text);
				List<MethodCallExpressionArgs> list = null;
				if (BaseResolve.MethodTimeMapping.ContainsKey(text))
				{
					list = new List<MethodCallExpressionArgs>();
					DateType dateType = BaseResolve.MethodTimeMapping[text];
					string text2 = base.Context.SqlParameterKeyWord + "Const" + base.Context.ParameterIndex;
					list.Add(new MethodCallExpressionArgs
					{
						IsMember = false,
						MemberName = text2,
						MemberValue = dateType
					});
					base.Context.Parameters.Add(new SugarParameter(text2, dateType.ToString()));
					base.Context.ParameterIndex++;
					text = "DateAdd";
					flag = true;
				}
				else
				{
					switch (text)
					{
					case "get_Item":
					{
						string text3 = base.Context.SqlParameterKeyWord + "Const" + base.Context.ParameterIndex;
						base.Context.Parameters.Add(new SugarParameter(text3, ExpressionTool.DynamicInvoke(methodCallExpression)));
						base.Context.Result.Append($" {text3} ");
						base.Context.ParameterIndex++;
						return;
					}
					case "NewGuid":
						base.Context.Result.Append(base.Context.DbMehtods.NewUid(null));
						return;
					case "GetConfigValue":
						GetConfigValue(methodCallExpression, parameter);
						return;
					}
					if (IsSubMethod(methodCallExpression, text))
					{
						string sql = new SubResolve(methodCallExpression, base.Context, parameter.OppsiteExpression).GetSql();
						if (base.Context.ResolveType.IsIn(ResolveExpressType.SelectMultiple, ResolveExpressType.SelectSingle) || (parameter.BaseParameter != null && parameter.BaseParameter.CommonTempData != null && parameter.BaseParameter.CommonTempData.Equals(CommonTempDataType.Result)))
						{
							parameter.BaseParameter.CommonTempData = sql;
						}
						else
						{
							AppendValue(parameter, isLeft, sql);
						}
						return;
					}
					if (IsIfElse(methodCallExpression, text))
					{
						string text4 = new CaseWhenResolve(methodCallExpression, base.Context, parameter.OppsiteExpression).GetSql();
						if ((contextIndex == 2 && parameter.BaseExpression == null) || (parameter.BaseExpression != null && ExpressionTool.IsLogicOperator(parameter.BaseExpression)))
						{
							text4 += "=1 ";
						}
						if (base.Context.ResolveType.IsIn(ResolveExpressType.SelectMultiple, ResolveExpressType.SelectSingle, ResolveExpressType.Update))
						{
							parameter.BaseParameter.CommonTempData = text4;
						}
						else
						{
							AppendValue(parameter, isLeft, text4);
						}
						return;
					}
				}
				if (IsContainsArray(methodCallExpression, text, flag))
				{
					text = "ContainsArray";
					flag = true;
				}
				if (flag)
				{
					NativeExtensionMethod(parameter, methodCallExpression, isLeft, BaseResolve.MethodMapping[text], list);
				}
				else
				{
					SqlFuncMethod(parameter, methodCallExpression, isLeft);
				}
			}

			private void NativeExtensionMethod(ExpressionParameter parameter, MethodCallExpression express, bool? isLeft, string name, List<MethodCallExpressionArgs> appendArgs = null)
			{
				_ = express.Method;
				List<Expression> list = express.Arguments.Cast<Expression>().ToList();
				MethodCallExpressionModel methodCallExpressionModel = new MethodCallExpressionModel();
				methodCallExpressionModel.Name = name;
				methodCallExpressionModel.Args = new List<MethodCallExpressionArgs>();
				switch (base.Context.ResolveType)
				{
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
					if (express.Object != null)
					{
						list.Insert(0, express.Object);
					}
					Where(parameter, isLeft, name, list, methodCallExpressionModel, appendArgs);
					break;
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.Update:
					if (express.Object != null)
					{
						list.Insert(0, express.Object);
					}
					Select(parameter, isLeft, name, list, methodCallExpressionModel, appendArgs);
					break;
				case ResolveExpressType.FieldSingle:
				case ResolveExpressType.FieldMultiple:
					if (express.Method.Name == "ToString" && express.Object != null && express.Object?.Type == UtilConstants.DateType)
					{
						string text = ((list[0] as ConstantExpression)?.Value)?.ToString() ?? "";
						if (text == "" && list[0] is MemberExpression)
						{
							text = ExpressionTool.GetExpressionValue(list[0])?.ToString() ?? "";
						}
						string newExpressionValue = GetNewExpressionValue(express.Object);
						string text2 = base.Context.DbMehtods.GetDateString(newExpressionValue, text);
						if (IsSqlServerModel())
						{
							text2 = $"FORMAT({newExpressionValue},'{text}','en-US')";
						}
						if (text2 == null)
						{
							string value = GeDateFormat(text, newExpressionValue);
							AppendValue(parameter, isLeft, value);
						}
						else
						{
							AppendValue(parameter, isLeft, text2);
						}
					}
					else
					{
						string newExpressionValue2 = GetNewExpressionValue(express, (!base.Context.IsJoin) ? ResolveExpressType.WhereSingle : ResolveExpressType.WhereMultiple);
						AppendValue(parameter, isLeft, newExpressionValue2);
					}
					break;
				case (ResolveExpressType)6:
				case ResolveExpressType.Join:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					break;
				}
			}

			protected void SqlFuncMethod(ExpressionParameter parameter, MethodCallExpression express, bool? isLeft)
			{
				if (!CheckMethod(express))
				{
					CusMethod(parameter, express, isLeft);
					return;
				}
				string text = express.Method.Name;
				if (text == "Any" && ExpressionTool.IsVariable(express.Arguments[0]))
				{
					text = "ListAny";
				}
				else if (text == "All" && ExpressionTool.IsVariable(express.Arguments[0]))
				{
					text = "ListAll";
				}
				else if (text == "IndexOf")
				{
					text = "CharIndexNew";
				}
				List<Expression> list = express.Arguments.Cast<Expression>().ToList();
				MethodCallExpressionModel methodCallExpressionModel = new MethodCallExpressionModel();
				methodCallExpressionModel.Args = new List<MethodCallExpressionArgs>();
				switch (base.Context.ResolveType)
				{
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
					Check.Exception(text == "GetSelfAndAutoFill", "SqlFunc.GetSelfAndAutoFill can only be used in Select.");
					if (text == "CharIndexNew" && list.Count == 1)
					{
						list.Insert(0, express.Object);
					}
					Where(parameter, isLeft, text, list, methodCallExpressionModel);
					break;
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.Update:
					Select(parameter, isLeft, text, list, methodCallExpressionModel);
					break;
				case ResolveExpressType.FieldSingle:
				case ResolveExpressType.FieldMultiple:
					Field(parameter, isLeft, text, list, methodCallExpressionModel);
					break;
				case (ResolveExpressType)6:
				case ResolveExpressType.Join:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					break;
				}
			}

			protected void Field(ExpressionParameter parameter, bool? isLeft, string name, IEnumerable<Expression> args, MethodCallExpressionModel model, List<MethodCallExpressionArgs> appendArgs = null)
			{
				if (base.Context.ResolveType == ResolveExpressType.FieldSingle)
				{
					base.Context.ResolveType = ResolveExpressType.WhereSingle;
				}
				else
				{
					base.Context.ResolveType = ResolveExpressType.WhereMultiple;
				}
				Where(parameter, isLeft, name, args, model);
			}

			protected void Select(ExpressionParameter parameter, bool? isLeft, string name, IEnumerable<Expression> args, MethodCallExpressionModel model, List<MethodCallExpressionArgs> appendArgs = null)
			{
				if (name.IsIn("GetSelfAndAutoFill", "SelectAll"))
				{
					string text = (args.First() as MemberExpression)?.Expression?.ToString();
					if (text == null && args.First() is ParameterExpression)
					{
						text = (args.First() as ParameterExpression).Type.GetProperties().First().Name;
					}
					MethodCallExpressionArgs methodCallExpressionArgs = new MethodCallExpressionArgs
					{
						MemberValue = text,
						IsMember = true,
						MemberName = text
					};
					model.Args.Add(methodCallExpressionArgs);
					if (args.Count() == 2)
					{
						methodCallExpressionArgs.MemberName = args.Last().ToString().Replace("\"", "");
						methodCallExpressionArgs.MemberValue = ".";
					}
				}
				else
				{
					foreach (Expression arg in args)
					{
						if (name == "IIF" && arg == args.First() && arg is MemberExpression)
						{
							Expression value = System.Linq.Expressions.Expression.Constant(true);
							Expression item = ExpressionBuilderHelper.CreateExpression(arg, value, ExpressionType.Equal);
							MemberExpression memberExpression = arg as MemberExpression;
							if (memberExpression.Member.Name == "HasValue")
							{
								item = ExpressionBuilderHelper.CreateExpression(memberExpression.Expression, System.Linq.Expressions.Expression.Constant(null), ExpressionType.NotEqual);
							}
							AppendItem(parameter, name, new List<Expression> { item }, model, item);
						}
						else
						{
							AppendItem(parameter, name, args, model, arg);
						}
					}
					if (appendArgs != null)
					{
						model.Args.AddRange(appendArgs);
					}
				}
				if (parameter.BaseParameter.BaseParameter.BaseParameter == null)
				{
					base.Context.Result.Append(GetMethodValue(name, model));
				}
				else
				{
					parameter.BaseParameter.CommonTempData = GetMethodValue(name, model);
				}
			}

			protected void Where(ExpressionParameter parameter, bool? isLeft, string name, IEnumerable<Expression> args, MethodCallExpressionModel model, List<MethodCallExpressionArgs> appendArgs = null)
			{
				foreach (Expression arg in args)
				{
					Expression item = arg;
					if (name == "IIF" && arg is UnaryExpression)
					{
						item = ExpressionTool.RemoveConvert(item);
					}
					else if (arg is UnaryExpression)
					{
						item = (arg as UnaryExpression).Operand;
					}
					else if (arg is MethodCallExpression methodCallExpression && methodCallExpression.Method.Name == "op_Implicit")
					{
						item = methodCallExpression.Arguments[0];
					}
					AppendItem(parameter, name, args, model, item);
				}
				if (appendArgs != null)
				{
					model.Args.AddRange(appendArgs);
				}
				object obj = GetMethodValue(name, model);
				if (parameter.BaseExpression is BinaryExpression && parameter.OppsiteExpression.Type == UtilConstants.BoolType && name == "HasValue" && !(parameter.OppsiteExpression is BinaryExpression) && (!(parameter.OppsiteExpression is MethodCallExpression) || !(parameter.OppsiteExpression.Type == UtilConstants.BoolType)))
				{
					obj = packIfElse(obj);
				}
				if (parameter.OppsiteExpression != null && name == "IsNullOrEmpty" && parameter.OppsiteExpression.Type == UtilConstants.BoolType && parameter.OppsiteExpression is ConstantExpression)
				{
					obj = packIfElse(obj);
				}
				bool flag = contextIndex == 2;
				if (flag && parameter.BaseExpression == null && base.Context.ResolveType.IsIn(ResolveExpressType.WhereMultiple, ResolveExpressType.WhereSingle) && parameter.CurrentExpression is MethodCallExpression && (parameter.CurrentExpression as MethodCallExpression).Method.Name.IsIn("ToBool", "ToBoolean"))
				{
					obj = obj?.ToString() + "=1 ";
				}
