				};
				MethodCallExpressionArgs item2 = new MethodCallExpressionArgs
				{
					IsMember = true,
					MemberName = value
				};
				MethodCallExpressionModel methodCallExpressionModel = new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs> { item2, item }
				};
				string text = "^";
				string text2 = "$";
				formatString = formatString.Replace("yyyy", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				formatString = formatString.Replace("yy", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				methodCallExpressionModel.Args.Last().MemberValue = DateType.Month;
				formatString = (IsMySql() ? formatString.Replace("MM", text + UtilMethods.ConvertStringToNumbers("LPAD(" + GetMethodValue("DateValue", methodCallExpressionModel).ObjToString() + ",2,0)") + text2) : (IsSqlite() ? formatString.Replace("MM", text + UtilMethods.ConvertStringToNumbers("SUBSTR('00' ||" + GetMethodValue("DateValue", methodCallExpressionModel).ObjToString() + ", -2, 2)") + text2) : ((!IsOracle()) ? formatString.Replace("MM", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2) : formatString.Replace("MM", text + UtilMethods.ConvertStringToNumbers("lpad(cast(" + GetMethodValue("DateValue", methodCallExpressionModel).ObjToString() + " as varchar(20)),2,'0')") + text2))));
				formatString = formatString.Replace("M", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				methodCallExpressionModel.Args.Last().MemberValue = DateType.Day;
				if (IsSqlServer())
				{
					formatString = formatString.Replace("dd", text + UtilMethods.ConvertStringToNumbers(string.Format("CASE  WHEN  LEN({0})=1  THEN '0'+ {0}   else  {0}  end", GetMethodValue("DateValue", methodCallExpressionModel))) + text2);
				}
				formatString = formatString.Replace("dd", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				formatString = formatString.Replace("d", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				methodCallExpressionModel.Args.Last().MemberValue = DateType.Hour;
				formatString = Regex.Replace(formatString, "hh", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2, RegexOptions.IgnoreCase);
				formatString = Regex.Replace(formatString, "h", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2, RegexOptions.IgnoreCase);
				methodCallExpressionModel.Args.Last().MemberValue = DateType.Minute;
				formatString = formatString.Replace("mm", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				formatString = formatString.Replace("m", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				methodCallExpressionModel.Args.Last().MemberValue = DateType.Second;
				formatString = formatString.Replace("ss", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				formatString = formatString.Replace("s", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				if (!IsSqlite())
				{
					methodCallExpressionModel.Args.Last().MemberValue = DateType.Millisecond;
					formatString = formatString.Replace("ms", text + UtilMethods.ConvertStringToNumbers(GetMethodValue("DateValue", methodCallExpressionModel).ObjToString()) + text2);
				}
				foreach (Match item3 in Regex.Matches(formatString, "\\^\\d+\\$").Cast<Match>().ToList())
				{
					formatString = formatString.Replace(item3.Value, "$@" + UtilMethods.ConvertNumbersToString(item3.Value.TrimStart('^').TrimEnd('$')) + "$");
				}
				string[] array = formatString.TrimStart('$').TrimEnd('$').Split('$');
				MethodCallExpressionModel methodCallExpressionModel2 = new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs>()
				};
				string[] array2 = array;
				foreach (string text3 in array2)
				{
					if (text3 != "" && text3.Substring(0, 1) == "@")
					{
						methodCallExpressionModel2.Args.Add(new MethodCallExpressionArgs
						{
