			private bool IsSqlServer()
			{
				return base.Context is SqlServerExpressionContext;
			}

			private bool IsMySql()
			{
				return base.Context.GetType().Name == "MySqlExpressionContext";
			}

			private bool IsSqlite()
			{
				return base.Context is SqliteExpressionContext;
			}

			private bool IsOracle()
			{
				return base.Context is OracleExpressionContext;
			}

			private void CusMethod(ExpressionParameter parameter, MethodCallExpression express, bool? isLeft)
			{
				try
				{
					OneToManyNavgateExpression oneToManyNavgateExpression = new OneToManyNavgateExpression(base.Context?.SugarContext?.Context, this);
					oneToManyNavgateExpression.ParameterIndex = base.Context.ParameterIndex;
					base.Context.ParameterIndex++;
					if (oneToManyNavgateExpression.IsNavgate(express))
					{
						MapperSql sql = oneToManyNavgateExpression.GetSql();
						SetNavigateResult();
						base.Context.SingleTableNameSubqueryShortName = oneToManyNavgateExpression.ShorName;
						AppendValue(parameter, isLeft, sql);
						return;
					}
					OneToManyNavgateExpressionN oneToManyNavgateExpressionN = new OneToManyNavgateExpressionN(base.Context?.SugarContext?.Context, this);
					if (oneToManyNavgateExpressionN.IsNavgate(express))
					{
						object sql2 = oneToManyNavgateExpressionN.GetSql();
						SetNavigateResult();
						base.Context.SingleTableNameSubqueryShortName = oneToManyNavgateExpressionN.shorName;
						AppendValue(parameter, isLeft, sql2);
						return;
					}
					object obj = ExpressionTool.DynamicInvoke(express);
					if (obj is MapperSql)
					{
						obj = (obj as MapperSql).Sql;
						AppendValue(parameter, isLeft, obj);
						return;
					}
					parameter.BaseParameter.CommonTempData = obj;
					string text = AppendParameter(obj);
					if (parameter.BaseParameter.CommonTempData != null && parameter.BaseParameter.CommonTempData.Equals(CommonTempDataType.Result))
					{
						base.Context.Result.Append(text);
					}
					else
					{
						AppendValue(parameter, isLeft, text);
					}
				}
				catch (Exception ex)
				{
					if (ex is SqlSugarException)
					{
						Check.Exception(true, string.Format(ex.Message, express.Method.Name));
					}
					else
					{
						Check.Exception(true, string.Format(ErrorMessage.MethodError, express.Method.Name));
					}
				}
			}

			private static bool MethodValueIsTrue(object methodValue)
			{
				return methodValue?.ToString().Contains("THEN true  ELSE false END") ?? false;
			}

			private object packIfElse(object methodValue)
			{
				methodValue = base.Context.DbMehtods.CaseWhen(new List<KeyValuePair<string, string>>
				{
					new KeyValuePair<string, string>("IF", methodValue.ObjToString()),
					new KeyValuePair<string, string>("Return", base.Context.DbMehtods.TrueValue()),
					new KeyValuePair<string, string>("End", base.Context.DbMehtods.FalseValue())
				});
				return methodValue;
			}

			private void SetShortName(Expression exp)
			{
				LambdaExpression lambdaExpression = exp as LambdaExpression;
				if (lambdaExpression.Parameters != null && lambdaExpression.Parameters.Count == 1 && base.Context.SingleTableNameSubqueryShortName == null)
				{
					base.Context.SingleTableNameSubqueryShortName = lambdaExpression.Parameters.First().Name;
				}
			}

			private void AppendItem(ExpressionParameter parameter, string name, IEnumerable<Expression> args, MethodCallExpressionModel model, Expression item)
			{
				if (ExpressionTool.IsUnConvertExpress(item))
				{
					item = (item as UnaryExpression).Operand;
				}
				if (base.Context.IsSingle && args.Any((Expression it) => ExpressionTool.IsSubQuery(it)) && base.BaseParameter?.BaseParameter?.BaseParameter?.CurrentExpression != null)
				{
					Expression expression = base.BaseParameter?.BaseParameter?.BaseParameter?.CurrentExpression;
					if (expression is LambdaExpression)
					{
						SetShortName(expression);
					}
					else if (expression is UnaryExpression)
					{
						expression = base.BaseParameter?.BaseParameter?.BaseParameter?.BaseParameter?.CurrentExpression;
						if (expression is LambdaExpression)
						{
							SetShortName(expression);
						}
					}
				}
				else if (base.Context.IsSingle && args.Any((Expression it) => ExpressionTool.IsIsNullSubQuery(it)))
				{
					Expression expression2 = base.BaseParameter?.BaseParameter?.BaseParameter?.CurrentExpression;
					if (expression2 is LambdaExpression)
					{
						SetShortName(expression2);
					}
					else if (expression2 is UnaryExpression)
					{
						expression2 = base.BaseParameter?.BaseParameter?.BaseParameter?.BaseParameter?.CurrentExpression;
