					}
				}
				else
				{
					AppendModel(parameter, model, item, name, args);
				}
			}

			private void AppendModelByIIFMember(ExpressionParameter parameter, MethodCallExpressionModel model, Expression item)
			{
				parameter.CommonTempData = CommonTempDataType.Result;
				base.Expression = item;
				Start();
				MethodCallExpressionArgs methodCallExpressionArgs = new MethodCallExpressionArgs
				{
					IsMember = (parameter.ChildExpression is MemberExpression),
					MemberName = parameter.CommonTempData
				};
				if (methodCallExpressionArgs.IsMember && parameter.ChildExpression != null && parameter.ChildExpression.ToString() == "DateTime.Now")
				{
					methodCallExpressionArgs.IsMember = false;
				}
				object memberName = methodCallExpressionArgs.MemberName;
				if (methodCallExpressionArgs.IsMember)
				{
					MemberExpression memberExpression = parameter.ChildExpression as MemberExpression;
					if (memberExpression.Expression != null && memberExpression.Expression is ConstantExpression)
					{
						methodCallExpressionArgs.IsMember = false;
					}
				}
				if (!methodCallExpressionArgs.IsMember)
				{
					string text = base.Context.SqlParameterKeyWord + "MethodConst" + base.Context.ParameterIndex;
					base.Context.ParameterIndex++;
					methodCallExpressionArgs.MemberName = text;
					methodCallExpressionArgs.MemberValue = memberName;
					base.Context.Parameters.Add(new SugarParameter(text, memberName));
				}
				model.Args.Add(methodCallExpressionArgs);
				parameter.ChildExpression = null;
			}

			private void AppendModelByIIFBinary(ExpressionParameter parameter, MethodCallExpressionModel model, Expression item)
