			private void AppendModelByIIFMethod(ExpressionParameter parameter, MethodCallExpressionModel model, Expression item)
			{
				MethodCallExpression methodCallExpression = item as MethodCallExpression;
				if (methodCallExpression.Method.Name.IsIn("ToBool", "ToBoolean", "IIF"))
				{
					model.Args.Add(GetMethodCallArgs(parameter, item));
				}
				else if (methodCallExpression.Method.Name.IsIn("Contains", "EndsWith", "StartsWith"))
				{
					Expression conditionalExpression = ExpressionTool.GetConditionalExpression(item);
					model.Args.Add(GetMethodCallArgs(parameter, conditionalExpression));
				}
				else
				{
					Check.Exception(true, "The SqlFunc.IIF(arg1,arg2,arg3) , {0} argument  do not support ", item.ToString());
				}
			}

			private void AppendModel(ExpressionParameter parameter, MethodCallExpressionModel model, Expression item, string name, IEnumerable<Expression> args)
			{
				parameter.CommonTempData = CommonTempDataType.Result;
				base.Expression = item;
				bool flag = false;
				bool flag2 = false;
				if (item.Type == UtilConstants.DateType && parameter.CommonTempData.ObjToString() == CommonTempDataType.Result.ToString() && item.ToString() == "DateTime.Now.Date")
				{
					parameter.CommonTempData = DateTime.Now.Date;
				}
				else if (item is ConditionalExpression)
				{
					parameter.CommonTempData = GetNewExpressionValue(item);
				}
				else if (IsNot(item))
				{
					parameter.CommonTempData = GetNewExpressionValue(item);
				}
				else if (IsDateDate(item))
				{
					parameter.CommonTempData = GetNewExpressionValue(item);
				}
				else if (IsDateValue(item))
				{
					parameter.CommonTempData = GetNewExpressionValue(item);
				}
				else if (model.Name == "ToString" && item is ConstantExpression && (item as ConstantExpression).Type.IsEnum())
				{
					parameter.CommonTempData = item.ToString();
				}
				else if (IsDateItemValue(item))
				{
					parameter.CommonTempData = GetNewExpressionValue(item);
				}
				else if (name == "Format" && item is NewArrayExpression)
				{
					ReadOnlyCollection<Expression> expressions = (item as NewArrayExpression).Expressions;
					parameter.CommonTempData = expressions.Select((Expression it) => GetNewExpressionValue(ExpressionTool.RemoveConvert(it))).ToArray();
				}
				else if (name == "Format" && item is ConstantExpression)
				{
					parameter.CommonTempData = ExpressionTool.GetExpressionValue(item);
				}
				else if (name == "FullTextContains" && item is NewArrayExpression)
				{
					List<string> newArrayMembers = ExpressionTool.GetNewArrayMembers(item as NewArrayExpression);
					parameter.CommonTempData = newArrayMembers.Select((string it) => base.Context.GetTranslationColumnName(it)).ToList();
					flag = true;
				}
				else if (ExpressionTool.IsNegate(item) && (item as UnaryExpression)?.Operand is MemberExpression)
				{
					Expression item2 = (item as UnaryExpression)?.Operand;
					parameter.CommonTempData = GetNewExpressionValue(item2) + " * -1 ";
					flag = true;
					flag2 = true;
				}
				else if (name == "IIF" && item is MemberExpression memberExpression && memberExpression?.Expression is BinaryExpression && ExpressionTool.GetParameters(memberExpression).Count > 0)
				{
					parameter.CommonTempData = GetNewExpressionValue(memberExpression);
					flag = true;
					flag2 = true;
				}
				else
				{
					Start();
				}
				MethodCallExpressionArgs methodCallExpressionArgs = new MethodCallExpressionArgs
				{
					IsMember = (parameter.ChildExpression is MemberExpression && !ExpressionTool.IsConstExpression(parameter.ChildExpression as MemberExpression)),
					MemberName = parameter.CommonTempData
				};
				ExpressionContext context = base.Context;
				if (context != null && context.SugarContext?.Context?.CurrentConnectionConfig?.MoreSettings?.IsCorrectErrorSqlParameterName == true && methodCallExpressionArgs.MemberName is string)
				{
					methodCallExpressionArgs.MemberName = ExpressionTool.ResolveMemberValue(base.Context, item, methodCallExpressionArgs.MemberName?.ToString());
				}
				if (methodCallExpressionArgs.MemberName is MapperSql)
				{
					methodCallExpressionArgs.MemberName = (methodCallExpressionArgs.MemberName as MapperSql).Sql;
				}
				if (methodCallExpressionArgs.IsMember && parameter.ChildExpression != null && parameter.ChildExpression.ToString() == "DateTime.Now")
				{
					methodCallExpressionArgs.IsMember = false;
				}
				object obj = methodCallExpressionArgs.MemberName;
				if (methodCallExpressionArgs.IsMember)
				{
					MemberExpression memberExpression2 = parameter.ChildExpression as MemberExpression;
					if (memberExpression2.Expression != null && memberExpression2.Expression is ConstantExpression)
					{
						methodCallExpressionArgs.IsMember = false;
					}
				}
				if (IsDateDate(item) || IsDateValue(item) || IsDateItemValue(item) || item is ConditionalExpression || IsNot(item))
				{
					methodCallExpressionArgs.IsMember = true;
				}
				if ((!methodCallExpressionArgs.IsMember && item is MethodCallExpression && item.ToString() == "GetDate()") || (item is UnaryExpression && ((UnaryExpression)item).Operand.ToString() == "GetDate()"))
				{
					_ = base.Context.SqlParameterKeyWord + "MethodConst" + base.Context.ParameterIndex;
					base.Context.ParameterIndex++;
					methodCallExpressionArgs.MemberName = obj;
					methodCallExpressionArgs.MemberValue = null;
				}
				else if (!methodCallExpressionArgs.IsMember && !flag2)
				{
					string text = base.Context.SqlParameterKeyWord + "MethodConst" + base.Context.ParameterIndex;
					base.Context.ParameterIndex++;
					methodCallExpressionArgs.MemberName = text;
					if (name == "ToString" && UtilMethods.GetUnderType(base.Expression.Type).IsEnum())
					{
						obj = obj?.ToString();
					}
					else if (name == "ContainsArray" && args.Count() == 2 && obj != null && obj is IList)
					{
						List<object> list = new List<object>();
						foreach (object item3 in obj as IList)
						{
							list.Add(GetMemberValue(item3, args.Last(), out SugarParameter _));
						}
						obj = list;
					}
					else if (!(item is ParameterExpression) && name.IsIn("Contains", "StartsWith", "EndsWith") && item == args.Last() && ExpressionTool.IsSqlParameterDbType(base.Context, args.First()))
					{
						object value = ExpressionTool.DynamicInvoke(args.Last());
						SugarParameter parameterBySqlParameterDbType = ExpressionTool.GetParameterBySqlParameterDbType(base.Context.ParameterIndex, value, base.Context, args.First());
						base.Context.Parameters.Add(parameterBySqlParameterDbType);
						methodCallExpressionArgs.MemberName = parameterBySqlParameterDbType.ParameterName;
						methodCallExpressionArgs.MemberValue = parameterBySqlParameterDbType.Value;
						methodCallExpressionArgs.IsMember = true;
						flag = true;
						base.Context.ParameterIndex++;
					}
					methodCallExpressionArgs.MemberValue = obj;
					if (!flag)
					{
						if (obj == null && item != null)
						{
							base.Context.Parameters.Add(new SugarParameter(text, obj, UtilMethods.GetUnderType(item.Type)));
						}
						else
						{
							base.Context.Parameters.Add(new SugarParameter(text, obj));
						}
					}
				}
				model.Args.Add(methodCallExpressionArgs);
				parameter.ChildExpression = null;
			}

			private void GetConfigValue(MethodCallExpression express, ExpressionParameter parameter)
			{
				Expression expression = express.Arguments[0];
				string name = Regex.Match(express.Method.ToString(), "GetConfigValue\\[(.+)\\]").Groups[1].Value;
				string code = null;
				if (express.Arguments.Count > 1)
				{
					code = ExpressionTool.GetExpressionValue(express.Arguments[1])?.ToString() ?? "";
				}
				ConfigTableInfo configTableInfo = SqlFuncExtendsion.TableInfos.FirstOrDefault((ConfigTableInfo y) => y.Type.Name == name && y.Code == code);
				Check.Exception(configTableInfo == null, $"GetConfigValue no configuration  Entity={name} UniqueCode={code}");
				ConfigTableInfo configTableInfo2 = new ConfigTableInfo
				{
					Code = configTableInfo.Code,
					TableName = configTableInfo.TableName,
					Key = configTableInfo.Key,
					Parameter = new List<SugarParameter>(),
					Type = configTableInfo.Type,
					Value = configTableInfo.Value,
					Where = configTableInfo.Where
				};
				if (configTableInfo.Parameter != null && configTableInfo.Parameter.Any())
				{
					foreach (SugarParameter item in configTableInfo.Parameter)
					{
						configTableInfo2.Parameter.Add(new SugarParameter("", null)
						{
							DbType = item.DbType,
							Direction = item.Direction,
							IsArray = item.IsArray,
							IsJson = item.IsJson,
							IsNullable = item.IsNullable,
							IsRefCursor = item.IsRefCursor,
							ParameterName = item.ParameterName,
							Size = item.Size,
							SourceColumn = item.SourceColumn,
							SourceColumnNullMapping = item.SourceColumnNullMapping,
							SourceVersion = item.SourceVersion,
							TempDate = item.TempDate,
							TypeName = item.TypeName,
							Value = item.Value,
							_Size = item._Size
						});
					}
				}
				string format = " (SELECT {0} FROM {1} WHERE {2}={3}";
				if (ExpressionTool.IsUnConvertExpress(expression))
				{
					expression = (expression as UnaryExpression).Operand;
				}
				MemberExpression memberExpression = expression as MemberExpression;
				object obj = null;
				if (expression is ConditionalExpression conditionalExpression)
				{
					MethodCallExpressionModel methodCallExpressionModel = new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs>()
					};
					memberExpression = conditionalExpression.Test as MemberExpression;
					Type type = memberExpression.Expression.Type;
					string name2 = memberExpression.Member.Name;
					methodCallExpressionModel.Args.Add(new MethodCallExpressionArgs
					{
						MemberValue = conditionalExpression.Test,
						MemberName = base.Context.GetDbColumnName(type.Name, name2)
					});
					methodCallExpressionModel.Args.Add(new MethodCallExpressionArgs
					{
						MemberValue = conditionalExpression.IfTrue,
						MemberName = conditionalExpression.IfTrue
					});
					methodCallExpressionModel.Args.Add(new MethodCallExpressionArgs
					{
						MemberValue = conditionalExpression.IfFalse,
						MemberName = conditionalExpression.IfFalse
					});
					methodCallExpressionModel.Expression = expression;
					obj = IIF_Ex(methodCallExpressionModel);
				}
				Expression expression2 = memberExpression.Expression;
				Type type2 = expression2.Type;
				string name3 = memberExpression.Member.Name;
				string text = $"{base.Context.GetTranslationColumnName(expression2.ToString())}.{base.Context.GetDbColumnName(type2.Name, name3)}";
				if (base.Context.IsSingle)
				{
					base.Context.SingleTableNameSubqueryShortName = expression2.ToString();
				}
				format = ((obj != null) ? string.Format(format, configTableInfo2.Value, base.Context.GetTranslationColumnName(configTableInfo2.TableName), configTableInfo2.Key, obj) : string.Format(format, configTableInfo2.Value, base.Context.GetTranslationColumnName(configTableInfo2.TableName), configTableInfo2.Key, text));
				if (configTableInfo2.Parameter != null)
				{
					foreach (SugarParameter item2 in configTableInfo2.Parameter)
					{
						string parameterName = item2.ParameterName;
						item2.ParameterName = Regex.Split(parameterName, "_con_").First() + "_con_" + base.Context.ParameterIndex;
						configTableInfo2.Where = configTableInfo2.Where.Replace(parameterName, item2.ParameterName);
					}
					base.Context.ParameterIndex++;
					base.Context.Parameters.AddRange(configTableInfo2.Parameter);
				}
				if (configTableInfo2.Where.HasValue())
				{
					format = format + " AND " + configTableInfo2.Where;
				}
				format += " )";
				if (base.Context.ResolveType.IsIn(ResolveExpressType.SelectMultiple, ResolveExpressType.SelectSingle, ResolveExpressType.Update))
				{
					parameter.BaseParameter.CommonTempData = format;
				}
				else
				{
					AppendMember(parameter, parameter.IsLeft, format);
				}
			}

			private string IIF_Ex(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				MethodCallExpressionArgs methodCallExpressionArgs3 = model.Args[2];
				string ifTrue = methodCallExpressionArgs2.MemberName.ObjToString();
				string ifFalse = methodCallExpressionArgs3.MemberName.ObjToString();
				if (ifTrue == ifFalse)
				{
					return $" {methodCallExpressionArgs2.MemberName} ";
				}
				if (model.Parameters != null && model.Conext != null && ifTrue.StartsWith(model.Conext?.SqlParameterKeyWord) && ifFalse.StartsWith(model.Conext?.SqlParameterKeyWord))
				{
					SugarParameter sugarParameter = model.Parameters.Where((SugarParameter it) => it.ParameterName != null).FirstOrDefault((SugarParameter it) => it.ParameterName.Equals(ifTrue));
					SugarParameter sugarParameter2 = model.Parameters.Where((SugarParameter it) => it.ParameterName != null).FirstOrDefault((SugarParameter it) => it.ParameterName.Equals(ifFalse));
					if (sugarParameter != null && sugarParameter2 != null)
					{
						object value = sugarParameter.Value;
						if (value != null && value.Equals(sugarParameter2.Value))
						{
							model.Parameters.Remove(sugarParameter2);
							return $" {methodCallExpressionArgs2.MemberName} ";
						}
					}
				}
				return $"( CASE  WHEN  {methodCallExpressionArgs.MemberName.ToString().ToLower()} THEN N'{methodCallExpressionArgs2.MemberName.ToString().Trim('"')}'  ELSE N'{methodCallExpressionArgs3.MemberName.ToString().Trim('"')}' END )";
			}

			private object GetMethodValue(string name, MethodCallExpressionModel model)
			{
				model.Parameters = base.Context.Parameters;
				if (IsExtMethod(name))
				{
					model.Expression = base.Expression;
					model.BaseExpression = base.BaseParameter.CurrentExpression;
					DbType dbType = DbType.SqlServer;
					dbType = ((base.Context is SqlServerExpressionContext) ? DbType.SqlServer : ((!(base.Context is MySqlExpressionContext)) ? ((base.Context is SqliteExpressionContext) ? DbType.Sqlite : ((base.Context is OracleExpressionContext) ? DbType.Oracle : ((!base.Context.GetType().Name.StartsWith("MySql")) ? GetType(base.Context.GetType().Name) : DbType.MySql))) : DbType.MySql));
					return base.Context.SqlFuncServices.First((SqlFuncExternal it) => it.UniqueMethodName == name).MethodValue(model, dbType, base.Context);
				}
				ExpressionContext context = base.Context;
				bool iLike = context != null && context.SugarContext?.Context?.CurrentConnectionConfig?.MoreSettings?.EnableILike == true;
				if (name == "Parse" && TempParseType.IsIn(UtilConstants.GuidType) && model.Args != null && model.Args.Count() > 1)
				{
					name = "Equals";
				}
				else if (name == "Parse")
				{
					name = "To" + TempParseType.Name;
				}
				else if (name == "IsNullOrWhiteSpace")
				{
					name = "IsNullOrEmpty";
				}
				if (model.Conext == null)
				{
					model.Conext = base.Context;
				}
				string result5;
				switch (name)
				{
				case "IIF":
					return base.Context.DbMehtods.IIF(model);
				case "HasNumber":
					return base.Context.DbMehtods.HasNumber(model);
				case "HasValue":
					return base.Context.DbMehtods.HasValue(model);
				case "IsNullOrEmpty":
					model.Conext = base.Context;
					return base.Context.DbMehtods.IsNullOrEmpty(model);
				case "ToLower":
					return base.Context.DbMehtods.ToLower(model);
				case "ToUpper":
					return base.Context.DbMehtods.ToUpper(model);
				case "Trim":
					return base.Context.DbMehtods.Trim(model);
				case "Contains":
					return GetLike(base.Context.DbMehtods.Contains(model), iLike);
				case "ContainsArray":
				{
					if (model.Args[0].MemberValue == null)
					{
						SugarParameter sugarParameter = base.Context.Parameters.FirstOrDefault((SugarParameter it) => it.ParameterName == model.Args[0].MemberName.ObjToString());
						if (sugarParameter.HasValue())
						{
							model.Args[0].MemberValue = sugarParameter.Value;
						}
					}
					if (base.Context.TableEnumIsString == true)
					{
						List<string> list = new List<string>();
						foreach (object item in model.Args[0].MemberValue as IEnumerable)
						{
							if (item != null && UtilMethods.GetUnderType(item.GetType()).IsEnum())
							{
								list.Add(item.ToString());
							}
						}
						if (list.Any())
						{
							model.Args[0].MemberValue = list;
						}
					}
					string result4 = base.Context.DbMehtods.ContainsArray(model);
					base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[0].MemberName.ObjToString());
					return result4;
				}
				case "ContainsArrayUseSqlParameters":
				{
					if (model.Args[0].MemberValue == null)
					{
						SugarParameter sugarParameter2 = base.Context.Parameters.FirstOrDefault((SugarParameter it) => it.ParameterName == model.Args[0].MemberName.ObjToString());
						if (sugarParameter2.HasValue())
						{
							model.Args[0].MemberValue = sugarParameter2.Value;
						}
					}
					model.Data = base.Context.SqlParameterKeyWord + "INP_" + base.Context.ParameterIndex;
					base.Context.ParameterIndex++;
					if (model.Args[0].MemberValue.HasValue())
					{
						IEnumerable obj = (IEnumerable)model.Args[0].MemberValue;
						int num = 0;
						foreach (object item2 in obj)
						{
							base.Context.Parameters.Add(new SugarParameter(model.Data + "_" + num, item2));
							num++;
						}
					}
					string result6 = base.Context.DbMehtods.ContainsArrayUseSqlParameters(model);
					base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[0].MemberName.ObjToString());
					return result6;
				}
				case "Equals":
					return base.Context.DbMehtods.Equals(model);
				case "EqualsNull":
					return base.Context.DbMehtods.EqualsNull(model);
				case "DateIsSame":
				{
					if (model.Args.Count == 2)
					{
						return base.Context.DbMehtods.DateIsSameDay(model);
					}
					string result3 = base.Context.DbMehtods.DateIsSameByType(model);
					base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[2].MemberName.ObjToString());
					return result3;
				}
				case "DateAdd":
				{
					model.Conext = base.Context;
					if (model.Args.Count == 2)
					{
						return base.Context.DbMehtods.DateAddDay(model);
					}
					string result2 = base.Context.DbMehtods.DateAddByType(model);
					base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[2].MemberName.ObjToString());
					return result2;
				}
				case "DateValue":
				{
					string result = base.Context.DbMehtods.DateValue(model);
					base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[1].MemberName.ObjToString());
					return result;
				}
				case "Between":
					return base.Context.DbMehtods.Between(model);
				case "StartsWith":
					return GetLike(base.Context.DbMehtods.StartsWith(model), iLike);
				case "EndsWith":
					return GetLike(base.Context.DbMehtods.EndsWith(model), iLike);
				case "ToInt32":
					return base.Context.DbMehtods.ToInt32(model);
				case "ToInt64":
					return base.Context.DbMehtods.ToInt64(model);
				case "ToDate":
					return base.Context.DbMehtods.ToDate(model);
				case "ToDateTime":
					return base.Context.DbMehtods.ToDate(model);
				case "ToTime":
					return base.Context.DbMehtods.ToTime(model);
				case "ToString":
					if (model.Args.Count > 1)
					{
						string dateString = base.Context.DbMehtods.GetDateString(model.Args.First().MemberName.ObjToString(), model.Args.Last().MemberValue.ObjToString());
						if (IsSqlServerModel())
						{
							return $"FORMAT({model.Args.First().MemberName.ObjToString()},'{model.Args.Last().MemberValue.ObjToString()}')";
						}
						if (dateString != null)
						{
							return dateString;
						}
						return GeDateFormat(model.Args.Last().MemberValue.ObjToString(), model.Args.First().MemberName.ObjToString());
					}
					return base.Context.DbMehtods.ToString(model);
				case "ToVarchar":
					return base.Context.DbMehtods.ToVarchar(model);
				case "ToDecimal":
					return base.Context.DbMehtods.ToDecimal(model);
				case "ToGuid":
					return base.Context.DbMehtods.ToGuid(model);
				case "ToDouble":
					return base.Context.DbMehtods.ToDouble(model);
				case "ToBool":
					return base.Context.DbMehtods.ToBool(model);
				case "ToBoolean":
					return base.Context.DbMehtods.ToBool(model);
				case "Substring":
					if (model.Args.Count == 2)
					{
						model.Args.Add(new MethodCallExpressionArgs
						{
							MemberName = "100000",
							IsMember = true,
							MemberValue = "100000"
						});
					}
					model.Conext = base.Context;
					return base.Context.DbMehtods.Substring(model);
				case "Replace":
					return base.Context.DbMehtods.Replace(model);
				case "Length":
					return base.Context.DbMehtods.Length(model);
				case "AggregateSum":
					return base.Context.DbMehtods.AggregateSum(model);
				case "AggregateAvg":
					return base.Context.DbMehtods.AggregateAvg(model);
				case "AggregateMin":
					return base.Context.DbMehtods.AggregateMin(model);
				case "AggregateMax":
					return base.Context.DbMehtods.AggregateMax(model);
				case "AggregateCount":
					return base.Context.DbMehtods.AggregateCount(model);
				case "AggregateDistinctCount":
					return base.Context.DbMehtods.AggregateDistinctCount(model);
				case "MappingColumn":
				{
					string text2 = base.Context.DbMehtods.MappingColumn(model);
					if (model.Args.Count == 1 && text2.IsNullOrEmpty())
					{
						return model.Args[0].MemberName.ObjToString().TrimStart('\'').TrimEnd('\'');
					}
					if (model.Args[0].IsMember)
					{
						_ = !model.Args[1].IsMember;
					}
					else
						_ = 0;
					if (model.Args.Count > 1)
					{
						base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[1].MemberName.ObjToString());
					}
					else
					{
						base.Context.Parameters.RemoveAll((SugarParameter it) => it.ParameterName == model.Args[0].MemberName.ObjToString());
					}
					if (text2 == "")
					{
						return model.Args[1].MemberName.ObjToString().TrimStart('\'').TrimEnd('\'');
					}
					return text2;
				}
				case "IsNull":
					return base.Context.DbMehtods.IsNull(model);
				case "MergeString":
					return base.Context.DbMehtods.MergeString(model.Args.Select((MethodCallExpressionArgs it) => it.MemberName.ObjToString()).ToArray());
				case "SelectAll":
