					if (list.HasValue())
					{
						KeyValuePair<string, SugarParameter[]> keyValuePair = context.Queryable<object>().SqlBuilder.ConditionalModelToSql(list);
						string appendSql = keyValuePair.Key;
						int valueOrDefault = (methodCallExpressionResolve?.Context?.SugarContext?.QueryBuilder?.Parameters?.Count).GetValueOrDefault();
						UtilMethods.RepairReplicationParameters(ref appendSql, keyValuePair.Value, 0, "_" + valueOrDefault + "_");
						methodCallExpressionResolve.Context.Parameters.AddRange(keyValuePair.Value);
						return appendSql;
					}
					return " 1=1 ";
				}
				InitType(expression);
				return methodCallExpressionResolve.GetNewExpressionValue(expression);
			}

			private void InitType(Expression whereExp)
			{
				if (!(whereExp is LambdaExpression))
				{
					return;
				}
				ReadOnlyCollection<ParameterExpression> parameters = (whereExp as LambdaExpression).Parameters;
				if (parameters == null || parameters.Count <= 0)
				{
					return;
				}
				foreach (ParameterExpression item in parameters)
				{
					context.InitMappingInfo(item.Type);
				}
			}

			private bool ValidateNav(bool result, MemberExpression memberExp, Expression childExpression)
			{
				if (childExpression != null && childExpression is MemberExpression)
				{
					Expression expression = (childExpression as MemberExpression).Expression;
					if (expression.Type.IsClass() && expression is ParameterExpression)
					{
						Type type = expression.Type;
						EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(type);
						Type type2 = childExpression.Type.GetGenericArguments()[0];
						EntityInfo entityInfo2 = context.EntityMaintenance.GetEntityInfo(type2);
						if (entityInfo.Columns.Any((EntityColumnInfo x) => x.PropertyName == (childExpression as MemberExpression).Member.Name && x.Navigat != null))
						{
							EntityInfo = entityInfo;
							ShorName = expression.ToString();
							MemberName = memberExp.Member.Name;
							ProPertyEntity = entityInfo2;
							Navigat = entityInfo.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == (childExpression as MemberExpression).Member.Name).Navigat;
							result = true;
						}
					}
				}
				return result;
			}

			internal MapperSql GetSql()
			{
				if (Navigat.NavigatType == NavigateType.OneToMany)
				{
					return GetOneToManySql();
				}
				if (Navigat.NavigatType == NavigateType.Dynamic)
				{
					return GetDynamicSql();
				}
				return GetManyToManySql();
			}

			private MapperSql GetDynamicSql()
			{
				if (Navigat.Name == null)
				{
					Check.ExceptionEasy(isException: true, " NavigateType.Dynamic User-defined navigation objects need to be configured with json to be used in expressions .  " + ProPertyEntity.Type.Name, " NavigateType.Dynamic 自定义导航对象需要配置json才能在表达式中使用。 " + ProPertyEntity.Type.Name);
				}
				MapperSql mapperSql = new MapperSql();
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>();
				if (PropertyShortName.HasValue())
				{
					sugarQueryable.QueryBuilder.TableShortName = PropertyShortName;
				}
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500;
				bool flag = false;
				Type[] types = null;
				if (methodCallExpressionResolve?.Context?.SugarContext?.QueryBuilder != null)
				{
					sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500 + methodCallExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex;
					methodCallExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex++;
					flag = methodCallExpressionResolve.Context.SugarContext.QueryBuilder.IsDisabledGobalFilter;
					types = methodCallExpressionResolve.Context.SugarContext.QueryBuilder.RemoveFilters;
				}
				sugarQueryable.AS(ProPertyEntity.DbTableName).ClearFilter(types).Filter(flag ? null : ProPertyEntity.Type)
					.WhereIF(!string.IsNullOrEmpty(whereSql), whereSql);
				foreach (JToken item2 in JArray.Parse(Navigat.Name))
				{
					string m = ((object)item2[(object)"m"])?.ToString() ?? "";
					string c = ((object)item2[(object)"c"])?.ToString() ?? "";
					string dbColumnName = EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == m).DbColumnName;
					string dbColumnName2 = ProPertyEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == c).DbColumnName;
					sugarQueryable.Where($" {sugarQueryable.SqlBuilder.GetTranslationColumnName(ShorName)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(dbColumnName)}={sugarQueryable.SqlBuilder.GetTranslationColumnName(dbColumnName2)} ");
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.ToSql();
				List<SugarParameter> value = keyValuePair.Value;
				if (value != null && value.Any())
				{
					foreach (SugarParameter item in keyValuePair.Value)
					{
						if (!methodCallExpressionResolve.Context.Parameters.Any((SugarParameter it) => it.ParameterName == item.ParameterName))
						{
							methodCallExpressionResolve.Context.Parameters.Add(item);
						}
					}
				}
				mapperSql.Sql = keyValuePair.Key;
				mapperSql.Sql = " (" + mapperSql.Sql + ") ";
				mapperSql.Sql = GetMethodSql(mapperSql.Sql);
				return mapperSql;
			}

			private MapperSql GetManyToManySql()
			{
				string text = ProPertyEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey)?.DbColumnName;
				string text2 = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey)?.DbColumnName;
				if (Navigat.BClassId.HasValue())
				{
					text = ProPertyEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == Navigat.BClassId)?.DbColumnName;
				}
				if (Navigat.AClassId.HasValue())
				{
					text2 = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == Navigat.AClassId)?.DbColumnName;
				}
				Check.ExceptionEasy(text2.IsNullOrEmpty(), EntityInfo.EntityName + "need primary key", EntityInfo.EntityName + "需要主键");
				Check.ExceptionEasy(text.IsNullOrEmpty(), ProPertyEntity.EntityName + "need primary key", ProPertyEntity.EntityName + "需要主键");
				MapperSql mapperSql = new MapperSql();
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>();
				text = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(text);
				text2 = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(text2);
				Type mappingType = Navigat.MappingType;
				Check.ExceptionEasy(mappingType == null, "ManyToMany misconfiguration", "多对多配置错误");
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(mappingType);
				string translationTableName = sugarQueryable.QueryBuilder.Builder.GetTranslationTableName(entityInfo.DbTableName);
				string dbColumnName = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == Navigat.MappingAId).DbColumnName;
				string dbColumnName2 = entityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == Navigat.MappingBId).DbColumnName;
				dbColumnName = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName);
				dbColumnName2 = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName2);
				string translationTableName2 = sugarQueryable.QueryBuilder.Builder.GetTranslationTableName(ProPertyEntity.DbTableName);
				context.InitMappingInfo(mappingType);
				QueryBuilder queryBuilder = context.Queryable<object>().QueryBuilder;
				queryBuilder.LambdaExpressions.ParameterIndex = 100 + ParameterIndex;
				string filters = queryBuilder.GetFilters(mappingType);
				if (filters.HasValue())
				{
					MethodCallExpressionResolve obj = methodCallExpressionResolve;
					if (obj == null || obj.Context?.SugarContext?.QueryBuilder?.IsDisabledGobalFilter != true)
					{
						text2 = text2 + " AND " + filters;
						if (queryBuilder.Parameters != null)
						{
							methodCallExpressionResolve.Context.Parameters.AddRange(queryBuilder.Parameters);
						}
					}
				}
				mapperSql.Sql = $" (select {((MethodName == "Any") ? "1" : " COUNT(1) ")} from {translationTableName2} {ProPertyEntity.DbTableName}_1  where  {ProPertyEntity.DbTableName}_1.{text} in (select {dbColumnName2} from {translationTableName} where {dbColumnName} = {ShorName}.{text2} )  )";
				if (whereSql.HasValue())
				{
					mapperSql.Sql = mapperSql.Sql.TrimEnd(')');
					if (whereSql.Contains(" " + PropertyShortName + "."))
					{
						whereSql = whereSql.Replace(" " + PropertyShortName + ".", " " + ProPertyEntity.DbTableName + "_1.");
					}
					else if (whereSql.Contains(" " + sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(PropertyShortName) + "."))
					{
						whereSql = whereSql.Replace(" " + sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(PropertyShortName) + ".", " " + ProPertyEntity.DbTableName + "_1.");
					}
					else if (whereSql.Contains("(" + sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(PropertyShortName) + "."))
					{
						whereSql = whereSql.Replace("(" + sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(PropertyShortName) + ".", "(" + ProPertyEntity.DbTableName + "_1.");
					}
					mapperSql.Sql = mapperSql.Sql + " AND " + whereSql + ")";
				}
				if (MethodName == "Any")
				{
					mapperSql.Sql = " " + mapperSql.Sql + " ";
				}
				else
				{
					mapperSql.Sql = " (" + mapperSql.Sql + ") ";
				}
				mapperSql.Sql = GetMethodSql(mapperSql.Sql);
				return mapperSql;
			}

			private MapperSql GetOneToManySql()
			{
				EntityColumnInfo entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (Navigat.Name2.HasValue())
				{
					entityColumnInfo = EntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == Navigat.Name2);
				}
				Check.ExceptionEasy(entityColumnInfo == null, EntityInfo.EntityName + " need primary key ", "导航属性 " + EntityInfo.EntityName + "需要主键");
				string dbColumnName = entityColumnInfo.DbColumnName;
				string dbColumnName2 = ProPertyEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == Navigat.Name).DbColumnName;
				MapperSql mapperSql = new MapperSql();
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>();
				dbColumnName = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName);
				dbColumnName2 = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName2);
				if (PropertyShortName.HasValue())
				{
					sugarQueryable.QueryBuilder.TableShortName = PropertyShortName;
				}
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500;
				bool flag = false;
				Type[] types = null;
				if (methodCallExpressionResolve?.Context?.SugarContext?.QueryBuilder != null)
				{
					sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500 + methodCallExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex;
					methodCallExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex++;
					flag = methodCallExpressionResolve.Context.SugarContext.QueryBuilder.IsDisabledGobalFilter;
					types = methodCallExpressionResolve.Context.SugarContext.QueryBuilder.RemoveFilters;
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.AS(ProPertyEntity.DbTableName).ClearFilter(types).Filter(flag ? null : ProPertyEntity.Type)
					.WhereIF(!string.IsNullOrEmpty(whereSql), whereSql)
					.Where($" {dbColumnName2}={sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(ShorName)}.{dbColumnName} ")
					.Select((MethodName == "Any") ? "1" : " COUNT(1) ")
					.ToSql();
				List<SugarParameter> value = keyValuePair.Value;
				if (value != null && value.Any())
				{
					foreach (SugarParameter item in keyValuePair.Value)
					{
						if (!methodCallExpressionResolve.Context.Parameters.Any((SugarParameter it) => it.ParameterName == item.ParameterName))
						{
							methodCallExpressionResolve.Context.Parameters.Add(item);
						}
					}
				}
				mapperSql.Sql = keyValuePair.Key;
				mapperSql.Sql = " (" + mapperSql.Sql + ") ";
				mapperSql.Sql = GetMethodSql(mapperSql.Sql);
				return mapperSql;
			}

			private string GetMethodSql(string sql)
			{
				if (MethodName == "Any")
				{
					return " ( EXISTS " + sql + " ) ";
				}
				return sql;
			}
		}
		internal class OneToManyNavgateExpressionN
		{
			public SqlSugarProvider context;

			public string shorName;

			public EntityInfo entityInfo;

			public List<ExpressionItems> items;

			public string whereSql;

			public MethodCallExpressionResolve methodCallExpressionResolve;

			public OneToManyNavgateExpressionN(SqlSugarProvider context, MethodCallExpressionResolve methodCallExpressionResolve)
			{
				this.context = context;
				this.methodCallExpressionResolve = methodCallExpressionResolve;
			}

			internal bool IsNavgate(Expression expression)
			{
				bool result = false;
				Expression expression2 = expression;
				if (expression2 is UnaryExpression)
				{
					expression2 = (expression2 as UnaryExpression).Operand;
				}
				if (expression2 is MethodCallExpression)
				{
					MethodCallExpression methodCallExpression = expression2 as MethodCallExpression;
					if (methodCallExpression.Method.Name.IsIn("Any", "Count") && methodCallExpression.Arguments.Count > 0 && methodCallExpression.Arguments[0] is MemberExpression)
					{
						result = ValiteOneManyCall(result, methodCallExpression, methodCallExpression.Arguments[0] as MemberExpression, methodCallExpression.Arguments[0]);
						if (methodCallExpression.Arguments.Count > 1)
						{
							whereSql = GetWhereSql(methodCallExpression);
						}
					}
				}
				return result;
			}

			private bool ValiteOneManyCall(bool result, MethodCallExpression callExpression, MemberExpression memberExp, Expression childExpression)
			{
				if (childExpression != null && childExpression is MemberExpression)
				{
					Expression expression = (childExpression as MemberExpression).Expression;
					if (expression == null || expression is ConstantExpression)
					{
						return false;
					}
					items = new List<ExpressionItems>();
					Type type = childExpression.Type;
					if (!type.FullName.IsCollectionsList())
					{
						return false;
					}
					type = type.GetGenericArguments()[0];
					items.Add(new ExpressionItems
					{
						Type = 3,
						Expression = callExpression,
						ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(type)
					});
					items.Add(new ExpressionItems
					{
						Type = 2,
						Expression = childExpression,
						ThisEntityInfo = context.EntityMaintenance.GetEntityInfo(type),
						ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type)
					});
					if (items.Any((ExpressionItems it) => it.Type == 2 && it.Nav == null))
					{
						return false;
					}
					while (expression != null)
					{
						if (IsClass(expression))
						{
							items.Add(new ExpressionItems
							{
								Type = 2,
								Expression = expression,
								ThisEntityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type),
								ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(GetMemberExpression(expression).Type)
							});
							expression = GetMemberExpression(expression);
							continue;
						}
						if (IsParameter(expression))
						{
							shorName = expression.ToString();
							entityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type);
						}
						break;
					}
					if (!items.Any((ExpressionItems it) => it.Type == 2 && it.Nav == null))
					{
						return true;
					}
				}
				return result;
			}

			public object GetSql()
			{
				MapperSql mapperSql = new MapperSql();
				ExpressionItems expressionItems = items.Where((ExpressionItems it) => it.Type == 3).First();
				List<ExpressionItems> source = items.Where((ExpressionItems it) => it.Type == 2).Reverse().ToList();
				ExpressionItems formInfo = source.First();
				List<ExpressionItems> list = source.Skip(1).ToList();
				int num = 0;
				string text = formInfo.ThisEntityInfo.DbTableName + num;
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>(text).AS(formInfo.ThisEntityInfo.DbTableName);
				num++;
				string lastShortName = "";
				int index = 0;
				foreach (ExpressionItems item in list)
				{
					lastShortName = ((item.Nav.NavigatType != NavigateType.OneToMany) ? ((item.Nav.NavigatType != NavigateType.OneToOne) ? ManyToMany(ref formInfo, ref num, sugarQueryable, ref index, item) : OneToOne(ref formInfo, ref num, sugarQueryable, ref index, item)) : OneToMany(ref formInfo, ref num, sugarQueryable, ref index, item));
				}
				bool flag = (expressionItems.Expression as MethodCallExpression).Method.Name == "Any";
				sugarQueryable.Select(flag ? "1" : " COUNT(1) ");
				ExpressionItems last = source.First();
				EntityColumnInfo firstPkColumn = last.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				firstPkColumn = GetFirstPkColumn(last, firstPkColumn);
				Check.ExceptionEasy(firstPkColumn == null, last.ThisEntityInfo.EntityName + " need PrimayKey", "使用导航属性" + last.ThisEntityInfo.EntityName + " 缺少主键");
				EntityColumnInfo entityColumnInfo = last.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == last.Nav.Name);
				Check.ExceptionEasy(entityColumnInfo == null, last.ParentEntityInfo.EntityName + " no found " + last.Nav.Name, last.ParentEntityInfo.EntityName + " 不存在 " + last.Nav.Name);
				sugarQueryable.Where($" {sugarQueryable.SqlBuilder.GetTranslationColumnName(shorName)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName)} = {sugarQueryable.SqlBuilder.GetTranslationColumnName(text)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(firstPkColumn.DbColumnName)} ");
				sugarQueryable.WhereIF(whereSql.HasValue(), GetWhereSql1(whereSql, lastShortName, list, sugarQueryable.SqlBuilder));
				mapperSql.Sql = "( " + sugarQueryable.ToSql().Key + " ) ";
				if (flag)
				{
					if (mapperSql.Sql.StartsWith("( ") && mapperSql.Sql.EndsWith(" ) "))
					{
						mapperSql.Sql = " EXISTS " + mapperSql.Sql + " ";
					}
					else
					{
						mapperSql.Sql = " EXISTS( " + mapperSql.Sql + ") ";
					}
				}
				return mapperSql;
			}

			private static EntityColumnInfo GetFirstPkColumn(ExpressionItems last, EntityColumnInfo FirstPkColumn)
			{
				if (last.Nav.NavigatType == NavigateType.OneToOne && last.Nav.Name2.HasValue())
				{
					EntityColumnInfo entityColumnInfo = last.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == last.Nav.Name2);
					if (entityColumnInfo != null)
					{
						FirstPkColumn = entityColumnInfo;
					}
				}
				return FirstPkColumn;
			}

			private static string OneToMany(ref ExpressionItems formInfo, ref int i, ISugarQueryable<object> queryable, ref int index, ExpressionItems item)
			{
				string text = item.ThisEntityInfo.DbTableName + i;
				EntityColumnInfo entityColumnInfo = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name);
				EntityColumnInfo entityColumnInfo2 = item.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (item.Nav.Name2.HasValue())
				{
					entityColumnInfo2 = item.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name2);
				}
				Check.ExceptionEasy(entityColumnInfo == null, item.ThisEntityInfo.EntityName + " need PrimayKey", "使用导航属性" + item.ThisEntityInfo.EntityName + " 缺少主键");
				string joinWhere = $" {queryable.SqlBuilder.GetTranslationColumnName(text)}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName)}={queryable.SqlBuilder.GetTranslationColumnName(formInfo.ThisEntityInfo.DbTableName + (i - 1))}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo2.DbColumnName)}";
				queryable.AddJoinInfo(item.ThisEntityInfo.DbTableName, text, joinWhere, JoinType.Inner);
				i++;
				index++;
				formInfo = item;
				return text;
			}

			private static string OneToOne(ref ExpressionItems formInfo, ref int i, ISugarQueryable<object> queryable, ref int index, ExpressionItems item)
			{
				string text = item.ThisEntityInfo.DbTableName + i;
				EntityColumnInfo entityColumnInfo = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				EntityColumnInfo entityColumnInfo2 = item.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name);
				if (item.Nav.Name2.HasValue())
				{
					entityColumnInfo = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name2);
				}
				Check.ExceptionEasy(entityColumnInfo == null, item.ThisEntityInfo.EntityName + " need PrimayKey", "使用导航属性" + item.ThisEntityInfo.EntityName + " 缺少主键");
				string joinWhere = $" {text}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName)}={formInfo.ThisEntityInfo.DbTableName + (i - 1)}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo2.DbColumnName)}";
				queryable.AddJoinInfo(item.ThisEntityInfo.DbTableName, text, joinWhere, JoinType.Inner);
				i++;
				index++;
				formInfo = item;
				return text;
			}

			private string ManyToMany(ref ExpressionItems formInfo, ref int i, ISugarQueryable<object> queryable, ref int index, ExpressionItems item)
			{
				string text = item.ThisEntityInfo.DbTableName + i;
				EntityColumnInfo entityColumnInfo = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				EntityColumnInfo entityColumnInfo2 = item.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(item.Nav.MappingType);
				EntityColumnInfo entityColumnInfo3 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => item.Nav.MappingAId == it.PropertyName);
				EntityColumnInfo entityColumnInfo4 = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => item.Nav.MappingBId == it.PropertyName);
				Check.ExceptionEasy(entityColumnInfo2 == null, " " + entityColumnInfo2.EntityName + " need primary key ", entityColumnInfo2.EntityName + "需要主键");
				Check.ExceptionEasy(entityColumnInfo2 == null, " " + entityColumnInfo.EntityName + " need primary key ", entityColumnInfo.EntityName + "需要主键");
				string text2 = entityInfo.EntityName + "_1";
				string joinWhere = $" {queryable.SqlBuilder.GetTranslationColumnName(text2)}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo3.DbColumnName)}={formInfo.ThisEntityInfo.DbTableName + (i - 1)}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo2.DbColumnName)}";
				queryable.AddJoinInfo(entityInfo.DbTableName, text2, joinWhere, JoinType.Inner);
				string joinWhere2 = $" {text}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName)}={text2}.{queryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo4.DbColumnName)}";
				queryable.AddJoinInfo(entityColumnInfo.DbTableName, text, joinWhere2, JoinType.Inner);
				i++;
				index++;
				formInfo = item;
				return text;
			}

			private string GetWhereSql1(string wheresql, string lastShortName, List<ExpressionItems> joinInfos, ISqlBuilder sqlBuilder)
			{
				if (wheresql == null)
				{
					return wheresql;
				}
				joinInfos.Last().ThisEntityInfo.Columns.ForEach(delegate(EntityColumnInfo it)
				{
					if (it.DbColumnName != null)
					{
						if (whereSql.Contains("." + sqlBuilder.GetTranslationColumnName(it.DbColumnName)))
						{
							string text = "\\w+\\." + sqlBuilder.GetTranslationColumnName(it.DbColumnName).Replace(sqlBuilder.SqlTranslationLeft, "\\" + sqlBuilder.SqlTranslationLeft).Replace(sqlBuilder.SqlTranslationRight, "\\" + sqlBuilder.SqlTranslationRight)
								.Replace("\\\\", "\\");
							if (!text.IsMatch(whereSql))
							{
								text = $"\\{sqlBuilder.SqlTranslationLeft}\\w+\\{sqlBuilder.SqlTranslationRight}\\." + sqlBuilder.GetTranslationColumnName(it.DbColumnName).Replace(sqlBuilder.SqlTranslationLeft, "\\" + sqlBuilder.SqlTranslationLeft).Replace(sqlBuilder.SqlTranslationRight, "\\" + sqlBuilder.SqlTranslationRight)
									.Replace("\\\\", "\\");
							}
							whereSql = Regex.Replace(whereSql, text, sqlBuilder.GetTranslationColumnName(lastShortName) + "." + sqlBuilder.GetTranslationColumnName(it.DbColumnName));
						}
						else
						{
							string text2 = whereSql;
							string text3 = whereSql.Replace(sqlBuilder.GetTranslationColumnName(it.DbColumnName), sqlBuilder.GetTranslationColumnName(lastShortName) + "." + sqlBuilder.GetTranslationColumnName(it.DbColumnName));
							if (!(text2 != text3) || text2.Contains(" " + sqlBuilder.GetTranslationColumnName(it.DbColumnName)))
							{
								whereSql = text3;
							}
						}
					}
				});
				return whereSql;
			}

