		internal class OneToOneNavgateExpression
		{
			public ExpressionContext ExpContext;

			private SqlSugarProvider context;

			internal EntityInfo EntityInfo;

			internal EntityInfo ProPertyEntity;

			private Navigate Navigat;

			public string ShorName;

			internal string MemberName;

			private MemberExpressionResolve _memberExpressionResolve;

			public OneToOneNavgateExpression(SqlSugarProvider context, MemberExpressionResolve memberExpressionResolve)
			{
				this.context = context;
				_memberExpressionResolve = memberExpressionResolve;
			}

			internal bool IsNavgate(Expression expression)
			{
				bool result = false;
				Expression expression2 = expression;
				if (expression2 is UnaryExpression)
				{
					expression2 = (expression2 as UnaryExpression).Operand;
				}
				if (expression2 is MemberExpression)
				{
					MemberExpression memberExpression = expression2 as MemberExpression;
					Expression expression3 = memberExpression.Expression;
					result = ValidateNav(result, memberExpression, expression3);
				}
				return result;
			}

			private bool ValidateNav(bool result, MemberExpression memberExp, Expression childExpression)
			{
				if (childExpression != null && childExpression is MemberExpression)
				{
					Expression expression = (childExpression as MemberExpression).Expression;
					if (expression == null)
					{
						return false;
					}
					if (expression.Type.IsClass() && expression is ParameterExpression)
					{
						EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type);
						if (entityInfo.Columns.Any((EntityColumnInfo x) => x.PropertyName == (childExpression as MemberExpression).Member.Name && x.Navigat != null))
						{
							EntityInfo = entityInfo;
							ShorName = expression.ToString();
							MemberName = memberExp.Member.Name;
							ProPertyEntity = context.EntityMaintenance.GetEntityInfo(childExpression.Type);
							Navigat = entityInfo.Columns.FirstOrDefault((EntityColumnInfo x) => x.PropertyName == (childExpression as MemberExpression).Member.Name).Navigat;
							result = true;
						}
					}
				}
				return result;
