			internal MapperSql GetSql()
			{
				if (ProPertyEntity.Type.Name.StartsWith("List`"))
				{
					Check.ExceptionEasy(isException: true, " expression error ", "导航查询出错，比如.Count要改成 .Count()");
				}
				else if (Navigat.NavigatType == NavigateType.Dynamic)
				{
					return NavigatDynamicSql();
				}
				string text = ProPertyEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey)?.DbColumnName;
				if (Navigat.Name2.HasValue())
				{
					text = ProPertyEntity.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == Navigat.Name2)?.DbColumnName;
				}
				if (text == null)
				{
					Check.ExceptionEasy(isException: true, ProPertyEntity.EntityName + " naviate config error", ProPertyEntity.EntityName + " 导航配置错误");
				}
				string dbColumnName = EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == Navigat.Name).DbColumnName;
				string dbColumnName2 = ProPertyEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == MemberName).DbColumnName;
				MapperSql mapperSql = new MapperSql();
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>();
				text = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(text);
				dbColumnName = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName);
				dbColumnName2 = sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(dbColumnName2);
				string text2 = ProPertyEntity.DbTableName;
				ExpressionContext expContext = ExpContext;
				if (expContext != null && expContext.SugarContext?.QueryBuilder?.IsCrossQueryWithAttr == true)
				{
					TenantAttribute customAttribute = ProPertyEntity.Type.GetCustomAttribute<TenantAttribute>();
					string text3 = context.CurrentConnectionConfig.ConfigId.ObjToString();
					if (customAttribute != null && text3 != customAttribute.configId.ObjToString())
					{
						SqlSugarProvider connection = context.Root.GetConnection(customAttribute.configId);
						string database = connection.Ado.Connection.Database;
						text2 = ((!connection.CurrentConnectionConfig.DbLinkName.HasValue()) ? sugarQueryable.QueryBuilder.LambdaExpressions.DbMehtods.GetTableWithDataBase(sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(database), sugarQueryable.QueryBuilder.Builder.GetTranslationColumnName(text2)) : UtilMethods.GetTableByDbLink(connection, text2, text2, customAttribute));
					}
				}
				Type[] types = null;
				bool flag = false;
				if (_memberExpressionResolve?.Context?.SugarContext?.QueryBuilder != null)
				{
					sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500 + _memberExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex;
					_memberExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex++;
					flag = _memberExpressionResolve.Context.SugarContext.QueryBuilder.IsDisabledGobalFilter;
					types = _memberExpressionResolve.Context.SugarContext.QueryBuilder.RemoveFilters;
				}
				Type type = ((ProPertyEntity.Columns.Count((EntityColumnInfo it) => it.IsPrimarykey) > 1) ? ProPertyEntity.Type : null);
				if (flag)
				{
					type = null;
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarQueryable.AS(text2).ClearFilter(types).Filter(type)
					.WhereIF(Navigat.WhereSql.HasValue(), Navigat.WhereSql)
					.Where($" {sugarQueryable.SqlBuilder.GetTranslationColumnName(ShorName)}.{dbColumnName}={text} ")
					.Select(dbColumnName2)
					.ToSql();
				mapperSql.Sql = keyValuePair.Key;
				mapperSql.Sql = " (" + mapperSql.Sql + ") ";
				if ((type != null) & (keyValuePair.Value?.Any() ?? false))
				{
					foreach (SugarParameter item in keyValuePair.Value)
					{
						if (!_memberExpressionResolve.Context.Parameters.Any((SugarParameter it) => it.ParameterName == item.ParameterName))
						{
							_memberExpressionResolve.Context.Parameters.Add(item);
						}
					}
				}
				return mapperSql;
			}

			private MapperSql NavigatDynamicSql()
			{
				if (Navigat.Name == null)
				{
					Check.ExceptionEasy(isException: true, " NavigateType.Dynamic User-defined navigation objects need to be configured with json to be used in expressions .  " + ProPertyEntity.Type.Name, " NavigateType.Dynamic 自定义导航对象需要配置json才能在表达式中使用。 " + ProPertyEntity.Type.Name);
				}
				new MapperSql();
				string dbColumnName = ProPertyEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == MemberName).DbColumnName;
				MapperSql mapperSql = new MapperSql();
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>();
				string dbTableName = ProPertyEntity.DbTableName;
				Type[] types = null;
				bool flag = false;
				if (_memberExpressionResolve?.Context?.SugarContext?.QueryBuilder != null)
				{
					sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = 500 + _memberExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex;
					_memberExpressionResolve.Context.SugarContext.QueryBuilder.LambdaExpressions.ParameterIndex++;
					flag = _memberExpressionResolve.Context.SugarContext.QueryBuilder.IsDisabledGobalFilter;
					types = _memberExpressionResolve.Context.SugarContext.QueryBuilder.RemoveFilters;
				}
				Type type = ((ProPertyEntity.Columns.Count((EntityColumnInfo it) => it.IsPrimarykey) > 1) ? ProPertyEntity.Type : null);
				if (flag)
				{
					type = null;
				}
				sugarQueryable.AS(dbTableName).Take(1).ClearFilter(types)
					.Filter(type)
					.WhereIF(Navigat.WhereSql.HasValue(), Navigat.WhereSql)
					.Select(dbColumnName);
				foreach (JToken item in JArray.Parse(Navigat.Name))
				{
					string m = ((object)item[(object)"m"])?.ToString() ?? "";
					string c = ((object)item[(object)"c"])?.ToString() ?? "";
					string dbColumnName2 = EntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == m).DbColumnName;
					string dbColumnName3 = ProPertyEntity.Columns.First((EntityColumnInfo it) => it.PropertyName == c).DbColumnName;
					sugarQueryable.Where($" {sugarQueryable.SqlBuilder.GetTranslationColumnName(ShorName)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(dbColumnName2)}={sugarQueryable.SqlBuilder.GetTranslationColumnName(dbColumnName3)} ");
				}
				mapperSql.Sql = sugarQueryable.ToSql().Key;
				mapperSql.Sql = " (" + mapperSql.Sql + ") ";
				return mapperSql;
			}
		}
		internal class OneToOneNavgateExpressionN
		{
			public EntityInfo entityInfo;

			public List<ExpressionItems> items;

			public SqlSugarProvider context;

			public ISqlBuilder builder;

			public string shorName { get; set; }

			public OneToOneNavgateExpressionN(SqlSugarProvider context)
			{
				this.context = context;
			}

			public bool IsNavgate(Expression expression)
			{
				if (context == null)
				{
					return false;
				}
				bool result = false;
				Expression expression2 = expression;
				if (expression2 is UnaryExpression)
				{
					expression2 = (expression2 as UnaryExpression).Operand;
				}
				if (expression2 is MemberExpression)
				{
					MemberExpression memberExpression = expression2 as MemberExpression;
					Expression expression3 = memberExpression.Expression;
					result = ValidateIsJoinMember(result, memberExpression, expression3);
				}
				return result;
			}

			public MapperSql GetMemberSql()
			{
				MapperSql mapperSql = new MapperSql();
				ExpressionItems expressionItems = items.Where((ExpressionItems it) => it.Type == 1).First();
				List<ExpressionItems> source = items.Where((ExpressionItems it) => it.Type == 2).Reverse().ToList();
				ExpressionItems expressionItems2 = source.First();
				string text = expressionItems2?.Nav?.WhereSql;
				List<ExpressionItems> list = source.Skip(1).ToList();
				int num = 0;
				string name = expressionItems2.ThisEntityInfo.DbTableName + num;
				ISugarQueryable<object> sugarQueryable = context.Queryable<object>(ToShortName(name)).AS(expressionItems2.ThisEntityInfo.DbTableName).Filter(null, isDisabledGobalFilter: true);
				builder = sugarQueryable.SqlBuilder;
				num++;
				string name2 = "";
				foreach (ExpressionItems item in list)
				{
					string text2 = item.ThisEntityInfo.DbTableName + num;
					EntityColumnInfo entityColumnInfo = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
					if (item.Nav.Name2.HasValue())
					{
						EntityColumnInfo entityColumnInfo2 = item.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name2);
						if (entityColumnInfo2 != null)
						{
							entityColumnInfo = entityColumnInfo2;
						}
					}
					EntityColumnInfo entityColumnInfo3 = item.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == item.Nav.Name);
					Check.ExceptionEasy(entityColumnInfo == null, item.ThisEntityInfo.EntityName + " need PrimayKey", "使用导航属性" + item.ThisEntityInfo.EntityName + " 缺少主键");
					string text3 = $" {ToShortName(text2)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo.DbColumnName)}={ToShortName(expressionItems2.ThisEntityInfo.DbTableName + (num - 1))}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo3.DbColumnName)}";
					if (item.Nav.WhereSql.HasValue())
					{
						text3 = text3 + " AND " + item.Nav.WhereSql;
					}
					sugarQueryable.AddJoinInfo(item.ThisEntityInfo.DbTableName, ToShortName(text2), text3, JoinType.Inner);
					num++;
					name2 = text2;
					expressionItems2 = item;
				}
				string selectProperyInfo = ExpressionTool.GetMemberName(expressionItems.Expression);
				EntityColumnInfo entityColumnInfo4 = expressionItems.ParentEntityInfo.Columns.First((EntityColumnInfo it) => it.PropertyName == selectProperyInfo);
				if (text != null && text.HasValue())
				{
					sugarQueryable.Where(text);
				}
				sugarQueryable.Select(" " + ToShortName(name2) + "." + sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo4.DbColumnName));
				ExpressionItems last = source.First();
				EntityColumnInfo entityColumnInfo5 = last.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsPrimarykey);
				if (last.Nav.Name2.HasValue())
				{
					EntityColumnInfo entityColumnInfo6 = last.ThisEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == last.Nav.Name2);
					if (entityColumnInfo6 != null)
					{
						entityColumnInfo5 = entityColumnInfo6;
					}
				}
				Check.ExceptionEasy(entityColumnInfo5 == null, last.ThisEntityInfo.EntityName + " need PrimayKey", "使用导航属性" + last.ThisEntityInfo.EntityName + " 缺少主键");
				EntityColumnInfo entityColumnInfo7 = last.ParentEntityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == last.Nav.Name);
				Check.ExceptionEasy(entityColumnInfo7 == null, last.ParentEntityInfo.EntityName + " no found " + last.Nav.Name, last.ParentEntityInfo.EntityName + " 不存在 " + last.Nav.Name);
				sugarQueryable.Where($" {ToShortName(shorName)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo7.DbColumnName)} = {ToShortName(name)}.{sugarQueryable.SqlBuilder.GetTranslationColumnName(entityColumnInfo5.DbColumnName)} ");
				mapperSql.Sql = "( " + sugarQueryable.ToSql().Key + " ) ";
				return mapperSql;
			}

			private bool ValidateIsJoinMember(bool result, MemberExpression memberExp, Expression childExpression)
			{
				if (childExpression != null && childExpression is MemberExpression)
				{
					Expression expression = (childExpression as MemberExpression).Expression;
					if (expression == null || expression is ConstantExpression)
					{
						return false;
					}
					items = new List<ExpressionItems>();
					items.Add(new ExpressionItems
					{
						Type = 1,
						Expression = memberExp,
						ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(childExpression.Type)
					});
					items.Add(new ExpressionItems
					{
						Type = 2,
						Expression = childExpression,
						ThisEntityInfo = context.EntityMaintenance.GetEntityInfo(childExpression.Type),
						ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type)
					});
					if (items.Any((ExpressionItems it) => it.Type == 2 && it.Nav == null))
					{
						return false;
					}
					while (expression != null)
					{
						if (IsClass(expression))
						{
							items.Add(new ExpressionItems
							{
								Type = 2,
								Expression = expression,
								ThisEntityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type),
								ParentEntityInfo = context.EntityMaintenance.GetEntityInfo(GetMemberExpression(expression).Type)
							});
							expression = GetMemberExpression(expression);
							continue;
						}
						if (IsParameter(expression))
						{
							shorName = expression.ToString();
							entityInfo = context.EntityMaintenance.GetEntityInfo(expression.Type);
						}
						break;
					}
					if (!items.Any((ExpressionItems it) => it.Type == 2 && it.Nav == null))
					{
						return true;
					}
				}
				return result;
			}

			private string ToShortName(string name)
			{
				if (name.ObjToString().Contains("."))
				{
					if (context != null)
					{
						ISqlBuilder sqlBuilder = context.Queryable<object>().SqlBuilder;
						return sqlBuilder.SqlTranslationLeft + name.Replace(".", "_") + sqlBuilder.SqlTranslationRight;
					}
					name.Replace(".", "_");
				}
				if (builder == null)
				{
					return name;
				}
				return builder.GetTranslationColumnName(name);
			}

			private static bool IsParameter(Expression child2Expression)
			{
				if (child2Expression.Type.IsClass())
				{
					return child2Expression is ParameterExpression;
				}
				return false;
			}

			private static Expression GetMemberExpression(Expression child2Expression)
			{
				return (child2Expression as MemberExpression).Expression;
			}

			private static bool IsClass(Expression child2Expression)
			{
				if (child2Expression.Type.IsClass())
				{
					return child2Expression is MemberExpression;
				}
				return false;
			}
		}
		public class TypeParameterExpressionReolve : BaseResolve
		{
			public TypeParameterExpressionReolve(ExpressionParameter parameter)
				: base(parameter)
			{
				ParameterExpression parameterExpression = (ParameterExpression)base.Expression;
				switch (parameter.Context.ResolveType)
				{
				case ResolveExpressType.Update:
					parameter.BaseParameter.CommonTempData = parameterExpression.Name;
					break;
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
					if (parameter.BaseParameter != null && parameter.BaseParameter.CurrentExpression.NodeType == ExpressionType.Lambda)
					{
						base.Context.Result.Append(base.Context.GetTranslationColumnName(parameterExpression.Name) + ".*");
					}
					else
					{
						parameter.BaseParameter.CommonTempData = parameterExpression.Name;
					}
					break;
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
				case ResolveExpressType.FieldSingle:
				case (ResolveExpressType)6:
				case ResolveExpressType.FieldMultiple:
				case ResolveExpressType.Join:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
					break;
				}
			}
		}
		public class UnaryExpressionResolve : BaseResolve
		{
			public UnaryExpressionResolve(ExpressionParameter parameter)
				: base(parameter)
			{
				Expression expression = base.Expression;
				UnaryExpression unaryExpression = base.Expression as UnaryExpression;
				ExpressionParameter baseParameter = parameter.BaseParameter;
				switch (base.Context.ResolveType)
				{
				case ResolveExpressType.WhereSingle:
				case ResolveExpressType.WhereMultiple:
				case ResolveExpressType.SelectSingle:
				case ResolveExpressType.SelectMultiple:
				case ResolveExpressType.FieldSingle:
				case ResolveExpressType.FieldMultiple:
				case ResolveExpressType.ArraySingle:
				case ResolveExpressType.ArrayMultiple:
				case ResolveExpressType.Update:
				{
					ExpressionType nodeType = unaryExpression.NodeType;
					base.Expression = unaryExpression.Operand;
					bool flag = unaryExpression.Operand is MemberExpression;
					bool flag2 = unaryExpression.Operand is ConstantExpression;
					bool flag3 = parameter.OppsiteExpression is ConstantExpression && (parameter.OppsiteExpression as ConstantExpression).Value == null && ExpressionTool.IsComparisonOperator(unaryExpression.Operand);
					if (flag & flag3)
					{
						Append(parameter, nodeType);
					}
					else if (baseParameter.CurrentExpression is NewArrayExpression)
					{
						Result(parameter, nodeType);
					}
					else if (baseParameter.OperatorValue == "=" && BaseResolve.IsNotMember(expression))
					{
						AppendNotMember(parameter, nodeType);
					}
					else if (baseParameter.OperatorValue == "=" && BaseResolve.IsNotParameter(expression))
					{
						AppendNotParameter(parameter, nodeType);
					}
					else if (base.Expression is BinaryExpression || parameter.BaseExpression is BinaryExpression || baseParameter.CommonTempData.ObjToString() == CommonTempDataType.Append.ToString())
					{
						Append(parameter, nodeType);
					}
					else if (flag)
					{
						MemberLogic(parameter, baseParameter, nodeType);
					}
					else if (flag2)
					{
						Result(parameter, nodeType);
					}
					else
					{
						Append(parameter, nodeType);
					}
					break;
				}
				case (ResolveExpressType)6:
				case ResolveExpressType.Join:
					break;
				}
			}

			private void MemberLogic(ExpressionParameter parameter, ExpressionParameter baseParameter, ExpressionType nodeType)
			{
				MemberExpression memberExpression = base.Expression as MemberExpression;
				bool flag = ExpressionTool.IsLogicOperator(baseParameter.OperatorValue) || baseParameter.OperatorValue.IsNullOrEmpty();
				if (flag && memberExpression.Member.Name == "HasValue" && memberExpression.Expression != null && memberExpression.NodeType == ExpressionType.MemberAccess)
				{
					MemberExpression memberExpression2 = memberExpression.Expression as MemberExpression;
					parameter.CommonTempData = CommonTempDataType.Result;
					bool flag2 = memberExpression2.Expression != null && memberExpression2.Expression is ConstantExpression;
					if (flag2)
					{
						object obj = ExpressionTool.DynamicInvoke(memberExpression2);
						string memberName = AppendParameter(obj);
						string parameter2 = base.Context.DbMehtods.HasValue(new MethodCallExpressionModel
						{
							Args = new List<MethodCallExpressionArgs>
							{
								new MethodCallExpressionArgs
								{
									IsMember = false,
									MemberName = memberName,
									MemberValue = obj
								}
							}
						});
						base.Context.Result.Append(parameter2);
						return;
					}
					base.Expression = (flag2 ? memberExpression2.Expression : memberExpression2);
					Start();
					MethodCallExpressionArgs item = (flag2 ? new MethodCallExpressionArgs
					{
						IsMember = false
					} : new MethodCallExpressionArgs
					{
						IsMember = true,
						MemberName = parameter.CommonTempData,
						MemberValue = null
					});
					string text = base.Context.DbMehtods.HasValue(new MethodCallExpressionModel
					{
						Args = new List<MethodCallExpressionArgs> { item }
					});
					if (nodeType == ExpressionType.Not && memberExpression.Member.Name == "HasValue")
					{
						base.Context.Result.Append("NOT" + text);
					}
					else
					{
						base.Context.Result.Append(text);
					}
					parameter.CommonTempData = null;
				}
				else if ((memberExpression.Type == UtilConstants.BoolType) & flag)
				{
					Append(parameter, nodeType);
				}
				else
				{
					Result(parameter, nodeType);
				}
			}

			private void Result(ExpressionParameter parameter, ExpressionType nodeType)
			{
				base.BaseParameter.ChildExpression = base.Expression;
				parameter.CommonTempData = CommonTempDataType.Result;
				if (nodeType == ExpressionType.Not)
				{
					AppendNot(parameter.CommonTempData);
				}
				Start();
				parameter.BaseParameter.CommonTempData = parameter.CommonTempData;
				if (nodeType == ExpressionType.Negate && parameter.BaseParameter.CommonTempData is int)
				{
					parameter.BaseParameter.CommonTempData = Convert.ToInt32(parameter.BaseParameter.CommonTempData) * -1;
				}
				parameter.BaseParameter.ChildExpression = base.Expression;
				parameter.CommonTempData = null;
			}

			private void Append(ExpressionParameter parameter, ExpressionType nodeType)
			{
				base.BaseParameter.ChildExpression = base.Expression;
				base.IsLeft = parameter.IsLeft;
				parameter.CommonTempData = CommonTempDataType.Append;
				if (nodeType == ExpressionType.Not)
				{
					AppendNot(parameter.CommonTempData);
				}
				if (nodeType == ExpressionType.Negate)
				{
					AppendNegate(parameter.CommonTempData);
				}
				Start();
				parameter.BaseParameter.CommonTempData = parameter.CommonTempData;
				parameter.BaseParameter.ChildExpression = base.Expression;
				parameter.CommonTempData = null;
			}

			private void AppendNotMember(ExpressionParameter parameter, ExpressionType nodeType)
			{
				base.BaseParameter.ChildExpression = base.Expression;
				base.IsLeft = parameter.IsLeft;
				parameter.CommonTempData = CommonTempDataType.Result;
				Start();
				string parameter2 = base.Context.DbMehtods.IIF(new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs>
					{
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = parameter.CommonTempData.ObjToString() + "=1",
							Type = UtilConstants.BoolType
						},
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = AppendParameter(0)
						},
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = AppendParameter(1)
						}
					}
				});
				base.Context.Result.Append(parameter2);
				parameter.BaseParameter.ChildExpression = base.Expression;
				parameter.CommonTempData = null;
			}

			private void AppendNotParameter(ExpressionParameter parameter, ExpressionType nodeType)
			{
				base.BaseParameter.ChildExpression = base.Expression;
				base.IsLeft = parameter.IsLeft;
				parameter.CommonTempData = CommonTempDataType.Result;
				Start();
				string parameter2 = base.Context.DbMehtods.IIF(new MethodCallExpressionModel
				{
					Args = new List<MethodCallExpressionArgs>
					{
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = AppendParameter(parameter.CommonTempData) + "=1"
						},
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = AppendParameter(0)
						},
						new MethodCallExpressionArgs
						{
							IsMember = true,
							MemberName = AppendParameter(1)
						}
					}
				});
				base.Context.Result.Append(parameter2);
				parameter.BaseParameter.ChildExpression = base.Expression;
				parameter.CommonTempData = null;
			}
