			public string GetValue(Expression expression)
			{
				string text = "";
				if (Context.SugarContext != null)
				{
					SqlSugarProvider context = Context.SugarContext.Context;
					BindingFlags bindingAttr = BindingFlags.Instance | BindingFlags.NonPublic;
					Type subTableType = Context.SubTableType;
					bool flag = HasWhere;
					if (context.QueryFilter.GetFilterList != null)
					{
						foreach (SqlFilterItem getFilter in context.QueryFilter.GetFilterList)
						{
							PropertyInfo property = getFilter.GetType().GetProperty("exp", bindingAttr);
							if (!(property != null))
							{
								continue;
							}
							Type type = getFilter.GetType().GetProperty("type", bindingAttr).GetValue(getFilter, null) as Type;
							if (type == subTableType || (type.IsInterface && Enumerable.Contains(subTableType.GetInterfaces(), type)))
							{
								context.EntityMaintenance.GetEntityInfo(type);
								Context.InitMappingInfo(type);
								Expression item = property.GetValue(getFilter, null) as Expression;
								string text2 = (flag ? " AND " : " WHERE ");
								flag = true;
								text = text + text2 + SubTools.GetMethodValue(Context, item, ResolveExpressType.WhereSingle);
								if (type.IsInterface && Context?.SugarContext?.QueryBuilder != null)
								{
									text = Context.SugarContext?.QueryBuilder.ReplaceFilterColumnName(text, subTableType);
								}
							}
						}
					}
				}
