		public class SubFirst : ISubOperation
		{
			public bool HasWhere { get; set; }

			public string Name => "First";

			public Expression Expression { get; set; }

			public int Sort => 200;

			public ExpressionContext Context { get; set; }

			public string GetValue(Expression expression = null)
			{
				MethodCallExpression methodCallExpression = expression as MethodCallExpression;
				if (IsAutoGeneric(methodCallExpression))
				{
					return GetValueByAuto(methodCallExpression);
				}
				if (IsAutoSelect(methodCallExpression))
				{
					return GetValueByAuto(methodCallExpression);
				}
				InitType(methodCallExpression);
				Type type = expression.Type;
				if (type.FullName.IsCollectionsList() && methodCallExpression.Arguments.Count == 0 && type.GenericTypeArguments.Length != 0 && Context.SugarContext != null && Context.SugarContext.QueryBuilder.IsSelectNoAll)
				{
					Type type2 = type.GenericTypeArguments[0];
					List<EntityColumnInfo> columns = Context.SugarContext.Context.EntityMaintenance.GetEntityInfo(type2).Columns;
					return string.Join(",", from it in columns
						where !it.IsIgnore
						where it.DbColumnName.HasValue()
						select Context.GetTranslationColumnName(it.DbColumnName)) + ",@sugarIndex as sugarIndex";
				}
				if (methodCallExpression.Arguments.Count == 0)
				{
					return "*,@sugarIndex as sugarIndex";
				}
				Expression expression2 = methodCallExpression.Arguments[0];
				_ = (expression2 as LambdaExpression).Parameters;
				if ((expression2 as LambdaExpression).Body is UnaryExpression)
				{
					expression2 = ((expression2 as LambdaExpression).Body as UnaryExpression).Operand;
				}
				LambdaExpression expression3 = expression2 as LambdaExpression;
				ExpressionContext copyContextWithMapping = Context.GetCopyContextWithMapping();
				copyContextWithMapping.Resolve(expression3, ResolveExpressType.SelectMultiple);
				string text = copyContextWithMapping.Result.GetString();
				Context.Parameters.AddRange(copyContextWithMapping.Parameters);
				Context.Index = copyContextWithMapping.Index;
				Context.ParameterIndex = copyContextWithMapping.ParameterIndex;
				SetShortName(methodCallExpression, null);
				return text + ",@sugarIndex as sugarIndex";
			}

			private void InitType(MethodCallExpression exp)
			{
				if (exp.Arguments.Count <= 0)
				{
					return;
				}
				foreach (ParameterExpression parameter in (exp.Arguments[0] as LambdaExpression).Parameters)
				{
					if (Context.InitMappingInfo != null)
					{
						Context.InitMappingInfo(parameter.Type);
						Context.RefreshMapping();
					}
				}
			}

			public void SetShortName(MethodCallExpression exp, string result)
			{
				if (exp.Arguments.Any() && exp.Arguments[0] is LambdaExpression)
				{
					ReadOnlyCollection<ParameterExpression> parameters = (exp.Arguments[0] as LambdaExpression).Parameters;
					if (parameters != null && parameters.Count > 0)
					{
						Context.CurrentShortName = Context.GetTranslationColumnName(parameters[0].ObjToString());
					}
				}
			}

			public void SetShortNameNext(MethodCallExpression exp, string result)
			{
				if (exp.Arguments.Count > 1 && exp.Arguments[1] is LambdaExpression)
				{
					ReadOnlyCollection<ParameterExpression> parameters = (exp.Arguments[1] as LambdaExpression).Parameters;
					if (parameters != null && parameters.Count > 0)
					{
						Context.CurrentShortName = Context.GetTranslationColumnName(parameters[0].ObjToString());
					}
				}
			}

			private string GetValueByAuto(MethodCallExpression exp)
			{
				Expression expression = exp.Arguments.FirstOrDefault();
				if (expression == null)
				{
					Type type = exp.Type;
					ParameterExpression parameterExpression = System.Linq.Expressions.Expression.Parameter(type, "it");
					expression = System.Linq.Expressions.Expression.Lambda(System.Linq.Expressions.Expression.MemberInit(System.Linq.Expressions.Expression.New(type)), parameterExpression);
				}
				Expression lambdaExpressionBody = ExpressionTool.GetLambdaExpressionBody(expression);
				MemberInitExpression memberInitExpression = lambdaExpressionBody as MemberInitExpression;
				List<ParameterExpression> parameters = ExpressionTool.GetParameters(exp);
				InitType(exp);
				if (parameters.Any())
				{
					Context.CurrentShortName = Context.GetTranslationColumnName(parameters.FirstOrDefault().Name);
				}
				Check.ExceptionEasy(memberInitExpression == null, "Subquery ToList(exp,true) expression " + exp.ToString() + " can only be it=>new class(){Id = it.id}", "子查询ToList(exp,true)表达式" + exp.ToString() + "只能是it=>new class(){ id=it.Id}");
				Dictionary<string, Expression> dic = ExpressionTool.GetMemberBindingItemList(memberInitExpression.Bindings);
				SqlSugarProvider context = Context.SugarContext.Context;
				ISqlBuilder builder = Context.SugarContext.QueryBuilder.Builder;
				List<EntityColumnInfo> list = (from it in context.EntityMaintenance.GetEntityInfo(lambdaExpressionBody.Type).Columns
					where !dic.ContainsKey(it.PropertyName)
					where !it.IsIgnore
					select it).ToList();
				List<string> list2 = new List<string>();
				List<string> list3 = new List<string>();
				foreach (EntityColumnInfo item in list)
				{
					foreach (ParameterExpression item2 in parameters)
					{
						List<EntityColumnInfo> columns = context.EntityMaintenance.GetEntityInfo(item2.Type).Columns;
						if (!list3.Any((string it) => it.EqualCase(item.PropertyName)) && columns.Any((EntityColumnInfo it) => it.PropertyName.EqualCase(item.PropertyName)))
						{
							EntityColumnInfo entityColumnInfo = columns.First((EntityColumnInfo it) => it.PropertyName == item.PropertyName);
							string translationColumnName = builder.GetTranslationColumnName(item2.Name);
							string translationColumnName2 = builder.GetTranslationColumnName(entityColumnInfo.DbColumnName);
							string value = builder.SqlTranslationLeft + item.PropertyName + builder.SqlTranslationRight;
							list2.Add($"{translationColumnName}.{translationColumnName2} as {value}");
							list3.Add(entityColumnInfo.PropertyName);
						}
					}
				}
				ExpressionContext copyContextWithMapping = Context.GetCopyContextWithMapping();
				copyContextWithMapping.Resolve(lambdaExpressionBody, ResolveExpressType.SelectMultiple);
				string text = copyContextWithMapping.Result.GetString();
				if (dic.Count > 0 && list2.Count == 0)
				{
					return text + ",@sugarIndex as sugarIndex";
				}
				if (dic.Count > 0 && list2.Count > 0)
				{
					return text + "," + string.Join(",", list2) + ",@sugarIndex as sugarIndex";
				}
				return string.Join(",", list2) + ",@sugarIndex as sugarIndex";
			}

			private static bool IsAutoSelect(MethodCallExpression exp)
			{
				if (exp.Arguments.Count == 2)
				{
					return exp.Arguments.Last().Type == UtilConstants.BoolType;
				}
				return false;
			}

			private static bool IsAutoGeneric(MethodCallExpression exp)
			{
				if (exp.Arguments.Count == 0)
				{
					return exp.Method.GetGenericArguments().Count() == 1;
				}
				return false;
			}
		}
