		public class SubInnerJoin : ISubOperation
		{
			public bool HasWhere { get; set; }

			public string Name => "InnerJoin";

			public Expression Expression { get; set; }

			public int Sort => 302;

			public ExpressionContext Context { get; set; }

			public string GetValue(Expression expression)
			{
				MethodCallExpression methodCallExpression = expression as MethodCallExpression;
				Expression expression2 = methodCallExpression.Arguments[0];
				Context.GetTranslationColumnName((expression2 as LambdaExpression).Parameters[0].Name);
				ParameterExpression parameterExpression = (expression2 as LambdaExpression).Parameters.Last();
				foreach (ParameterExpression parameter in (expression2 as LambdaExpression).Parameters)
				{
					Context.InitMappingInfo(parameter.Type);
				}
				Context.RefreshMapping();
				string text = Context.GetTranslationTableName(parameterExpression.Type.Name);
				if (Context.IsAsAttr)
				{
					SqlSugarProvider context = Context.SugarContext.Context;
					EntityInfo entityInfo = context.EntityMaintenance.GetEntityInfo(parameterExpression.Type);
					text = ((QueryableProvider<object>)context.Queryable<object>()).GetTableName(entityInfo, text);
				}
				if (methodCallExpression.Arguments.Count == 2 && methodCallExpression.Arguments.Last().HasValue())
				{
					text = Context.GetTranslationTableName(ExpressionTool.DynamicInvoke(methodCallExpression.Arguments.Last())?.ToString() ?? "");
				}
				string text2 = string.Format(" {2} INNER JOIN {1} {0} ", Context.GetTranslationColumnName(parameterExpression.Name), text, null);
				ExpressionContext context2 = Context;
				if (context2 != null && context2.SugarContext?.Context?.CurrentConnectionConfig?.DbType == DbType.SqlServer)
				{
					ExpressionContext context3 = Context;
					if (context3 != null && context3.SugarContext?.Context?.CurrentConnectionConfig?.MoreSettings?.IsWithNoLockSubquery == true)
					{
						text2 += " WITH(NOLOCK)  ";
					}
				}
				string result = text2 + "ON " + SubTools.GetMethodValue(Context, expression2, ResolveExpressType.WhereMultiple);
