		public class SubWhere : ISubOperation
		{
			public bool HasWhere { get; set; }

			public string Name => "Where";

			public Expression Expression { get; set; }

			public int Sort => 400;

			public ExpressionContext Context { get; set; }

			public string GetValue(Expression expression)
			{
				MethodCallExpression methodCallExpression = expression as MethodCallExpression;
				if (Regex.Matches(expression.ToString(), "Subqueryable").Count >= 2)
				{
					SubSelect subSelect = new SubSelect();
					subSelect.Context = Context;
					subSelect.SetShortName(methodCallExpression, "+");
				}
				Expression expression2 = methodCallExpression.Arguments[0];
				if (ExpressionTool.GetMethodName(expression2) == "ToExpression")
				{
					expression2 = ExpressionTool.DynamicInvoke(expression2) as Expression;
				}
				ExpressionContext expressionContext = Context;
				IEnumerable<ParameterExpression> source = ExpressionTool.GetParameters(expression).Distinct();
				if (Context.JoinIndex > 0 || source.Count() > 1)
				{
					expressionContext = Context.GetCopyContextWithMapping();
					expressionContext.IsSingle = false;
				}
				string result = "WHERE " + SubTools.GetMethodValue(expressionContext, expression2, ResolveExpressType.WhereMultiple);
				if (expression2.Type == typeof(List<IConditionalModel>) && Context.Parameters.Any())
				{
					SugarParameter sugarParameter = Context.Parameters.Last();
					Context.Parameters.Remove(sugarParameter);
					List<IConditionalModel> models = sugarParameter.Value as List<IConditionalModel>;
					KeyValuePair<string, SugarParameter[]> keyValuePair = Context.SugarContext.QueryBuilder.Builder.ConditionalModelToSql(models, Context.ParameterIndex * 100);
					Context.ParameterIndex += Context.ParameterIndex * 100;
					result = "WHERE " + keyValuePair.Key;
					Context.Parameters.AddRange(keyValuePair.Value);
					return result;
				}
				if (expression2.Type == typeof(List<IConditionalModel>) && !Context.Parameters.Any())
				{
					List<IConditionalModel> models2 = ExpressionTool.DynamicInvoke((expression as MethodCallExpression).Arguments[0]) as List<IConditionalModel>;
					KeyValuePair<string, SugarParameter[]> keyValuePair2 = Context.SugarContext.QueryBuilder.Builder.ConditionalModelToSql(models2, Context.ParameterIndex * 100);
					Context.ParameterIndex += Context.ParameterIndex * 100;
					result = "WHERE " + keyValuePair2.Key;
					Context.Parameters.AddRange(keyValuePair2.Value);
					return result;
				}
				if (Context.JoinIndex > 0 || source.Count() > 1)
				{
					Context.Parameters.AddRange(expressionContext.Parameters);
					Context.Index = expressionContext.Index;
					Context.ParameterIndex = expressionContext.ParameterIndex;
				}
				string regex = "^WHERE  (\\@Const\\d+) $";
				if (Context is OracleExpressionContext)
				{
					regex = "^WHERE  (\\:Const\\d+) $";
				}
				if (Regex.IsMatch(result, regex))
				{
					object value = GetValue(result, regex);
					if (!(value is Expression))
					{
						result = "WHERE " + value;
						return result;
					}
					SugarParameter item = Context.Parameters.First((SugarParameter it) => it.ParameterName == Regex.Match(result, regex).Groups[1].Value);
					result = "WHERE " + SubTools.GetMethodValue(Context, value as Expression, ResolveExpressType.WhereMultiple);
					expression2 = value as Expression;
					Context.Parameters.Remove(item);
				}
				string text = Context.GetTranslationColumnName((expression2 as LambdaExpression).Parameters.First().Name) + ".";
				if (Context.JoinIndex == 0 && result.Contains(" FROM "))
				{
					Context.CurrentShortName = text.ObjToString().TrimEnd('.');
				}
				else if (Context.JoinIndex == 0 && Context.CurrentShortName != text.TrimEnd('.'))
				{
					result = result.Replace(text, SubTools.GetSubReplace(Context));
				}
				if (!string.IsNullOrEmpty(text) && Context.IsSingle && Context.JoinIndex == 0)
				{
					Context.CurrentShortName = text.TrimEnd('.');
				}
				return result;
			}

			private object GetValue(string result, string regex)
			{
				return Context.Parameters.First((SugarParameter it) => it.ParameterName == Regex.Match(result, regex).Groups[1].Value).Value;
			}
		}
		public class SubWhereIF : ISubOperation
		{
			public bool HasWhere { get; set; }

			public string Name => "WhereIF";

			public Expression Expression { get; set; }

			public int Sort => 400;

			public ExpressionContext Context { get; set; }

			public string GetValue(Expression expression)
			{
				MethodCallExpression methodCallExpression = expression as MethodCallExpression;
				object value = null;
				try
				{
					value = ExpressionTool.DynamicInvoke(methodCallExpression.Arguments[0]);
				}
				catch
				{
					Check.Exception(true, ErrorMessage.WhereIFCheck, methodCallExpression.Arguments[0].ToString());
				}
				if (Regex.Matches(expression.ToString(), "Subqueryable").Count >= 2)
				{
					SubSelect subSelect = new SubSelect();
					subSelect.Context = Context;
					subSelect.SetShortNameNext(methodCallExpression, "+");
				}
				if (!Convert.ToBoolean(Convert.ToBoolean(value)))
				{
					return "WHERE 1=1 ";
				}
				Expression expression2 = methodCallExpression.Arguments[1];
				ExpressionContext expressionContext = Context;
				if (Context.JoinIndex > 0)
				{
					expressionContext = Context.GetCopyContextWithMapping();
					expressionContext.IsSingle = false;
				}
				string text = "WHERE " + SubTools.GetMethodValue(expressionContext, expression2, ResolveExpressType.WhereMultiple);
				if (Context.JoinIndex > 0)
				{
					Context.Parameters.AddRange(expressionContext.Parameters);
					Context.Index = expressionContext.Index;
					Context.ParameterIndex = expressionContext.ParameterIndex;
				}
				string text2 = Context.GetTranslationColumnName((expression2 as LambdaExpression).Parameters.First().Name) + ".";
				if (Context.JoinIndex == 0)
				{
					text = text.Replace(text2, SubTools.GetSubReplace(Context));
				}
				if (!string.IsNullOrEmpty(text2) && Context.IsSingle && Context.JoinIndex == 0)
				{
					Context.CurrentShortName = text2.TrimEnd('.');
				}
				return text;
			}
		}
		public class SubWithNolock : ISubOperation
		{
			public ExpressionContext Context { get; set; }

			public Expression Expression { get; set; }

			public bool HasWhere { get; set; }

			public string Name => "WithNoLock";

			public int Sort => 301;

			public string GetValue(Expression expression)
			{
				if (Context is SqlServerExpressionContext)
				{
					return "WITH(NOLOCK) ";
				}
				return "";
			}
		}
