		/// <summary>
		///  ** description：Get subquery sql
		///  ** author：sunkaixuan
		///  ** date：2017/9/17
		///  ** email:610262374@qq.com
		///  </summary>
		public class SubResolve
		{
			private List<MethodCallExpression> allMethods = new List<MethodCallExpression>();

			private ExpressionContext context;

			private string subKey = "$SubAs:";

			private bool hasWhere;

			private bool isXmlPath;

			private bool isAsAttr;

			public SubResolve(MethodCallExpression expression, ExpressionContext context, Expression oppsiteExpression)
			{
				this.context = context;
				MethodCallExpression methodCallExpression = expression;
				allMethods.Add(methodCallExpression);
				if (context.IsSingle && oppsiteExpression != null && oppsiteExpression is MemberExpression)
				{
					Expression expression2 = (oppsiteExpression as MemberExpression).Expression;
					if (expression2 is ParameterExpression)
					{
						this.context.SingleTableNameSubqueryShortName = (expression2 as ParameterExpression).Name;
					}
					else
					{
						this.context.SingleTableNameSubqueryShortName = (context.Expression as LambdaExpression).Parameters.First().Name;
					}
				}
				else if (context.IsSingle && ExpressionTool.GetMethodName(methodCallExpression) != "ToList")
				{
					if (context.Expression is LambdaExpression)
					{
						this.context.SingleTableNameSubqueryShortName = (context.Expression as LambdaExpression).Parameters.First().Name;
					}
					else if (context.Expression is MethodCallExpression)
					{
						ReadOnlyCollection<Expression> arguments = ((context.Expression as MethodCallExpression).Object as MethodCallExpression).Arguments;
						if (arguments != null && arguments.Any() && arguments[0] is LambdaExpression lambdaExpression)
						{
							string selfParameterName = lambdaExpression.Parameters.First().Name;
							if (lambdaExpression.Body is BinaryExpression)
							{
								context.SingleTableNameSubqueryShortName = (((lambdaExpression.Body as BinaryExpression).Left as MemberExpression)?.Expression as ParameterExpression)?.Name;
							}
							else if (lambdaExpression.Body is MethodCallExpression methodCallExpression2 && methodCallExpression2.Type == UtilConstants.BoolType)
							{
								List<ParameterExpression> parameters = ExpressionTool.GetParameters(methodCallExpression2);
								if (context.SingleTableNameSubqueryShortName == null && parameters != null && parameters.Select((ParameterExpression s) => s.Name)?.Distinct()?.Count() == 2)
								{
									context.SingleTableNameSubqueryShortName = parameters?.LastOrDefault()?.Name;
								}
							}
							if (ExpressionTool.GetMethodName(context.Expression).IsContainsIn("ToList") && lambdaExpression.Parameters.Any((ParameterExpression it) => it.Name == selfParameterName) && lambdaExpression.Body is BinaryExpression)
							{
								context.SingleTableNameSubqueryShortName = (((lambdaExpression.Body as BinaryExpression).Right as MemberExpression)?.Expression as ParameterExpression)?.Name;
							}
							if (context.SingleTableNameSubqueryShortName == selfParameterName && lambdaExpression.Body is BinaryExpression)
							{
								context.SingleTableNameSubqueryShortName = (((lambdaExpression.Body as BinaryExpression).Right as MemberExpression)?.Expression as ParameterExpression)?.Name;
							}
						}
					}
					else if (context.Expression.GetType().Name == "MethodBinaryExpression")
					{
						Expression expression3 = (((context.Expression as BinaryExpression).Left is MethodCallExpression) ? (context.Expression as BinaryExpression).Left : (context.Expression as BinaryExpression).Right);
						if (expression3 is MethodCallExpression)
						{
							LambdaExpression lambdaExpression2 = ((expression3 as MethodCallExpression).Object as MethodCallExpression).Arguments[0] as LambdaExpression;
							string name = lambdaExpression2.Parameters.First().Name;
							context.SingleTableNameSubqueryShortName = (((lambdaExpression2.Body as BinaryExpression).Left as MemberExpression).Expression as ParameterExpression).Name;
							if (context.SingleTableNameSubqueryShortName == name)
							{
								context.SingleTableNameSubqueryShortName = (((lambdaExpression2.Body as BinaryExpression).Right as MemberExpression).Expression as ParameterExpression).Name;
							}
						}
					}
					else if (context.RootExpression != null && context.Expression.GetType().Name == "SimpleBinaryExpression")
					{
						string name2 = (this.context.RootExpression as LambdaExpression).Parameters[0].Name;
						context.SingleTableNameSubqueryShortName = name2;
					}
					else if (context.Expression is BinaryExpression)
					{
						Expression expression4 = (((context.Expression as BinaryExpression).Left is MethodCallExpression) ? (context.Expression as BinaryExpression).Left : (context.Expression as BinaryExpression).Right);
						if (expression4 is MethodCallExpression)
						{
							ReadOnlyCollection<Expression> arguments2 = ((expression4 as MethodCallExpression).Object as MethodCallExpression).Arguments;
							if (arguments2.Count > 0)
							{
								LambdaExpression lambdaExpression3 = arguments2[0] as LambdaExpression;
								string name3 = lambdaExpression3.Parameters.First().Name;
								context.SingleTableNameSubqueryShortName = (((lambdaExpression3.Body as BinaryExpression).Left as MemberExpression)?.Expression as ParameterExpression)?.Name;
								if (context.SingleTableNameSubqueryShortName == name3)
								{
									context.SingleTableNameSubqueryShortName = (((lambdaExpression3.Body as BinaryExpression).Right as MemberExpression).Expression as ParameterExpression).Name;
								}
							}
						}
					}
					else if (context.Expression is MemberInitExpression)
					{
						List<string> list = (from it in ExpressionTool.GetParameters(context.Expression)
							select it.Name).Distinct().ToList();
						if (list != null && list.Count() > 1)
						{
							context.SingleTableNameSubqueryShortName = list.First();
						}
					}
					else
					{
						Check.ExceptionEasy("I'm sorry I can't parse the current expression", "不支持当前表达式");
					}
				}
				int subQueryIndex = this.context.SubQueryIndex;
				while (methodCallExpression != null)
				{
					MethodCallExpression methodCallExpression3 = methodCallExpression.Object as MethodCallExpression;
					if (methodCallExpression3 != null)
					{
						allMethods.Add(methodCallExpression3);
					}
					if (subQueryIndex == this.context.SubQueryIndex && methodCallExpression3 != null && methodCallExpression3.Arguments.HasValue() && methodCallExpression3.Arguments.Any((Expression it) => it.ToString().Contains("Subqueryable()")))
					{
						this.context.SubQueryIndex++;
					}
					methodCallExpression = methodCallExpression3;
				}
			}

			public string GetSql()
			{
				List<string> subItems = GetSubItems();
				List<string> list = subItems.Where((string it) => !it.StartsWith(subKey)).ToList();
				List<string> list2 = subItems.Where((string it) => it.StartsWith(subKey)).ToList();
				if (list2.Any())
				{
					GetSubAs(list, list2);
				}
				if (context.CurrentShortName.HasValue())
				{
					GetShortName(list);
				}
				string text = "";
				if (list.Count((string it) => IsJoin(it)) > 1)
				{
					int index = list.IndexOf(list.First((string x) => IsJoin(x)));
					List<string> list3 = list.Where((string it) => IsJoin(it)).ToList();
					list3.Reverse();
					List<string> list4 = list.Where((string it) => !IsJoin(it)).ToList();
					list4.InsertRange(index, list3);
					text = string.Join(" ", list4);
				}
				else
				{
					text = string.Join(" ", list);
				}
				if (isXmlPath)
				{
					string forXmlPath = context.DbMehtods.GetForXmlPath();
					if (forXmlPath.HasValue())
					{
						text += forXmlPath;
					}
				}
				return context.DbMehtods.Pack(text);
			}

			private static bool IsJoin(string it)
			{
				if (!it.StartsWith("  INNER JOIN"))
				{
					return it.StartsWith("  LEFT JOIN");
				}
				return true;
			}

			private void GetSubAs(List<string> sqlItems, List<string> asItems)
			{
				for (int i = 0; i < sqlItems.Count; i++)
				{
					if (sqlItems[i].StartsWith("FROM " + context.SqlTranslationLeft))
					{
						string text = context.GetTranslationTableName(asItems.First().Replace(subKey, ""), isMapping: false);
						string pattern = "\\" + context.SqlTranslationLeft + ".+\\" + context.SqlTranslationRight;
						if (context.IsSingle && context.JoinIndex == 0 && context.CurrentShortName.HasValue() && isAsAttr && !text.Contains(context.CurrentShortName))
						{
							text = text + " " + context.CurrentShortName + " ";
						}
						sqlItems[i] = Regex.Replace(sqlItems[i], pattern, text);
					}
				}
			}

			private void GetShortName(List<string> sqlItems)
			{
				for (int i = 0; i < sqlItems.Count; i++)
				{
					if (sqlItems[i].StartsWith("FROM " + context.SqlTranslationLeft) && (!isAsAttr || !sqlItems[i].EndsWith(context.CurrentShortName + " ")))
					{
						sqlItems[i] = sqlItems[i] + " " + context.CurrentShortName + " ";
					}
				}
			}

			private List<string> GetSubItems()
			{
				bool isSubSubQuery = allMethods.Select((MethodCallExpression it) => it.ToString()).Any((string it) => Regex.Matches(it, "Subquery").Count > 1);
				List<ISubOperation> list = allMethods.Select(delegate(MethodCallExpression exp)
				{
					if (isSubSubQuery)
					{
						context.JoinIndex = 1;
						context.SubQueryIndex = 0;
					}
					string methodName = exp.Method.Name;
					List<ISubOperation> source = SubTools.SubItems(context);
					ISubOperation subOperation = source.First((ISubOperation s) => s.Name == methodName);
					if (subOperation is SubWhere && !hasWhere)
					{
						hasWhere = true;
					}
					else if (subOperation is SubWhere)
					{
						subOperation = source.First((ISubOperation s) => s is SubAnd);
					}
					if (subOperation is SubWhereIF && !hasWhere)
					{
						hasWhere = true;
					}
					else if (subOperation is SubWhereIF)
					{
						subOperation = source.First((ISubOperation s) => s is SubAndIF);
					}
					else if (subOperation is SubSelectStringJoin)
					{
						isXmlPath = true;
					}
					else if (subOperation is SubAsWithAttr)
					{
						isAsAttr = true;
					}
					subOperation.Context = context;
					subOperation.Expression = exp;
					return subOperation;
				}).ToList();
				SetOrderByIndex(list);
				list.Insert(0, new SubBegin());
				if (list.Any((ISubOperation it) => it is SubSelect || it is SubFirst))
				{
					list.Add(new SubTop
					{
						Context = context
					});
				}
				if (list.Any((ISubOperation it) => it is SubAny || it is SubNotAny))
				{
					list.Add(new SubLeftBracket());
					list.Add(new SubRightBracket());
					list.Add(new SubSelectDefault());
				}
				SqlSugarProvider sqlSugarProvider = context?.SugarContext?.Context;
				if (sqlSugarProvider != null && sqlSugarProvider != null && sqlSugarProvider.CurrentConnectionConfig?.DbType == DbType.SqlServer)
				{
					ConnectionConfig currentConnectionConfig = sqlSugarProvider.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.IsWithNoLockSubquery == true && !list.Any((ISubOperation it) => it is SubWithNolock))
					{
						list.Add(new SubWithNolock
						{
							Context = context
						});
					}
				}
				list = list.OrderBy((ISubOperation it) => it.Sort).ToList();
				bool isHasWhere = list.Where((ISubOperation it) => it is SubWhere).Any();
				bool num = list.Any((ISubOperation it) => it is SubInnerJoin || it is SubLeftJoin);
				if (num)
				{
					context.JoinIndex++;
				}
				if (isAsAttr)
				{
					context.IsAsAttr = true;
				}
				if (list.Any((ISubOperation it) => it is SubSelect) && list.Any((ISubOperation it) => it is SubTake))
				{
					list.RemoveAll((ISubOperation it) => it is SubTake);
				}
				if ((!num & isSubSubQuery) && context.CurrentShortName == null)
				{
					context.CurrentShortName = ExpressionTool.GetParameters(allMethods.FirstOrDefault()).FirstOrDefault().Name;
				}
				bool hasNolock = false;
				List<string> list2 = list.Select(delegate(ISubOperation it)
				{
					it.HasWhere = isHasWhere;
					if (it is SubWithNolock)
					{
						hasNolock = true;
					}
					string text = it.GetValue(it.Expression);
					bool flag = it is SubLeftJoin || it is SubInnerJoin;
					bool flag2 = UtilMethods.GetDatabaseType(context) == DbType.SqlServer;
					if (hasNolock & flag & flag2)
					{
						text = text.Replace("] ON (", "] WITH(NOLOCK)  ON (");
					}
					return text;
				}).ToList();
				ExpressionContext expressionContext = context;
				if (expressionContext != null && expressionContext.SugarContext?.Context?.CurrentConnectionConfig?.DbType == DbType.Oracle && list.Any((ISubOperation s) => s is SubSelect) && list.Any((ISubOperation s) => s is SubOrderBy || s is SubOrderByDesc))
				{
					list2.Insert(0, "SELECT * FROM(");
					list2.Add(") WHERE ROWNUM = 1  ");
				}
				context.JoinIndex = 0;
				context.IsAsAttr = false;
				return list2;
			}

			private static void SetOrderByIndex(List<ISubOperation> isubList)
			{
				int num = 0;
				List<ISubOperation> list = isubList.Where((ISubOperation it) => it is SubOrderBy || it is SubOrderByDesc).ToList();
				if (list.Count <= 1)
				{
					return;
				}
				list.Reverse();
				foreach (ISubOperation item in list)
				{
					if (item is SubOrderBy)
					{
						(item as SubOrderBy).OrderIndex = num;
						num++;
					}
					else if (item is SubOrderByDesc)
					{
						(item as SubOrderByDesc).OrderIndex = num;
						num++;
					}
				}
			}
		}
