			public static string GetMethodValue(ExpressionContext context, Expression item, ResolveExpressType type)
			{
				ExpressionContext copyContext = context.GetCopyContext();
				copyContext.MappingColumns = context.MappingColumns;
				copyContext.MappingTables = context.MappingTables;
				copyContext.InitMappingInfo = context.InitMappingInfo;
				copyContext.RefreshMapping = context.RefreshMapping;
				copyContext.IgnoreComumnList = context.IgnoreComumnList;
				copyContext.SqlFuncServices = context.SqlFuncServices;
				copyContext.Resolve(item, type);
				context.Index = copyContext.Index;
				context.ParameterIndex = copyContext.ParameterIndex;
				if (copyContext.Parameters.HasValue())
				{
					context.Parameters.AddRange(copyContext.Parameters);
				}
				return copyContext.Result.GetResultString();
			}

			public static string GetMethodValueSubJoin(ExpressionContext context, Expression item, ResolveExpressType type)
			{
				ExpressionContext copyContext = context.GetCopyContext();
				copyContext.MappingColumns = context.MappingColumns;
				copyContext.MappingTables = context.MappingTables;
				copyContext.InitMappingInfo = context.InitMappingInfo;
				copyContext.RefreshMapping = context.RefreshMapping;
				copyContext.IgnoreComumnList = context.IgnoreComumnList;
				copyContext.SqlFuncServices = context.SqlFuncServices;
				if (type == ResolveExpressType.WhereMultiple || type == ResolveExpressType.FieldMultiple)
				{
					copyContext.IsSingle = false;
				}
				copyContext.Resolve(item, type);
				context.Index = copyContext.Index;
				context.ParameterIndex = copyContext.ParameterIndex;
				if (copyContext.Parameters.HasValue())
				{
					context.Parameters.AddRange(copyContext.Parameters);
				}
				return copyContext.Result.GetResultString();
			}
		}
