			public List<T> DataReaderToValueTupleType<T>(IDataReader reader)
			{
				List<T> list = new List<T>();
				List<string> list2 = Enumerable.Range(0, reader.FieldCount).Select(reader.GetName).ToList();
				List<Type> list3 = Enumerable.Range(0, reader.FieldCount).Select(reader.GetFieldType).ToList();
				using (reader)
				{
					while (reader.Read())
					{
						Type typeFromHandle = typeof(T);
						object obj = Activator.CreateInstance(typeFromHandle);
						for (int i = 0; i < reader.FieldCount; i++)
						{
							_ = list2[i];
							object value = reader.GetValue(i);
							_ = list3[i];
							FieldInfo fieldInfo = typeFromHandle.GetFields()[i];
							fieldInfo.SetValue(obj, UtilMethods.ChangeType2(value, fieldInfo.FieldType));
						}
						list.Add((T)obj);
					}
					return list;
				}
			}

			public async Task<List<T>> DataReaderToValueTupleTypeAsync<T>(IDataReader reader)
			{
				List<T> result = new List<T>();
				List<string> propertyNames = Enumerable.Range(0, reader.FieldCount).Select(reader.GetName).ToList();
				List<Type> propertyTypes = Enumerable.Range(0, reader.FieldCount).Select(reader.GetFieldType).ToList();
				using (reader)
				{
					while (await ((DbDataReader)reader).ReadAsync())
					{
						Type typeFromHandle = typeof(T);
						object obj = Activator.CreateInstance(typeFromHandle);
						for (int i = 0; i < reader.FieldCount; i++)
						{
							_ = propertyNames[i];
							object value = reader.GetValue(i);
							Type conversionType = propertyTypes[i];
							typeFromHandle.GetFields()[i].SetValue(obj, Convert.ChangeType(value, conversionType));
						}
						result.Add((T)obj);
					}
				}
				return result;
			}

