			/// <summary>
			///             DataReader to DataReaderToDictionary
			/// </summary>
			/// <param name="reader"></param>
			/// <returns></returns>
			public Dictionary<string, object> DataReaderToDictionary(IDataReader reader, Type type)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				for (int i = 0; i < reader.FieldCount; i++)
				{
					string text = reader.GetName(i);
					try
					{
						text = Context.EntityMaintenance.GetPropertyName(text, type);
						object obj = reader.GetValue(i);
						if (obj == DBNull.Value)
						{
							obj = null;
						}
						dictionary.Add(text, obj);
					}
					catch
					{
						if (!dictionary.ContainsKey(text))
						{
							dictionary.Add(text, null);
						}
					}
				}
				return dictionary;
			}

			/// <summary>
			/// DataReaderToList
			/// </summary>
			/// <typeparam name="T"></typeparam>
			/// <param name="reader"></param>
			/// <returns></returns>
			public List<T> DataReaderToList<T>(IDataReader reader)
			{
				using (reader)
				{
					Type typeFromHandle = typeof(T);
					List<PropertyInfo> list = (from p in typeFromHandle.GetProperties()
						where p.GetIndexParameters().Length == 0
						select p).ToList();
					QueryBuilder queryBuilder = QueryBuilder;
					if (queryBuilder != null && queryBuilder.IsAnyParameterExpression && queryBuilder.SelectValue is LambdaExpression { Body: MemberInitExpression body })
					{
						List<string> memberNames = (from b in body.Bindings.OfType<MemberAssignment>()
							select b.Member.Name).ToList();
						list = list.Where((PropertyInfo p) => memberNames.Contains(p.Name)).ToList();
					}
					List<T> list2 = new List<T>();
					if (reader != null && !reader.IsClosed)
					{
						while (reader.Read())
						{
							Dictionary<string, object> value = DataReaderToList(reader, typeFromHandle, list, list2);
							string value2 = SerializeObject(value);
