			private Dictionary<string, object> DataReaderToList<T>(IDataReader reader, Type tType, List<PropertyInfo> classProperties, List<T> reval)
			{
				Dictionary<string, object> dictionary = DataReaderToDictionary(reader, tType);
				Dictionary<string, string> mappingKeys = QueryBuilder?.MappingKeys;
				Dictionary<string, object> dictionary2 = new Dictionary<string, object>();
				if (UtilMethods.IsTuple(tType, classProperties))
				{
					int num = 0;
					{
						foreach (PropertyInfo classProperty in classProperties)
						{
							_ = classProperty;
							dictionary2.Add("Item" + (num + 1), reader.GetValue(num));
							num++;
						}
						return dictionary2;
					}
				}
				foreach (PropertyInfo item in classProperties)
				{
					string name = item.Name;
					_ = tType.Name;
					if (item.PropertyType.IsClass())
					{
						if (item.PropertyType.FullName == "Newtonsoft.Json.Linq.JObject")
						{
							dictionary2.Add(name, (dynamic)DeserializeObject<object>(dictionary[item.Name].ToString()));
						}
						else if (IsJsonItem(dictionary, name))
						{
							dictionary2.Add(name, DeserializeObject<Dictionary<string, object>>(dictionary.First((KeyValuePair<string, object> it) => it.Key.EqualCase(name)).Value.ObjToString()));
						}
						else if (IsJsonList(dictionary, item))
						{
							string value = dictionary.First((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value.ToString();
							dictionary2.Add(name, DeserializeObject<List<Dictionary<string, object>>>(value));
						}
						else if (IsBytes(dictionary, item))
						{
							dictionary2.Add(name, (byte[])dictionary[item.Name.ToLower()]);
						}
						else
						{
							if (StaticConfig.EnableAot && tType == typeof(DbColumnInfo) && item.PropertyType == typeof(object))
							{
								continue;
							}
							if (item.PropertyType == typeof(object))
							{
								dictionary2.Add(name, dictionary[item.Name.ToLower()]);
								continue;
							}
							if (IsArrayItem(dictionary, item))
							{
								string text = dictionary.First((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value?.ToString() ?? "";
								if (text.StartsWith("[{"))
								{
									dictionary2.Add(name, DeserializeObject<JArray>(text));
								}
								else
								{
									dictionary2.Add(name, DeserializeObject<string[]>(text));
								}
								continue;
							}
							Type propertyType = item.PropertyType;
							if ((object)propertyType != null && propertyType.IsArray && dictionary != null && dictionary.Any((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)) && dictionary?.FirstOrDefault((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value is Array value2)
							{
								dictionary2.Add(name, value2);
							}
							else
							{
								if (StaticConfig.EnableAot && item.PropertyType == typeof(Type))
								{
									continue;
								}
								List<string> list = null;
								QueryBuilder queryBuilder = QueryBuilder;
								if (queryBuilder != null && queryBuilder.SelectNewIgnoreColumns?.Any() == true)
								{
									List<KeyValuePair<string, string>> source = QueryBuilder.SelectNewIgnoreColumns.Where<KeyValuePair<string, string>>((KeyValuePair<string, string> it) => it.Value == item.PropertyType.Name).ToList();
									if (source.Any())
									{
										list = source.Select((KeyValuePair<string, string> it) => it.Key).ToList();
									}
									if (list != null && list.Contains(name))
									{
										continue;
									}
								}
								dictionary2.Add(name, DataReaderToDynamicList_Part(dictionary, item, reval, mappingKeys, list));
							}
						}
					}
					else
					{
						if (!dictionary.Any((KeyValuePair<string, object> it) => it.Key.Equals(name, StringComparison.CurrentCultureIgnoreCase)))
						{
							continue;
						}
						object obj = (dictionary.ContainsKey(name) ? dictionary[name] : dictionary.First((KeyValuePair<string, object> it) => it.Key.Equals(name, StringComparison.CurrentCultureIgnoreCase)).Value);
						if (obj != null)
						{
							QueryBuilder queryBuilder2 = QueryBuilder;
							if (queryBuilder2 != null && queryBuilder2.QueryableFormats?.Any((QueryableFormat it) => it.PropertyName == name) == true)
							{
								QueryableFormat valueFomatInfo = QueryBuilder?.QueryableFormats?.First((QueryableFormat it) => it.PropertyName == name);
								obj = UtilMethods.GetFormatValue(obj, valueFomatInfo);
							}
						}
						Type underType = UtilMethods.GetUnderType(item.PropertyType);
						if (obj == DBNull.Value || obj == null)
						{
							obj = (item.PropertyType.IsIn(UtilConstants.IntType, UtilConstants.LongType, UtilConstants.DecType, UtilConstants.DobType, UtilConstants.ByteType) ? ((object)0) : ((item.PropertyType == UtilConstants.GuidType) ? ((object)Guid.Empty) : ((item.PropertyType == UtilConstants.DateType) ? ((object)DateTime.MinValue) : ((!(item.PropertyType == UtilConstants.StringType)) ? null : null))));
						}
						else if (underType == UtilConstants.IntType)
						{
							obj = Convert.ToInt32(obj);
						}
						else if (underType == UtilConstants.LongType)
						{
							obj = Convert.ToInt64(obj);
						}
						else if (underType.IsEnum() && obj is decimal)
						{
							obj = Convert.ToInt64(obj);
						}
						else if (underType.FullName == "System.DateOnly")
						{
							obj = Convert.ToDateTime(obj).ToString("yyyy-MM-dd");
						}
						else if (underType.FullName == "System.TimeOnly" || underType.FullName == "System.TimeSpan")
						{
							obj = Convert.ToDateTime(obj).ToString("HH:mm:ss");
						}
						dictionary2.Add(name, obj);
					}
				}
				return dictionary2;
			}

			private void SetAppendColumns(IDataReader dataReader)
			{
				if (QueryBuilder != null && QueryBuilder.AppendColumns != null && QueryBuilder.AppendColumns.Any())
				{
					if (QueryBuilder.AppendValues == null)
					{
						QueryBuilder.AppendValues = new List<List<QueryableAppendColumn>>();
					}
					List<QueryableAppendColumn> list = new List<QueryableAppendColumn>();
					foreach (QueryableAppendColumn appendColumn in QueryBuilder.AppendColumns)
					{
						int ordinal = dataReader.GetOrdinal(appendColumn.AsName);
						object value = dataReader.GetValue(ordinal);
						list.Add(new QueryableAppendColumn
						{
							Name = appendColumn.Name,
							AsName = appendColumn.AsName,
							Value = value
						});
					}
					QueryBuilder.AppendValues.Add(list);
				}
				if (QueryBuilder?.AppendNavInfo == null)
				{
					return;
				}
				AppendNavResult appendNavResult = new AppendNavResult();
				foreach (KeyValuePair<string, string> item in QueryBuilder?.AppendNavInfo.AppendProperties)
				{
					int ordinal2 = dataReader.GetOrdinal("SugarNav_" + item.Key);
					object value2 = dataReader.GetValue(ordinal2);
					appendNavResult.result.Add("SugarNav_" + item.Key, value2);
				}
				QueryBuilder?.AppendNavInfo.Result.Add(appendNavResult);
			}

			private static bool IsBytes(Dictionary<string, object> readerValues, PropertyInfo item)
			{
				if (item.PropertyType == UtilConstants.ByteArrayType && readerValues.ContainsKey(item.Name.ToLower()))
				{
					if (readerValues[item.Name.ToLower()] != null)
					{
						return readerValues[item.Name.ToLower()].GetType() == UtilConstants.ByteArrayType;
					}
					return true;
				}
				return false;
			}

			private static bool IsJsonItem(Dictionary<string, object> readerValuesOld, string name)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				if (readerValuesOld.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(name)))
				{
					KeyValuePair<string, object> keyValuePair = readerValuesOld.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(name));
					dictionary.Add(keyValuePair.Key, keyValuePair.Value);
				}
				if (dictionary != null && dictionary.Count == 1 && dictionary.First().Key == name && dictionary.First().Value != null && dictionary.First().Value.GetType() == UtilConstants.StringType)
				{
					return Regex.IsMatch(dictionary.First().Value.ObjToString(), "^\\{.+\\}$");
				}
				return false;
			}

			private static bool IsArrayItem(Dictionary<string, object> readerValues, PropertyInfo item)
			{
				bool num = item.PropertyType.IsArray && readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)) && readerValues.FirstOrDefault<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value is string;
				bool flag = item.PropertyType.FullName.IsCollectionsList() && item.PropertyType.GenericTypeArguments.Length == 1 && !item.PropertyType.GenericTypeArguments.First().IsClass() && readerValues.FirstOrDefault<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value is string;
				return num | flag;
			}

			private bool IsJsonList(Dictionary<string, object> readerValues, PropertyInfo item)
			{
				if (item.PropertyType.FullName.IsCollectionsList() && readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)) && readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value != null && readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value.GetType() == UtilConstants.StringType)
				{
					return Regex.IsMatch(readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> y) => y.Key.EqualCase(item.Name)).Value.ToString(), "^\\[{.+\\}]$");
				}
				return false;
			}

			private Dictionary<string, object> DataReaderToDynamicList_Part<T>(Dictionary<string, object> readerValues, PropertyInfo item, List<T> reval, Dictionary<string, string> mappingKeys = null, List<string> ignoreColumns = null)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				Type propertyType = item.PropertyType;
				if (UtilConstants.SugarType == propertyType)
				{
					return dictionary;
				}
				if (propertyType.FullName.IsCollectionsList())
				{
					return null;
				}
				if (propertyType == typeof(string[]))
				{
					return null;
				}
				List<PropertyInfo> list = propertyType.GetProperties().ToList();
				if (propertyType.Name.StartsWith("Dictionary`"))
				{
					return null;
				}
				List<EntityColumnInfo> columns = Context.EntityMaintenance.GetEntityInfo(propertyType).Columns;
				foreach (PropertyInfo item2 in list)
				{
					string name = item2.Name;
					string name2 = propertyType.Name;
					if (item2.PropertyType.IsClass())
					{
						if (ignoreColumns != null && ignoreColumns.Contains(name))
						{
							continue;
						}
						SugarColumn customAttribute = item2.GetCustomAttribute<SugarColumn>();
						if (customAttribute != null && customAttribute.IsJson)
						{
							if (mappingKeys != null && mappingKeys.ContainsKey(item.Name))
							{
								string shortName = mappingKeys[item.Name];
								Json(readerValues, dictionary, name, name2, shortName, item);
							}
							else
							{
								Json(readerValues, dictionary, name, name2, item);
							}
						}
						else if (columns.Any((EntityColumnInfo it) => it.IsJson))
						{
							EntityColumnInfo entityColumnInfo = columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyName == name);
							if (entityColumnInfo != null && entityColumnInfo.IsJson)
							{
								Json(readerValues, dictionary, name, name2);
							}
						}
						else
						{
							dictionary.Add(name, DataReaderToDynamicList_Part(readerValues, item2, reval));
						}
						continue;
					}
					string key = name2 + "." + name;
					string text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower() == key.ToLower());
					if (text == null)
					{
						key = item.Name + "." + name;
						text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower() == key.ToLower());
						if (text == null)
						{
							text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower().EndsWith("." + key.ToLower()));
						}
					}
					string text2 = text;
					if (mappingKeys != null && mappingKeys.ContainsKey(item.Name))
					{
						key = mappingKeys[item.Name] + "." + name2 + "." + name;
						text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower() == key.ToLower());
						if (text == null)
						{
							string key2 = item.Name + "." + name;
							text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower() == key2.ToLower());
						}
					}
					else if (mappingKeys != null && mappingKeys.ContainsKey("Single_" + name))
					{
						key = mappingKeys["Single_" + name];
						text = readerValues.Select<KeyValuePair<string, object>, string>((KeyValuePair<string, object> it) => it.Key).FirstOrDefault((string it) => it.ToLower() == key.ToLower());
					}
					if (text == null && text2 != null)
					{
						text = text2;
					}
					if (text != null)
					{
						object obj = readerValues[text];
						if (obj == DBNull.Value)
						{
							obj = null;
						}
						Type underType = UtilMethods.GetUnderType(item2.PropertyType);
						if (item2.PropertyType == UtilConstants.IntType)
						{
							obj = obj.ObjToInt();
						}
						else if (item2.PropertyType == UtilConstants.ShortType)
						{
							obj = Convert.ToInt16(obj);
						}
						else if (item2.PropertyType == UtilConstants.LongType)
						{
							obj = Convert.ToInt64(obj);
						}
						else if (UtilMethods.GetUnderType(item2.PropertyType) == UtilConstants.IntType && obj != null)
						{
							obj = obj.ObjToInt();
						}
						else if (underType == UtilConstants.LongType && obj != null)
						{
							obj = obj.ObjToLong();
						}
						else if (obj != null && underType?.FullName == "System.DateOnly")
						{
							obj = Convert.ToDateTime(obj).ToString("yyyy-MM-dd");
						}
						else if (UtilMethods.GetUnderType(item2.PropertyType).IsEnum() && obj is decimal && (item2.PropertyType.IsEnum() || obj != null))
						{
							obj = Convert.ToInt64(obj);
						}
						dictionary.Add(name, obj);
					}
				}
				return dictionary;
			}

			private void Json(Dictionary<string, object> readerValues, Dictionary<string, object> result, string name, string typeName, string shortName = null, PropertyInfo item = null)
			{
				string key = (typeName + "." + name).ToLower();
				if (readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)))
				{
					object value = readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)).Value;
					AddJson(result, name, value);
					return;
				}
				key = (shortName + "." + typeName + "." + name).ToLower();
				if (readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)))
				{
					object value2 = readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)).Value;
					AddJson(result, name, value2);
				}
				else if (item != null && readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(item.Name + "." + name)))
				{
					object value3 = readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(item.Name + "." + name)).Value;
					AddJson(result, name, value3);
				}
			}

			private void Json(Dictionary<string, object> readerValues, Dictionary<string, object> result, string name, string typeName, PropertyInfo item)
			{
				string key = (typeName + "." + name).ToLower();
				if (readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)))
				{
					object value = readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)).Value;
					AddJson(result, name, value);
					return;
				}
				key = (item.Name + "." + name).ToLower();
				if (readerValues.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)))
				{
					object value2 = readerValues.First<KeyValuePair<string, object>>((KeyValuePair<string, object> it) => it.Key.EqualCase(key)).Value;
					AddJson(result, name, value2);
				}
			}

			private void AddJson(Dictionary<string, object> result, string name, object jsonString)
			{
				if (jsonString != null)
				{
					if (jsonString.ToString().First() == '{' && jsonString.ToString().Last() == '}')
					{
						result.Add(name, DeserializeObject<Dictionary<string, object>>(jsonString?.ToString() ?? ""));
					}
					else if (jsonString.ToString().Replace(" ", "") != "[]" && !jsonString.ToString().Contains("{") && !jsonString.ToString().Contains("}"))
					{
						result.Add(name, (dynamic)DeserializeObject<object>(jsonString?.ToString() ?? ""));
					}
					else
					{
						result.Add(name, DeserializeObject<List<Dictionary<string, object>>>(jsonString?.ToString() ?? ""));
					}
				}
			}

			/// <summary>
			/// Serialize Object
			/// </summary>
			/// <param name="value"></param>
			/// <returns></returns>
			public string SerializeObject(object value)
			{
				DependencyManagement.TryJsonNet();
				return Context.CurrentConnectionConfig.ConfigureExternalServices.SerializeService.SerializeObject(value);
			}

			public string SerializeObject(object value, Type type)
			{
				DependencyManagement.TryJsonNet();
				if (type.IsAnonymousType())
				{
					return Context.CurrentConnectionConfig.ConfigureExternalServices.SerializeService.SerializeObject(value);
				}
				if (Context.EntityMaintenance.GetEntityInfo(type).Columns.Any((EntityColumnInfo it) => it.NoSerialize || it.SerializeDateTimeFormat.HasValue()))
				{
					return Context.CurrentConnectionConfig.ConfigureExternalServices.SerializeService.SugarSerializeObject(value);
				}
				return Context.CurrentConnectionConfig.ConfigureExternalServices.SerializeService.SerializeObject(value);
			}

			/// <summary>
			/// Serialize Object
			/// </summary>
			/// <param name="value"></param>
			/// <returns></returns>
			public T DeserializeObject<T>(string value)
			{
				DependencyManagement.TryJsonNet();
				return Context.CurrentConnectionConfig.ConfigureExternalServices.SerializeService.DeserializeObject<T>(value);
			}

			/// <summary>
			/// Copy new Object
			/// </summary>
			/// <typeparam name="T"></typeparam>
			/// <param name="sourceObject"></param>
			/// <returns></returns>
			public T TranslateCopy<T>(T sourceObject)
			{
				if (sourceObject == null)
				{
					return default(T);
				}
				string value = SerializeObject(sourceObject);
				return DeserializeObject<T>(value);
			}

			public SqlSugarProvider CopyContext(bool isCopyEvents = false)
			{
				SqlSugarProvider sqlSugarProvider = new SqlSugarProvider(TranslateCopy(Context.CurrentConnectionConfig));
				sqlSugarProvider.CurrentConnectionConfig.ConfigureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
				sqlSugarProvider.MappingColumns = TranslateCopy(Context.MappingColumns);
				sqlSugarProvider.MappingTables = TranslateCopy(Context.MappingTables);
				sqlSugarProvider.IgnoreColumns = TranslateCopy(Context.IgnoreColumns);
				sqlSugarProvider.IgnoreInsertColumns = TranslateCopy(Context.IgnoreInsertColumns);
				if (isCopyEvents)
				{
					sqlSugarProvider.QueryFilter = Context.QueryFilter;
					sqlSugarProvider.CurrentConnectionConfig.AopEvents = Context.CurrentConnectionConfig.AopEvents;
				}
				return sqlSugarProvider;
			}

			public DataTable DictionaryListToDataTable(List<Dictionary<string, object>> list)
			{
				DataTable dataTable = new DataTable();
				if (list.Count == 0)
				{
					return dataTable;
				}
				foreach (KeyValuePair<string, object> item in list.First())
				{
					dataTable.Columns.Add(item.Key, (item.Value == null) ? typeof(object) : item.Value.GetType());
				}
				foreach (Dictionary<string, object> item2 in list)
				{
					DataRow dataRow = dataTable.NewRow();
					foreach (string key in item2.Keys)
					{
						if (item2[key] == null)
						{
							dataRow[key] = DBNull.Value;
						}
						else
						{
							dataRow[key] = item2[key];
						}
					}
					dataTable.Rows.Add(dataRow);
				}
				return dataTable;
			}

			public dynamic DataTableToDynamic(DataTable table)
			{
				List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
				foreach (DataRow row in table.Rows)
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					foreach (DataColumn column in table.Columns)
					{
						object obj = row[column];
						if (obj == DBNull.Value)
						{
							obj = null;
						}
						dictionary.Add(column.ColumnName, obj);
					}
					list.Add(dictionary);
				}
				return DeserializeObject<object>(SerializeObject(list));
			}

