				return DeserializeObject<List<T>>(SerializeObject(list));
			}

			public DataTable ListToDataTable<T>(List<T> list)
			{
				DataTable dataTable = new DataTable();
				if (list != null && list.Count > 0)
				{
					PropertyInfo[] properties = list[0].GetType().GetProperties();
					PropertyInfo[] array = properties;
					foreach (PropertyInfo propertyInfo in array)
					{
						Type type = propertyInfo.PropertyType;
						if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(Nullable<>))
						{
							type = type.GetGenericArguments()[0];
						}
						dataTable.Columns.Add(propertyInfo.Name, type);
					}
					for (int j = 0; j < list.Count; j++)
					{
						ArrayList arrayList = new ArrayList();
						array = properties;
						for (int i = 0; i < array.Length; i++)
						{
							object value = array[i].GetValue(list[j], null);
							arrayList.Add(value);
						}
						object[] values = arrayList.ToArray();
						dataTable.LoadDataRow(values, fAcceptChanges: true);
					}
				}
				return dataTable;
			}

			public DataTable ListToDataTableWithAttr<T>(List<T> list)
			{
				EntityInfo entityInfo = Context.EntityMaintenance.GetEntityInfo<T>();
				DataTable dataTable = new DataTable();
				dataTable.TableName = entityInfo.DbTableName;
				if (list != null && list.Count > 0)
				{
					IEnumerable<EntityColumnInfo> enumerable = entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore);
					foreach (EntityColumnInfo item in enumerable)
					{
						Type type = item.PropertyInfo.PropertyType;
						if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(Nullable<>))
						{
							type = type.GetGenericArguments()[0];
						}
						dataTable.Columns.Add(item.DbColumnName, type);
					}
					for (int num = 0; num < list.Count; num++)
					{
						ArrayList arrayList = new ArrayList();
						foreach (EntityColumnInfo item2 in enumerable)
						{
							object value = item2.PropertyInfo.GetValue(list[num], null);
							arrayList.Add(value);
						}
						object[] values = arrayList.ToArray();
						dataTable.LoadDataRow(values, fAcceptChanges: true);
					}
				}
				return dataTable;
			}

			public Dictionary<string, object> DataTableToDictionary(DataTable table)
			{
				return table.Rows.Cast<DataRow>().ToDictionary((DataRow x) => x[0].ToString(), (DataRow x) => x[1]);
