			public List<IConditionalModel> JsonToConditionalModels(string json)
			{
				List<IConditionalModel> list = new List<IConditionalModel>();
				foreach (JToken item2 in Context.Utilities.DeserializeObject<JArray>(json))
				{
					if (((IEnumerable<JToken>)item2).Count() <= 0)
					{
						continue;
					}
					if (((object)item2).ToString().Contains("ConditionalList"))
					{
						IConditionalModel item = new ConditionalTree
						{
							ConditionalList = GetConditionalList(item2)
						};
						list.Add(item);
						continue;
					}
					string text = Extensions.Value<string>((IEnumerable<JToken>)item2[(object)"ConditionalType"]);
					ConditionalModel conditionalModel = new ConditionalModel
					{
						FieldName = (((object)item2[(object)"FieldName"])?.ToString() ?? ""),
						CSharpTypeName = (item2[(object)"CSharpTypeName"].ObjToString().IsNullOrEmpty() ? null : item2[(object)"CSharpTypeName"].ObjToString()),
						FieldValue = ((Extensions.Value<string>((IEnumerable<JToken>)item2[(object)"FieldValue"]) == null) ? null : ((object)item2[(object)"FieldValue"]).ToString())
					};
					if (text.IsInt())
					{
						conditionalModel.ConditionalType = (ConditionalType)Convert.ToInt32(text);
					}
					else
					{
						conditionalModel.ConditionalType = (ConditionalType)Enum.Parse(typeof(ConditionalType), text.ObjToString());
					}
					list.Add(conditionalModel);
				}
				return list;
			}

			private static List<KeyValuePair<WhereType, IConditionalModel>> GetConditionalList(JToken item)
			{
				List<KeyValuePair<WhereType, IConditionalModel>> list = new List<KeyValuePair<WhereType, IConditionalModel>>();
				foreach (JToken item2 in (IEnumerable<JToken>)((IEnumerable<JToken>)Extensions.Values((IEnumerable<JToken>)item)).First())
				{
					WhereType key = (WhereType)Convert.ToInt32(Extensions.Value<int>((IEnumerable<JToken>)item2[(object)"Key"]));
					IConditionalModel conditionalModel = null;
					JToken val = item2[(object)"Value"];
					conditionalModel = ((!((object)val).ToString().Contains("ConditionalList")) ? ((IConditionalModel)new ConditionalModel
					{
						ConditionalType = GetConditionalType(val),
						FieldName = (((object)val[(object)"FieldName"])?.ToString() ?? ""),
						CSharpTypeName = (val[(object)"CSharpTypeName"].ObjToString().IsNullOrEmpty() ? null : val[(object)"CSharpTypeName"].ObjToString()),
						FieldValue = ((Extensions.Value<string>((IEnumerable<JToken>)val[(object)"FieldValue"]) == null) ? null : ((object)val[(object)"FieldValue"]).ToString())
					}) : ((IConditionalModel)new ConditionalTree
					{
						ConditionalList = GetConditionalList(val)
					}));
					list.Add(new KeyValuePair<WhereType, IConditionalModel>(key, conditionalModel));
				}
				return list;
			}

			private static ConditionalType GetConditionalType(JToken value)
			{
				//IL_000b: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Invalid comparison between Unknown and I4
				if ((int)value[(object)"ConditionalType"].Type == 8)
				{
					string text = Extensions.Value<string>((IEnumerable<JToken>)value[(object)"ConditionalType"]);
					if (!text.IsInt())
					{
						return (ConditionalType)Enum.Parse(typeof(ConditionalType), text);
					}
				}
				return (ConditionalType)Convert.ToInt32(Extensions.Value<int>((IEnumerable<JToken>)value[(object)"ConditionalType"]));
			}

			public List<T> ToTree<T>(List<T> list, Expression<Func<T, IEnumerable<object>>> childListExpression, Expression<Func<T, object>> parentIdExpression, Expression<Func<T, object>> pkExpression, object rootValue)
			{
				string memberName = ExpressionTool.GetMemberName(pkExpression);
				return (Context.Queryable<T>() as QueryableProvider<T>).GetTreeRoot(childListExpression, parentIdExpression, memberName, list, rootValue);
			}

