			private bool IsObjct(JToken sqlfunc)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)sqlfunc.Type == 1;
			}

			private bool IsArray(string sqlfunc)
			{
				return sqlfunc.StartsWith("[");
			}

			public static bool IsSqlFunc(JToken item, string fileName)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				if ((int)item.Type != 1)
				{
					return fileName.ToLower().Contains("SqlFunc_");
				}
				return true;
			}

			private bool IsObject(JToken parameters)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)parameters.Type == 1;
			}

			private bool IsArray(JToken parameters)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)parameters.Type == 2;
			}

			private bool IsString(JToken parameters)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)parameters.Type == 8;
			}

			private bool IsFieldName(JToken item)
			{
				return item.ObjToString().ToLower().Contains("fieldname");
			}

			private bool IsArraySingleItem(JToken item)
			{
				if (IsArray(item))
				{
					return ((IEnumerable<JToken>)item).Count() == 1;
				}
				return false;
			}

			public ObjectFuncModel JsonToSqlFuncModels(JToken sqlfunc)
			{
				JToken key = ((IEnumerable<JToken>)sqlfunc).First();
				if (IsObjct(sqlfunc))
				{
					return GetFuncModelByObject(key);
				}
				return GetFuncModelByArray(sqlfunc);
			}

			public IFuncModel JsonToSqlFuncModels(string sqlfunc)
			{
				if (IsArray(sqlfunc))
				{
					return GetFuncModelByArray(sqlfunc);
				}
				return GetFuncModelByObject(sqlfunc);
			}

			private ObjectFuncModel GetFuncModelByArray(JToken sqlfunc)
			{
				ObjectFuncModel objectFuncModel = new ObjectFuncModel();
				objectFuncModel.Parameters = new List<object>();
				objectFuncModel.FuncName = "Sqlfunc_Format";
				new StringBuilder();
				foreach (JToken item in (IEnumerable<JToken>)sqlfunc)
				{
					objectFuncModel.Parameters.Add(GetParameter(item));
				}
				return objectFuncModel;
			}

			private ObjectFuncModel GetFuncModelByObject(JToken key)
			{
				ObjectFuncModel objectFuncModel = new ObjectFuncModel();
				JProperty val = key.ToObject<JProperty>();
				objectFuncModel.FuncName = val.Name;
				JToken value = val.Value;
				objectFuncModel.Parameters = GetParameter(value);
				return objectFuncModel;
			}

			private IFuncModel GetFuncModelByObject(string sqlfunc)
			{
				JObject sqlfunc2 = Context.Utilities.DeserializeObject<JObject>(sqlfunc);
				return JsonToSqlFuncModels((JToken)(object)sqlfunc2);
			}

			private IFuncModel GetFuncModelByArray(string sqlfunc)
			{
				ObjectFuncModel objectFuncModel = new ObjectFuncModel();
				objectFuncModel.Parameters = new List<object>();
				objectFuncModel.FuncName = "Sqlfunc_Format";
				JArray obj = Context.Utilities.DeserializeObject<JArray>(sqlfunc);
				new StringBuilder();
				foreach (JToken item in obj)
				{
					objectFuncModel.Parameters.Add(GetParameter(item));
				}
				return objectFuncModel;
			}

			public List<object> GetParameter(JToken parameters)
			{
				List<object> list = new List<object>();
				if (IsString(parameters))
				{
					list.Add(GetStringParameters(parameters));
				}
				else if (IsArray(parameters))
				{
					list.AddRange(GetArrayParameters(parameters));
				}
				else if (IsObject(parameters))
				{
					list.Add(GetObjectParameters(parameters));
				}
				else
				{
					list.Add(GetObjectErrorParameters(parameters));
				}
				return list;
			}

			private static List<object> GetObjectErrorParameters(JToken parameters)
			{
				Check.Exception(true, ErrorMessage.GetThrowMessage(" " + ((object)parameters).ToString() + " format is error ", " " + ((object)parameters).ToString() + " 格式错误"));
				return null;
			}

			public List<object> GetArrayParameters(JToken parameters)
			{
				List<object> list = new List<object>();
				foreach (JToken item in (IEnumerable<JToken>)parameters)
				{
					list.Add(GetParameter(item));
				}
				return list;
			}

			public object GetObjectParameters(JToken parameters)
			{
				return JsonToSqlFuncModels(parameters);
			}

			public object GetStringParameters(JToken parameters)
			{
				return parameters.ObjToString().ToCheckField();
			}

