			private List<Dictionary<string, object>> GetColumnsByArray(string json)
			{
				List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
				foreach (Dictionary<string, object> item in Context.Utilities.DeserializeObject<List<Dictionary<string, object>>>(json))
				{
					list.Add(GetColumns(item));
				}
				return list;
			}

			private Dictionary<string, object> GetColumns(Dictionary<string, object> dictionary)
			{
				Dictionary<string, object> dictionary2 = new Dictionary<string, object>();
				foreach (KeyValuePair<string, object> item in dictionary)
				{
					object value = GetValue(item);
					dictionary2.Add(item.Key, value);
				}
				return dictionary2;
			}

			private static object GetValue(KeyValuePair<string, object> item)
			{
				if (item.Value == null)
				{
					return null;
				}
				string? valueString = item.Value.ToString();
				return UtilMethods.ConvertDataByTypeName(value: Json2SqlHelper.GetValue(valueString), ctypename: Json2SqlHelper.GetType(valueString));
			}

