			public List<OrderByModel> JsonToOrderByModels(string json)
			{
				//IL_0043: Unknown result type (might be due to invalid IL or missing references)
				//IL_0049: Invalid comparison between Unknown and I4
				//IL_006a: Unknown result type (might be due to invalid IL or missing references)
				//IL_0070: Invalid comparison between Unknown and I4
				List<OrderByModel> list = new List<OrderByModel>();
				foreach (JToken item2 in Context.Utilities.DeserializeObject<JArray>(json))
				{
					if (IsFieldName(item2))
					{
						OrderByModel item = item2.ToObject<OrderByModel>();
						list.Add(item);
					}
					else if ((int)item2.Type == 8)
					{
						list.Add(new OrderByModel
						{
							FieldName = item2.ObjToString().ToCheckField()
						});
					}
					else if ((int)item2.Type == 2)
					{
						list.Add(new OrderByModel
						{
							FieldName = item2[(object)0].ObjToString(),
							OrderByType = ((item2[(object)1].ObjToString().ToLower() == "desc") ? OrderByType.Desc : OrderByType.Asc)
						});
					}
				}
				return list;
			}

			public List<SelectModel> JsonToSelectModels(string json)
			{
				List<SelectModel> list = new List<SelectModel>();
				foreach (JToken item2 in Context.Utilities.DeserializeObject<JArray>(json))
				{
					if (IsFieldName(item2))
					{
						SelectModel item = item2.ToObject<SelectModel>();
						list.Add(item);
					}
					else if (IsString(item2))
					{
						list.Add(new SelectModel
						{
							FieldName = item2.ObjToString().ToCheckField(),
							AsName = item2.ObjToString().Replace(".", "_")
						});
					}
					else if (IsArraySingleItem(item2))
					{
						object obj = item2[(object)0].ObjToString();
						string asName = item2[(object)0].ObjToString().Replace(".", "_");
						if (IsSqlFunc(item2[(object)0], obj.ObjToString()))
						{
							obj = JsonToSqlFuncModels(item2[(object)0]);
						}
						list.Add(new SelectModel
						{
							FieldName = obj,
							AsName = asName
						});
					}
					else if (IsArray(item2))
					{
						object obj2 = item2[(object)0].ObjToString();
						string asName2 = item2[(object)1].ObjToString().Replace(".", "_");
						if (IsSqlFunc(item2[(object)0], obj2.ObjToString()))
						{
							obj2 = JsonToSqlFuncModels(item2[(object)0]);
						}
						list.Add(new SelectModel
						{
							FieldName = obj2,
							AsName = asName2
						});
					}
					else
					{
						list.Add(new SelectModel
						{
							FieldName = item2.ObjToString().Trim(),
							AsName = item2.ObjToString().Trim()
						});
					}
				}
				return list;
			}
		}
		internal class DependencyManagement
		{
			private static bool IsTryJsonNet;

			private static bool IsTryMySqlData;

			private static bool IsTrySqlite;

			private static bool IsTryOracle;

			public static void TryJsonNet()
			{
				if (!IsTryJsonNet)
				{
					try
					{
						new SerializeService().SerializeObject(new { });
						IsTryJsonNet = true;
					}
					catch
					{
						throw new Exception(ErrorMessage.GetThrowMessage(" Snet.DB.sugar Some functions are used in newtonsoft ,Nuget references Newtonsoft.Json 9.0.0.1 + .", " Snet.DB.sugar 部分功能用到Newtonsoft.Json.dll，需要在Nuget上安装 Newtonsoft.Json 9.0.0.1及以上版本，如果有版本兼容问题请先删除原有引用"));
					}
				}
			}

			public static void TryMySqlData()
			{
				if (!IsTryMySqlData)
				{
					try
					{
						new MySqlProvider().GetAdapter();
						IsTryMySqlData = true;
					}
					catch
					{
						throw new Exception(ErrorMessage.GetThrowMessage("You need to refer to MySql.Data.dll", "需要引用MySql.Data.dll，请在Nuget安装最新稳定版本,如果有版本兼容问题请先删除原有引用"));
					}
				}
