						new OracleProvider().GetAdapter();
						IsTryOracle = true;
					}
					catch
					{
						throw new Exception(ErrorMessage.GetThrowMessage("You need to refer to Oracle.ManagedDataAccess.Core", "你需要引用 Oracle.ManagedDataAccess.Core"));
