			public static UpdateableProvider<T> GetUpdateableProvider<T>(ConnectionConfig currentConnectionConfig) where T : class, new()
			{
				if (currentConnectionConfig.DbType == DbType.Oracle)
				{
					return new OracleUpdateable<T>();
				}
				if (IsCustomDb(currentConnectionConfig))
				{
					Type customTypeByClass = GetCustomTypeByClass<T>("Snet.DB.sugar." + currentConnectionConfig.DbType.ToString() + "." + currentConnectionConfig.DbType.ToString() + "Updateable`1");
					if (customTypeByClass == null)
					{
						customTypeByClass = GetCustomTypeByClass<T>(CustomNamespace + "." + CustomDbName + "Updateable`1");
					}
					if (customTypeByClass == null)
					{
						return new UpdateableProvider<T>();
					}
					return (UpdateableProvider<T>)Activator.CreateInstance(customTypeByClass, nonPublic: true);
				}
				return new UpdateableProvider<T>();
			}

