			private static bool IsCustomDb(ConnectionConfig currentConnectionConfig)
			{
				if (currentConnectionConfig.DbType != DbType.SqlServer && currentConnectionConfig.DbType != DbType.MySql && currentConnectionConfig.DbType != DbType.Oracle && currentConnectionConfig.DbType != DbType.Sqlite)
				{
					return GetCustomTypeByClass("Snet.DB.sugar." + currentConnectionConfig.DbType.ToString() + "." + currentConnectionConfig.DbType.ToString() + "Provider") != null;
				}
				return false;
			}

