			private static string GetClassName(string type, string name)
			{
				return type switch
				{
					"Access" => "Snet.DB.sugar.Access.Access" + name, 
					"ClickHouse" => "Snet.DB.sugar.ClickHouse.ClickHouse" + name, 
					"GBase" => "Snet.DB.sugar.GBase.GBase" + name, 
					"Odbc" => "Snet.DB.sugar.Odbc.Odbc" + name, 
					"Custom" => CustomNamespace + "." + CustomDbName + name, 
					"HANA" => CustomDllName + "." + type + name, 
					"DB2" => "Snet.DB.sugar.DB2." + type + name, 
					"GaussDBNative" => "Snet.DB.sugar.GaussDB.GaussDB" + name, 
					_ => "Snet.DB.sugar." + type + name, 
				};
			}

