			private static Restult CreateInstance<Restult>(string className, params Type[] types)
			{
				try
				{
					if (NoCache)
					{
						return NoCacheGetCacheInstance<Restult>(className, types);
					}
					return GetCacheInstance<Restult>(className, types);
				}
				catch
				{
					NoCache = true;
					return NoCacheGetCacheInstance<Restult>(className, types);
				}
			}

			private static Restult GetCacheInstance<Restult>(string className, Type[] types)
			{
				string key = className + string.Join(",", types.Select((Type it) => it.FullName));
				Type value = null;
				if (!typeCache.TryGetValue(key, out value))
				{
					lock (typeCache)
					{
						if (!typeCache.TryGetValue(key, out value))
						{
							if (string.IsNullOrEmpty(CustomDllName))
							{
								value = Type.GetType(className + "`" + types.Length, throwOnError: true).MakeGenericType(types);
							}
							else
							{
								Type customTypeByClass = GetCustomTypeByClass(className + "`" + types.Length);
								if (customTypeByClass != null)
								{
									value = customTypeByClass.MakeGenericType(types);
								}
								if (value == null)
								{
									value = Type.GetType(className + "`" + types.Length, throwOnError: true).MakeGenericType(types);
								}
							}
							Check.ArgumentNullException(value, string.Format(ErrorMessage.ObjNotExist, className));
							typeCache[key] = value;
						}
					}
				}
				return (Restult)Activator.CreateInstance(value, nonPublic: true);
			}

			private static Restult NoCacheGetCacheInstance<Restult>(string className, Type[] types)
			{
				Type type = null;
				if (string.IsNullOrEmpty(CustomDllName))
				{
					type = Type.GetType(className + "`" + types.Length, throwOnError: true).MakeGenericType(types);
				}
				else
				{
					Type customTypeByClass = GetCustomTypeByClass(className + "`" + types.Length);
					if (customTypeByClass != null)
					{
						type = customTypeByClass.MakeGenericType(types);
					}
					if (type == null)
					{
						type = Type.GetType(className + "`" + types.Length)?.MakeGenericType(types);
						if (type == null)
						{
							type = GetCustomDbType(className + "`" + types.Length, type).MakeGenericType(types);
						}
					}
				}
				return (Restult)Activator.CreateInstance(type, nonPublic: true);
			}

			public static T CreateInstance<T>(string className)
			{
				try
				{
					if (NoCache)
					{
						return NoCacheGetCacheInstance<T>(className);
					}
					return GetCacheInstance<T>(className);
				}
				catch
				{
					return NoCacheGetCacheInstance<T>(className);
				}
			}

			private static T GetCacheInstance<T>(string className)
			{
				Type type;
				if (typeCache.ContainsKey(className))
				{
					type = typeCache[className];
				}
				else
				{
					lock (typeCache)
					{
						if (string.IsNullOrEmpty(CustomDllName))
						{
							type = assembly.GetType(className);
						}
						else
						{
							type = GetCustomTypeByClass(className);
							if (type == null)
							{
								type = assembly.GetType(className);
							}
						}
						if (type == null)
						{
							type = GetCustomDbType(className, type);
						}
						Check.ArgumentNullException(type, string.Format(ErrorMessage.ObjNotExist, className));
						if (!typeCache.ContainsKey(className))
						{
							typeCache.Add(className, type);
						}
					}
				}
				return (T)Activator.CreateInstance(type, nonPublic: true);
			}

			private static T NoCacheGetCacheInstance<T>(string className)
			{
				Type type = null;
				type = ((!string.IsNullOrEmpty(CustomDllName)) ? GetCustomTypeByClass(className) : assembly.GetType(className));
				if (type == null)
				{
					type = GetCustomDbType(className, type);
				}
				return (T)Activator.CreateInstance(type, nonPublic: true);
			}

			private static Type GetCustomDbType(string className, Type type)
			{
				if (className.Replace(".", "").Length + 1 == className.Length)
				{
					string[] source = className.Split('.');
					foreach (KeyValuePair<string, DbType> item in UtilMethods.EnumToDictionary<DbType>())
					{
						if (source.Last().StartsWith(item.Value.ToString()))
						{
							type = GetCustomTypeByClass(source.First() + "." + item.Value.ToString() + "." + source.Last());
							break;
						}
					}
				}
				return type;
			}

			internal static Type GetCustomTypeByClass(string className)
			{
				Type type = null;
				string[] array = CustomDlls.ToArray();
				foreach (string customDllName in array)
				{
					if (type == null)
					{
						type = GetCustomTypeByClass(className, customDllName);
					}
					if (type != null)
					{
						break;
					}
				}
				return type;
			}

			internal static Type GetCustomTypeByClass(string className, string customDllName)
			{
				string cacheKey = "Assembly_" + customDllName + assembly.GetHashCode();
				Type type = new ReflectionInoCacheService().GetOrCreate(cacheKey, delegate
				{
					try
					{
						if (string.IsNullOrEmpty(customDllName))
						{
							Assembly[] customAssemblies = CustomAssemblies;
							if (customAssemblies != null && customAssemblies.Any())
							{
								customDllName = CustomAssemblies.First().GetName().Name;
							}
						}
						Assembly[] customAssemblies2 = CustomAssemblies;
						if (customAssemblies2 != null && customAssemblies2.Any((Assembly it) => it.FullName.StartsWith(customDllName)))
						{
							return CustomAssemblies?.First((Assembly it) => it.FullName.StartsWith(customDllName));
						}
						string text = Assembly.GetExecutingAssembly().Location;
						if (text.HasValue())
						{
							text = Path.Combine(Path.GetDirectoryName(text), customDllName + ".dll");
						}
						if (text.HasValue() && FileHelper.IsExistFile(text))
						{
							return Assembly.LoadFrom(text);
						}
						if (IsWebFrom)
						{
							return Assembly.LoadFrom((Path.GetDirectoryName(Assembly.GetExecutingAssembly().GetName().CodeBase) + "\\" + customDllName + ".dll").Replace("file:\\", ""));
						}
						return Assembly.LoadFrom(customDllName + ".dll");
					}
					catch
					{
						string message = "Not Found " + customDllName + ".dll";
						Check.Exception(true, message);
						return (Assembly)null;
					}
				}).GetType(className);
				if (type == null)
				{
					type = assembly.GetType(className);
				}
				return type;
			}

			internal static Type GetCustomTypeByClass<T>(string className)
			{
				Type type = null;
				string[] array = CustomDlls.ToArray();
				foreach (string customDllName in array)
				{
					if (type == null)
					{
						type = GetCustomTypeByClass<T>(className, customDllName);
					}
					if (type != null)
					{
						break;
					}
				}
				return type;
			}

			internal static Type GetCustomTypeByClass<T>(string className, string customDllName)
			{
				string cacheKey = "Assembly_" + customDllName + assembly.GetHashCode();
				Assembly orCreate = new ReflectionInoCacheService().GetOrCreate(cacheKey, delegate
				{
					try
					{
						Assembly[] customAssemblies = CustomAssemblies;
						if (customAssemblies != null && customAssemblies.Any((Assembly it) => it.FullName.StartsWith(customDllName)))
						{
							return CustomAssemblies?.First((Assembly it) => it.FullName.StartsWith(customDllName));
						}
						string text = Assembly.GetExecutingAssembly().Location;
						if (text.HasValue())
						{
							text = Path.Combine(Path.GetDirectoryName(text), customDllName + ".dll");
						}
						if (text.HasValue() && FileHelper.IsExistFile(text))
						{
							return Assembly.LoadFrom(text);
						}
						if (IsWebFrom)
						{
							return Assembly.LoadFrom((Path.GetDirectoryName(Assembly.GetExecutingAssembly().GetName().CodeBase) + "\\" + customDllName + ".dll").Replace("file:\\", ""));
						}
						return Assembly.LoadFrom(customDllName + ".dll");
					}
					catch
					{
						string message = "Not Found " + customDllName + ".dll";
						Check.Exception(true, message);
						return (Assembly)null;
					}
				});
				Type typeFromHandle = typeof(T);
				string name = className + "[[" + typeFromHandle.FullName + "," + typeFromHandle.Assembly.FullName + "]]";
				return orCreate.GetType(name);
			}
		}
		public class SugarMapper
		{
			private ISqlSugarClient _context;

			public SugarMapper(ISqlSugarClient context)
			{
				_context = context;
			}

			public string GetSelectValue<TResult>(QueryBuilder queryBuilder)
			{
				_ = string.Empty;
				EntityInfo entityInfo = _context.EntityMaintenance.GetEntityInfo<TResult>();
				LambdaExpression obj = queryBuilder.JoinExpression as LambdaExpression;
				List<KeyValuePair<string, JoinMapper>> list = new List<KeyValuePair<string, JoinMapper>>();
				var list2 = obj.Parameters.Select((ParameterExpression it) => new
				{
					shortName = it.Name,
					type = it.Type
				}).ToList();
				foreach (EntityColumnInfo viewColumns in entityInfo.Columns)
				{
					bool flag = false;
					foreach (var expPars in list2)
					{
						if (flag)
						{
							break;
						}
						var anon = _context.EntityMaintenance.GetEntityInfo(expPars.type).Columns.Where((EntityColumnInfo it) => !it.IsIgnore).Select(delegate(EntityColumnInfo it)
						{
							string[] array = new string[8]
							{
								it.PropertyName,
								it.DbColumnName,
								expPars.type.Name + it.PropertyName,
								expPars.type.Name + it.DbColumnName,
								expPars.type.Name + "_" + it.PropertyName,
								expPars.type.Name + "_" + it.DbColumnName,
								expPars.shortName + it.PropertyName,
								expPars.shortName + it.DbColumnName
							};
							return new { it, array };
						}).ToList()
							.FirstOrDefault(y => y.array.Select((string z) => z.ToLower()).Contains(viewColumns.PropertyName.ToLower()));
						if (anon != null)
						{
							JoinMapper value = new JoinMapper
							{
								AsName = viewColumns.PropertyName,
								DbName = anon.it.DbColumnName
							};
							string translationColumnName = queryBuilder.Builder.GetTranslationColumnName(expPars.shortName);
							list.Add(new KeyValuePair<string, JoinMapper>(translationColumnName, value));
							flag = true;
						}
					}
				}
				return queryBuilder.GetSelectByItems(list);
			}
		}
