		public class ReflectionInoCacheService : ICacheService
		{
			public void Add<V>(string key, V value)
			{
				ReflectionInoCore<V>.GetInstance().Add(key, value);
			}

			public void Add<V>(string key, V value, int cacheDurationInSeconds)
			{
				ReflectionInoCore<V>.GetInstance().Add(key, value, cacheDurationInSeconds);
			}

			public bool ContainsKey<V>(string key)
			{
				return ReflectionInoCore<V>.GetInstance().ContainsKey(key);
			}

			public V Get<V>(string key)
			{
				return ReflectionInoCore<V>.GetInstance().Get(key);
			}

			public IEnumerable<string> GetAllKey<V>()
			{
				return ReflectionInoCore<V>.GetInstance().GetAllKey();
			}

			public V GetOrCreate<V>(string cacheKey, Func<V> create, int cacheDurationInSeconds = int.MaxValue)
			{
				return ReflectionInoCore<V>.GetInstance().GetOrCreate(cacheKey, create);
			}

			public void Remove<V>(string key)
			{
				ReflectionInoCore<V>.GetInstance().Remove(key);
			}
		}
		public class ReflectionInoCore<V>
		{
			private readonly ConcurrentDictionary<string, V> InstanceCache = new ConcurrentDictionary<string, V>();

			private static ReflectionInoCore<V> _instance = null;

			private static readonly object _instanceLock = new object();

			public V this[string key] => Get(key);

			private ReflectionInoCore()
			{
			}

			public bool ContainsKey(string key)
			{
				return InstanceCache.ContainsKey(key);
			}

			public V Get(string key)
			{
				if (ContainsKey(key))
				{
					return InstanceCache[key];
				}
				return default(V);
			}

			public static ReflectionInoCore<V> GetInstance()
			{
				if (_instance == null)
				{
					lock (_instanceLock)
					{
						if (_instance == null)
						{
							_instance = new ReflectionInoCore<V>();
							ReflectionInoHelper.AddRemoveFunc(delegate
							{
								GetInstance().RemoveAllCache();
							});
						}
					}
				}
				return _instance;
			}

			public void Add(string key, V value)
			{
				InstanceCache.GetOrAdd(key, value);
			}

			public void Add(string key, V value, int cacheDurationInSeconds)
			{
				Check.ThrowNotSupportedException("ReflectionInoCache.Add(string key, V value, int cacheDurationInSeconds)");
			}

			public void Remove(string key)
			{
				InstanceCache.TryRemove(key, out var _);
			}

			public void RemoveAllCache()
			{
				foreach (string item in GetAllKey())
				{
					Remove(item);
				}
			}

			public IEnumerable<string> GetAllKey()
			{
				return InstanceCache.Keys;
			}

			public V GetOrCreate(string cacheKey, Func<V> create)
			{
				if (ContainsKey(cacheKey))
				{
					return Get(cacheKey);
				}
				V val = create();
				Add(cacheKey, val);
				return val;
			}
		}
		internal static class ReflectionInoHelper
		{
			private static List<Action> removeActions = new List<Action>();

			internal static void AddRemoveFunc(Action removeAction)
			{
				removeActions.Add(removeAction);
			}

			public static void RemoveAllCache()
			{
				lock (removeActions)
				{
					foreach (Action removeAction in removeActions)
					{
						removeAction();
					}
				}
			}
		}
		public class SerializeService : ISerializeService
		{
			public string SerializeObject(object value)
			{
				if (value != null && value.GetType().FullName.StartsWith("System.Text.Json."))
				{
					return (string)value.GetType().Assembly.GetType("System.Text.Json.JsonSerializer").GetMyMethod("Serialize", 2).MakeGenericMethod(value.GetType())
						.Invoke(null, new object[2] { value, null });
				}
				return JsonConvert.SerializeObject(value);
			}

			public string SugarSerializeObject(object value)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				//IL_0016: Expected O, but got Unknown
				return JsonConvert.SerializeObject(value, new JsonSerializerSettings
				{
					ContractResolver = (IContractResolver)(object)new MyContractResolver()
				});
			}

			public T DeserializeObject<T>(string value)
			{
				//IL_00b7: Unknown result type (might be due to invalid IL or missing references)
				//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
				//IL_00c4: Expected O, but got Unknown
				if (typeof(T).FullName.StartsWith("System.Text.Json."))
				{
					return (T)(from it in typeof(T).Assembly.GetType("System.Text.Json.JsonSerializer").GetMethods()
						where it.Name == "Deserialize"
						where it.GetParameters().Any((ParameterInfo z) => z.ParameterType == typeof(string))
						select it).First().MakeGenericMethod(typeof(T)).Invoke(null, new object[2] { value, null });
				}
				JsonSerializerSettings val = new JsonSerializerSettings
				{
					NullValueHandling = (NullValueHandling)1
				};
				return JsonConvert.DeserializeObject<T>(value, val);
			}
		}
		public class MyContractResolver : DefaultContractResolver
		{
			protected override IList<JsonProperty> CreateProperties(Type type, MemberSerialization memberSerialization)
			{
				//IL_0031: Unknown result type (might be due to invalid IL or missing references)
				if (type.IsAnonymousType() || type == UtilConstants.ObjType || type.Namespace == "Snet.DB.sugar" || !type.IsClass())
				{
					return ((DefaultContractResolver)this).CreateProperties(type, memberSerialization);
				}
				List<JsonProperty> list = (from x in type.GetProperties()
					where !x.GetCustomAttributes(inherit: true).Any((object a) => a is SugarColumn && ((SugarColumn)a).NoSerialize)
					select x).Select((Func<PropertyInfo, JsonProperty>)delegate(PropertyInfo p)
				{
					//IL_0000: Unknown result type (might be due to invalid IL or missing references)
					//IL_0005: Unknown result type (might be due to invalid IL or missing references)
					//IL_0011: Unknown result type (might be due to invalid IL or missing references)
					//IL_001d: Unknown result type (might be due to invalid IL or missing references)
					//IL_0024: Unknown result type (might be due to invalid IL or missing references)
					//IL_002b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0039: Expected O, but got Unknown
					return new JsonProperty
					{
						PropertyName = p.Name,
						PropertyType = p.PropertyType,
						Readable = true,
						Writable = true,
						ValueProvider = ((DefaultContractResolver)this).CreateMemberValueProvider((MemberInfo)p)
					};
				}).ToList();
				foreach (JsonProperty item in list)
				{
					if (UtilMethods.GetUnderType(item.PropertyType) == UtilConstants.DateType)
					{
						CreateDateProperty(type, item);
					}
				}
				return list;
			}

			private static void CreateDateProperty(Type type, JsonProperty item)
			{
				//IL_0095: Unknown result type (might be due to invalid IL or missing references)
				//IL_009a: Unknown result type (might be due to invalid IL or missing references)
				//IL_00ab: Expected O, but got Unknown
				PropertyInfo propertyInfo = (from it in type.GetProperties()
					where it.Name == item.PropertyName
					select it).First();
				UtilMethods.GetUnderType(propertyInfo);
				if (propertyInfo.GetCustomAttributes(inherit: true).Any((object it) => it is SugarColumn))
				{
					SugarColumn sugarColumn = (SugarColumn)propertyInfo.GetCustomAttributes(inherit: true).First((object it) => it is SugarColumn);
					item.Converter = (JsonConverter)new IsoDateTimeConverter
					{
						DateTimeFormat = sugarColumn.SerializeDateTimeFormat
					};
				}
			}
		}
		public class DateSplitTableService : ISplitTableService
		{
			internal class SplitTableSort
			{
				public string Name { get; set; }

				public int Sort { get; set; }
			}

			public virtual List<SplitTableInfo> GetAllTables(ISqlSugarClient db, EntityInfo EntityInfo, List<DbTableInfo> tableInfos)
			{
				CheckTableName(EntityInfo.DbTableName);
				string regex = "^" + EntityInfo.DbTableName.Replace("{year}", "([0-9]{2,4})").Replace("{day}", "([0-9]{1,2})").Replace("{month}", "([0-9]{1,2})");
				List<string> list = (from it in tableInfos
					where Regex.IsMatch(it.Name, regex, RegexOptions.IgnoreCase)
					select it.Name).Reverse().ToList();
				List<SplitTableInfo> list2 = new List<SplitTableInfo>();
				foreach (string item in list)
				{
					SplitTableInfo splitTableInfo = new SplitTableInfo();
					splitTableInfo.TableName = item;
					Match match = Regex.Match(item, regex, RegexOptions.IgnoreCase);
					string value = match.Groups[1].Value;
					string value2 = match.Groups[2].Value;
					string value3 = match.Groups[3].Value;
					splitTableInfo.Date = GetDate(value, value2, value3, EntityInfo.DbTableName);
					list2.Add(splitTableInfo);
				}
				return list2.OrderByDescending((SplitTableInfo it) => it.Date).ToList();
			}

			public virtual string GetTableName(ISqlSugarClient db, EntityInfo EntityInfo)
			{
				SplitTableAttribute customAttribute = EntityInfo.Type.GetCustomAttribute<SplitTableAttribute>();
				if (customAttribute != null)
				{
					SplitType splitType = customAttribute.SplitType;
					return GetTableName(db, EntityInfo, splitType);
				}
				return GetTableName(db, EntityInfo, SplitType.Day);
			}

			public virtual string GetTableName(ISqlSugarClient db, EntityInfo EntityInfo, SplitType splitType)
			{
				DateTime date = db.GetDate();
				return GetTableNameByDate(EntityInfo, splitType, date);
			}

			public virtual string GetTableName(ISqlSugarClient db, EntityInfo entityInfo, SplitType splitType, object fieldValue)
			{
				DateTime date = Convert.ToDateTime(fieldValue);
				return GetTableNameByDate(entityInfo, splitType, date);
			}

			public virtual object GetFieldValue(ISqlSugarClient db, EntityInfo entityInfo, SplitType splitType, object entityValue)
			{
				EntityColumnInfo entityColumnInfo = entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.PropertyInfo.GetCustomAttribute<SplitFieldAttribute>() != null);
				if (entityColumnInfo == null)
				{
					return db.GetDate();
				}
				if (entityValue == null)
				{
					return null;
				}
				object value = entityColumnInfo.PropertyInfo.GetValue(entityValue, null);
				if (value == null)
				{
					return db.GetDate();
				}
				if (value is DateTimeOffset dateTimeOffset)
				{
					return dateTimeOffset.DateTime;
				}
				if (UtilMethods.GetUnderType(value.GetType()) != UtilConstants.DateType)
				{
					throw new Exception("DateSplitTableService Split column " + entityColumnInfo.PropertyName + " not DateTime " + splitType);
				}
				if (Convert.ToDateTime(value) == DateTime.MinValue)
				{
					return db.GetDate();
				}
				return value;
			}

			public void VerifySplitType(SplitType splitType)
			{
				switch (splitType)
				{
				case SplitType.Day:
				case SplitType.Week:
				case SplitType.Month:
				case SplitType.Season:
				case SplitType.Year:
				case SplitType.Month_6:
					return;
				}
				throw new Exception("DateSplitTableService no support " + splitType);
			}

			private string GetTableNameByDate(EntityInfo EntityInfo, SplitType splitType, DateTime date)
			{
				date = ConvertDateBySplitType(date, splitType);
				return EntityInfo.DbTableName.Replace("{year}", date.Year.ToString() ?? "").Replace("{day}", PadLeft2(date.Day.ToString() ?? "")).Replace("{month}", PadLeft2(date.Month.ToString() ?? ""));
			}

			private DateTime GetDate(string group1, string group2, string group3, string dbTableName)
			{
				int sort = dbTableName.IndexOf("{year}");
				int sort2 = dbTableName.IndexOf("{day}");
				int sort3 = dbTableName.IndexOf("{month}");
				List<SplitTableSort> list = new List<SplitTableSort>
				{
					new SplitTableSort
					{
						Name = "{year}",
						Sort = sort
					},
					new SplitTableSort
					{
						Name = "{day}",
						Sort = sort2
					},
					new SplitTableSort
					{
						Name = "{month}",
						Sort = sort3
					}
				}.OrderBy((SplitTableSort it) => it.Sort).ToList();
				string value = "";
				string value2 = "";
				string value3 = "";
				if (list[0].Name == "{year}")
				{
					value = group1;
				}
				if (list[1].Name == "{year}")
				{
					value = group2;
				}
				if (list[2].Name == "{year}")
				{
					value = group3;
				}
				if (list[0].Name == "{month}")
				{
					value2 = group1;
				}
				if (list[1].Name == "{month}")
				{
					value2 = group2;
				}
				if (list[2].Name == "{month}")
				{
					value2 = group3;
				}
				if (list[0].Name == "{day}")
				{
					value3 = group1;
				}
				if (list[1].Name == "{day}")
				{
					value3 = group2;
				}
				if (list[2].Name == "{day}")
				{
					value3 = group3;
				}
				return Convert.ToDateTime($"{value}-{value2}-{value3}", CultureInfo.InvariantCulture);
			}

			private string PadLeft2(string str)
			{
				if (str.Length < 2)
				{
					return str.PadLeft(2, '0');
				}
				return str;
			}

			private static void CheckTableName(string dbTableName)
			{
				Check.Exception(!dbTableName.Contains("{year}"), ErrorMessage.GetThrowMessage("table name need {{year}}", "分表表名需要占位符 {{year}}"));
				Check.Exception(!dbTableName.Contains("{month}"), ErrorMessage.GetThrowMessage("table name need {{month}}", "分表表名需要占位符 {{month}} "));
				Check.Exception(!dbTableName.Contains("{day}"), ErrorMessage.GetThrowMessage("table name need {{day}}", "分表表名需要占位符{{day}}"));
				Check.Exception(Regex.Matches(dbTableName, "\\{year\\}").Count > 1, ErrorMessage.GetThrowMessage(" There can only be one {{year}}", " 只能有一个 {{year}}"));
				Check.Exception(Regex.Matches(dbTableName, "\\{month\\}").Count > 1, ErrorMessage.GetThrowMessage("There can only be one {{month}}", "只能有一个 {{month}} "));
				Check.Exception(Regex.Matches(dbTableName, "\\{day\\}").Count > 1, ErrorMessage.GetThrowMessage("There can only be one {{day}}", "只能有一个{{day}}"));
				Check.Exception(Regex.IsMatch(dbTableName, "\\d\\{|\\}\\d"), ErrorMessage.GetThrowMessage(" '{{' or  '}}'  can't be numbers nearby", "占位符相令一位不能是数字,比如 : 1{{day}}2 错误 , 正确: 1_{{day}}_2"));
			}

			private DateTime ConvertDateBySplitType(DateTime time, SplitType type)
			{
				switch (type)
				{
				case SplitType.Day:
					return Convert.ToDateTime(time.ToString("yyyy-MM-dd"));
				case SplitType.Week:
					return GetMondayDate(time);
				case SplitType.Month:
					return Convert.ToDateTime(time.ToString("yyyy-MM-01"));
				case SplitType.Season:
					if (time.Month <= 3)
					{
						return Convert.ToDateTime(time.ToString("yyyy-01-01"));
					}
					if (time.Month <= 6)
					{
						return Convert.ToDateTime(time.ToString("yyyy-04-01"));
					}
					if (time.Month <= 9)
					{
						return Convert.ToDateTime(time.ToString("yyyy-07-01"));
					}
					return Convert.ToDateTime(time.ToString("yyyy-10-01"));
				case SplitType.Year:
					return Convert.ToDateTime(time.ToString("yyyy-01-01"));
				case SplitType.Month_6:
					if (time.Month <= 6)
					{
						return Convert.ToDateTime(time.ToString("yyyy-01-01"));
					}
					return Convert.ToDateTime(time.ToString("yyyy-07-01"));
				default:
					throw new Exception("SplitType parameter error ");
				}
			}

			private DateTime GetMondayDate()
			{
				return GetMondayDate(DateTime.Now);
			}

			private DateTime GetSundayDate()
			{
				return GetSundayDate(DateTime.Now);
			}

			private DateTime GetMondayDate(DateTime someDate)
			{
				int num = (int)(someDate.DayOfWeek - 1);
				if (num == -1)
				{
					num = 6;
				}
				TimeSpan value = new TimeSpan(num, 0, 0, 0);
				return someDate.Subtract(value);
			}

			private DateTime GetSundayDate(DateTime someDate)
			{
				int num = (int)(someDate.DayOfWeek - 0);
				if (num != 0)
				{
					num = 7 - num;
				}
				TimeSpan value = new TimeSpan(num, 0, 0, 0);
				return someDate.Add(value);
			}
		}
