		public class StorageableInfo<T> where T : class, new()
		{
			public T Item { get; set; }

			internal List<T> Database { get; set; }

			internal string[] PkFields { get; set; }

			public bool Any(Func<T, bool> expression)
			{
				return Database.Any(expression);
			}

			public bool NotAny(Func<T, bool> expression)
			{
				return !Database.Any(expression);
			}

			public bool Any()
			{
				IEnumerable<T> source = Database.Where((T it) => true);
				string[] pkFields = PkFields;
				foreach (string pk in pkFields)
				{
					source = source.Where((T it) => IsEquals(it, pk));
				}
				return source.Any();
			}

			private bool IsEquals(T it, string pk)
			{
				object value = it.GetType().GetProperty(pk).GetValue(it, null);
				object value2 = Item.GetType().GetProperty(pk).GetValue(Item, null);
				string thisValue = value.ObjToString();
				string equalValue = value2.ObjToString();
				if (value != null && (value is decimal || value is decimal?))
				{
					return Convert.ToDecimal(value) == Convert.ToDecimal(value2);
				}
				return thisValue.EqualCase(equalValue);
			}

			public bool NotAny()
			{
				return !Any();
			}
		}
