		public class StorageableResult<T> where T : class, new()
		{
			public List<StorageableMessage<T>> TotalList { get; set; }

			public List<StorageableMessage<T>> InsertList { get; set; }

			public List<StorageableMessage<T>> UpdateList { get; set; }

			public List<StorageableMessage<T>> DeleteList { get; set; }

			public List<StorageableMessage<T>> ErrorList { get; set; }

			public List<StorageableMessage<T>> IgnoreList { get; set; }

			public List<StorageableMessage<T>> OtherList { get; set; }

			public IInsertable<T> AsInsertable { get; set; }

			public IUpdateable<T> AsUpdateable { get; set; }

			public IDeleteable<T> AsDeleteable { get; set; }

			internal List<EntityColumnInfo> _WhereColumnList { get; set; }

			internal string _AsName { get; set; }

			internal SqlSugarProvider _Context { get; set; }

			public int BulkCopy()
			{
				return _Context.Fastest<T>().AS(_AsName).BulkCopy(InsertList.Select((StorageableMessage<T> it) => it.Item).ToList());
			}

			public Task<int> BulkCopyAsync()
			{
				return _Context.Fastest<T>().AS(_AsName).BulkCopyAsync(InsertList.Select((StorageableMessage<T> it) => it.Item).ToList());
			}

			public int BulkUpdate()
			{
				if (_WhereColumnList != null && _WhereColumnList.Any())
				{
					string[] updateColumns = (from it in _Context.EntityMaintenance.GetEntityInfo<T>().Columns
						where !it.IsPrimarykey && !it.IsIdentity && !it.IsOnlyIgnoreUpdate && !it.IsIgnore
						select it.DbColumnName ?? it.PropertyName).ToArray();
					return BulkUpdate(updateColumns);
				}
				return _Context.Fastest<T>().AS(_AsName).BulkUpdate(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList());
			}

			public Task<int> BulkUpdateAsync()
			{
				if (_WhereColumnList != null && _WhereColumnList.Any())
				{
					string[] updateColumns = (from it in _Context.EntityMaintenance.GetEntityInfo<T>().Columns
						where !it.IsPrimarykey && !it.IsIdentity && !it.IsOnlyIgnoreUpdate && !it.IsIgnore
						select it.DbColumnName ?? it.PropertyName).ToArray();
					return BulkUpdateAsync(updateColumns);
				}
				return _Context.Fastest<T>().AS(_AsName).BulkUpdateAsync(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList());
			}

			public int BulkUpdate(params string[] UpdateColumns)
			{
				Check.Exception(UpdateColumns == null, "UpdateColumns is null");
				if (_WhereColumnList != null && _WhereColumnList.Any())
				{
					return _Context.Fastest<T>().AS(_AsName).BulkUpdate(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList(), _WhereColumnList.Select((EntityColumnInfo it) => it.DbColumnName).ToArray(), UpdateColumns);
				}
				string[] array = (from it in _Context.EntityMaintenance.GetEntityInfo<T>().Columns
					where it.IsPrimarykey
					select it.DbColumnName).ToArray();
				Check.Exception(array.Count() == 0, "need primary key");
				return _Context.Fastest<T>().AS(_AsName).BulkUpdate(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList(), array, UpdateColumns);
			}

			public async Task<int> BulkUpdateAsync(params string[] UpdateColumns)
			{
				Check.Exception(UpdateColumns == null, "UpdateColumns is null");
				if (_WhereColumnList != null && _WhereColumnList.Any())
				{
					return await _Context.Fastest<T>().AS(_AsName).BulkUpdateAsync(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList(), _WhereColumnList.Select((EntityColumnInfo it) => it.DbColumnName).ToArray(), UpdateColumns);
				}
				string[] array = (from it in _Context.EntityMaintenance.GetEntityInfo<T>().Columns
					where it.IsPrimarykey
					select it.DbColumnName).ToArray();
				Check.Exception(array.Count() == 0, "need primary key");
				return await _Context.Fastest<T>().AS(_AsName).BulkUpdateAsync(UpdateList.Select((StorageableMessage<T> it) => it.Item).ToList(), array, UpdateColumns);
			}
		}
