		public class DynamicCoreHelper
		{
			public class BuildPropertySelectorResult
			{
				public FormattableString formattableString { get; set; }

				public string ShortName { get; set; }

				public Type ResultNewType { get; set; }

				public LambdaExpression Exp { get; internal set; }
			}

			public static BuildPropertySelectorResult BuildPropertySelector(string shortName, Type type, List<string> propertyNames, params object[] args)
			{
				BuildPropertySelectorResult buildPropertySelectorResult = new BuildPropertySelectorResult();
				if (type == null)
				{
					throw new ArgumentNullException("type");
				}
				if (propertyNames == null || propertyNames.Count == 0)
				{
					throw new ArgumentNullException("propertyNames");
				}
				ParameterExpression parameterExpression = Expression.Parameter(type, shortName);
				string format = "new { " + string.Join(", ", propertyNames) + " }";
				format = ReplaceFormatParameters(format);
				buildPropertySelectorResult.formattableString = FormattableStringFactory.Create(format, args);
				LambdaExpression lambdaExpression = SqlSugarDynamicExpressionParser.ParseLambda(new ParameterExpression[1] { parameterExpression }, null, format, args);
				buildPropertySelectorResult.ResultNewType = lambdaExpression.Body.Type;
				buildPropertySelectorResult.ShortName = shortName;
				buildPropertySelectorResult.Exp = lambdaExpression;
				return buildPropertySelectorResult;
			}

			public static Expression<Func<T, bool>> GetWhere<T>(string shortName, FormattableString whereSql)
			{
				return (Expression<Func<T, bool>>)GetWhere(typeof(T), shortName, whereSql);
			}

			public static LambdaExpression GetWhere(Type entityType, string shortName, FormattableString whereSql)
			{
				ParameterExpression parameterExpression = Expression.Parameter(entityType, shortName);
				whereSql.GetArguments();
				string sql = ReplaceFormatParameters(whereSql.Format);
				sql = CompatibleDynamicLinqCoreBug(sql);
				return SqlSugarDynamicExpressionParser.ParseLambda(new ParameterExpression[1] { parameterExpression }, typeof(bool), sql, whereSql.GetArguments());
			}

			private static string CompatibleDynamicLinqCoreBug(string sql)
			{
				if (sql != null && sql.Contains("SqlFunc."))
				{
					sql = sql.Replace("SqlFunc.LessThan(", "SqlFunc.LessThan_LinqDynamicCore(");
					sql = sql.Replace("SqlFunc.LessThan (", "SqlFunc.LessThan_LinqDynamicCore (");
					sql = sql.Replace("SqlFunc.GreaterThan(", "SqlFunc.GreaterThan_LinqDynamicCore(");
					sql = sql.Replace("SqlFunc.GreaterThan (", "SqlFunc.GreaterThan_LinqDynamicCore (");
				}
				return sql;
			}

			public static LambdaExpression GetObject(Type entityType, string shortName, FormattableString whereSql)
			{
				ParameterExpression parameterExpression = Expression.Parameter(entityType, shortName);
				whereSql.GetArguments();
				string sql = ReplaceFormatParameters(whereSql.Format);
				return SqlSugarDynamicExpressionParser.ParseLambda(new ParameterExpression[1] { parameterExpression }, typeof(object), sql, whereSql.GetArguments());
			}

			public static LambdaExpression GetWhere(Dictionary<string, Type> parameterDictionary, FormattableString whereSql)
			{
				ParameterExpression[] parameterExpressions = parameterDictionary.Select<KeyValuePair<string, Type>, ParameterExpression>((KeyValuePair<string, Type> it) => Expression.Parameter(it.Value, it.Key)).ToArray();
				whereSql.GetArguments();
				string sql = ReplaceFormatParameters(whereSql.Format);
				return SqlSugarDynamicExpressionParser.ParseLambda(sql: CompatibleDynamicLinqCoreBug(sql), parameterExpressions: parameterExpressions, type: typeof(bool), objects: whereSql.GetArguments());
			}

			public static LambdaExpression GetMember(Dictionary<string, Type> parameterDictionary, Type propertyType, FormattableString memberSql)
			{
				ParameterExpression[] parameterExpressions = parameterDictionary.Select<KeyValuePair<string, Type>, ParameterExpression>((KeyValuePair<string, Type> it) => Expression.Parameter(it.Value, it.Key)).ToArray();
				memberSql.GetArguments();
				string sql = ReplaceFormatParameters(memberSql.Format);
				return SqlSugarDynamicExpressionParser.ParseLambda(parameterExpressions, propertyType, sql, memberSql.GetArguments());
			}

			public static LambdaExpression GetMember(Type entityType, Type propertyType, string shortName, FormattableString memberSql)
			{
				ParameterExpression parameterExpression = Expression.Parameter(entityType, shortName);
				memberSql.GetArguments();
				string sql = ReplaceFormatParameters(memberSql.Format);
				return SqlSugarDynamicExpressionParser.ParseLambda(new ParameterExpression[1] { parameterExpression }, propertyType, sql, memberSql.GetArguments());
			}

			private static string ReplaceFormatParameters(string format)
			{
				int parameterIndex = 0;
				return Regex.Replace(format, "\\{\\d+\\}", delegate
				{
					string result = $"@{parameterIndex}";
					parameterIndex++;
					return result;
				});
			}
		}
