		internal class JsonCommonProvider
		{
			public ISqlBuilder sqlBuilder { get; set; }

			public int ParameterIndex => ((SqlBuilderProvider)sqlBuilder)?.GetParameterNameIndex ?? 0;

			public JsonCommonProvider(ISqlSugarClient context)
			{
				sqlBuilder = InstanceFactory.GetSqlbuilder(context.CurrentConnectionConfig);
				if (context is SqlSugarProvider)
				{
					sqlBuilder.Context = context as SqlSugarProvider;
				}
				else if (context is SqlSugarScopeProvider)
				{
					sqlBuilder.Context = (context as SqlSugarScopeProvider).conn;
				}
				else if (context is SqlSugarScope)
				{
					sqlBuilder.Context = (context as SqlSugarScope).GetConnection(context.CurrentConnectionConfig.ConfigId);
				}
				else
				{
					sqlBuilder.Context = (context as SqlSugarClient).Context;
				}
			}

			public JsonTableNameInfo GetTableName(JToken item)
			{
				//IL_000c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0012: Invalid comparison between Unknown and I4
				JsonTableNameInfo jsonTableNameInfo = new JsonTableNameInfo();
				if ((int)((IEnumerable<JToken>)item).First().Type == 2 && ((IEnumerable<JToken>)item.First).Count() == 2)
				{
					string tableName = ((IEnumerable<JToken>)item).First()[(object)0].ObjToString();
					string shortName = ((IEnumerable<JToken>)item).First()[(object)1].ObjToString();
					jsonTableNameInfo.ShortName = shortName;
					jsonTableNameInfo.TableName = tableName;
				}
				else
				{
					string tableName2 = ((object)((IEnumerable<JToken>)item).First()).ToString();
					jsonTableNameInfo.TableName = tableName2;
				}
				return jsonTableNameInfo;
			}

			public KeyValuePair<string, SugarParameter[]> GetWhere(string item, SqlSugarProvider context)
			{
				if (!IsConditionalModel(item))
				{
					IFuncModel model = context.Utilities.JsonToSqlFuncModels(item);
					return sqlBuilder.FuncModelToSql(model);
				}
				List<IConditionalModel> models = context.Utilities.JsonToConditionalModels(item);
				return sqlBuilder.ConditionalModelToSql(models);
			}

			public KeyValuePair<string, SugarParameter[]> GetWhere(JToken item, SqlSugarProvider context)
			{
				//IL_0012: Unknown result type (might be due to invalid IL or missing references)
				//IL_0018: Invalid comparison between Unknown and I4
				string text = ((object)((IEnumerable<JToken>)item).First()).ToString();
				Check.ExceptionEasy((int)((IEnumerable<JToken>)item).First().Type != 2, "Where format error " + (object)item, "Where格式错误" + (object)item);
				if (!IsConditionalModel(text))
				{
					IFuncModel model = context.Utilities.JsonToSqlFuncModels(text);
					return sqlBuilder.FuncModelToSql(model);
				}
				List<IConditionalModel> models = context.Utilities.JsonToConditionalModels(text);
				return sqlBuilder.ConditionalModelToSql(models);
			}

			private static bool IsConditionalModel(string value)
			{
				return value.ToLower().Contains("fieldname");
			}
		}
		public class JsonDeleteableProvider : IJsonDeleteableProvider<JsonDeleteResult>, IJsonProvider<JsonDeleteResult>
		{
			private ISqlSugarClient context;

			private JObject jObject;

			private JsonCommonProvider jsonCommonProvider;

			private IDeleteable<object> sugarDeleteable;

			public JsonDeleteableProvider(ISqlSugarClient context, JObject jObject)
			{
				this.jObject = jObject;
				this.context = context;
				jsonCommonProvider = new JsonCommonProvider(context);
			}

			public SqlObjectResult ToSql()
			{
				return ToSqlList().First();
			}

			public List<SqlObjectResult> ToSqlList()
			{
				List<SqlObjectResult> list = new List<SqlObjectResult>();
				JsonQueryParameter jsonQueryParameter = new JsonQueryParameter();
				List<JToken> list2 = ((IEnumerable<JToken>)Extensions.AsJEnumerable((IEnumerable<JToken>)jObject)).ToList();
				sugarDeleteable = context.Deleteable<object>();
				foreach (JToken item in list2)
				{
					AppendAll(jsonQueryParameter, item);
				}
				list.Add(new SqlObjectResult(sugarDeleteable.ToSql(), JsonProviderType.Deleteable));
				return list;
			}

			private void AppendAll(JsonQueryParameter jsonQueryParameter, JToken item)
			{
				string name = item.Path.ToLower();
				if (IsWhere(name))
				{
					AppendWhere(item);
				}
				else if (IsTable(name))
				{
					AppendTable(item);
				}
			}

			private void AppendTable(JToken item)
			{
				JsonTableNameInfo tableName = jsonCommonProvider.GetTableName(item);
				string tableName2 = tableName.TableName.ToCheckField();
				if (tableName.ShortName.HasValue())
				{
					tableName2 = tableName.ShortName + "." + tableName.TableName;
				}
				sugarDeleteable.AS(tableName2);
			}

			private void AppendWhere(JToken item)
			{
				KeyValuePair<string, SugarParameter[]> keyValuePair = jsonCommonProvider.GetWhere(item, sugarDeleteable.DeleteBuilder.Context);
				sugarDeleteable.Where(keyValuePair.Key, keyValuePair.Value);
			}

			private static bool IsTable(string name)
			{
				return name == "Deleteable".Get().ToLower();
			}

			private static bool IsWhere(string name)
			{
				return name == "Where".ToLower();
			}

			public string ToSqlString()
			{
				throw new NotImplementedException();
			}

			public JsonDeleteResult ToResult()
			{
				JsonDeleteResult jsonDeleteResult = new JsonDeleteResult();
				SqlObjectResult sqlObjectResult = ToSqlList().First();
				jsonDeleteResult.UpdateRows = context.Ado.ExecuteCommand(sqlObjectResult.Sql, sqlObjectResult.Parameters);
				return jsonDeleteResult;
			}

			List<string> IJsonProvider<JsonDeleteResult>.ToSqlString()
			{
				throw new NotImplementedException();
			}
		}
		public class JsonInsertableProvider : IJsonInsertableProvider<JsonInsertResult>, IJsonProvider<JsonInsertResult>
		{
			private ISqlSugarClient context;

			private JObject jObject;

			private JsonCommonProvider jsonCommonProvider;

			private IInsertable<Dictionary<string, object>> sugarInsertable;

			private string TableName { get; set; }

			private string IdentityId { get; set; }

			private int Count { get; set; }

			private void AppendIdentity(JToken item)
			{
				JsonTableNameInfo tableName = jsonCommonProvider.GetTableName(item);
				IdentityId = tableName.TableName;
			}

			private void AppendName(JToken item)
			{
				JsonTableNameInfo tableName = jsonCommonProvider.GetTableName(item);
				TableName = tableName.TableName.ToCheckField();
				if (tableName.ShortName.HasValue())
				{
					TableName = tableName.ShortName + "." + tableName.TableName;
				}
			}

			private void AppendRow(JToken item)
			{
				string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
				List<Dictionary<string, object>> insertObjs = context.Utilities.JsonToColumnsModels(json);
				sugarInsertable = context.Insertable(insertObjs).AS(TableName);
			}

			private static bool IsColumns(string name)
			{
				return name == "columns".ToLower();
			}

			private static bool IsName(string name)
			{
				return name == "Insertable".Get().ToLower();
			}

			private static bool IsIdentity(string name)
			{
				return name == "identity".ToLower();
			}

			private List<SqlObjectResult> ToSqlHelper()
			{
				List<SqlObjectResult> list = new List<SqlObjectResult>();
				JsonQueryParameter jsonQueryParameter = new JsonQueryParameter();
				foreach (JToken item in from it in ((IEnumerable<JToken>)Extensions.AsJEnumerable((IEnumerable<JToken>)jObject)).ToList()
					orderby (!it.Path.EqualCase("Insertable".Get())) ? 1 : 0
					select it)
				{
					AppendAll(jsonQueryParameter, item);
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarInsertable.ToSql();
				if (IdentityId.HasValue())
				{
					list.Add(new SqlObjectResult(keyValuePair, JsonProviderType.InsertableIdentity));
				}
				else
				{
					list.Add(new SqlObjectResult(keyValuePair, JsonProviderType.Insertable));
				}
				return list;
			}

			public SqlObjectResult ToSql()
			{
				return ToSqlList().First();
			}

			public JsonInsertableProvider(ISqlSugarClient context, JObject jObject)
			{
				this.jObject = jObject;
				this.context = context;
				jsonCommonProvider = new JsonCommonProvider(context);
			}

			public JsonInsertResult ToResult()
			{
				JsonInsertResult jsonInsertResult = new JsonInsertResult();
				SqlObjectResult sqlObjectResult = ToSqlList().First();
				if (sqlObjectResult.JsonSqlType != JsonProviderType.InsertableIdentity)
				{
					jsonInsertResult.InsertCount = context.Ado.ExecuteCommand(sqlObjectResult.Sql, sqlObjectResult.Parameters);
				}
				else
				{
					jsonInsertResult.InsertCount = Count;
					jsonInsertResult.IdentityValue = context.Ado.GetInt(sqlObjectResult.Sql, sqlObjectResult.Parameters);
				}
				return jsonInsertResult;
			}

			public List<SqlObjectResult> ToSqlList()
			{
				return ToSqlHelper();
			}

			private void AppendAll(JsonQueryParameter jsonQueryParameter, JToken item)
			{
				string name = item.Path.ToLower();
				if (IsName(name))
				{
					AppendName(item);
				}
				else if (IsIdentity(name))
				{
					AppendIdentity(item);
				}
				else if (IsColumns(name))
				{
					AppendRow(item);
				}
			}

			public List<string> ToSqlString()
			{
				throw new NotImplementedException();
			}
		}
