					return;
				}
				JArray val = new JArray();
				List<JsonTableConfig> list = (from it in jsonTableConfigs
					group it by it.TableName into it
					select it.First()).ToList();
				bool flag = IsAnyJoin(appendTypeNames);
				foreach (JsonTableConfig item2 in list)
				{
					if (flag || !item2.Columns.Any())
					{
						continue;
					}
					foreach (string item3 in item2.Columns.Select((JsonColumnConfig it) => it.Name).Distinct())
					{
						val.Add(JToken.op_Implicit(item3));
					}
				}
				AppendSelect((JToken)(object)val);
			}

			private bool IsAppendSelect()
			{
				if (!IsAnySelect(appendTypeNames))
				{
					return jsonTableConfigs.Any();
				}
				return false;
			}

			private void AppendFrom(JToken item)
			{
				JsonTableNameInfo tableName = jsonCommonProvider.GetTableName(item);
				tableName.TableName.ToCheckField();
				AddMasterTableInfos(tableName);
				if (tableName.ShortName.HasValue())
				{
					sugarQueryable.AS(tableName.TableName, tableName.ShortName);
				}
				else
				{
					sugarQueryable.AS(tableName.TableName, tableName.ShortName);
				}
			}

			private void AppendGroupBy(JToken item)
			{
				string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
				List<GroupByModel> models = context.Utilities.JsonToGroupByModels(json);
				sugarQueryable.GroupBy(models);
			}

			private void AppendHaving(JToken item)
			{
				string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
				IFuncModel model = context.Utilities.JsonToSqlFuncModels(json);
				sugarQueryable.Having(model);
			}

			private bool AppendJoin(JToken item)
			{
				BeforeJoin();
				string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
				JoinModel joinModel = context.Utilities.JsonToJoinModels(json);
				sugarQueryable.AddJoinInfo(joinModel.TableName, joinModel.ShortName, joinModel.OnWhereList, GetJoinType(item));
				AddTableInfos(joinModel.TableName, joinModel.ShortName);
				AfterJoin();
				return true;
			}

			private static JoinType GetJoinType(JToken obj)
			{
				string text = obj.Path.ToLower();
				if (text.Contains("right"))
				{
					return JoinType.Right;
				}
				if (text.Contains("left"))
				{
					return JoinType.Left;
				}
				if (text.Contains("full"))
				{
					return JoinType.Full;
				}
				return JoinType.Inner;
			}

			private void AfterJoin()
			{
			}

			private void BeforeJoin()
			{
			}

			private void AppendOrderBy(JToken item)
			{
				string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
				List<OrderByModel> models = context.Utilities.JsonToOrderByModels(json);
				sugarQueryable.OrderBy(models);
			}

			private int AppendPageSize(JToken item)
			{
				return Convert.ToInt32(((object)((IEnumerable<JToken>)item).First()).ToString().ObjToInt());
			}

			private int AppendPageNumber(JToken item)
			{
				int num = Convert.ToInt32(((object)((IEnumerable<JToken>)item).First()).ToString().ObjToInt());
				if (num == 0)
				{
					num = 1;
				}
				return num;
			}

			private bool AppendSelect(JToken item)
			{
				//IL_0002: Unknown result type (might be due to invalid IL or missing references)
				//IL_0008: Invalid comparison between Unknown and I4
				if ((int)item.Type == 4)
				{
					string json = ((object)((IEnumerable<JToken>)item).First()).ToString();
					List<SelectModel> obj = context.Utilities.JsonToSelectModels(json);
					obj = FilterSelect(obj);
					sugarQueryable.Select(obj);
					return true;
				}
				List<SelectModel> obj2 = context.Utilities.JsonToSelectModels(((object)item).ToString());
				obj2 = FilterSelect(obj2);
				sugarQueryable.Select(obj2);
				return true;
			}

			private List<SelectModel> FilterSelect(List<SelectModel> obj)
			{
				if (!jsonTableConfigs.Any())
				{
					return obj;
				}
				List<SelectModel> list = new List<SelectModel>();
				foreach (SelectModel item in obj)
				{
					if (item.FieldName is string)
					{
						string tableName = GetTableName(item.FieldName?.ToString() ?? "");
						string columnName = GetColumnName(item.FieldName?.ToString() ?? "");
						if (IsMyColums(tableName, columnName))
						{
							list.Add(item);
						}
					}
					else
					{
						list.Add(item);
					}
				}
				return list;
			}

			private bool IsMyColums(string tableName, string columnName)
			{
				return jsonTableConfigs.Any((JsonTableConfig it) => it.TableName.EqualCase(tableName) && it.Columns.Any((JsonColumnConfig z) => z.Name.EqualCase(columnName)));
			}

			private string GetColumnName(string filedName)
			{
				return filedName.Split('.').Last();
			}

			private string GetTableName(string filedName)
			{
				if (!filedName.Contains("."))
				{
					return TableInfos.First((JsonQueryableProvider_TableInfo it) => it.IsMaster).Table;
				}
				string shortName = filedName.Split('.').First();
				return TableInfos.First((JsonQueryableProvider_TableInfo it) => it.ShortName == shortName).Table;
			}

			private void AppendWhere(JToken item)
			{
				BeforeWhere();
				KeyValuePair<string, SugarParameter[]> keyValuePair = jsonCommonProvider.GetWhere(item, sugarQueryable.Context);
				sugarQueryable.Where(keyValuePair.Key, keyValuePair.Value);
				AfterWhere();
			}

			private void AfterWhere()
			{
			}

			private void BeforeWhere()
			{
				if (!IsExecutedBeforeWhereFunc)
				{
					BeforeWhereFunc();
					IsExecutedBeforeWhereFunc = true;
				}
			}

			private static bool IsJoin(string name)
			{
				if (!name.StartsWith("LeftJoin".ToLower()) && !name.StartsWith("RightJoin".ToLower()))
				{
					return name.StartsWith("InnerJoin".ToLower());
				}
				return true;
			}

			private static bool IsJoinLastAfter(string name)
			{
				return name == "joinlastafter";
			}

			private static bool IsPageSize(string name)
			{
				return name == "PageSize".ToLower();
			}

			private static bool IsPageNumber(string name)
			{
				return name == "PageNumber".ToLower();
			}

			private static bool IsSelect(string name)
			{
				return name == "Select".ToLower();
			}

			private static bool IsHaving(string name)
			{
				return name == "Having".ToLower();
			}

			private static bool IsGroupBy(string name)
			{
				return name == "GroupBy".ToLower();
			}

			private static bool IsOrderBy(string name)
			{
				return name == "OrderBy".ToLower();
			}

			private static bool IsWhere(string name)
			{
				return name == "Where".ToLower();
			}

			private static bool IsForm(string name)
			{
				return name == "Queryable".Get().ToLower();
			}

			private static bool IsAnySelect(List<JToken> appendTypeNames)
			{
				return appendTypeNames.Any((JToken it) => IsSelect(it.Path.ToLower()));
			}

			private static bool IsAnyJoin(List<JToken> appendTypeNames)
			{
				return appendTypeNames.Any((JToken it) => IsJoin(it.Path.ToLower()));
			}

			private int GetSort(string name)
			{
				if (IsForm(name))
				{
					return 0;
				}
				if (IsJoin(name))
				{
					return 1;
				}
				if (IsJoinLastAfter(name))
				{
					return 2;
				}
				return 100;
			}

			private void AddMasterTableInfos(JsonTableNameInfo tableNameInfo)
			{
				AddTableInfos(tableNameInfo.TableName, tableNameInfo.ShortName, isMaster: true);
			}

			private void AddTableInfos(string tableName, string shortName, bool isMaster = false)
			{
				UtilMethods.IsNullReturnNew(TableInfos);
				TableInfos.Add(new JsonQueryableProvider_TableInfo
				{
					Table = tableName,
					ShortName = shortName,
					IsMaster = true
				});
			}

			private JsonQueryableProvider_TableInfo GetMasterTable()
			{
				return TableInfos.First((JsonQueryableProvider_TableInfo it) => it.IsMaster);
			}

			public JsonQueryableProvider(ISqlSugarClient context, JObject jobject)
			{
				this.jobject = jobject;
				this.context = context;
				jsonCommonProvider = new JsonCommonProvider(context);
			}

			public IJsonQueryableProvider<JsonQueryResult> ShowDesciption()
			{
				IsDescription = true;
				return this;
			}

			public IJsonQueryableProvider<JsonQueryResult> UseAuthentication(JsonTableConfig config)
			{
				if (config == null)
				{
					jsonTableConfigs = new List<JsonTableConfig> { config };
				}
				else
				{
					jsonTableConfigs.Add(config);
				}
				return this;
			}

			public IJsonQueryableProvider<JsonQueryResult> UseAuthentication(List<JsonTableConfig> configs)
			{
				foreach (JsonTableConfig config in configs)
				{
					UseAuthentication(config);
				}
				return this;
			}

			public SqlObjectResult ToSql()
			{
				return ToSqlList().First();
			}

			public JsonQueryResult ToResult()
			{
				return ToResultDefault();
			}

			public List<SqlObjectResult> ToSqlList()
			{
				return ToSqlDefault();
			}

			public List<string> ToSqlString()
			{
				throw new NotImplementedException();
			}

			private void AppendQueryableAll(JsonQueryParameter jsonQueryParameter, JToken item)
			{
				SetQueryableParameterIndex();
				string name = item.Path.ToLower();
				if (IsForm(name))
				{
					AppendFrom(item);
				}
				else if (IsWhere(name))
				{
					AppendWhere(item);
				}
				else if (IsOrderBy(name))
				{
					AppendOrderBy(item);
				}
				else if (IsJoinLastAfter(name))
				{
					ApendJoinLastAfter(item);
				}
				else if (IsGroupBy(name))
				{
					AppendGroupBy(item);
				}
				else if (IsHaving(name))
				{
					AppendHaving(item);
				}
				else if (IsSelect(name))
				{
					jsonQueryParameter.IsSelect = AppendSelect(item);
				}
				else if (IsPageNumber(name))
				{
					jsonQueryParameter.PageIndex = AppendPageNumber(item);
				}
				else if (IsPageSize(name))
				{
					jsonQueryParameter.PageSize = AppendPageSize(item);
				}
				else if (IsJoin(name))
				{
					jsonQueryParameter.IsSelect = AppendJoin(item);
				}
			}

			private void SetQueryableParameterIndex()
			{
				((SqlBuilderProvider)sugarQueryable.SqlBuilder).GetParameterNameIndex = jsonCommonProvider.ParameterIndex;
			}

			private void RegisterAop()
			{
				BeforeWhereFunc = delegate
				{
					JsonQueryableProvider_TableInfo masterTable = GetMasterTable();
					List<JsonTableConfig> list = jsonTableConfigs.Where((JsonTableConfig it) => it.TableName.EqualCase(masterTable.Table)).ToList();
					if (list.Any())
					{
						foreach (JsonTableConfig item in list)
						{
							List<IConditionalModel> conditionals = item.Conditionals;
							conditionals = GetConvertConditions(conditionals);
							KeyValuePair<string, SugarParameter[]> keyValuePair = sugarQueryable.SqlBuilder.ConditionalModelToSql(conditionals);
							string appendSql = keyValuePair.Key;
							sugarQueryable.SqlBuilder.RepairReplicationParameters(ref appendSql, keyValuePair.Value, appendIndex);
							appendIndex++;
							sugarQueryable.Where(appendSql, keyValuePair.Value);
						}
					}
				};
			}

			private List<IConditionalModel> GetConvertConditions(List<IConditionalModel> conditions)
			{
				return conditions;
			}

			private List<SqlObjectResult> ToSqlDefault()
			{
				List<SqlObjectResult> result = new List<SqlObjectResult>();
				sugarQueryable = context.Queryable<object>();
				appendTypeNames = GetTypeNames();
				JsonQueryParameter jsonQueryParameter = new JsonQueryParameter();
				RegisterAop();
				foreach (JToken appendTypeName in appendTypeNames)
				{
					AppendQueryableAll(jsonQueryParameter, appendTypeName);
				}
				return ToPageDefault(result, jsonQueryParameter);
			}

			private List<JToken> GetTypeNames()
			{
				List<JToken> list = ((IEnumerable<JToken>)Extensions.AsJEnumerable((IEnumerable<JToken>)jobject)).ToList();
				list.Add(((IEnumerable<JToken>)JToken.Parse("{JoinLastAfter:null}")).First());
				return list.OrderBy((JToken it) => GetSort(it.Path.ToLower())).ToList();
			}

			private JsonQueryResult ToResultDefault()
			{
				JsonQueryResult result = new JsonQueryResult();
				List<SqlObjectResult> source = ToSqlList();
				SqlObjectResult sqlCount = source.FirstOrDefault((SqlObjectResult it) => it.JsonSqlType == JsonProviderType.QueryableCount);
				SqlObjectResult sqlList = source.FirstOrDefault((SqlObjectResult it) => it.JsonSqlType == JsonProviderType.Queryable);
				AddCount(result, sqlCount);
				AddList(result, sqlList);
				AddDescription();
				return result;
			}

			private List<SqlObjectResult> ToPageDefault(List<SqlObjectResult> result, JsonQueryParameter jsonQueryParameter)
			{
				if (jsonQueryParameter.IsPage)
				{
					AddPageSql(result, jsonQueryParameter);
				}
				else
				{
					AddDefaultSql(result);
				}
				Check.ExceptionEasy(jsonQueryParameter.JoinNoSelect, "join query need Select", "联表查询需要设置Select");
				return result;
			}

			private void AddDefaultSql(List<SqlObjectResult> result)
			{
				result.Add(new SqlObjectResult(sugarQueryable.Clone().ToSql(), JsonProviderType.Queryable));
			}

			private void AddPageSql(List<SqlObjectResult> result, JsonQueryParameter jsonQueryParameter)
			{
				int index = (jsonQueryParameter.PageIndex.Value - 1) * jsonQueryParameter.PageSize.Value;
				int value = jsonQueryParameter.PageSize.Value;
				result.Add(new SqlObjectResult(this.sugarQueryable.Clone().Skip(index).Take(value)
					.ToSql(), JsonProviderType.Queryable));
				ISugarQueryable<object> sugarQueryable = this.sugarQueryable.Select("COUNT(1)");
				sugarQueryable.QueryBuilder.OrderByValue = null;
				result.Add(new SqlObjectResult(sugarQueryable.ToSql(), JsonProviderType.QueryableCount));
			}

			private void AddDescription()
			{
				_ = IsDescription;
			}

			private void AddList(JsonQueryResult result, SqlObjectResult SqlList)
			{
				if (SqlList != null)
				{
					result.Data = context.Ado.SqlQuery<object>(SqlList.Sql, SqlList.Parameters);
				}
			}

			private void AddCount(JsonQueryResult result, SqlObjectResult SqlCount)
			{
				if (SqlCount != null)
				{
					result.ToTalRows = context.Ado.GetInt(SqlCount.Sql, SqlCount.Parameters);
				}
			}
		}
		internal class JsonQueryableProvider_TableInfo
		{
			public string Table { get; set; }

			public string ShortName { get; set; }

			public bool IsMaster { get; set; }

			public bool IsJoin { get; set; }

			public int Index { get; set; }
		}
		public class JsonUpdateableProvider : IJsonUpdateableProvider<JsonUpdateResult>, IJsonProvider<JsonUpdateResult>
		{
			private ISqlSugarClient context;

			private JObject jObject;

			private JsonCommonProvider jsonCommonProvider;

			private IUpdateable<Dictionary<string, object>> sugarUpdateable;

			private string TableName { get; set; }

			private bool isList { get; set; }

			private void AppendRow(JToken item)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_000d: Invalid comparison between Unknown and I4
				JToken obj = ((IEnumerable<JToken>)item).First();
				bool flag = (int)obj.Type == 1;
				string json = ((object)obj).ToString();
				List<Dictionary<string, object>> list = context.Utilities.JsonToColumnsModels(json);
				if (flag)
				{
					sugarUpdateable = context.Updateable(list.First()).AS(TableName);
					return;
				}
				sugarUpdateable = context.Updateable(list).AS(TableName);
				isList = list.Take(2).Count() > 0;
			}

			private void AppendTable(JToken item)
			{
				JsonTableNameInfo tableName = jsonCommonProvider.GetTableName(item);
				TableName = tableName.TableName.ToCheckField();
				if (tableName.ShortName.HasValue())
				{
					TableName = tableName.ShortName + "." + tableName.TableName;
				}
			}

			private void AppendWhere(JToken item)
			{
				Check.Exception(isList, "Batch updates cannot use Where, only WhereColumns can set columns", "批量更新不能使用Where，只能通过WhereColumns设置列");
				KeyValuePair<string, SugarParameter[]> keyValuePair = jsonCommonProvider.GetWhere(item, sugarUpdateable.UpdateBuilder.Context);
				sugarUpdateable.Where(keyValuePair.Key, keyValuePair.Value);
			}

			private void AppendWhereColumns(JToken item)
			{
				string[] array = ((IEnumerable<JToken>)item).First().ToObject<string[]>();
				Check.ExceptionEasy(array.IsNullOrEmpty(), "need WhereColumns", "WhereColumns 需要设置列名");
				sugarUpdateable.WhereColumns(array);
			}

			private static bool IsColumns(string name)
			{
				return name == "Columns".ToLower();
			}

			private static bool IsWhere(string name)
			{
				return name == "Where".ToLower();
			}

			private static bool IsWhereColumns(string name)
			{
				return name == "WhereColumns".ToLower();
			}

			private static bool IsTable(string name)
			{
				return name == "Updateable".Get().ToLower();
			}

			public JsonUpdateableProvider(ISqlSugarClient context, JObject jObject)
			{
				this.jObject = jObject;
				this.context = context;
				jsonCommonProvider = new JsonCommonProvider(context);
			}

			public JsonUpdateResult ToResult()
			{
				JsonUpdateResult jsonUpdateResult = new JsonUpdateResult();
				SqlObjectResult sqlObjectResult = ToSqlList().First();
				jsonUpdateResult.UpdateRows = context.Ado.ExecuteCommand(sqlObjectResult.Sql, sqlObjectResult.Parameters);
				return jsonUpdateResult;
			}

			public SqlObjectResult ToSql()
			{
				return ToSqlList().First();
			}

			public List<SqlObjectResult> ToSqlList()
			{
				List<SqlObjectResult> list = new List<SqlObjectResult>();
				JsonQueryParameter jsonQueryParameter = new JsonQueryParameter();
				foreach (JToken appendType in GetAppendTypes())
				{
					AppendAll(jsonQueryParameter, appendType);
				}
				KeyValuePair<string, List<SugarParameter>> keyValuePair = sugarUpdateable.ToSql();
				list.Add(new SqlObjectResult(keyValuePair, JsonProviderType.Updateable));
				return list;
			}

			private List<JToken> GetAppendTypes()
			{
				return ((IEnumerable<JToken>)Extensions.AsJEnumerable((IEnumerable<JToken>)jObject)).ToList().OrderBy(delegate(JToken it)
				{
					if (it.Path.EqualCase("Updateable".Get()))
					{
						return 0;
					}
					return it.Path.EqualCase("Columns") ? 1 : 3;
				}).ToList();
			}

			private void AppendAll(JsonQueryParameter jsonQueryParameter, JToken item)
			{
				string name = item.Path.ToLower();
				if (IsTable(name))
				{
					AppendTable(item);
				}
				else if (IsWhereColumns(name))
				{
					AppendWhereColumns(item);
				}
				else if (IsWhere(name))
				{
					AppendWhere(item);
				}
				else if (IsColumns(name))
				{
					AppendRow(item);
				}
			}

			public List<string> ToSqlString()
			{
				throw new NotImplementedException();
			}
		}
		public static class JsonProviderConfig
		{
			public const string KeyInsertable = "Insertable";

			public const string KeyUpdateable = "Updateable";

			public const string KeyQueryable = "Queryable";

			public const string KeyDeleteable = "Deleteable";

			private static Dictionary<string, string> words = new Dictionary<string, string>
			{
				{ "Insertable", "Table" },
				{ "Updateable", "Table" },
				{ "Queryable", "Table" },
				{ "Deleteable", "Table" }
			};

			public static string Rename(string key, string name)
			{
				return words[key] = name;
			}

			internal static string Get(this string value)
			{
				return words[value];
			}

			internal static string GetWord(string key)
			{
				Check.ExceptionEasy(!words.ContainsKey(key), key + " is error", key + " 不存在 ");
				return words[key];
			}
		}
		internal class Json2SqlHelper
		{
			public static bool IsSqlValue(string valueString)
			{
				return Regex.IsMatch(valueString, "^\\{\\w{1,10}\\}\\:");
			}

			public static string GetType(string valueString)
			{
				return Regex.Match(valueString, "^\\{(\\w+)\\}\\:").Groups[1].Value;
			}

			public static string GetValue(string valueString)
			{
				return Regex.Replace(valueString, "^\\{\\w{1,10}\\}\\:", "");
			}

			public static List<string> GetTableNames(string json)
			{
				List<string> list = new List<string>();
				JToken val = ((IEnumerable<JToken>)Extensions.AsJEnumerable((IEnumerable<JToken>)JObject.Parse(json))).Where((JToken it) => it.Path.ToLower().IsIn("Insertable".Get().ToLower(), "Updateable".Get().ToLower(), "Deleteable".Get().ToLower(), "Queryable".Get().ToLower())).FirstOrDefault();
				if (val != null)
				{
					list.Add(((object)((IEnumerable<JToken>)val).First()).ToString());
				}
				return list;
			}
		}
