		/// <summary>
		/// 数据填充器
		/// </summary>
		public class SqlDataAdapter : IDataAdapter
		{
			private SqlCommand command;

			private string sql;

			private SqlConnection _sqlConnection;

			/// <summary>
			/// SelectCommand
			/// </summary>
			public SqlCommand SelectCommand
			{
				get
				{
					//IL_0015: Unknown result type (might be due to invalid IL or missing references)
					//IL_001f: Expected O, but got Unknown
					if (command == null)
					{
						command = new SqlCommand(sql, _sqlConnection);
					}
					return command;
				}
				set
				{
					command = value;
				}
			}

			/// <summary>
			/// SqlDataAdapter
			/// </summary>
			/// <param name="command"></param>
			public SqlDataAdapter(SqlCommand command)
			{
				this.command = command;
			}

			public SqlDataAdapter()
			{
			}

			/// <summary>
			/// SqlDataAdapter
			/// </summary>
			/// <param name="sql"></param>
			/// <param name="_sqlConnection"></param>
			public SqlDataAdapter(string sql, SqlConnection _sqlConnection)
			{
				this.sql = sql;
				this._sqlConnection = _sqlConnection;
			}

			/// <summary>
