		public class SqliteProvider : AdoProvider
		{
			public override IDbConnection Connection
			{
				get
				{
					//IL_003d: Unknown result type (might be due to invalid IL or missing references)
					//IL_0047: Expected O, but got Unknown
					if (_DbConnection == null)
					{
						try
						{
							string connectionString = base.Context.CurrentConnectionConfig.ConnectionString;
							if (connectionString != null && !connectionString.Contains("="))
							{
								Check.ExceptionEasy("ConnString format error . Correct format DataSource=...", "字符串格式错误，应该是DataSource=...");
							}
							_DbConnection = (IDbConnection)new SqliteConnection(connectionString);
						}
						catch (Exception ex)
						{
							if (ex.InnerException != null)
							{
								Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message + "\r\n" + ex.InnerException.Message);
							}
							else
							{
								Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message);
							}
						}
					}
					return _DbConnection;
				}
				set
				{
					_DbConnection = value;
				}
			}

			public override void ExecuteBefore(string sql, SugarParameter[] parameters)
			{
				BeforeTime = DateTime.Now;
				if (sql.HasValue() && parameters.HasValue())
				{
					foreach (SugarParameter sugarParameter in parameters)
					{
						string parameterName = sugarParameter.ParameterName;
						if (!sql.Contains(parameterName) && Regex.IsMatch(sql, "(" + parameterName + "$)|(" + parameterName + "[ ,\\,])", RegexOptions.IgnoreCase))
						{
							sugarParameter.ParameterName = Regex.Match(sql, "(" + parameterName + "$)|(" + parameterName + "[ ,\\,])", RegexOptions.IgnoreCase).Value.Trim();
						}
					}
				}
				if (!IsEnableLogEvent)
				{
					return;
				}
				Action<string, SugarParameter[]> logEventStarting = LogEventStarting;
				if (logEventStarting != null)
				{
					if (parameters == null || parameters.Length == 0)
					{
						logEventStarting(sql, new SugarParameter[0]);
					}
					else
					{
						logEventStarting(sql, parameters);
					}
				}
			}

			public override void BeginTran(string transactionName)
			{
				base.BeginTran();
			}

			/// <summary>
			/// Only SqlServer
			/// </summary>
			/// <param name="iso"></param>
			/// <param name="transactionName"></param>
			public override void BeginTran(IsolationLevel iso, string transactionName)
			{
				base.BeginTran(iso);
			}

			public override IDataAdapter GetAdapter()
			{
				return new SqliteDataAdapter();
			}

			public override DbCommand GetCommand(string sql, SugarParameter[] parameters)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Expected O, but got Unknown
				//IL_000c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0012: Expected O, but got Unknown
				//IL_0039: Unknown result type (might be due to invalid IL or missing references)
				//IL_0043: Expected O, but got Unknown
				SqliteCommand val = new SqliteCommand(sql, (SqliteConnection)Connection);
				((DbCommand)(object)val).CommandType = CommandType;
				((DbCommand)(object)val).CommandTimeout = CommandTimeOut;
				if (base.Transaction != null)
				{
					val.Transaction = (SqliteTransaction)base.Transaction;
				}
				if (parameters.HasValue())
				{
					IDataParameter[] array = ToIDbDataParameter(parameters);
					val.Parameters.AddRange((IEnumerable<SqliteParameter>)(SqliteParameter[])array);
				}
				CheckConnection();
				return (DbCommand)(object)val;
			}

			public override void SetCommandToAdapter(IDataAdapter dataAdapter, DbCommand command)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Expected O, but got Unknown
				((SqliteDataAdapter)dataAdapter).SelectCommand = (SqliteCommand)command;
			}

			/// <summary>
			/// if SQLite return SQLiteParameter[] pars
			/// if sqlerver return SqlParameter[] pars ...
			/// </summary>
			/// <param name="parameters"></param>
			/// <returns></returns>
			public override IDataParameter[] ToIDbDataParameter(params SugarParameter[] parameters)
			{
				//IL_0079: Unknown result type (might be due to invalid IL or missing references)
				//IL_0083: Expected O, but got Unknown
				if (parameters == null || parameters.Length == 0)
				{
					return null;
				}
				SqliteParameter[] array = (SqliteParameter[])(object)new SqliteParameter[parameters.Length];
				int num = 0;
				bool flag = Context.IsVarchar();
				foreach (SugarParameter sugarParameter in parameters)
				{
					if (sugarParameter.Value == null)
					{
						sugarParameter.Value = DBNull.Value;
					}
					if (sugarParameter.Value.GetType() == UtilConstants.GuidType)
					{
						sugarParameter.Value = sugarParameter.Value.ToString();
					}
					SqliteParameter sqlParameter = new SqliteParameter();
					((DbParameter)(object)sqlParameter).ParameterName = sugarParameter.ParameterName;
					((DbParameter)(object)sqlParameter).Size = sugarParameter.Size;
					((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					((DbParameter)(object)sqlParameter).DbType = sugarParameter.DbType;
					array[num] = sqlParameter;
					if (((DbParameter)(object)sqlParameter).Direction.IsIn(ParameterDirection.Output, ParameterDirection.InputOutput, ParameterDirection.ReturnValue))
					{
						if (base.OutputParameters == null)
						{
							base.OutputParameters = new List<IDataParameter>();
						}
						base.OutputParameters.RemoveAll((IDataParameter it) => it.ParameterName == ((DbParameter)(object)sqlParameter).ParameterName);
						base.OutputParameters.Add((IDataParameter)sqlParameter);
					}
					if (((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.Guid)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.String;
						if (((DbParameter)(object)sqlParameter).Value != DBNull.Value)
						{
							((DbParameter)(object)sqlParameter).Value = ((DbParameter)(object)sqlParameter).Value.ObjToString();
						}
					}
					if (flag && ((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.String)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiString;
					}
					else if (sugarParameter.DbType == System.Data.DbType.DateTimeOffset)
					{
						if (((DbParameter)(object)sqlParameter).Value != DBNull.Value)
						{
							((DbParameter)(object)sqlParameter).Value = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)((DbParameter)(object)sqlParameter).Value);
						}
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.DateTime;
					}
					num++;
				}
				return (IDataParameter[])array;
			}
		}
		public class OracleExpressionContext : ExpressionContext, ILambdaExpressions
		{
			public SqlSugarProvider Context { get; set; }

			public override string SqlParameterKeyWord => ":";

			public override string SqlTranslationLeft => "\"";

			public override string SqlTranslationRight => "\"";

			public bool IsUppper
			{
				get
				{
					if (base.SugarContext?.Context?.Context?.CurrentConnectionConfig?.MoreSettings == null)
					{
						return true;
					}
					ExpressionOutParameter sugarContext = base.SugarContext;
					if (sugarContext == null)
					{
						return false;
					}
					return sugarContext.Context?.Context?.CurrentConnectionConfig?.MoreSettings.IsAutoToUpper == true;
				}
			}

			public OracleExpressionContext()
			{
				base.DbMehtods = new OracleMethod();
			}

			public override string GetTranslationTableName(string entityName, bool isMapping = true)
			{
				return base.GetTranslationTableName(entityName, isMapping).ToUpper(IsUppper);
			}

			public override string GetTranslationColumnName(string columnName)
			{
				if (columnName == "systimestamp")
				{
					return columnName;
				}
				if (columnName.Contains(":"))
				{
					return base.GetTranslationColumnName(columnName);
				}
				if (columnName.Contains("\".\""))
				{
					return columnName;
				}
				return base.GetTranslationColumnName(columnName).ToUpper(IsUppper);
			}

			public override string GetDbColumnName(string entityName, string propertyName)
			{
