		public class MySqlBlukCopy<T>
		{
			internal SqlSugarProvider Context { get; set; }

			internal ISqlBuilder Builder { get; set; }

			internal T[] Entitys { get; set; }

			internal string Chara { get; set; }

			public MySqlBlukCopy(SqlSugarProvider context, ISqlBuilder builder, T[] entitys)
			{
				Context = context;
				Builder = builder;
				Entitys = entitys;
			}

			private MySqlBlukCopy()
			{
			}

			public bool ExecuteBulkCopy(string characterSet)
			{
				Chara = characterSet;
				return ExecuteBulkCopy();
			}

			public bool ExecuteBulkCopy()
			{
				//IL_01de: Unknown result type (might be due to invalid IL or missing references)
				//IL_01e3: Unknown result type (might be due to invalid IL or missing references)
				//IL_01ef: Unknown result type (might be due to invalid IL or missing references)
				//IL_01fa: Unknown result type (might be due to invalid IL or missing references)
				//IL_0202: Unknown result type (might be due to invalid IL or missing references)
				//IL_020a: Unknown result type (might be due to invalid IL or missing references)
				//IL_0215: Unknown result type (might be due to invalid IL or missing references)
				//IL_021c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0223: Unknown result type (might be due to invalid IL or missing references)
				//IL_0234: Unknown result type (might be due to invalid IL or missing references)
				//IL_023b: Unknown result type (might be due to invalid IL or missing references)
				bool flag = false;
				if (Entitys == null || Entitys.Length == 0)
				{
					return flag;
				}
				if (Entitys.First() == null && Entitys.Length == 1)
				{
					return flag;
				}
				DataTable dt = new DataTable();
				EntityInfo entity = Context.EntityMaintenance.GetEntityInfo<T>();
				dt.TableName = Builder.GetTranslationColumnName(entity.DbTableName);
				List<PropertyInfo> pList = new List<PropertyInfo>();
				Array.ForEach(entity.Columns.ToArray(), delegate(EntityColumnInfo p)
				{
					if (!p.IsIgnore && !p.IsOnlyIgnoreInsert)
					{
						pList.Add(p.PropertyInfo);
						dt.Columns.Add(p.DbColumnName);
					}
				});
				DataRow row = null;
				T[] entitys = Entitys;
				foreach (T item in entitys)
				{
					row = dt.NewRow();
					pList.ForEach(delegate(PropertyInfo p)
					{
						string name = p.Name;
						if (entity.Columns.Any((EntityColumnInfo it) => it.PropertyName == name))
						{
							name = entity.Columns.First((EntityColumnInfo it) => it.PropertyName == name).DbColumnName;
						}
						row[name] = GetValue(p, item);
					});
					dt.Rows.Add(row);
				}
				string text = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "failFiles");
				DirectoryInfo directoryInfo = new DirectoryInfo(text);
				if (!directoryInfo.Exists)
				{
					directoryInfo.Create();
				}
				string text2 = Path.Combine(text, Guid.NewGuid().ToString() + ".csv");
				string contents = DataTableToCsvString(dt);
				File.WriteAllText(text2, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				IDbConnection connection = Context.Ado.Connection;
				MySqlConnection val = (MySqlConnection)((connection is MySqlConnection) ? connection : null);
				try
				{
					Context.Ado.Open();
					MySqlBulkLoader val2 = new MySqlBulkLoader(val)
					{
						CharacterSet = GetChara(),
						FieldTerminator = ",",
						FieldQuotationCharacter = '"',
						EscapeCharacter = '"',
						LineTerminator = Environment.NewLine,
						FileName = text2,
						NumberOfLinesToSkip = 0,
						TableName = dt.TableName,
						Local = true
					};
					val2.Columns.AddRange((from DataColumn colum in dt.Columns
						select colum.ColumnName).Distinct().ToArray());
					flag = val2.Load() > 0;
					if (flag && File.Exists(text2))
					{
						File.Delete(text2);
					}
				}
				catch (MySqlException ex)
				{
					throw ex;
				}
				finally
				{
					CloseDb();
				}
				return flag;
			}

			public Task<bool> ExecuteBulkCopyAsync()
			{
				return Task.FromResult(ExecuteBulkCopy());
			}

			public Task<bool> ExecuteBulkCopyAsync(string characterSet)
			{
				Chara = characterSet;
				return Task.FromResult(ExecuteBulkCopy());
			}

			private string GetChara()
			{
				if (Chara == null)
				{
					return "utf8mb4";
				}
				return Chara;
			}

			private void CloseDb()
			{
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection && Context.Ado.Transaction == null)
				{
					Context.Ado.Connection.Close();
				}
			}

			/// <summary>
			///             DataTable to CSV
			/// </summary>
			/// <param name="table">datatable</param>
			/// <returns>CSV</returns>
			public string DataTableToCsvString(DataTable table)
			{
				if (table.Rows.Count == 0)
				{
					return "";
				}
				StringBuilder stringBuilder = new StringBuilder();
				foreach (DataRow row in table.Rows)
				{
					for (int i = 0; i < table.Columns.Count; i++)
					{
						DataColumn dataColumn = table.Columns[i];
						if (i != 0)
						{
							stringBuilder.Append(",");
						}
						if (dataColumn.DataType == typeof(string) && (row[dataColumn].ToString().Contains(",") || row[dataColumn].ToString().Contains("\r") || row[dataColumn].ToString().Contains("\"") || row[dataColumn].ToString().Contains("\n")))
						{
							stringBuilder.Append("\"" + row[dataColumn].ToString().Replace("\"", "\"\"") + "\"");
						}
						else if (dataColumn.DataType == typeof(bool))
						{
							if (row[dataColumn] == DBNull.Value)
							{
								stringBuilder.Append("NULL");
							}
							else
							{
								stringBuilder.Append(row[dataColumn].ObjToBool() ? 1 : 0);
							}
						}
						else if (dataColumn.DataType == UtilConstants.DateType && row[dataColumn] != null && row[dataColumn] != DBNull.Value)
						{
							stringBuilder.Append(row[dataColumn].ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff"));
						}
						else if (row[dataColumn] == null || row[dataColumn] == DBNull.Value)
						{
							stringBuilder.Append("NULL");
						}
						else
						{
							stringBuilder.Append(row[dataColumn].ToString());
						}
					}
					stringBuilder.AppendLine();
				}
				return stringBuilder.ToString();
			}

			private static object GetValue(PropertyInfo p, T item)
			{
				object obj = p.GetValue(item, null);
				if (obj != null && UtilMethods.GetUnderType(p.PropertyType) == UtilConstants.BoolType && !obj.ObjToBool())
				{
					obj = null;
				}
				return obj;
			}
		}
