						if (dbColumnInfo != null)
						{
							if (dbColumnInfo.Value != null && UtilMethods.GetUnderType(dbColumnInfo.Value.GetType()) == UtilConstants.DateType && dbColumnInfo.Value != null && dbColumnInfo.Value.ToString() == DateTime.MinValue.ToString())
							{
