							}
							dataRow[item.ColumnName] = dbColumnInfo.Value;
						}
					}
					dataTable.Rows.Add(dataRow);
				}
				if (InsertBuilder.OracleSeqInfoList != null && InsertBuilder.OracleSeqInfoList.Any())
				{
					List<int> list = InsertBuilder.OracleSeqInfoList.Select<KeyValuePair<string, int>, int>((KeyValuePair<string, int> it) => it.Value).ToList();
					EntityColumnInfo entityColumnInfo = InsertBuilder.EntityInfo.Columns.Where((EntityColumnInfo it) => !string.IsNullOrEmpty(it.OracleSequenceName)).First();
					string dbColumnName = entityColumnInfo.DbColumnName;
					list.Add(Context.Ado.GetInt(" select " + entityColumnInfo.OracleSequenceName + ".nextval from dual"));
					int num = 0;
					foreach (DataRow row in dataTable.Rows)
					{
						row[dbColumnName] = list[num];
						num++;
					}
				}
				return dataTable;
			}

