		public class MySqlCodeFirst : CodeFirstProvider
		{
			public override void NoExistLogic(EntityInfo entityInfo)
			{
				string tableName = GetTableName(entityInfo);
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				if (entityInfo.Columns.HasValue())
				{
					foreach (EntityColumnInfo item2 in entityInfo.Columns.OrderBy((EntityColumnInfo it) => (!it.IsPrimarykey) ? 1 : 0))
					{
						if (!item2.IsIgnore)
						{
							if (item2.PropertyInfo != null && UtilMethods.GetUnderType(item2.PropertyInfo.PropertyType) == UtilConstants.GuidType && item2.Length == 0 && item2.DataType == null)
							{
								item2.Length = Guid.NewGuid().ToString().Length;
							}
							DbColumnInfo item = EntityColumnToDbColumn(entityInfo, tableName, item2);
							list.Add(item);
						}
					}
					if (entityInfo.IsCreateTableFiledSort)
					{
						list = list.OrderBy((DbColumnInfo c) => c.CreateTableFieldSort).ToList();
						list = list.OrderBy((DbColumnInfo it) => (!it.IsPrimarykey) ? 1 : 0).ToList();
					}
				}
				Context.DbMaintenance.CreateTable(tableName, list);
			}

			protected override DbColumnInfo EntityColumnToDbColumn(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
			{
				Type underType = UtilMethods.GetUnderType(item.PropertyInfo);
				UtilMethods.SetDefaultValueForBoolean(item, underType);
				DbColumnInfo dbColumnInfo = new DbColumnInfo
				{
					TableId = entityInfo.Columns.IndexOf(item),
					DbColumnName = (item.DbColumnName.HasValue() ? item.DbColumnName : item.PropertyName),
					IsPrimarykey = item.IsPrimarykey,
					IsIdentity = item.IsIdentity,
					TableName = tableName,
					IsNullable = item.IsNullable,
					DefaultValue = item.DefaultValue,
					ColumnDescription = item.ColumnDescription,
					Length = item.Length,
					DecimalDigits = item.DecimalDigits,
					CreateTableFieldSort = item.CreateTableFieldSort
				};
				GetDbType(item, underType, dbColumnInfo);
				if (dbColumnInfo.DataType.Equals("varchar", StringComparison.CurrentCultureIgnoreCase) && dbColumnInfo.Length == 0)
				{
					dbColumnInfo.Length = 1;
				}
				return dbColumnInfo;
			}

			protected override void ConvertColumns(List<DbColumnInfo> dbColumns)
			{
				foreach (DbColumnInfo dbColumn in dbColumns)
				{
					if (dbColumn.DataType == "DateTime")
					{
						dbColumn.Length = 0;
					}
				}
			}

			protected override void ChangeKey(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
			{
				Context.DbMaintenance.UpdateColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item));
				if (!item.IsPrimarykey)
				{
					Context.DbMaintenance.DropConstraint(tableName, null);
				}
				if (item.IsPrimarykey)
				{
					Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
				}
			}

			internal DbColumnInfo GetEntityColumnToDbColumn(EntityInfo entity, string dbTableName, EntityColumnInfo item)
			{
				return EntityColumnToDbColumn(entity, dbTableName, item);
			}

			protected override void GetDbType(EntityColumnInfo item, Type propertyType, DbColumnInfo result)
			{
				if (!string.IsNullOrEmpty(item.DataType))
				{
					result.DataType = item.DataType;
					return;
				}
				if (propertyType.IsEnum())
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName((item.Length > 9) ? UtilConstants.LongType.Name : UtilConstants.IntType.Name);
					return;
				}
				if (item.IsJson && item.DataType == null)
				{
					result.DataType = "json";
					return;
				}
				if (propertyType == UtilConstants.DecType && item.Length == 0 && item.DecimalDigits == 0)
				{
					result.Length = 18;
					result.DecimalDigits = 4;
					result.DataType = "decimal";
					return;
				}
				string type = GetType(propertyType.Name);
				if (type == "Boolean")
				{
					result.DataType = "tinyint";
					result.Length = 1;
					result.Scale = 0;
					result.DecimalDigits = 0;
				}
				else
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName(type);
					if (type == "Guid" && result.DataType == "varchar" && result.Length <= 1)
					{
						result.Length = 36;
					}
				}
			}

			protected override bool IsNoSamgeType(EntityColumnInfo ec, DbColumnInfo dc)
			{
				if (ec.UnderType == UtilConstants.BoolType && dc.DataType == "tinyint" && dc.Length == 1)
				{
					return false;
				}
				if (ec.UnderType == UtilConstants.DobType && dc.DataType == "double")
				{
					return false;
				}
				if (ec.UnderType == UtilConstants.DateType)
				{
					string dataType = dc.DataType;
					if (dataType != null && dataType.StartsWith("datetime"))
					{
						return false;
					}
				}
				return base.IsNoSamgeType(ec, dc);
			}
		}
		public class MySqlDbBind : DbBindProvider
		{
