					ConfigureExternalServices configureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
					if (configureExternalServices != null && configureExternalServices.AppendDataReaderTypeMappings.HasValue())
					{
						return configureExternalServices.AppendDataReaderTypeMappings.Union(MappingTypesConst).ToList();
					}
					return MappingTypesConst;
				}
			}

			public override List<string> StringThrow => new List<string> { "int32", "datetime", "decimal", "double", "byte" };

			public override string GetDbTypeName(string csharpTypeName)
			{
				if (csharpTypeName == UtilConstants.ByteArrayType.Name)
				{
					return "longblob";
				}
				if (csharpTypeName == "Int32")
				{
					csharpTypeName = "int";
				}
				if (csharpTypeName == "Int16")
				{
					csharpTypeName = "short";
				}
				if (csharpTypeName == "Int64")
				{
					csharpTypeName = "long";
				}
				if (csharpTypeName == "Boolean")
				{
					csharpTypeName = "bool";
				}
				if (csharpTypeName == "SByte")
				{
					csharpTypeName = "Byte";
				}
				if (csharpTypeName == "DateTimeOffset")
				{
					csharpTypeName = "DateTime";
				}
				IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Value.ToString().Equals(csharpTypeName, StringComparison.CurrentCultureIgnoreCase));
				if (enumerable == null || !enumerable.Any())
				{
					return "varchar";
				}
				return enumerable.First().Key;
			}
		}
		public class MySqlDbFirst : DbFirstProvider
		{
			protected override string GetPropertyTypeName(DbColumnInfo item)
			{
				if (item.DataType == "tinyint" && item.Length == 1 && !Context.CurrentConnectionConfig.ConnectionString.ToLower().Contains("treattinyasboolea"))
				{
					item.DataType = "bit";
					item.DefaultValue = "true";
					return "bool";
				}
				if (item.DataType == "mediumint")
				{
					item.DataType = "int";
					return "int";
				}
				if (item.DataType == "mediumint unsigned")
				{
					item.DataType = "mediumint unsigned";
					return "uint";
				}
				if (item.DataType == "double unsigned")
				{
					return "double";
				}
				return base.GetPropertyTypeName(item);
			}
		}
		internal class DorisHelper
		{
			public static void UpdateDateParameter(MySqlParameter sqlParameter)
			{
				if (((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.DateTime)
				{
					((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.String;
					((DbParameter)(object)sqlParameter).Value = ((DbParameter)(object)sqlParameter).Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff");
				}
				if (((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.DateTimeOffset)
				{
					((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.String;
					((DbParameter)(object)sqlParameter).Value = ((DbParameter)(object)sqlParameter).Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff");
				}
			}

			public static List<DbColumnInfo> GetColumns(List<DbColumnInfo> colums)
			{
				foreach (DbColumnInfo colum in colums)
				{
					string dataType = colum.DataType;
					if (dataType != null && dataType.Contains("("))
					{
						colum.DataType = colum.DataType.Substring(0, colum.DataType.IndexOf("("));
					}
					if (colum.DataType == "tinyint" && colum.Length == 4)
					{
						colum.Length = 1;
					}
				}
				return colums;
			}

			public static string UpdateDorisSql(ISqlBuilder sqlBuilder, List<DbColumnInfo> columns, string sql)
			{
				DbColumnInfo dbColumnInfo = columns.FirstOrDefault((DbColumnInfo it) => it.IsPrimarykey);
				if (dbColumnInfo != null)
				{
					Check.ExceptionEasy(columns.Where((DbColumnInfo it) => it.IsIdentity).Count() > 1, "Doris identity key no supported", "Doris不支持自增");
					Check.ExceptionEasy(columns.Where((DbColumnInfo it) => it.IsPrimarykey).Count() > 1, "Doris Only one primary key is supported", "Doris只支持单主键");
					sql = sql.Replace("$PrimaryKey)", ")");
					string translationColumnName = sqlBuilder.GetTranslationColumnName(dbColumnInfo.DbColumnName);
					sql = sql + " \r\nENGINE=OLAP\r\nUNIQUE KEY(" + translationColumnName + ")\r\nDISTRIBUTED BY HASH(" + translationColumnName + ") BUCKETS 1\r\nPROPERTIES (\r\n    'replication_num' = '1',\r\n    'storage_format' = 'DEFAULT'\r\n);\r\n\r\n";
				}
				return sql;
			}
		}
