			public override bool AddColumnRemark(string columnName, string tableName, string description)
			{
				tableName = base.SqlBuilder.GetTranslationColumnName(tableName);
				columnName = base.SqlBuilder.GetTranslationColumnName(columnName);
				foreach (string item in (from it in (base.Context.Ado.GetDataTable("SHOW CREATE TABLE " + tableName + ";").Rows[0][1]?.ToString() ?? "").Split('\n')
					where it.Last() == ','
					select it).ToList())
				{
					if (item.Contains(columnName))
					{
						string text = new Regex(" COMMENT .+$").Replace(item.TrimEnd(','), "");
						text = text + " COMMENT '" + description.ToSqlFilter() + "'  ";
						string sql = "ALTER TABLE " + tableName + " MODIFY COLUMN " + text.TrimEnd(',');
						base.Context.Ado.ExecuteCommand(sql);
						break;
					}
				}
				return true;
			}

			/// <summary>
			///             by current connection string
			/// </summary>
			/// <param name="databaseDirectory"></param>
			/// <returns></returns>
			public override bool CreateDatabase(string databaseName, string databaseDirectory = null)
			{
				if (base.Context.Ado.IsValidConnection() && base.Context.Ado.Connection.Database?.ToLower() == databaseName?.ToLower())
				{
					return true;
				}
				if (databaseDirectory != null && !FileHelper.IsExistDirectory(databaseDirectory))
				{
					FileHelper.CreateDirectory(databaseDirectory);
				}
				string database = base.Context.Ado.Connection.Database;
				string text = base.Context.CurrentConnectionConfig.ConnectionString;
				if (Regex.Split(text, database).Length > 2)
				{
					string value = Regex.Match(text, "database\\=\\w+|datasource\\=\\w+", RegexOptions.IgnoreCase).Value;
					if (!string.IsNullOrEmpty(value))
					{
						text = text.Replace(value, "database=mysql");
					}
					else
					{
						Check.ExceptionEasy("Failed to create the database. The database name has a keyword. Please change the name", "建库失败，库名存在关键字，请换一个名字");
					}
				}
				else
				{
					text = text.Replace(database, "mysql");
				}
				SqlSugarClient sqlSugarClient = new SqlSugarClient(new ConnectionConfig
				{
					DbType = base.Context.CurrentConnectionConfig.DbType,
					IsAutoCloseConnection = true,
					ConnectionString = text
				});
				if (!GetDataBaseList(sqlSugarClient).Any((string it) => it.Equals(databaseName, StringComparison.CurrentCultureIgnoreCase)))
				{
					string text2 = CreateDataBaseSql;
					if (ContainsCharSet("utf8mb4"))
					{
						text2 = text2.Replace("utf8 COLLATE utf8_general_ci", "utf8mb4");
					}
					if (!string.IsNullOrEmpty(StaticConfig.CodeFirst_MySqlCollate))
					{
						text2 = ((!text2.Contains(" COLLATE ")) ? (text2 + " COLLATE  " + StaticConfig.CodeFirst_MySqlCollate + " ") : $" {Regex.Split(text2, " COLLATE ").First()} COLLATE  {StaticConfig.CodeFirst_MySqlCollate} ");
					}
					sqlSugarClient.Ado.ExecuteCommand(string.Format(text2, databaseName, databaseDirectory));
				}
				return true;
			}

			public override bool AddTableRemark(string tableName, string description)
			{
				string sql = string.Format(AddTableRemarkSql, base.SqlBuilder.GetTranslationTableName(tableName), description);
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}

			public override bool CreateTable(string tableName, List<DbColumnInfo> columns, bool isCreatePrimaryKey = true)
			{
				if (columns.HasValue())
				{
					foreach (DbColumnInfo column in columns)
					{
						if (column.DbColumnName.Equals("GUID", StringComparison.CurrentCultureIgnoreCase) && column.Length == 0)
						{
							column.Length = 10;
						}
					}
				}
				string createTableSql = GetCreateTableSql(tableName, columns);
				string newValue = null;
				if (columns.Any((DbColumnInfo it) => it.IsPrimarykey) & isCreatePrimaryKey)
				{
					newValue = string.Format(", Primary key({0})", string.Join(",", from it in columns
						where it.IsPrimarykey
						select base.SqlBuilder.GetTranslationColumnName(it.DbColumnName)));
				}
				createTableSql = createTableSql.Replace("$PrimaryKey", newValue);
				if (!string.IsNullOrEmpty(StaticConfig.CodeFirst_MySqlTableEngine))
				{
					createTableSql = createTableSql + " ENGINE = " + StaticConfig.CodeFirst_MySqlTableEngine;
				}
				base.Context.Ado.ExecuteCommand(createTableSql);
				return true;
			}

			public override bool AddRemark(EntityInfo entity)
			{
				List<DbColumnInfo> columnInfosByTableName = base.Context.DbMaintenance.GetColumnInfosByTableName(entity.DbTableName, isCache: false);
				SqlSugarProvider context = base.Context;
				context.DbMaintenance.AddTableRemark(entity.DbTableName, entity.TableDescription);
				foreach (EntityColumnInfo item in entity.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList())
				{
					if (item.ColumnDescription != null)
					{
						MySqlCodeFirst mySqlCodeFirst = base.Context.CodeFirst as MySqlCodeFirst;
						if (item.UnderType == UtilConstants.GuidType && item.Length == 0)
						{
							item.Length = 36;
						}
						DbColumnInfo? dbColumnInfo = columnInfosByTableName.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(item.DbColumnName));
						if (((dbColumnInfo != null) ? dbColumnInfo.ColumnDescription.ObjToString() : null) != item.ColumnDescription.ObjToString())
						{
							string sql = GetUpdateColumnSql(entity.DbTableName, mySqlCodeFirst.GetEntityColumnToDbColumn(entity, entity.DbTableName, item)) + " " + (item.IsIdentity ? "AUTO_INCREMENT" : "") + "  COMMENT '" + item.ColumnDescription + "'";
							context.Ado.ExecuteCommand(sql);
						}
					}
				}
				return true;
			}

			protected override string GetCreateTableSql(string tableName, List<DbColumnInfo> columns)
			{
				List<string> list = new List<string>();
				Check.Exception(columns.IsNullOrEmpty(), "No columns found ");
				foreach (DbColumnInfo column in columns)
				{
					ConvertCreateColumnInfo(column);
					string dbColumnName = column.DbColumnName;
					string text = "";
					text = GetSize(column);
					string dataType = column.DataType;
					string text2 = (column.IsNullable ? CreateTableNull : CreateTableNotNull);
					string text3 = null;
					string text4 = (column.IsIdentity ? CreateTableIdentity : null);
					string text5 = string.Format(CreateTableColumn, base.SqlBuilder.GetTranslationColumnName(dbColumnName), dataType, text, text2, text3, text4);
					if (!string.IsNullOrEmpty(column.ColumnDescription))
					{
						text5 = text5 + " COMMENT '" + column.ColumnDescription.ToSqlFilter() + "' ";
					}
					list.Add(text5);
				}
				return string.Format(CreateTableSql, base.SqlBuilder.GetTranslationTableName(tableName), string.Join(",\r\n", list));
			}

			public override bool AddPrimaryKey(string tableName, string columnName)
			{
				return base.AddPrimaryKey(tableName, columnName);
			}

			public override bool AddColumn(string tableName, DbColumnInfo columnInfo)
			{
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				int num;
				if (!columnInfo.IsNullable)
				{
					num = (columnInfo.DefaultValue.HasValue() ? 1 : 0);
					if (num != 0)
					{
						columnInfo = base.Context.Utilities.TranslateCopy(columnInfo);
						columnInfo.IsNullable = true;
					}
				}
				else
				{
					num = 0;
				}
				string text = GetAddColumnSql(tableName, columnInfo);
				if (text != null && columnInfo.ColumnDescription.HasValue() && !text.ToLower().Contains("comment"))
				{
					text = text + " COMMENT '" + columnInfo.ColumnDescription.ToSqlFilter() + "'  ";
				}
				base.Context.Ado.ExecuteCommand(text);
				if (num != 0)
				{
					Type underType = UtilMethods.GetUnderType(base.Context.Queryable<object>().AS(columnInfo.TableName).Where("1=2")
						.Select(base.SqlBuilder.GetTranslationColumnName(columnInfo.DbColumnName))
						.ToDataTable()
						.Columns.Cast<DataColumn>().First((DataColumn it) => it.ColumnName.EqualCase(columnInfo.DbColumnName)).DataType);
					object value = ((underType == UtilConstants.StringType) ? "" : Activator.CreateInstance(underType));
					value = GetDefaultValue(columnInfo, value);
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					dictionary.Add(columnInfo.DbColumnName, value);
					base.Context.Updateable(dictionary).AS(tableName).Where(columnInfo.DbColumnName + " is null ")
						.ExecuteCommand();
					columnInfo.IsNullable = false;
					UpdateColumn(tableName, columnInfo);
				}
				return true;
			}

			public override bool UpdateColumn(string tableName, DbColumnInfo column)
			{
				ConvertCreateColumnInfo(column);
				return base.UpdateColumn(tableName, column);
			}

			protected override string GetSize(DbColumnInfo item)
			{
				string result = null;
				if (item.Length > 4000 || item.Length == -1)
				{
					result = "";
					item.DataType = "longtext";
				}
				else if (item.Length > 0 && item.DecimalDigits == 0)
				{
					result = ((item.Length > 0) ? $"({item.Length})" : null);
				}
				else if (item.Length == 0 && item.DecimalDigits > 0)
				{
					item.Length = 10;
					result = $"({item.Length},{item.DecimalDigits})";
				}
				else if (item.Length > 0 && item.DecimalDigits > 0)
				{
					result = ((item.Length > 0) ? $"({item.Length},{item.DecimalDigits})" : null);
				}
				return result;
			}

			public override bool RenameColumn(string tableName, string oldColumnName, string newColumnName)
			{
				IEnumerable<DbColumnInfo> enumerable = from it in GetColumnInfosByTableName(tableName, isCache: false)
					where it.DbColumnName.Equals(oldColumnName, StringComparison.CurrentCultureIgnoreCase)
					select it;
				if (enumerable != null && enumerable.Any())
				{
					DbColumnInfo dbColumnInfo = enumerable.First();
					string text = " " + dbColumnInfo.DataType;
					text = ((dbColumnInfo.Length > 0 && dbColumnInfo.Scale == 0) ? (text + $"({dbColumnInfo.Length}) ") : ((dbColumnInfo.Scale <= 0 || dbColumnInfo.Length <= 0) ? (text + (dbColumnInfo.IsNullable ? " NULL " : " NOT NULL ")) : (text + $"({dbColumnInfo.Length},{dbColumnInfo.Scale}) ")));
					tableName = base.SqlBuilder.GetTranslationTableName(tableName);
					oldColumnName = base.SqlBuilder.GetTranslationColumnName(oldColumnName);
					newColumnName = base.SqlBuilder.GetTranslationColumnName(newColumnName);
					string sql = string.Format(RenameColumnSql, tableName, oldColumnName, newColumnName + text);
					base.Context.Ado.ExecuteCommand(sql);
					return true;
				}
				return false;
			}

			public override bool AddDefaultValue(string tableName, string columnName, string defaultValue)
			{
				if (defaultValue == "''")
				{
					defaultValue = "";
				}
				if (defaultValue.ToLower().IsIn("null", "now()", "current_timestamp") || defaultValue.ToLower().Contains("current_timestamp") || defaultValue.Contains("()"))
				{
					defaultValue = "(" + defaultValue + ")";
					string sql = string.Format(AddDefaultValueSql.Replace("'", ""), tableName, columnName, defaultValue);
					base.Context.Ado.ExecuteCommand(sql);
					return true;
				}
				if (defaultValue == "0" || defaultValue == "1")
				{
					string sql2 = string.Format(AddDefaultValueSql.Replace("'", ""), tableName, columnName, defaultValue);
					base.Context.Ado.ExecuteCommand(sql2);
					return true;
				}
				return base.AddDefaultValue(tableName, columnName, defaultValue);
			}

			public override bool IsAnyConstraint(string constraintName)
			{
				throw new NotSupportedException("MySql IsAnyConstraint NotSupportedException");
			}

			public override bool BackupDataBase(string databaseName, string fullFileName)
			{
				if (fullFileName == null)
				{
					fullFileName = "c:\\" + databaseName + ".sql";
				}
				SqlSugarClient sqlSugarClient = base.Context.CopyNew();
				using (sqlSugarClient.Ado.OpenAlways())
				{
					if (databaseName != null)
					{
						sqlSugarClient.Ado.Connection.ChangeDatabase(databaseName);
					}
					Assembly assembly = null;
					try
					{
						assembly = ((!(StaticConfig.Backup_MySqlBackupType != null)) ? Assembly.LoadFrom(Assembly.GetExecutingAssembly().Location.Replace("Snet.DB.sugar.dll", "MySqlBackupNet.MySqlConnector.dll")) : StaticConfig.Backup_MySqlBackupType.Assembly);
					}
					catch (Exception)
					{
						Check.ExceptionEasy("Need MySqlBackup.NET.MySqlConnector", "需要安装:MySqlBackup.NET.MySqlConnector");
						throw;
					}
					Type type = assembly.GetType("MySqlConnector.MySqlBackup", throwOnError: false);
					object obj = Activator.CreateInstance(type, sqlSugarClient.Ado.Connection.CreateCommand());
					type.GetMethod("ExportToFile").Invoke(obj, new object[1] { fullFileName });
				}
				return true;
			}

			public override bool CreateIndex(string tableName, string[] columnNames, string IndexName, bool isUnique = false)
			{
				string text = "";
				if (IndexName.ToLower().Contains("{include:"))
				{
					text = Regex.Match(IndexName, "\\{include\\:.+$").Value;
					IndexName = IndexName.Replace(text, "");
					if (text == null)
					{
						throw new Exception("include format error");
					}
					text = "";
				}
				string sql = string.Format("CREATE {3} INDEX {2} ON {0}({1})" + text, base.SqlBuilder.GetTranslationColumnName(tableName), string.Join(",", columnNames), IndexName, isUnique ? "UNIQUE" : "");
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}

			private bool DorisUpadteColumns(ref string tableName, DbColumnInfo column)
			{
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				string translationTableName = base.SqlBuilder.GetTranslationTableName(column.DbColumnName);
				string sql = GetUpdateColumnSql(tableName, column).Replace("change  column", " MODIFY COLUMN").Replace("DEFAULT NULL ", " NULL ").Replace(translationTableName + " " + translationTableName, translationTableName);
				try
				{
					base.Context.Ado.ExecuteCommand(sql);
				}
				catch (Exception ex)
				{
					if (ex.Message == "errCode = 2, detailMessage = Nothing is changed. please check your alter stmt.")
					{
						return true;
					}
					throw ex;
				}
				return true;
			}

			private bool ContainsCharSet(string charset)
			{
				if (base.Context.CurrentConnectionConfig.ConnectionString.ObjToString().ToLower().Contains(charset))
				{
					return true;
				}
				return false;
			}

			private static void ConvertCreateColumnInfo(DbColumnInfo x)
			{
				string[] source = new string[2] { "longtext", "date" };
				if ("nvarchar".EqualCase(x.DataType) || "varchar".EqualCase(x.DataType))
				{
					if (x.Length < 1)
					{
						x.DataType += "(255)";
					}
				}
				else if (Enumerable.Contains(source, x.DataType?.ToLower()))
				{
					x.Length = 0;
					x.DecimalDigits = 0;
				}
			}
		}
		public class MySqlProvider : AdoProvider
		{
			public override IDbConnection Connection
			{
				get
				{
					//IL_006f: Unknown result type (might be due to invalid IL or missing references)
					//IL_0079: Expected O, but got Unknown
					if (_DbConnection == null)
					{
						try
						{
							string text = base.Context.CurrentConnectionConfig.ConnectionString;
							Check.ExceptionEasy(string.IsNullOrEmpty(text), "ConnectionString is not null", "连接字符串ConnectionString不能为Null");
							if (!text.ToLower().Contains("charset") && !text.ToLower().Contains("character"))
							{
								text = text.Trim().TrimEnd(';') + ";charset=utf8;";
							}
							_DbConnection = (IDbConnection)new MySqlConnection(text);
						}
						catch (Exception ex)
						{
							if (ex is SqlSugarException)
							{
								throw ex;
							}
							Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message);
						}
					}
					return _DbConnection;
				}
				set
				{
					_DbConnection = value;
				}
			}

