			public override DbCommand GetCommand(string sql, SugarParameter[] parameters)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Expected O, but got Unknown
				//IL_000c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0012: Expected O, but got Unknown
				//IL_0039: Unknown result type (might be due to invalid IL or missing references)
				//IL_0043: Expected O, but got Unknown
				MySqlCommand val = new MySqlCommand(sql, (MySqlConnection)Connection);
				((DbCommand)(object)val).CommandType = CommandType;
				((DbCommand)(object)val).CommandTimeout = CommandTimeOut;
				if (base.Transaction != null)
				{
					val.Transaction = (MySqlTransaction)base.Transaction;
				}
				if (parameters.HasValue())
				{
					IDataParameter[] array = ToIDbDataParameter(parameters);
					((DbParameterCollection)(object)val.Parameters).AddRange((Array)(MySqlParameter[])array);
				}
				CheckConnection();
				return (DbCommand)(object)val;
			}

			public override void SetCommandToAdapter(IDataAdapter dataAdapter, DbCommand command)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Expected O, but got Unknown
				((MySqlDataAdapter)dataAdapter).SelectCommand = (MySqlCommand)command;
			}

			/// <summary>
			/// if mysql return MySqlParameter[] pars
			/// if sqlerver return SqlParameter[] pars ...
			/// </summary>
			/// <param name="parameters"></param>
			/// <returns></returns>
			public override IDataParameter[] ToIDbDataParameter(params SugarParameter[] parameters)
			{
				//IL_004e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0058: Expected O, but got Unknown
				if (parameters == null || parameters.Length == 0)
				{
					return null;
				}
				MySqlParameter[] array = (MySqlParameter[])(object)new MySqlParameter[parameters.Length];
				int num = 0;
				bool flag = Context.IsVarchar();
				foreach (SugarParameter sugarParameter in parameters)
				{
					if (sugarParameter.Value == null)
					{
						sugarParameter.Value = DBNull.Value;
					}
					MySqlParameter sqlParameter = new MySqlParameter();
					((DbParameter)(object)sqlParameter).ParameterName = sugarParameter.ParameterName;
					((DbParameter)(object)sqlParameter).Size = sugarParameter.Size;
					((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					((DbParameter)(object)sqlParameter).DbType = sugarParameter.DbType;
					if (sugarParameter.Direction == (ParameterDirection)0)
					{
						sugarParameter.Direction = ParameterDirection.Input;
					}
					((DbParameter)(object)sqlParameter).Direction = sugarParameter.Direction;
					array[num] = sqlParameter;
					if (((DbParameter)(object)sqlParameter).Direction.IsIn(ParameterDirection.Output, ParameterDirection.InputOutput, ParameterDirection.ReturnValue))
					{
						if (base.OutputParameters == null)
						{
							base.OutputParameters = new List<IDataParameter>();
						}
						base.OutputParameters.RemoveAll((IDataParameter it) => it.ParameterName == ((DbParameter)(object)sqlParameter).ParameterName);
						base.OutputParameters.Add((IDataParameter)sqlParameter);
					}
					if (flag && ((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.String)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiString;
					}
					else if (sugarParameter.DbType == System.Data.DbType.DateTimeOffset)
					{
						if (((DbParameter)(object)sqlParameter).Value != DBNull.Value)
						{
							((DbParameter)(object)sqlParameter).Value = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)((DbParameter)(object)sqlParameter).Value);
						}
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.DateTime;
					}
					if (((DbParameter)(object)sqlParameter).Value is DateTime && ((DbParameter)(object)sqlParameter).Value.ObjToDate() == DateTime.MinValue && Convert.ToDateTime(((DbParameter)(object)sqlParameter).Value) == DateTime.MinValue)
					{
						((DbParameter)(object)sqlParameter).Value = UtilMethods.GetMinDate(Context.CurrentConnectionConfig);
					}
					if (!sugarParameter.IsJson && ((DbParameter)(object)sqlParameter).Value != null && ((DbParameter)(object)sqlParameter).Value is JArray)
					{
						((DbParameter)(object)sqlParameter).Value = ((DbParameter)(object)sqlParameter).Value.ToString();
					}
					num++;
				}
				return (IDataParameter[])array;
			}

			protected override void SugarCatch(Exception ex, string sql, SugarParameter[] parameters)
			{
				base.SugarCatch(ex, sql, parameters);
				_ = ex is NullReferenceException;
			}

			public override async Task<DbCommand> GetCommandAsync(string sql, SugarParameter[] parameters)
			{
				MySqlCommand sqlCommand = new MySqlCommand(sql, (MySqlConnection)Connection);
				((DbCommand)(object)sqlCommand).CommandType = CommandType;
				((DbCommand)(object)sqlCommand).CommandTimeout = CommandTimeOut;
				if (base.Transaction != null)
				{
					sqlCommand.Transaction = (MySqlTransaction)base.Transaction;
				}
				if (parameters.HasValue())
				{
					IDataParameter[] array = ToIDbDataParameter(parameters);
					((DbParameterCollection)(object)sqlCommand.Parameters).AddRange((Array)(MySqlParameter[])array);
				}
				if (Connection.State != ConnectionState.Open)
				{
					try
					{
						IDbConnection connection = Connection;
						await ((DbConnection)((connection is MySqlConnection) ? connection : null)).OpenAsync();
					}
					catch (Exception ex)
					{
						Check.Exception(true, ex.Message);
					}
				}
				return (DbCommand)(object)sqlCommand;
			}

			public override async Task<int> ExecuteCommandAsync(string sql, params SugarParameter[] parameters)
			{
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.SqlMiddle?.IsSqlMiddle == true)
				{
					return await base.ExecuteCommandAsync(sql, parameters);
				}
				int result;
				try
				{
					int num;
					_ = num - 1;
					_ = 2;
					try
					{
						Async();
						InitParameters(ref sql, parameters);
						if (FormatSql != null)
						{
							sql = FormatSql(sql);
						}
						SetConnectionStart(sql);
						if (ProcessingEventStartingSQL != null)
						{
							ExecuteProcessingSQL(ref sql, ref parameters);
						}
						ExecuteBefore(sql, parameters);
						DbCommand sqlCommand = await GetCommandAsync(sql, parameters);
						int num2 = (CancellationToken.HasValue ? (await sqlCommand.ExecuteNonQueryAsync(CancellationToken.Value)) : (await sqlCommand.ExecuteNonQueryAsync()));
						if (IsClearParameters)
						{
							sqlCommand.Parameters.Clear();
						}
						base.SqlExecuteCount = num2;
						ExecuteAfter(sql, parameters);
						sqlCommand.Dispose();
						result = num2;
					}
					catch (Exception ex)
					{
						CommandType = CommandType.Text;
						if (ErrorEvent != null)
						{
							ExecuteErrorEvent(sql, parameters, ex);
						}
						throw ex;
					}
				}
				finally
				{
					if (IsAutoClose())
					{
						await CloseAsync();
					}
					SetConnectionEnd(sql);
				}
				return result;
			}

			public override async Task<IDataReader> GetDataReaderAsync(string sql, params SugarParameter[] parameters)
			{
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.SqlMiddle?.IsSqlMiddle == true)
				{
					return await base.GetDataReaderAsync(sql, parameters);
				}
				try
				{
					Async();
					InitParameters(ref sql, parameters);
					if (FormatSql != null)
					{
						sql = FormatSql(sql);
					}
					SetConnectionStart(sql);
					bool isSp = CommandType == CommandType.StoredProcedure;
					if (ProcessingEventStartingSQL != null)
					{
						ExecuteProcessingSQL(ref sql, ref parameters);
					}
					ExecuteBefore(sql, parameters);
					DbCommand sqlCommand = await GetCommandAsync(sql, parameters);
					DbDataReader result = (CancellationToken.HasValue ? (await sqlCommand.ExecuteReaderAsync(IsAutoClose() ? CommandBehavior.CloseConnection : CommandBehavior.Default, CancellationToken.Value)) : (await sqlCommand.ExecuteReaderAsync(IsAutoClose() ? CommandBehavior.CloseConnection : CommandBehavior.Default)));
					if (isSp)
					{
						base.DataReaderParameters = sqlCommand.Parameters;
					}
					if (IsClearParameters)
					{
						sqlCommand.Parameters.Clear();
					}
					ExecuteAfter(sql, parameters);
					SetConnectionEnd(sql);
					if (Context.CurrentConnectionConfig.DbType != DbType.Sqlite)
					{
						sqlCommand.Dispose();
					}
					return result;
				}
				catch (Exception ex)
				{
					CommandType = CommandType.Text;
					if (ErrorEvent != null)
					{
						ExecuteErrorEvent(sql, parameters, ex);
					}
					throw ex;
				}
			}

			public override async Task<object> GetScalarAsync(string sql, params SugarParameter[] parameters)
			{
				ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.SqlMiddle?.IsSqlMiddle == true)
				{
					return await base.GetScalarAsync(sql, parameters);
				}
				object result;
				try
				{
					int num;
					_ = num - 1;
					_ = 2;
					try
					{
						Async();
						InitParameters(ref sql, parameters);
						if (FormatSql != null)
						{
							sql = FormatSql(sql);
						}
						SetConnectionStart(sql);
						if (ProcessingEventStartingSQL != null)
						{
							ExecuteProcessingSQL(ref sql, ref parameters);
						}
						ExecuteBefore(sql, parameters);
						DbCommand sqlCommand = await GetCommandAsync(sql, parameters);
						object obj = (CancellationToken.HasValue ? (await sqlCommand.ExecuteScalarAsync(CancellationToken.Value)) : (await sqlCommand.ExecuteScalarAsync()));
						if (IsClearParameters)
						{
							sqlCommand.Parameters.Clear();
						}
						ExecuteAfter(sql, parameters);
						sqlCommand.Dispose();
						result = obj;
					}
					catch (Exception ex)
					{
						CommandType = CommandType.Text;
						if (ErrorEvent != null)
						{
							ExecuteErrorEvent(sql, parameters, ex);
						}
						throw ex;
					}
				}
				finally
				{
					if (IsAutoClose())
					{
						await CloseAsync();
					}
					SetConnectionEnd(sql);
				}
				return result;
			}
		}
		public class MySqlFastBuilder : FastBuilder, IFastBuilder
		{
			public override string UpdateSql { get; set; } = "UPDATE  {1} TM    INNER JOIN {2} TE  ON {3} SET {0} ";

			private async Task<int> MySqlConnectorBulkCopy(DataTable dt)
			{
				try
				{
					base.Context.Open();
					MySqlTransaction val = (MySqlTransaction)base.Context.Ado.Transaction;
					await new MySqlBulkCopy((MySqlConnection)base.Context.Ado.Connection, val)
					{
						DestinationTableName = dt.TableName
					}.WriteToServerAsync(dt, default(CancellationToken));
					return dt.Rows.Count;
				}
				catch (Exception)
				{
					throw;
				}
				finally
				{
					CloseDb();
				}
			}

			public async Task<int> ExecuteBulkCopyAsync(DataTable dt)
			{
				if (dt.Columns.Cast<DataColumn>().Any((DataColumn it) => it.DataType == UtilConstants.ByteArrayType))
				{
					return await MySqlConnectorBulkCopy(dt);
				}
				string text = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "bulkcopyfiles");
				if (StaticConfig.BulkCopy_MySqlCsvPath.HasValue())
				{
					text = StaticConfig.BulkCopy_MySqlCsvPath;
				}
				DirectoryInfo directoryInfo = new DirectoryInfo(text);
				if (!directoryInfo.Exists)
				{
					directoryInfo.Create();
				}
				string fileName = Path.Combine(text, Guid.NewGuid().ToString() + ".csv");
				string contents = new MySqlBlukCopy<object>(base.Context.Context, null, null).DataTableToCsvString(dt);
				File.WriteAllText(fileName, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				IDbConnection connection = base.Context.Ado.Connection;
				MySqlConnection val = (MySqlConnection)((connection is MySqlConnection) ? connection : null);
				int result = 0;
				try
				{
					base.Context.Ado.Open();
					MySqlBulkLoader val2 = new MySqlBulkLoader(val)
					{
						CharacterSet = "utf8mb4",
						FieldTerminator = ",",
						FieldQuotationCharacter = '"',
						EscapeCharacter = '"',
						LineTerminator = Environment.NewLine,
						FileName = fileName,
						NumberOfLinesToSkip = 0,
						TableName = dt.TableName,
						Local = true
					};
					if (CharacterSet.HasValue())
					{
						val2.CharacterSet = CharacterSet;
					}
					val2.Columns.AddRange((from DataColumn colum in dt.Columns
						select new MySqlBuilder().GetTranslationColumnName(colum.ColumnName)).Distinct().ToArray());
					result = await val2.LoadAsync();
					if (File.Exists(fileName))
					{
						File.Delete(fileName);
					}
				}
				catch (Exception ex)
				{
					if (File.Exists(fileName))
					{
						File.Delete(fileName);
					}
					if (ex.Message == "The used command is not allowed with this MySQL version")
					{
						Check.ExceptionEasy("connection string add : AllowLoadLocalInfile=true", "BulkCopy MySql连接字符串需要添加 AllowLoadLocalInfile=true; 添加后如果还不行Mysql数据库执行一下 SET GLOBAL local_infile=1 ");
					}
					else if (ex.Message.Contains("To use MySqlBulkLoader.Local=true, set Allo"))
					{
						Check.ExceptionEasy("connection string add : AllowLoadLocalInfile=true", "BulkCopy MySql连接字符串需要添加 AllowLoadLocalInfile=true; 添加后如果还不行Mysql数据库执行一下 SET GLOBAL local_infile=1 ");
					}
					else
					{
						if (!(ex.Message == "Loading local data is disabled; this must be enabled on both the client and server sides"))
						{
							throw;
						}
						base.Context.Ado.ExecuteCommand("SET GLOBAL local_infile=1");
						Check.ExceptionEasy(ex.Message, " 检测到你没有开启文件，AllowLoadLocalInfile=true加到自符串上，已自动执行 SET GLOBAL local_infile=1 在试一次");
					}
				}
				finally
				{
					CloseDb();
				}
				return result;
			}

			public override async Task CreateTempAsync<T>(DataTable dt)
			{
				ISugarQueryable<T> queryable = base.Context.Queryable<T>();
				string translationTableName = queryable.SqlBuilder.GetTranslationTableName(dt.TableName);
				dt.TableName = "temp" + SnowFlakeSingle.instance.getID();
				_ = string.Empty;
				string value = ((!dt.Columns.Cast<DataColumn>().Any((DataColumn it) => it.DataType == UtilConstants.ByteArrayType)) ? (from it in queryable.AS(translationTableName)
					where false
					select it).ToSql().Key : (from it in queryable.AS(translationTableName)
					where false
					select it).Select(string.Join(",", from DataColumn it in dt.Columns
					select queryable.SqlBuilder.GetTranslationTableName(it.ColumnName))).ToSql().Key);
				await base.Context.Ado.ExecuteCommandAsync($"Create TEMPORARY  table {dt.TableName}({value}) ");
			}
		}
		public class MySqlQueryable<T> : QueryableProvider<T>
		{
			public override ISugarQueryable<T> With(string withString)
			{
				if (withString == null)
				{
					return this;
				}
				if (UtilMethods.StringCheckFirstAndLast(withString.TrimStart(' ').TrimEnd(' '), "/*", "*/"))
				{
					base.QueryBuilder.TableWithString = withString;
				}
				else if (UtilMethods.StringCheckFirstAndLast(withString.TrimStart(' ').TrimEnd(' ').ToLower(), "force", ")"))
				{
					base.QueryBuilder.TableWithString = withString;
				}
				return this;
			}

			public override ISugarQueryable<T> PartitionBy(string groupFileds)
			{
				GroupBy(groupFileds);
				return this;
			}
		}
