		public class MySqlInsertBuilder : InsertBuilder
		{
			private int i;

			public override string SqlTemplate
			{
				get
				{
					if (base.IsReturnIdentity)
					{
						return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;SELECT LAST_INSERT_ID();";
					}
					return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;";
				}
			}

			public object FormatValue(object value, string name)
			{
				string text = "N";
				if (base.Context.CurrentConnectionConfig.MoreSettings != null && base.Context.CurrentConnectionConfig.MoreSettings.DisableNvarchar)
				{
					text = "";
				}
				if (value == null)
				{
					return "NULL";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType)
				{
					return GetDateTimeString(value);
				}
				if (value is DateTimeOffset)
				{
					return GetDateTimeOffsetString(value);
				}
				if (value is decimal num)
				{
					return num.ToString(CultureInfo.InvariantCulture);
				}
				if (value is double num2)
				{
					return num2.ToString(CultureInfo.InvariantCulture);
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					string text2 = "0x" + BitConverter.ToString((byte[])value).Replace("-", "");
					if (text2 == "0x")
					{
						text2 = "''";
					}
					return text2;
				}
				if (underType.IsEnum())
				{
					ConnMoreSettings moreSettings = base.Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						return value.ToSqlValue();
					}
					return Convert.ToInt64(value);
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					i++;
					string text3 = base.Builder.SqlParameterKeyWord + name + "_" + i;
					base.Parameters.Add(new SugarParameter(text3, value));
					return text3;
				}
				return text + "'" + GetString(value) + "'";
			}

			private object GetDateTimeOffsetString(object value)
			{
				DateTime dateTime = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value);
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}

			private object GetDateTimeString(object value)
			{
				DateTime dateTime = value.ObjToDate();
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}

			private string GetString(object value)
			{
				string text = value.ToString();
				if (text.HasValue() && text.Contains("\\"))
				{
					text = text.Replace("\\", "\\\\");
				}
				return text;
			}

			public override string ToSqlString()
			{
				if (base.IsNoInsertNull)
				{
					base.DbColumnInfoList = base.DbColumnInfoList.Where((DbColumnInfo it) => it.Value != null).ToList();
				}
				List<IGrouping<int, DbColumnInfo>> list = (from it in base.DbColumnInfoList
					group it by it.TableId).ToList();
				bool num = list.Count() == 1;
				string text = string.Join(",", from it in list.First()
					select base.Builder.GetTranslationColumnName(it.DbColumnName));
				if (num)
				{
					string arg = string.Join(",", base.DbColumnInfoList.Select((DbColumnInfo it) => base.GetDbColumn(it, base.Builder.SqlParameterKeyWord + it.DbColumnName)));
					ActionMinDate();
					string result = string.Format(SqlTemplate, GetTableNameString, text, arg);
					return GetMySqlIgnore(result);
				}
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("INSERT INTO " + GetTableNameString + " ");
				stringBuilder.Append("(");
				stringBuilder.Append(text);
				stringBuilder.Append(") VALUES");
				string text2 = "";
				foreach (IGrouping<int, DbColumnInfo> item in list)
				{
					stringBuilder.Append("(");
					text2 = string.Join(",", item.Select((DbColumnInfo it) => base.GetDbColumn(it, FormatValue(it.Value, it.PropertyName))));
					stringBuilder.Append(text2);
					if (list.Last() == item)
					{
						stringBuilder.Append(") ");
					}
					else
					{
						stringBuilder.Append("),  ");
					}
				}
				stringBuilder.AppendLine(";select @@IDENTITY");
				string result2 = stringBuilder.ToString();
				return GetMySqlIgnore(result2);
			}

			private string GetMySqlIgnore(string result)
			{
				if (base.MySqlIgnore)
				{
					result = result.Replace("INSERT INTO", " INSERT IGNORE INTO");
				}
				return result;
			}
		}
