				{
					if (base.Skip == 0 && base.Take == 1 && base.OrderByValue == "ORDER BY NOW() ")
					{
						base.OrderByValue = null;
					}
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, GetOrderByString, (base.Skip.ObjToInt() > 0) ? base.Skip.ObjToInt() : 0, base.Take);
				}
				else
				{
					text = base.sql.ToString();
				}
				base.OrderByValue = orderByValue;
				text = GetSqlQuerySql(text);
				if (text.IndexOf("-- No table") > 0)
				{
					return "-- No table";
				}
				if (base.TranLock != null)
				{
					text += base.TranLock;
				}
				return text;
			}

			private string ToCountSqlString()
			{
				string orderByValue = base.OrderByValue;
				string text = null;
				base.sql = new StringBuilder();
				string text2 = (base.Hints.HasValue() ? (" " + base.Hints + " Count(*)") : "Count(*)");
				base.sql.AppendFormat(SqlTemplate, text2, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, (base.Skip.HasValue || base.Take.HasValue) ? null : GetOrderByString);
				if (base.IsCount)
				{
					if (base.sql.ToString().Contains("-- No table"))
					{
						return "-- No table";
					}
					return base.sql.ToString();
				}
				if (base.Skip.HasValue && !base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, (base.Skip.HasValue || base.Take.HasValue) ? null : GetOrderByString, base.Skip.ObjToInt(), long.MaxValue);
				}
				else if (!base.Skip.HasValue && base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, GetOrderByString, 0, base.Take.ObjToInt());
				}
				else if (base.Skip.HasValue && base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, GetOrderByString, (base.Skip.ObjToInt() > 0) ? base.Skip.ObjToInt() : 0, base.Take);
				}
				else
				{
					text = base.sql.ToString();
				}
				base.OrderByValue = orderByValue;
				return text;
			}

			public override string ToCountSql(string sql)
			{
				if (base.GroupByValue.HasValue() || base.IsDistinct)
				{
					return base.ToCountSql(sql);
				}
				return ToCountSqlString();
			}
		}
		public class MySqlUpdateBuilder : UpdateBuilder
		{
			private int i;

			public override string SqlTemplateBatch => "UPDATE  {1} S {2}   INNER JOIN ${{0}}  SET {0} ";

			public override string SqlTemplateJoin => "            (\r\n              {0}\r\n\r\n            ) T ON {1}\r\n                 ";

			protected override string GetJoinUpdate(string columnsString, ref string whereString)
			{
				string text = $"  {base.Builder.GetTranslationColumnName(base.TableName)}  {base.Builder.GetTranslationColumnName(base.ShortName)} ";
				foreach (JoinQueryInfo joinInfo in base.JoinInfos)
				{
					text += $"\r\n JOIN {base.Builder.GetTranslationColumnName(joinInfo.TableName)}  {base.Builder.GetTranslationColumnName(joinInfo.ShortName)} ON {joinInfo.JoinWhere} ";
				}
				string arg = text + "\r\n ";
				return string.Format(SqlTemplate, arg, columnsString, whereString);
			}

			protected override string TomultipleSqlString(List<IGrouping<int, DbColumnInfo>> groupList)
			{
				Check.Exception(base.PrimaryKeys == null || base.PrimaryKeys.Count == 0, " Update List<T> need Primary key");
				int num = 200;
				int num2 = 1;
				int num3 = (groupList.Count + num - 1) / num;
				StringBuilder stringBuilder = new StringBuilder();
				while (num3 >= num2)
				{
					StringBuilder stringBuilder2 = new StringBuilder();
					string arg = string.Join(",", (from it in groupList.First()
						where !it.IsPrimarykey && (!it.IsIdentity || (base.IsOffIdentity && it.IsIdentity))
						select it).Select(delegate(DbColumnInfo it)
					{
						if (base.SetValues.IsValuable())
						{
							IEnumerable<KeyValuePair<string, string>> enumerable = base.SetValues.Where<KeyValuePair<string, string>>((KeyValuePair<string, string> sv) => sv.Key == base.Builder.GetTranslationColumnName(it.DbColumnName));
							if (enumerable != null && enumerable.Any())
							{
								return enumerable.First().Value;
							}
						}
						return string.Format("S.{0}=T.{0}", base.Builder.GetTranslationColumnName(it.DbColumnName));
					}));
					stringBuilder.AppendFormat(SqlTemplateBatch.ToString(), arg, GetTableNameStringNoWith, base.TableWithString);
					int num4 = 0;
					foreach (IGrouping<int, DbColumnInfo> item in groupList.Skip((num2 - 1) * num).Take(num).ToList())
					{
						if (num4 != 0)
						{
							stringBuilder2.Append(SqlTemplateBatchUnion);
						}
						stringBuilder2.Append("\r\n SELECT " + string.Join(",", item.Select((DbColumnInfo it) => string.Format(SqlTemplateBatchSelect, base.GetDbColumn(it, FormatValue(it.Value, it.PropertyName)), base.Builder.GetTranslationColumnName(it.DbColumnName)))));
						num4++;
					}
					num2++;
					stringBuilder2.Append("\r\n");
					string text = null;
					if (base.WhereValues.HasValue())
					{
						foreach (string whereValue in base.WhereValues)
						{
							bool flag = text == null;
							text += (flag ? null : " AND ");
							text += Regex.Replace(whereValue, " \\" + base.Builder.SqlTranslationLeft, "S." + base.Builder.SqlTranslationLeft);
						}
					}
					if (base.PrimaryKeys.HasValue())
					{
						foreach (string primaryKey in base.PrimaryKeys)
						{
							bool flag2 = text == null;
							text += (flag2 ? null : " AND ");
							text += string.Format("S.{0}=T.{0}", base.Builder.GetTranslationColumnName(primaryKey));
						}
					}
					string newValue = string.Format(SqlTemplateJoin, stringBuilder2, text);
					stringBuilder.Replace("${0}", newValue);
					stringBuilder.Append(";");
				}
				stringBuilder = GetBatchUpdateSql(stringBuilder);
				return stringBuilder.ToString();
			}

			private StringBuilder GetBatchUpdateSql(StringBuilder batchUpdateSql)
			{
				if (ReSetValueBySqlExpListType == null && base.ReSetValueBySqlExpList != null)
				{
					string text = batchUpdateSql.ToString();
					foreach (KeyValuePair<string, ReSetValueBySqlExpListModel> reSetValueBySqlExp in base.ReSetValueBySqlExpList)
					{
						string dbColumnName = reSetValueBySqlExp.Value.DbColumnName;
						text = ((reSetValueBySqlExp.Value.Type != ReSetValueBySqlExpListModelType.List) ? text.Replace("T." + dbColumnName, reSetValueBySqlExp.Value.Sql.Replace(dbColumnName, "S." + dbColumnName)) : text.Replace("T." + dbColumnName, "S." + dbColumnName + reSetValueBySqlExp.Value.Sql + "T." + dbColumnName));
						batchUpdateSql = new StringBuilder(text);
					}
				}
				return batchUpdateSql;
			}

			public object FormatValue(object value, string name)
			{
				string text = "N";
				if (base.Context.CurrentConnectionConfig.MoreSettings != null && base.Context.CurrentConnectionConfig.MoreSettings.DisableNvarchar)
				{
					text = "";
				}
				if (value == null)
				{
					return "NULL";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType)
				{
					return GetDateTimeString(value);
				}
				if (value is DateTimeOffset)
				{
					return GetDateTimeOffsetString(value);
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					string text2 = "0x" + BitConverter.ToString((byte[])value).Replace("-", "");
					if (text2 == "0x")
					{
						text2 = "''";
					}
					return text2;
				}
				if (underType.IsEnum())
				{
					ConnMoreSettings moreSettings = base.Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						return value.ToSqlValue();
					}
					return Convert.ToInt64(value);
				}
				if (underType == UtilConstants.LongType)
				{
					return GetString(value);
				}
				if (underType == UtilConstants.IntType)
				{
					return GetString(value);
				}
				if (value is decimal num)
				{
					return "'" + num.ToString(CultureInfo.InvariantCulture) + "'";
				}
				if (value is double num2)
				{
					return "'" + num2.ToString(CultureInfo.InvariantCulture) + "'";
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					i++;
					string text3 = base.Builder.SqlParameterKeyWord + name + "_" + i;
					base.Parameters.Add(new SugarParameter(text3, value));
					return text3;
				}
				return text + "'" + GetString(value) + "'";
			}

			private object GetDateTimeString(object value)
			{
				DateTime dateTime = value.ObjToDate();
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}

			private object GetDateTimeOffsetString(object value)
			{
				DateTime dateTime = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value);
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}

			private string GetString(object value)
			{
				string text = value.ToString();
				if (text.HasValue() && text.Contains("\\"))
				{
					text = text.Replace("\\", "\\\\");
				}
				return text;
			}
		}
		public class OracleCodeFirst : CodeFirstProvider
		{
			protected override int DefultLength { get; set; }

			public OracleCodeFirst()
			{
				if (DefultLength == 0)
				{
					DefultLength = 40;
				}
			}

			protected override void GetDbType(EntityColumnInfo item, Type propertyType, DbColumnInfo result)
			{
				if (!string.IsNullOrEmpty(item.DataType))
				{
					result.DataType = item.DataType;
				}
				else if (item.DataType == null && item.UnderType == UtilConstants.LongType)
				{
					result.Length = 0;
					result.DecimalDigits = 0;
					result.DataType = "NUMBER(19,0)";
				}
				else if (item.DataType == null && item.UnderType == UtilConstants.BoolType)
				{
					result.Length = 0;
					result.DecimalDigits = 0;
					result.DataType = "NUMBER(1,0)";
				}
				else if (propertyType.IsEnum())
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName((item.Length > 9) ? UtilConstants.LongType.Name : UtilConstants.IntType.Name);
				}
				else if (propertyType.Name.Equals("Guid", StringComparison.CurrentCultureIgnoreCase))
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName(UtilConstants.StringType.Name);
					if (result.Length <= 1)
					{
						result.Length = 36;
					}
				}
				else
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName(propertyType.Name);
				}
			}

			protected override void KeyAction(EntityColumnInfo item, DbColumnInfo dbColumn, out bool pkDiff, out bool idEntityDiff)
			{
				pkDiff = item.IsPrimarykey != dbColumn.IsPrimarykey;
				idEntityDiff = false;
			}
		}
