			};

			public override List<KeyValuePair<string, CSharpDataType>> MappingTypes
			{
				get
				{
					ConfigureExternalServices configureExternalServices = Context.CurrentConnectionConfig.ConfigureExternalServices;
					if (configureExternalServices != null && configureExternalServices.AppendDataReaderTypeMappings.HasValue())
					{
						return configureExternalServices.AppendDataReaderTypeMappings.Union(MappingTypesConst).ToList();
					}
					return MappingTypesConst;
				}
			}

			public override List<string> StringThrow => new List<string> { "int32", "datetime", "decimal", "double", "byte" };

			public override string GetDbTypeName(string csharpTypeName)
			{
				if (csharpTypeName == UtilConstants.ByteArrayType.Name)
				{
					return "blob";
				}
				if (csharpTypeName.ToLower() == "int32")
				{
					csharpTypeName = "int";
				}
				if (csharpTypeName.ToLower() == "int16")
				{
					csharpTypeName = "short";
				}
				if (csharpTypeName.ToLower() == "int64")
				{
					csharpTypeName = "long";
				}
				if (csharpTypeName.ToLower().IsIn("boolean", "bool"))
				{
					csharpTypeName = "bool";
				}
				if (csharpTypeName == "Guid")
				{
					csharpTypeName = "string";
				}
				if (csharpTypeName == "DateTimeOffset")
				{
					csharpTypeName = "DateTime";
				}
				IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Value.ToString().Equals(csharpTypeName, StringComparison.CurrentCultureIgnoreCase));
				if (!enumerable.HasValue())
				{
					return "varchar";
				}
				return enumerable.First().Key;
			}

			public override string GetPropertyTypeName(string dbTypeName)
			{
				dbTypeName = dbTypeName.ToLower();
				IEnumerable<KeyValuePair<string, CSharpDataType>> enumerable = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Value.ToString().ToLower() == dbTypeName || it.Key.ToLower() == dbTypeName);
				if (dbTypeName == "int32")
				{
					return "int";
				}
				if (dbTypeName == "int64")
				{
					return "long";
				}
				if (dbTypeName == "int16")
				{
					return "short";
				}
				if (enumerable == null)
				{
					return "other";
				}
				if (dbTypeName == "xml" || dbTypeName == "string")
				{
					return "string";
				}
				if (dbTypeName == "byte[]")
				{
					return "byte[]";
				}
				if (enumerable == null || enumerable.Count() == 0)
				{
					Check.ThrowNotSupportedException($" \"{dbTypeName}\" Type NotSupported, DbBindProvider.GetPropertyTypeName error.");
					return null;
				}
				if (enumerable.First().Value == CSharpDataType.byteArray)
				{
					return "byte[]";
				}
				return enumerable.First().Value.ToString();
			}
		}
