			public override bool UpdateColumn(string tableName, DbColumnInfo column)
			{
				ConvertCreateColumnInfo(column);
				DbColumnInfo dbColumnInfo = base.Context.DbMaintenance.GetColumnInfosByTableName(tableName, isCache: false).FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(column.DbColumnName));
				if (dbColumnInfo != null && dbColumnInfo.IsNullable == column.IsNullable)
				{
					string updateColumnSqlOnlyType = GetUpdateColumnSqlOnlyType(tableName, column);
					base.Context.Ado.ExecuteCommand(updateColumnSqlOnlyType);
					return true;
				}
				return base.UpdateColumn(tableName, column);
