			protected virtual string GetUpdateColumnSqlOnlyType(string tableName, DbColumnInfo columnInfo)
			{
				string translationColumnName = base.SqlBuilder.GetTranslationColumnName(columnInfo.DbColumnName);
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				string size = GetSize(columnInfo);
