			public override bool AddRemark(EntityInfo entity)
			{
				SqlSugarProvider context = base.Context;
				foreach (EntityColumnInfo item in entity.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList())
				{
					if (item.ColumnDescription != null)
					{
						if (context.DbMaintenance.IsAnyColumnRemark(item.DbColumnName.ToUpper(IsUppper), item.DbTableName.ToUpper(IsUppper)))
						{
							context.DbMaintenance.DeleteColumnRemark(base.SqlBuilder.GetTranslationColumnName(item.DbColumnName), base.SqlBuilder.GetTranslationColumnName(item.DbTableName));
							context.DbMaintenance.AddColumnRemark(base.SqlBuilder.GetTranslationColumnName(item.DbColumnName), base.SqlBuilder.GetTranslationColumnName(item.DbTableName), item.ColumnDescription);
						}
						else
						{
							context.DbMaintenance.AddColumnRemark(base.SqlBuilder.GetTranslationColumnName(item.DbColumnName), base.SqlBuilder.GetTranslationColumnName(item.DbTableName), item.ColumnDescription);
						}
					}
				}
				if (entity.TableDescription != null)
				{
					if (context.DbMaintenance.IsAnyTableRemark(entity.DbTableName))
					{
						context.DbMaintenance.DeleteTableRemark(base.SqlBuilder.GetTranslationColumnName(entity.DbTableName));
						context.DbMaintenance.AddTableRemark(base.SqlBuilder.GetTranslationColumnName(entity.DbTableName), entity.TableDescription);
					}
					else
					{
						context.DbMaintenance.AddTableRemark(base.SqlBuilder.GetTranslationColumnName(entity.DbTableName), entity.TableDescription);
					}
				}
				return true;
			}

			public override List<DbColumnInfo> GetColumnInfosByTableName(string tableName, bool isCache = true)
			{
				string cacheKey = "DbMaintenanceProvider.GetColumnInfosByTableName." + base.SqlBuilder.GetNoTranslationColumnName(tableName).ToLower();
				cacheKey = GetCacheKey(cacheKey);
				if (!isCache)
				{
					return GetColumnInfosByTableName(tableName);
				}
				return base.Context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => GetColumnInfosByTableName(tableName));
			}

			private List<DbColumnInfo> GetColumnInfosByTableName(string tableName)
			{
				List<DbColumnInfo> oracleDbType = GetOracleDbType(tableName);
				string sql = "select *  /* " + Guid.NewGuid().ToString() + " */ from " + base.SqlBuilder.GetTranslationTableName(base.SqlBuilder.GetNoTranslationColumnName(tableName)) + " WHERE 1=2 ";
				if (!IsAnyTable(tableName, isCache: false) && !GetViewInfoList(isCache: false).Any((DbTableInfo it) => it.Name.EqualCase(tableName)))
				{
					return new List<DbColumnInfo>();
				}
				base.Context.Utilities.RemoveCache<List<DbColumnInfo>>("DbMaintenanceProvider.GetFieldComment." + tableName);
				base.Context.Utilities.RemoveCache<List<string>>("DbMaintenanceProvider.GetPrimaryKeyByTableNames." + base.SqlBuilder.GetNoTranslationColumnName(tableName).ToLower());
				bool isEnableLogEvent = base.Context.Ado.IsEnableLogEvent;
				base.Context.Ado.IsEnableLogEvent = false;
				using DbDataReader dbDataReader = (DbDataReader)base.Context.Ado.GetDataReader(sql);
				base.Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				foreach (DataRow row in dbDataReader.GetSchemaTable().Rows)
				{
					DbColumnInfo column = new DbColumnInfo
					{
						TableName = tableName,
						DataType = row["DataType"].ToString().Replace("System.", "").Trim(),
						IsNullable = (bool)row["AllowDBNull"],
						ColumnDescription = GetFieldComment(tableName, row["ColumnName"].ToString()),
						DbColumnName = row["ColumnName"].ToString(),
						IsPrimarykey = GetPrimaryKeyByTableNames(tableName).Any((string it) => it.Equals(row["ColumnName"].ToString(), StringComparison.CurrentCultureIgnoreCase)),
						Length = row["ColumnSize"].ObjToInt(),
						Scale = row["numericscale"].ObjToInt()
					};
					DbColumnInfo dbColumnInfo = oracleDbType.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(column.DbColumnName));
					if (dbColumnInfo != null)
					{
						column.OracleDataType = dbColumnInfo.DataType;
						if (dbColumnInfo.DataType.EqualCase("number"))
						{
							column.Length = row["numericprecision"].ObjToInt();
							column.Scale = row["numericscale"].ObjToInt();
							column.DecimalDigits = row["numericscale"].ObjToInt();
							if (column.Length == 38 && column.Scale == 0)
							{
								column.Length = 22;
							}
						}
						if (dbColumnInfo.DefaultValue != null)
						{
							column.DefaultValue = dbColumnInfo.DefaultValue.TrimEnd('\'').TrimStart('\'');
						}
					}
					list.Add(column);
				}
				return list;
			}

			private List<DbColumnInfo> GetOracleDbType(string tableName)
			{
				string sql = "select      \r\n                                 t1.table_name as TableName,   \r\n                                 t6.comments,        \r\n                                 t1.column_id, \r\n                                 t1.column_name as DbColumnName,     \r\n                                 t5.comments,       \r\n                                 t1.data_type as DataType,     \r\n                                 t1.data_length as Length,   \r\n                                 t1.char_length,   \r\n                                 t1.data_precision,  \r\n                                 t1.data_scale,     \r\n                                 t1.nullable,  \r\n                                 t1.data_default as DefaultValue,\r\n                                 t4.index_name,     \r\n                                 t4.column_position,  \r\n                                 t4.descend          \r\n                            from user_tab_columns t1   \r\n                            left join (select t2.table_name,     \r\n                                              t2.column_name,  \r\n                                              t2.column_position,  \r\n                                              t2.descend,      \r\n                                              t3.index_name        \r\n                                       from user_ind_columns t2   \r\n                                       left join user_indexes t3   \r\n                                         on  t2.table_name = t3.table_name and t2.index_name = t3.index_name\r\n                                        and t3.status = 'valid' and t3.uniqueness = 'unique') t4   --unique:唯一索引\r\n                              on  t1.table_name = t4.table_name and t1.column_name = t4.column_name \r\n                            left join user_col_comments t5 on   t1.table_name = t5.table_name and t1.column_name = t5.column_name \r\n                            left join user_tab_comments t6 on  t1.table_name = t6.table_name\r\n                            where upper(t1.table_name)=upper('" + tableName + "')\r\n                            order by  t1.table_name, t1.column_id";
				return base.Context.Ado.SqlQuery<DbColumnInfo>(sql);
			}

			private List<string> GetPrimaryKeyByTableNames(string tableName)
			{
				bool isEnableLogEvent = base.Context.Ado.IsEnableLogEvent;
				base.Context.Ado.IsEnableLogEvent = false;
				string sql = " select distinct cu.COLUMN_name KEYNAME  from user_cons_columns cu, user_constraints au \r\n                            where cu.constraint_name = au.constraint_name\r\n                            and au.constraint_type = 'P' and au.table_name = '" + tableName.ToUpper(IsUppper) + "'";
				List<string> result = base.Context.Ado.SqlQuery<string>(sql);
				base.Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				return result;
			}

			public string GetTableComment(string tableName)
			{
				string cacheKey = "DbMaintenanceProvider.GetTableComment." + tableName;
				List<string> orCreate = base.Context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, delegate
				{
					string sql = "SELECT COMMENTS FROM USER_TAB_COMMENTS WHERE TABLE_NAME =@tableName ORDER BY TABLE_NAME";
					bool isEnableLogEvent = base.Context.Ado.IsEnableLogEvent;
					base.Context.Ado.IsEnableLogEvent = false;
					List<string> result = base.Context.Ado.SqlQuery<string>(sql, new
					{
						tableName = tableName.ToUpper(IsUppper)
					});
					base.Context.Ado.IsEnableLogEvent = isEnableLogEvent;
