				return orCreate.FirstOrDefault((DbColumnInfo it) => it.DbColumnName.EqualCase(filedName))?.ColumnDescription;
			}

			public override bool CreateTable(string tableName, List<DbColumnInfo> columns, bool isCreatePrimaryKey = true)
			{
				if (columns.HasValue())
				{
					foreach (DbColumnInfo column in columns)
					{
						ConvertCreateColumnInfo(column);
						if (column.DbColumnName.Equals("GUID", StringComparison.CurrentCultureIgnoreCase) && column.Length == 0)
						{
							column.Length = 50;
						}
						if (column.DataType == "varchar" && column.Length == 0)
						{
							column.Length = 50;
						}
						if (column.IsIdentity)
						{
							ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
							if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.EnableOracleIdentity == true)
							{
								column.DataType = "NUMBER GENERATED ALWAYS AS IDENTITY";
							}
						}
						if (column.DataType != null)
						{
							ConnectionConfig currentConnectionConfig2 = base.Context.CurrentConnectionConfig;
							if (currentConnectionConfig2 != null && currentConnectionConfig2.MoreSettings?.OracleCodeFirstNvarchar2 == true && !column.DataType.ToLower().Contains("nvarchar2"))
							{
								column.DataType = column.DataType.ToLower().Replace("varchar", "nvarchar2");
							}
						}
					}
				}
				string createTableSql = GetCreateTableSql(tableName, columns);
				base.Context.Ado.ExecuteCommand(createTableSql);
				if (isCreatePrimaryKey)
				{
					List<DbColumnInfo> list = columns.Where((DbColumnInfo it) => it.IsPrimarykey).ToList();
					if (list.Count <= 1)
					{
						foreach (DbColumnInfo item in list)
						{
							base.Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
						}
					}
					else
					{
						string[] columnNames = list.Select((DbColumnInfo it) => it.DbColumnName).ToArray();
						base.Context.DbMaintenance.AddPrimaryKeys(tableName, columnNames);
					}
				}
				return true;
			}

			public override bool IsAnyIndex(string indexName)
			{
				string sql = string.Format(IsAnyIndexSql, indexName);
				return base.Context.Ado.GetInt(sql) == 1;
			}

			public override bool IsAnyConstraint(string constraintName)
			{
				string sql = string.Format(IsAnyIndexSql, constraintName);
				int num = base.Context.Ado.GetInt(sql);
				if (num != 2)
				{
					return num == 3;
				}
				return true;
			}

			public override bool DropIndex(string indexName, string tableName)
			{
				return DropIndex(indexName);
			}

			private static void ConvertCreateColumnInfo(DbColumnInfo x)
			{
				string[] source = new string[4] { "int", "date", "clob", "nclob" };
				if (x.OracleDataType.HasValue())
				{
					x.DataType = x.OracleDataType;
				}
				if (Enumerable.Contains(source, x.DataType?.ToLower()))
				{
					x.Length = 0;
					x.DecimalDigits = 0;
				}
				if (x.DecimalDigits > 0)
				{
					string dataType = x.DataType;
					if (dataType != null && dataType.ToLower()?.IsIn("varchar", "clob", "varchar2", "nvarchar2", "nvarchar") == true)
					{
						x.DecimalDigits = 0;
					}
				}
			}
		}
