			public override int ExecuteReturnIdentity()
			{
				bool oldIsAuto = AutoBegin();
				base.InsertBuilder.IsReturnIdentity = true;
				PreToSql();
				string text = base.InsertBuilder.ToSqlString();
				if (isIdEntityEnable())
				{
					if (text != null && text.StartsWith("INSERT ALL"))
					{
						return UseParameter().ExecuteCommand();
					}
					text += " RETURNING ID INTO :newId01 ";
					base.InsertBuilder.Parameters.Add(new SugarParameter(":newId01", 0, isOutput: true));
				}
				RestoreMapping();
				bool isDisableMasterSlaveSeparation = base.Context.Ado.IsDisableMasterSlaveSeparation;
				base.Context.Ado.IsDisableMasterSlaveSeparation = true;
				int num = base.Ado.ExecuteCommand(text, (base.InsertBuilder.Parameters == null) ? null : base.InsertBuilder.Parameters.ToArray());
				int num2 = ((!GetIdentityKeys().IsNullOrEmpty() && num != 0) ? GetSeqValue(GetSeqName()).ObjToInt() : 0);
				base.Context.Ado.IsDisableMasterSlaveSeparation = isDisableMasterSlaveSeparation;
				After(text, num2);
				AutoEnd(oldIsAuto);
				if (isIdEntityEnable())
				{
					SugarParameter? sugarParameter = base.InsertBuilder.Parameters.FirstOrDefault((SugarParameter it) => it.ParameterName == ":newId01");
					int? obj;
					if (sugarParameter == null)
					{
						obj = null;
					}
					else
					{
						object value = sugarParameter.Value;
						obj = ((value != null) ? new int?(value.ObjToInt()) : ((int?)null));
					}
					int? num3 = obj;
					return num3.GetValueOrDefault();
				}
				return num2;
			}

