			private void AutoEnd(bool oldIsAuto)
			{
				if (oldIsAuto)
				{
					base.Context.Context.CurrentConnectionConfig.IsAutoCloseConnection = oldIsAuto;
					if (base.Ado.Transaction == null)
					{
						base.Context.Ado.Close();
					}
				}
			}

			private bool AutoBegin()
			{
				bool isAutoCloseConnection = base.Context.Context.CurrentConnectionConfig.IsAutoCloseConnection;
				if (base.Context.Context.CurrentConnectionConfig.IsAutoCloseConnection)
				{
					base.Context.Context.CurrentConnectionConfig.IsAutoCloseConnection = false;
				}
				return isAutoCloseConnection;
			}

