			protected override void PreToSql()
			{
				List<string> seqNames = GetSeqNames();
				int num = base.InsertObjs.Count();
				base.InsertBuilder.OracleSeqInfoList = new Dictionary<string, int>();
				if ((seqNames.HasValue() && num > 1) || base.InsertBuilder.IsBlukCopy)
				{
					Check.Exception(seqNames.Count != seqNames.Distinct().Count(), "The field sequence needs to be unique");
					foreach (string item in seqNames)
					{
						int num2 = 0;
						num2 = base.Ado.GetInt("select  " + item + ".Nextval  from dual");
						int num3 = num - 1;
						if (num3 > 0)
						{
							StringBuilder stringBuilder = new StringBuilder();
							stringBuilder.AppendLine(" select " + item + ".nextval,t.* from (");
							for (int i = 0; i < num3; i++)
							{
								stringBuilder.AppendLine(" select 1 from dual");
								if (i < num3 - 1)
								{
									stringBuilder.AppendLine("union all");
								}
							}
							stringBuilder.AppendLine(" )t");
							base.Ado.SqlQuery<int>(stringBuilder.ToString());
						}
						base.InsertBuilder.OracleSeqInfoList.Add(item, num2);
					}
				}
				base.PreToSql();
			}
		}
		public class OracleProvider : AdoProvider
		{
			private static string[] KeyWord = new string[24]
			{
				":asc", "@asc", ":desc", "@desc", "@month", ":month", ":day", "@day", "@group", ":group",
				":index", "@index", "@order", ":order", "@user", "@level", ":user", ":level", ":type", "@type",
				":year", "@year", "@date", ":date"
			};

			public override string SqlParameterKeyWord => ":";

			public override IDbConnection Connection
			{
				get
				{
					//IL_0019: Unknown result type (might be due to invalid IL or missing references)
					//IL_0023: Expected O, but got Unknown
					try
					{
						if (_DbConnection == null)
						{
							_DbConnection = (IDbConnection)new OracleConnection(base.Context.CurrentConnectionConfig.ConnectionString);
						}
					}
					catch (Exception ex)
					{
						Check.Exception(true, ErrorMessage.ConnnectionOpen, ex.Message);
