			public override Func<string, SugarParameter[], KeyValuePair<string, SugarParameter[]>> ProcessingEventStartingSQL => delegate(string sql, SugarParameter[] parameter)
			{
				if (sql == "-- No table ")
				{
					sql = " SELECT  'No table' FROM DUAL WHERE 1=2 ";
				}
				return (base.ProcessingEventStartingSQL != null) ? base.ProcessingEventStartingSQL(sql, parameter) : new KeyValuePair<string, SugarParameter[]>(sql, parameter);
			};

			public override Action<SqlSugarException> ErrorEvent => delegate(SqlSugarException it)
			{
				if (base.ErrorEvent != null)
				{
					base.ErrorEvent(it);
				}
				if (it.Message != null && it.Message.Contains("无效的主机/绑定变量名"))
				{
					Check.ExceptionEasy(it.Message, "错误：" + it.Message + "，出现这个错的原因： 1.可能是参数名为关键词（例如 @user ）2. SQL错误。");
				}
			};

			public OracleProvider()
			{
				base.IsOpenAsync = true;
			}

			/// <summary>
			/// Only SqlServer
			/// </summary>
			/// <param name="transactionName"></param>
