			{
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				((OracleConnection)Connection).BeginTransaction();
			}

			/// <summary>
			/// Only SqlServer
			/// </summary>
			/// <param name="iso"></param>
			/// <param name="transactionName"></param>
			public override void BeginTran(IsolationLevel iso, string transactionName)
			{
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				((OracleConnection)Connection).BeginTransaction(iso);
			}

			public override IDataAdapter GetAdapter()
			{
				return new MyOracleDataAdapter();
			}

			public override DbCommand GetCommand(string sql, SugarParameter[] parameters)
			{
				//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
				//IL_00b3: Expected O, but got Unknown
				//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
				//IL_00b4: Expected O, but got Unknown
				//IL_00e9: Unknown result type (might be due to invalid IL or missing references)
				//IL_00f3: Expected O, but got Unknown
				sql = ReplaceKeyWordParameterName(sql, parameters);
				if (sql != null && sql.EndsWith(";") && (sql == null || sql.TrimStart()?.ToLower().StartsWith("begin") != true) && (sql == null || sql.TrimStart()?.ToLower().Contains("begin") != true))
				{
					sql = sql.TrimEnd(';');
				}
				OracleCommand val = new OracleCommand(sql, (OracleConnection)Connection);
				val.BindByName = true;
				((DbCommand)(object)val).CommandType = CommandType;
				((DbCommand)(object)val).CommandTimeout = CommandTimeOut;
				val.InitialLONGFetchSize = -1;
				if (base.Transaction != null)
				{
					val.Transaction = (OracleTransaction)base.Transaction;
				}
				if (parameters.HasValue())
				{
					IDataParameter[] array = ToIDbDataParameter(parameters);
					((DbParameterCollection)(object)val.Parameters).AddRange((Array)(OracleParameter[])array);
				}
				CheckConnection();
				return (DbCommand)(object)val;
			}

			public override async Task<DbCommand> GetCommandAsync(string sql, SugarParameter[] parameters)
			{
				sql = ReplaceKeyWordParameterName(sql, parameters);
				if (sql?.EndsWith(";") ?? false)
				{
					string text = sql;
					if (text == null || text.TrimStart()?.ToLower().StartsWith("begin") != true)
					{
						string text2 = sql;
						if (text2 == null || text2.TrimStart()?.ToLower().Contains("begin") != true)
						{
							sql = sql.TrimEnd(';');
						}
					}
				}
				OracleCommand sqlCommand = new OracleCommand(sql, (OracleConnection)Connection);
				sqlCommand.BindByName = true;
				((DbCommand)(object)sqlCommand).CommandType = CommandType;
				((DbCommand)(object)sqlCommand).CommandTimeout = CommandTimeOut;
				sqlCommand.InitialLONGFetchSize = -1;
				if (base.Transaction != null)
				{
					sqlCommand.Transaction = (OracleTransaction)base.Transaction;
				}
				if (parameters.HasValue())
				{
					IDataParameter[] array = ToIDbDataParameter(parameters);
					((DbParameterCollection)(object)sqlCommand.Parameters).AddRange((Array)(OracleParameter[])array);
				}
				await CheckConnectionAsync();
				return (DbCommand)(object)sqlCommand;
			}

			private string ReplaceKeyWordParameterName(string sql, SugarParameter[] parameters)
			{
				sql = ReplaceKeyWordWithAd(sql, parameters);
				if (parameters.HasValue() && CommandType != CommandType.StoredProcedure)
				{
					foreach (SugarParameter Parameter in parameters.OrderByDescending((SugarParameter x) => x.ParameterName?.Length))
					{
						if (Parameter.ParameterName != null && Parameter.ParameterName.ToLower().IsContainsStartWithIn(KeyWord))
						{
							if (parameters.Count((SugarParameter it) => it.ParameterName.StartsWith(Parameter.ParameterName)) == 1)
							{
								string text = Parameter.ParameterName + "_01";
								text = text.Insert(1, "KW");
								sql = Regex.Replace(sql, Parameter.ParameterName, text, RegexOptions.IgnoreCase);
								Parameter.ParameterName = text;
							}
							else if (Parameter.ParameterName.ToLower().IsContainsIn(KeyWord))
							{
								Check.ExceptionEasy(" " + Parameter.ParameterName + " is key word", Parameter.ParameterName + "是关键词");
							}
						}
					}
				}
				return sql;
			}

			private static string ReplaceKeyWordWithAd(string sql, SugarParameter[] parameters)
			{
				if (parameters != null && sql != null && sql.Contains("@"))
				{
					foreach (SugarParameter item in parameters.OrderByDescending((SugarParameter it) => it.ParameterName.Length))
					{
						if (item.ParameterName.StartsWith("@"))
						{
							item.ParameterName = ":" + item.ParameterName.TrimStart('@');
						}
						sql = Regex.Replace(sql, "@" + item.ParameterName.TrimStart(':'), item.ParameterName, RegexOptions.IgnoreCase);
					}
				}
				return sql;
			}

			public override void SetCommandToAdapter(IDataAdapter dataAdapter, DbCommand command)
			{
				//IL_0007: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Expected O, but got Unknown
				((MyOracleDataAdapter)dataAdapter).SelectCommand = (OracleCommand)command;
			}

			/// <summary>
			/// if mysql return MySqlParameter[] pars
			/// if sqlerver return SqlParameter[] pars ...
			/// </summary>
			/// <param name="parameters"></param>
			/// <returns></returns>
			public override IDataParameter[] ToIDbDataParameter(params SugarParameter[] parameters)
			{
				//IL_004e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0058: Expected O, but got Unknown
				//IL_04fd: Unknown result type (might be due to invalid IL or missing references)
				if (parameters == null || parameters.Length == 0)
				{
					return null;
				}
				OracleParameter[] array = (OracleParameter[])(object)new OracleParameter[parameters.Length];
				int num = 0;
				bool flag = Context.IsVarchar();
				foreach (SugarParameter sugarParameter in parameters)
				{
					if (sugarParameter.Value == null)
					{
						sugarParameter.Value = DBNull.Value;
					}
					OracleParameter sqlParameter = new OracleParameter();
					((DbParameter)(object)sqlParameter).Size = ((sugarParameter.Size != -1) ? sugarParameter.Size : 0);
					((DbParameter)(object)sqlParameter).ParameterName = sugarParameter.ParameterName;
					if (((DbParameter)(object)sqlParameter).ParameterName[0] == '@')
					{
						((DbParameter)(object)sqlParameter).ParameterName = ":" + ((DbParameter)(object)sqlParameter).ParameterName.Substring(1, ((DbParameter)(object)sqlParameter).ParameterName.Length - 1);
					}
					if (CommandType == CommandType.StoredProcedure)
					{
						((DbParameter)(object)sqlParameter).ParameterName = ((DbParameter)(object)sqlParameter).ParameterName.TrimStart(':');
					}
					if (sugarParameter.IsRefCursor)
					{
						sqlParameter.OracleDbType = (OracleDbType)121;
					}
					if (sugarParameter.IsNvarchar2 && sugarParameter.DbType == System.Data.DbType.String)
					{
						sqlParameter.OracleDbType = (OracleDbType)119;
					}
					if (sugarParameter.IsClob)
					{
						sqlParameter.OracleDbType = (OracleDbType)105;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					if (sugarParameter.IsNClob)
					{
						sqlParameter.OracleDbType = (OracleDbType)116;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					if (sugarParameter.IsArray)
					{
						sqlParameter.OracleDbType = (OracleDbType)126;
						sqlParameter.CollectionType = (OracleCollectionType)1;
					}
					if (((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.Guid)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.String;
						((DbParameter)(object)sqlParameter).Value = ((DbParameter)(object)sqlParameter).Value.ObjToString();
					}
					else if (sugarParameter.DbType == System.Data.DbType.DateTimeOffset)
					{
						if (sugarParameter.Value != DBNull.Value)
						{
							((DbParameter)(object)sqlParameter).Value = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)sugarParameter.Value);
						}
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.DateTime;
					}
					else if (sugarParameter.DbType == System.Data.DbType.Boolean)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Int16;
						if (sugarParameter.Value == DBNull.Value)
						{
							sugarParameter.Value = 0;
						}
						else
						{
							((DbParameter)(object)sqlParameter).Value = (((bool)sugarParameter.Value) ? 1 : 0);
						}
					}
					else if (sugarParameter.DbType == System.Data.DbType.DateTime)
					{
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.DateTime;
					}
					else if (sugarParameter.DbType == System.Data.DbType.Date)
					{
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Date;
					}
					else if (sugarParameter.DbType == System.Data.DbType.AnsiStringFixedLength)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiStringFixedLength;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					else if (sugarParameter.DbType == System.Data.DbType.AnsiString)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiString;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					else if (sugarParameter.DbType == System.Data.DbType.UInt32)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Int32;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					else if (sugarParameter.DbType == System.Data.DbType.UInt16)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Int16;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					else if (sugarParameter.DbType == System.Data.DbType.UInt64)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Int64;
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					else
					{
						if (sugarParameter.Value != null && sugarParameter.Value.GetType() == UtilConstants.GuidType)
						{
							sugarParameter.Value = sugarParameter.Value.ToString();
						}
						((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					}
					if (sugarParameter.Direction != 0)
					{
						((DbParameter)(object)sqlParameter).Direction = sugarParameter.Direction;
					}
					array[num] = sqlParameter;
					if (((DbParameter)(object)sqlParameter).Direction.IsIn(ParameterDirection.Output, ParameterDirection.InputOutput, ParameterDirection.ReturnValue))
					{
						if (base.OutputParameters == null)
						{
							base.OutputParameters = new List<IDataParameter>();
						}
						base.OutputParameters.RemoveAll((IDataParameter it) => it.ParameterName == ((DbParameter)(object)sqlParameter).ParameterName);
						base.OutputParameters.Add((IDataParameter)sqlParameter);
					}
					if (flag && ((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.String)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiString;
					}
					if (sugarParameter.CustomDbType != null && sugarParameter.CustomDbType is OracleDbType)
					{
						sqlParameter.OracleDbType = (OracleDbType)sugarParameter.CustomDbType;
					}
					num++;
				}
				return (IDataParameter[])array;
			}
		}
