		public class OracleBuilder : SqlBuilderProvider
		{
			public override string SqlParameterKeyWord => ":";

			public override string SqlDateNow => "sysdate";

			public override string FullSqlDateNow => "select systimestamp from dual";

			public override string SqlTranslationLeft => "\"";

			public override string SqlTranslationRight => "\"";

			public bool IsUppper
			{
				get
				{
					if (base.Context.CurrentConnectionConfig.MoreSettings == null)
					{
						return true;
					}
					return base.Context.CurrentConnectionConfig.MoreSettings.IsAutoToUpper;
				}
			}

			public override string GetTranslationTableName(string name)
			{
				string translationTableName = base.GetTranslationTableName(name);
				if (translationTableName.Contains("(") && translationTableName.Contains(")"))
				{
					return translationTableName;
				}
				return translationTableName.ToUpper(IsUppper);
			}

			public override string GetTranslationColumnName(string entityName, string propertyName)
			{
				return base.GetTranslationColumnName(entityName, propertyName).ToUpper(IsUppper);
			}

			public override string GetTranslationColumnName(string propertyName)
			{
				return base.GetTranslationColumnName(propertyName).ToUpper(IsUppper);
			}

			public override string RemoveParentheses(string sql)
			{
				if (sql.StartsWith("(") && sql.EndsWith(")"))
				{
					sql = sql.Substring(1, sql.Length - 2);
				}
				return sql;
			}

			public override void FormatSaveQueueSql(StringBuilder sqlBuilder)
			{
				string text = sqlBuilder?.ToString();
				if (text == null || text.TrimStart()?.Substring(0, 5)?.EqualCase("begin") != true)
				{
					sqlBuilder.Clear();
					sqlBuilder.AppendLine("begin");
					sqlBuilder.Append(text);
					sqlBuilder.AppendLine("end; ");
				}
			}
		}
