		public class OracleMethod : DefaultDbMethod, IDbMethods
		{
			public override string ParameterKeyWord { get; set; } = ":";

			public override string UNIX_TIMESTAMP(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				return $" (CAST({memberName} AS DATE) - DATE '1970-01-01') * 86400 ";
			}

			public override string IsNullOrEmpty(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $"( {methodCallExpressionArgs.MemberName} IS NULL )";
			}

			public override string WeekOfYear(MethodCallExpressionModel mode)
			{
				object memberName = mode.Args[0].MemberName;
				return $"TO_NUMBER(TO_CHAR({memberName}, 'WW')) ";
			}

			public override string BitwiseAnd(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				return $" BITAND({methodCallExpressionArgs.MemberName},{methodCallExpressionArgs2.MemberName}) ";
			}

			public override string BitwiseInclusiveOR(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				return $" BITOR({methodCallExpressionArgs.MemberName},{methodCallExpressionArgs2.MemberName}) ";
			}

			public override string Modulo(MethodCallExpressionModel model)
			{
				return " MOD(" + model.Args[0].MemberName?.ToString() + " , " + model.Args[1].MemberName?.ToString() + ")";
			}

			public override string GetStringJoinSelector(string result, string separator)
			{
				if (!result.Contains(","))
				{
					return $"listagg(to_char({result}),'{separator}') within group(order by {result}) ";
				}
				return $"listagg(to_char({result.Split(',').First()}),'{separator}') within group(order by {result.Split(',').Last()}) ";
			}

			public override string HasValue(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $"( {methodCallExpressionArgs.MemberName} IS NOT NULL ) ";
			}

			public override string DateDiff(MethodCallExpressionModel model)
			{
				DateType dateType = (DateType)Enum.Parse(typeof(DateType), model.Args[0].MemberValue.ObjToString());
				object memberName = model.Args[1].MemberName;
				object memberName2 = model.Args[2].MemberName;
				return dateType switch
				{
					DateType.Year => $" ( cast((months_between( {memberName2} ,  {memberName}))/12 as number(9,0) ) )", 
					DateType.Month => $" ( cast((months_between( {memberName2} ,  {memberName})) as number(9,0) ) )", 
					DateType.Day => $" ( ROUND(TO_NUMBER(cast({memberName2} as date) - cast({memberName} as date)))  )", 
					DateType.Hour => $" ( ROUND(TO_NUMBER(cast({memberName2} as date) - cast({memberName} as date)) * 24)  )", 
					DateType.Minute => $" ( ROUND(TO_NUMBER(cast({memberName2} as date) - cast({memberName} as date)) * 24 * 60) )", 
					DateType.Second => $" ( ROUND(TO_NUMBER(cast({memberName2} as date) - cast({memberName} as date)) * 24 * 60 * 60) )", 
					DateType.Millisecond => $" ( ROUND(TO_NUMBER(cast({memberName2} as date) - cast({memberName} as date)) * 24 * 60 * 60 * 60) )", 
					_ => throw new Exception(dateType.ToString() + " datediff no support"), 
				};
			}

			private void PageEach<T>(IEnumerable<T> pageItems, int pageSize, Action<List<T>> action)
			{
				if (pageItems != null && pageItems.Any())
				{
					int num = (pageItems.Count() + pageSize - 1) / pageSize;
					for (int i = 1; i <= num; i++)
					{
						List<T> obj = pageItems.Skip((i - 1) * pageSize).Take(pageSize).ToList();
						action(obj);
					}
				}
			}

			public override string ContainsArray(MethodCallExpressionModel model)
			{
				if (model.Args[0].MemberValue == null)
				{
					return base.ContainsArray(model);
				}
				object[] array = ((IEnumerable)model.Args[0].MemberValue).Cast<object>().ToArray();
				if (array.Count() < 1000)
				{
					return base.ContainsArray(model);
				}
				string result = "";
				PageEach(array, 999, delegate(List<object> it)
				{
					model.Args.First().MemberValue = it;
					result = result + base.ContainsArray(model) + " OR ";
				});
				return " ( " + result.TrimEnd(' ').TrimEnd('R').TrimEnd('O') + " ) ";
			}

			public override string ToInt64(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $" CAST({methodCallExpressionArgs.MemberName} AS Number)";
			}

			public override string ToTime(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $" to_timestamp({methodCallExpressionArgs.MemberName},'0000-01-01 hh24:mi:ss') ";
			}

			public override string Substring(MethodCallExpressionModel model)
