		public class OracleFastBuilder : FastBuilder, IFastBuilder
		{
			private EntityInfo entityInfo;

			public override bool IsActionUpdateColumns { get; set; } = true;

			public override DbFastestProperties DbFastestProperties { get; set; } = new DbFastestProperties
			{
				IsMerge = true
			};

			public override string UpdateSql { get; set; } = "UPDATE (SELECT {4}  FROM {2} TM,{3} TE WHERE {1})SET {0}";

			public OracleFastBuilder(EntityInfo entityInfo)
			{
				this.entityInfo = entityInfo;
			}

			public override async Task CreateTempAsync<T>(DataTable dt)
			{
				ISqlBuilder sqlBuilder = base.Context.Queryable<object>().SqlBuilder;
				List<string> values = (from DataColumn it in dt.Columns
					select sqlBuilder.GetTranslationColumnName(it.ColumnName)).ToList();
				string tableName = dt.TableName;
				List<string> columns = (from it in base.Context.EntityMaintenance.GetEntityInfo<T>().Columns
					where it.IsPrimarykey
					select it.DbColumnName).ToList();
				dt.TableName = "Temp" + SnowFlakeSingle.instance.getID();
				if (columns.Count() == 0 && DbFastestProperties != null && DbFastestProperties.WhereColumns.HasValue())
				{
					columns.AddRange(DbFastestProperties.WhereColumns);
				}
				string key = (from it in base.Context.Queryable<T>().AS(tableName)
					where false
					select it).Select(string.Join(",", values)).ToSql().Key;
				await base.Context.Ado.ExecuteCommandAsync($"create table {dt.TableName} as {key} ");
				base.Context.DbMaintenance.AddPrimaryKeys(dt.TableName, columns.ToArray(), "Pk_" + SnowFlakeSingle.instance.getID());
			}

			public override async Task<int> UpdateByTempAsync(string tableName, string tempName, string[] updateColumns, string[] whereColumns)
			{
				ISqlBuilder sqlBuilder = base.Context.Queryable<object>().SqlBuilder;
				Check.ArgumentNullException(!updateColumns.Any(), "update columns count is 0");
				Check.ArgumentNullException(!whereColumns.Any(), "where columns count is 0");
				string text = string.Join(",", updateColumns.Select((string it) => "TM" + it + "=TE" + it));
				string text2 = string.Join(" AND ", whereColumns.Select((string it) => "TM." + sqlBuilder.GetTranslationColumnName(it) + "=TE." + sqlBuilder.GetTranslationColumnName(it)));
				string text3 = string.Join(",", updateColumns.Select((string it) => $" TM.{sqlBuilder.GetTranslationColumnName(it)} TM{it},TE.{sqlBuilder.GetTranslationColumnName(it)} TE{it}"));
				string sql = string.Format(UpdateSql, text, text2, tableName, tempName, text3);
				return await base.Context.Ado.ExecuteCommandAsync(sql);
			}

			private OracleBulkCopy GetBulkCopyInstance()
			{
				//IL_006c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0077: Expected O, but got Unknown
				//IL_0072: Unknown result type (might be due to invalid IL or missing references)
				//IL_0078: Expected O, but got Unknown
				//IL_004e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0059: Expected O, but got Unknown
				//IL_0054: Unknown result type (might be due to invalid IL or missing references)
				//IL_005a: Expected O, but got Unknown
				if (base.Context.Ado.Connection.State == ConnectionState.Closed)
				{
					base.Context.Ado.Connection.Open();
				}
				OracleBulkCopy val = ((base.Context.Ado.Transaction != null) ? new OracleBulkCopy((OracleConnection)base.Context.Ado.Connection, (OracleBulkCopyOptions)1) : new OracleBulkCopy((OracleConnection)base.Context.Ado.Connection, (OracleBulkCopyOptions)0));
				val.BulkCopyTimeout = base.Context.Ado.CommandTimeOut;
				return val;
			}

			public override Task<int> Merge<T>(string tableName, DataTable dt, EntityInfo entityInfo, string[] whereColumns, string[] updateColumns, List<T> datas)
			{
				Check.Exception(this.entityInfo.Columns.Any((EntityColumnInfo it) => it.OracleSequenceName.HasValue()), "The BulkMerge method cannot be used for  sequence", "BulkMerge方法不能用序列");
				ISqlBuilder sqlBuilder = base.Context.Queryable<object>().SqlBuilder;
				IEnumerable<EntityColumnInfo> source = from it in entityInfo.Columns
					where !it.IsIgnore
					where !it.IsIdentity
					where !it.InsertServerTime
					where it.InsertSql == null
					where it.OracleSequenceName == null
					where !it.IsOnlyIgnoreInsert
					select it;
				string value = string.Join("  AND  ", whereColumns.Select((string it) => "tgt." + sqlBuilder.GetTranslationColumnName(it) + "=src." + sqlBuilder.GetTranslationColumnName(it)));
				string value2 = string.Join(" , ", updateColumns.Select((string it) => "tgt." + sqlBuilder.GetTranslationColumnName(it) + "=src." + sqlBuilder.GetTranslationColumnName(it)));
				string value3 = string.Join(" , ", source.Select((EntityColumnInfo it) => "tgt." + sqlBuilder.GetTranslationColumnName(it.DbColumnName)));
				string value4 = string.Join(" , ", source.Select((EntityColumnInfo it) => "src." + sqlBuilder.GetTranslationColumnName(it.DbColumnName)));
				string sql = $"MERGE INTO {sqlBuilder.GetTranslationColumnName(tableName)} tgt\r\nUSING {sqlBuilder.GetTranslationColumnName(dt.TableName)} src\r\nON ({value})\r\nWHEN MATCHED THEN\r\n    UPDATE SET {value2}\r\nWHEN NOT MATCHED THEN\r\n    INSERT ({value3})\r\n    VALUES ({value4})";
				return base.Context.Ado.ExecuteCommandAsync(sql);
			}

			public Task<int> ExecuteBulkCopyAsync(DataTable dt)
			{
				if (entityInfo.Columns.FirstOrDefault((EntityColumnInfo it) => it.IsIdentity) != null)
				{
					throw new Exception("Oracle bulkcopy no support identity");
				}
				OracleBulkCopy bulkCopyInstance = GetBulkCopyInstance();
				try
				{
					bulkCopyInstance.DestinationTableName = dt.TableName;
					bulkCopyInstance.WriteToServer(dt);
				}
				catch (Exception ex)
				{
					throw ex;
				}
				finally
				{
					CloseDb();
				}
				return Task.FromResult(dt.Rows.Count);
			}
		}
		public class OracleInsertBuilder : InsertBuilder
		{
			private int i;

			public override string SqlTemplate => "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ";

			public override string SqlTemplateBatch => "INSERT INTO {0} ({1})";

			public override string ToSqlString()
			{
				List<EntityColumnInfo> list = base.EntityInfo.Columns.Where((EntityColumnInfo it) => it.OracleSequenceName.HasValue()).ToList();
				if (base.IsNoInsertNull)
				{
					base.DbColumnInfoList = base.DbColumnInfoList.Where((DbColumnInfo it) => it.Value != null).ToList();
				}
				ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
				if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.EnableOracleIdentity == true)
				{
					base.DbColumnInfoList = base.DbColumnInfoList.Where((DbColumnInfo it) => !it.IsIdentity).ToList();
				}
				List<IGrouping<int, DbColumnInfo>> list2 = (from it in base.DbColumnInfoList
					group it by it.TableId).ToList();
				bool num = list2.Count() == 1;
				string text = string.Join(",", from it in list2.First()
					select base.Builder.GetTranslationColumnName(it.DbColumnName));
				if (num && base.EntityInfo.EntityName != "Dictionary`2")
				{
					string text2 = string.Join(",", base.DbColumnInfoList.Select((DbColumnInfo it) => base.GetDbColumn(it, base.Builder.SqlParameterKeyWord + it.DbColumnName)));
					if (list.HasValue())
					{
						text = text.TrimEnd(',') + "," + string.Join(",", list.Select((EntityColumnInfo it) => base.Builder.GetTranslationColumnName(it.DbColumnName)));
						text2 = text2.TrimEnd(',') + "," + string.Join(",", list.Select((EntityColumnInfo it) => it.OracleSequenceName + ".nextval"));
					}
					ActionMinDate();
					return string.Format(SqlTemplate, GetTableNameString, text, text2);
				}
				int num2 = 500;
				if (list2.Count >= num2)
				{
					SqlSugarProvider context = base.Context;
					if (context == null || context.CurrentConnectionConfig?.MoreSettings?.EnableOracleIdentity != true)
					{
						return Big(list, list2, text);
					}
				}
				return Small(list, list2, text);
			}

			private string Big(List<EntityColumnInfo> identities, List<IGrouping<int, DbColumnInfo>> groupList, string columnsString)
			{
				base.Context.Utilities.PageEach(groupList, 100, delegate(List<IGrouping<int, DbColumnInfo>> groupListPasge)
				{
					base.Parameters = new List<SugarParameter>();
					string text = Small(identities, groupListPasge, columnsString);
					base.Context.Ado.ExecuteCommand(text, base.Parameters);
				});
				if (identities != null && identities.Count > 0 && base.OracleSeqInfoList != null && base.OracleSeqInfoList.Any())
				{
					return $"SELECT {base.OracleSeqInfoList.First().Value - 1} FROM DUAL";
				}
				return $"SELECT {groupList.Count} FROM DUAL";
			}

			private string Small(List<EntityColumnInfo> identities, List<IGrouping<int, DbColumnInfo>> groupList, string columnsString)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.AppendLine("INSERT ALL");
				foreach (IGrouping<int, DbColumnInfo> group in groupList)
				{
					stringBuilder.Append("INTO " + GetTableNameString + " ");
					string text = "";
					stringBuilder.Append("(");
					stringBuilder.Append(columnsString);
					if (identities.HasValue() && !base.IsOffIdentity)
					{
						stringBuilder.Append("," + string.Join(",", identities.Select((EntityColumnInfo it) => base.Builder.GetTranslationColumnName(it.DbColumnName))));
					}
					stringBuilder.Append(") VALUES");
					stringBuilder.Append("(");
					text = string.Join(",", group.Select((DbColumnInfo it) => GetDbColumn(it, FormatValue(it.Value, it.PropertyName))));
					stringBuilder.Append(text);
					if (!base.IsOffIdentity && identities.HasValue())
					{
						stringBuilder.Append(",");
						foreach (EntityColumnInfo identity in identities)
						{
							int value = base.OracleSeqInfoList[identity.OracleSequenceName];
							base.OracleSeqInfoList[identity.OracleSequenceName] = base.OracleSeqInfoList[identity.OracleSequenceName] + 1;
							if (identities.Last() == identity)
							{
								stringBuilder.Append(value);
							}
							else
							{
								stringBuilder.Append(value + ",");
							}
						}
					}
					stringBuilder.AppendLine(")  ");
				}
				if (identities.HasValue())
				{
					stringBuilder.AppendLine("SELECT " + (base.OracleSeqInfoList.First().Value - 1) + "  FROM DUAL");
				}
				else
				{
					stringBuilder.AppendLine("SELECT 1 FROM DUAL");
				}
				return stringBuilder.ToString();
			}

			public object FormatValue(object value, string name)
			{
				if (value == null)
				{
					return "NULL";
				}
				string n = base.Context.GetN();
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.StringType && value.ToString().Contains("{SugarSeq:=}"))
				{
					return value.ToString().Replace("{SugarSeq:=}", "");
				}
				if (underType == UtilConstants.DateType)
				{
					DateTime dateTime = value.ObjToDate();
					if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
					{
						dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
					}
					ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.DisableMillisecond == true)
					{
						return "to_date('" + dateTime.ToString("yyyy-MM-dd HH:mm:ss") + "', 'YYYY-MM-DD HH24:MI:SS')  ";
					}
					return "to_timestamp('" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.ffffff") + "', 'YYYY-MM-DD HH24:MI:SS.FF') ";
				}
				if (underType.IsEnum())
				{
					return Convert.ToInt64(value);
				}
				if (value is TimeSpan timeSpan)
				{
					return $"INTERVAL '{timeSpan.Days} {timeSpan.Hours:D2}:{timeSpan.Minutes:D2}:{timeSpan.Seconds:D2}.{timeSpan.Milliseconds:D3}' DAY TO SECOND(3)";
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					i++;
					string text = base.Builder.SqlParameterKeyWord + name + i;
					base.Parameters.Add(new SugarParameter(text, value, System.Data.DbType.Binary));
					return text;
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.DateTimeOffsetType)
				{
					return "to_timestamp('" + UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value).ToString("yyyy-MM-dd HH:mm:ss.ffffff") + "', 'YYYY-MM-DD HH24:MI:SS.FF') ";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					if (value.ToString().Length > 1000)
					{
						i++;
						string text2 = base.Builder.SqlParameterKeyWord + name + i;
						base.Parameters.Add(new SugarParameter(text2, value));
						return text2;
					}
					return n + "'" + value.ToString().ToSqlFilter() + "'";
				}
				return n + "'" + value.ToString() + "'";
			}
		}
		public class OracleQueryBuilder : QueryBuilder
		{
			public override bool IsSelectNoAll { get; set; } = true;

			public override string SqlTemplate => "SELECT {0}{" + UtilConstants.ReplaceKey + "} FROM {1}{2}{3}{4}";

			public override bool IsComplexModel(string sql)
			{
				if (!Regex.IsMatch(sql, "AS \"\\w+\\.\\w+\""))
				{
					return Regex.IsMatch(sql, "AS \"\\w+\\.\\w+\\.\\w+\"");
				}
				return true;
			}

			public override string ToSqlString()
			{
				if (base.Offset == "true")
				{
					return OffsetPage();
				}
				if (base.Take == 1 && base.Skip == 0 && base.TranLock == null && base.OrderByValue != "ORDER BY sysdate ")
				{
					return FirstSql();
				}
				_ = base.Take;
				_ = base.Skip;
				if (base.IsDistinct && (base.Take > 1 || base.Skip > 1))
				{
					return OffsetPage();
				}
				string text = _ToSqlString();
				if (base.TranLock != null)
				{
					text += base.TranLock;
				}
				return text;
			}

			private string OffsetPage()
			{
				int num = base.Skip ?? 1;
				int? take = base.Take;
				base.Skip = null;
				base.Take = null;
				base.Offset = null;
				return $"SELECT * FROM ( SELECT PAGETABLE1.*,ROWNUM PAGEINDEX FROM( {ToSqlString()}) PAGETABLE1 WHERE ROWNUM<={num + take}) WHERE PAGEINDEX>={((num == 0) ? num : (num + 1))}";
			}

			private string FirstSql()
			{
				int num = base.Skip ?? 1;
				int? take = base.Take;
				base.Skip = null;
				base.Take = null;
				base.Offset = null;
				return $"SELECT * FROM( {ToSqlString()}) PAGETABLE1 WHERE ROWNUM<={num + take}";
			}

			public string _ToSqlString()
			{
				string orderByValue = base.OrderByValue;
				string text = orderByValue;
				bool flag = base.IsCount && base.PartitionByValue.IsNullOrEmpty();
				AppendFilter();
				base.sql = new StringBuilder();
				if (base.OrderByValue == null && (base.Skip.HasValue || base.Take.HasValue))
				{
					base.OrderByValue = " ORDER BY " + base.Builder.SqlDateNow + " ";
				}
				if (base.PartitionByValue.HasValue())
				{
					base.OrderByValue = base.PartitionByValue + base.OrderByValue;
				}
				bool flag2 = base.Skip.HasValue || base.Take.HasValue;
				string text2 = $",ROW_NUMBER() OVER({GetOrderByString}) AS RowIndex ";
				string text3 = GetGroupByString + HavingInfos;
				string text4 = ((!flag2 && base.OrderByValue.HasValue()) ? GetOrderByString : null);
				if (flag)
				{
					text4 = null;
				}
				base.sql.AppendFormat(SqlTemplate, GetSelectValue, GetTableNameString, GetWhereValueString, text3, text4);
				base.sql.Replace(UtilConstants.ReplaceKey, (!flag2) ? null : (flag ? null : text2));
				if (flag)
				{
					base.OrderByValue = orderByValue;
					return base.sql.ToString();
				}
				string text5 = ToPageSql(base.sql.ToString(), base.Take, base.Skip);
				if (GetGroupByString == null && base.Take == 1 && base.Skip == 0 && orderByValue == "ORDER BY sysdate ")
				{
					text5 = $" {base.sql.ToString()} {(WhereInfos.Any() ? "AND" : "WHERE")}   ROWNUM = 1 ";
					text5 = text5.Replace(text2, " ");
				}
				if (!string.IsNullOrEmpty(base.TranLock) && GetGroupByString == null && base.Take > 1 && !base.Skip.HasValue && orderByValue == null)
				{
					text5 = $" {base.sql.ToString()} {(WhereInfos.Any() ? "AND" : "WHERE")}   ROWNUM <= {base.Take} ";
					text5 = text5.Replace(text2, " ");
				}
				if (base.ExternalPageIndex > 0)
				{
					if (text.IsNullOrEmpty())
					{
						text = " ORDER BY " + base.Builder.SqlDateNow + " ";
					}
					text5 = $"SELECT ExternalTable.*,ROW_NUMBER() OVER({GetExternalOrderBy(text)}) AS RowIndex2 FROM ({text5}) ExternalTable ";
					text5 = ToPageSql2(text5, base.ExternalPageIndex, base.ExternalPageSize, isExternal: true);
				}
				base.OrderByValue = orderByValue;
				text5 = GetSqlQuerySql(text5);
				if (text5.IndexOf("-- No table") > 0)
				{
					return "-- No table";
				}
				return text5;
			}

			public override string ToPageSql(string sql, int? take, int? skip, bool isExternal = false)
			{
				string format = (isExternal ? ExternalPageTempalte : PageTempalte);
				if (skip.HasValue && !take.HasValue)
				{
					return string.Format(format, sql.ToString(), skip.ObjToInt() + 1, long.MaxValue);
				}
				if (!skip.HasValue && take.HasValue)
				{
					return string.Format(format, sql.ToString(), 1, take.ObjToInt());
				}
				if (skip.HasValue && take.HasValue)
				{
					return string.Format(format, sql.ToString(), skip.ObjToInt() + 1, skip.ObjToInt() + take.ObjToInt());
				}
				return sql.ToString();
			}

			public override string ToPageSql2(string sql, int? pageIndex, int? pageSize, bool isExternal = false)
			{
				return string.Format(isExternal ? ExternalPageTempalte : PageTempalte, sql.ToString(), (pageIndex - 1) * pageSize + 1, pageIndex * pageSize);
			}

			public override string GetExternalOrderBy(string externalOrderBy)
			{
				return Regex.Replace(externalOrderBy, "\\\"\\w+\\\"\\.", "");
			}
		}
		public class OracleUpdateBuilder : UpdateBuilder
		{
			private int i;

			public override string ReSetValueBySqlExpListType { get; set; } = "oracle";

			public bool IsUppper
			{
				get
				{
					if (base.Context.CurrentConnectionConfig.MoreSettings == null)
					{
						return true;
					}
					return base.Context.CurrentConnectionConfig.MoreSettings.IsAutoToUpper;
				}
			}

			protected override string TomultipleSqlString(List<IGrouping<int, DbColumnInfo>> groupList)
			{
				if (groupList.Count == 0)
				{
					return " select 0 from dual";
				}
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.AppendLine("Begin");
				stringBuilder.AppendLine(string.Join("\r\n", groupList.Select(delegate(IGrouping<int, DbColumnInfo> t)
				{
					string arg = $"UPDATE {base.GetTableNameStringNoWith} SET";
					string arg2 = string.Join(",", (from m in t
						where !m.IsPrimarykey
						where base.OldPrimaryKeys == null || !base.OldPrimaryKeys.Contains(m.DbColumnName)
						select GetOracleUpdateColums(m)).ToArray());
					List<DbColumnInfo> list = t.Where((DbColumnInfo s) => s.IsPrimarykey).ToList();
					if (base.IsWhereColumns)
					{
						List<string> primaryKeys = base.PrimaryKeys;
						if (primaryKeys != null && primaryKeys.Any())
						{
							List<DbColumnInfo> list2 = list.Where((DbColumnInfo it) => base.PrimaryKeys?.Any((string p) => p.EqualCase(it.PropertyName) || p.EqualCase(it.DbColumnName)) ?? false).ToList();
							if (list2.Any())
							{
								list = list2;
							}
						}
					}
					List<string> list3 = new List<string>();
					foreach (DbColumnInfo item in list)
					{
						string text = ((list.First() == item) ? " " : " AND ");
						text += GetOracleUpdateColums(item, isWhere: true);
						list3.Add(text);
					}
					return string.Format("{0} {1} WHERE {2};", arg, arg2, string.Join("", list3));
				}).ToArray()));
				stringBuilder.AppendLine("End;");
				return stringBuilder.ToString();
			}

			private string GetOracleUpdateColums(DbColumnInfo m, bool isWhere = false)
			{
				string text = $"\"{m.DbColumnName.ToUpper(IsUppper)}\"={base.GetDbColumn(m, FormatValue(m.Value, m.IsPrimarykey, m.PropertyName))} ";
				if (isWhere && m.Value == null)
				{
					text = text.Replace("=NULL ", " is NULL ");
				}
				return text;
			}

			public object FormatValue(object value, bool isPrimaryKey, string name)
			{
				if (value == null)
				{
					return "NULL";
				}
				string text = base.Context.GetN();
				if (isPrimaryKey)
				{
					text = "";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType)
				{
					DateTime dateTime = value.ObjToDate();
					if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
					{
						dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
					}
					ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.DisableMillisecond == true)
					{
						return "to_date('" + dateTime.ToString("yyyy-MM-dd HH:mm:ss") + "', 'YYYY-MM-DD HH24:MI:SS')  ";
					}
					return "to_timestamp('" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.ffffff") + "', 'YYYY-MM-DD HH24:MI:SS.FF') ";
				}
				if (underType.IsEnum())
				{
					return Convert.ToInt64(value);
				}
				if (underType.IsIn(UtilConstants.IntType, UtilConstants.LongType, UtilConstants.ShortType))
				{
					return value;
				}
				if (underType == UtilConstants.GuidType)
				{
					return "'" + value.ToString() + "'";
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					return "0x" + BitConverter.ToString((byte[])value).Replace("-", "");
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (value is TimeSpan timeSpan)
				{
					return $"INTERVAL '{timeSpan.Days} {timeSpan.Hours:D2}:{timeSpan.Minutes:D2}:{timeSpan.Seconds:D2}.{timeSpan.Milliseconds:D3}' DAY TO SECOND(3)";
				}
				if (underType == UtilConstants.DateTimeOffsetType)
				{
					return "to_timestamp('" + UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value).ToString("yyyy-MM-dd HH:mm:ss.ffffff") + "', 'YYYY-MM-DD HH24:MI:SS.FF') ";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					if (value.ToString().Length > 1000)
					{
						i++;
						string text2 = base.Builder.SqlParameterKeyWord + name + i;
						base.Parameters.Add(new SugarParameter(text2, value));
						return text2;
					}
					return text + "'" + value.ToString().ToSqlFilter() + "'";
				}
				return text + "'" + value.ToString() + "'";
			}

			protected override string GetJoinUpdate(string columnsString, ref string whereString)
			{
				string text = $"  {base.Builder.GetTranslationColumnName(base.TableName)}  {base.Builder.GetTranslationColumnName(base.ShortName)} ";
				foreach (JoinQueryInfo joinInfo in base.JoinInfos)
				{
					text += $"\r\n USING {base.Builder.GetTranslationColumnName(joinInfo.TableName)}  {base.Builder.GetTranslationColumnName(joinInfo.ShortName)} ON {joinInfo.JoinWhere} ";
				}
				string arg = text + "\r\n ";
				return string.Format(SqlTemplate.Replace("UPDATE", "MERGE INTO").Replace("SET", "WHEN MATCHED THEN \r\nUPDATE SET"), arg, columnsString, whereString);
			}
		}
		public class OracleUpdateable<T> : UpdateableProvider<T> where T : class, new()
		{
			protected override List<string> GetIdentityKeys()
			{
				return (from it in base.EntityInfo.Columns
					where it.OracleSequenceName.HasValue()
					select it.DbColumnName).ToList();
			}

			public override int ExecuteCommand()
			{
				if (base.UpdateObjs.Count() == 1)
				{
					int num = base.ExecuteCommand();
					if (num == -1)
					{
						return 1;
					}
					return num;
				}
				if (base.UpdateObjs.Count() == 0)
				{
					return 0;
				}
				base.ExecuteCommand();
				return base.UpdateObjs.Count();
			}

			public override async Task<int> ExecuteCommandAsync()
			{
				if (base.UpdateObjs.Count() == 1)
				{
					int num = await base.ExecuteCommandAsync();
					if (num == -1)
					{
						return 1;
					}
					return num;
				}
				if (base.UpdateObjs.Count() == 0)
				{
					return 0;
				}
				await base.ExecuteCommandAsync();
				return base.UpdateObjs.Count();
			}
		}
		public class SqliteCodeFirst : CodeFirstProvider
		{
			public override void ExistLogic(EntityInfo entityInfo)
			{
				if (!entityInfo.Columns.HasValue() || entityInfo.IsDisabledUpdateAll)
				{
					return;
				}
				if (entityInfo.Columns.Where((EntityColumnInfo it) => it.IsPrimarykey).Count() > 1)
				{
					AddColumn(entityInfo);
					return;
				}
				string tableName = GetTableName(entityInfo);
				List<DbColumnInfo> dbColumns = Context.DbMaintenance.GetColumnInfosByTableName(tableName, isCache: false);
				ConvertColumns(dbColumns);
				List<EntityColumnInfo> entityColumns = entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
				List<DbColumnInfo> list = (from dc in dbColumns
					where !entityColumns.Any((EntityColumnInfo ec) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
					where !entityColumns.Any((EntityColumnInfo ec) => dc.DbColumnName.Equals(ec.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
					select dc).ToList();
				List<EntityColumnInfo> list2 = (from ec in entityColumns
					where ec.OldDbColumnName.IsNullOrEmpty() || !dbColumns.Any((DbColumnInfo dc) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
					where !dbColumns.Any((DbColumnInfo dc) => ec.DbColumnName.Equals(dc.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
					select ec).ToList();
				List<EntityColumnInfo> list3 = (from entityColumn in entityColumns
					where !string.IsNullOrEmpty(entityColumn.OldDbColumnName)
					where dbColumns.Any((DbColumnInfo dbColumn) => entityColumn.OldDbColumnName.Equals(dbColumn.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
					select entityColumn).ToList();
				bool flag = false;
				foreach (EntityColumnInfo item2 in list2)
				{
					Context.DbMaintenance.AddColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item2));
					flag = true;
				}
				foreach (DbColumnInfo item3 in list)
				{
					ConnectionConfig currentConnectionConfig = Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.SqliteCodeFirstEnableDropColumn == true)
					{
						Context.DbMaintenance.DropColumn(tableName, item3.DbColumnName);
						flag = true;
					}
				}
				using (List<EntityColumnInfo>.Enumerator enumerator = list3.GetEnumerator())
				{
					if (enumerator.MoveNext())
					{
						_ = enumerator.Current;
						throw new NotSupportedException("rename Column");
					}
				}
				foreach (EntityColumnInfo item in entityColumns)
				{
					DbColumnInfo dbColumnInfo = dbColumns.FirstOrDefault((DbColumnInfo dc) => dc.DbColumnName.Equals(item.DbColumnName, StringComparison.CurrentCultureIgnoreCase));
					if (dbColumnInfo == null)
					{
						continue;
					}
					KeyAction(item, dbColumnInfo, out var pkDiff, out var idEntityDiff);
					if (((dbColumnInfo != null) & pkDiff) && !idEntityDiff)
					{
						if (item.IsPrimarykey)
						{
							Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
						}
						else
						{
							Context.DbMaintenance.DropConstraint(tableName, $"PK_{tableName}_{item.DbColumnName}");
						}
					}
					else if (pkDiff | idEntityDiff)
					{
						ChangeKey(entityInfo, tableName, item);
					}
				}
				if (flag && base.IsBackupTable)
				{
					Context.DbMaintenance.BackupTable(tableName, tableName + DateTime.Now.ToString("yyyyMMddHHmmss"), base.MaxBackupDataRows);
				}
			}

			private void AddColumn(EntityInfo entityInfo)
			{
				string tableName = GetTableName(entityInfo);
				List<DbColumnInfo> dbColumns2 = Context.DbMaintenance.GetColumnInfosByTableName(tableName, isCache: false);
				List<EntityColumnInfo> source = entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList();
				ConvertColumns(dbColumns2);
				foreach (EntityColumnInfo item in (from ec in source
					where ec.OldDbColumnName.IsNullOrEmpty() || !dbColumns2.Any((DbColumnInfo dc) => dc.DbColumnName.Equals(ec.OldDbColumnName, StringComparison.CurrentCultureIgnoreCase))
					where !dbColumns2.Any((DbColumnInfo dc) => ec.DbColumnName.Equals(dc.DbColumnName, StringComparison.CurrentCultureIgnoreCase))
					select ec).ToList())
				{
					if (item.IsPrimarykey || item.IsIdentity)
					{
						Check.ExceptionEasy("Multiple primary keys cannot be modified", "多主键不能修改");
					}
					Context.DbMaintenance.AddColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item));
				}
			}

			public override void NoExistLogic(EntityInfo entityInfo)
			{
				string tableName = GetTableName(entityInfo);
				_ = tableName + DateTime.Now.ToString("yyyyMMddHHmmss");
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				if (entityInfo.Columns.HasValue())
				{
					foreach (EntityColumnInfo item2 in from it in entityInfo.Columns
						orderby (!it.IsPrimarykey) ? 1 : 0
						where !it.IsIgnore
						select it)
					{
						DbColumnInfo item = EntityColumnToDbColumn(entityInfo, tableName, item2);
						list.Add(item);
					}
					if (entityInfo.IsCreateTableFiledSort)
					{
						list = list.OrderBy((DbColumnInfo c) => c.CreateTableFieldSort).ToList();
						list = list.OrderBy((DbColumnInfo it) => (!it.IsPrimarykey) ? 1 : 0).ToList();
					}
				}
				Context.DbMaintenance.CreateTable(tableName, list);
			}

			protected override DbColumnInfo EntityColumnToDbColumn(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
			{
				Type underType = UtilMethods.GetUnderType(item.PropertyInfo);
				DbColumnInfo dbColumnInfo = new DbColumnInfo
				{
					TableId = entityInfo.Columns.IndexOf(item),
					DbColumnName = (item.DbColumnName.HasValue() ? item.DbColumnName : item.PropertyName),
					IsPrimarykey = item.IsPrimarykey,
					IsIdentity = item.IsIdentity,
					TableName = tableName,
					IsNullable = item.IsNullable,
					DefaultValue = item.DefaultValue,
					ColumnDescription = item.ColumnDescription,
					Length = item.Length,
					CreateTableFieldSort = item.CreateTableFieldSort
				};
				GetDbType(item, underType, dbColumnInfo);
				if (dbColumnInfo.DataType.Equals("varchar", StringComparison.CurrentCultureIgnoreCase) && dbColumnInfo.Length == 0)
				{
					dbColumnInfo.Length = 1;
				}
				return dbColumnInfo;
			}

			protected override void ConvertColumns(List<DbColumnInfo> dbColumns)
			{
				foreach (DbColumnInfo dbColumn in dbColumns)
				{
					if (dbColumn.DataType == "DateTime")
					{
						dbColumn.Length = 0;
					}
				}
			}

			protected override void ChangeKey(EntityInfo entityInfo, string tableName, EntityColumnInfo item)
			{
				Context.DbMaintenance.UpdateColumn(tableName, EntityColumnToDbColumn(entityInfo, tableName, item));
				if (!item.IsPrimarykey)
				{
					Context.DbMaintenance.DropConstraint(tableName, null);
				}
				if (item.IsPrimarykey)
				{
					Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
				}
			}
		}
