					return "blob";
				}
				if (csharpTypeName == "Int32")
				{
					csharpTypeName = "int";
				}
				if (csharpTypeName == "Int16")
				{
					csharpTypeName = "short";
				}
				if (csharpTypeName == "Int64")
				{
					csharpTypeName = "long";
				}
				if (csharpTypeName == "Boolean")
				{
					csharpTypeName = "bool";
				}
				if (csharpTypeName == "DateTimeOffset")
				{
					csharpTypeName = "DateTime";
				}
				IEnumerable<KeyValuePair<string, CSharpDataType>> source = MappingTypes.Where<KeyValuePair<string, CSharpDataType>>((KeyValuePair<string, CSharpDataType> it) => it.Value.ToString().Equals(csharpTypeName, StringComparison.CurrentCultureIgnoreCase));
				if (!source.Any())
				{
					return "varchar";
				}
				return source.First().Key;
			}
		}
