			protected override string GetAddColumnSql(string tableName, DbColumnInfo columnInfo)
			{
				string text = base.GetAddColumnSql(tableName, columnInfo);
				if (columnInfo.DefaultValue.HasValue())
				{
					SqlSugarProvider context = base.Context;
					if (context != null && context.CurrentConnectionConfig?.MoreSettings?.SqliteCodeFirstEnableDefaultValue == true)
					{
						string text2 = columnInfo.DefaultValue;
						if (!text2.Contains("(") && !text2.EqualCase("CURRENT_TIMESTAMP") && !text2.StartsWith("'"))
						{
							text2 = text2.ToSqlValue();
						}
						text2 = " DEFAULT " + text2;
						text += text2;
					}
				}
				return text;
			}

			public override bool UpdateColumn(string tableName, DbColumnInfo column)
			{
				bool flag = base.Context.Ado.IsNoTran();
				try
				{
					if (column.IsPrimarykey)
					{
						Check.ExceptionEasy("Sqlite no support alter column primary key", "Sqlite不支持修改主键");
					}
					if (flag)
					{
						base.Context.Ado.BeginTran();
					}
					tableName = tableName ?? column.TableName;
					string dbColumnName = column.DbColumnName;
					string text = (column.DbColumnName = "Column" + SnowFlakeSingle.Instance.NextId());
					column.DefaultValue = null;
					AddColumn(tableName, column);
					base.Context.Ado.ExecuteCommand($"UPDATE {base.SqlBuilder.GetTranslationColumnName(tableName)} SET {base.SqlBuilder.GetTranslationColumnName(column.DbColumnName)}={base.SqlBuilder.GetTranslationColumnName(dbColumnName)}");
					DropColumn(tableName, dbColumnName);
					column.DbColumnName = dbColumnName;
					AddColumn(tableName, column);
					base.Context.Ado.ExecuteCommand($"UPDATE {base.SqlBuilder.GetTranslationColumnName(tableName)} SET {base.SqlBuilder.GetTranslationColumnName(column.DbColumnName)}={base.SqlBuilder.GetTranslationColumnName(text)}");
					DropColumn(tableName, text);
					if (flag)
					{
						base.Context.Ado.CommitTran();
					}
					return true;
				}
				catch (Exception)
				{
					if (flag)
					{
						base.Context.Ado.RollbackTran();
					}
					throw;
				}
			}

