			/// </summary>
			/// <param name="databaseDirectory"></param>
			/// <returns></returns>
			public override bool CreateDatabase(string databaseName, string databaseDirectory = null)
			{
				string connectionString = base.Context.CurrentConnectionConfig.ConnectionString;
				string value = Regex.Match(connectionString, "[a-z,A-Z]\\:\\\\.+\\\\").Value;
				if (value.IsNullOrEmpty())
				{
					value = Regex.Match(connectionString, "\\/.+\\/").Value;
				}
				if (value.IsNullOrEmpty())
				{
					value = Regex.Match(connectionString, "[a-z,A-Z]\\:\\\\").Value;
				}
				if (!FileHelper.IsExistDirectory(value))
				{
					FileHelper.CreateDirectory(value);
				}
				base.Context.Ado.Connection.Open();
				base.Context.Ado.Connection.Close();
				return true;
			}

			public override List<DbColumnInfo> GetColumnInfosByTableName(string tableName, bool isCache = true)
			{
				string cacheKey = "DbMaintenanceProvider.GetColumnInfosByTableName." + base.SqlBuilder.GetNoTranslationColumnName(tableName).ToLower();
				cacheKey = GetCacheKey(cacheKey);
				if (isCache)
				{
					return base.Context.Utilities.GetReflectionInoCacheInstance().GetOrCreate(cacheKey, () => GetColumnInfosByTableName(tableName));
				}
				return GetColumnInfosByTableName(tableName);
			}

			private List<DbColumnInfo> GetColumnInfosByTableName(string tableName)
			{
				//IL_007a: Unknown result type (might be due to invalid IL or missing references)
				//IL_0080: Expected O, but got Unknown
				string sql = "PRAGMA table_info(" + base.SqlBuilder.GetTranslationColumnName(tableName) + ")";
				bool isEnableLogEvent = base.Context.Ado.IsEnableLogEvent;
				base.Context.Ado.IsEnableLogEvent = false;
				string text = base.Context.Ado.GetString("SELECT sql FROM sqlite_master WHERE name='" + tableName + "' AND type='table'");
				using DbDataReader dbDataReader = (SqliteDataReader)base.Context.Ado.GetDataReader(sql);
				base.Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				while (dbDataReader.Read())
				{
					string text2 = dbDataReader.GetValue(2).ObjToString();
					int length = 0;
					int num = 0;
					if (text2.Contains("("))
					{
						if (text2.Contains(","))
						{
							string text3 = text2.Split('(').Last().TrimEnd(')');
							num = text3.Split(',').Last().ObjToInt();
							length = text3.Split(',').First().ObjToInt();
						}
						else
						{
							length = text2.Split('(').Last().TrimEnd(')')
								.ObjToInt();
						}
						text2 = text2.Split('(').First();
					}
					DbColumnInfo item = new DbColumnInfo
					{
						TableName = base.SqlBuilder.GetNoTranslationColumnName(tableName ?? ""),
						DataType = text2,
						IsNullable = !dbDataReader.GetBoolean(3),
						IsIdentity = (text.Contains("AUTOINCREMENT") && dbDataReader.GetBoolean(5).ObjToBool()),
						ColumnDescription = null,
						DbColumnName = dbDataReader.GetString(1),
						DefaultValue = dbDataReader.GetValue(4).ObjToString(),
						IsPrimarykey = dbDataReader.GetBoolean(5).ObjToBool(),
						Length = length,
						DecimalDigits = num,
						Scale = num
					};
					list.Add(item);
				}
				return list;
			}

			private List<DbColumnInfo> GetColumnsByTableName2(string tableName)
			{
				//IL_0057: Unknown result type (might be due to invalid IL or missing references)
				//IL_005d: Expected O, but got Unknown
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				string sql = "select * from " + tableName + " limit 0,1";
				bool isEnableLogEvent = base.Context.Ado.IsEnableLogEvent;
				base.Context.Ado.IsEnableLogEvent = false;
				using DbDataReader dbDataReader = (SqliteDataReader)base.Context.Ado.GetDataReader(sql);
				base.Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				List<DbColumnInfo> list = new List<DbColumnInfo>();
				foreach (DataRow row in dbDataReader.GetSchemaTable().Rows)
				{
					DbColumnInfo item = new DbColumnInfo
					{
						TableName = tableName,
						IsIdentity = (bool)row["IsAutoIncrement"],
						DbColumnName = row["ColumnName"].ToString()
					};
					list.Add(item);
				}
				return list;
			}

