			public override bool BackupTable(string oldTableName, string newTableName, int maxBackupDataRows = int.MaxValue)
			{
				oldTableName = base.SqlBuilder.GetTranslationTableName(oldTableName);
				newTableName = base.SqlBuilder.GetTranslationTableName(newTableName);
				string sql = string.Format(BackupTableSql, newTableName, oldTableName, maxBackupDataRows);
