			public override bool CreateTable(string tableName, List<DbColumnInfo> columns, bool isCreatePrimaryKey = true)
			{
				if (columns.HasValue())
				{
					foreach (DbColumnInfo column in columns)
					{
						if (column.IsIdentity && !column.IsPrimarykey)
						{
							Check.Exception(true, "Identity only primary key");
						}
					}
				}
				string text = GetCreateTableSql(tableName, columns);
				string newValue = null;
				if (!isCreatePrimaryKey || columns.Count((DbColumnInfo it) => it.IsPrimarykey) > 1)
				{
					text = text.Replace("PRIMARY KEY AUTOINCREMENT", "").Replace("PRIMARY KEY", "");
				}
				if ((columns.Count((DbColumnInfo it) => it.IsPrimarykey) > 1) & isCreatePrimaryKey)
				{
					newValue = string.Format(",\r\n Primary key({0})", string.Join(",", from it in columns
						where it.IsPrimarykey
						select base.SqlBuilder.GetTranslationColumnName(it.DbColumnName)));
					newValue = newValue.Replace("`", "\"");
				}
				text = text.Replace("$PrimaryKey", newValue);
				base.Context.Ado.ExecuteCommand(text);
				return true;
			}

			protected override string GetCreateTableSql(string tableName, List<DbColumnInfo> columns)
			{
				List<string> list = new List<string>();
				Check.Exception(columns.IsNullOrEmpty(), "No columns found ");
				foreach (DbColumnInfo column in columns)
				{
					string dbColumnName = column.DbColumnName;
					string dataType = column.DataType;
					if (dataType == "varchar" && column.Length == 0)
					{
						column.Length = 1;
					}
					string text = ((column.Length > 0) ? $"({column.Length})" : null);
					string text2 = (column.IsNullable ? CreateTableNull : CreateTableNotNull);
					string text3 = (column.IsPrimarykey ? CreateTablePirmaryKey : null);
					string text4 = (column.IsIdentity ? CreateTableIdentity : null);
					string text5 = string.Format(CreateTableColumn, base.SqlBuilder.GetTranslationColumnName(dbColumnName), dataType, text, text2, text3, text4);
					if (column.DefaultValue.HasValue())
					{
						ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
						if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.SqliteCodeFirstEnableDefaultValue == true)
						{
							string text6 = column.DefaultValue;
							if (!text6.Contains("(") && !text6.EqualCase("CURRENT_TIMESTAMP") && !text6.StartsWith("'"))
							{
								text6 = text6.ToSqlValue();
							}
							text5 = text5 + " DEFAULT " + text6;
						}
					}
					if (column.ColumnDescription.HasValue())
					{
						ConnectionConfig currentConnectionConfig2 = base.Context.CurrentConnectionConfig;
						if (currentConnectionConfig2 != null && currentConnectionConfig2.MoreSettings?.SqliteCodeFirstEnableDescription == true)
						{
							text5 = text5 + " /*" + column.ColumnDescription.Replace("\r", "").Replace("\n", "") + "*/ ";
						}
					}
					list.Add(text5);
				}
				return string.Format(CreateTableSql, base.SqlBuilder.GetTranslationTableName(tableName), string.Join(",\r\n", list)).Replace("`", "\"");
			}

