				base.Context.Ado.ExecuteCommand("PRAGMA main.page_size=1024; PRAGMA main.locking_mode=EXCLUSIVE; PRAGMA main.cache_size=5000; PRAGMA main.synchronous=NORMAL; PRAGMA main.journal_mode=WAL; VACUUM INTO '" + fullFileName.ToSqlFilter() + "'");
				return false;
			}
		}
