			public SqliteExpressionContext()
			{
				base.DbMehtods = new SqliteMethod();
			}
		}
		public class SqliteMethod : DefaultDbMethod, IDbMethods
		{
			public override string UNIX_TIMESTAMP(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				return $" CAST(STRFTIME('%s', {memberName}) AS INTEGER) ";
			}

			public override string WeekOfYear(MethodCallExpressionModel mode)
			{
				object memberName = mode.Args[0].MemberName;
				return $"STRFTIME('%W', {memberName})+1 ";
			}

			public override string Equals(MethodCallExpressionModel model)
			{
				string text = base.Equals(model);
				if (model.Args.Count == 3 && text.Trim().Last() == ')')
				{
					text = " " + text.Trim().TrimEnd(')') + " COLLATE NOCASE )  ";
				}
				return text;
			}

			public override string Collate(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				return $" {memberName}   COLLATE BINARY   ";
			}

			public override string JsonIndex(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				return $"json_extract({methodCallExpressionArgs.MemberName}, '$[{methodCallExpressionArgs2.MemberValue}]')";
			}

			public override string JsonField(MethodCallExpressionModel model)
			{
				bool flag = model.Args[1].MemberValue is string text && text[0] == '$';
				model.Parameters.RemoveAll((SugarParameter item) => item.ParameterName == (model.Args[1].MemberName?.ToString() ?? ""));
				return string.Format("json_extract({0},'{1}{2}')", model.Args[0].MemberName, flag ? string.Empty : string.Intern("$."), model.Args[1].MemberValue);
			}

			public override string GetStringJoinSelector(string result, string separator)
			{
				return $"group_concat({result},'{separator}') ";
			}

			public override string DateDiff(MethodCallExpressionModel model)
			{
				DateType dateType = (DateType)Enum.Parse(typeof(DateType), model.Args[0].MemberValue.ObjToString());
				object memberName = model.Args[1].MemberName;
				object memberName2 = model.Args[2].MemberName;
				return dateType switch
				{
					DateType.Year => $" ( strftime('%Y',{memberName2}) - strftime('%Y',{memberName}) )", 
					DateType.Month => $" ( (strftime('%m',{memberName2}) - strftime('%m',{memberName}))+(strftime('%Y',{memberName2}) - strftime('%Y',{memberName}))*12 )", 
					DateType.Day => $" (julianday( strftime('%Y-%m-%d',datetime({memberName2})) )-julianday(strftime('%Y-%m-%d',datetime({memberName})))) ", 
					DateType.Hour => $" ((julianday( strftime('%Y-%m-%d %H:%M',datetime({memberName2})) )-   julianday(strftime('%Y-%m-%d %H:%M',datetime({memberName}))))*24 )", 
					DateType.Minute => $" ((julianday( strftime('%Y-%m-%d %H:%M',datetime({memberName2})) )-   julianday(strftime('%Y-%m-%d %H:%M',datetime({memberName}))))*24*60  )", 
					DateType.Second => $" ((julianday( strftime('%Y-%m-%d %H:%M:%S',datetime({memberName2})) )-   julianday(strftime('%Y-%m-%d %H:%M:%S',datetime({memberName}))))*24*60*60  )", 
					_ => throw new Exception(dateType.ToString() + " datediff no support"), 
				};
