				switch ((DateType)Enum.Parse(typeof(DateType), text2, ignoreCase: false))
				{
				case DateType.Year:
					text2 = "%Y";
					break;
				case DateType.Month:
					text2 = "%m";
					break;
				case DateType.Day:
					text2 = "%d";
					return string.Format(" CAST(STRFTIME('{1}', DATETIME(DATETIME(strftime('%Y-%m-%d', {0})), 'LOCALTIME')) AS INTEGER)", methodCallExpressionArgs.MemberName, text2);
				case DateType.Hour:
					text2 = "%H";
					break;
				case DateType.Second:
					text2 = "%S";
					break;
				case DateType.Minute:
					text2 = "%M";
					break;
				case DateType.Weekday:
					return $" cast (strftime('%w', {methodCallExpressionArgs.MemberName}) as integer) ";
				default:
					Check.ThrowNotSupportedException(text);
