			public override string DateIsSameByType(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				object memberName2 = model.Args[1].MemberName;
				object memberValue = model.Args[2].MemberValue;
				DateType dateType = (DateType)Enum.Parse(typeof(DateType), memberValue.ObjToString(), ignoreCase: false);
				int num = 1;
				switch (dateType)
				{
				case DateType.Year:
					num /= 365;
					break;
				case DateType.Month:
					num /= 30;
					break;
				case DateType.Hour:
					num *= 24;
					break;
				case DateType.Second:
					num = num * 24 * 60 * 60;
					break;
				case DateType.Minute:
					num = num * 24 * 60;
					break;
				case DateType.Millisecond:
					num = num * 24 * 60 * 60 * 1000;
					break;
				}
				return $" Cast((JulianDay({memberName}) - JulianDay({memberName2}))  *{num} As INTEGER)";
			}

