		public class SqliteFastBuilder : IFastBuilder
		{
			private EntityInfo entityInfo;

			private bool IsUpdate;

			public EntityInfo FastEntityInfo { get; set; }

			public string CharacterSet { get; set; }

			private DataTable UpdateDataTable { get; set; }

			public bool IsActionUpdateColumns { get; set; }

			public DbFastestProperties DbFastestProperties { get; set; } = new DbFastestProperties
			{
				IsNoCopyDataTable = true
			};

			public SqlSugarProvider Context { get; set; }

			public SqliteFastBuilder(EntityInfo entityInfo)
			{
				this.entityInfo = entityInfo;
			}

			public void CloseDb()
			{
				if (Context.CurrentConnectionConfig.IsAutoCloseConnection && Context.Ado.Transaction == null)
				{
					Context.Close();
				}
			}

			public async Task CreateTempAsync<T>(DataTable dt) where T : class, new()
			{
				await Task.Delay(0);
				IsUpdate = true;
			}

			public async Task<int> ExecuteBulkCopyAsync(DataTable dt)
			{
				if (dt.Rows.Count == 0 || IsUpdate)
				{
					UpdateDataTable = dt;
					return 0;
				}
				foreach (EntityColumnInfo column in entityInfo.Columns)
				{
					if (column.IsIdentity && dt.Columns.Contains(column.DbColumnName))
					{
						dt.Columns.Remove(column.DbColumnName);
					}
				}
				List<Dictionary<string, object>> dictionary = Context.Utilities.DataTableToDictionaryList(dt.Rows.Cast<DataRow>().Take(1).CopyToDataTable());
				int num = 0;
				IDbConnection connection = Context.Ado.Connection;
				SqliteConnection val = (SqliteConnection)((connection is SqliteConnection) ? connection : null);
				Open(val);
				if (Context.Ado.Transaction == null)
				{
					SqliteTransaction transaction = val.BeginTransaction();
					try
					{
						num = await _BulkCopy(dt, dictionary, num, val);
						((DbTransaction)(object)transaction).Commit();
					}
					finally
					{
						((IDisposable)transaction)?.Dispose();
					}
				}
				else
				{
					num = await _BulkCopy(dt, dictionary, num, val);
				}
				return num;
			}

			private async Task<int> _BulkCopy(DataTable dt, List<Dictionary<string, object>> dictionary, int i, SqliteConnection cn)
			{
				SqliteCommand cmd = cn.CreateCommand();
				try
				{
					SqlSugarProvider context = Context;
					if (context != null && context.CurrentConnectionConfig?.MoreSettings?.IsCorrectErrorSqlParameterName == true)
					{
						foreach (DataRow row in dt.Rows)
						{
							((DbCommand)(object)cmd).CommandText = Context.Insertable(UtilMethods.DataRowToDictionary(row)).AS(dt.TableName).ToSqlString()
								.Replace(";SELECT LAST_INSERT_ROWID();", "");
							TransformInsertCommand(cmd);
							int num = i;
							i = num + await ((DbCommand)(object)cmd).ExecuteNonQueryAsync();
						}
					}
					else
					{
						((DbCommand)(object)cmd).CommandText = Context.Insertable(dictionary.First()).AS(dt.TableName).ToSql()
							.Key.Replace(";SELECT LAST_INSERT_ROWID();", "");
						TransformInsertCommand(cmd);
						foreach (DataRow row2 in dt.Rows)
						{
							foreach (DataColumn column in dt.Columns)
							{
								if (IsBoolTrue(row2, column))
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, (object)true);
								}
								else if (IsBoolFalse(row2, column))
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, (object)false);
								}
								else
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, row2[column.ColumnName]);
								}
							}
							int num = i;
							i = num + await ((DbCommand)(object)cmd).ExecuteNonQueryAsync();
							((DbParameterCollection)(object)cmd.Parameters).Clear();
						}
					}
				}
				finally
				{
					((IDisposable)cmd)?.Dispose();
				}
				return i;
			}

			private void TransformInsertCommand(SqliteCommand cmd)
			{
				DbFastestProperties dbFastestProperties = DbFastestProperties;
				if (dbFastestProperties != null && dbFastestProperties.IsIgnoreInsertError && ((DbCommand)(object)cmd).CommandText.StartsWith("INSERT INTO "))
				{
					((DbCommand)(object)cmd).CommandText = "INSERT OR IGNORE  INTO  " + ((DbCommand)(object)cmd).CommandText.Substring("INSERT INTO ".Length);
				}
			}

			private async Task<int> _BulkUpdate(DataTable dt, List<Dictionary<string, object>> dictionary, int i, string[] whereColums, string[] updateColums, SqliteConnection cn)
			{
				SqliteCommand cmd = cn.CreateCommand();
				try
				{
					SqlSugarProvider context = Context;
					if (context != null && context.CurrentConnectionConfig?.MoreSettings?.IsCorrectErrorSqlParameterName == true)
					{
						foreach (DataRow row in dt.Rows)
						{
							((DbCommand)(object)cmd).CommandText = Context.Updateable(UtilMethods.DataRowToDictionary(row)).WhereColumns(whereColums).UpdateColumns(updateColums)
								.AS(dt.TableName)
								.ToSqlString();
							int num = i;
							i = num + await ((DbCommand)(object)cmd).ExecuteNonQueryAsync();
						}
					}
					else
					{
						((DbCommand)(object)cmd).CommandText = Context.Updateable(dictionary.First()).WhereColumns(whereColums).UpdateColumns(updateColums)
							.AS(dt.TableName)
							.ToSql()
							.Key;
						foreach (DataRow row2 in dt.Rows)
						{
							foreach (DataColumn column in dt.Columns)
							{
								if (IsBoolTrue(row2, column))
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, (object)true);
								}
								else if (IsBoolFalse(row2, column))
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, (object)false);
								}
								else
								{
									cmd.Parameters.AddWithValue("@" + column.ColumnName, row2[column.ColumnName]);
								}
							}
							int num = i;
							i = num + await ((DbCommand)(object)cmd).ExecuteNonQueryAsync();
							((DbParameterCollection)(object)cmd.Parameters).Clear();
						}
					}
				}
				finally
				{
					((IDisposable)cmd)?.Dispose();
				}
				return i;
			}

			private static bool IsBoolFalse(DataRow dataRow, DataColumn item)
			{
				if (dataRow[item.ColumnName] != null && dataRow[item.ColumnName] is string)
				{
					return dataRow[item.ColumnName].ToString() == "isSqliteCore_False";
				}
				return false;
			}

			private static bool IsBoolTrue(DataRow dataRow, DataColumn item)
			{
				if (dataRow[item.ColumnName] != null && dataRow[item.ColumnName] is string)
				{
					return dataRow[item.ColumnName].ToString() == "isSqliteCore_True";
				}
				return false;
			}

			private static void Open(SqliteConnection cn)
			{
				if (((DbConnection)(object)cn).State != ConnectionState.Open)
				{
					((DbConnection)(object)cn).Open();
				}
			}

			public async Task<int> UpdateByTempAsync(string tableName, string tempName, string[] updateColumns, string[] whereColumns)
			{
				DataTable updateDataTable = UpdateDataTable;
				if (updateDataTable.Rows.Count == 0)
				{
					return 0;
				}
				List<Dictionary<string, object>> dictionary = Context.Utilities.DataTableToDictionaryList(updateDataTable.Rows.Cast<DataRow>().Take(1).CopyToDataTable());
				int num = 0;
				IDbConnection connection = Context.Ado.Connection;
				SqliteConnection val = (SqliteConnection)((connection is SqliteConnection) ? connection : null);
				Open(val);
				if (Context.Ado.Transaction == null)
				{
					SqliteTransaction transaction = val.BeginTransaction();
					try
					{
						num = await _BulkUpdate(updateDataTable, dictionary, num, whereColumns, updateColumns, val);
						((DbTransaction)(object)transaction).Commit();
					}
					finally
					{
						((IDisposable)transaction)?.Dispose();
					}
				}
				else
				{
					num = await _BulkUpdate(updateDataTable, dictionary, num, whereColumns, updateColumns, val);
				}
				return num;
			}

			public async Task<int> Merge<T>(string tableName, DataTable dt, EntityInfo entityInfo, string[] whereColumns, string[] updateColumns, List<T> datas) where T : class, new()
			{
				int result = 0;
				await Context.Utilities.PageEachAsync(datas, 2000, async delegate(List<T> pageItems)
				{
					StorageableResult<T> x = await Context.Storageable(pageItems).As(tableName).WhereColumns(whereColumns)
						.ToStorageAsync();
					int num = result;
					result = num + await x.BulkCopyAsync();
					num = result;
					result = num + await x.BulkUpdateAsync(updateColumns);
					return result;
				});
				return result;
			}
		}
		public class SqliteInsertBuilder : InsertBuilder
		{
			public override string SqlTemplate
			{
				get
				{
					if (base.IsReturnIdentity)
					{
						return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;SELECT LAST_INSERT_ROWID();";
					}
					return "INSERT INTO {0} \r\n           ({1})\r\n     VALUES\r\n           ({2}) ;";
				}
			}

			public override string SqlTemplateBatch => "INSERT INTO {0} ({1})";

			public override string ToSqlString()
			{
				if (base.IsNoInsertNull)
				{
					base.DbColumnInfoList = base.DbColumnInfoList.Where((DbColumnInfo it) => it.Value != null).ToList();
				}
				List<IGrouping<int, DbColumnInfo>> list = (from it in base.DbColumnInfoList
					group it by it.TableId).ToList();
				bool num = list.Count() == 1;
				string text = string.Join(",", from it in list.First()
					select base.Builder.GetTranslationColumnName(it.DbColumnName));
				if (num)
				{
					string arg = string.Join(",", base.DbColumnInfoList.Select((DbColumnInfo it) => base.GetDbColumn(it, base.Builder.SqlParameterKeyWord + it.DbColumnName)));
					ActionMinDate();
					string text2 = string.Format(SqlTemplate, GetTableNameString, text, arg);
					if (base.MySqlIgnore)
					{
						text2 = text2.Remove(0, "INSERT INTO `".Length);
						text2 = text2.Insert(0, "INSERT OR IGNORE  INTO  `");
					}
					return text2;
				}
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("INSERT INTO " + GetTableNameString + " ");
				stringBuilder.Append("(");
				stringBuilder.Append(text);
				stringBuilder.Append(") VALUES");
				string text3 = "";
				int i = 0;
				foreach (IGrouping<int, DbColumnInfo> item in list)
				{
					stringBuilder.Append("(");
					text3 = string.Join(",", item.Select((DbColumnInfo it) => base.GetDbColumn(it, FormatValue(i, it.DbColumnName, it.Value))));
					stringBuilder.Append(text3);
					if (list.Last() == item)
					{
						stringBuilder.Append(") ");
					}
					else
					{
						stringBuilder.Append("),  ");
					}
					i++;
				}
				stringBuilder.AppendLine(";SELECT LAST_INSERT_ROWID();");
				if (base.MySqlIgnore)
				{
					stringBuilder.Remove(0, "INSERT INTO `".Length);
					stringBuilder.Insert(0, "INSERT OR IGNORE  INTO  `");
				}
				return stringBuilder.ToString();
			}

			public object FormatValue(int i, string name, object value)
			{
				if (value == null)
				{
					return "NULL";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType)
				{
					DateTime dateTime = value.ObjToDate();
					if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
					{
						dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
					}
					ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.DisableMillisecond == true)
					{
						return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss") + "'";
					}
					return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
				}
				if (underType.IsEnum())
				{
					ConnMoreSettings moreSettings = base.Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						return value.ToSqlValue();
					}
					return Convert.ToInt64(value);
				}
				if (underType == UtilConstants.DateTimeOffsetType)
				{
					return GetDateTimeOffsetString(value);
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					string text = base.Builder.SqlParameterKeyWord + name + i;
					base.Parameters.Add(new SugarParameter(text, value));
					return text;
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					return "'" + value.ToString().ToSqlFilter() + "'";
				}
				return "'" + value.ToString() + "'";
			}

			private object GetDateTimeOffsetString(object value)
			{
				DateTime dateTime = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value);
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fffffff") + "'";
			}

			private object GetDateTimeString(object value)
			{
				DateTime dateTime = value.ObjToDate();
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
			}
		}
		public class SqliteQueryBuilder : QueryBuilder
		{
			public override string PageTempalte => "SELECT {0} FROM {1} {2} {3} {4} LIMIT {5},{6}";

			public override string DefaultOrderByTemplate => "ORDER BY DATETIME('now')   ";

			public override string GetSelectValue
			{
				get
				{
					string empty = string.Empty;
					empty = ((base.SelectValue != null && !(base.SelectValue is string)) ? GetSelectValueByExpression() : GetSelectValueByString());
					if (base.SelectType == ResolveExpressType.SelectMultiple)
					{
						base.SelectCacheKey += string.Join("-", JoinQueryInfos.Select((JoinQueryInfo it) => it.TableName));
					}
					if (base.IsDistinct)
					{
						empty = " DISTINCT " + empty;
					}
					if (base.SubToListParameters != null && base.SubToListParameters.Any())
					{
						empty = SubToListMethod(empty);
					}
					return empty;
				}
			}

			public override bool IsComplexModel(string sql)
			{
				if (!Regex.IsMatch(sql, "AS \\`\\w+\\.\\w+\\`"))
				{
					return Regex.IsMatch(sql, "AS \\`\\w+\\.\\w+\\.\\w+\\`");
				}
				return true;
			}

			public override string ToSqlString()
			{
				base.AppendFilter();
				string text = null;
				string orderByValue = base.OrderByValue;
				base.sql = new StringBuilder();
				base.sql.AppendFormat(SqlTemplate, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, (base.Skip.HasValue || base.Take.HasValue) ? null : GetOrderByString);
				if (base.IsCount)
				{
					return base.sql.ToString();
				}
				if (base.Skip.HasValue && !base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, (base.Skip.HasValue || base.Take.HasValue) ? null : GetOrderByString, base.Skip.ObjToInt(), long.MaxValue);
				}
				else if (!base.Skip.HasValue && base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, GetOrderByString, 0, base.Take.ObjToInt());
				}
				else if (base.Skip.HasValue && base.Take.HasValue)
				{
					if (base.OrderByValue == "ORDER BY ")
					{
						base.OrderByValue += GetSelectValue.Split(',')[0];
					}
					text = string.Format(PageTempalte, GetSelectValue, GetTableNameString, GetWhereValueString, GetGroupByString + HavingInfos, GetOrderByString, (base.Skip.ObjToInt() > 0) ? base.Skip.ObjToInt() : 0, base.Take);
				}
				else
				{
					text = base.sql.ToString();
				}
				base.OrderByValue = orderByValue;
				text = GetSqlQuerySql(text);
				if (text.IndexOf("-- No table") > 0)
				{
					return "-- No table";
				}
				return text;
			}
		}
		public class SqliteUpdateBuilder : UpdateBuilder
		{
			public override string ReSetValueBySqlExpListType { get; set; } = "sqlite";

			protected override string TomultipleSqlString(List<IGrouping<int, DbColumnInfo>> groupList)
			{
				StringBuilder stringBuilder = new StringBuilder();
				int i = 0;
				stringBuilder.AppendLine(string.Join("\r\n", groupList.Select(delegate(IGrouping<int, DbColumnInfo> t)
				{
					string arg = $"UPDATE {base.GetTableNameStringNoWith} SET";
					string arg2 = string.Join(",", (from m in t
						where !m.IsPrimarykey
						where base.OldPrimaryKeys == null || !base.OldPrimaryKeys.Contains(m.DbColumnName)
						select GetOracleUpdateColums(i, m, iswhere: false)).ToArray());
					List<DbColumnInfo> list = t.Where((DbColumnInfo s) => s.IsPrimarykey).ToList();
					if (base.IsWhereColumns)
					{
						List<string> primaryKeys = base.PrimaryKeys;
						if (primaryKeys != null && primaryKeys.Any())
						{
							List<DbColumnInfo> list2 = list.Where((DbColumnInfo it) => base.PrimaryKeys?.Any((string p) => p.EqualCase(it.PropertyName) || p.EqualCase(it.DbColumnName)) ?? false).ToList();
							if (list2.Any())
							{
								list = list2;
							}
						}
					}
					List<string> list3 = new List<string>();
					foreach (DbColumnInfo item in list)
					{
						list.First();
						string text = "";
						text += GetOracleUpdateColums(i, item, iswhere: true);
						list3.Add(text);
					}
					i++;
					return string.Format("{0} {1} WHERE {2};", arg, arg2, string.Join(" AND", list3));
				}).ToArray()));
				return stringBuilder.ToString();
			}

			private string GetOracleUpdateColums(int i, DbColumnInfo m, bool iswhere)
			{
				string text = $"\"{m.DbColumnName.ToUpper()}\"={base.GetDbColumn(m, FormatValue(i, m.DbColumnName, m.Value, iswhere))}";
				if (iswhere && m.Value == null)
				{
					text = text.Replace("=NULL", " is NULL ");
				}
				return text;
			}

			public object FormatValue(int i, string name, object value, bool iswhere)
			{
				if (value == null)
				{
					return "NULL";
				}
				Type underType = UtilMethods.GetUnderType(value.GetType());
				if (underType == UtilConstants.DateType && !iswhere)
				{
					DateTime dateTime = value.ObjToDate();
					if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
					{
						dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
					}
					ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.DisableMillisecond == true)
					{
						return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss") + "'";
					}
					return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff") + "'";
				}
				if (underType == UtilConstants.DateTimeOffsetType)
				{
					return GetDateTimeOffsetString(value);
				}
				if ((underType == UtilConstants.DateType) & iswhere)
				{
					string text = base.Builder.SqlParameterKeyWord + name + i;
					base.Parameters.Add(new SugarParameter(text, value));
					return text;
				}
				if (underType.IsEnum())
				{
					ConnMoreSettings moreSettings = base.Context.CurrentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.TableEnumIsString == true)
					{
						return value.ToSqlValue();
					}
					return Convert.ToInt64(value);
				}
				if (underType == UtilConstants.ByteArrayType)
				{
					string text2 = base.Builder.SqlParameterKeyWord + name + i;
					base.Parameters.Add(new SugarParameter(text2, value));
					return text2;
				}
				if (underType == UtilConstants.BoolType)
				{
					if (!value.ObjToBool())
					{
						return "0";
					}
					return "1";
				}
				if (underType == UtilConstants.StringType || underType == UtilConstants.ObjType)
				{
					return "'" + value.ToString().ToSqlFilter() + "'";
				}
				return "'" + value.ToString() + "'";
			}

			private object GetDateTimeOffsetString(object value)
			{
				DateTime dateTime = UtilMethods.ConvertFromDateTimeOffset((DateTimeOffset)value);
				if (dateTime < UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig))
				{
					dateTime = UtilMethods.GetMinDate(base.Context.CurrentConnectionConfig);
				}
				return "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss.fffffff") + "'";
			}
		}
		public class SqlServerCodeFirst : CodeFirstProvider
		{
			protected override string GetTableName(EntityInfo entityInfo)
			{
				string tableName = Context.EntityMaintenance.GetTableName(entityInfo.EntityName);
				string[] tableArray = tableName.Split('.');
				bool flag = tableName.Split(']').Length == 1;
				if ((tableArray.Length > 1) & flag)
				{
					SqlServerDbMaintenance sqlServerDbMaintenance = new SqlServerDbMaintenance
					{
						Context = Context
					};
					if (!sqlServerDbMaintenance.GetSchemas().Any((string it) => it.EqualCase(tableArray.First())))
					{
						return tableArray.Last();
					}
					return sqlServerDbMaintenance.SqlBuilder.GetTranslationTableName(tableName);
				}
				return tableName;
			}

			protected override void GetDbType(EntityColumnInfo item, Type propertyType, DbColumnInfo result)
			{
				if (!string.IsNullOrEmpty(item.DataType))
				{
					result.DataType = item.DataType;
					return;
				}
				if (propertyType.IsEnum())
				{
					result.DataType = Context.Ado.DbBind.GetDbTypeName((item.Length > 9) ? UtilConstants.LongType.Name : UtilConstants.IntType.Name);
					return;
				}
				string type = GetType(propertyType.Name);
				result.DataType = Context.Ado.DbBind.GetDbTypeName(type);
				if (result.DataType == "varbinary" && item.Length == 0)
				{
					result.DataType = "varbinary(max)";
				}
			}
		}
