		public class SqlServerDbMaintenance : DbMaintenanceProvider
		{
			protected override string GetDataBaseSql => "SELECT NAME FROM master.dbo.sysdatabases ORDER BY NAME";

			protected override string GetColumnInfosByTableNameSql => "SELECT sysobjects.name AS TableName,\r\n                           syscolumns.Id AS TableId,\r\n                           syscolumns.name AS DbColumnName,\r\n                           systypes.name AS DataType,\r\n                           COLUMNPROPERTY(syscolumns.id,syscolumns.name,'PRECISION') as [length],\r\n                           isnull(COLUMNPROPERTY(syscolumns.id,syscolumns.name,'Scale'),0) as Scale, \r\n\t\t\t\t\t\t   isnull(COLUMNPROPERTY(syscolumns.id,syscolumns.name,'Scale'),0) as DecimalDigits,\r\n                           Cast( sys.extended_properties.[value] as nvarchar(2000)) AS [ColumnDescription],\r\n                           syscomments.text AS DefaultValue,\r\n                           syscolumns.isnullable AS IsNullable,\r\n\t                       columnproperty(syscolumns.id,syscolumns.name,'IsIdentity')as IsIdentity,\r\n                           (CASE\r\n                                WHEN EXISTS\r\n                                       ( \r\n                                             \tselect 1\r\n\t\t\t\t\t\t\t\t\t\t\t\tfrom sysindexes i\r\n\t\t\t\t\t\t\t\t\t\t\t\tjoin sysindexkeys k on i.id = k.id and i.indid = k.indid\r\n\t\t\t\t\t\t\t\t\t\t\t\tjoin sysobjects o on i.id = o.id\r\n\t\t\t\t\t\t\t\t\t\t\t\tjoin syscolumns c on i.id=c.id and k.colid = c.colid\r\n\t\t\t\t\t\t\t\t\t\t\t\twhere o.xtype = 'U' \r\n\t\t\t\t\t\t\t\t\t\t\t\tand exists(select 1 from sysobjects where xtype = 'PK' and name = i.name) \r\n\t\t\t\t\t\t\t\t\t\t\t\tand o.name=sysobjects.name and c.name=syscolumns.name\r\n                                       ) THEN 1\r\n                                ELSE 0\r\n                            END) AS IsPrimaryKey\r\n                    FROM syscolumns\r\n                    INNER JOIN systypes ON syscolumns.xtype = systypes.xtype\r\n                    LEFT JOIN sysobjects ON syscolumns.id = sysobjects.id\r\n                    LEFT OUTER JOIN sys.extended_properties ON (sys.extended_properties.minor_id = syscolumns.colid\r\n                                                                AND sys.extended_properties.major_id = syscolumns.id)\r\n                    LEFT OUTER JOIN syscomments ON syscolumns.cdefault = syscomments.id\r\n                    WHERE syscolumns.id IN\r\n                        (SELECT id\r\n                         FROM sysobjects\r\n                         WHERE upper(xtype) IN('U',\r\n                                        'V') )\r\n                      AND (systypes.name <> 'sysname')\r\n                      AND sysobjects.name=N'{0}'\r\n                      AND systypes.name<>'geometry'\r\n                      AND systypes.name<>'geography'\r\n                    ORDER BY syscolumns.colid";

			protected override string GetTableInfoListSql => "SELECT s.Name,Convert(nvarchar(max),tbp.value) as Description\r\n                            FROM sysobjects s\r\n\t\t\t\t\t     \tLEFT JOIN sys.extended_properties as tbp ON s.id=tbp.major_id and tbp.minor_id=0 AND (tbp.Name='MS_Description' OR tbp.Name is null)  WHERE s.xtype IN('U') ";

			protected override string GetViewInfoListSql => "SELECT s.Name,Convert(varchar(max),tbp.value) as Description\r\n                            FROM sysobjects s\r\n\t\t\t\t\t     \tLEFT JOIN sys.extended_properties as tbp ON s.id=tbp.major_id and tbp.minor_id=0  AND (tbp.Name='MS_Description' OR tbp.Name is null) WHERE s.xtype IN('V')  ";

			protected override string CreateDataBaseSql => "create database {0}  ";

			protected override string AddPrimaryKeySql => "ALTER TABLE {0} ADD CONSTRAINT {1} PRIMARY KEY({2})";

			protected override string AddColumnToTableSql => "ALTER TABLE {0} ADD {1} {2}{3} {4} {5} {6}";

			protected override string AlterColumnToTableSql => "ALTER TABLE {0} ALTER COLUMN {1} {2}{3} {4} {5} {6}";

			protected override string BackupDataBaseSql => "USE master;BACKUP DATABASE {0} TO disk = '{1}'";

			protected override string CreateTableSql => "CREATE TABLE {0}(\r\n{1})";

			protected override string CreateTableColumn => "{0} {1}{2} {3} {4} {5}";

			protected override string TruncateTableSql => "TRUNCATE TABLE {0}";

			protected override string BackupTableSql => "SELECT TOP {0} * INTO {1} FROM  {2}";

			protected override string DropTableSql => "DROP TABLE {0}";

			protected override string DropColumnToTableSql => "ALTER TABLE {0} DROP COLUMN {1}";

			protected override string DropConstraintSql => "ALTER TABLE {0} DROP CONSTRAINT  {1}";

			protected override string RenameColumnSql => "exec sp_rename '{0}.{1}','{2}','column';";

			protected override string AddColumnRemarkSql => "EXECUTE sp_addextendedproperty N'MS_Description', N'{2}', N'user', N'dbo', N'table', N'{1}', N'column', N'{0}'";

			protected override string DeleteColumnRemarkSql => "EXEC sp_dropextendedproperty 'MS_Description','user',dbo,'table','{1}','column','{0}'";

			protected override string IsAnyColumnRemarkSql => "SELECT A.name AS table_name, B.name AS column_name, C.value AS column_description FROM sys.tables A LEFT JOIN sys.extended_properties C ON C.major_id = A.object_id LEFT JOIN sys.columns B ON B.object_id = A.object_id AND C.minor_id = B.column_id INNER JOIN sys.schemas SC ON SC.schema_id = A.schema_id AND SC.name = 'dbo' WHERE A.name = '{1}' and B.name = '{0}'";

