			protected override string IsAnyTableRemarkSql => "SELECT C.class_desc\r\n                                FROM sys.tables A \r\n                                LEFT JOIN sys.extended_properties C ON C.major_id = A.object_id \r\n\t\t\t\t\t\t\t\tINNER JOIN sys.schemas SC ON  SC.schema_id=A.schema_id AND SC.name='dbo'\r\n                                WHERE A.name = '{0}'  AND minor_id=0";

			protected override string RenameTableSql => "EXEC sp_rename '{0}','{1}'";

			protected override string CreateIndexSql => "CREATE {3} NONCLUSTERED INDEX Index_{0}_{2} ON {0}({1})";

