			protected override string IsAnyProcedureSql => "select count(*) from sys.objects where [object_id] = OBJECT_ID(N'{0}') and [type] in (N'P')";

			protected override string CheckSystemTablePermissionsSql => "select top 1 id from sysobjects";

			protected override string CreateTableNull => "NULL";

			protected override string CreateTableNotNull => "NOT NULL";

			protected override string CreateTablePirmaryKey => "PRIMARY KEY";

			protected override string CreateTableIdentity => "IDENTITY(1,1)";

			public override bool DropIndex(string indexName, string tableName)
			{
				indexName = base.SqlBuilder.GetTranslationColumnName(indexName);
				tableName = base.SqlBuilder.GetTranslationColumnName(tableName);
				base.Context.Ado.ExecuteCommand(" DROP INDEX  " + indexName + "  ON " + tableName);
				return true;
			}

			public override bool SetAutoIncrementInitialValue(string tableName, int initialValue)
			{
				base.Context.Ado.ExecuteCommand("DBCC CHECKIDENT ('" + tableName + $"', RESEED, {initialValue})");
				return true;
			}

			public override bool SetAutoIncrementInitialValue(Type entityType, int initialValue)
			{
				return SetAutoIncrementInitialValue(base.Context.EntityMaintenance.GetEntityInfo(entityType).DbTableName, initialValue);
			}

			public override List<DbTableInfo> GetSchemaTables(EntityInfo entityInfo)
			{
				if (entityInfo.DbTableName.Contains(".") && base.Context.CurrentConnectionConfig.DbType == DbType.SqlServer)
				{
					string schema = entityInfo.DbTableName.Split('.').First();
					if (GetSchemas().Any((string it) => it.EqualCase(schema)) || schema.EqualCase("dbo"))
					{
						return base.Context.Ado.SqlQuery<DbTableInfo>("SELECT schem.name+'.'+tb.name Name,tb.Description from \r\n                                ( SELECT obj.name,Convert(nvarchar(max),prop.value)as Description,obj.schema_id FROM sys.objects  obj\r\n                                    LEFT JOIN sys.extended_properties  prop \r\n                                    ON obj.object_id=prop.major_id\r\n                                        and prop.minor_id=0\r\n                                        AND (prop.Name='MS_Description' OR prop.Name is null)\r\n                                        WHERE obj.type IN('U')) tb\r\n                                            inner join\tsys.schemas as schem\r\n                                            on tb.schema_id=schem.schema_id ");
					}
				}
				return null;
			}

			public override bool DropColumn(string tableName, string columnName)
			{
				if (Regex.IsMatch(tableName, "^\\w+$") && Regex.IsMatch(columnName, "^\\w+$"))
				{
					string sql = $"SELECT distinct dc.name AS ConstraintName \r\nFROM sys.default_constraints dc\r\nJOIN sys.columns c ON dc.parent_column_id = c.column_id\r\nWHERE dc.parent_object_id = OBJECT_ID('{tableName}')\r\nAND c.name = '{columnName}';";
					foreach (string item in base.Context.Ado.SqlQuery<string>(sql))
					{
						if (item != null && item.ToUpper()?.StartsWith("DF__") == true)
						{
							base.Context.Ado.ExecuteCommand("ALTER TABLE " + base.SqlBuilder.GetTranslationColumnName(tableName) + " DROP CONSTRAINT " + item);
						}
					}
				}
				return base.DropColumn(tableName, columnName);
			}

			public override List<string> GetDbTypes()
			{
				return base.Context.Ado.SqlQuery<string>("SELECT name\r\nFROM sys.types\r\nWHERE is_user_defined = 0;");
			}

			public override List<string> GetTriggerNames(string tableName)
			{
				return base.Context.Ado.SqlQuery<string>("SELECT DISTINCT sysobjects.name AS TriggerName\r\nFROM sysobjects\r\nJOIN syscomments ON sysobjects.id = syscomments.id\r\nWHERE sysobjects.xtype = 'TR'\r\nAND syscomments.text LIKE '%" + tableName + "%'");
			}

			public override List<string> GetFuncList()
			{
				return base.Context.Ado.SqlQuery<string>("SELECT name\r\nFROM sys.objects\r\nWHERE type_desc  IN( 'SQL_SCALAR_FUNCTION','SQL_INLINE_TABLE_VALUED_FUNCTION') ");
			}

			private bool IsAnySchemaTable(string tableName)
			{
				if (tableName == null || !tableName.Contains("."))
				{
					return false;
				}
				List<string> obj = GetSchemas() ?? new List<string>();
				obj.Add("dbo");
				return obj.Any((string it) => it.EqualCase(tableName?.Split('.').FirstOrDefault()));
			}

			public override bool IsAnyColumnRemark(string columnName, string tableName)
			{
				if (tableName != null && tableName.Contains(".") && tableName.Contains(base.SqlBuilder.SqlTranslationLeft))
				{
					tableName = string.Join(".", from it in tableName.Split('.')
						select base.SqlBuilder.GetNoTranslationColumnName(it));
				}
				if (IsAnySchemaTable(tableName))
				{
					string text = tableName.Split('.').First();
					tableName = tableName.Split('.').Last();
					string sql = string.Format(IsAnyColumnRemarkSql.Replace("'dbo'", "'" + text + "'"), columnName, tableName);
					DataTable dataTable = base.Context.Ado.GetDataTable(sql);
					if (dataTable.Rows != null)
					{
						return dataTable.Rows.Count > 0;
					}
					return false;
				}
				return base.IsAnyColumnRemark(columnName, tableName);
			}

			public override bool DeleteColumnRemark(string columnName, string tableName)
			{
				if (tableName != null && tableName.Contains(".") && tableName.Contains(base.SqlBuilder.SqlTranslationLeft))
				{
					tableName = string.Join(".", from it in tableName.Split('.')
						select base.SqlBuilder.GetNoTranslationColumnName(it));
				}
				if (IsAnySchemaTable(tableName))
				{
					string text = tableName.Split('.').First();
					tableName = tableName.Split('.').Last();
					string text2 = DeleteColumnRemarkSql.Replace(",dbo,", "," + text + ",");
					if (!text.EqualCase("dbo"))
					{
						text2 = text2.Replace("N'user'", "N'schema'");
						text2 = text2.Replace("'user'", "N'schema'");
					}
					string sql = string.Format(text2, columnName, tableName);
					base.Context.Ado.ExecuteCommand(sql);
					return true;
				}
				return base.DeleteColumnRemark(columnName, tableName);
			}

			public override bool AddColumnRemark(string columnName, string tableName, string description)
			{
				if (tableName != null && tableName.Contains(".") && tableName.Contains(base.SqlBuilder.SqlTranslationLeft))
				{
					tableName = string.Join(".", from it in tableName.Split('.')
						select base.SqlBuilder.GetNoTranslationColumnName(it));
				}
				if (IsAnySchemaTable(tableName))
				{
					string text = tableName.Split('.').First();
					tableName = tableName.Split('.').Last();
					string text2 = AddColumnRemarkSql.Replace("N'dbo'", "N'" + text + "'");
					if (!text.EqualCase("dbo"))
					{
						text2 = text2.Replace("N'user'", "N'schema'");
					}
					string sql = string.Format(text2, columnName, tableName, description);
					base.Context.Ado.ExecuteCommand(sql);
					return true;
				}
				return base.AddColumnRemark(columnName, tableName, description);
			}

			public override void AddDefaultValue(EntityInfo entityInfo)
			{
				List<DbColumnInfo> columnInfosByTableName = GetColumnInfosByTableName(entityInfo.DbTableName, isCache: false);
				_ = base.Context;
				foreach (EntityColumnInfo item in entityInfo.Columns.Where((EntityColumnInfo it) => !it.IsIgnore).ToList())
				{
					if ((item.DefaultValue.HasValue() || (item.DefaultValue == "" && item.UnderType == UtilConstants.StringType)) && !IsAnyDefaultValue(entityInfo.DbTableName, item.DbColumnName, columnInfosByTableName))
					{
						AddDefaultValue(entityInfo.DbTableName, item.DbColumnName, item.DefaultValue);
					}
				}
			}

			public override List<string> GetIndexList(string tableName)
			{
				return base.Context.Ado.SqlQuery<string>("SELECT indexname = i.name FROM sys.indexes i\r\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\r\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\r\nWHERE i.object_id = OBJECT_ID('" + tableName + "')");
			}

