			public override bool UpdateColumn(string tableName, DbColumnInfo column)
			{
				ConvertCreateColumnInfo(column);
				if (column.DataType != null)
				{
					ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
					if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.SqlServerCodeFirstNvarchar == true && !column.DataType.ToLower().Contains("nvarchar") && !column.DataType.EndsWith(")"))
					{
						column.DataType = column.DataType.ToLower().Replace("varchar", "nvarchar");
					}
				}
				return base.UpdateColumn(tableName, column);
			}

			public override bool IsAnyTable(string tableName, bool isCache = true)
			{
				if (tableName.Contains("."))
				{
					List<string> schemas = GetSchemas();
					string first = base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').First());
					if (schemas.FirstOrDefault((string it) => it.EqualCase(first)) == null)
					{
						return base.IsAnyTable(tableName, isCache);
					}
					return base.Context.Ado.GetInt("select object_id(N'" + tableName + "')") > 0;
				}
				if (isCache)
				{
					return base.IsAnyTable(tableName, isCache);
				}
				if (tableName.Contains(base.SqlBuilder.SqlTranslationLeft))
				{
					tableName = base.SqlBuilder.GetNoTranslationColumnName(tableName);
				}
				string sql = "IF EXISTS (SELECT * FROM sys.objects with(nolock)\r\n                        WHERE type='u' AND name=N'" + tableName.ToSqlFilter() + "')  \r\n                        SELECT 1 AS res ELSE SELECT 0 AS res;";
				return base.Context.Ado.GetInt(sql) > 0;
			}

			public List<string> GetSchemas()
			{
				return base.Context.Ado.SqlQuery<string>("SELECT name FROM  sys.schemas where name <> 'dbo'");
			}

			public override bool DeleteTableRemark(string tableName)
			{
				string sql = string.Format(DeleteTableRemarkSql, tableName);
				if (tableName.Contains("."))
				{
					List<string> schemas = GetSchemas();
					string tableSchemas = base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').First());
					if (schemas.Any((string y) => y.EqualCase(tableSchemas)))
					{
						sql = string.Format(DeleteTableRemarkSql, base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').Last()));
						sql = ((!tableSchemas.EqualCase("user")) ? sql.Replace(",dbo,", "," + tableSchemas + ",").Replace("'user'", "'SCHEMA'") : sql.Replace("'user'", "'SCHEMA'").Replace("dbo", "'" + tableSchemas + "'"));
					}
				}
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}

			public override bool IsAnyTableRemark(string tableName)
			{
				string sql = string.Format(IsAnyTableRemarkSql, tableName);
				if (tableName.Contains("."))
				{
					List<string> schemas = GetSchemas();
					string tableSchemas = base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').First());
					if (schemas.Any((string y) => y.EqualCase(tableSchemas)))
					{
						sql = string.Format(IsAnyTableRemarkSql, base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').Last()));
						sql = sql.Replace("'dbo'", "'" + tableSchemas + "'");
					}
				}
				DataTable dataTable = base.Context.Ado.GetDataTable(sql);
				if (dataTable.Rows != null)
				{
					return dataTable.Rows.Count > 0;
				}
				return false;
			}

			public override bool AddTableRemark(string tableName, string description)
			{
				string sql = string.Format(AddTableRemarkSql, tableName, description);
				if (tableName.Contains("."))
				{
					List<string> schemas = GetSchemas();
					string tableSchemas = base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').First());
					if (schemas.Any((string y) => y.EqualCase(tableSchemas)))
					{
						sql = string.Format(AddTableRemarkSql, base.SqlBuilder.GetNoTranslationColumnName(tableName.Split('.').Last()), description);
						sql = ((!tableSchemas.EqualCase("user")) ? sql.Replace("N'dbo'", "N'" + tableSchemas + "'").Replace("N'user'", "N'SCHEMA'") : sql.Replace("N'user', N'dbo'", "N'user', '" + tableSchemas + "'").Replace("N'user'", "N'SCHEMA'"));
					}
				}
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}

			public override bool AddDefaultValue(string tableName, string columnName, string defaultValue)
			{
				if (defaultValue == "''")
				{
					defaultValue = "";
				}
				string text = AddDefaultValueSql;
				if (defaultValue != null && defaultValue.Replace(" ", "").Contains("()"))
				{
					text = text.Replace("'{2}'", "{2}");
				}
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				columnName = base.SqlBuilder.GetTranslationTableName(columnName);
				string sql = string.Format(text, tableName, columnName, defaultValue);
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}

			/// <summary>
			///             by current connection string
			/// </summary>
			/// <param name="databaseDirectory"></param>
			/// <returns></returns>
			public override bool CreateDatabase(string databaseName, string databaseDirectory = null)
			{
				if (databaseDirectory != null)
				{
					try
					{
						if (!FileHelper.IsExistDirectory(databaseDirectory) && FileHelper.IsExistDirectory(Path.GetPathRoot(databaseDirectory)))
						{
							FileHelper.CreateDirectory(databaseDirectory);
						}
					}
					catch
					{
					}
				}
				string database = base.Context.Ado.Connection.Database;
				string text = base.Context.CurrentConnectionConfig.ConnectionString;
				if (Regex.Split(text, database).Length > 2)
				{
					string value = Regex.Match(text, "database\\=\\w+|datasource\\=\\w+", RegexOptions.IgnoreCase).Value;
					if (!string.IsNullOrEmpty(value))
					{
						text = text.Replace(value, "database=master");
					}
					else
					{
						Check.ExceptionEasy("Failed to create the database. The database name has a keyword. Please change the name", "建库失败，库名存在关键字，请换一个名字");
					}
				}
				else
				{
					text = text.Replace(database, "master");
				}
				SqlSugarClient sqlSugarClient = new SqlSugarClient(new ConnectionConfig
				{
					DbType = base.Context.CurrentConnectionConfig.DbType,
					IsAutoCloseConnection = true,
					ConnectionString = text
				});
				if (!GetDataBaseList(sqlSugarClient).Any((string it) => it.Equals(databaseName, StringComparison.CurrentCultureIgnoreCase)))
				{
					string separatorChar = UtilMethods.GetSeparatorChar();
					string text2 = CreateDataBaseSql;
					if (databaseDirectory.HasValue())
					{
						text2 += "on primary \r\n                                        (\r\n                                            name = N'{0}',\r\n                                            filename = N'{1}\\{0}.mdf',\r\n                                            size = 10mb,\r\n                                            maxsize = 5000mb,\r\n                                            filegrowth = 1mb\r\n                                        ),\r\n                                        (\r\n                                            name = N'{0}_ndf',   \r\n                                            filename = N'{1}\\{0}.ndf',\r\n                                            size = 10mb,\r\n                                            maxsize = 5000mb,\r\n                                             filegrowth =10mb\r\n                                        )\r\n                                        log on  \r\n                                        (\r\n                                            name = N'{0}_log',\r\n                                            filename = N'{1}\\{0}.ldf',\r\n                                            size = 100mb,\r\n                                            maxsize = 1gb,\r\n                                            filegrowth = 10mb\r\n                                        ); ";
						databaseDirectory = databaseDirectory.Replace("\\", separatorChar);
					}
					if (databaseName.Contains("."))
					{
						databaseName = "[" + databaseName + "]";
					}
					else if (Regex.IsMatch(databaseName, "^\\d.*"))
					{
						databaseName = "[" + databaseName + "]";
					}
					sqlSugarClient.Ado.ExecuteCommand(string.Format(text2, databaseName, databaseDirectory));
				}
				return true;
			}

			public override bool CreateTable(string tableName, List<DbColumnInfo> columns, bool isCreatePrimaryKey = true)
			{
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				foreach (DbColumnInfo column in columns)
				{
					ConvertCreateColumnInfo(column);
					if (column.DataType == "decimal" && column.DecimalDigits == 0 && column.Length == 0)
					{
						column.DecimalDigits = 4;
						column.Length = 18;
					}
					else if (column.DataType != null)
					{
						ConnectionConfig currentConnectionConfig = base.Context.CurrentConnectionConfig;
						if (currentConnectionConfig != null && currentConnectionConfig.MoreSettings?.SqlServerCodeFirstNvarchar == true && !column.DataType.ToLower().Contains("nvarchar") && !column.DataType.EndsWith(")"))
						{
							column.DataType = column.DataType.ToLower().Replace("varchar", "nvarchar");
						}
					}
				}
				string createTableSql = GetCreateTableSql(tableName, columns);
				base.Context.Ado.ExecuteCommand(createTableSql);
				if (isCreatePrimaryKey)
				{
					List<DbColumnInfo> list = columns.Where((DbColumnInfo it) => it.IsPrimarykey).ToList();
					if (list.Count > 1)
					{
						base.Context.DbMaintenance.AddPrimaryKeys(tableName, list.Select((DbColumnInfo it) => it.DbColumnName).ToArray());
					}
					else
					{
						foreach (DbColumnInfo item in list)
						{
							base.Context.DbMaintenance.AddPrimaryKey(tableName, item.DbColumnName);
						}
					}
				}
				return true;
			}

			private static void ConvertCreateColumnInfo(DbColumnInfo x)
			{
				string[] source = new string[15]
				{
					"int", "text", "image", "smallint", "bigint", "date", "bit", "ntext", "datetime", "datetime2",
					"uniqueidentifier", "tinyint", "rowversion", "timestamp", "money"
				};
				if (x.DataType.EqualCase("nvarchar") || x.DataType.EqualCase("varchar"))
				{
					if (x.Length < 1)
					{
						x.DataType += "(max)";
					}
				}
				else if (Enumerable.Contains(source, x.DataType?.ToLower()))
				{
					x.Length = 0;
					x.DecimalDigits = 0;
				}
			}

			public override List<DbColumnInfo> GetColumnInfosByTableName(string tableName, bool isCache = true)
			{
				tableName = base.SqlBuilder.GetNoTranslationColumnName(tableName);
				return base.GetColumnInfosByTableName(tableName, isCache);
			}

			public override bool RenameColumn(string tableName, string oldColumnName, string newColumnName)
			{
				tableName = base.SqlBuilder.GetTranslationTableName(tableName);
				oldColumnName = base.SqlBuilder.GetTranslationColumnName(oldColumnName);
				newColumnName = base.SqlBuilder.GetNoTranslationColumnName(newColumnName);
				string sql = string.Format(RenameColumnSql, tableName, oldColumnName, newColumnName);
				base.Context.Ado.ExecuteCommand(sql);
				return true;
			}
		}
