		public class SqlServerMethod : DefaultDbMethod, IDbMethods
		{
			public override string UNIX_TIMESTAMP(MethodCallExpressionModel model)
			{
				object memberName = model.Args[0].MemberName;
				return $" DATEDIFF(SECOND, '1970-01-01', {memberName}) ";
			}

			public override string ToDecimal(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $" CAST({methodCallExpressionArgs.MemberName} AS DECIMAL(18,6)) ";
			}

			public override string JsonArrayLength(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				return $" (SELECT COUNT(*) FROM OPENJSON({methodCallExpressionArgs.MemberName})) ";
			}

			public override string JsonIndex(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				return $"JSON_VALUE({methodCallExpressionArgs.MemberName}, '$[{methodCallExpressionArgs2.MemberValue}]')";
			}

			public override string CharIndexNew(MethodCallExpressionModel model)
			{
				return string.Format("CHARINDEX ({1},{0})", model.Args[0].MemberName, model.Args[1].MemberName);
			}

			public override string WeekOfYear(MethodCallExpressionModel mode)
			{
				object memberName = mode.Args[0].MemberName;
				return $"DATEPART(WEEK, {memberName})  ";
			}

			public override string GetTableWithDataBase(string dataBaseName, string tableName)
			{
				return dataBaseName + ".dbo." + tableName;
			}

			public override string GetForXmlPath()
			{
				return "  FOR XML PATH('')),1,len(N','),'')  ";
			}

			public override string GetStringJoinSelector(string result, string separator)
			{
				if (result.ObjToString().Trim().StartsWith("DISTINCT ", StringComparison.OrdinalIgnoreCase))
				{
					int num = result.IndexOf(result, StringComparison.Ordinal);
					result = result.Substring(num + 9);
					return $"stuff((SELECT DISTINCT cast(N'{separator}' as nvarchar(max)) + cast({result} as nvarchar(max))";
				}
				return $"stuff((SELECT cast(N'{separator}' as nvarchar(max)) + cast({result} as nvarchar(max))";
			}

			public override string DateValue(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				if (methodCallExpressionArgs.MemberName != null && methodCallExpressionArgs.MemberName is DateTime)
				{
					if (methodCallExpressionArgs2.MemberValue?.ToString() == DateType.Weekday.ToString())
					{
						return $" (datepart({methodCallExpressionArgs2.MemberValue},'{methodCallExpressionArgs.MemberName}')-1) ";
					}
					return $" datepart({methodCallExpressionArgs2.MemberValue},'{methodCallExpressionArgs.MemberName}') ";
				}
				if (methodCallExpressionArgs2.MemberValue?.ToString() == DateType.Weekday.ToString())
				{
					return $" (datepart({methodCallExpressionArgs2.MemberValue},{methodCallExpressionArgs.MemberName})-1) ";
				}
				return $" datepart({methodCallExpressionArgs2.MemberValue},{methodCallExpressionArgs.MemberName}) ";
			}

			public override string HasValue(MethodCallExpressionModel model)
			{
				if (model.Args[0].Type == UtilConstants.GuidType)
				{
					MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
					return $"( {methodCallExpressionArgs.MemberName} IS NOT NULL )";
				}
				if (model.Args[0].Type.IsIn(UtilConstants.DobType, UtilConstants.DecType, UtilConstants.DateTimeOffsetType, UtilConstants.DateType))
				{
					MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[0];
					return $"( {methodCallExpressionArgs2.MemberName} IS NOT NULL )";
				}
				MethodCallExpressionArgs methodCallExpressionArgs3 = model.Args[0];
				return string.Format("( {0}<>'' AND {0} IS NOT NULL )", methodCallExpressionArgs3.MemberName);
			}

			public override string JsonField(MethodCallExpressionModel model)
			{
				MethodCallExpressionArgs methodCallExpressionArgs = model.Args[0];
				MethodCallExpressionArgs methodCallExpressionArgs2 = model.Args[1];
				string json = GetJson(methodCallExpressionArgs.MemberName, methodCallExpressionArgs2.MemberName, model.Args.Count() == 2);
				if (model.Args.Count > 2)
				{
					json = GetJson(json, model.Args[2].MemberName, model.Args.Count() == 3);
				}
				if (model.Args.Count > 3)
				{
					json = GetJson(json, model.Args[3].MemberName, model.Args.Count() == 4);
				}
				if (model.Args.Count > 4)
