			public override string TrimStart(MethodCallExpressionModel mode)
			{
				object memberName = mode.Args[0].MemberName;
				object memberName2 = mode.Args[1].MemberName;
				return $" CASE WHEN LEFT({memberName}, 1) = {memberName2} THEN RIGHT({memberName}, LEN({memberName}) - 1) ELSE {memberName} END ";
			}

			public override string PadLeft(MethodCallExpressionModel mode)
			{
				object memberName = mode.Args[0].MemberName;
				object memberName2 = mode.Args[1].MemberName;
				object memberName3 = mode.Args[2].MemberName;
