			/// <summary>
			/// if mysql return MySqlParameter[] pars
			/// if sqlerver return SqlParameter[] pars ...
			/// </summary>
			/// <param name="parameters"></param>
			/// <returns></returns>
			public SqlParameter[] GetSqlParameter(params SugarParameter[] parameters)
			{
				//IL_004e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0058: Expected O, but got Unknown
				bool flag = Context.IsVarchar();
				if (parameters == null || parameters.Length == 0)
				{
					return null;
				}
				SqlParameter[] array = (SqlParameter[])(object)new SqlParameter[parameters.Length];
				int num = 0;
				foreach (SugarParameter sugarParameter in parameters)
				{
					if (sugarParameter.Value == null)
					{
						sugarParameter.Value = DBNull.Value;
					}
					SqlParameter sqlParameter = new SqlParameter();
					((DbParameter)(object)sqlParameter).ParameterName = sugarParameter.ParameterName;
					if (!string.IsNullOrEmpty(sugarParameter.UdtTypeName))
					{
						sqlParameter.UdtTypeName = sugarParameter.UdtTypeName;
					}
					((DbParameter)(object)sqlParameter).Size = sugarParameter.Size;
					((DbParameter)(object)sqlParameter).Value = sugarParameter.Value;
					((DbParameter)(object)sqlParameter).DbType = GetDbType(sugarParameter);
					if (sugarParameter.DbType == System.Data.DbType.Time)
					{
						sqlParameter.SqlDbType = SqlDbType.Time;
						if (((DbParameter)(object)sqlParameter).Value != DBNull.Value)
						{
							((DbParameter)(object)sqlParameter).Value = DateTime.Parse(sugarParameter.Value?.ToString()).TimeOfDay;
						}
					}
					else if (sugarParameter.Value != null && sugarParameter.Value is XElement)
					{
						sqlParameter.SqlDbType = SqlDbType.Xml;
						((DbParameter)(object)sqlParameter).Value = (sugarParameter.Value as XElement).ToString();
					}
					if (((DbParameter)(object)sqlParameter).Value != null && ((DbParameter)(object)sqlParameter).Value != DBNull.Value && ((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.DateTime && Convert.ToDateTime(((DbParameter)(object)sqlParameter).Value) == DateTime.MinValue)
					{
						((DbParameter)(object)sqlParameter).Value = UtilMethods.GetMinDate(Context.CurrentConnectionConfig);
					}
					if (sugarParameter.Direction == (ParameterDirection)0)
					{
						sugarParameter.Direction = ParameterDirection.Input;
					}
					((DbParameter)(object)sqlParameter).Direction = sugarParameter.Direction;
					array[num] = sqlParameter;
					if (sugarParameter.TypeName.HasValue())
					{
						sqlParameter.TypeName = sugarParameter.TypeName;
						sqlParameter.SqlDbType = SqlDbType.Structured;
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.Object;
					}
					if (((DbParameter)(object)sqlParameter).Direction.IsIn(ParameterDirection.Output, ParameterDirection.InputOutput, ParameterDirection.ReturnValue))
					{
						if (base.OutputParameters == null)
						{
							base.OutputParameters = new List<IDataParameter>();
						}
						base.OutputParameters.RemoveAll((IDataParameter it) => it.ParameterName == ((DbParameter)(object)sqlParameter).ParameterName);
						base.OutputParameters.Add((IDataParameter)sqlParameter);
					}
					if (flag && ((DbParameter)(object)sqlParameter).DbType == System.Data.DbType.String)
					{
						((DbParameter)(object)sqlParameter).DbType = System.Data.DbType.AnsiString;
					}
					if (sugarParameter.CustomDbType != null && sugarParameter.CustomDbType is SqlDbType)
					{
						sqlParameter.SqlDbType = (SqlDbType)sugarParameter.CustomDbType;
					}
					if (((DbParameter)(object)sqlParameter).Direction == ParameterDirection.Output && sugarParameter.Scale > 0)
					{
						sqlParameter.Scale = sugarParameter.Scale;
					}
					num++;
				}
				return array;
			}

			private static System.Data.DbType GetDbType(SugarParameter parameter)
			{
				if (parameter.DbType == System.Data.DbType.UInt16)
				{
					return System.Data.DbType.Int16;
				}
				if (parameter.DbType == System.Data.DbType.UInt32)
				{
					return System.Data.DbType.Int32;
				}
				if (parameter.DbType == System.Data.DbType.UInt64)
				{
					return System.Data.DbType.Int64;
				}
				return parameter.DbType;
			}
		}
