			public virtual RepositoryType CopyNew<RepositoryType>(IServiceProvider serviceProvider) where RepositoryType : ISugarRepository
			{
				return (RepositoryType)handleDependencies(typeof(RepositoryType), serviceProvider, needNewCopy: true);
			}

			private object handleDependencies(Type type, IServiceProvider serviceProvider, bool needNewCopy = false)
			{
				ConstructorInfo constructorInfo = null;
				Type type2 = type;
				ParameterInfo[] array = ((!type.IsInterface || !IsAssignableToBaseRepository(type)) ? type.GetConstructors().FirstOrDefault() : (type2 = serviceProvider.GetService(type)?.GetType()).GetConstructors().FirstOrDefault())?.GetParameters();
				if (array == null || array.Length == 0)
				{
					object service = serviceProvider.GetService(type);
					if (service is ISugarRepository sugarRepository)
					{
						return setContext(sugarRepository, needNewCopy);
					}
					return service;
				}
				List<object> list = new List<object>();
				ParameterInfo[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					Type parameterType = array2[i].ParameterType;
					list.Add(handleDependencies(parameterType, serviceProvider));
				}
				object obj = null;
				if (list != null && list.Count > 0)
				{
					return Activator.CreateInstance(type2, list.ToArray());
				}
				return Activator.CreateInstance(type2);
			}

			private ISugarRepository setContext(ISugarRepository sugarRepository, bool needNewCopy)
			{
				if (sugarRepository.Context != null)
				{
					if (needNewCopy)
					{
						sugarRepository.Context = sugarRepository.Context.CopyNew();
					}
				}
				else if (needNewCopy)
				{
					sugarRepository.Context = Context.CopyNew();
				}
				else
