					sugarRepository.Context = Context;
				}
				return sugarRepository;
			}

			private bool IsAssignableToBaseRepository(Type type)
			{
				Type[] interfaces = type.GetInterfaces();
				foreach (Type type2 in interfaces)
				{
					if (type2.IsGenericType && type2.GetGenericTypeDefinition() == typeof(ISimpleClient<>))
					{
						Type type3 = type2.GetGenericArguments()[0];
						if (typeof(ISimpleClient<>).MakeGenericType(type3).IsAssignableFrom(type))
						{
							return true;
						}
					}
				}
				return false;
			}

