		public class SplitTableContextResult<T>
		{
			public List<T> Items { get; set; }

			public SplitTableContext Helper { get; set; }

			public string GetTableName()
			{
				return GetTableNames().First();
			}

			public string[] GetTableNames()
			{
				List<string> list = new List<string>();
				SplitTableAttribute customAttribute = typeof(T).GetCustomAttribute<SplitTableAttribute>();
				Check.Exception(customAttribute == null, " " + typeof(T).Name + " need SplitTableAttribute");
				foreach (T item in Items)
				{
					list.Add(Helper.GetTableName(Helper.GetValue(customAttribute.SplitType, item)));
				}
				return list.Distinct().ToArray();
			}

			public string[] GetTableNames(SplitType splitType)
			{
				List<string> list = new List<string>();
				foreach (T item in Items)
				{
					list.Add(Helper.GetTableName(Helper.GetValue(splitType, item)));
				}
				return list.ToArray();
			}
		}
		public class SplitTableContext
		{
			internal SqlSugarProvider Context { get; set; }

			internal EntityInfo EntityInfo { get; set; }

			internal ISplitTableService Service { get; set; }

			private SplitTableContext()
			{
			}

			internal SplitTableContext(SqlSugarProvider context)
			{
				Context = context;
				if (Context.CurrentConnectionConfig.ConfigureExternalServices != null && Context.CurrentConnectionConfig.ConfigureExternalServices.SplitTableService != null)
				{
					Service = Context.CurrentConnectionConfig.ConfigureExternalServices.SplitTableService;
				}
				else
				{
					Service = new DateSplitTableService();
				}
			}

			public List<SplitTableInfo> GetTables()
			{
				if (StaticConfig.SplitTableGetTablesFunc != null)
				{
					return GetCustomGetTables();
				}
				bool isEnableLogEvent = Context.Ado.IsEnableLogEvent;
				Context.Ado.IsEnableLogEvent = false;
				List<DbTableInfo> list = ((DbMaintenanceProvider)Context.DbMaintenance).GetSchemaTables(EntityInfo);
				if (list == null)
				{
					list = Context.DbMaintenance.GetTableInfoList(isCache: false);
				}
				List<SplitTableInfo> allTables = Service.GetAllTables(Context, EntityInfo, list);
				Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				return allTables;
			}

			private List<SplitTableInfo> GetCustomGetTables()
			{
				bool isEnableLogEvent = Context.Ado.IsEnableLogEvent;
				Context.Ado.IsEnableLogEvent = false;
				List<SplitTableInfo> source = StaticConfig.SplitTableGetTablesFunc();
				List<SplitTableInfo> allTables = Service.GetAllTables(Context, EntityInfo, source.Select((SplitTableInfo it) => new DbTableInfo
				{
					Name = it.TableName
				}).ToList());
				Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				return allTables.ToList();
			}

			public string GetDefaultTableName()
			{
				return Service.GetTableName(Context, EntityInfo);
			}

			public string GetTableName(SplitType splitType)
			{
				return Service.GetTableName(Context, EntityInfo, splitType);
			}

			public string GetTableName(SplitType splitType, object fieldValue)
			{
				return Service.GetTableName(Context, EntityInfo, splitType, fieldValue);
			}

			public string GetTableName(object fieldValue)
			{
				SplitTableAttribute customAttribute = EntityInfo.Type.GetCustomAttribute<SplitTableAttribute>();
				Check.Exception(customAttribute == null, " " + EntityInfo.EntityName + " need SplitTableAttribute");
				return Service.GetTableName(Context, EntityInfo, customAttribute.SplitType, fieldValue);
			}

			public object GetValue(SplitType splitType, object entityValue)
			{
				return Service.GetFieldValue(Context, EntityInfo, splitType, entityValue);
			}

			internal void CheckPrimaryKey()
			{
				Check.Exception(EntityInfo.Columns.Any((EntityColumnInfo it) => it.IsIdentity), ErrorMessage.GetThrowMessage("Split table can't IsIdentity=true", "分表禁止使用自增列"));
			}
		}
