			public SqlSugarClient(List<ConnectionConfig> configs)
			{
				Check.Exception(configs.IsNullOrEmpty(), "List<ConnectionConfig> configs is null or count=0");
				InitConfigs(configs);
				ConnectionConfig config = configs.First();
				InitContext(config);
				_AllClients = configs.Select((ConnectionConfig it) => new SugarTenant
				{
					ConnectionConfig = it
				}).ToList();
				_AllClients.First((SugarTenant it) => it.ConnectionConfig.ConfigId == config.ConfigId).Context = Context;
			}

