				InitConfigs(configs);
				ConnectionConfig config = configs.First();
				InitContext(config);
				_AllClients = configs.Select((ConnectionConfig it) => new SugarTenant
				{
					ConnectionConfig = it
				}).ToList();
				_AllClients.First((SugarTenant it) => it.ConnectionConfig.ConfigId == config.ConfigId).Context = Context;
				configAction(this);
			}

			public T CreateContext<T>(bool isTran = true) where T : SugarUnitOfWork, new()
			{
				T val = new T();
				_CreateContext(isTran, val);
				Type typeFromHandle = typeof(T);
				PropertyInfo[] ps = typeFromHandle.GetProperties();
				string cacheKey = "SugarUnitOfWork" + typeof(T).FullName + typeof(T).GetHashCode();
				foreach (PropertyInfo item in new ReflectionInoCacheService().GetOrCreate(cacheKey, () => ps.Where((PropertyInfo it) => (it.PropertyType.BaseType != null && it.PropertyType.BaseType.Name.StartsWith("SimpleClient`")) || it.PropertyType.Name.StartsWith("SimpleClient`"))))
				{
					object obj = Activator.CreateInstance(item.PropertyType);
					TenantAttribute customAttribute = item.PropertyType.GetGenericArguments()[0].GetCustomAttribute<TenantAttribute>();
					if (customAttribute == null)
					{
						obj.GetType().GetProperty("Context").SetValue(obj, this);
					}
					else
					{
						obj.GetType().GetProperty("Context").SetValue(obj, GetConnection(customAttribute.configId));
					}
					item.SetValue(val, obj);
				}
				return val;
			}

			public SugarUnitOfWork CreateContext(bool isTran = true)
			{
				SugarUnitOfWork sugarUnitOf = new SugarUnitOfWork();
				return _CreateContext(isTran, sugarUnitOf);
			}

			private SugarUnitOfWork _CreateContext(bool isTran, SugarUnitOfWork sugarUnitOf)
			{
				sugarUnitOf.Db = this;
				sugarUnitOf.Tenant = this;
				sugarUnitOf.IsTran = isTran;
				Open();
				if (isTran)
				{
					BeginTran();
				}
				return sugarUnitOf;
			}

			public SimpleClient<T> GetSimpleClient<T>() where T : class, new()
			{
				return Context.GetSimpleClient<T>();
			}

			public RepositoryType GetRepository<RepositoryType>() where RepositoryType : ISugarRepository, new()
			{
				Type typeFromHandle = typeof(RepositoryType);
				bool num = typeFromHandle.GetConstructors().Any((ConstructorInfo z) => z.GetParameters().Any());
				object obj = null;
				if (num)
				{
					object[] args = new string[1];
					obj = Activator.CreateInstance(typeFromHandle, args);
				}
				else
				{
					obj = Activator.CreateInstance(typeFromHandle);
				}
				RepositoryType result = (RepositoryType)obj;
				if (result.Context == null)
				{
					result.Context = Context;
				}
				return result;
			}

