			public ISugarQueryable<T> Queryable<T>()
			{
				return Context.Queryable<T>();
			}

			public ISugarQueryable<T> Queryable<T>(ISugarQueryable<T> queryable)
			{
				ISugarQueryable<T> sugarQueryable = Context.Queryable(queryable);
				QueryBuilder queryBuilder = queryable.QueryBuilder;
				sugarQueryable.QueryBuilder.IsQueryInQuery = true;
				int num = ((sugarQueryable.QueryBuilder.Parameters == null) ? 1 : (sugarQueryable.QueryBuilder.Parameters.Count + 1));
				sugarQueryable.QueryBuilder.WhereIndex = queryBuilder.WhereIndex + 1;
				sugarQueryable.QueryBuilder.LambdaExpressions.ParameterIndex = queryBuilder.LambdaExpressions.ParameterIndex + num;
				return sugarQueryable;
			}

