			public void RemoveConnection(dynamic configId)
			{
				SugarTenant sugarTenant = _AllClients.FirstOrDefault((SugarTenant it) => it.ConnectionConfig.ConfigId.ObjToString() == ((object)configId).ObjToString());
				object configId2 = CurrentConnectionConfig.ConfigId;
				if (sugarTenant != null)
				{
					if (sugarTenant.Context.Ado.IsAnyTran())
					{
						Check.ExceptionEasy("RemoveConnection error  has tran", $"删除失败{sugarTenant.ConnectionConfig.ConfigId}存在未提交事务");
					}
					else if (sugarTenant.ConnectionConfig.ConfigId.ObjToString() == configId2.ObjToString())
					{
						Check.ExceptionEasy("Default ConfigId cannot be deleted", $"默认库不能删除{sugarTenant.ConnectionConfig.ConfigId}");
					}
					_AllClients.Remove(sugarTenant);
				}
			}

			public void AddConnection(ConnectionConfig connection)
			{
				Check.ArgumentNullException(connection, "AddConnection.connection can't be null");
				InitTenant();
				if (_AllClients.FirstOrDefault((SugarTenant it) => it.ConnectionConfig.ConfigId.ObjToString() == connection.ConfigId.ObjToString()) == null)
				{
					if (_AllClients == null)
					{
						_AllClients = new List<SugarTenant>();
					}
					SqlSugarProvider sqlSugarProvider = new SqlSugarProvider(connection);
					if (connection.AopEvents != null)
					{
						sqlSugarProvider.Ado.IsEnableLogEvent = true;
					}
					_AllClients.Add(new SugarTenant
					{
						ConnectionConfig = connection,
						Context = sqlSugarProvider
					});
				}
			}

