			public SqlSugarProvider GetConnection(object configId)
			{
				InitTenant();
				SugarTenant sugarTenant = _AllClients.FirstOrDefault((SugarTenant it) => Convert.ToString(it.ConnectionConfig.ConfigId) == Convert.ToString(configId));
				if (sugarTenant == null)
				{
					Check.Exception(true, "ConfigId was not found {0}", configId?.ToString() ?? "");
				}
				if (sugarTenant.Context == null)
				{
					sugarTenant.Context = new SqlSugarProvider(sugarTenant.ConnectionConfig);
				}
				_ = sugarTenant.Context.Aop;
				if (sugarTenant.Context.CurrentConnectionConfig.AopEvents == null)
				{
					sugarTenant.Context.CurrentConnectionConfig.AopEvents = new AopEvents();
				}
				if (_IsAllTran && sugarTenant.Context.Ado.Transaction == null)
				{
					sugarTenant.Context.Ado.BeginTran();
				}
				sugarTenant.Context.Root = this;
				if (sugarTenant.Context.MappingTables == null)
				{
					sugarTenant.Context.MappingTables = new MappingTableList();
				}
				return sugarTenant.Context;
			}

