			public void ChangeDatabase(object configId)
			{
				configId = Convert.ToString(configId);
				bool isEnableLogEvent = _Context.Ado.IsEnableLogEvent;
				Check.Exception(!_AllClients.Any((SugarTenant it) => Convert.ToString(it.ConnectionConfig.ConfigId) == Convert.ToString(configId)), "ConfigId was not found {0}", configId?.ToString() ?? "");
				InitTenant(_AllClients.First((SugarTenant it) => Convert.ToString(it.ConnectionConfig.ConfigId) == Convert.ToString(configId)));
				if (_IsAllTran)
				{
					Ado.BeginTran();
				}
				if (_IsOpen)
				{
					Open();
				}
				_Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				if (_CurrentConnectionConfig.AopEvents == null)
				{
					_CurrentConnectionConfig.AopEvents = new AopEvents();
				}
			}

			public void ChangeDatabase(Func<ConnectionConfig, bool> changeExpression)
			{
				bool isEnableLogEvent = _Context.Ado.IsEnableLogEvent;
				IEnumerable<ConnectionConfig> allConfigs = _AllClients.Select((SugarTenant it) => it.ConnectionConfig);
				Check.Exception(!allConfigs.Any(changeExpression), "changeExpression was not found {0}", changeExpression.ToString());
				InitTenant(_AllClients.First((SugarTenant it) => it.ConnectionConfig == allConfigs.First(changeExpression)));
				if (_IsAllTran)
				{
					Ado.BeginTran();
				}
				if (_IsOpen)
				{
					Open();
				}
				_Context.Ado.IsEnableLogEvent = isEnableLogEvent;
				if (_CurrentConnectionConfig.AopEvents == null)
				{
					_CurrentConnectionConfig.AopEvents = new AopEvents();
				}
			}

