			public void CommitTran()
			{
				Context.Ado.CommitTran();
				AllClientEach(delegate(ISqlSugarClient it)
				{
					try
					{
						it.Ado.CommitTran();
					}
					catch
					{
						SugarRetry.Execute(delegate
						{
							it.Ado.CommitTran();
						}, new TimeSpan(0, 0, 5));
					}
				});
				_IsAllTran = false;
			}

