			public SqlSugarClient CopyNew()
			{
				if (_AllClients != null && _AllClients.Count > 1 && _configAction != null)
				{
					List<ConnectionConfig> list = new List<ConnectionConfig>();
					foreach (SugarTenant allClient in _AllClients)
					{
						list.Add(UtilMethods.CopyConfig(allClient.ConnectionConfig));
					}
					SqlSugarClient sqlSugarClient = new SqlSugarClient(list, _configAction);
					sqlSugarClient.QueryFilter = QueryFilter;
					sqlSugarClient.Ado.CommandTimeOut = Ado.CommandTimeOut;
					return sqlSugarClient;
				}
				SqlSugarClient sqlSugarClient2 = ((_configAction == null) ? new SqlSugarClient(UtilMethods.CopyConfig(Ado.Context.CurrentConnectionConfig)) : new SqlSugarClient(UtilMethods.CopyConfig(Ado.Context.CurrentConnectionConfig), _configAction));
				sqlSugarClient2.QueryFilter = QueryFilter;
				if (_AllClients != null)
				{
					foreach (SugarTenant allClient2 in _AllClients)
					{
						if (!sqlSugarClient2.IsAnyConnection(allClient2.ConnectionConfig.ConfigId))
						{
							sqlSugarClient2.AddConnection(UtilMethods.CopyConfig(allClient2.ConnectionConfig));
						}
					}
				}
				return sqlSugarClient2;
			}

