			private SqlSugarProvider GetContext()
			{
				SqlSugarProvider sqlSugarProvider = null;
				sqlSugarProvider = Synchronization();
				if (sqlSugarProvider.Root == null)
				{
					sqlSugarProvider.Root = this;
				}
				return sqlSugarProvider;
			}

			private SqlSugarProvider NoSameThreadAsync()
			{
				return GetCallContext();
			}

			private SqlSugarProvider NoSameThread()
			{
				if (CallContext.ContextList.Value == null)
				{
					SqlSugarProvider sqlSugarProvider = CopyClient();
					AddCallContext(sqlSugarProvider);
					return sqlSugarProvider;
				}
				SqlSugarProvider callContext = GetCallContext();
				if (callContext == null)
				{
					SqlSugarProvider sqlSugarProvider2 = CopyClient();
					AddCallContext(sqlSugarProvider2);
					return sqlSugarProvider2;
				}
				return callContext;
			}

			private void InitTenant()
			{
				if (_AllClients == null)
				{
					_AllClients = new List<SugarTenant>();
					_AllClients.Add(new SugarTenant
					{
						ConnectionConfig = CurrentConnectionConfig,
						Context = Context
					});
				}
			}

			private SqlSugarProvider Synchronization()
			{
				_Context.MappingColumns = _MappingColumns;
				_Context.MappingTables = _MappingTables;
				_Context.IgnoreColumns = _IgnoreColumns;
				_Context.IgnoreInsertColumns = _IgnoreInsertColumns;
				return _Context;
			}

			private SqlSugarProvider NoSameThreadAndShard()
			{
				if (CallContext.ContextList.Value.IsNullOrEmpty())
				{
					SqlSugarProvider sqlSugarProvider = CopyClient();
					AddCallContext(sqlSugarProvider);
					return sqlSugarProvider;
				}
				SqlSugarProvider callContext = GetCallContext();
				if (callContext == null)
				{
					SqlSugarProvider sqlSugarProvider2 = CopyClient();
					AddCallContext(sqlSugarProvider2);
					return sqlSugarProvider2;
				}
				return callContext;
			}

			private SqlSugarProvider SameThreadAndShard()
			{
				if (CallContext.ContextList.Value.IsNullOrEmpty())
				{
					AddCallContext(_Context);
					return _Context;
				}
				SqlSugarProvider callContext = GetCallContext();
				if (callContext == null)
				{
					SqlSugarProvider sqlSugarProvider = CopyClient();
					AddCallContext(sqlSugarProvider);
					return sqlSugarProvider;
				}
				return callContext;
			}

			private bool IsAsync()
			{
				return AsyncId.HasValue;
			}

			private bool IsSingleInstanceAsync()
			{
				if (IsSingleInstance == true)
				{
					return AsyncId.HasValue;
				}
				return false;
			}

			private bool IsSynchronization()
			{
				return _ThreadId == Thread.CurrentThread.ManagedThreadId.ToString();
			}

			private SqlSugarProvider CopyClient()
			{
				return new SqlSugarProvider(CurrentConnectionConfig)
				{
					MappingColumns = _MappingColumns,
					MappingTables = _MappingTables,
					IgnoreColumns = _IgnoreColumns,
					IgnoreInsertColumns = _IgnoreInsertColumns
				};
			}

			private void AddCallContext(SqlSugarProvider context)
