				_Context = new SqlSugarProvider(config);
				if (!num)
				{
					_Context.Ado.IsEnableLogEvent = true;
				}
				CurrentConnectionConfig = config;
				_ThreadId = Thread.CurrentThread.ManagedThreadId.ToString();
				if (MappingTables == null)
