		{
			RepositoryType GetMyRepository<RepositoryType>() where RepositoryType : new();

			bool Commit();
		}
		/// <summary>
		/// ISugarUnitOfWorkClear  not exists Snet.DB.sugar method
		/// ISugarUnitOfWork exists Snet.DB.sugar method
		/// </summary>
		public interface ISugarUnitOfWork : ISugarUnitOfWorkClear
		{
			ISqlSugarClient Db { get; }

			ITenant Tenant { get; }

			SimpleClient<T> GetRepository<T>() where T : class, new();
		}
		/// <summary>
		/// SugarUnitOfWork-&gt;ISugarUnitOfWork-&gt;ISaugarUnitOfWorkClear
		/// ISaugarUnitOfWorkClear  not exists Snet.DB.sugar method
		/// ISugarUnitOfWork exists Snet.DB.sugar method
		/// </summary>
		public class SugarUnitOfWork : IDisposable, ISugarUnitOfWork, ISugarUnitOfWorkClear
		{
			private const string TranSuccessEvent = "_sqlSugar_tranSuccessEvent";

			public ISqlSugarClient Db { get; internal set; }

			public ITenant Tenant { get; internal set; }

			public bool IsTran { get; internal set; }

			public bool IsCommit { get; internal set; }

			public bool IsClose { get; internal set; }

			public void Dispose()
			{
				if (IsTran && !IsCommit)
				{
					Tenant.RollbackTran();
				}
				if (Db.Ado.Transaction == null && !IsClose)
				{
					Db.Close();
				}
			}

			public SimpleClient<T> GetRepository<T>() where T : class, new()
			{
				TenantAttribute customAttribute = typeof(T).GetCustomAttribute<TenantAttribute>();
				if (customAttribute == null)
				{
					return new SimpleClient<T>(Db);
				}
				return new SimpleClient<T>(Db.AsTenant().GetConnection(customAttribute.configId));
			}

			public RepositoryType GetMyRepository<RepositoryType>() where RepositoryType : new()
			{
				ISugarRepository sugarRepository = (ISugarRepository)(object)new RepositoryType();
				TenantAttribute tenantAttribute = typeof(RepositoryType).GetGenericArguments().FirstOrDefault()?.GetCustomAttribute<TenantAttribute>();
				if (tenantAttribute == null)
				{
					sugarRepository.Context = Db;
				}
				else
				{
					sugarRepository.Context = Db.AsTenant().GetConnection(tenantAttribute.configId);
				}
				return (RepositoryType)sugarRepository;
			}

			public bool Commit()
			{
				if (IsTran && !IsCommit)
				{
					Tenant.CommitTran();
					IsCommit = true;
					if (Db.TempItems != null && Db.TempItems.TryGetValue("_sqlSugar_tranSuccessEvent", out object value) && value != null && value is Action<ISqlSugarClient> action)
					{
						action(Db);
					}
				}
				if (Db.Ado.Transaction == null && !IsClose)
				{
					Db.Close();
					IsClose = true;
				}
				return IsCommit;
			}

			/// <summary>
			/// 增加事务成功后事件
			/// </summary>
			/// <param name="action">需要执行的委托</param>
			public void AppendTranSuccessEvent(Action<ISqlSugarClient> action)
			{
				if (Db.TempItems != null && Db.TempItems.TryGetValue("_sqlSugar_tranSuccessEvent", out object value) && value != null && value is Action<ISqlSugarClient> a)
				{
					Action<ISqlSugarClient> value2 = (Action<ISqlSugarClient>)Delegate.Combine(a, action);
					Db.TempItems["_sqlSugar_tranSuccessEvent"] = value2;
				}
				else if (Db.TempItems != null)
				{
					Db.TempItems["_sqlSugar_tranSuccessEvent"] = action;
				}
			}

			/// <summary>
			/// 减少事务成功后事件
			/// </summary>
			/// <param name="action"></param>
			public void SubtractTranSuccessEvent(Action<ISqlSugarClient> action)
			{
				if (Db.TempItems != null && Db.TempItems.TryGetValue("_sqlSugar_tranSuccessEvent", out object value) && value != null && value is Action<ISqlSugarClient> source)
				{
					Action<ISqlSugarClient> action2 = (Action<ISqlSugarClient>)Delegate.Remove(source, action);
					Db.TempItems["_sqlSugar_tranSuccessEvent"] = action2;
					if (action2 == null)
					{
						Db.TempItems.Remove("_sqlSugar_tranSuccessEvent");
					}
				}
			}
		}
