		public class CallContextAsync<T>
		{
			private static ConcurrentDictionary<string, AsyncLocal<T>> state = new ConcurrentDictionary<string, AsyncLocal<T>>();

			public static void SetData(string name, T data)
			{
				state.GetOrAdd(name, (string _) => new AsyncLocal<T>()).Value = data;
			}

			public static T GetData(string name)
			{
				if (!state.TryGetValue(name, out AsyncLocal<T> value))
				{
					return default(T);
				}
				return value.Value;
			}
		}
