		internal static class DataTableExtensions
		{
			public static DataTable ToPivotTable<T, TColumn, TRow, TData>(this IEnumerable<T> source, Func<T, TColumn> columnSelector, Expression<Func<T, TRow>> rowSelector, Func<IEnumerable<T>, TData> dataSelector)
			{
				DataTable table = new DataTable();
				List<string> list = new List<string>();
				string memberName = string.Empty;
				if (rowSelector.Body is MemberExpression)
				{
					memberName = ((MemberExpression)rowSelector.Body).Member.Name;
					list.Add(memberName);
				}
				else
				{
					list.AddRange(from it in ((NewExpression)rowSelector.Body).Arguments
						select it as MemberExpression into it
						select it.Member.Name);
				}
				table.Columns.AddRange(list.Select((string x) => new DataColumn(x)).ToArray());
				IEnumerable<TColumn> columns = source.Select(columnSelector).Distinct();
				table.Columns.AddRange(columns.Select((TColumn x) => new DataColumn(x?.ToString())).ToArray());
				Action<DataRow, IGrouping<TRow, T>> action;
				if (string.IsNullOrEmpty(memberName))
				{
					action = delegate(DataRow row, IGrouping<TRow, T> rowGroup)
					{
						PropertyInfo[] properties = rowGroup.Key.GetType().GetProperties();
						foreach (PropertyInfo propertyInfo in properties)
						{
							row[propertyInfo.Name] = propertyInfo.GetValue(rowGroup.Key, null);
						}
					};
				}
				else
				{
					action = delegate(DataRow row, IGrouping<TRow, T> rowGroup)
					{
						row[memberName] = rowGroup.Key;
					};
				}
				source.GroupBy(rowSelector.Compile()).Select(delegate(IGrouping<TRow, T> rowGroup)
				{
					DataRow row = table.NewRow();
					action(row, rowGroup);
					(from x in columns.GroupJoin(rowGroup, (TColumn c) => c, (T r) => columnSelector(r), delegate(TColumn c, IEnumerable<T> columnGroup)
						{
							Dictionary<string, object> dictionary = new Dictionary<string, object>();
							if (c != null)
							{
								dictionary[c.ToString()] = dataSelector(columnGroup);
							}
							return dictionary;
						}).SelectMany((Dictionary<string, object> x) => x)
						select row[x.Key] = x.Value).ToArray();
					table.Rows.Add(row);
					return row;
				}).ToList();
				return table;
			}

			public static IEnumerable<dynamic> ToPivotList<T, TColumn, TRow, TData>(this IEnumerable<T> source, Func<T, TColumn> columnSelector, Expression<Func<T, TRow>> rowSelector, Func<IEnumerable<T>, TData> dataSelector)
			{
				string memberName = string.Empty;
				if (rowSelector.Body is MemberExpression)
				{
					memberName = ((MemberExpression)rowSelector.Body).Member.Name;
				}
				IEnumerable<TColumn> columns = source.Select(columnSelector).Distinct();
				Action<IDictionary<string, object>, IGrouping<TRow, T>> action;
				if (string.IsNullOrEmpty(memberName))
				{
					action = delegate(IDictionary<string, object> row, IGrouping<TRow, T> rowGroup)
					{
						PropertyInfo[] properties = rowGroup.Key.GetType().GetProperties();
						foreach (PropertyInfo propertyInfo in properties)
						{
							row[propertyInfo.Name] = propertyInfo.GetValue(rowGroup.Key, null);
						}
					};
				}
				else
				{
					action = delegate(IDictionary<string, object> row, IGrouping<TRow, T> rowGroup)
					{
						row[memberName] = rowGroup.Key;
					};
				}
				return source.GroupBy(rowSelector.Compile()).Select(delegate(IGrouping<TRow, T> rowGroup)
				{
					IDictionary<string, object> row = new ExpandoObject();
					action(row, rowGroup);
					(from x in columns.GroupJoin(rowGroup, (TColumn c) => c, (T r) => columnSelector(r), delegate(TColumn c, IEnumerable<T> columnGroup)
						{
							Dictionary<string, object> dictionary = new Dictionary<string, object>();
							if (c != null)
							{
								dictionary[c.ToString()] = dataSelector(columnGroup);
							}
							return dictionary;
						}).SelectMany((Dictionary<string, object> x) => x)
						select row[x.Key] = x.Value).ToList();
					return row;
				});
			}
		}
		public static class DbExtensions
		{
			public static string ToJoinSqlInVals<T>(this T[] array)
			{
				if (array == null || array.Length == 0)
				{
					return string.Empty.ToSqlValue();
				}
				return string.Join(",", from it in array
					where it != null
					select it.ToSqlValue());
			}

			public static string ToJoinSqlInValsByVarchar<T>(this T[] array)
			{
				if (array == null || array.Length == 0)
				{
					return string.Empty.ToSqlValue();
				}
				return string.Join(",", from it in array
					where it != null
					select "N" + it.ToSqlValue());
			}

			public static string ToJoinSqlInValsN<T>(this T[] array)
			{
				if (array == null || array.Length == 0)
				{
					return string.Empty.ToSqlValue();
				}
				return string.Join(",", from it in array
					where it != null
					select "N" + it.ToSqlValue());
			}

			public static string ToSqlValue(this object value)
			{
				if (value != null && Enumerable.Contains(UtilConstants.NumericalTypes, value.GetType()))
				{
					return value.ToString();
				}
				return (value?.ToString() ?? "").ToSqlValue();
			}

			public static string ToSqlValue(this string value)
			{
				return $"'{value.ToSqlFilter()}'";
			}

			/// <summary>
			///             Sql Filter
			/// </summary>
			/// <param name="value"></param>
			/// <returns></returns>
			public static string ToSqlFilter(this string value)
			{
				if (!value.IsNullOrEmpty())
				{
					int length = value.Length;
					value = value.Replace("'", "''");
					if (length != value.Length && value.IndexOf(")") > 0 && value.IndexOf("\\''") > 0)
					{
						value = value.Replace("\\", "\\\\");
					}
				}
				return value;
			}

			/// <summary>
			/// Check field format
			/// </summary>
			/// <param name="value"></param>
			/// <returns></returns>
			public static string ToCheckField(this string value)
			{
				if (StaticConfig.Check_FieldFunc != null)
				{
					return StaticConfig.Check_FieldFunc(value);
				}
				if (value != null)
				{
					if (value.IsContainsIn(";", "--"))
					{
						throw new Exception(value + " format error ");
					}
					if (value.IsContainsIn("//") && value.Length - value.Replace("/", "").Length >= 4)
					{
						throw new Exception(value + " format error ");
					}
					if (value.IsContainsIn("'") && (value.Length - value.Replace("'", "").Length) % 2 != 0)
					{
						throw new Exception(value + " format error ");
					}
					if (IsUpdateSql(value, "/", "/"))
					{
						Check.ExceptionEasy(value + " format error  ", value + "不能存在  /+【update drop 等】+/ ");
					}
					else if (IsUpdateSql(value, "/", " "))
					{
						Check.ExceptionEasy(value + " format error  ", value + "不能存在  /+【update drop 等】+空格 ");
					}
					else if (IsUpdateSql(value, " ", "/"))
					{
						Check.ExceptionEasy(value + " format error  ", value + "不能存在  空格+【update drop 等】+/ ");
					}
					else if (value.ToLower().Contains(" update ") || value.ToLower().Contains(" delete ") || value.ToLower().Contains(" drop ") || value.ToLower().Contains(" alert ") || value.ToLower().Contains(" create ") || value.ToLower().Contains(" insert "))
					{
						Check.ExceptionEasy(value + " format error  ", value + "不能存在  空格+【update drop 等】+空格 ");
					}
				}
				return value;
			}

			private static bool IsUpdateSql(string value, string left, string right)
			{
				if (!value.ToLower().Contains(left + "update" + right) && !value.ToLower().Contains(left + "delete" + right) && !value.ToLower().Contains(left + "drop" + right) && !value.ToLower().Contains(left + "alert" + right) && !value.ToLower().Contains(left + "create" + right))
				{
					return value.ToLower().Contains(left + "insert" + right);
				}
				return true;
			}

			public static bool ContainsChinese(string input)
			{
				string pattern = "[\\u4e00-\\u9fa5]";
				return Regex.IsMatch(input, pattern);
			}

			public static bool IsRegexWNoContainsChinese(this string value)
			{
				if (!ContainsChinese(value) && Regex.IsMatch(value, "^\\w+$"))
				{
					return true;
				}
				return false;
			}

			public static string ToCheckRegexW(this string value)
			{
				if (Regex.IsMatch(value, "^\\w+$"))
				{
					return value;
				}
				throw new Exception("ToCheckRegexW " + value + " format error ");
			}

			internal static string ToLower(this string value, bool isAutoToLower)
			{
				if (value == null)
				{
					return null;
				}
				if (!isAutoToLower)
				{
					return value;
				}
				return value.ToLower();
			}

			internal static string ToUpper(this string value, bool isAutoToUpper)
			{
				if (value == null)
				{
					return null;
				}
				if (!isAutoToUpper)
				{
					return value;
				}
				return value.ToUpper();
			}
		}
		public class ExpressionBuilderHelper
		{
			public static object CallFunc(Type type, object[] param, object methodData, string methodName)
			{
				return methodData.GetType().GetMethod(methodName).MakeGenericMethod(type)
					.Invoke(methodData, param);
			}

			public static T CallFunc<T>(object param, object methodData, string methodName)
			{
				Type type = param.GetType();
				return (T)methodData.GetType().GetMethod(methodName).MakeGenericMethod(type)
					.Invoke(methodData, new object[1] { param });
			}

			public static T CallStaticFunc<T>(object param, Type methodType, string methodName)
			{
				Type type = param.GetType();
				return (T)methodType.GetMethod(methodName).MakeGenericMethod(type).Invoke(null, new object[1] { param });
			}

			/// <summary>
			/// Create Expression
			/// </summary>
			public static Expression CreateExpression(Expression left, Expression value, ExpressionType type)
			{
				return type switch
				{
					ExpressionType.Equal => Expression.Equal(left, Expression.Convert(value, left.Type)), 
					ExpressionType.NotEqual => Expression.NotEqual(left, Expression.Convert(value, left.Type)), 
					_ => Expression.Equal(left, Expression.Convert(value, left.Type)), 
				};
			}

			public static Expression CreateExpressionLike<ColumnType>(Type entityType, string propertyName, List<ColumnType> list)
			{
				ParameterExpression parameterExpression = Expression.Parameter(entityType, "p");
				MemberExpression memberExpression = Expression.PropertyOrField(parameterExpression, propertyName);
				MethodInfo method = typeof(List<>).MakeGenericType(typeof(ColumnType)).GetMethod("Contains");
				return Expression.Lambda(Expression.Call(Expression.Constant(list), method, memberExpression), parameterExpression);
			}

			public static Expression<Func<T, object>> CreateNewFields<T>(EntityInfo entity, List<string> propertyNames)
			{
				Type typeFromHandle = typeof(T);
				Dictionary<string, PropertyInfo> sourceProperties = entity.Columns.Where((EntityColumnInfo it) => propertyNames.Contains(it.PropertyName)).ToDictionary((EntityColumnInfo it) => it.PropertyName, (EntityColumnInfo it) => it.PropertyInfo);
				if (StaticConfig.EnableAot)
				{
					Type? typeFromHandle2 = typeof(T);
					ParameterExpression sourceItem = Expression.Parameter(typeFromHandle, "t");
					return Expression.Lambda<Func<T, object>>(Expression.MemberInit(bindings: (from p in typeFromHandle2.GetProperties()
						where sourceProperties.Any<KeyValuePair<string, PropertyInfo>>((KeyValuePair<string, PropertyInfo> s) => s.Key == p.Name)
						select Expression.Bind(p, Expression.Property(sourceItem, sourceProperties[p.Name]))).OfType<MemberBinding>(), newExpression: Expression.New(typeFromHandle2.GetConstructor(Type.EmptyTypes))), new ParameterExpression[1] { sourceItem });
				}
				Type dynamicType = LinqRuntimeTypeBuilder.GetDynamicType(sourceProperties.Values);
				ParameterExpression sourceItem2 = Expression.Parameter(typeFromHandle, "t");
				return Expression.Lambda<Func<T, object>>(Expression.MemberInit(bindings: (from p in dynamicType.GetRuntimeProperties()
					select Expression.Bind(p, Expression.Property(sourceItem2, sourceProperties[p.Name]))).OfType<MemberBinding>(), newExpression: Expression.New(dynamicType.GetConstructor(Type.EmptyTypes))), new ParameterExpression[1] { sourceItem2 });
			}

			public static Expression CreateExpressionSelectField(Type classType, string propertyName, Type propertyType, string shortName = "it")
			{
				ParameterExpression parameterExpression = Expression.Parameter(classType, shortName);
				PropertyInfo property = classType.GetProperty(propertyName);
				MemberExpression body = Expression.Property(parameterExpression, property);
				return Expression.Lambda(typeof(Func<, >).MakeGenericType(classType, propertyType), body, parameterExpression);
			}

			public static Expression CreateExpressionSelectFieldObject(Type classType, string propertyName)
			{
				ParameterExpression parameterExpression = Expression.Parameter(classType, "it");
				PropertyInfo property = classType.GetProperty(propertyName);
				UnaryExpression body = Expression.Convert(Expression.Property(parameterExpression, property), typeof(object));
				return Expression.Lambda(typeof(Func<, >).MakeGenericType(classType, typeof(object)), body, parameterExpression);
			}
		}
		internal static class LinqRuntimeTypeBuilder
		{
			private static readonly AssemblyName AssemblyName;

			private static readonly ModuleBuilder ModuleBuilder;

			private static readonly Dictionary<string, Type> BuiltTypes;

			private const MethodAttributes RuntimeGetSetAttrs = MethodAttributes.Public | MethodAttributes.HideBySig | MethodAttributes.SpecialName;

			static LinqRuntimeTypeBuilder()
			{
				AssemblyName = new AssemblyName
				{
					Name = "LinqRuntimeTypes4iTheoChan"
				};
				BuiltTypes = new Dictionary<string, Type>();
				ModuleBuilder = AssemblyBuilder.DefineDynamicAssembly(AssemblyName, AssemblyBuilderAccess.Run).DefineDynamicModule(AssemblyName.Name);
			}

			private static string GetTypeKey(Dictionary<string, Type> properties)
			{
				string text = string.Empty;
				foreach (KeyValuePair<string, Type> property in properties)
				{
					text = text + property.Key + ";" + property.Value.Name + ";";
				}
				return text;
			}

			public static Type BuildDynamicType(Dictionary<string, Type> properties)
			{
				if (properties == null)
				{
					throw new ArgumentNullException("properties");
				}
				if (properties.Count == 0)
				{
					throw new ArgumentOutOfRangeException("properties", "fields must have at least 1 field definition");
				}
				try
				{
					Monitor.Enter(BuiltTypes);
					string typeKey = GetTypeKey(properties);
					if (BuiltTypes.ContainsKey(typeKey))
					{
						return BuiltTypes[typeKey];
					}
					TypeBuilder typeBuilder = ModuleBuilder.DefineType(typeKey, TypeAttributes.Public | TypeAttributes.Serializable);
					foreach (KeyValuePair<string, Type> property in properties)
					{
						PropertyBuilder propertyBuilder = typeBuilder.DefineProperty(property.Key, PropertyAttributes.None, property.Value, null);
						FieldBuilder field = typeBuilder.DefineField("itheofield_" + property.Key, property.Value, FieldAttributes.Private);
						MethodBuilder methodBuilder = typeBuilder.DefineMethod("get_" + property.Key, MethodAttributes.Public | MethodAttributes.HideBySig | MethodAttributes.SpecialName, property.Value, Type.EmptyTypes);
						ILGenerator iLGenerator = methodBuilder.GetILGenerator();
						iLGenerator.Emit(OpCodes.Ldarg_0);
						iLGenerator.Emit(OpCodes.Ldfld, field);
						iLGenerator.Emit(OpCodes.Ret);
						MethodBuilder methodBuilder2 = typeBuilder.DefineMethod("set_" + property.Key, MethodAttributes.Public | MethodAttributes.HideBySig | MethodAttributes.SpecialName, null, new Type[1] { property.Value });
						ILGenerator iLGenerator2 = methodBuilder2.GetILGenerator();
						iLGenerator2.Emit(OpCodes.Ldarg_0);
						iLGenerator2.Emit(OpCodes.Ldarg_1);
						iLGenerator2.Emit(OpCodes.Stfld, field);
						iLGenerator2.Emit(OpCodes.Ret);
						propertyBuilder.SetGetMethod(methodBuilder);
						propertyBuilder.SetSetMethod(methodBuilder2);
					}
					BuiltTypes[typeKey] = typeBuilder.CreateType();
					return BuiltTypes[typeKey];
				}
				catch
				{
					throw;
				}
				finally
				{
					Monitor.Exit(BuiltTypes);
				}
			}

			private static string GetTypeKey(IEnumerable<PropertyInfo> properties)
			{
				return GetTypeKey(properties.ToDictionary((PropertyInfo f) => f.Name, (PropertyInfo f) => f.PropertyType));
			}

			public static Type GetDynamicType(IEnumerable<PropertyInfo> properties)
			{
				return BuildDynamicType(properties.ToDictionary((PropertyInfo f) => f.Name, (PropertyInfo f) => f.PropertyType));
			}
		}
		internal static class FastCopy
		{
			private static ConcurrentDictionary<string, object> copiers = new ConcurrentDictionary<string, object>();

			/// <summary>
			/// 复制两个对象同名属性值
			/// </summary>
			/// <typeparam name="S"></typeparam>
			/// <typeparam name="T"></typeparam>
			/// <param name="source">源对象</param>
			/// <param name="target">目标对象</param>
			/// <param name="copyNull">源对象属性值为null时，是否将值复制给目标对象</param>
			public static void Copy<S, T>(S source, T target, bool copyNull = true)
			{
				string key = $"{typeof(S)}_{typeof(T)}_{copyNull}";
				if (!copiers.TryGetValue(key, out object value))
				{
					Action<S, T> action = CreateCopier<S, T>(copyNull);
					copiers.TryAdd(key, action);
					value = action;
				}
				((Action<S, T>)value)(source, target);
			}

			/// <summary>
			/// 为指定的两种类型编译生成属性复制委托
			/// </summary>
			/// <typeparam name="S"></typeparam>
			/// <typeparam name="T"></typeparam>
			/// <param name="copyNull">源对象属性值为null时，是否将值复制给目标对象</param>
			/// <returns></returns>
			private static Action<S, T> CreateCopier<S, T>(bool copyNull)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(S));
				ParameterExpression parameterExpression2 = Expression.Parameter(typeof(T));
				List<PropertyInfo> sourceProps = (from p in typeof(S).GetProperties(BindingFlags.Instance | BindingFlags.Public)
					where p.CanRead
					select p).ToList();
				IEnumerable<PropertyInfo> enumerable = from tProp in (from p in typeof(T).GetProperties(BindingFlags.Instance | BindingFlags.Public)
						where p.CanWrite
						select p).ToList()
					where sourceProps.Where((PropertyInfo sProp) => sProp.Name == tProp.Name && (sProp.PropertyType == tProp.PropertyType || sProp.PropertyType.IsAssignableFrom(tProp.PropertyType) || (tProp.PropertyType.IsValueType && sProp.PropertyType.IsValueType && ((tProp.PropertyType.GenericTypeArguments.Length != 0) ? tProp.PropertyType.GenericTypeArguments[0] : tProp.PropertyType) == sProp.PropertyType))).Count() > 0
					select tProp;
				List<Expression> list = new List<Expression>();
				foreach (PropertyInfo item4 in enumerable)
				{
					if (item4.PropertyType.IsValueType)
					{
						PropertyInfo property = typeof(S).GetProperty(item4.Name);
						PropertyInfo property2 = typeof(T).GetProperty(item4.Name);
						if (property.PropertyType == property2.PropertyType)
						{
							BinaryExpression item = Expression.Assign(Expression.Property(parameterExpression2, item4.Name), Expression.Property(parameterExpression, item4.Name));
							list.Add(item);
						}
						else if (property.PropertyType.GenericTypeArguments.Length == 0 && property2.PropertyType.GenericTypeArguments.Length != 0)
						{
							UnaryExpression right = Expression.Convert(Expression.Property(parameterExpression, item4.Name), property2.PropertyType);
							BinaryExpression item2 = Expression.Assign(Expression.Property(parameterExpression2, item4.Name), right);
							list.Add(item2);
						}
					}
					else
					{
						BinaryExpression binaryExpression = Expression.Assign(Expression.Property(parameterExpression2, item4.Name), Expression.Property(parameterExpression, item4.Name));
						BinaryExpression test = Expression.Equal(Expression.Constant(null, item4.PropertyType), Expression.Property(parameterExpression, item4.Name));
						ConditionalExpression ifTrue = Expression.IfThen(Expression.IsTrue(Expression.Constant(copyNull)), binaryExpression);
						ConditionalExpression item3 = Expression.IfThenElse(test, ifTrue, binaryExpression);
						list.Add(item3);
					}
				}
				return Expression.Lambda<Action<S, T>>(Expression.Block(list.ToArray()), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile();
			}

			internal static List<string> GetDiff<T>(T item, T trackingData) where T : class, new()
			{
				List<string> list = new List<string>();
				PropertyInfo[] properties = typeof(T).GetProperties();
				foreach (PropertyInfo propertyInfo in properties)
				{
					object value = propertyInfo.GetValue(item);
					object value2 = propertyInfo.GetValue(trackingData);
					if (value == null && value2 != null)
					{
						list.Add(propertyInfo.Name);
					}
					else if (value != null && !value.Equals(value2))
					{
						list.Add(propertyInfo.Name);
					}
				}
				return list;
			}
		}
		internal class FileHelper
		{
			public static void CreateFile(string filePath, string text, Encoding encoding)
			{
				try
				{
					if (IsExistFile(filePath))
					{
						DeleteFile(filePath);
					}
					if (IsExistFile(filePath))
					{
						return;
					}
					CreateDirectory(GetDirectoryFromFilePath(filePath));
					using FileStream stream = new FileInfo(filePath).Create();
					using StreamWriter streamWriter = new StreamWriter(stream, encoding);
					streamWriter.Write(text);
					streamWriter.Flush();
				}
				catch (Exception ex)
				{
					throw ex;
				}
			}

			public static bool IsExistDirectory(string directoryPath)
			{
				return Directory.Exists(directoryPath);
			}

			public static void CreateDirectory(string directoryPath)
			{
				if (!IsExistDirectory(directoryPath) && directoryPath != "")
				{
					Directory.CreateDirectory(directoryPath);
				}
			}

			public static void DeleteFile(string filePath)
			{
				if (IsExistFile(filePath))
				{
					File.Delete(filePath);
				}
			}

			public static string GetDirectoryFromFilePath(string filePath)
			{
				return new FileInfo(filePath).Directory.FullName;
			}

			public static bool IsExistFile(string filePath)
			{
				return File.Exists(filePath);
			}
		}
		public interface IPropertyCallAdapter<TThis>
		{
			object InvokeGet(TThis @this);
		}
		public class PropertyCallAdapter<TThis, TResult> : IPropertyCallAdapter<TThis>
		{
			private readonly Func<TThis, TResult> _getterInvocation;

			public PropertyCallAdapter(Func<TThis, TResult> getterInvocation)
			{
				_getterInvocation = getterInvocation;
			}

			public object InvokeGet(TThis @this)
			{
				return _getterInvocation(@this);
			}
		}
		public class PropertyCallAdapterProvider<TThis>
		{
			private static readonly ConcurrentDictionary<string, IPropertyCallAdapter<TThis>> _instances = new ConcurrentDictionary<string, IPropertyCallAdapter<TThis>>();

			public static IPropertyCallAdapter<TThis> GetInstance(string forPropertyName)
			{
				if (!_instances.TryGetValue(forPropertyName, out IPropertyCallAdapter<TThis> value))
				{
					PropertyInfo propertyInfo = null;
					IEnumerable<PropertyInfo> source = from it in typeof(TThis).GetProperties(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
						where it.Name == forPropertyName
						select it;
					propertyInfo = ((source.Count() != 1) ? source.First() : source.First());
					Delegate obj = null;
					MethodInfo getMethod;
					if (propertyInfo != null && (getMethod = propertyInfo.GetGetMethod(nonPublic: true)) != null)
					{
						obj = Delegate.CreateDelegate(typeof(Func<, >).MakeGenericType(typeof(TThis), propertyInfo.PropertyType), null, getMethod);
					}
					value = Activator.CreateInstance(typeof(PropertyCallAdapter<, >).MakeGenericType(typeof(TThis), propertyInfo.PropertyType), obj) as IPropertyCallAdapter<TThis>;
					_instances.GetOrAdd(forPropertyName, value);
				}
				return value;
			}
		}
