			public static object ConvertToArray(string input, Type targetType)
			{
				bool isArray = targetType.IsArray;
				bool flag = targetType.IsGenericType && targetType.GetGenericTypeDefinition() == typeof(List<>);
				if (!isArray && !flag)
				{
					throw new ArgumentException("目标类型必须是数组或List类型");
				}
				Type type = (isArray ? targetType.GetElementType() : targetType.GetGenericArguments()[0]);
				if (string.IsNullOrEmpty(input))
				{
					if (isArray)
					{
						return Array.CreateInstance(type, 0);
					}
					return Activator.CreateInstance(typeof(List<>).MakeGenericType(type));
				}
				string[] array = input.Trim('[', ']').Split(',');
				if (isArray)
				{
					Array array2 = Array.CreateInstance(type, array.Length);
					for (int i = 0; i < array.Length; i++)
					{
						string value = array[i]?.Trim()?.TrimStart('"')?.TrimEnd('"');
						array2.SetValue(ChangeType2(value, type), i);
					}
					return array2;
				}
				IList list = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(type));
				for (int j = 0; j < array.Length; j++)
				{
					string value2 = array[j]?.Trim()?.TrimStart('"')?.TrimEnd('"');
					list.Add(ChangeType2(value2, type));
				}
				return list;
			}

