			public static DataTable ConvertDateTimeOffsetToDateTime(DataTable table)
			{
				if (!table.Columns.Cast<DataColumn>().Any((DataColumn it) => it.DataType == typeof(DateTimeOffset)))
				{
					return table;
				}
				DataTable dataTable = table.Clone();
				dataTable.TableName = table.TableName;
				foreach (DataColumn column in dataTable.Columns)
				{
					if (column.DataType == typeof(DateTimeOffset))
					{
						column.DataType = typeof(DateTime);
					}
				}
				DataTable dataTable2 = new DataTable();
				dataTable2.TableName = table.TableName;
				foreach (DataColumn column2 in table.Columns)
				{
					Type type = ((column2.DataType == typeof(DateTimeOffset)) ? typeof(DateTime) : column2.DataType);
					dataTable2.Columns.Add(column2.ColumnName, type);
				}
				foreach (DataRow row in table.Rows)
				{
					DataRow dataRow2 = dataTable2.NewRow();
					foreach (DataColumn column3 in table.Columns)
					{
						object obj = row[column3];
						if (obj is DateTimeOffset dateTimeOffset)
						{
							dataRow2[column3.ColumnName] = dateTimeOffset.DateTime;
						}
						else
						{
							dataRow2[column3.ColumnName] = obj;
						}
					}
					dataTable2.Rows.Add(dataRow2);
				}
				return dataTable2;
			}

			public static string EscapeLikeValue(ISqlSugarClient db, string value, params char[] wildcards)
			{
				if (wildcards != null)
				{
					foreach (char wildcard in wildcards)
					{
						value = EscapeLikeValue(db, value, wildcard);
					}
				}
				return value;
			}

			public static string EscapeLikeValue(ISqlSugarClient db, string value, char wildcard = '%')
			{
				DbType dbType = db.CurrentConnectionConfig.DbType;
				ConnectionConfig currentConnectionConfig = db.CurrentConnectionConfig;
				if (currentConnectionConfig != null)
				{
					ConnMoreSettings moreSettings = currentConnectionConfig.MoreSettings;
					if (moreSettings != null && moreSettings.DatabaseModel.HasValue)
					{
						dbType = db.CurrentConnectionConfig.MoreSettings.DatabaseModel.Value;
					}
				}
				if (string.IsNullOrEmpty(value))
				{
					return value;
				}
				string oldValue = wildcard.ToString();
				switch (dbType)
				{
				case DbType.SqlServer:
					if (wildcard == ']' || wildcard == '[')
					{
						string text = "[[]";
						string text2 = "[]]";
						string text3 = Guid.NewGuid().ToString();
						string text4 = Guid.NewGuid().ToString();
						value = value.Replace(text, text3).Replace(text2, text4);
						value = value.Replace(wildcard.ToString() ?? "", $"[{wildcard}]");
						value = value.Replace(text3, text).Replace(text4, text2);
					}
					else
					{
						string newValue = "[[]";
						string newValue2 = "[]]";
						string text5 = Guid.NewGuid().ToString();
						string text6 = Guid.NewGuid().ToString();
						value = value.Replace("[", text5).Replace("]", text6);
						value = value.Replace(text5, newValue).Replace(text6, newValue2);
						value = value.Replace(oldValue, $"[{wildcard}]");
					}
					break;
				default:
					value = value.Replace(oldValue, "\\" + wildcard);
					break;
				}
				return value;
			}

