			internal static string GetTableByDbLink(SqlSugarProvider context, string tableName, string oldTableName, TenantAttribute attr)
			{
				QueryBuilder queryBuilderWithContext = InstanceFactory.GetQueryBuilderWithContext(context);
				string dbLinkName = context.Root.GetConnection(attr.configId).CurrentConnectionConfig.DbLinkName;
				if (dbLinkName != null)
				{
					tableName = ((dbLinkName.First() == '@') ? (queryBuilderWithContext.Builder.GetTranslationColumnName(oldTableName) + dbLinkName) : ((dbLinkName.Last() != '_') ? (dbLinkName + "." + queryBuilderWithContext.Builder.GetTranslationColumnName(oldTableName)) : (dbLinkName + oldTableName)));
				}
				return tableName;
			}

			public static List<Tuple<string, Type>> GetColumnInfo(IDataReader reader)
			{
				List<Tuple<string, Type>> list = new List<Tuple<string, Type>>();
				int fieldCount = reader.FieldCount;
				for (int i = 0; i < fieldCount; i++)
				{
					string name = reader.GetName(i);
					Type fieldType = reader.GetFieldType(i);
					list.Add(Tuple.Create(name, fieldType));
				}
				return list;
			}

			public static object ConvertToObjectList(Type targetType, List<object> sourceList)
			{
				object obj = Activator.CreateInstance(typeof(List<>).MakeGenericType(targetType));
				MethodInfo method = obj.GetType().GetMethod("Add");
				foreach (object source in sourceList)
				{
					method.Invoke(obj, new object[1] { source });
				}
				return obj;
			}

			public static Dictionary<string, object> DataRowToDictionary(DataRow row)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				foreach (DataColumn column in row.Table.Columns)
				{
					if (column.ColumnName != "Items" && !column.DataType.Name.IsCollectionsList())
					{
						dictionary.Add(column.ColumnName, row[column]);
					}
				}
				return dictionary;
			}

			public static IEnumerable<T> BuildTree<T>(ISqlSugarClient db, IEnumerable<T> list, string idName, string pIdName, string childName, object rootValue)
			{
				EntityInfo entityInfo = db.EntityMaintenance.GetEntityInfo<T>();
				PropertyInfo property = entityInfo.Type.GetProperty(idName);
				PropertyInfo property2 = entityInfo.Type.GetProperty(pIdName);
				PropertyInfo property3 = entityInfo.Type.GetProperty(childName);
				BuildTreeGroup(list, property, property2, out Dictionary<string, T> kvList, out IEnumerable<IGrouping<string, T>> group);
				IGrouping<string, T> grouping = ((rootValue != null) ? group.FirstOrDefault((IGrouping<string, T> x) => x.Key == rootValue.ObjToString()) : group.FirstOrDefault((IGrouping<string, T> x) => x.Key == null || x.Key == "" || x.Key == "0" || x.Key == Guid.Empty.ToString()));
				if (grouping != null)
				{
					foreach (IGrouping<string, T> item in group)
					{
						if (kvList.TryGetValue(item.Key, out var value))
						{
							property3.SetValue(value, item.ToList());
						}
					}
				}
				return grouping;
			}

			private static void BuildTreeGroup<T>(IEnumerable<T> list, PropertyInfo mainIdProp, PropertyInfo pIdProp, out Dictionary<string, T> kvList, out IEnumerable<IGrouping<string, T>> group)
			{
				kvList = list.ToDictionary((T x) => mainIdProp.GetValue(x).ObjToString());
				group = from x in list
					group x by pIdProp.GetValue(x).ObjToString();
			}

