			/// <returns></returns>
			internal static object GetFormatValue(object addValue, QueryableFormat valueFomatInfo)
			{
				if (valueFomatInfo.MethodName == "ToString")
				{
					if (valueFomatInfo.Type == UtilConstants.GuidType)
					{
						addValue = Guid.Parse(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.ByteType)
					{
						addValue = Convert.ToByte(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.IntType)
					{
						addValue = Convert.ToInt32(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.LongType)
					{
						addValue = Convert.ToInt64(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.UIntType)
					{
						addValue = Convert.ToUInt32(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.ULongType)
					{
						addValue = Convert.ToUInt64(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.DecType)
					{
						addValue = Convert.ToDecimal(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.Type == UtilConstants.DobType)
					{
						addValue = Convert.ToDouble(addValue?.ToString() ?? "").ToString(valueFomatInfo.Format);
					}
					else if (valueFomatInfo.TypeString == "Enum")
					{
						addValue = ChangeType2(addValue, valueFomatInfo.Type)?.ToString();
					}
				}
				else if (valueFomatInfo.MethodName == "OnlyInSelectConvertToString")
				{
					MethodInfo methodInfo = valueFomatInfo.MethodInfo;
					if (methodInfo != null)
					{
						object obj = (methodInfo.IsStatic ? null : Activator.CreateInstance(methodInfo.ReflectedType));
						object[] parameters = new object[1] { addValue };
						addValue = methodInfo.Invoke(obj, parameters);
					}
				}
				return addValue;
			}

