			internal static void EndCustomSplitTable(ISqlSugarClient context, Type entityType)
			{
				if (context != null && !(entityType == null))
				{
					SplitTableAttribute customAttribute = entityType.GetCustomAttribute<SplitTableAttribute>();
					if (customAttribute != null && customAttribute.CustomSplitTableService != null)
					{
						context.CurrentConnectionConfig.ConfigureExternalServices.SplitTableService = null;
					}
				}
			}

			internal static void StartCustomSplitTable(ISqlSugarClient context, Type entityType)
			{
				if (context == null || entityType == null)
				{
					return;
				}
				SplitTableAttribute customAttribute = entityType.GetCustomAttribute<SplitTableAttribute>();
				if (customAttribute == null)
				{
					return;
				}
				if (customAttribute.CustomSplitTableService != null)
				{
					context.CurrentConnectionConfig.ConfigureExternalServices.SplitTableService = (ISplitTableService)Activator.CreateInstance(customAttribute.CustomSplitTableService);
				}
				if (context?.CurrentConnectionConfig?.ConfigureExternalServices?.SplitTableService == null || !(customAttribute.CustomSplitTableService == null))
				{
					return;
				}
				string dbTableName = context.EntityMaintenance.GetEntityInfo(entityType).DbTableName;
				if (dbTableName == null || !dbTableName.EndsWith("_{year}{month}{day}"))
				{
					return;
				}
				string dbTableName2 = context.EntityMaintenance.GetEntityInfo(entityType).DbTableName;
				if (dbTableName2 != null)
				{
					string text = dbTableName2.Replace("_{year}{month}{day}", "");
					if (((text != null) ? new bool?(!text.Contains("{")) : ((bool?)null)) == true)
					{
						context.CurrentConnectionConfig.ConfigureExternalServices.SplitTableService = null;
					}
				}
			}

			public static void ConvertParameter(SugarParameter p, ISqlBuilder builder)
			{
				if (!p.ParameterName.StartsWith(builder.SqlParameterKeyWord))
				{
					p.ParameterName = builder.SqlParameterKeyWord + p.ParameterName.TrimStart('@');
				}
			}

			public static object SetAnonymousObjectPropertyValue(object obj, string propertyName, object propertyValue)
			{
				if (obj.GetType().IsAnonymousType())
				{
					FieldInfo[] fields = obj.GetType().GetFields(BindingFlags.Instance | BindingFlags.NonPublic);
					foreach (FieldInfo fieldInfo in fields)
					{
						if (fieldInfo.Name == "<" + propertyName + ">i__Field")
						{
							fieldInfo.SetValue(obj, propertyValue);
							break;
						}
					}
				}
				else
				{
					obj.GetType().GetProperty(propertyName).SetValue(obj, propertyValue);
				}
				return obj;
			}

