			public static string GetNativeSql(string sql, SugarParameter[] pars)
			{
				if (pars == null || pars.Length == 0)
				{
					return "\r\n[Sql]:" + sql + "\r\n";
				}
				return $"\r\n[Sql]:{sql} \r\n[Pars]:{string.Join(" ", pars.Select((SugarParameter it) => $"\r\n[Name]:{it.ParameterName} [Value]:{it.Value} [Type]:{it.DbType} {(it.IsNvarchar2 ? "nvarchar2" : "")}  "))} \r\n";
			}

			public static string ToUnderLine(string str, bool isToUpper = false)
			{
				if (str == null || str.Contains("_"))
				{
					return str;
				}
				if (isToUpper)
				{
					return string.Concat(str.Select((char x, int i) => (i <= 0 || !char.IsUpper(x)) ? x.ToString() : ("_" + x))).ToUpper();
				}
				return string.Concat(str.Select((char x, int i) => (i <= 0 || !char.IsUpper(x)) ? x.ToString() : ("_" + x))).ToLower();
			}

			internal static bool IsArrayMember(Expression expression, SqlSugarProvider context)
			{
				if (expression == null)
				{
					return false;
				}
				if (!(expression is LambdaExpression))
				{
					return false;
				}
				LambdaExpression lambdaExpression = (LambdaExpression)expression;
				if (!(lambdaExpression.Body is MemberExpression))
				{
					return false;
				}
				MemberExpression member = lambdaExpression.Body as MemberExpression;
				if (!member.Type.IsClass())
				{
					return false;
				}
				if (member.Expression == null)
				{
					return false;
				}
				return context.EntityMaintenance.GetEntityInfo(member.Expression.Type).Columns.FirstOrDefault((EntityColumnInfo z) => z.IsArray && z.PropertyName == member.Member.Name) != null;
			}

			internal static bool IsJsonMember(Expression expression, SqlSugarProvider context)
			{
				if (expression == null)
				{
					return false;
				}
				if (!(expression is LambdaExpression))
				{
					return false;
				}
				LambdaExpression lambdaExpression = (LambdaExpression)expression;
				if (!(lambdaExpression.Body is MemberExpression))
				{
					return false;
				}
				MemberExpression member = lambdaExpression.Body as MemberExpression;
				if (!member.Type.IsClass())
				{
					return false;
				}
				if (member.Expression == null)
				{
					return false;
				}
				return context.EntityMaintenance.GetEntityInfo(member.Expression.Type).Columns.FirstOrDefault((EntityColumnInfo z) => z.IsJson && z.PropertyName == member.Member.Name) != null;
			}

