			internal static DateTime ConvertFromDateTimeOffset(DateTimeOffset dateTime)
			{
				if (dateTime.Offset.Equals(TimeSpan.Zero))
				{
					return dateTime.UtcDateTime;
				}
				if (dateTime.Offset.Equals(TimeZoneInfo.Local.GetUtcOffset(dateTime.DateTime)))
				{
					return DateTime.SpecifyKind(dateTime.DateTime, DateTimeKind.Local);
				}
				return dateTime.DateTime;
			}

			internal static object To(object value, Type destinationType)
			{
				return To(value, destinationType, CultureInfo.InvariantCulture);
			}

			internal static object To(object value, Type destinationType, CultureInfo culture)
			{
				if (value != null)
				{
					destinationType = GetUnderType(destinationType);
					Type type = value.GetType();
					if (destinationType.Name == "DateOnly" && type == typeof(string))
					{
						return Type.GetType("System.DateOnly", throwOnError: true, ignoreCase: true).GetMethods().FirstOrDefault((MethodInfo it) => it.GetParameters().Length == 1 && it.Name == "FromDateTime")
							.Invoke(null, new object[1] { Convert.ToDateTime(value) });
					}
					if (destinationType.FullName == "System.Ulid")
					{
						MethodInfo myMethod = destinationType.GetMyMethod("Parse", 1);
						if (myMethod != null)
						{
							return myMethod.Invoke(null, new object[1] { value });
						}
					}
					else
					{
						if (value is byte[] array && array.Length == 1 && destinationType == typeof(char))
						{
							return (char)array[0];
						}
						if (value is DateTime && destinationType == typeof(TimeSpan))
						{
							value = Convert.ToDateTime(value).TimeOfDay;
						}
						else if (value is DateTime && destinationType.FullName == "System.TimeOnly")
						{
							value = Convert.ToDateTime(value).TimeOfDay;
						}
					}
					TypeConverter converter = TypeDescriptor.GetConverter(destinationType);
					if (converter != null && converter.CanConvertFrom(value.GetType()))
					{
						return converter.ConvertFrom(null, culture, value);
					}
					TypeConverter converter2 = TypeDescriptor.GetConverter(type);
					if (converter2 != null && converter2.CanConvertTo(destinationType))
					{
						return converter2.ConvertTo(null, culture, value, destinationType);
					}
					if (destinationType.IsEnum && value is int)
					{
						return Enum.ToObject(destinationType, (int)value);
					}
					if (destinationType.IsEnum && value is double)
					{
						return Enum.ToObject(destinationType, Convert.ToInt32(value));
					}
					if (destinationType.IsEnum && value is decimal)
					{
						return Enum.ToObject(destinationType, Convert.ToInt32(value));
					}
					if (destinationType.Name == "TimeOnly" && type.Name != "TimeOnly")
					{
						return Type.GetType("System.TimeOnly", throwOnError: true, ignoreCase: true).GetMethods().FirstOrDefault((MethodInfo it) => it.GetParameters().Length == 1 && it.Name == "FromTimeSpan")
							.Invoke(null, new object[1] { value });
					}
					if (destinationType.Name == "DateOnly" && type.Name != "DateOnly")
					{
						return Type.GetType("System.DateOnly", throwOnError: true, ignoreCase: true).GetMethods().FirstOrDefault((MethodInfo it) => it.GetParameters().Length == 1 && it.Name == "FromDateTime")
							.Invoke(null, new object[1] { value });
					}
					if (!destinationType.IsInstanceOfType(value))
					{
						return Convert.ChangeType(value, destinationType, culture);
					}
				}
				return value;
			}

			public static bool IsAnyAsyncMethod(StackFrame[] methods)
			{
				bool result = false;
				for (int i = 0; i < methods.Length; i++)
				{
					if (IsAsyncMethod(methods[i].GetMethod()))
					{
						result = true;
						break;
					}
				}
				return result;
			}

