			internal static object GetRandomByType(Type underType)
			{
				if (underType == UtilConstants.GuidType)
				{
					return Guid.NewGuid();
				}
				if (underType == UtilConstants.LongType)
				{
					return SnowFlakeSingle.Instance.NextId();
				}
				if (underType == UtilConstants.StringType)
				{
					return Guid.NewGuid().ToString() ?? "";
				}
				if (underType == UtilConstants.DateType)
				{
					return DateTime.Now;
				}
				return Guid.NewGuid().ToString() ?? "";
			}

			public static bool IsAsyncMethod(MethodBase method)
			{
				if (method == null)
				{
					return false;
				}
				if (method.DeclaringType != null && Enumerable.Contains<Type>(method.DeclaringType.GetInterfaces(), typeof(IAsyncStateMachine)))
				{
					return true;
				}
				string name = method.Name;
				if (name.Contains("OutputAsyncCausalityEvents"))
				{
					return true;
				}
				if (name.Contains("OutputWaitEtwEvents"))
				{
					return true;
				}
				if (name.Contains("ExecuteAsync"))
				{
					return true;
				}
				Type typeFromHandle = typeof(AsyncStateMachineAttribute);
				return (AsyncStateMachineAttribute)method.GetCustomAttribute(typeFromHandle) != null;
			}

			public static StackTraceInfo GetStackTrace()
			{
				StackTrace stackTrace = new StackTrace(fNeedFileInfo: true);
				StackTraceInfo stackTraceInfo = new StackTraceInfo();
				stackTraceInfo.MyStackTraceList = new List<StackTraceInfoItem>();
				stackTraceInfo.SugarStackTraceList = new List<StackTraceInfoItem>();
				for (int i = 0; i < stackTrace.FrameCount; i++)
				{
					StackFrame frame = stackTrace.GetFrame(i);
					if (frame.GetMethod().Module.Name.ToLower() != "sqlsugar.dll" && frame.GetMethod().Name.First() != '<')
					{
						stackTraceInfo.MyStackTraceList.Add(new StackTraceInfoItem
						{
							FileName = frame.GetFileName(),
							MethodName = frame.GetMethod().Name,
							Line = frame.GetFileLineNumber()
						});
					}
					else
					{
						stackTraceInfo.SugarStackTraceList.Add(new StackTraceInfoItem
						{
							FileName = frame.GetFileName(),
							MethodName = frame.GetMethod().Name,
							Line = frame.GetFileLineNumber()
						});
					}
				}
				return stackTraceInfo;
			}

