			public static object ChangeType2(object value, Type type)
			{
				if (value is byte[] && type == UtilConstants.StringType)
				{
					return Encoding.UTF8.GetString(value as byte[]);
				}
				if (value == null && type.IsGenericType)
				{
					return Activator.CreateInstance(type);
				}
				if (value == null)
				{
					return null;
				}
				if (type == value.GetType())
				{
					return value;
				}
				if (type.IsEnum)
				{
					if (value is string)
					{
						return Enum.Parse(type, value as string);
					}
					return Enum.ToObject(type, value);
				}
				if (value is string && type == typeof(Guid?))
				{
					return value.IsNullOrEmpty() ? ((Guid?)null) : new Guid?(new Guid(value as string));
				}
				if (!type.IsInterface && type.IsGenericType)
				{
					Type type2 = type.GetGenericArguments()[0];
					object obj = ChangeType(value, type2);
					return Activator.CreateInstance(type, obj);
				}
				if (value is string && type == typeof(Guid))
				{
					return new Guid(value as string);
				}
				if (value is string && type == typeof(Version))
				{
					return new Version(value as string);
				}
				if (!(value is IConvertible))
				{
					return value;
				}
				if (value is DateTime && type.FullName == "System.DateOnly")
				{
					value = DateTimeToDateOnly(value);
				}
				return Convert.ChangeType(value, type);
			}

