			internal static void RepairReplicationParameters(ref string appendSql, SugarParameter[] parameters, int addIndex, string append = null)
			{
				if (!appendSql.HasValue() || !parameters.HasValue())
				{
					return;
				}
				foreach (SugarParameter item in parameters.OrderByDescending((SugarParameter it) => it.ParameterName.Length))
				{
					string text = item.ParameterName + append + addIndex;
					appendSql = ReplaceSqlParameter(appendSql, item, text);
					item.ParameterName = text;
				}
			}

			internal static void RepairReplicationParameters(ISqlSugarClient db, ref string appendSql, SugarParameter[] parameters, int addIndex, string append = null)
			{
				if (!appendSql.HasValue() || !parameters.HasValue())
				{
					return;
				}
				foreach (SugarParameter item in parameters.OrderByDescending((SugarParameter it) => it.ParameterName.Length))
				{
					string parameterName = item.ParameterName;
					string text = parameterName + append + addIndex;
					int maxParameterNameLength = db.CurrentConnectionConfig.MoreSettings.MaxParameterNameLength;
					if (text.Length > maxParameterNameLength)
					{
						text = parameterName.Substring(0, 1) + parameterName.GetNonNegativeHashCodeString() + "_" + addIndex;
					}
					appendSql = ReplaceSqlParameter(appendSql, item, text);
					item.ParameterName = text;
				}
			}

