			public static Func<string, object> GetTypeConvert(object value)
			{
				if (value is int || value is uint || value is int? || value is uint?)
				{
					return (string x) => Convert.ToInt32(x);
				}
				if (value is short || value is ushort || value is short? || value is ushort?)
				{
					return (string x) => Convert.ToInt16(x);
				}
				if (value is long || value is long? || value is ulong? || value is long?)
				{
					return (string x) => Convert.ToInt64(x);
				}
				if (value is DateTime || value is DateTime?)
				{
					return (string x) => Convert.ToDateTime(x);
				}
				if (value is bool || value is bool?)
				{
					return (string x) => Convert.ToBoolean(x);
				}
				return null;
			}

