			public static void DataInoveByExpresson<Type>(Type[] datas, MethodCallExpression callExpresion)
			{
				MethodInfo method = callExpresion.Method;
				foreach (Type val in datas)
				{
					if (val == null)
					{
						continue;
					}
					if (callExpresion.Arguments.Count == 0)
					{
						method.Invoke(val, null);
						continue;
					}
					List<object> list = new List<object>();
					foreach (Expression argument in callExpresion.Arguments)
					{
						PropertyInfo propertyInfo = argument.GetType().GetProperties().FirstOrDefault((PropertyInfo it) => it.Name == "Value");
						if (propertyInfo == null)
						{
							object item = Expression.Lambda(argument).Compile().DynamicInvoke();
							list.Add(item);
						}
						else
						{
							object value = propertyInfo.GetValue(argument, null);
							list.Add(value);
						}
					}
					method.Invoke(val, list.ToArray());
				}
			}

			public static Dictionary<string, T> EnumToDictionary<T>()
			{
				Dictionary<string, T> dictionary = new Dictionary<string, T>();
				if (!typeof(T).IsEnum)
				{
					return dictionary;
				}
				_ = string.Empty;
				foreach (object value in Enum.GetValues(typeof(T)))
				{
					string key = value.ToString().ToLower();
					if (!dictionary.ContainsKey(key))
					{
						dictionary.Add(key, (T)value);
					}
				}
				return dictionary;
			}

