			public static object ConvertDataByTypeName(string ctypename, string value)
			{
				ConditionalModel conditionalModel = new ConditionalModel
				{
					CSharpTypeName = ctypename,
					FieldValue = value
				};
				if (ctypename == "DateOnly")
				{
					return Convert.ToDateTime(value);
				}
				if (conditionalModel.FieldValue == string.Empty && conditionalModel.CSharpTypeName.HasValue() && !conditionalModel.CSharpTypeName.EqualCase("string"))
				{
					return null;
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.DecType.Name))
				{
					return Convert.ToDecimal(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.DobType.Name))
				{
					return Convert.ToDouble(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.DateType.Name))
				{
					return Convert.ToDateTime(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.IntType.Name))
				{
					return Convert.ToInt32(conditionalModel.FieldValue);
				}
				if (conditionalModel.FieldValue != null && conditionalModel.CSharpTypeName.EqualCase(UtilConstants.BoolType.Name))
				{
					return Convert.ToBoolean(conditionalModel.FieldValue.ToLower());
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.LongType.Name))
				{
					return Convert.ToInt64(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.ShortType.Name))
				{
					return Convert.ToInt16(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.DateTimeOffsetType.Name))
				{
					if (DateTimeOffset.TryParse(conditionalModel.FieldValue, out var result))
					{
						return result;
					}
					return GetDateTimeOffsetByDateTime(Convert.ToDateTime(conditionalModel.FieldValue));
				}
				if (conditionalModel.CSharpTypeName.EqualCase(UtilConstants.GuidType.Name))
				{
					return Guid.Parse(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("int"))
				{
					return Convert.ToInt32(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("long"))
				{
					return Convert.ToInt64(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("float"))
				{
					return Convert.ToSingle(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("single"))
				{
					return Convert.ToSingle(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("short"))
				{
					return Convert.ToInt16(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("byte"))
				{
					return Convert.ToByte(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("uint"))
				{
					return Convert.ToUInt32(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("ulong"))
				{
					return Convert.ToUInt64(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("ushort"))
				{
					return Convert.ToUInt16(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("uint32"))
				{
					return Convert.ToUInt32(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("uint64"))
				{
					return Convert.ToUInt64(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("bool"))
				{
					return Convert.ToBoolean(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("ToBoolean"))
				{
					return Convert.ToBoolean(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("uint16"))
				{
					return Convert.ToUInt16(conditionalModel.FieldValue);
				}
				if (conditionalModel.CSharpTypeName.EqualCase("byte[]") && conditionalModel.FieldValue != null && conditionalModel.FieldValue.Contains("|"))
				{
					return (from it in conditionalModel.FieldValue.Split('|')
						select Convert.ToByte(it)).ToArray();
				}
				return conditionalModel.FieldValue;
			}

