			/// <summary>
			/// Get Week Last Day Sun
			/// </summary>
			/// <param name="datetime"></param>
			/// <returns></returns>
			public static DateTime GetWeekLastDaySun(DateTime datetime)
			{
				int num = Convert.ToInt32(datetime.DayOfWeek);
				num = ((num == 0) ? 7 : num);
				int num2 = 7 - num;
				return Convert.ToDateTime(datetime.AddDays(num2).ToString("yyyy-MM-dd"));
			}

			/// <summary>
			/// Get Week First Day Mon
			/// </summary>
			/// <param name="datetime"></param>
			/// <returns></returns>
			public static DateTime GetWeekFirstDayMon(DateTime datetime)
			{
				int num = Convert.ToInt32(datetime.DayOfWeek);
				num = ((num == 0) ? 6 : (num - 1));
				int num2 = -1 * num;
				return Convert.ToDateTime(datetime.AddDays(num2).ToString("yyyy-MM-dd"));
			}

			public static string GetSqlString(DbType dbType, string sql, SugarParameter[] parametres, bool DisableNvarchar = false)
			{
				if (parametres == null)
				{
					parametres = new SugarParameter[0];
				}
				return GetSqlString(new ConnectionConfig
				{
					DbType = dbType,
					MoreSettings = new ConnMoreSettings
					{
						DisableNvarchar = DisableNvarchar
					}
				}, new KeyValuePair<string, List<SugarParameter>>(sql, parametres.ToList()));
			}

			public static string GetSqlString(ConnectionConfig connectionConfig, KeyValuePair<string, List<SugarParameter>> sqlObj)
			{
				string text = Guid.NewGuid().ToString() ?? "";
				string text2 = sqlObj.Key;
				if (sqlObj.Value != null)
				{
					foreach (SugarParameter item in from it in CopySugarParameters(sqlObj.Value)
						orderby it.ParameterName.Length descending
						select it)
					{
						if (item.ParameterName.StartsWith(":") && !text2.Contains(item.ParameterName))
						{
							item.ParameterName = "@" + item.ParameterName.TrimStart(':');
						}
						if (connectionConfig.MoreSettings == null)
						{
							connectionConfig.MoreSettings = new ConnMoreSettings();
						}
						if (item.Value != null && item.Value is DateTime && (DateTime)item.Value == DateTime.MinValue)
						{
							item.Value = connectionConfig.MoreSettings.DbMinDate;
						}
						if (item.Value == null || item.Value == DBNull.Value)
						{
							text2 = text2.Replace(item.ParameterName, "null");
						}
						else if (IsNumber(item.Value.GetType().Name))
						{
							text2 = text2.Replace(item.ParameterName, item.Value.ObjToString());
						}
						else if (item.Value is DateTime && connectionConfig.DbType == DbType.SqlServer)
						{
							text2 = text2.Replace(item.ParameterName, "CAST('" + item.Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff") + "' AS DATETIME)");
						}
						else if (item.Value is DateTime && connectionConfig.DbType == DbType.Oracle)
						{
							if (item.DbType == System.Data.DbType.Date || (connectionConfig != null && connectionConfig.MoreSettings?.DisableMillisecond == true))
							{
								string newValue = "to_date('" + item.Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss") + "', 'YYYY-MM-DD HH24:MI:SS')  ";
								text2 = text2.Replace(item.ParameterName, newValue);
							}
							else
							{
								string newValue2 = "to_timestamp('" + item.Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.ffffff") + "', 'YYYY-MM-DD HH24:MI:SS.FF') ";
								text2 = text2.Replace(item.ParameterName, newValue2);
							}
						}
						else if (item.Value is DateTime)
						{
							text2 = text2.Replace(item.ParameterName, "'" + item.Value.ObjToDate().ToString("yyyy-MM-dd HH:mm:ss.fff") + "'");
						}
						else if (item.IsArray)
						{
							text2 = text2.Replace(item.ParameterName, "'{" + new SerializeService().SerializeObject(item.Value).TrimStart('[').TrimEnd(']') + "}'");
						}
						else if (item.Value is byte[])
						{
							text2 = text2.Replace(item.ParameterName, "0x" + BitConverter.ToString((byte[])item.Value).Replace("-", ""));
						}
						else if (item.Value is bool)
						{
							text2 = text2.Replace(item.ParameterName, (Convert.ToBoolean(item.Value) ? 1 : 0).ToString() ?? "");
						}
						else
						{
							ConnMoreSettings moreSettings = connectionConfig.MoreSettings;
							text2 = (((moreSettings == null || !moreSettings.DisableNvarchar) && item.DbType != System.Data.DbType.AnsiString && connectionConfig.DbType != DbType.Sqlite) ? text2.Replace(item.ParameterName, "N'" + item.Value.ObjToStringNoTrim().Replace("@", text).ToSqlFilter() + "'") : text2.Replace(item.ParameterName, "'" + item.Value.ObjToString().Replace("@", text).ToSqlFilter() + "'"));
						}
					}
				}
				return text2.Replace(text, "@");
			}

			public static string ByteArrayToPostgreByteaLiteral(byte[] data)
			{
				StringBuilder stringBuilder = new StringBuilder("E'");
				foreach (byte b in data)
				{
					if (b >= 32 && b < 127 && !char.IsControl((char)b))
					{
						stringBuilder.Append((char)b);
						continue;
					}
					stringBuilder.Append("\\\\");
					stringBuilder.Append(Convert.ToString(b, 8).PadLeft(3, '0'));
				}
				stringBuilder.Append("'::bytea");
				return stringBuilder.ToString();
			}

			public static void CheckArray<T>(T[] insertObjs) where T : class, new()
			{
				if (insertObjs != null && insertObjs.Length == 1 && insertObjs.FirstOrDefault() != null && insertObjs.FirstOrDefault().GetType().FullName.Contains("System.Collections.Generic.List`"))
				{
					Check.ExceptionEasy("Insertable(T []) is an array and your argument is a List", "二次封装引起的进错重载,当前方法是 Insertable(T []) 参数是一个数组，而你的参数是一个List");
				}
			}

