			internal static object TimeOnlyToTimeSpan(object value)
			{
				return value?.GetType().GetMethods().First((MethodInfo it) => it.GetParameters().Length == 0 && it.Name == "ToTimeSpan")
					.Invoke(value, new object[0]);
			}

			internal static object DateOnlyToDateTime(object value)
			{
				if (value is DateTime)
				{
					return value;
				}
				return value?.GetType().GetMethods().First((MethodInfo it) => it.GetParameters().Length == 0 && it.Name == "ToShortDateString")
					.Invoke(value, new object[0]);
			}

			internal static object DateTimeToDateOnly(object value)
			{
				if (value == null)
				{
					return null;
				}
				Type? type = Type.GetType("System.DateOnly, System.Runtime", throwOnError: false);
				if (type == null)
				{
					throw new InvalidOperationException("DateOnly type not found.");
				}
				ConstructorInfo? constructor = type.GetConstructor(new Type[3]
				{
					typeof(int),
					typeof(int),
					typeof(int)
				});
				if (constructor == null)
				{
					throw new InvalidOperationException("DateOnly constructor not found.");
				}
				PropertyInfo? property = value.GetType().GetProperty("Year");
				PropertyInfo property2 = value.GetType().GetProperty("Month");
				PropertyInfo property3 = value.GetType().GetProperty("Day");
				if (property == null || property2 == null || property3 == null)
				{
					throw new InvalidOperationException("DateTime properties not found.");
				}
				int num = (int)property.GetValue(value);
				int num2 = (int)property2.GetValue(value);
				int num3 = (int)property3.GetValue(value);
				return constructor.Invoke(new object[3] { num, num2, num3 });
			}

			internal static void AddDiscrimator<T>(Type type, ISugarQueryable<T> queryable, string shortName = null)
			{
				EntityInfo entityInfo = queryable.Context?.EntityMaintenance?.GetEntityInfoWithAttr(type);
				if (entityInfo != null && entityInfo.Discrimator.HasValue())
				{
					Check.ExceptionEasy(!Regex.IsMatch(entityInfo.Discrimator, "^(?:\\w+:\\w+)(?:,\\w+:\\w+)*$"), "The format should be type:cat for this type, and if there are multiple, it can be FieldName:cat,FieldName2:dog ", "格式错误应该是type:cat这种格式，如果是多个可以FieldName:cat,FieldName2:dog，不要有空格");
					string[] array = entityInfo.Discrimator.Split(',');
					foreach (string obj in array)
					{
						string text = obj.Split(':').First();
						string fieldValue = obj.Split(':').Last();
						queryable.Where(shortName + text, "=", fieldValue);
					}
				}
			}

			internal static string GetDiscrimator(EntityInfo entityInfo, ISqlBuilder builer)
			{
				List<string> list = new List<string>();
				if (entityInfo != null && entityInfo.Discrimator.HasValue())
				{
					Check.ExceptionEasy(!Regex.IsMatch(entityInfo.Discrimator, "^(?:\\w+:\\w+)(?:,\\w+:\\w+)*$"), "The format should be type:cat for this type, and if there are multiple, it can be FieldName:cat,FieldName2:dog ", "格式错误应该是type:cat这种格式，如果是多个可以FieldName:cat,FieldName2:dog，不要有空格");
					string[] array = entityInfo.Discrimator.Split(',');
					foreach (string obj in array)
					{
						string propertyName = obj.Split(':').First();
						string value = obj.Split(':').Last();
						list.Add(builer.GetTranslationColumnName(propertyName) + "=" + value.ToSqlValue() + " ");
					}
				}
				return string.Join(" AND ", list);
			}

			internal static bool NoErrorParameter(string parameterName)
			{
				if (parameterName == null)
				{
					return false;
				}
				if (parameterName.Contains(" "))
				{
					return false;
				}
				if (parameterName.Contains("("))
				{
					return false;
				}
				if (parameterName.Contains("（"))
				{
					return false;
				}
				if (parameterName.Contains("."))
				{
					return false;
				}
				return true;
			}

