		public class UtilRandom
		{
			public static Random Random = new Random();

			public static int GetRandomIndex(Dictionary<int, int> pars)
			{
				int num = 0;
				foreach (KeyValuePair<int, int> par in pars)
				{
					num += par.Value;
				}
				int num2 = Random.Next(1, num);
				int result = 0;
				int num3 = 0;
				foreach (KeyValuePair<int, int> par2 in pars)
				{
					int num4 = pars.ToList().IndexOf(par2);
					int num5 = ((num4 != 0) ? pars[num4 - 1] : 0);
					num3 += par2.Value;
					result = par2.Key;
					if (num2 >= num5 && num2 <= num3)
					{
						break;
					}
				}
				return result;
			}
		}
