			public static bool IsEamil(this object thisValue)
			{
				if (thisValue == null)
				{
					return false;
				}
				return Regex.IsMatch(thisValue.ToString(), "^[\\w-]+(\\.[\\w-]+)*@[\\w-]+(\\.[\\w-]+)+$");
