			public static bool IsAnonymousType(this Type type)
			{
				string name = type.Name;
				if (name.Contains("<>") && name.Contains("__"))
				{
					return name.Contains("AnonymousType");
				}
				return false;
			}

			public static bool IsCollectionsList(this string thisValue)
			{
				if (!(thisValue ?? "").StartsWith("System.Collections.Generic.List"))
				{
					return (thisValue ?? "").StartsWith("System.Collections.Generic.IEnumerable");
				}
				return true;
			}

			public static bool IsIterator(this Type type)
			{
				if (type.BaseType == null)
				{
					return false;
				}
				if (type.BaseType.IsGenericType)
				{
					return type.BaseType?.GetGenericTypeDefinition()?.FullName == "System.Linq.Enumerable+Iterator`1";
				}
				return false;
			}

			public static bool IsStringArray(this string thisValue)
			{
				return (thisValue ?? "").IsMatch("System\\.[a-z,A-Z,0-9]+?\\[\\]");
			}

			public static bool IsEnumerable(this string thisValue)
			{
				return (thisValue ?? "").StartsWith("System.Linq.Enumerable");
			}

			public static bool IsClass(this Type thisValue)
			{
				if (thisValue != StringType && thisValue.IsEntity())
				{
					return thisValue != UtilConstants.ByteArrayType;
				}
				return false;
			}
		}
