		public class EnumToStringConvert : ISugarDataConverter
		{
			public SugarParameter ParameterConverter<T>(object columnValue, int columnIndex)
			{
				string name = "@MyEnum" + columnIndex;
				Type underType = UtilMethods.GetUnderType(typeof(T));
				if (columnValue == null)
				{
					return new SugarParameter(name, null);
				}
				string value = Enum.Parse(underType, columnValue?.ToString() ?? "").ToString();
				return new SugarParameter(name, value);
			}

			public T QueryConverter<T>(IDataRecord dr, int i)
			{
				string value = dr.GetString(i);
				return (T)Enum.Parse(UtilMethods.GetUnderType(typeof(T)), value);
			}
		}
		public class NoParameterCommonPropertyConvert : ISugarDataConverter
		{
			public SugarParameter ParameterConverter<T>(object columnValue, int columnIndex)
			{
				if (columnValue == null)
				{
					new SugarParameter("null", null, null);
				}
				return new SugarParameter(columnValue?.ToString() ?? "", null, null);
			}

			public T QueryConverter<T>(IDataRecord dr, int i)
			{
				return (T)UtilMethods.ChangeType2(dr.GetValue(i), typeof(T));
			}
		}
		public class CommonPropertyConvert : ISugarDataConverter
		{
			public SugarParameter ParameterConverter<T>(object columnValue, int columnIndex)
			{
				string name = "@Common" + columnIndex;
				Type underType = UtilMethods.GetUnderType(typeof(T));
				return new SugarParameter(name, columnValue, underType);
			}

			public T QueryConverter<T>(IDataRecord dr, int i)
			{
				object obj = dr.GetValue(i);
				if (obj is byte[] && typeof(T) != UtilConstants.ByteArrayType)
				{
					obj = Encoding.UTF8.GetString((byte[])obj);
				}
				return (T)UtilMethods.ChangeType2(obj, typeof(T));
			}
		}
