		public class IdWorker
		{
			public const long Twepoch = 1288834974657L;

			private const int WorkerIdBits = 5;

			private const int DatacenterIdBits = 5;

			private const int SequenceBits = 12;

			private const long MaxWorkerId = 31L;

			private const long MaxDatacenterId = 31L;

			private const int WorkerIdShift = 12;

			private const int DatacenterIdShift = 17;

			public const int TimestampLeftShift = 22;

			private const long SequenceMask = 4095L;

			private long _sequence;

			private long _lastTimestamp = -1L;

			private readonly object _lock = new object();

			public long WorkerId { get; protected set; }

			public long DatacenterId { get; protected set; }

			public long Sequence
			{
				get
				{
					return _sequence;
				}
				internal set
				{
					_sequence = value;
				}
			}

			public IdWorker(long workerId, long datacenterId, long sequence = 0L)
			{
				WorkerId = workerId;
				DatacenterId = datacenterId;
				_sequence = sequence;
				if (workerId > 31 || workerId < 0)
				{
					throw new ArgumentException($"worker Id can't be greater than {31L} or less than 0");
				}
				if (datacenterId > 31 || datacenterId < 0)
				{
					throw new ArgumentException($"datacenter Id can't be greater than {31L} or less than 0");
				}
			}

			public long getID()
			{
				return NextId();
			}

			public virtual long NextId()
			{
				if (StaticConfig.CustomSnowFlakeFunc != null)
				{
					return StaticConfig.CustomSnowFlakeFunc();
				}
				lock (_lock)
				{
					long num = TimeGen();
					if (num < _lastTimestamp)
					{
						if (StaticConfig.CustomSnowFlakeTimeErrorFunc != null)
						{
							return StaticConfig.CustomSnowFlakeTimeErrorFunc();
						}
						throw new InvalidSystemClock($"服务器时间出现回退你可以使用StaticConfig.CustomSnowFlakeTimeErrorFunc=【自定义方法】处理让他不报错返回新ID,Clock moved backwards.  Refusing to generate id for {_lastTimestamp - num} milliseconds");
					}
					if (_lastTimestamp == num)
					{
						_sequence = (_sequence + 1) & 0xFFF;
						if (_sequence == 0L)
						{
							num = TilNextMillis(_lastTimestamp);
						}
					}
					else
					{
						_sequence = 0L;
					}
					_lastTimestamp = num;
					return (num - 1288834974657L << 22) | (DatacenterId << 17) | (WorkerId << 12) | _sequence;
				}
			}

			protected virtual long TilNextMillis(long lastTimestamp)
			{
				long num;
				for (num = TimeGen(); num <= lastTimestamp; num = TimeGen())
				{
				}
				return num;
			}

			protected virtual long TimeGen()
			{
				return System.CurrentTimeMillis();
			}
		}
		public class InvalidSystemClock : Exception
		{
			public InvalidSystemClock(string message)
				: base(message)
			{
			}
		}
		public static class System
		{
			public static Func<long> currentTimeFunc = InternalCurrentTimeMillis;

			private static readonly DateTime Jan1st1970 = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);

			public static long CurrentTimeMillis()
			{
				return currentTimeFunc();
			}

			public static IDisposable StubCurrentTime(Func<long> func)
			{
				currentTimeFunc = func;
				return new DisposableAction(delegate
				{
					currentTimeFunc = InternalCurrentTimeMillis;
				});
			}

			public static IDisposable StubCurrentTime(long millis)
			{
				currentTimeFunc = () => millis;
				return new DisposableAction(delegate
				{
					currentTimeFunc = InternalCurrentTimeMillis;
				});
			}

			private static long InternalCurrentTimeMillis()
			{
				return (long)(DateTime.UtcNow - Jan1st1970).TotalMilliseconds;
			}
		}
	}
